window.STATIC_PROJECT_FILES = {"ar": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" استخدم;\n\"src/models/product.hudhud\" استخدم;\n\"src/models/order.hudhud\" استخدم;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" استخدم;\n\"src/services/payment.hudhud\" استخدم;\n\"src/services/notification.hudhud\" استخدم;\n\n// Yardımcı صنفları içe aktar\n\"src/utils/validation.hudhud\" استخدم;\n\"src/utils/formatting.hudhud\" استخدم;\n\nاطبع(\"============================================================\");\nاطبع(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nاطبع(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nمتغير authService = جديد AuthService();\nمتغير paymentService = جديد PaymentService();\nمتغير notificationService = جديد NotificationService();\n\nاطبع(\"1️⃣  KULLANICI KAYDI\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni استخدمıcı oluştur\nمتغير newUser = جديد User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nاطبع(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email صحيحla\nإذا (Validation.email(newUser.email)) {\n    اطبع(\"✓ Email geçerli: \" + newUser.email);\n} وإلا {\n    اطبع(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nمتغير authResult = authService.register(newUser);\nإذا (authResult.success) {\n    اطبع(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nاطبع(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nمتغير product = جديد Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nاطبع(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat صحيحla\nإذا (Validation.price(product.price)) {\n    اطبع(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nإذا (product.inStock()) {\n    اطبع(\"✓ Ürün stokta mevcut\");\n} وإلا {\n    اطبع(\"✗ Ürün stokta yok\");\n}\n\nاطبع(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nمتغير order = جديد Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nاطبع(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nاطبع(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nمتغير paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nإذا (paymentResult.success) {\n    اطبع(\"✓ \" + paymentResult.message);\n    اطبع(\"  İşlem No: \" + paymentResult.transactionId);\n    اطبع(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    اطبع(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    اطبع(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} وإلا {\n    اطبع(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nاطبع(\"\\n============================================================\");\nاطبع(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nاطبع(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nاطبع(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" استخدم;\n\"../src/services/auth.hudhud\" استخدم;\n\nاطبع(\"============================================================\");\nاطبع(\"Auth Service Tests\");\nاطبع(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nمتغير authService = جديد AuthService();\nاطبع(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nمتغير user = جديد User(\"Test User\", \"test@example.com\", \"test123\");\nمتغير result1 = authService.register(user);\n\nإذا (result1.success) {\n    اطبع(\"✓ Test 2 passed: Registration successful\");\n    اطبع(\"  User ID: \" + result1.userId);\n    اطبع(\"  Message: \" + result1.message);\n} وإلا {\n    اطبع(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nمتغير loginResult = authService.login(\"test@example.com\", \"test123\");\n\nإذا (loginResult.success) {\n    اطبع(\"✓ Test 3 passed: Login successful\");\n    اطبع(\"  Token: \" + loginResult.token);\n    اطبع(\"  Message: \" + loginResult.message);\n} وإلا {\n    اطبع(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nمتغير verifyResult = authService.verifyToken(loginResult.token);\n\nإذا (verifyResult.valid) {\n    اطبع(\"✓ Test 4 passed: Token verification successful\");\n    اطبع(\"  User ID: \" + verifyResult.userId);\n} وإلا {\n    اطبع(\"✗ Test 4 failed: Token verification failed\");\n}\n\nاطبع(\"\\n============================================================\");\nاطبع(\"All Auth tests completed!\");\nاطبع(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" استخدم;\n\nاطبع(\"============================================================\");\nاطبع(\"User Model Tests\");\nاطبع(\"============================================================\\n\");\n\n// Test 1: User creation\nمتغير user = جديد User(\"Test User\", \"test@example.com\", \"test123\");\n\nإذا (user.name == \"Test User\") {\n    اطبع(\"✓ Test 1 passed: User creation\");\n} وإلا {\n    اطبع(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nإذا (user.email == \"test@example.com\") {\n    اطبع(\"✓ Test 2 passed: Email set correctly\");\n} وإلا {\n    اطبع(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nإذا (user.id > 0) {\n    اطبع(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} وإلا {\n    اطبع(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nمتغير info = user.bilgi();\nإذا (info.length > 0) {\n    اطبع(\"✓ Test 4 passed: bilgi() method works\");\n    اطبع(\"  Info: \" + info);\n} وإلا {\n    اطبع(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nاطبع(\"\\n============================================================\");\nاطبع(\"All User tests completed!\");\nاطبع(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nصنف NotificationService {\n    دالة send(to, subject, message) {\n        اطبع(\"   📧 Email gönderildi:\");\n        اطبع(\"      Kime: \" + to);\n        اطبع(\"      Konu: \" + subject);\n        اطبع(\"      Mesaj: \" + message);\n        ارجع صحيح;\n    }\n    \n    دالة sendSms(phone, message) {\n        اطبع(\"   📱 SMS gönderildi:\");\n        اطبع(\"      Numara: \" + phone);\n        اطبع(\"      Mesaj: \" + message);\n        ارجع صحيح;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nصنف PaymentService {\n    دالة process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        متغير success = صحيح; // Gerçekte API çağrısı yapılır\n        \n        إذا (success) {\n            ارجع {\n                success: صحيح,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } وإلا {\n            ارجع {\n                success: خطأ,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    دالة refund(transactionId) {\n        ارجع {\n            success: صحيح,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nصنف AuthService {\n    منشئ() {\n        ذاتي.userCount = 0;\n    }\n    \n    دالة register(user) {\n        ذاتي.userCount = ذاتي.userCount + 1;\n        ارجع {\n            success: صحيح,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    دالة login(email, password) {\n        // Basitleştirilmiş login\n        ارجع {\n            success: صحيح,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    دالة logout(token) {\n        ارجع { success: صحيح };\n    }\n    \n    دالة verifyToken(token) {\n        ارجع { valid: صحيح, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nصنف User {\n    منشئ(name, email, password) {\n        ذاتي.id = Math.floor(Math.random() * 10000);\n        ذاتي.name = name;\n        ذاتي.email = email;\n        ذاتي.password = password;\n        ذاتي.createdAt = \"2024-03-07\";\n    }\n    \n    دالة bilgi() {\n        ارجع \"User #\" + ذاتي.id + \": \" + ذاتي.name + \" (\" + ذاتي.email + \")\";\n    }\n    \n    دالة getId() {\n        ارجع ذاتي.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nصنف Product {\n    منشئ(name, price, stock, category) {\n        ذاتي.id = Math.floor(Math.random() * 10000);\n        ذاتي.name = name;\n        ذاتي.price = price;\n        ذاتي.stock = stock;\n        ذاتي.category = category;\n    }\n    \n    دالة bilgi() {\n        ارجع ذاتي.name + \" - \" + ذاتي.price + \" TL (Stok: \" + ذاتي.stock + \", Kategori: \" + ذاتي.category + \")\";\n    }\n    \n    دالة inStock() {\n        ارجع ذاتي.stock > 0;\n    }\n    \n    دالة getId() {\n        ارجع ذاتي.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nصنف Order {\n    منشئ(userId, productId, quantity, totalPrice) {\n        ذاتي.id = Math.floor(Math.random() * 10000);\n        ذاتي.userId = userId;\n        ذاتي.productId = productId;\n        ذاتي.quantity = quantity;\n        ذاتي.totalPrice = totalPrice;\n        ذاتي.status = \"pending\";\n        ذاتي.createdAt = \"2024-03-07\";\n    }\n    \n    دالة bilgi() {\n        ارجع \"Sipariş #\" + ذاتي.id + \" - Kullanıcı: \" + ذاتي.userId + \", Ürün: \" + ذاتي.productId + \", Adet: \" + ذاتي.quantity + \", Toplam: \" + ذاتي.totalPrice + \" TL, Durum: \" + ذاتي.status;\n    }\n    \n    دالة confirm() {\n        ذاتي.status = \"confirmed\";\n    }\n    \n    دالة getId() {\n        ارجع ذاتي.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nدالة random_string(length) {\n    ارجع \"random_\" + length;\n}\n\nدالة sleep(ms) {\n    // Bekleme simülasyonu\n    اطبع(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nدالة log(message) {\n    اطبع(\"[LOG] \" + message);\n}\n\nدالة error(message) {\n    اطبع(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nصنف Formatting {\n    ثابت دالة currency(amount, currency) {\n        إذا (currency == \"TRY\") {\n            ارجع amount + \" ₺\";\n        } وإلا {\n            إذا (currency == \"USD\") {\n                ارجع \"$\" + amount;\n            } وإلا {\n                إذا (currency == \"EUR\") {\n                    ارجع \"€\" + amount;\n                } وإلا {\n                    ارجع amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    ثابت دالة date(date) {\n        ارجع date;\n    }\n    \n    ثابت دالة phone(phone) {\n        // (555) 123-4567 formatı\n        ارجع \"(\" + phone + \")\";\n    }\n    \n    ثابت دالة number(num) {\n        // 1,234,567 formatı\n        ارجع num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nصنف Validation {\n    ثابت دالة email(email) {\n        // Basit email صحيحlama\n        ارجع email.length > 5;\n    }\n    \n    ثابت دالة password(password) {\n        // Şifre en az 6 karakter olmalı\n        ارجع password.length >= 6;\n    }\n    \n    ثابت دالة price(price) {\n        ارجع price > 0;\n    }\n    \n    ثابت دالة phone(phone) {\n        // Telefon numarası صحيحlama\n        ارجع phone.length == 10;\n    }\n    \n    ثابت دالة required(value) {\n        ارجع value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nمتغير APP_NAME = \"My Project\";\nمتغير APP_VERSION = \"1.0.0\";\nمتغير MAX_UPLOAD_SIZE = 10485760; // 10MB\nمتغير SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nمتغير STATUS_PENDING = \"pending\";\nمتغير STATUS_APPROVED = \"approved\";\nمتغير STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nمتغير DB_HOST = \"localhost\";\nمتغير DB_PORT = 5432;\nمتغير DB_NAME = \"myproject_db\";\nمتغير DB_USER = \"admin\";\nمتغير DB_PASSWORD = \"secure_password\";\n\nدالة get_connection_string() {\n    ارجع \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nمتغير API_BASE_URL = \"https://api.example.com\";\nمتغير API_VERSION = \"v1\";\nمتغير API_TIMEOUT = 30000;\n\nدالة get_api_url(endpoint) {\n    ارجع API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "ja": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" 使用;\n\"src/models/product.hudhud\" 使用;\n\"src/models/order.hudhud\" 使用;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" 使用;\n\"src/services/payment.hudhud\" 使用;\n\"src/services/notification.hudhud\" 使用;\n\n// Yardımcı クラスları içe aktar\n\"src/utils/validation.hudhud\" 使用;\n\"src/utils/formatting.hudhud\" 使用;\n\n印刷(\"============================================================\");\n印刷(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\n印刷(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\n変数 authService = 新規 AuthService();\n変数 paymentService = 新規 PaymentService();\n変数 notificationService = 新規 NotificationService();\n\n印刷(\"1️⃣  KULLANICI KAYDI\");\n印刷(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni 使用ıcı oluştur\n変数 newUser = 新規 User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\n印刷(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email 真la\nもし (Validation.email(newUser.email)) {\n    印刷(\"✓ Email geçerli: \" + newUser.email);\n} そうでなければ {\n    印刷(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\n変数 authResult = authService.register(newUser);\nもし (authResult.success) {\n    印刷(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\n印刷(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\n印刷(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\n変数 product = 新規 Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\n印刷(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat 真la\nもし (Validation.price(product.price)) {\n    印刷(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nもし (product.inStock()) {\n    印刷(\"✓ Ürün stokta mevcut\");\n} そうでなければ {\n    印刷(\"✗ Ürün stokta yok\");\n}\n\n印刷(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\n印刷(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\n変数 order = 新規 Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\n印刷(\"Sipariş oluşturuldu: \" + order.bilgi());\n\n印刷(\"\\n4️⃣  ÖDEME İŞLEMİ\");\n印刷(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\n変数 paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nもし (paymentResult.success) {\n    印刷(\"✓ \" + paymentResult.message);\n    印刷(\"  İşlem No: \" + paymentResult.transactionId);\n    印刷(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    印刷(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    印刷(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} そうでなければ {\n    印刷(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\n印刷(\"\\n============================================================\");\n印刷(\"✓ E-Ticaret sistemi demo tamamlandı!\");\n印刷(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\n印刷(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" 使用;\n\"../src/services/auth.hudhud\" 使用;\n\n印刷(\"============================================================\");\n印刷(\"Auth Service Tests\");\n印刷(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\n変数 authService = 新規 AuthService();\n印刷(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\n変数 user = 新規 User(\"Test User\", \"test@example.com\", \"test123\");\n変数 result1 = authService.register(user);\n\nもし (result1.success) {\n    印刷(\"✓ Test 2 passed: Registration successful\");\n    印刷(\"  User ID: \" + result1.userId);\n    印刷(\"  Message: \" + result1.message);\n} そうでなければ {\n    印刷(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\n変数 loginResult = authService.login(\"test@example.com\", \"test123\");\n\nもし (loginResult.success) {\n    印刷(\"✓ Test 3 passed: Login successful\");\n    印刷(\"  Token: \" + loginResult.token);\n    印刷(\"  Message: \" + loginResult.message);\n} そうでなければ {\n    印刷(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\n変数 verifyResult = authService.verifyToken(loginResult.token);\n\nもし (verifyResult.valid) {\n    印刷(\"✓ Test 4 passed: Token verification successful\");\n    印刷(\"  User ID: \" + verifyResult.userId);\n} そうでなければ {\n    印刷(\"✗ Test 4 failed: Token verification failed\");\n}\n\n印刷(\"\\n============================================================\");\n印刷(\"All Auth tests completed!\");\n印刷(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" 使用;\n\n印刷(\"============================================================\");\n印刷(\"User Model Tests\");\n印刷(\"============================================================\\n\");\n\n// Test 1: User creation\n変数 user = 新規 User(\"Test User\", \"test@example.com\", \"test123\");\n\nもし (user.name == \"Test User\") {\n    印刷(\"✓ Test 1 passed: User creation\");\n} そうでなければ {\n    印刷(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nもし (user.email == \"test@example.com\") {\n    印刷(\"✓ Test 2 passed: Email set correctly\");\n} そうでなければ {\n    印刷(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nもし (user.id > 0) {\n    印刷(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} そうでなければ {\n    印刷(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\n変数 info = user.bilgi();\nもし (info.length > 0) {\n    印刷(\"✓ Test 4 passed: bilgi() method works\");\n    印刷(\"  Info: \" + info);\n} そうでなければ {\n    印刷(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\n印刷(\"\\n============================================================\");\n印刷(\"All User tests completed!\");\n印刷(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nクラス NotificationService {\n    関数 send(to, subject, message) {\n        印刷(\"   📧 Email gönderildi:\");\n        印刷(\"      Kime: \" + to);\n        印刷(\"      Konu: \" + subject);\n        印刷(\"      Mesaj: \" + message);\n        戻る 真;\n    }\n    \n    関数 sendSms(phone, message) {\n        印刷(\"   📱 SMS gönderildi:\");\n        印刷(\"      Numara: \" + phone);\n        印刷(\"      Mesaj: \" + message);\n        戻る 真;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nクラス PaymentService {\n    関数 process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        変数 success = 真; // Gerçekte API çağrısı yapılır\n        \n        もし (success) {\n            戻る {\n                success: 真,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } そうでなければ {\n            戻る {\n                success: 偽,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    関数 refund(transactionId) {\n        戻る {\n            success: 真,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nクラス AuthService {\n    コンストラクタ() {\n        自己.userCount = 0;\n    }\n    \n    関数 register(user) {\n        自己.userCount = 自己.userCount + 1;\n        戻る {\n            success: 真,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    関数 login(email, password) {\n        // Basitleştirilmiş login\n        戻る {\n            success: 真,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    関数 logout(token) {\n        戻る { success: 真 };\n    }\n    \n    関数 verifyToken(token) {\n        戻る { valid: 真, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nクラス User {\n    コンストラクタ(name, email, password) {\n        自己.id = Math.floor(Math.random() * 10000);\n        自己.name = name;\n        自己.email = email;\n        自己.password = password;\n        自己.createdAt = \"2024-03-07\";\n    }\n    \n    関数 bilgi() {\n        戻る \"User #\" + 自己.id + \": \" + 自己.name + \" (\" + 自己.email + \")\";\n    }\n    \n    関数 getId() {\n        戻る 自己.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nクラス Product {\n    コンストラクタ(name, price, stock, category) {\n        自己.id = Math.floor(Math.random() * 10000);\n        自己.name = name;\n        自己.price = price;\n        自己.stock = stock;\n        自己.category = category;\n    }\n    \n    関数 bilgi() {\n        戻る 自己.name + \" - \" + 自己.price + \" TL (Stok: \" + 自己.stock + \", Kategori: \" + 自己.category + \")\";\n    }\n    \n    関数 inStock() {\n        戻る 自己.stock > 0;\n    }\n    \n    関数 getId() {\n        戻る 自己.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nクラス Order {\n    コンストラクタ(userId, productId, quantity, totalPrice) {\n        自己.id = Math.floor(Math.random() * 10000);\n        自己.userId = userId;\n        自己.productId = productId;\n        自己.quantity = quantity;\n        自己.totalPrice = totalPrice;\n        自己.status = \"pending\";\n        自己.createdAt = \"2024-03-07\";\n    }\n    \n    関数 bilgi() {\n        戻る \"Sipariş #\" + 自己.id + \" - Kullanıcı: \" + 自己.userId + \", Ürün: \" + 自己.productId + \", Adet: \" + 自己.quantity + \", Toplam: \" + 自己.totalPrice + \" TL, Durum: \" + 自己.status;\n    }\n    \n    関数 confirm() {\n        自己.status = \"confirmed\";\n    }\n    \n    関数 getId() {\n        戻る 自己.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\n関数 random_string(length) {\n    戻る \"random_\" + length;\n}\n\n関数 sleep(ms) {\n    // Bekleme simülasyonu\n    印刷(\"Bekleniyor: \" + ms + \"ms\");\n}\n\n関数 log(message) {\n    印刷(\"[LOG] \" + message);\n}\n\n関数 error(message) {\n    印刷(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nクラス Formatting {\n    静的 関数 currency(amount, currency) {\n        もし (currency == \"TRY\") {\n            戻る amount + \" ₺\";\n        } そうでなければ {\n            もし (currency == \"USD\") {\n                戻る \"$\" + amount;\n            } そうでなければ {\n                もし (currency == \"EUR\") {\n                    戻る \"€\" + amount;\n                } そうでなければ {\n                    戻る amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    静的 関数 date(date) {\n        戻る date;\n    }\n    \n    静的 関数 phone(phone) {\n        // (555) 123-4567 formatı\n        戻る \"(\" + phone + \")\";\n    }\n    \n    静的 関数 number(num) {\n        // 1,234,567 formatı\n        戻る num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nクラス Validation {\n    静的 関数 email(email) {\n        // Basit email 真lama\n        戻る email.length > 5;\n    }\n    \n    静的 関数 password(password) {\n        // Şifre en az 6 karakter olmalı\n        戻る password.length >= 6;\n    }\n    \n    静的 関数 price(price) {\n        戻る price > 0;\n    }\n    \n    静的 関数 phone(phone) {\n        // Telefon numarası 真lama\n        戻る phone.length == 10;\n    }\n    \n    静的 関数 required(value) {\n        戻る value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\n変数 APP_NAME = \"My Project\";\n変数 APP_VERSION = \"1.0.0\";\n変数 MAX_UPLOAD_SIZE = 10485760; // 10MB\n変数 SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\n変数 STATUS_PENDING = \"pending\";\n変数 STATUS_APPROVED = \"approved\";\n変数 STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\n変数 DB_HOST = \"localhost\";\n変数 DB_PORT = 5432;\n変数 DB_NAME = \"myproject_db\";\n変数 DB_USER = \"admin\";\n変数 DB_PASSWORD = \"secure_password\";\n\n関数 get_connection_string() {\n    戻る \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\n変数 API_BASE_URL = \"https://api.example.com\";\n変数 API_VERSION = \"v1\";\n変数 API_TIMEOUT = 30000;\n\n関数 get_api_url(endpoint) {\n    戻る API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "zh": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" 使用;\n\"src/models/product.hudhud\" 使用;\n\"src/models/order.hudhud\" 使用;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" 使用;\n\"src/services/payment.hudhud\" 使用;\n\"src/services/notification.hudhud\" 使用;\n\n// Yardımcı 类ları içe aktar\n\"src/utils/validation.hudhud\" 使用;\n\"src/utils/formatting.hudhud\" 使用;\n\n打印(\"============================================================\");\n打印(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\n打印(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\n变量 authService = 新 AuthService();\n变量 paymentService = 新 PaymentService();\n变量 notificationService = 新 NotificationService();\n\n打印(\"1️⃣  KULLANICI KAYDI\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni 使用ıcı oluştur\n变量 newUser = 新 User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\n打印(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email 真la\n如果 (Validation.email(newUser.email)) {\n    打印(\"✓ Email geçerli: \" + newUser.email);\n} 否则 {\n    打印(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\n变量 authResult = authService.register(newUser);\n如果 (authResult.success) {\n    打印(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\n打印(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\n变量 product = 新 Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\n打印(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat 真la\n如果 (Validation.price(product.price)) {\n    打印(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\n如果 (product.inStock()) {\n    打印(\"✓ Ürün stokta mevcut\");\n} 否则 {\n    打印(\"✗ Ürün stokta yok\");\n}\n\n打印(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\n变量 order = 新 Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\n打印(\"Sipariş oluşturuldu: \" + order.bilgi());\n\n打印(\"\\n4️⃣  ÖDEME İŞLEMİ\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\n变量 paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\n如果 (paymentResult.success) {\n    打印(\"✓ \" + paymentResult.message);\n    打印(\"  İşlem No: \" + paymentResult.transactionId);\n    打印(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    打印(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    打印(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} 否则 {\n    打印(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\n打印(\"\\n============================================================\");\n打印(\"✓ E-Ticaret sistemi demo tamamlandı!\");\n打印(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\n打印(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" 使用;\n\"../src/services/auth.hudhud\" 使用;\n\n打印(\"============================================================\");\n打印(\"Auth Service Tests\");\n打印(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\n变量 authService = 新 AuthService();\n打印(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\n变量 user = 新 User(\"Test User\", \"test@example.com\", \"test123\");\n变量 result1 = authService.register(user);\n\n如果 (result1.success) {\n    打印(\"✓ Test 2 passed: Registration successful\");\n    打印(\"  User ID: \" + result1.userId);\n    打印(\"  Message: \" + result1.message);\n} 否则 {\n    打印(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\n变量 loginResult = authService.login(\"test@example.com\", \"test123\");\n\n如果 (loginResult.success) {\n    打印(\"✓ Test 3 passed: Login successful\");\n    打印(\"  Token: \" + loginResult.token);\n    打印(\"  Message: \" + loginResult.message);\n} 否则 {\n    打印(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\n变量 verifyResult = authService.verifyToken(loginResult.token);\n\n如果 (verifyResult.valid) {\n    打印(\"✓ Test 4 passed: Token verification successful\");\n    打印(\"  User ID: \" + verifyResult.userId);\n} 否则 {\n    打印(\"✗ Test 4 failed: Token verification failed\");\n}\n\n打印(\"\\n============================================================\");\n打印(\"All Auth tests completed!\");\n打印(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" 使用;\n\n打印(\"============================================================\");\n打印(\"User Model Tests\");\n打印(\"============================================================\\n\");\n\n// Test 1: User creation\n变量 user = 新 User(\"Test User\", \"test@example.com\", \"test123\");\n\n如果 (user.name == \"Test User\") {\n    打印(\"✓ Test 1 passed: User creation\");\n} 否则 {\n    打印(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\n如果 (user.email == \"test@example.com\") {\n    打印(\"✓ Test 2 passed: Email set correctly\");\n} 否则 {\n    打印(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\n如果 (user.id > 0) {\n    打印(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} 否则 {\n    打印(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\n变量 info = user.bilgi();\n如果 (info.length > 0) {\n    打印(\"✓ Test 4 passed: bilgi() method works\");\n    打印(\"  Info: \" + info);\n} 否则 {\n    打印(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\n打印(\"\\n============================================================\");\n打印(\"All User tests completed!\");\n打印(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\n类 NotificationService {\n    函数 send(to, subject, message) {\n        打印(\"   📧 Email gönderildi:\");\n        打印(\"      Kime: \" + to);\n        打印(\"      Konu: \" + subject);\n        打印(\"      Mesaj: \" + message);\n        返回 真;\n    }\n    \n    函数 sendSms(phone, message) {\n        打印(\"   📱 SMS gönderildi:\");\n        打印(\"      Numara: \" + phone);\n        打印(\"      Mesaj: \" + message);\n        返回 真;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\n类 PaymentService {\n    函数 process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        变量 success = 真; // Gerçekte API çağrısı yapılır\n        \n        如果 (success) {\n            返回 {\n                success: 真,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } 否则 {\n            返回 {\n                success: 假,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    函数 refund(transactionId) {\n        返回 {\n            success: 真,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\n类 AuthService {\n    构造函数() {\n        自己.userCount = 0;\n    }\n    \n    函数 register(user) {\n        自己.userCount = 自己.userCount + 1;\n        返回 {\n            success: 真,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    函数 login(email, password) {\n        // Basitleştirilmiş login\n        返回 {\n            success: 真,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    函数 logout(token) {\n        返回 { success: 真 };\n    }\n    \n    函数 verifyToken(token) {\n        返回 { valid: 真, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\n类 User {\n    构造函数(name, email, password) {\n        自己.id = Math.floor(Math.random() * 10000);\n        自己.name = name;\n        自己.email = email;\n        自己.password = password;\n        自己.createdAt = \"2024-03-07\";\n    }\n    \n    函数 bilgi() {\n        返回 \"User #\" + 自己.id + \": \" + 自己.name + \" (\" + 自己.email + \")\";\n    }\n    \n    函数 getId() {\n        返回 自己.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\n类 Product {\n    构造函数(name, price, stock, category) {\n        自己.id = Math.floor(Math.random() * 10000);\n        自己.name = name;\n        自己.price = price;\n        自己.stock = stock;\n        自己.category = category;\n    }\n    \n    函数 bilgi() {\n        返回 自己.name + \" - \" + 自己.price + \" TL (Stok: \" + 自己.stock + \", Kategori: \" + 自己.category + \")\";\n    }\n    \n    函数 inStock() {\n        返回 自己.stock > 0;\n    }\n    \n    函数 getId() {\n        返回 自己.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\n类 Order {\n    构造函数(userId, productId, quantity, totalPrice) {\n        自己.id = Math.floor(Math.random() * 10000);\n        自己.userId = userId;\n        自己.productId = productId;\n        自己.quantity = quantity;\n        自己.totalPrice = totalPrice;\n        自己.status = \"pending\";\n        自己.createdAt = \"2024-03-07\";\n    }\n    \n    函数 bilgi() {\n        返回 \"Sipariş #\" + 自己.id + \" - Kullanıcı: \" + 自己.userId + \", Ürün: \" + 自己.productId + \", Adet: \" + 自己.quantity + \", Toplam: \" + 自己.totalPrice + \" TL, Durum: \" + 自己.status;\n    }\n    \n    函数 confirm() {\n        自己.status = \"confirmed\";\n    }\n    \n    函数 getId() {\n        返回 自己.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\n函数 random_string(length) {\n    返回 \"random_\" + length;\n}\n\n函数 sleep(ms) {\n    // Bekleme simülasyonu\n    打印(\"Bekleniyor: \" + ms + \"ms\");\n}\n\n函数 log(message) {\n    打印(\"[LOG] \" + message);\n}\n\n函数 error(message) {\n    打印(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\n类 Formatting {\n    静态 函数 currency(amount, currency) {\n        如果 (currency == \"TRY\") {\n            返回 amount + \" ₺\";\n        } 否则 {\n            如果 (currency == \"USD\") {\n                返回 \"$\" + amount;\n            } 否则 {\n                如果 (currency == \"EUR\") {\n                    返回 \"€\" + amount;\n                } 否则 {\n                    返回 amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    静态 函数 date(date) {\n        返回 date;\n    }\n    \n    静态 函数 phone(phone) {\n        // (555) 123-4567 formatı\n        返回 \"(\" + phone + \")\";\n    }\n    \n    静态 函数 number(num) {\n        // 1,234,567 formatı\n        返回 num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\n类 Validation {\n    静态 函数 email(email) {\n        // Basit email 真lama\n        返回 email.length > 5;\n    }\n    \n    静态 函数 password(password) {\n        // Şifre en az 6 karakter olmalı\n        返回 password.length >= 6;\n    }\n    \n    静态 函数 price(price) {\n        返回 price > 0;\n    }\n    \n    静态 函数 phone(phone) {\n        // Telefon numarası 真lama\n        返回 phone.length == 10;\n    }\n    \n    静态 函数 required(value) {\n        返回 value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\n变量 APP_NAME = \"My Project\";\n变量 APP_VERSION = \"1.0.0\";\n变量 MAX_UPLOAD_SIZE = 10485760; // 10MB\n变量 SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\n变量 STATUS_PENDING = \"pending\";\n变量 STATUS_APPROVED = \"approved\";\n变量 STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\n变量 DB_HOST = \"localhost\";\n变量 DB_PORT = 5432;\n变量 DB_NAME = \"myproject_db\";\n变量 DB_USER = \"admin\";\n变量 DB_PASSWORD = \"secure_password\";\n\n函数 get_connection_string() {\n    返回 \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\n变量 API_BASE_URL = \"https://api.example.com\";\n变量 API_VERSION = \"v1\";\n变量 API_TIMEOUT = 30000;\n\n函数 get_api_url(endpoint) {\n    返回 API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "hi": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" उपयोग;\n\"src/models/product.hudhud\" उपयोग;\n\"src/models/order.hudhud\" उपयोग;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" उपयोग;\n\"src/services/payment.hudhud\" उपयोग;\n\"src/services/notification.hudhud\" उपयोग;\n\n// Yardımcı वर्गları içe aktar\n\"src/utils/validation.hudhud\" उपयोग;\n\"src/utils/formatting.hudhud\" उपयोग;\n\nप्रिंट(\"============================================================\");\nप्रिंट(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nप्रिंट(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nचर authService = नया AuthService();\nचर paymentService = नया PaymentService();\nचर notificationService = नया NotificationService();\n\nप्रिंट(\"1️⃣  KULLANICI KAYDI\");\nप्रिंट(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni उपयोगıcı oluştur\nचर newUser = नया User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nप्रिंट(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email सत्यla\nअगर (Validation.email(newUser.email)) {\n    प्रिंट(\"✓ Email geçerli: \" + newUser.email);\n} नहीं_तो {\n    प्रिंट(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nचर authResult = authService.register(newUser);\nअगर (authResult.success) {\n    प्रिंट(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nप्रिंट(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nप्रिंट(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nचर product = नया Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nप्रिंट(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat सत्यla\nअगर (Validation.price(product.price)) {\n    प्रिंट(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nअगर (product.inStock()) {\n    प्रिंट(\"✓ Ürün stokta mevcut\");\n} नहीं_तो {\n    प्रिंट(\"✗ Ürün stokta yok\");\n}\n\nप्रिंट(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nप्रिंट(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nचर order = नया Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nप्रिंट(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nप्रिंट(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nप्रिंट(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nचर paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nअगर (paymentResult.success) {\n    प्रिंट(\"✓ \" + paymentResult.message);\n    प्रिंट(\"  İşlem No: \" + paymentResult.transactionId);\n    प्रिंट(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    प्रिंट(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    प्रिंट(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} नहीं_तो {\n    प्रिंट(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nप्रिंट(\"\\n============================================================\");\nप्रिंट(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nप्रिंट(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nप्रिंट(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" उपयोग;\n\"../src/services/auth.hudhud\" उपयोग;\n\nप्रिंट(\"============================================================\");\nप्रिंट(\"Auth Service Tests\");\nप्रिंट(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nचर authService = नया AuthService();\nप्रिंट(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nचर user = नया User(\"Test User\", \"test@example.com\", \"test123\");\nचर result1 = authService.register(user);\n\nअगर (result1.success) {\n    प्रिंट(\"✓ Test 2 passed: Registration successful\");\n    प्रिंट(\"  User ID: \" + result1.userId);\n    प्रिंट(\"  Message: \" + result1.message);\n} नहीं_तो {\n    प्रिंट(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nचर loginResult = authService.login(\"test@example.com\", \"test123\");\n\nअगर (loginResult.success) {\n    प्रिंट(\"✓ Test 3 passed: Login successful\");\n    प्रिंट(\"  Token: \" + loginResult.token);\n    प्रिंट(\"  Message: \" + loginResult.message);\n} नहीं_तो {\n    प्रिंट(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nचर verifyResult = authService.verifyToken(loginResult.token);\n\nअगर (verifyResult.valid) {\n    प्रिंट(\"✓ Test 4 passed: Token verification successful\");\n    प्रिंट(\"  User ID: \" + verifyResult.userId);\n} नहीं_तो {\n    प्रिंट(\"✗ Test 4 failed: Token verification failed\");\n}\n\nप्रिंट(\"\\n============================================================\");\nप्रिंट(\"All Auth tests completed!\");\nप्रिंट(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" उपयोग;\n\nप्रिंट(\"============================================================\");\nप्रिंट(\"User Model Tests\");\nप्रिंट(\"============================================================\\n\");\n\n// Test 1: User creation\nचर user = नया User(\"Test User\", \"test@example.com\", \"test123\");\n\nअगर (user.name == \"Test User\") {\n    प्रिंट(\"✓ Test 1 passed: User creation\");\n} नहीं_तो {\n    प्रिंट(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nअगर (user.email == \"test@example.com\") {\n    प्रिंट(\"✓ Test 2 passed: Email set correctly\");\n} नहीं_तो {\n    प्रिंट(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nअगर (user.id > 0) {\n    प्रिंट(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} नहीं_तो {\n    प्रिंट(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nचर info = user.bilgi();\nअगर (info.length > 0) {\n    प्रिंट(\"✓ Test 4 passed: bilgi() method works\");\n    प्रिंट(\"  Info: \" + info);\n} नहीं_तो {\n    प्रिंट(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nप्रिंट(\"\\n============================================================\");\nप्रिंट(\"All User tests completed!\");\nप्रिंट(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nवर्ग NotificationService {\n    फ़ंक्शन send(to, subject, message) {\n        प्रिंट(\"   📧 Email gönderildi:\");\n        प्रिंट(\"      Kime: \" + to);\n        प्रिंट(\"      Konu: \" + subject);\n        प्रिंट(\"      Mesaj: \" + message);\n        वापसी सत्य;\n    }\n    \n    फ़ंक्शन sendSms(phone, message) {\n        प्रिंट(\"   📱 SMS gönderildi:\");\n        प्रिंट(\"      Numara: \" + phone);\n        प्रिंट(\"      Mesaj: \" + message);\n        वापसी सत्य;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nवर्ग PaymentService {\n    फ़ंक्शन process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        चर success = सत्य; // Gerçekte API çağrısı yapılır\n        \n        अगर (success) {\n            वापसी {\n                success: सत्य,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } नहीं_तो {\n            वापसी {\n                success: असत्य,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    फ़ंक्शन refund(transactionId) {\n        वापसी {\n            success: सत्य,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nवर्ग AuthService {\n    निर्माता() {\n        स्वयं.userCount = 0;\n    }\n    \n    फ़ंक्शन register(user) {\n        स्वयं.userCount = स्वयं.userCount + 1;\n        वापसी {\n            success: सत्य,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    फ़ंक्शन login(email, password) {\n        // Basitleştirilmiş login\n        वापसी {\n            success: सत्य,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    फ़ंक्शन logout(token) {\n        वापसी { success: सत्य };\n    }\n    \n    फ़ंक्शन verifyToken(token) {\n        वापसी { valid: सत्य, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nवर्ग User {\n    निर्माता(name, email, password) {\n        स्वयं.id = Math.floor(Math.random() * 10000);\n        स्वयं.name = name;\n        स्वयं.email = email;\n        स्वयं.password = password;\n        स्वयं.createdAt = \"2024-03-07\";\n    }\n    \n    फ़ंक्शन bilgi() {\n        वापसी \"User #\" + स्वयं.id + \": \" + स्वयं.name + \" (\" + स्वयं.email + \")\";\n    }\n    \n    फ़ंक्शन getId() {\n        वापसी स्वयं.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nवर्ग Product {\n    निर्माता(name, price, stock, category) {\n        स्वयं.id = Math.floor(Math.random() * 10000);\n        स्वयं.name = name;\n        स्वयं.price = price;\n        स्वयं.stock = stock;\n        स्वयं.category = category;\n    }\n    \n    फ़ंक्शन bilgi() {\n        वापसी स्वयं.name + \" - \" + स्वयं.price + \" TL (Stok: \" + स्वयं.stock + \", Kategori: \" + स्वयं.category + \")\";\n    }\n    \n    फ़ंक्शन inStock() {\n        वापसी स्वयं.stock > 0;\n    }\n    \n    फ़ंक्शन getId() {\n        वापसी स्वयं.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nवर्ग Order {\n    निर्माता(userId, productId, quantity, totalPrice) {\n        स्वयं.id = Math.floor(Math.random() * 10000);\n        स्वयं.userId = userId;\n        स्वयं.productId = productId;\n        स्वयं.quantity = quantity;\n        स्वयं.totalPrice = totalPrice;\n        स्वयं.status = \"pending\";\n        स्वयं.createdAt = \"2024-03-07\";\n    }\n    \n    फ़ंक्शन bilgi() {\n        वापसी \"Sipariş #\" + स्वयं.id + \" - Kullanıcı: \" + स्वयं.userId + \", Ürün: \" + स्वयं.productId + \", Adet: \" + स्वयं.quantity + \", Toplam: \" + स्वयं.totalPrice + \" TL, Durum: \" + स्वयं.status;\n    }\n    \n    फ़ंक्शन confirm() {\n        स्वयं.status = \"confirmed\";\n    }\n    \n    फ़ंक्शन getId() {\n        वापसी स्वयं.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nफ़ंक्शन random_string(length) {\n    वापसी \"random_\" + length;\n}\n\nफ़ंक्शन sleep(ms) {\n    // Bekleme simülasyonu\n    प्रिंट(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nफ़ंक्शन log(message) {\n    प्रिंट(\"[LOG] \" + message);\n}\n\nफ़ंक्शन error(message) {\n    प्रिंट(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nवर्ग Formatting {\n    स्थिर फ़ंक्शन currency(amount, currency) {\n        अगर (currency == \"TRY\") {\n            वापसी amount + \" ₺\";\n        } नहीं_तो {\n            अगर (currency == \"USD\") {\n                वापसी \"$\" + amount;\n            } नहीं_तो {\n                अगर (currency == \"EUR\") {\n                    वापसी \"€\" + amount;\n                } नहीं_तो {\n                    वापसी amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    स्थिर फ़ंक्शन date(date) {\n        वापसी date;\n    }\n    \n    स्थिर फ़ंक्शन phone(phone) {\n        // (555) 123-4567 formatı\n        वापसी \"(\" + phone + \")\";\n    }\n    \n    स्थिर फ़ंक्शन number(num) {\n        // 1,234,567 formatı\n        वापसी num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nवर्ग Validation {\n    स्थिर फ़ंक्शन email(email) {\n        // Basit email सत्यlama\n        वापसी email.length > 5;\n    }\n    \n    स्थिर फ़ंक्शन password(password) {\n        // Şifre en az 6 karakter olmalı\n        वापसी password.length >= 6;\n    }\n    \n    स्थिर फ़ंक्शन price(price) {\n        वापसी price > 0;\n    }\n    \n    स्थिर फ़ंक्शन phone(phone) {\n        // Telefon numarası सत्यlama\n        वापसी phone.length == 10;\n    }\n    \n    स्थिर फ़ंक्शन required(value) {\n        वापसी value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nचर APP_NAME = \"My Project\";\nचर APP_VERSION = \"1.0.0\";\nचर MAX_UPLOAD_SIZE = 10485760; // 10MB\nचर SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nचर STATUS_PENDING = \"pending\";\nचर STATUS_APPROVED = \"approved\";\nचर STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nचर DB_HOST = \"localhost\";\nचर DB_PORT = 5432;\nचर DB_NAME = \"myproject_db\";\nचर DB_USER = \"admin\";\nचर DB_PASSWORD = \"secure_password\";\n\nफ़ंक्शन get_connection_string() {\n    वापसी \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nचर API_BASE_URL = \"https://api.example.com\";\nचर API_VERSION = \"v1\";\nचर API_TIMEOUT = 30000;\n\nफ़ंक्शन get_api_url(endpoint) {\n    वापसी API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "bn": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" ব্যবহার;\n\"src/models/product.hudhud\" ব্যবহার;\n\"src/models/order.hudhud\" ব্যবহার;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" ব্যবহার;\n\"src/services/payment.hudhud\" ব্যবহার;\n\"src/services/notification.hudhud\" ব্যবহার;\n\n// Yardımcı শ্রেণীları içe aktar\n\"src/utils/validation.hudhud\" ব্যবহার;\n\"src/utils/formatting.hudhud\" ব্যবহার;\n\nমুদ্রণ(\"============================================================\");\nমুদ্রণ(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nমুদ্রণ(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nচলক authService = নতুন AuthService();\nচলক paymentService = নতুন PaymentService();\nচলক notificationService = নতুন NotificationService();\n\nমুদ্রণ(\"1️⃣  KULLANICI KAYDI\");\nমুদ্রণ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni ব্যবহারıcı oluştur\nচলক newUser = নতুন User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nমুদ্রণ(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email সত্যla\nযদি (Validation.email(newUser.email)) {\n    মুদ্রণ(\"✓ Email geçerli: \" + newUser.email);\n} নাহলে {\n    মুদ্রণ(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nচলক authResult = authService.register(newUser);\nযদি (authResult.success) {\n    মুদ্রণ(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nমুদ্রণ(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nমুদ্রণ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nচলক product = নতুন Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nমুদ্রণ(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat সত্যla\nযদি (Validation.price(product.price)) {\n    মুদ্রণ(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nযদি (product.inStock()) {\n    মুদ্রণ(\"✓ Ürün stokta mevcut\");\n} নাহলে {\n    মুদ্রণ(\"✗ Ürün stokta yok\");\n}\n\nমুদ্রণ(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nমুদ্রণ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nচলক order = নতুন Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nমুদ্রণ(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nমুদ্রণ(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nমুদ্রণ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nচলক paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nযদি (paymentResult.success) {\n    মুদ্রণ(\"✓ \" + paymentResult.message);\n    মুদ্রণ(\"  İşlem No: \" + paymentResult.transactionId);\n    মুদ্রণ(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    মুদ্রণ(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    মুদ্রণ(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} নাহলে {\n    মুদ্রণ(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nমুদ্রণ(\"\\n============================================================\");\nমুদ্রণ(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nমুদ্রণ(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nমুদ্রণ(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" ব্যবহার;\n\"../src/services/auth.hudhud\" ব্যবহার;\n\nমুদ্রণ(\"============================================================\");\nমুদ্রণ(\"Auth Service Tests\");\nমুদ্রণ(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nচলক authService = নতুন AuthService();\nমুদ্রণ(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nচলক user = নতুন User(\"Test User\", \"test@example.com\", \"test123\");\nচলক result1 = authService.register(user);\n\nযদি (result1.success) {\n    মুদ্রণ(\"✓ Test 2 passed: Registration successful\");\n    মুদ্রণ(\"  User ID: \" + result1.userId);\n    মুদ্রণ(\"  Message: \" + result1.message);\n} নাহলে {\n    মুদ্রণ(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nচলক loginResult = authService.login(\"test@example.com\", \"test123\");\n\nযদি (loginResult.success) {\n    মুদ্রণ(\"✓ Test 3 passed: Login successful\");\n    মুদ্রণ(\"  Token: \" + loginResult.token);\n    মুদ্রণ(\"  Message: \" + loginResult.message);\n} নাহলে {\n    মুদ্রণ(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nচলক verifyResult = authService.verifyToken(loginResult.token);\n\nযদি (verifyResult.valid) {\n    মুদ্রণ(\"✓ Test 4 passed: Token verification successful\");\n    মুদ্রণ(\"  User ID: \" + verifyResult.userId);\n} নাহলে {\n    মুদ্রণ(\"✗ Test 4 failed: Token verification failed\");\n}\n\nমুদ্রণ(\"\\n============================================================\");\nমুদ্রণ(\"All Auth tests completed!\");\nমুদ্রণ(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" ব্যবহার;\n\nমুদ্রণ(\"============================================================\");\nমুদ্রণ(\"User Model Tests\");\nমুদ্রণ(\"============================================================\\n\");\n\n// Test 1: User creation\nচলক user = নতুন User(\"Test User\", \"test@example.com\", \"test123\");\n\nযদি (user.name == \"Test User\") {\n    মুদ্রণ(\"✓ Test 1 passed: User creation\");\n} নাহলে {\n    মুদ্রণ(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nযদি (user.email == \"test@example.com\") {\n    মুদ্রণ(\"✓ Test 2 passed: Email set correctly\");\n} নাহলে {\n    মুদ্রণ(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nযদি (user.id > 0) {\n    মুদ্রণ(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} নাহলে {\n    মুদ্রণ(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nচলক info = user.bilgi();\nযদি (info.length > 0) {\n    মুদ্রণ(\"✓ Test 4 passed: bilgi() method works\");\n    মুদ্রণ(\"  Info: \" + info);\n} নাহলে {\n    মুদ্রণ(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nমুদ্রণ(\"\\n============================================================\");\nমুদ্রণ(\"All User tests completed!\");\nমুদ্রণ(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nশ্রেণী NotificationService {\n    ফাংশন send(to, subject, message) {\n        মুদ্রণ(\"   📧 Email gönderildi:\");\n        মুদ্রণ(\"      Kime: \" + to);\n        মুদ্রণ(\"      Konu: \" + subject);\n        মুদ্রণ(\"      Mesaj: \" + message);\n        ফেরত সত্য;\n    }\n    \n    ফাংশন sendSms(phone, message) {\n        মুদ্রণ(\"   📱 SMS gönderildi:\");\n        মুদ্রণ(\"      Numara: \" + phone);\n        মুদ্রণ(\"      Mesaj: \" + message);\n        ফেরত সত্য;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nশ্রেণী PaymentService {\n    ফাংশন process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        চলক success = সত্য; // Gerçekte API çağrısı yapılır\n        \n        যদি (success) {\n            ফেরত {\n                success: সত্য,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } নাহলে {\n            ফেরত {\n                success: মিথ্যা,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    ফাংশন refund(transactionId) {\n        ফেরত {\n            success: সত্য,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nশ্রেণী AuthService {\n    নির্মাতা() {\n        নিজ.userCount = 0;\n    }\n    \n    ফাংশন register(user) {\n        নিজ.userCount = নিজ.userCount + 1;\n        ফেরত {\n            success: সত্য,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    ফাংশন login(email, password) {\n        // Basitleştirilmiş login\n        ফেরত {\n            success: সত্য,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    ফাংশন logout(token) {\n        ফেরত { success: সত্য };\n    }\n    \n    ফাংশন verifyToken(token) {\n        ফেরত { valid: সত্য, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nশ্রেণী User {\n    নির্মাতা(name, email, password) {\n        নিজ.id = Math.floor(Math.random() * 10000);\n        নিজ.name = name;\n        নিজ.email = email;\n        নিজ.password = password;\n        নিজ.createdAt = \"2024-03-07\";\n    }\n    \n    ফাংশন bilgi() {\n        ফেরত \"User #\" + নিজ.id + \": \" + নিজ.name + \" (\" + নিজ.email + \")\";\n    }\n    \n    ফাংশন getId() {\n        ফেরত নিজ.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nশ্রেণী Product {\n    নির্মাতা(name, price, stock, category) {\n        নিজ.id = Math.floor(Math.random() * 10000);\n        নিজ.name = name;\n        নিজ.price = price;\n        নিজ.stock = stock;\n        নিজ.category = category;\n    }\n    \n    ফাংশন bilgi() {\n        ফেরত নিজ.name + \" - \" + নিজ.price + \" TL (Stok: \" + নিজ.stock + \", Kategori: \" + নিজ.category + \")\";\n    }\n    \n    ফাংশন inStock() {\n        ফেরত নিজ.stock > 0;\n    }\n    \n    ফাংশন getId() {\n        ফেরত নিজ.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nশ্রেণী Order {\n    নির্মাতা(userId, productId, quantity, totalPrice) {\n        নিজ.id = Math.floor(Math.random() * 10000);\n        নিজ.userId = userId;\n        নিজ.productId = productId;\n        নিজ.quantity = quantity;\n        নিজ.totalPrice = totalPrice;\n        নিজ.status = \"pending\";\n        নিজ.createdAt = \"2024-03-07\";\n    }\n    \n    ফাংশন bilgi() {\n        ফেরত \"Sipariş #\" + নিজ.id + \" - Kullanıcı: \" + নিজ.userId + \", Ürün: \" + নিজ.productId + \", Adet: \" + নিজ.quantity + \", Toplam: \" + নিজ.totalPrice + \" TL, Durum: \" + নিজ.status;\n    }\n    \n    ফাংশন confirm() {\n        নিজ.status = \"confirmed\";\n    }\n    \n    ফাংশন getId() {\n        ফেরত নিজ.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nফাংশন random_string(length) {\n    ফেরত \"random_\" + length;\n}\n\nফাংশন sleep(ms) {\n    // Bekleme simülasyonu\n    মুদ্রণ(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nফাংশন log(message) {\n    মুদ্রণ(\"[LOG] \" + message);\n}\n\nফাংশন error(message) {\n    মুদ্রণ(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nশ্রেণী Formatting {\n    স্থির ফাংশন currency(amount, currency) {\n        যদি (currency == \"TRY\") {\n            ফেরত amount + \" ₺\";\n        } নাহলে {\n            যদি (currency == \"USD\") {\n                ফেরত \"$\" + amount;\n            } নাহলে {\n                যদি (currency == \"EUR\") {\n                    ফেরত \"€\" + amount;\n                } নাহলে {\n                    ফেরত amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    স্থির ফাংশন date(date) {\n        ফেরত date;\n    }\n    \n    স্থির ফাংশন phone(phone) {\n        // (555) 123-4567 formatı\n        ফেরত \"(\" + phone + \")\";\n    }\n    \n    স্থির ফাংশন number(num) {\n        // 1,234,567 formatı\n        ফেরত num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nশ্রেণী Validation {\n    স্থির ফাংশন email(email) {\n        // Basit email সত্যlama\n        ফেরত email.length > 5;\n    }\n    \n    স্থির ফাংশন password(password) {\n        // Şifre en az 6 karakter olmalı\n        ফেরত password.length >= 6;\n    }\n    \n    স্থির ফাংশন price(price) {\n        ফেরত price > 0;\n    }\n    \n    স্থির ফাংশন phone(phone) {\n        // Telefon numarası সত্যlama\n        ফেরত phone.length == 10;\n    }\n    \n    স্থির ফাংশন required(value) {\n        ফেরত value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nচলক APP_NAME = \"My Project\";\nচলক APP_VERSION = \"1.0.0\";\nচলক MAX_UPLOAD_SIZE = 10485760; // 10MB\nচলক SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nচলক STATUS_PENDING = \"pending\";\nচলক STATUS_APPROVED = \"approved\";\nচলক STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nচলক DB_HOST = \"localhost\";\nচলক DB_PORT = 5432;\nচলক DB_NAME = \"myproject_db\";\nচলক DB_USER = \"admin\";\nচলক DB_PASSWORD = \"secure_password\";\n\nফাংশন get_connection_string() {\n    ফেরত \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nচলক API_BASE_URL = \"https://api.example.com\";\nচলক API_VERSION = \"v1\";\nচলক API_TIMEOUT = 30000;\n\nফাংশন get_api_url(endpoint) {\n    ফেরত API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "bs": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" koristi;\n\"src/models/product.hudhud\" koristi;\n\"src/models/order.hudhud\" koristi;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" koristi;\n\"src/services/payment.hudhud\" koristi;\n\"src/services/notification.hudhud\" koristi;\n\n// Yardımcı klasaları içe aktar\n\"src/utils/validation.hudhud\" koristi;\n\"src/utils/formatting.hudhud\" koristi;\n\nštampaj(\"============================================================\");\nštampaj(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nštampaj(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nvarijabla authService = novi AuthService();\nvarijabla paymentService = novi PaymentService();\nvarijabla notificationService = novi NotificationService();\n\nštampaj(\"1️⃣  KULLANICI KAYDI\");\nštampaj(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni koristiıcı oluştur\nvarijabla newUser = novi User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nštampaj(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email tačnola\nako (Validation.email(newUser.email)) {\n    štampaj(\"✓ Email geçerli: \" + newUser.email);\n} inače {\n    štampaj(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nvarijabla authResult = authService.register(newUser);\nako (authResult.success) {\n    štampaj(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nštampaj(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nštampaj(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nvarijabla product = novi Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nštampaj(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat tačnola\nako (Validation.price(product.price)) {\n    štampaj(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nako (product.inStock()) {\n    štampaj(\"✓ Ürün stokta mevcut\");\n} inače {\n    štampaj(\"✗ Ürün stokta yok\");\n}\n\nštampaj(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nštampaj(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nvarijabla order = novi Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nštampaj(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nštampaj(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nštampaj(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nvarijabla paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nako (paymentResult.success) {\n    štampaj(\"✓ \" + paymentResult.message);\n    štampaj(\"  İşlem No: \" + paymentResult.transactionId);\n    štampaj(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    štampaj(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    štampaj(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} inače {\n    štampaj(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nštampaj(\"\\n============================================================\");\nštampaj(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nštampaj(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nštampaj(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" koristi;\n\"../src/services/auth.hudhud\" koristi;\n\nštampaj(\"============================================================\");\nštampaj(\"Auth Service Tests\");\nštampaj(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nvarijabla authService = novi AuthService();\nštampaj(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nvarijabla user = novi User(\"Test User\", \"test@example.com\", \"test123\");\nvarijabla result1 = authService.register(user);\n\nako (result1.success) {\n    štampaj(\"✓ Test 2 passed: Registration successful\");\n    štampaj(\"  User ID: \" + result1.userId);\n    štampaj(\"  Message: \" + result1.message);\n} inače {\n    štampaj(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nvarijabla loginResult = authService.login(\"test@example.com\", \"test123\");\n\nako (loginResult.success) {\n    štampaj(\"✓ Test 3 passed: Login successful\");\n    štampaj(\"  Token: \" + loginResult.token);\n    štampaj(\"  Message: \" + loginResult.message);\n} inače {\n    štampaj(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nvarijabla verifyResult = authService.verifyToken(loginResult.token);\n\nako (verifyResult.valid) {\n    štampaj(\"✓ Test 4 passed: Token verification successful\");\n    štampaj(\"  User ID: \" + verifyResult.userId);\n} inače {\n    štampaj(\"✗ Test 4 failed: Token verification failed\");\n}\n\nštampaj(\"\\n============================================================\");\nštampaj(\"All Auth tests completed!\");\nštampaj(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" koristi;\n\nštampaj(\"============================================================\");\nštampaj(\"User Model Tests\");\nštampaj(\"============================================================\\n\");\n\n// Test 1: User creation\nvarijabla user = novi User(\"Test User\", \"test@example.com\", \"test123\");\n\nako (user.name == \"Test User\") {\n    štampaj(\"✓ Test 1 passed: User creation\");\n} inače {\n    štampaj(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nako (user.email == \"test@example.com\") {\n    štampaj(\"✓ Test 2 passed: Email set correctly\");\n} inače {\n    štampaj(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nako (user.id > 0) {\n    štampaj(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} inače {\n    štampaj(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nvarijabla info = user.bilgi();\nako (info.length > 0) {\n    štampaj(\"✓ Test 4 passed: bilgi() method works\");\n    štampaj(\"  Info: \" + info);\n} inače {\n    štampaj(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nštampaj(\"\\n============================================================\");\nštampaj(\"All User tests completed!\");\nštampaj(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nklasa NotificationService {\n    funkcija send(to, subject, message) {\n        štampaj(\"   📧 Email gönderildi:\");\n        štampaj(\"      Kime: \" + to);\n        štampaj(\"      Konu: \" + subject);\n        štampaj(\"      Mesaj: \" + message);\n        vrati tačno;\n    }\n    \n    funkcija sendSms(phone, message) {\n        štampaj(\"   📱 SMS gönderildi:\");\n        štampaj(\"      Numara: \" + phone);\n        štampaj(\"      Mesaj: \" + message);\n        vrati tačno;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nklasa PaymentService {\n    funkcija process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        varijabla success = tačno; // Gerçekte API çağrısı yapılır\n        \n        ako (success) {\n            vrati {\n                success: tačno,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } inače {\n            vrati {\n                success: netačno,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    funkcija refund(transactionId) {\n        vrati {\n            success: tačno,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nklasa AuthService {\n    konstruktor() {\n        vlastiti.userCount = 0;\n    }\n    \n    funkcija register(user) {\n        vlastiti.userCount = vlastiti.userCount + 1;\n        vrati {\n            success: tačno,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    funkcija login(email, password) {\n        // Basitleştirilmiş login\n        vrati {\n            success: tačno,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    funkcija logout(token) {\n        vrati { success: tačno };\n    }\n    \n    funkcija verifyToken(token) {\n        vrati { valid: tačno, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nklasa User {\n    konstruktor(name, email, password) {\n        vlastiti.id = Math.floor(Math.random() * 10000);\n        vlastiti.name = name;\n        vlastiti.email = email;\n        vlastiti.password = password;\n        vlastiti.createdAt = \"2024-03-07\";\n    }\n    \n    funkcija bilgi() {\n        vrati \"User #\" + vlastiti.id + \": \" + vlastiti.name + \" (\" + vlastiti.email + \")\";\n    }\n    \n    funkcija getId() {\n        vrati vlastiti.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nklasa Product {\n    konstruktor(name, price, stock, category) {\n        vlastiti.id = Math.floor(Math.random() * 10000);\n        vlastiti.name = name;\n        vlastiti.price = price;\n        vlastiti.stock = stock;\n        vlastiti.category = category;\n    }\n    \n    funkcija bilgi() {\n        vrati vlastiti.name + \" - \" + vlastiti.price + \" TL (Stok: \" + vlastiti.stock + \", Kategori: \" + vlastiti.category + \")\";\n    }\n    \n    funkcija inStock() {\n        vrati vlastiti.stock > 0;\n    }\n    \n    funkcija getId() {\n        vrati vlastiti.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nklasa Order {\n    konstruktor(userId, productId, quantity, totalPrice) {\n        vlastiti.id = Math.floor(Math.random() * 10000);\n        vlastiti.userId = userId;\n        vlastiti.productId = productId;\n        vlastiti.quantity = quantity;\n        vlastiti.totalPrice = totalPrice;\n        vlastiti.status = \"pending\";\n        vlastiti.createdAt = \"2024-03-07\";\n    }\n    \n    funkcija bilgi() {\n        vrati \"Sipariş #\" + vlastiti.id + \" - Kullanıcı: \" + vlastiti.userId + \", Ürün: \" + vlastiti.productId + \", Adet: \" + vlastiti.quantity + \", Toplam: \" + vlastiti.totalPrice + \" TL, Durum: \" + vlastiti.status;\n    }\n    \n    funkcija confirm() {\n        vlastiti.status = \"confirmed\";\n    }\n    \n    funkcija getId() {\n        vrati vlastiti.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfunkcija random_string(length) {\n    vrati \"random_\" + length;\n}\n\nfunkcija sleep(ms) {\n    // Bekleme simülasyonu\n    štampaj(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfunkcija log(message) {\n    štampaj(\"[LOG] \" + message);\n}\n\nfunkcija error(message) {\n    štampaj(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nklasa Formatting {\n    statički funkcija currency(amount, currency) {\n        ako (currency == \"TRY\") {\n            vrati amount + \" ₺\";\n        } inače {\n            ako (currency == \"USD\") {\n                vrati \"$\" + amount;\n            } inače {\n                ako (currency == \"EUR\") {\n                    vrati \"€\" + amount;\n                } inače {\n                    vrati amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    statički funkcija date(date) {\n        vrati date;\n    }\n    \n    statički funkcija phone(phone) {\n        // (555) 123-4567 formatı\n        vrati \"(\" + phone + \")\";\n    }\n    \n    statički funkcija number(num) {\n        // 1,234,567 formatı\n        vrati num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nklasa Validation {\n    statički funkcija email(email) {\n        // Basit email tačnolama\n        vrati email.length > 5;\n    }\n    \n    statički funkcija password(password) {\n        // Şifre en az 6 karakter olmalı\n        vrati password.length >= 6;\n    }\n    \n    statički funkcija price(price) {\n        vrati price > 0;\n    }\n    \n    statički funkcija phone(phone) {\n        // Telefon numarası tačnolama\n        vrati phone.length == 10;\n    }\n    \n    statički funkcija required(value) {\n        vrati value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nvarijabla APP_NAME = \"My Project\";\nvarijabla APP_VERSION = \"1.0.0\";\nvarijabla MAX_UPLOAD_SIZE = 10485760; // 10MB\nvarijabla SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nvarijabla STATUS_PENDING = \"pending\";\nvarijabla STATUS_APPROVED = \"approved\";\nvarijabla STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nvarijabla DB_HOST = \"localhost\";\nvarijabla DB_PORT = 5432;\nvarijabla DB_NAME = \"myproject_db\";\nvarijabla DB_USER = \"admin\";\nvarijabla DB_PASSWORD = \"secure_password\";\n\nfunkcija get_connection_string() {\n    vrati \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nvarijabla API_BASE_URL = \"https://api.example.com\";\nvarijabla API_VERSION = \"v1\";\nvarijabla API_TIMEOUT = 30000;\n\nfunkcija get_api_url(endpoint) {\n    vrati API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "de": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" benutzen;\n\"src/models/product.hudhud\" benutzen;\n\"src/models/order.hudhud\" benutzen;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" benutzen;\n\"src/services/payment.hudhud\" benutzen;\n\"src/services/notification.hudhud\" benutzen;\n\n// Yardımcı klasseları içe aktar\n\"src/utils/validation.hudhud\" benutzen;\n\"src/utils/formatting.hudhud\" benutzen;\n\ndrucken(\"============================================================\");\ndrucken(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\ndrucken(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nvar authService = neu AuthService();\nvar paymentService = neu PaymentService();\nvar notificationService = neu NotificationService();\n\ndrucken(\"1️⃣  KULLANICI KAYDI\");\ndrucken(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni benutzenıcı oluştur\nvar newUser = neu User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\ndrucken(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email wahrla\nwenn (Validation.email(newUser.email)) {\n    drucken(\"✓ Email geçerli: \" + newUser.email);\n} sonst {\n    drucken(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nvar authResult = authService.register(newUser);\nwenn (authResult.success) {\n    drucken(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\ndrucken(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\ndrucken(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nvar product = neu Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\ndrucken(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat wahrla\nwenn (Validation.price(product.price)) {\n    drucken(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nwenn (product.inStock()) {\n    drucken(\"✓ Ürün stokta mevcut\");\n} sonst {\n    drucken(\"✗ Ürün stokta yok\");\n}\n\ndrucken(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\ndrucken(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nvar order = neu Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\ndrucken(\"Sipariş oluşturuldu: \" + order.bilgi());\n\ndrucken(\"\\n4️⃣  ÖDEME İŞLEMİ\");\ndrucken(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nvar paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nwenn (paymentResult.success) {\n    drucken(\"✓ \" + paymentResult.message);\n    drucken(\"  İşlem No: \" + paymentResult.transactionId);\n    drucken(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    drucken(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    drucken(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} sonst {\n    drucken(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\ndrucken(\"\\n============================================================\");\ndrucken(\"✓ E-Ticaret sistemi demo tamamlandı!\");\ndrucken(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\ndrucken(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" benutzen;\n\"../src/services/auth.hudhud\" benutzen;\n\ndrucken(\"============================================================\");\ndrucken(\"Auth Service Tests\");\ndrucken(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nvar authService = neu AuthService();\ndrucken(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nvar user = neu User(\"Test User\", \"test@example.com\", \"test123\");\nvar result1 = authService.register(user);\n\nwenn (result1.success) {\n    drucken(\"✓ Test 2 passed: Registration successful\");\n    drucken(\"  User ID: \" + result1.userId);\n    drucken(\"  Message: \" + result1.message);\n} sonst {\n    drucken(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nvar loginResult = authService.login(\"test@example.com\", \"test123\");\n\nwenn (loginResult.success) {\n    drucken(\"✓ Test 3 passed: Login successful\");\n    drucken(\"  Token: \" + loginResult.token);\n    drucken(\"  Message: \" + loginResult.message);\n} sonst {\n    drucken(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nvar verifyResult = authService.verifyToken(loginResult.token);\n\nwenn (verifyResult.valid) {\n    drucken(\"✓ Test 4 passed: Token verification successful\");\n    drucken(\"  User ID: \" + verifyResult.userId);\n} sonst {\n    drucken(\"✗ Test 4 failed: Token verification failed\");\n}\n\ndrucken(\"\\n============================================================\");\ndrucken(\"All Auth tests completed!\");\ndrucken(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" benutzen;\n\ndrucken(\"============================================================\");\ndrucken(\"User Model Tests\");\ndrucken(\"============================================================\\n\");\n\n// Test 1: User creation\nvar user = neu User(\"Test User\", \"test@example.com\", \"test123\");\n\nwenn (user.name == \"Test User\") {\n    drucken(\"✓ Test 1 passed: User creation\");\n} sonst {\n    drucken(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nwenn (user.email == \"test@example.com\") {\n    drucken(\"✓ Test 2 passed: Email set correctly\");\n} sonst {\n    drucken(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nwenn (user.id > 0) {\n    drucken(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} sonst {\n    drucken(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nvar info = user.bilgi();\nwenn (info.length > 0) {\n    drucken(\"✓ Test 4 passed: bilgi() method works\");\n    drucken(\"  Info: \" + info);\n} sonst {\n    drucken(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\ndrucken(\"\\n============================================================\");\ndrucken(\"All User tests completed!\");\ndrucken(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nklasse NotificationService {\n    funktion send(to, subject, message) {\n        drucken(\"   📧 Email gönderildi:\");\n        drucken(\"      Kime: \" + to);\n        drucken(\"      Konu: \" + subject);\n        drucken(\"      Mesaj: \" + message);\n        zurück wahr;\n    }\n    \n    funktion sendSms(phone, message) {\n        drucken(\"   📱 SMS gönderildi:\");\n        drucken(\"      Numara: \" + phone);\n        drucken(\"      Mesaj: \" + message);\n        zurück wahr;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nklasse PaymentService {\n    funktion process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        var success = wahr; // Gerçekte API çağrısı yapılır\n        \n        wenn (success) {\n            zurück {\n                success: wahr,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } sonst {\n            zurück {\n                success: falsch,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    funktion refund(transactionId) {\n        zurück {\n            success: wahr,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nklasse AuthService {\n    konstruktor() {\n        selbst.userCount = 0;\n    }\n    \n    funktion register(user) {\n        selbst.userCount = selbst.userCount + 1;\n        zurück {\n            success: wahr,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    funktion login(email, password) {\n        // Basitleştirilmiş login\n        zurück {\n            success: wahr,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    funktion logout(token) {\n        zurück { success: wahr };\n    }\n    \n    funktion verifyToken(token) {\n        zurück { valid: wahr, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nklasse User {\n    konstruktor(name, email, password) {\n        selbst.id = Math.floor(Math.random() * 10000);\n        selbst.name = name;\n        selbst.email = email;\n        selbst.password = password;\n        selbst.createdAt = \"2024-03-07\";\n    }\n    \n    funktion bilgi() {\n        zurück \"User #\" + selbst.id + \": \" + selbst.name + \" (\" + selbst.email + \")\";\n    }\n    \n    funktion getId() {\n        zurück selbst.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nklasse Product {\n    konstruktor(name, price, stock, category) {\n        selbst.id = Math.floor(Math.random() * 10000);\n        selbst.name = name;\n        selbst.price = price;\n        selbst.stock = stock;\n        selbst.category = category;\n    }\n    \n    funktion bilgi() {\n        zurück selbst.name + \" - \" + selbst.price + \" TL (Stok: \" + selbst.stock + \", Kategori: \" + selbst.category + \")\";\n    }\n    \n    funktion inStock() {\n        zurück selbst.stock > 0;\n    }\n    \n    funktion getId() {\n        zurück selbst.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nklasse Order {\n    konstruktor(userId, productId, quantity, totalPrice) {\n        selbst.id = Math.floor(Math.random() * 10000);\n        selbst.userId = userId;\n        selbst.productId = productId;\n        selbst.quantity = quantity;\n        selbst.totalPrice = totalPrice;\n        selbst.status = \"pending\";\n        selbst.createdAt = \"2024-03-07\";\n    }\n    \n    funktion bilgi() {\n        zurück \"Sipariş #\" + selbst.id + \" - Kullanıcı: \" + selbst.userId + \", Ürün: \" + selbst.productId + \", Adet: \" + selbst.quantity + \", Toplam: \" + selbst.totalPrice + \" TL, Durum: \" + selbst.status;\n    }\n    \n    funktion confirm() {\n        selbst.status = \"confirmed\";\n    }\n    \n    funktion getId() {\n        zurück selbst.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfunktion random_string(length) {\n    zurück \"random_\" + length;\n}\n\nfunktion sleep(ms) {\n    // Bekleme simülasyonu\n    drucken(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfunktion log(message) {\n    drucken(\"[LOG] \" + message);\n}\n\nfunktion error(message) {\n    drucken(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nklasse Formatting {\n    statisch funktion currency(amount, currency) {\n        wenn (currency == \"TRY\") {\n            zurück amount + \" ₺\";\n        } sonst {\n            wenn (currency == \"USD\") {\n                zurück \"$\" + amount;\n            } sonst {\n                wenn (currency == \"EUR\") {\n                    zurück \"€\" + amount;\n                } sonst {\n                    zurück amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    statisch funktion date(date) {\n        zurück date;\n    }\n    \n    statisch funktion phone(phone) {\n        // (555) 123-4567 formatı\n        zurück \"(\" + phone + \")\";\n    }\n    \n    statisch funktion number(num) {\n        // 1,234,567 formatı\n        zurück num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nklasse Validation {\n    statisch funktion email(email) {\n        // Basit email wahrlama\n        zurück email.length > 5;\n    }\n    \n    statisch funktion password(password) {\n        // Şifre en az 6 karakter olmalı\n        zurück password.length >= 6;\n    }\n    \n    statisch funktion price(price) {\n        zurück price > 0;\n    }\n    \n    statisch funktion phone(phone) {\n        // Telefon numarası wahrlama\n        zurück phone.length == 10;\n    }\n    \n    statisch funktion required(value) {\n        zurück value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nvar APP_NAME = \"My Project\";\nvar APP_VERSION = \"1.0.0\";\nvar MAX_UPLOAD_SIZE = 10485760; // 10MB\nvar SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nvar STATUS_PENDING = \"pending\";\nvar STATUS_APPROVED = \"approved\";\nvar STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nvar DB_HOST = \"localhost\";\nvar DB_PORT = 5432;\nvar DB_NAME = \"myproject_db\";\nvar DB_USER = \"admin\";\nvar DB_PASSWORD = \"secure_password\";\n\nfunktion get_connection_string() {\n    zurück \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nvar API_BASE_URL = \"https://api.example.com\";\nvar API_VERSION = \"v1\";\nvar API_TIMEOUT = 30000;\n\nfunktion get_api_url(endpoint) {\n    zurück API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "el": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" χρήση;\n\"src/models/product.hudhud\" χρήση;\n\"src/models/order.hudhud\" χρήση;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" χρήση;\n\"src/services/payment.hudhud\" χρήση;\n\"src/services/notification.hudhud\" χρήση;\n\n// Yardımcı κλάσηları içe aktar\n\"src/utils/validation.hudhud\" χρήση;\n\"src/utils/formatting.hudhud\" χρήση;\n\nεκτύπωση(\"============================================================\");\nεκτύπωση(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nεκτύπωση(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nμεταβλητή authService = νέο AuthService();\nμεταβλητή paymentService = νέο PaymentService();\nμεταβλητή notificationService = νέο NotificationService();\n\nεκτύπωση(\"1️⃣  KULLANICI KAYDI\");\nεκτύπωση(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni χρήσηıcı oluştur\nμεταβλητή newUser = νέο User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nεκτύπωση(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email αληθέςla\nαν (Validation.email(newUser.email)) {\n    εκτύπωση(\"✓ Email geçerli: \" + newUser.email);\n} αλλιώς {\n    εκτύπωση(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nμεταβλητή authResult = authService.register(newUser);\nαν (authResult.success) {\n    εκτύπωση(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nεκτύπωση(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nεκτύπωση(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nμεταβλητή product = νέο Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nεκτύπωση(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat αληθέςla\nαν (Validation.price(product.price)) {\n    εκτύπωση(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nαν (product.inStock()) {\n    εκτύπωση(\"✓ Ürün stokta mevcut\");\n} αλλιώς {\n    εκτύπωση(\"✗ Ürün stokta yok\");\n}\n\nεκτύπωση(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nεκτύπωση(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nμεταβλητή order = νέο Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nεκτύπωση(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nεκτύπωση(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nεκτύπωση(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nμεταβλητή paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nαν (paymentResult.success) {\n    εκτύπωση(\"✓ \" + paymentResult.message);\n    εκτύπωση(\"  İşlem No: \" + paymentResult.transactionId);\n    εκτύπωση(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    εκτύπωση(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    εκτύπωση(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} αλλιώς {\n    εκτύπωση(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nεκτύπωση(\"\\n============================================================\");\nεκτύπωση(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nεκτύπωση(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nεκτύπωση(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" χρήση;\n\"../src/services/auth.hudhud\" χρήση;\n\nεκτύπωση(\"============================================================\");\nεκτύπωση(\"Auth Service Tests\");\nεκτύπωση(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nμεταβλητή authService = νέο AuthService();\nεκτύπωση(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nμεταβλητή user = νέο User(\"Test User\", \"test@example.com\", \"test123\");\nμεταβλητή result1 = authService.register(user);\n\nαν (result1.success) {\n    εκτύπωση(\"✓ Test 2 passed: Registration successful\");\n    εκτύπωση(\"  User ID: \" + result1.userId);\n    εκτύπωση(\"  Message: \" + result1.message);\n} αλλιώς {\n    εκτύπωση(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nμεταβλητή loginResult = authService.login(\"test@example.com\", \"test123\");\n\nαν (loginResult.success) {\n    εκτύπωση(\"✓ Test 3 passed: Login successful\");\n    εκτύπωση(\"  Token: \" + loginResult.token);\n    εκτύπωση(\"  Message: \" + loginResult.message);\n} αλλιώς {\n    εκτύπωση(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nμεταβλητή verifyResult = authService.verifyToken(loginResult.token);\n\nαν (verifyResult.valid) {\n    εκτύπωση(\"✓ Test 4 passed: Token verification successful\");\n    εκτύπωση(\"  User ID: \" + verifyResult.userId);\n} αλλιώς {\n    εκτύπωση(\"✗ Test 4 failed: Token verification failed\");\n}\n\nεκτύπωση(\"\\n============================================================\");\nεκτύπωση(\"All Auth tests completed!\");\nεκτύπωση(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" χρήση;\n\nεκτύπωση(\"============================================================\");\nεκτύπωση(\"User Model Tests\");\nεκτύπωση(\"============================================================\\n\");\n\n// Test 1: User creation\nμεταβλητή user = νέο User(\"Test User\", \"test@example.com\", \"test123\");\n\nαν (user.name == \"Test User\") {\n    εκτύπωση(\"✓ Test 1 passed: User creation\");\n} αλλιώς {\n    εκτύπωση(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nαν (user.email == \"test@example.com\") {\n    εκτύπωση(\"✓ Test 2 passed: Email set correctly\");\n} αλλιώς {\n    εκτύπωση(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nαν (user.id > 0) {\n    εκτύπωση(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} αλλιώς {\n    εκτύπωση(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nμεταβλητή info = user.bilgi();\nαν (info.length > 0) {\n    εκτύπωση(\"✓ Test 4 passed: bilgi() method works\");\n    εκτύπωση(\"  Info: \" + info);\n} αλλιώς {\n    εκτύπωση(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nεκτύπωση(\"\\n============================================================\");\nεκτύπωση(\"All User tests completed!\");\nεκτύπωση(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nκλάση NotificationService {\n    συνάρτηση send(to, subject, message) {\n        εκτύπωση(\"   📧 Email gönderildi:\");\n        εκτύπωση(\"      Kime: \" + to);\n        εκτύπωση(\"      Konu: \" + subject);\n        εκτύπωση(\"      Mesaj: \" + message);\n        επιστροφή αληθές;\n    }\n    \n    συνάρτηση sendSms(phone, message) {\n        εκτύπωση(\"   📱 SMS gönderildi:\");\n        εκτύπωση(\"      Numara: \" + phone);\n        εκτύπωση(\"      Mesaj: \" + message);\n        επιστροφή αληθές;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nκλάση PaymentService {\n    συνάρτηση process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        μεταβλητή success = αληθές; // Gerçekte API çağrısı yapılır\n        \n        αν (success) {\n            επιστροφή {\n                success: αληθές,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } αλλιώς {\n            επιστροφή {\n                success: ψευδές,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    συνάρτηση refund(transactionId) {\n        επιστροφή {\n            success: αληθές,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nκλάση AuthService {\n    κατασκευαστής() {\n        εαυτός.userCount = 0;\n    }\n    \n    συνάρτηση register(user) {\n        εαυτός.userCount = εαυτός.userCount + 1;\n        επιστροφή {\n            success: αληθές,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    συνάρτηση login(email, password) {\n        // Basitleştirilmiş login\n        επιστροφή {\n            success: αληθές,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    συνάρτηση logout(token) {\n        επιστροφή { success: αληθές };\n    }\n    \n    συνάρτηση verifyToken(token) {\n        επιστροφή { valid: αληθές, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nκλάση User {\n    κατασκευαστής(name, email, password) {\n        εαυτός.id = Math.floor(Math.random() * 10000);\n        εαυτός.name = name;\n        εαυτός.email = email;\n        εαυτός.password = password;\n        εαυτός.createdAt = \"2024-03-07\";\n    }\n    \n    συνάρτηση bilgi() {\n        επιστροφή \"User #\" + εαυτός.id + \": \" + εαυτός.name + \" (\" + εαυτός.email + \")\";\n    }\n    \n    συνάρτηση getId() {\n        επιστροφή εαυτός.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nκλάση Product {\n    κατασκευαστής(name, price, stock, category) {\n        εαυτός.id = Math.floor(Math.random() * 10000);\n        εαυτός.name = name;\n        εαυτός.price = price;\n        εαυτός.stock = stock;\n        εαυτός.category = category;\n    }\n    \n    συνάρτηση bilgi() {\n        επιστροφή εαυτός.name + \" - \" + εαυτός.price + \" TL (Stok: \" + εαυτός.stock + \", Kategori: \" + εαυτός.category + \")\";\n    }\n    \n    συνάρτηση inStock() {\n        επιστροφή εαυτός.stock > 0;\n    }\n    \n    συνάρτηση getId() {\n        επιστροφή εαυτός.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nκλάση Order {\n    κατασκευαστής(userId, productId, quantity, totalPrice) {\n        εαυτός.id = Math.floor(Math.random() * 10000);\n        εαυτός.userId = userId;\n        εαυτός.productId = productId;\n        εαυτός.quantity = quantity;\n        εαυτός.totalPrice = totalPrice;\n        εαυτός.status = \"pending\";\n        εαυτός.createdAt = \"2024-03-07\";\n    }\n    \n    συνάρτηση bilgi() {\n        επιστροφή \"Sipariş #\" + εαυτός.id + \" - Kullanıcı: \" + εαυτός.userId + \", Ürün: \" + εαυτός.productId + \", Adet: \" + εαυτός.quantity + \", Toplam: \" + εαυτός.totalPrice + \" TL, Durum: \" + εαυτός.status;\n    }\n    \n    συνάρτηση confirm() {\n        εαυτός.status = \"confirmed\";\n    }\n    \n    συνάρτηση getId() {\n        επιστροφή εαυτός.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nσυνάρτηση random_string(length) {\n    επιστροφή \"random_\" + length;\n}\n\nσυνάρτηση sleep(ms) {\n    // Bekleme simülasyonu\n    εκτύπωση(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nσυνάρτηση log(message) {\n    εκτύπωση(\"[LOG] \" + message);\n}\n\nσυνάρτηση error(message) {\n    εκτύπωση(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nκλάση Formatting {\n    στατικό συνάρτηση currency(amount, currency) {\n        αν (currency == \"TRY\") {\n            επιστροφή amount + \" ₺\";\n        } αλλιώς {\n            αν (currency == \"USD\") {\n                επιστροφή \"$\" + amount;\n            } αλλιώς {\n                αν (currency == \"EUR\") {\n                    επιστροφή \"€\" + amount;\n                } αλλιώς {\n                    επιστροφή amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    στατικό συνάρτηση date(date) {\n        επιστροφή date;\n    }\n    \n    στατικό συνάρτηση phone(phone) {\n        // (555) 123-4567 formatı\n        επιστροφή \"(\" + phone + \")\";\n    }\n    \n    στατικό συνάρτηση number(num) {\n        // 1,234,567 formatı\n        επιστροφή num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nκλάση Validation {\n    στατικό συνάρτηση email(email) {\n        // Basit email αληθέςlama\n        επιστροφή email.length > 5;\n    }\n    \n    στατικό συνάρτηση password(password) {\n        // Şifre en az 6 karakter olmalı\n        επιστροφή password.length >= 6;\n    }\n    \n    στατικό συνάρτηση price(price) {\n        επιστροφή price > 0;\n    }\n    \n    στατικό συνάρτηση phone(phone) {\n        // Telefon numarası αληθέςlama\n        επιστροφή phone.length == 10;\n    }\n    \n    στατικό συνάρτηση required(value) {\n        επιστροφή value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nμεταβλητή APP_NAME = \"My Project\";\nμεταβλητή APP_VERSION = \"1.0.0\";\nμεταβλητή MAX_UPLOAD_SIZE = 10485760; // 10MB\nμεταβλητή SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nμεταβλητή STATUS_PENDING = \"pending\";\nμεταβλητή STATUS_APPROVED = \"approved\";\nμεταβλητή STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nμεταβλητή DB_HOST = \"localhost\";\nμεταβλητή DB_PORT = 5432;\nμεταβλητή DB_NAME = \"myproject_db\";\nμεταβλητή DB_USER = \"admin\";\nμεταβλητή DB_PASSWORD = \"secure_password\";\n\nσυνάρτηση get_connection_string() {\n    επιστροφή \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nμεταβλητή API_BASE_URL = \"https://api.example.com\";\nμεταβλητή API_VERSION = \"v1\";\nμεταβλητή API_TIMEOUT = 30000;\n\nσυνάρτηση get_api_url(endpoint) {\n    επιστροφή API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "en": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" use;\n\"src/models/product.hudhud\" use;\n\"src/models/order.hudhud\" use;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" use;\n\"src/services/payment.hudhud\" use;\n\"src/services/notification.hudhud\" use;\n\n// Yardımcı classları içe aktar\n\"src/utils/validation.hudhud\" use;\n\"src/utils/formatting.hudhud\" use;\n\nprint(\"============================================================\");\nprint(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nprint(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nvar authService = new AuthService();\nvar paymentService = new PaymentService();\nvar notificationService = new NotificationService();\n\nprint(\"1️⃣  KULLANICI KAYDI\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni useıcı oluştur\nvar newUser = new User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nprint(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email truela\nif (Validation.email(newUser.email)) {\n    print(\"✓ Email geçerli: \" + newUser.email);\n} else {\n    print(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nvar authResult = authService.register(newUser);\nif (authResult.success) {\n    print(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nprint(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nvar product = new Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nprint(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat truela\nif (Validation.price(product.price)) {\n    print(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nif (product.inStock()) {\n    print(\"✓ Ürün stokta mevcut\");\n} else {\n    print(\"✗ Ürün stokta yok\");\n}\n\nprint(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nvar order = new Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nprint(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nprint(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nvar paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nif (paymentResult.success) {\n    print(\"✓ \" + paymentResult.message);\n    print(\"  İşlem No: \" + paymentResult.transactionId);\n    print(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    print(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    print(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} else {\n    print(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nprint(\"\\n============================================================\");\nprint(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nprint(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nprint(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" use;\n\"../src/services/auth.hudhud\" use;\n\nprint(\"============================================================\");\nprint(\"Auth Service Tests\");\nprint(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nvar authService = new AuthService();\nprint(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nvar user = new User(\"Test User\", \"test@example.com\", \"test123\");\nvar result1 = authService.register(user);\n\nif (result1.success) {\n    print(\"✓ Test 2 passed: Registration successful\");\n    print(\"  User ID: \" + result1.userId);\n    print(\"  Message: \" + result1.message);\n} else {\n    print(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nvar loginResult = authService.login(\"test@example.com\", \"test123\");\n\nif (loginResult.success) {\n    print(\"✓ Test 3 passed: Login successful\");\n    print(\"  Token: \" + loginResult.token);\n    print(\"  Message: \" + loginResult.message);\n} else {\n    print(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nvar verifyResult = authService.verifyToken(loginResult.token);\n\nif (verifyResult.valid) {\n    print(\"✓ Test 4 passed: Token verification successful\");\n    print(\"  User ID: \" + verifyResult.userId);\n} else {\n    print(\"✗ Test 4 failed: Token verification failed\");\n}\n\nprint(\"\\n============================================================\");\nprint(\"All Auth tests completed!\");\nprint(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" use;\n\nprint(\"============================================================\");\nprint(\"User Model Tests\");\nprint(\"============================================================\\n\");\n\n// Test 1: User creation\nvar user = new User(\"Test User\", \"test@example.com\", \"test123\");\n\nif (user.name == \"Test User\") {\n    print(\"✓ Test 1 passed: User creation\");\n} else {\n    print(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nif (user.email == \"test@example.com\") {\n    print(\"✓ Test 2 passed: Email set correctly\");\n} else {\n    print(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nif (user.id > 0) {\n    print(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} else {\n    print(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nvar info = user.bilgi();\nif (info.length > 0) {\n    print(\"✓ Test 4 passed: bilgi() method works\");\n    print(\"  Info: \" + info);\n} else {\n    print(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nprint(\"\\n============================================================\");\nprint(\"All User tests completed!\");\nprint(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nclass NotificationService {\n    function send(to, subject, message) {\n        print(\"   📧 Email gönderildi:\");\n        print(\"      Kime: \" + to);\n        print(\"      Konu: \" + subject);\n        print(\"      Mesaj: \" + message);\n        return true;\n    }\n    \n    function sendSms(phone, message) {\n        print(\"   📱 SMS gönderildi:\");\n        print(\"      Numara: \" + phone);\n        print(\"      Mesaj: \" + message);\n        return true;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nclass PaymentService {\n    function process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        var success = true; // Gerçekte API çağrısı yapılır\n        \n        if (success) {\n            return {\n                success: true,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } else {\n            return {\n                success: false,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    function refund(transactionId) {\n        return {\n            success: true,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nclass AuthService {\n    constructor() {\n        self.userCount = 0;\n    }\n    \n    function register(user) {\n        self.userCount = self.userCount + 1;\n        return {\n            success: true,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    function login(email, password) {\n        // Basitleştirilmiş login\n        return {\n            success: true,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    function logout(token) {\n        return { success: true };\n    }\n    \n    function verifyToken(token) {\n        return { valid: true, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nclass User {\n    constructor(name, email, password) {\n        self.id = Math.floor(Math.random() * 10000);\n        self.name = name;\n        self.email = email;\n        self.password = password;\n        self.createdAt = \"2024-03-07\";\n    }\n    \n    function bilgi() {\n        return \"User #\" + self.id + \": \" + self.name + \" (\" + self.email + \")\";\n    }\n    \n    function getId() {\n        return self.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nclass Product {\n    constructor(name, price, stock, category) {\n        self.id = Math.floor(Math.random() * 10000);\n        self.name = name;\n        self.price = price;\n        self.stock = stock;\n        self.category = category;\n    }\n    \n    function bilgi() {\n        return self.name + \" - \" + self.price + \" TL (Stok: \" + self.stock + \", Kategori: \" + self.category + \")\";\n    }\n    \n    function inStock() {\n        return self.stock > 0;\n    }\n    \n    function getId() {\n        return self.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nclass Order {\n    constructor(userId, productId, quantity, totalPrice) {\n        self.id = Math.floor(Math.random() * 10000);\n        self.userId = userId;\n        self.productId = productId;\n        self.quantity = quantity;\n        self.totalPrice = totalPrice;\n        self.status = \"pending\";\n        self.createdAt = \"2024-03-07\";\n    }\n    \n    function bilgi() {\n        return \"Sipariş #\" + self.id + \" - Kullanıcı: \" + self.userId + \", Ürün: \" + self.productId + \", Adet: \" + self.quantity + \", Toplam: \" + self.totalPrice + \" TL, Durum: \" + self.status;\n    }\n    \n    function confirm() {\n        self.status = \"confirmed\";\n    }\n    \n    function getId() {\n        return self.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfunction random_string(length) {\n    return \"random_\" + length;\n}\n\nfunction sleep(ms) {\n    // Bekleme simülasyonu\n    print(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfunction log(message) {\n    print(\"[LOG] \" + message);\n}\n\nfunction error(message) {\n    print(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nclass Formatting {\n    static function currency(amount, currency) {\n        if (currency == \"TRY\") {\n            return amount + \" ₺\";\n        } else {\n            if (currency == \"USD\") {\n                return \"$\" + amount;\n            } else {\n                if (currency == \"EUR\") {\n                    return \"€\" + amount;\n                } else {\n                    return amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    static function date(date) {\n        return date;\n    }\n    \n    static function phone(phone) {\n        // (555) 123-4567 formatı\n        return \"(\" + phone + \")\";\n    }\n    \n    static function number(num) {\n        // 1,234,567 formatı\n        return num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nclass Validation {\n    static function email(email) {\n        // Basit email truelama\n        return email.length > 5;\n    }\n    \n    static function password(password) {\n        // Şifre en az 6 karakter olmalı\n        return password.length >= 6;\n    }\n    \n    static function price(price) {\n        return price > 0;\n    }\n    \n    static function phone(phone) {\n        // Telefon numarası truelama\n        return phone.length == 10;\n    }\n    \n    static function required(value) {\n        return value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nvar APP_NAME = \"My Project\";\nvar APP_VERSION = \"1.0.0\";\nvar MAX_UPLOAD_SIZE = 10485760; // 10MB\nvar SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nvar STATUS_PENDING = \"pending\";\nvar STATUS_APPROVED = \"approved\";\nvar STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nvar DB_HOST = \"localhost\";\nvar DB_PORT = 5432;\nvar DB_NAME = \"myproject_db\";\nvar DB_USER = \"admin\";\nvar DB_PASSWORD = \"secure_password\";\n\nfunction get_connection_string() {\n    return \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nvar API_BASE_URL = \"https://api.example.com\";\nvar API_VERSION = \"v1\";\nvar API_TIMEOUT = 30000;\n\nfunction get_api_url(endpoint) {\n    return API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "es": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" usar;\n\"src/models/product.hudhud\" usar;\n\"src/models/order.hudhud\" usar;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" usar;\n\"src/services/payment.hudhud\" usar;\n\"src/services/notification.hudhud\" usar;\n\n// Yardımcı claseları içe aktar\n\"src/utils/validation.hudhud\" usar;\n\"src/utils/formatting.hudhud\" usar;\n\nimprimir(\"============================================================\");\nimprimir(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nimprimir(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nvar authService = nuevo AuthService();\nvar paymentService = nuevo PaymentService();\nvar notificationService = nuevo NotificationService();\n\nimprimir(\"1️⃣  KULLANICI KAYDI\");\nimprimir(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni usarıcı oluştur\nvar newUser = nuevo User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nimprimir(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email verdaderola\nsi (Validation.email(newUser.email)) {\n    imprimir(\"✓ Email geçerli: \" + newUser.email);\n} sino {\n    imprimir(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nvar authResult = authService.register(newUser);\nsi (authResult.success) {\n    imprimir(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nimprimir(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nimprimir(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nvar product = nuevo Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nimprimir(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat verdaderola\nsi (Validation.price(product.price)) {\n    imprimir(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nsi (product.inStock()) {\n    imprimir(\"✓ Ürün stokta mevcut\");\n} sino {\n    imprimir(\"✗ Ürün stokta yok\");\n}\n\nimprimir(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nimprimir(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nvar order = nuevo Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nimprimir(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nimprimir(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nimprimir(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nvar paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nsi (paymentResult.success) {\n    imprimir(\"✓ \" + paymentResult.message);\n    imprimir(\"  İşlem No: \" + paymentResult.transactionId);\n    imprimir(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    imprimir(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    imprimir(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} sino {\n    imprimir(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nimprimir(\"\\n============================================================\");\nimprimir(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nimprimir(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nimprimir(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" usar;\n\"../src/services/auth.hudhud\" usar;\n\nimprimir(\"============================================================\");\nimprimir(\"Auth Service Tests\");\nimprimir(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nvar authService = nuevo AuthService();\nimprimir(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nvar user = nuevo User(\"Test User\", \"test@example.com\", \"test123\");\nvar result1 = authService.register(user);\n\nsi (result1.success) {\n    imprimir(\"✓ Test 2 passed: Registration successful\");\n    imprimir(\"  User ID: \" + result1.userId);\n    imprimir(\"  Message: \" + result1.message);\n} sino {\n    imprimir(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nvar loginResult = authService.login(\"test@example.com\", \"test123\");\n\nsi (loginResult.success) {\n    imprimir(\"✓ Test 3 passed: Login successful\");\n    imprimir(\"  Token: \" + loginResult.token);\n    imprimir(\"  Message: \" + loginResult.message);\n} sino {\n    imprimir(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nvar verifyResult = authService.verifyToken(loginResult.token);\n\nsi (verifyResult.valid) {\n    imprimir(\"✓ Test 4 passed: Token verification successful\");\n    imprimir(\"  User ID: \" + verifyResult.userId);\n} sino {\n    imprimir(\"✗ Test 4 failed: Token verification failed\");\n}\n\nimprimir(\"\\n============================================================\");\nimprimir(\"All Auth tests completed!\");\nimprimir(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" usar;\n\nimprimir(\"============================================================\");\nimprimir(\"User Model Tests\");\nimprimir(\"============================================================\\n\");\n\n// Test 1: User creation\nvar user = nuevo User(\"Test User\", \"test@example.com\", \"test123\");\n\nsi (user.name == \"Test User\") {\n    imprimir(\"✓ Test 1 passed: User creation\");\n} sino {\n    imprimir(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nsi (user.email == \"test@example.com\") {\n    imprimir(\"✓ Test 2 passed: Email set correctly\");\n} sino {\n    imprimir(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nsi (user.id > 0) {\n    imprimir(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} sino {\n    imprimir(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nvar info = user.bilgi();\nsi (info.length > 0) {\n    imprimir(\"✓ Test 4 passed: bilgi() method works\");\n    imprimir(\"  Info: \" + info);\n} sino {\n    imprimir(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nimprimir(\"\\n============================================================\");\nimprimir(\"All User tests completed!\");\nimprimir(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nclase NotificationService {\n    función send(to, subject, message) {\n        imprimir(\"   📧 Email gönderildi:\");\n        imprimir(\"      Kime: \" + to);\n        imprimir(\"      Konu: \" + subject);\n        imprimir(\"      Mesaj: \" + message);\n        retornar verdadero;\n    }\n    \n    función sendSms(phone, message) {\n        imprimir(\"   📱 SMS gönderildi:\");\n        imprimir(\"      Numara: \" + phone);\n        imprimir(\"      Mesaj: \" + message);\n        retornar verdadero;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nclase PaymentService {\n    función process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        var success = verdadero; // Gerçekte API çağrısı yapılır\n        \n        si (success) {\n            retornar {\n                success: verdadero,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } sino {\n            retornar {\n                success: falso,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    función refund(transactionId) {\n        retornar {\n            success: verdadero,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nclase AuthService {\n    constructor() {\n        propio.userCount = 0;\n    }\n    \n    función register(user) {\n        propio.userCount = propio.userCount + 1;\n        retornar {\n            success: verdadero,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    función login(email, password) {\n        // Basitleştirilmiş login\n        retornar {\n            success: verdadero,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    función logout(token) {\n        retornar { success: verdadero };\n    }\n    \n    función verifyToken(token) {\n        retornar { valid: verdadero, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nclase User {\n    constructor(name, email, password) {\n        propio.id = Math.floor(Math.random() * 10000);\n        propio.name = name;\n        propio.email = email;\n        propio.password = password;\n        propio.createdAt = \"2024-03-07\";\n    }\n    \n    función bilgi() {\n        retornar \"User #\" + propio.id + \": \" + propio.name + \" (\" + propio.email + \")\";\n    }\n    \n    función getId() {\n        retornar propio.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nclase Product {\n    constructor(name, price, stock, category) {\n        propio.id = Math.floor(Math.random() * 10000);\n        propio.name = name;\n        propio.price = price;\n        propio.stock = stock;\n        propio.category = category;\n    }\n    \n    función bilgi() {\n        retornar propio.name + \" - \" + propio.price + \" TL (Stok: \" + propio.stock + \", Kategori: \" + propio.category + \")\";\n    }\n    \n    función inStock() {\n        retornar propio.stock > 0;\n    }\n    \n    función getId() {\n        retornar propio.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nclase Order {\n    constructor(userId, productId, quantity, totalPrice) {\n        propio.id = Math.floor(Math.random() * 10000);\n        propio.userId = userId;\n        propio.productId = productId;\n        propio.quantity = quantity;\n        propio.totalPrice = totalPrice;\n        propio.status = \"pending\";\n        propio.createdAt = \"2024-03-07\";\n    }\n    \n    función bilgi() {\n        retornar \"Sipariş #\" + propio.id + \" - Kullanıcı: \" + propio.userId + \", Ürün: \" + propio.productId + \", Adet: \" + propio.quantity + \", Toplam: \" + propio.totalPrice + \" TL, Durum: \" + propio.status;\n    }\n    \n    función confirm() {\n        propio.status = \"confirmed\";\n    }\n    \n    función getId() {\n        retornar propio.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfunción random_string(length) {\n    retornar \"random_\" + length;\n}\n\nfunción sleep(ms) {\n    // Bekleme simülasyonu\n    imprimir(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfunción log(message) {\n    imprimir(\"[LOG] \" + message);\n}\n\nfunción error(message) {\n    imprimir(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nclase Formatting {\n    estático función currency(amount, currency) {\n        si (currency == \"TRY\") {\n            retornar amount + \" ₺\";\n        } sino {\n            si (currency == \"USD\") {\n                retornar \"$\" + amount;\n            } sino {\n                si (currency == \"EUR\") {\n                    retornar \"€\" + amount;\n                } sino {\n                    retornar amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    estático función date(date) {\n        retornar date;\n    }\n    \n    estático función phone(phone) {\n        // (555) 123-4567 formatı\n        retornar \"(\" + phone + \")\";\n    }\n    \n    estático función number(num) {\n        // 1,234,567 formatı\n        retornar num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nclase Validation {\n    estático función email(email) {\n        // Basit email verdaderolama\n        retornar email.length > 5;\n    }\n    \n    estático función password(password) {\n        // Şifre en az 6 karakter olmalı\n        retornar password.length >= 6;\n    }\n    \n    estático función price(price) {\n        retornar price > 0;\n    }\n    \n    estático función phone(phone) {\n        // Telefon numarası verdaderolama\n        retornar phone.length == 10;\n    }\n    \n    estático función required(value) {\n        retornar value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nvar APP_NAME = \"My Project\";\nvar APP_VERSION = \"1.0.0\";\nvar MAX_UPLOAD_SIZE = 10485760; // 10MB\nvar SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nvar STATUS_PENDING = \"pending\";\nvar STATUS_APPROVED = \"approved\";\nvar STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nvar DB_HOST = \"localhost\";\nvar DB_PORT = 5432;\nvar DB_NAME = \"myproject_db\";\nvar DB_USER = \"admin\";\nvar DB_PASSWORD = \"secure_password\";\n\nfunción get_connection_string() {\n    retornar \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nvar API_BASE_URL = \"https://api.example.com\";\nvar API_VERSION = \"v1\";\nvar API_TIMEOUT = 30000;\n\nfunción get_api_url(endpoint) {\n    retornar API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "fa": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" استفاده;\n\"src/models/product.hudhud\" استفاده;\n\"src/models/order.hudhud\" استفاده;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" استفاده;\n\"src/services/payment.hudhud\" استفاده;\n\"src/services/notification.hudhud\" استفاده;\n\n// Yardımcı کلاسları içe aktar\n\"src/utils/validation.hudhud\" استفاده;\n\"src/utils/formatting.hudhud\" استفاده;\n\nچاپ(\"============================================================\");\nچاپ(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nچاپ(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nمتغیر authService = جدید AuthService();\nمتغیر paymentService = جدید PaymentService();\nمتغیر notificationService = جدید NotificationService();\n\nچاپ(\"1️⃣  KULLANICI KAYDI\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni استفادهıcı oluştur\nمتغیر newUser = جدید User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nچاپ(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email درستla\nاگر (Validation.email(newUser.email)) {\n    چاپ(\"✓ Email geçerli: \" + newUser.email);\n} وگرنه {\n    چاپ(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nمتغیر authResult = authService.register(newUser);\nاگر (authResult.success) {\n    چاپ(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nچاپ(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nمتغیر product = جدید Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nچاپ(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat درستla\nاگر (Validation.price(product.price)) {\n    چاپ(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nاگر (product.inStock()) {\n    چاپ(\"✓ Ürün stokta mevcut\");\n} وگرنه {\n    چاپ(\"✗ Ürün stokta yok\");\n}\n\nچاپ(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nمتغیر order = جدید Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nچاپ(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nچاپ(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nمتغیر paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nاگر (paymentResult.success) {\n    چاپ(\"✓ \" + paymentResult.message);\n    چاپ(\"  İşlem No: \" + paymentResult.transactionId);\n    چاپ(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    چاپ(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    چاپ(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} وگرنه {\n    چاپ(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nچاپ(\"\\n============================================================\");\nچاپ(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nچاپ(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nچاپ(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" استفاده;\n\"../src/services/auth.hudhud\" استفاده;\n\nچاپ(\"============================================================\");\nچاپ(\"Auth Service Tests\");\nچاپ(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nمتغیر authService = جدید AuthService();\nچاپ(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nمتغیر user = جدید User(\"Test User\", \"test@example.com\", \"test123\");\nمتغیر result1 = authService.register(user);\n\nاگر (result1.success) {\n    چاپ(\"✓ Test 2 passed: Registration successful\");\n    چاپ(\"  User ID: \" + result1.userId);\n    چاپ(\"  Message: \" + result1.message);\n} وگرنه {\n    چاپ(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nمتغیر loginResult = authService.login(\"test@example.com\", \"test123\");\n\nاگر (loginResult.success) {\n    چاپ(\"✓ Test 3 passed: Login successful\");\n    چاپ(\"  Token: \" + loginResult.token);\n    چاپ(\"  Message: \" + loginResult.message);\n} وگرنه {\n    چاپ(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nمتغیر verifyResult = authService.verifyToken(loginResult.token);\n\nاگر (verifyResult.valid) {\n    چاپ(\"✓ Test 4 passed: Token verification successful\");\n    چاپ(\"  User ID: \" + verifyResult.userId);\n} وگرنه {\n    چاپ(\"✗ Test 4 failed: Token verification failed\");\n}\n\nچاپ(\"\\n============================================================\");\nچاپ(\"All Auth tests completed!\");\nچاپ(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" استفاده;\n\nچاپ(\"============================================================\");\nچاپ(\"User Model Tests\");\nچاپ(\"============================================================\\n\");\n\n// Test 1: User creation\nمتغیر user = جدید User(\"Test User\", \"test@example.com\", \"test123\");\n\nاگر (user.name == \"Test User\") {\n    چاپ(\"✓ Test 1 passed: User creation\");\n} وگرنه {\n    چاپ(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nاگر (user.email == \"test@example.com\") {\n    چاپ(\"✓ Test 2 passed: Email set correctly\");\n} وگرنه {\n    چاپ(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nاگر (user.id > 0) {\n    چاپ(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} وگرنه {\n    چاپ(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nمتغیر info = user.bilgi();\nاگر (info.length > 0) {\n    چاپ(\"✓ Test 4 passed: bilgi() method works\");\n    چاپ(\"  Info: \" + info);\n} وگرنه {\n    چاپ(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nچاپ(\"\\n============================================================\");\nچاپ(\"All User tests completed!\");\nچاپ(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nکلاس NotificationService {\n    تابع send(to, subject, message) {\n        چاپ(\"   📧 Email gönderildi:\");\n        چاپ(\"      Kime: \" + to);\n        چاپ(\"      Konu: \" + subject);\n        چاپ(\"      Mesaj: \" + message);\n        برگشت درست;\n    }\n    \n    تابع sendSms(phone, message) {\n        چاپ(\"   📱 SMS gönderildi:\");\n        چاپ(\"      Numara: \" + phone);\n        چاپ(\"      Mesaj: \" + message);\n        برگشت درست;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nکلاس PaymentService {\n    تابع process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        متغیر success = درست; // Gerçekte API çağrısı yapılır\n        \n        اگر (success) {\n            برگشت {\n                success: درست,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } وگرنه {\n            برگشت {\n                success: نادرست,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    تابع refund(transactionId) {\n        برگشت {\n            success: درست,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nکلاس AuthService {\n    سازنده() {\n        خود.userCount = 0;\n    }\n    \n    تابع register(user) {\n        خود.userCount = خود.userCount + 1;\n        برگشت {\n            success: درست,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    تابع login(email, password) {\n        // Basitleştirilmiş login\n        برگشت {\n            success: درست,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    تابع logout(token) {\n        برگشت { success: درست };\n    }\n    \n    تابع verifyToken(token) {\n        برگشت { valid: درست, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nکلاس User {\n    سازنده(name, email, password) {\n        خود.id = Math.floor(Math.random() * 10000);\n        خود.name = name;\n        خود.email = email;\n        خود.password = password;\n        خود.createdAt = \"2024-03-07\";\n    }\n    \n    تابع bilgi() {\n        برگشت \"User #\" + خود.id + \": \" + خود.name + \" (\" + خود.email + \")\";\n    }\n    \n    تابع getId() {\n        برگشت خود.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nکلاس Product {\n    سازنده(name, price, stock, category) {\n        خود.id = Math.floor(Math.random() * 10000);\n        خود.name = name;\n        خود.price = price;\n        خود.stock = stock;\n        خود.category = category;\n    }\n    \n    تابع bilgi() {\n        برگشت خود.name + \" - \" + خود.price + \" TL (Stok: \" + خود.stock + \", Kategori: \" + خود.category + \")\";\n    }\n    \n    تابع inStock() {\n        برگشت خود.stock > 0;\n    }\n    \n    تابع getId() {\n        برگشت خود.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nکلاس Order {\n    سازنده(userId, productId, quantity, totalPrice) {\n        خود.id = Math.floor(Math.random() * 10000);\n        خود.userId = userId;\n        خود.productId = productId;\n        خود.quantity = quantity;\n        خود.totalPrice = totalPrice;\n        خود.status = \"pending\";\n        خود.createdAt = \"2024-03-07\";\n    }\n    \n    تابع bilgi() {\n        برگشت \"Sipariş #\" + خود.id + \" - Kullanıcı: \" + خود.userId + \", Ürün: \" + خود.productId + \", Adet: \" + خود.quantity + \", Toplam: \" + خود.totalPrice + \" TL, Durum: \" + خود.status;\n    }\n    \n    تابع confirm() {\n        خود.status = \"confirmed\";\n    }\n    \n    تابع getId() {\n        برگشت خود.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nتابع random_string(length) {\n    برگشت \"random_\" + length;\n}\n\nتابع sleep(ms) {\n    // Bekleme simülasyonu\n    چاپ(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nتابع log(message) {\n    چاپ(\"[LOG] \" + message);\n}\n\nتابع error(message) {\n    چاپ(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nکلاس Formatting {\n    ثابت تابع currency(amount, currency) {\n        اگر (currency == \"TRY\") {\n            برگشت amount + \" ₺\";\n        } وگرنه {\n            اگر (currency == \"USD\") {\n                برگشت \"$\" + amount;\n            } وگرنه {\n                اگر (currency == \"EUR\") {\n                    برگشت \"€\" + amount;\n                } وگرنه {\n                    برگشت amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    ثابت تابع date(date) {\n        برگشت date;\n    }\n    \n    ثابت تابع phone(phone) {\n        // (555) 123-4567 formatı\n        برگشت \"(\" + phone + \")\";\n    }\n    \n    ثابت تابع number(num) {\n        // 1,234,567 formatı\n        برگشت num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nکلاس Validation {\n    ثابت تابع email(email) {\n        // Basit email درستlama\n        برگشت email.length > 5;\n    }\n    \n    ثابت تابع password(password) {\n        // Şifre en az 6 karakter olmalı\n        برگشت password.length >= 6;\n    }\n    \n    ثابت تابع price(price) {\n        برگشت price > 0;\n    }\n    \n    ثابت تابع phone(phone) {\n        // Telefon numarası درستlama\n        برگشت phone.length == 10;\n    }\n    \n    ثابت تابع required(value) {\n        برگشت value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nمتغیر APP_NAME = \"My Project\";\nمتغیر APP_VERSION = \"1.0.0\";\nمتغیر MAX_UPLOAD_SIZE = 10485760; // 10MB\nمتغیر SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nمتغیر STATUS_PENDING = \"pending\";\nمتغیر STATUS_APPROVED = \"approved\";\nمتغیر STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nمتغیر DB_HOST = \"localhost\";\nمتغیر DB_PORT = 5432;\nمتغیر DB_NAME = \"myproject_db\";\nمتغیر DB_USER = \"admin\";\nمتغیر DB_PASSWORD = \"secure_password\";\n\nتابع get_connection_string() {\n    برگشت \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nمتغیر API_BASE_URL = \"https://api.example.com\";\nمتغیر API_VERSION = \"v1\";\nمتغیر API_TIMEOUT = 30000;\n\nتابع get_api_url(endpoint) {\n    برگشت API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "fr": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" utiliser;\n\"src/models/product.hudhud\" utiliser;\n\"src/models/order.hudhud\" utiliser;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" utiliser;\n\"src/services/payment.hudhud\" utiliser;\n\"src/services/notification.hudhud\" utiliser;\n\n// Yardımcı classeları içe aktar\n\"src/utils/validation.hudhud\" utiliser;\n\"src/utils/formatting.hudhud\" utiliser;\n\nimprimer(\"============================================================\");\nimprimer(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nimprimer(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nvar authService = nouveau AuthService();\nvar paymentService = nouveau PaymentService();\nvar notificationService = nouveau NotificationService();\n\nimprimer(\"1️⃣  KULLANICI KAYDI\");\nimprimer(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni utiliserıcı oluştur\nvar newUser = nouveau User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nimprimer(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email vraila\nsi (Validation.email(newUser.email)) {\n    imprimer(\"✓ Email geçerli: \" + newUser.email);\n} sinon {\n    imprimer(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nvar authResult = authService.register(newUser);\nsi (authResult.success) {\n    imprimer(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nimprimer(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nimprimer(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nvar product = nouveau Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nimprimer(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat vraila\nsi (Validation.price(product.price)) {\n    imprimer(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nsi (product.inStock()) {\n    imprimer(\"✓ Ürün stokta mevcut\");\n} sinon {\n    imprimer(\"✗ Ürün stokta yok\");\n}\n\nimprimer(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nimprimer(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nvar order = nouveau Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nimprimer(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nimprimer(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nimprimer(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nvar paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nsi (paymentResult.success) {\n    imprimer(\"✓ \" + paymentResult.message);\n    imprimer(\"  İşlem No: \" + paymentResult.transactionId);\n    imprimer(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    imprimer(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    imprimer(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} sinon {\n    imprimer(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nimprimer(\"\\n============================================================\");\nimprimer(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nimprimer(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nimprimer(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" utiliser;\n\"../src/services/auth.hudhud\" utiliser;\n\nimprimer(\"============================================================\");\nimprimer(\"Auth Service Tests\");\nimprimer(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nvar authService = nouveau AuthService();\nimprimer(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nvar user = nouveau User(\"Test User\", \"test@example.com\", \"test123\");\nvar result1 = authService.register(user);\n\nsi (result1.success) {\n    imprimer(\"✓ Test 2 passed: Registration successful\");\n    imprimer(\"  User ID: \" + result1.userId);\n    imprimer(\"  Message: \" + result1.message);\n} sinon {\n    imprimer(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nvar loginResult = authService.login(\"test@example.com\", \"test123\");\n\nsi (loginResult.success) {\n    imprimer(\"✓ Test 3 passed: Login successful\");\n    imprimer(\"  Token: \" + loginResult.token);\n    imprimer(\"  Message: \" + loginResult.message);\n} sinon {\n    imprimer(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nvar verifyResult = authService.verifyToken(loginResult.token);\n\nsi (verifyResult.valid) {\n    imprimer(\"✓ Test 4 passed: Token verification successful\");\n    imprimer(\"  User ID: \" + verifyResult.userId);\n} sinon {\n    imprimer(\"✗ Test 4 failed: Token verification failed\");\n}\n\nimprimer(\"\\n============================================================\");\nimprimer(\"All Auth tests completed!\");\nimprimer(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" utiliser;\n\nimprimer(\"============================================================\");\nimprimer(\"User Model Tests\");\nimprimer(\"============================================================\\n\");\n\n// Test 1: User creation\nvar user = nouveau User(\"Test User\", \"test@example.com\", \"test123\");\n\nsi (user.name == \"Test User\") {\n    imprimer(\"✓ Test 1 passed: User creation\");\n} sinon {\n    imprimer(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nsi (user.email == \"test@example.com\") {\n    imprimer(\"✓ Test 2 passed: Email set correctly\");\n} sinon {\n    imprimer(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nsi (user.id > 0) {\n    imprimer(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} sinon {\n    imprimer(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nvar info = user.bilgi();\nsi (info.length > 0) {\n    imprimer(\"✓ Test 4 passed: bilgi() method works\");\n    imprimer(\"  Info: \" + info);\n} sinon {\n    imprimer(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nimprimer(\"\\n============================================================\");\nimprimer(\"All User tests completed!\");\nimprimer(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nclasse NotificationService {\n    fonction send(to, subject, message) {\n        imprimer(\"   📧 Email gönderildi:\");\n        imprimer(\"      Kime: \" + to);\n        imprimer(\"      Konu: \" + subject);\n        imprimer(\"      Mesaj: \" + message);\n        retourner vrai;\n    }\n    \n    fonction sendSms(phone, message) {\n        imprimer(\"   📱 SMS gönderildi:\");\n        imprimer(\"      Numara: \" + phone);\n        imprimer(\"      Mesaj: \" + message);\n        retourner vrai;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nclasse PaymentService {\n    fonction process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        var success = vrai; // Gerçekte API çağrısı yapılır\n        \n        si (success) {\n            retourner {\n                success: vrai,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } sinon {\n            retourner {\n                success: faux,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    fonction refund(transactionId) {\n        retourner {\n            success: vrai,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nclasse AuthService {\n    constructeur() {\n        soi.userCount = 0;\n    }\n    \n    fonction register(user) {\n        soi.userCount = soi.userCount + 1;\n        retourner {\n            success: vrai,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    fonction login(email, password) {\n        // Basitleştirilmiş login\n        retourner {\n            success: vrai,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    fonction logout(token) {\n        retourner { success: vrai };\n    }\n    \n    fonction verifyToken(token) {\n        retourner { valid: vrai, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nclasse User {\n    constructeur(name, email, password) {\n        soi.id = Math.floor(Math.random() * 10000);\n        soi.name = name;\n        soi.email = email;\n        soi.password = password;\n        soi.createdAt = \"2024-03-07\";\n    }\n    \n    fonction bilgi() {\n        retourner \"User #\" + soi.id + \": \" + soi.name + \" (\" + soi.email + \")\";\n    }\n    \n    fonction getId() {\n        retourner soi.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nclasse Product {\n    constructeur(name, price, stock, category) {\n        soi.id = Math.floor(Math.random() * 10000);\n        soi.name = name;\n        soi.price = price;\n        soi.stock = stock;\n        soi.category = category;\n    }\n    \n    fonction bilgi() {\n        retourner soi.name + \" - \" + soi.price + \" TL (Stok: \" + soi.stock + \", Kategori: \" + soi.category + \")\";\n    }\n    \n    fonction inStock() {\n        retourner soi.stock > 0;\n    }\n    \n    fonction getId() {\n        retourner soi.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nclasse Order {\n    constructeur(userId, productId, quantity, totalPrice) {\n        soi.id = Math.floor(Math.random() * 10000);\n        soi.userId = userId;\n        soi.productId = productId;\n        soi.quantity = quantity;\n        soi.totalPrice = totalPrice;\n        soi.status = \"pending\";\n        soi.createdAt = \"2024-03-07\";\n    }\n    \n    fonction bilgi() {\n        retourner \"Sipariş #\" + soi.id + \" - Kullanıcı: \" + soi.userId + \", Ürün: \" + soi.productId + \", Adet: \" + soi.quantity + \", Toplam: \" + soi.totalPrice + \" TL, Durum: \" + soi.status;\n    }\n    \n    fonction confirm() {\n        soi.status = \"confirmed\";\n    }\n    \n    fonction getId() {\n        retourner soi.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfonction random_string(length) {\n    retourner \"random_\" + length;\n}\n\nfonction sleep(ms) {\n    // Bekleme simülasyonu\n    imprimer(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfonction log(message) {\n    imprimer(\"[LOG] \" + message);\n}\n\nfonction error(message) {\n    imprimer(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nclasse Formatting {\n    statique fonction currency(amount, currency) {\n        si (currency == \"TRY\") {\n            retourner amount + \" ₺\";\n        } sinon {\n            si (currency == \"USD\") {\n                retourner \"$\" + amount;\n            } sinon {\n                si (currency == \"EUR\") {\n                    retourner \"€\" + amount;\n                } sinon {\n                    retourner amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    statique fonction date(date) {\n        retourner date;\n    }\n    \n    statique fonction phone(phone) {\n        // (555) 123-4567 formatı\n        retourner \"(\" + phone + \")\";\n    }\n    \n    statique fonction number(num) {\n        // 1,234,567 formatı\n        retourner num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nclasse Validation {\n    statique fonction email(email) {\n        // Basit email vrailama\n        retourner email.length > 5;\n    }\n    \n    statique fonction password(password) {\n        // Şifre en az 6 karakter olmalı\n        retourner password.length >= 6;\n    }\n    \n    statique fonction price(price) {\n        retourner price > 0;\n    }\n    \n    statique fonction phone(phone) {\n        // Telefon numarası vrailama\n        retourner phone.length == 10;\n    }\n    \n    statique fonction required(value) {\n        retourner value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nvar APP_NAME = \"My Project\";\nvar APP_VERSION = \"1.0.0\";\nvar MAX_UPLOAD_SIZE = 10485760; // 10MB\nvar SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nvar STATUS_PENDING = \"pending\";\nvar STATUS_APPROVED = \"approved\";\nvar STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nvar DB_HOST = \"localhost\";\nvar DB_PORT = 5432;\nvar DB_NAME = \"myproject_db\";\nvar DB_USER = \"admin\";\nvar DB_PASSWORD = \"secure_password\";\n\nfonction get_connection_string() {\n    retourner \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nvar API_BASE_URL = \"https://api.example.com\";\nvar API_VERSION = \"v1\";\nvar API_TIMEOUT = 30000;\n\nfonction get_api_url(endpoint) {\n    retourner API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "hr": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" koristi;\n\"src/models/product.hudhud\" koristi;\n\"src/models/order.hudhud\" koristi;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" koristi;\n\"src/services/payment.hudhud\" koristi;\n\"src/services/notification.hudhud\" koristi;\n\n// Yardımcı klasaları içe aktar\n\"src/utils/validation.hudhud\" koristi;\n\"src/utils/formatting.hudhud\" koristi;\n\nispiši(\"============================================================\");\nispiši(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nispiši(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nvarijabla authService = novi AuthService();\nvarijabla paymentService = novi PaymentService();\nvarijabla notificationService = novi NotificationService();\n\nispiši(\"1️⃣  KULLANICI KAYDI\");\nispiši(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni koristiıcı oluştur\nvarijabla newUser = novi User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nispiši(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email istinala\nako (Validation.email(newUser.email)) {\n    ispiši(\"✓ Email geçerli: \" + newUser.email);\n} inače {\n    ispiši(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nvarijabla authResult = authService.register(newUser);\nako (authResult.success) {\n    ispiši(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nispiši(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nispiši(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nvarijabla product = novi Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nispiši(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat istinala\nako (Validation.price(product.price)) {\n    ispiši(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nako (product.inStock()) {\n    ispiši(\"✓ Ürün stokta mevcut\");\n} inače {\n    ispiši(\"✗ Ürün stokta yok\");\n}\n\nispiši(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nispiši(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nvarijabla order = novi Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nispiši(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nispiši(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nispiši(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nvarijabla paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nako (paymentResult.success) {\n    ispiši(\"✓ \" + paymentResult.message);\n    ispiši(\"  İşlem No: \" + paymentResult.transactionId);\n    ispiši(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    ispiši(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    ispiši(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} inače {\n    ispiši(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nispiši(\"\\n============================================================\");\nispiši(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nispiši(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nispiši(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" koristi;\n\"../src/services/auth.hudhud\" koristi;\n\nispiši(\"============================================================\");\nispiši(\"Auth Service Tests\");\nispiši(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nvarijabla authService = novi AuthService();\nispiši(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nvarijabla user = novi User(\"Test User\", \"test@example.com\", \"test123\");\nvarijabla result1 = authService.register(user);\n\nako (result1.success) {\n    ispiši(\"✓ Test 2 passed: Registration successful\");\n    ispiši(\"  User ID: \" + result1.userId);\n    ispiši(\"  Message: \" + result1.message);\n} inače {\n    ispiši(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nvarijabla loginResult = authService.login(\"test@example.com\", \"test123\");\n\nako (loginResult.success) {\n    ispiši(\"✓ Test 3 passed: Login successful\");\n    ispiši(\"  Token: \" + loginResult.token);\n    ispiši(\"  Message: \" + loginResult.message);\n} inače {\n    ispiši(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nvarijabla verifyResult = authService.verifyToken(loginResult.token);\n\nako (verifyResult.valid) {\n    ispiši(\"✓ Test 4 passed: Token verification successful\");\n    ispiši(\"  User ID: \" + verifyResult.userId);\n} inače {\n    ispiši(\"✗ Test 4 failed: Token verification failed\");\n}\n\nispiši(\"\\n============================================================\");\nispiši(\"All Auth tests completed!\");\nispiši(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" koristi;\n\nispiši(\"============================================================\");\nispiši(\"User Model Tests\");\nispiši(\"============================================================\\n\");\n\n// Test 1: User creation\nvarijabla user = novi User(\"Test User\", \"test@example.com\", \"test123\");\n\nako (user.name == \"Test User\") {\n    ispiši(\"✓ Test 1 passed: User creation\");\n} inače {\n    ispiši(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nako (user.email == \"test@example.com\") {\n    ispiši(\"✓ Test 2 passed: Email set correctly\");\n} inače {\n    ispiši(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nako (user.id > 0) {\n    ispiši(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} inače {\n    ispiši(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nvarijabla info = user.bilgi();\nako (info.length > 0) {\n    ispiši(\"✓ Test 4 passed: bilgi() method works\");\n    ispiši(\"  Info: \" + info);\n} inače {\n    ispiši(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nispiši(\"\\n============================================================\");\nispiši(\"All User tests completed!\");\nispiši(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nklasa NotificationService {\n    funkcija send(to, subject, message) {\n        ispiši(\"   📧 Email gönderildi:\");\n        ispiši(\"      Kime: \" + to);\n        ispiši(\"      Konu: \" + subject);\n        ispiši(\"      Mesaj: \" + message);\n        vrati istina;\n    }\n    \n    funkcija sendSms(phone, message) {\n        ispiši(\"   📱 SMS gönderildi:\");\n        ispiši(\"      Numara: \" + phone);\n        ispiši(\"      Mesaj: \" + message);\n        vrati istina;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nklasa PaymentService {\n    funkcija process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        varijabla success = istina; // Gerçekte API çağrısı yapılır\n        \n        ako (success) {\n            vrati {\n                success: istina,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } inače {\n            vrati {\n                success: laž,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    funkcija refund(transactionId) {\n        vrati {\n            success: istina,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nklasa AuthService {\n    konstruktor() {\n        vlastiti.userCount = 0;\n    }\n    \n    funkcija register(user) {\n        vlastiti.userCount = vlastiti.userCount + 1;\n        vrati {\n            success: istina,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    funkcija login(email, password) {\n        // Basitleştirilmiş login\n        vrati {\n            success: istina,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    funkcija logout(token) {\n        vrati { success: istina };\n    }\n    \n    funkcija verifyToken(token) {\n        vrati { valid: istina, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nklasa User {\n    konstruktor(name, email, password) {\n        vlastiti.id = Math.floor(Math.random() * 10000);\n        vlastiti.name = name;\n        vlastiti.email = email;\n        vlastiti.password = password;\n        vlastiti.createdAt = \"2024-03-07\";\n    }\n    \n    funkcija bilgi() {\n        vrati \"User #\" + vlastiti.id + \": \" + vlastiti.name + \" (\" + vlastiti.email + \")\";\n    }\n    \n    funkcija getId() {\n        vrati vlastiti.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nklasa Product {\n    konstruktor(name, price, stock, category) {\n        vlastiti.id = Math.floor(Math.random() * 10000);\n        vlastiti.name = name;\n        vlastiti.price = price;\n        vlastiti.stock = stock;\n        vlastiti.category = category;\n    }\n    \n    funkcija bilgi() {\n        vrati vlastiti.name + \" - \" + vlastiti.price + \" TL (Stok: \" + vlastiti.stock + \", Kategori: \" + vlastiti.category + \")\";\n    }\n    \n    funkcija inStock() {\n        vrati vlastiti.stock > 0;\n    }\n    \n    funkcija getId() {\n        vrati vlastiti.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nklasa Order {\n    konstruktor(userId, productId, quantity, totalPrice) {\n        vlastiti.id = Math.floor(Math.random() * 10000);\n        vlastiti.userId = userId;\n        vlastiti.productId = productId;\n        vlastiti.quantity = quantity;\n        vlastiti.totalPrice = totalPrice;\n        vlastiti.status = \"pending\";\n        vlastiti.createdAt = \"2024-03-07\";\n    }\n    \n    funkcija bilgi() {\n        vrati \"Sipariş #\" + vlastiti.id + \" - Kullanıcı: \" + vlastiti.userId + \", Ürün: \" + vlastiti.productId + \", Adet: \" + vlastiti.quantity + \", Toplam: \" + vlastiti.totalPrice + \" TL, Durum: \" + vlastiti.status;\n    }\n    \n    funkcija confirm() {\n        vlastiti.status = \"confirmed\";\n    }\n    \n    funkcija getId() {\n        vrati vlastiti.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfunkcija random_string(length) {\n    vrati \"random_\" + length;\n}\n\nfunkcija sleep(ms) {\n    // Bekleme simülasyonu\n    ispiši(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfunkcija log(message) {\n    ispiši(\"[LOG] \" + message);\n}\n\nfunkcija error(message) {\n    ispiši(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nklasa Formatting {\n    statički funkcija currency(amount, currency) {\n        ako (currency == \"TRY\") {\n            vrati amount + \" ₺\";\n        } inače {\n            ako (currency == \"USD\") {\n                vrati \"$\" + amount;\n            } inače {\n                ako (currency == \"EUR\") {\n                    vrati \"€\" + amount;\n                } inače {\n                    vrati amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    statički funkcija date(date) {\n        vrati date;\n    }\n    \n    statički funkcija phone(phone) {\n        // (555) 123-4567 formatı\n        vrati \"(\" + phone + \")\";\n    }\n    \n    statički funkcija number(num) {\n        // 1,234,567 formatı\n        vrati num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nklasa Validation {\n    statički funkcija email(email) {\n        // Basit email istinalama\n        vrati email.length > 5;\n    }\n    \n    statički funkcija password(password) {\n        // Şifre en az 6 karakter olmalı\n        vrati password.length >= 6;\n    }\n    \n    statički funkcija price(price) {\n        vrati price > 0;\n    }\n    \n    statički funkcija phone(phone) {\n        // Telefon numarası istinalama\n        vrati phone.length == 10;\n    }\n    \n    statički funkcija required(value) {\n        vrati value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nvarijabla APP_NAME = \"My Project\";\nvarijabla APP_VERSION = \"1.0.0\";\nvarijabla MAX_UPLOAD_SIZE = 10485760; // 10MB\nvarijabla SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nvarijabla STATUS_PENDING = \"pending\";\nvarijabla STATUS_APPROVED = \"approved\";\nvarijabla STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nvarijabla DB_HOST = \"localhost\";\nvarijabla DB_PORT = 5432;\nvarijabla DB_NAME = \"myproject_db\";\nvarijabla DB_USER = \"admin\";\nvarijabla DB_PASSWORD = \"secure_password\";\n\nfunkcija get_connection_string() {\n    vrati \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nvarijabla API_BASE_URL = \"https://api.example.com\";\nvarijabla API_VERSION = \"v1\";\nvarijabla API_TIMEOUT = 30000;\n\nfunkcija get_api_url(endpoint) {\n    vrati API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "id": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" gunakan;\n\"src/models/product.hudhud\" gunakan;\n\"src/models/order.hudhud\" gunakan;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" gunakan;\n\"src/services/payment.hudhud\" gunakan;\n\"src/services/notification.hudhud\" gunakan;\n\n// Yardımcı kelasları içe aktar\n\"src/utils/validation.hudhud\" gunakan;\n\"src/utils/formatting.hudhud\" gunakan;\n\ncetak(\"============================================================\");\ncetak(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\ncetak(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nvar authService = baru AuthService();\nvar paymentService = baru PaymentService();\nvar notificationService = baru NotificationService();\n\ncetak(\"1️⃣  KULLANICI KAYDI\");\ncetak(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni gunakanıcı oluştur\nvar newUser = baru User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\ncetak(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email benarla\njika (Validation.email(newUser.email)) {\n    cetak(\"✓ Email geçerli: \" + newUser.email);\n} kalau_tidak {\n    cetak(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nvar authResult = authService.register(newUser);\njika (authResult.success) {\n    cetak(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\ncetak(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\ncetak(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nvar product = baru Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\ncetak(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat benarla\njika (Validation.price(product.price)) {\n    cetak(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\njika (product.inStock()) {\n    cetak(\"✓ Ürün stokta mevcut\");\n} kalau_tidak {\n    cetak(\"✗ Ürün stokta yok\");\n}\n\ncetak(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\ncetak(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nvar order = baru Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\ncetak(\"Sipariş oluşturuldu: \" + order.bilgi());\n\ncetak(\"\\n4️⃣  ÖDEME İŞLEMİ\");\ncetak(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nvar paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\njika (paymentResult.success) {\n    cetak(\"✓ \" + paymentResult.message);\n    cetak(\"  İşlem No: \" + paymentResult.transactionId);\n    cetak(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    cetak(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    cetak(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} kalau_tidak {\n    cetak(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\ncetak(\"\\n============================================================\");\ncetak(\"✓ E-Ticaret sistemi demo tamamlandı!\");\ncetak(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\ncetak(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" gunakan;\n\"../src/services/auth.hudhud\" gunakan;\n\ncetak(\"============================================================\");\ncetak(\"Auth Service Tests\");\ncetak(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nvar authService = baru AuthService();\ncetak(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nvar user = baru User(\"Test User\", \"test@example.com\", \"test123\");\nvar result1 = authService.register(user);\n\njika (result1.success) {\n    cetak(\"✓ Test 2 passed: Registration successful\");\n    cetak(\"  User ID: \" + result1.userId);\n    cetak(\"  Message: \" + result1.message);\n} kalau_tidak {\n    cetak(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nvar loginResult = authService.login(\"test@example.com\", \"test123\");\n\njika (loginResult.success) {\n    cetak(\"✓ Test 3 passed: Login successful\");\n    cetak(\"  Token: \" + loginResult.token);\n    cetak(\"  Message: \" + loginResult.message);\n} kalau_tidak {\n    cetak(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nvar verifyResult = authService.verifyToken(loginResult.token);\n\njika (verifyResult.valid) {\n    cetak(\"✓ Test 4 passed: Token verification successful\");\n    cetak(\"  User ID: \" + verifyResult.userId);\n} kalau_tidak {\n    cetak(\"✗ Test 4 failed: Token verification failed\");\n}\n\ncetak(\"\\n============================================================\");\ncetak(\"All Auth tests completed!\");\ncetak(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" gunakan;\n\ncetak(\"============================================================\");\ncetak(\"User Model Tests\");\ncetak(\"============================================================\\n\");\n\n// Test 1: User creation\nvar user = baru User(\"Test User\", \"test@example.com\", \"test123\");\n\njika (user.name == \"Test User\") {\n    cetak(\"✓ Test 1 passed: User creation\");\n} kalau_tidak {\n    cetak(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\njika (user.email == \"test@example.com\") {\n    cetak(\"✓ Test 2 passed: Email set correctly\");\n} kalau_tidak {\n    cetak(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\njika (user.id > 0) {\n    cetak(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} kalau_tidak {\n    cetak(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nvar info = user.bilgi();\njika (info.length > 0) {\n    cetak(\"✓ Test 4 passed: bilgi() method works\");\n    cetak(\"  Info: \" + info);\n} kalau_tidak {\n    cetak(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\ncetak(\"\\n============================================================\");\ncetak(\"All User tests completed!\");\ncetak(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nkelas NotificationService {\n    fungsi send(to, subject, message) {\n        cetak(\"   📧 Email gönderildi:\");\n        cetak(\"      Kime: \" + to);\n        cetak(\"      Konu: \" + subject);\n        cetak(\"      Mesaj: \" + message);\n        kembali benar;\n    }\n    \n    fungsi sendSms(phone, message) {\n        cetak(\"   📱 SMS gönderildi:\");\n        cetak(\"      Numara: \" + phone);\n        cetak(\"      Mesaj: \" + message);\n        kembali benar;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nkelas PaymentService {\n    fungsi process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        var success = benar; // Gerçekte API çağrısı yapılır\n        \n        jika (success) {\n            kembali {\n                success: benar,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } kalau_tidak {\n            kembali {\n                success: salah,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    fungsi refund(transactionId) {\n        kembali {\n            success: benar,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nkelas AuthService {\n    konstruktor() {\n        sendiri.userCount = 0;\n    }\n    \n    fungsi register(user) {\n        sendiri.userCount = sendiri.userCount + 1;\n        kembali {\n            success: benar,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    fungsi login(email, password) {\n        // Basitleştirilmiş login\n        kembali {\n            success: benar,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    fungsi logout(token) {\n        kembali { success: benar };\n    }\n    \n    fungsi verifyToken(token) {\n        kembali { valid: benar, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nkelas User {\n    konstruktor(name, email, password) {\n        sendiri.id = Math.floor(Math.random() * 10000);\n        sendiri.name = name;\n        sendiri.email = email;\n        sendiri.password = password;\n        sendiri.createdAt = \"2024-03-07\";\n    }\n    \n    fungsi bilgi() {\n        kembali \"User #\" + sendiri.id + \": \" + sendiri.name + \" (\" + sendiri.email + \")\";\n    }\n    \n    fungsi getId() {\n        kembali sendiri.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nkelas Product {\n    konstruktor(name, price, stock, category) {\n        sendiri.id = Math.floor(Math.random() * 10000);\n        sendiri.name = name;\n        sendiri.price = price;\n        sendiri.stock = stock;\n        sendiri.category = category;\n    }\n    \n    fungsi bilgi() {\n        kembali sendiri.name + \" - \" + sendiri.price + \" TL (Stok: \" + sendiri.stock + \", Kategori: \" + sendiri.category + \")\";\n    }\n    \n    fungsi inStock() {\n        kembali sendiri.stock > 0;\n    }\n    \n    fungsi getId() {\n        kembali sendiri.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nkelas Order {\n    konstruktor(userId, productId, quantity, totalPrice) {\n        sendiri.id = Math.floor(Math.random() * 10000);\n        sendiri.userId = userId;\n        sendiri.productId = productId;\n        sendiri.quantity = quantity;\n        sendiri.totalPrice = totalPrice;\n        sendiri.status = \"pending\";\n        sendiri.createdAt = \"2024-03-07\";\n    }\n    \n    fungsi bilgi() {\n        kembali \"Sipariş #\" + sendiri.id + \" - Kullanıcı: \" + sendiri.userId + \", Ürün: \" + sendiri.productId + \", Adet: \" + sendiri.quantity + \", Toplam: \" + sendiri.totalPrice + \" TL, Durum: \" + sendiri.status;\n    }\n    \n    fungsi confirm() {\n        sendiri.status = \"confirmed\";\n    }\n    \n    fungsi getId() {\n        kembali sendiri.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfungsi random_string(length) {\n    kembali \"random_\" + length;\n}\n\nfungsi sleep(ms) {\n    // Bekleme simülasyonu\n    cetak(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfungsi log(message) {\n    cetak(\"[LOG] \" + message);\n}\n\nfungsi error(message) {\n    cetak(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nkelas Formatting {\n    statis fungsi currency(amount, currency) {\n        jika (currency == \"TRY\") {\n            kembali amount + \" ₺\";\n        } kalau_tidak {\n            jika (currency == \"USD\") {\n                kembali \"$\" + amount;\n            } kalau_tidak {\n                jika (currency == \"EUR\") {\n                    kembali \"€\" + amount;\n                } kalau_tidak {\n                    kembali amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    statis fungsi date(date) {\n        kembali date;\n    }\n    \n    statis fungsi phone(phone) {\n        // (555) 123-4567 formatı\n        kembali \"(\" + phone + \")\";\n    }\n    \n    statis fungsi number(num) {\n        // 1,234,567 formatı\n        kembali num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nkelas Validation {\n    statis fungsi email(email) {\n        // Basit email benarlama\n        kembali email.length > 5;\n    }\n    \n    statis fungsi password(password) {\n        // Şifre en az 6 karakter olmalı\n        kembali password.length >= 6;\n    }\n    \n    statis fungsi price(price) {\n        kembali price > 0;\n    }\n    \n    statis fungsi phone(phone) {\n        // Telefon numarası benarlama\n        kembali phone.length == 10;\n    }\n    \n    statis fungsi required(value) {\n        kembali value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nvar APP_NAME = \"My Project\";\nvar APP_VERSION = \"1.0.0\";\nvar MAX_UPLOAD_SIZE = 10485760; // 10MB\nvar SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nvar STATUS_PENDING = \"pending\";\nvar STATUS_APPROVED = \"approved\";\nvar STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nvar DB_HOST = \"localhost\";\nvar DB_PORT = 5432;\nvar DB_NAME = \"myproject_db\";\nvar DB_USER = \"admin\";\nvar DB_PASSWORD = \"secure_password\";\n\nfungsi get_connection_string() {\n    kembali \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nvar API_BASE_URL = \"https://api.example.com\";\nvar API_VERSION = \"v1\";\nvar API_TIMEOUT = 30000;\n\nfungsi get_api_url(endpoint) {\n    kembali API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "it": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" usare;\n\"src/models/product.hudhud\" usare;\n\"src/models/order.hudhud\" usare;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" usare;\n\"src/services/payment.hudhud\" usare;\n\"src/services/notification.hudhud\" usare;\n\n// Yardımcı classeları içe aktar\n\"src/utils/validation.hudhud\" usare;\n\"src/utils/formatting.hudhud\" usare;\n\nstampare(\"============================================================\");\nstampare(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nstampare(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nvar authService = nuovo AuthService();\nvar paymentService = nuovo PaymentService();\nvar notificationService = nuovo NotificationService();\n\nstampare(\"1️⃣  KULLANICI KAYDI\");\nstampare(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni usareıcı oluştur\nvar newUser = nuovo User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nstampare(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email verola\nse (Validation.email(newUser.email)) {\n    stampare(\"✓ Email geçerli: \" + newUser.email);\n} altrimenti {\n    stampare(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nvar authResult = authService.register(newUser);\nse (authResult.success) {\n    stampare(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nstampare(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nstampare(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nvar product = nuovo Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nstampare(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat verola\nse (Validation.price(product.price)) {\n    stampare(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nse (product.inStock()) {\n    stampare(\"✓ Ürün stokta mevcut\");\n} altrimenti {\n    stampare(\"✗ Ürün stokta yok\");\n}\n\nstampare(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nstampare(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nvar order = nuovo Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nstampare(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nstampare(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nstampare(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nvar paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nse (paymentResult.success) {\n    stampare(\"✓ \" + paymentResult.message);\n    stampare(\"  İşlem No: \" + paymentResult.transactionId);\n    stampare(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    stampare(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    stampare(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} altrimenti {\n    stampare(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nstampare(\"\\n============================================================\");\nstampare(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nstampare(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nstampare(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" usare;\n\"../src/services/auth.hudhud\" usare;\n\nstampare(\"============================================================\");\nstampare(\"Auth Service Tests\");\nstampare(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nvar authService = nuovo AuthService();\nstampare(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nvar user = nuovo User(\"Test User\", \"test@example.com\", \"test123\");\nvar result1 = authService.register(user);\n\nse (result1.success) {\n    stampare(\"✓ Test 2 passed: Registration successful\");\n    stampare(\"  User ID: \" + result1.userId);\n    stampare(\"  Message: \" + result1.message);\n} altrimenti {\n    stampare(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nvar loginResult = authService.login(\"test@example.com\", \"test123\");\n\nse (loginResult.success) {\n    stampare(\"✓ Test 3 passed: Login successful\");\n    stampare(\"  Token: \" + loginResult.token);\n    stampare(\"  Message: \" + loginResult.message);\n} altrimenti {\n    stampare(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nvar verifyResult = authService.verifyToken(loginResult.token);\n\nse (verifyResult.valid) {\n    stampare(\"✓ Test 4 passed: Token verification successful\");\n    stampare(\"  User ID: \" + verifyResult.userId);\n} altrimenti {\n    stampare(\"✗ Test 4 failed: Token verification failed\");\n}\n\nstampare(\"\\n============================================================\");\nstampare(\"All Auth tests completed!\");\nstampare(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" usare;\n\nstampare(\"============================================================\");\nstampare(\"User Model Tests\");\nstampare(\"============================================================\\n\");\n\n// Test 1: User creation\nvar user = nuovo User(\"Test User\", \"test@example.com\", \"test123\");\n\nse (user.name == \"Test User\") {\n    stampare(\"✓ Test 1 passed: User creation\");\n} altrimenti {\n    stampare(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nse (user.email == \"test@example.com\") {\n    stampare(\"✓ Test 2 passed: Email set correctly\");\n} altrimenti {\n    stampare(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nse (user.id > 0) {\n    stampare(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} altrimenti {\n    stampare(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nvar info = user.bilgi();\nse (info.length > 0) {\n    stampare(\"✓ Test 4 passed: bilgi() method works\");\n    stampare(\"  Info: \" + info);\n} altrimenti {\n    stampare(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nstampare(\"\\n============================================================\");\nstampare(\"All User tests completed!\");\nstampare(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nclasse NotificationService {\n    funzione send(to, subject, message) {\n        stampare(\"   📧 Email gönderildi:\");\n        stampare(\"      Kime: \" + to);\n        stampare(\"      Konu: \" + subject);\n        stampare(\"      Mesaj: \" + message);\n        ritorno vero;\n    }\n    \n    funzione sendSms(phone, message) {\n        stampare(\"   📱 SMS gönderildi:\");\n        stampare(\"      Numara: \" + phone);\n        stampare(\"      Mesaj: \" + message);\n        ritorno vero;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nclasse PaymentService {\n    funzione process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        var success = vero; // Gerçekte API çağrısı yapılır\n        \n        se (success) {\n            ritorno {\n                success: vero,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } altrimenti {\n            ritorno {\n                success: falso,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    funzione refund(transactionId) {\n        ritorno {\n            success: vero,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nclasse AuthService {\n    costruttore() {\n        sé.userCount = 0;\n    }\n    \n    funzione register(user) {\n        sé.userCount = sé.userCount + 1;\n        ritorno {\n            success: vero,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    funzione login(email, password) {\n        // Basitleştirilmiş login\n        ritorno {\n            success: vero,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    funzione logout(token) {\n        ritorno { success: vero };\n    }\n    \n    funzione verifyToken(token) {\n        ritorno { valid: vero, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nclasse User {\n    costruttore(name, email, password) {\n        sé.id = Math.floor(Math.random() * 10000);\n        sé.name = name;\n        sé.email = email;\n        sé.password = password;\n        sé.createdAt = \"2024-03-07\";\n    }\n    \n    funzione bilgi() {\n        ritorno \"User #\" + sé.id + \": \" + sé.name + \" (\" + sé.email + \")\";\n    }\n    \n    funzione getId() {\n        ritorno sé.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nclasse Product {\n    costruttore(name, price, stock, category) {\n        sé.id = Math.floor(Math.random() * 10000);\n        sé.name = name;\n        sé.price = price;\n        sé.stock = stock;\n        sé.category = category;\n    }\n    \n    funzione bilgi() {\n        ritorno sé.name + \" - \" + sé.price + \" TL (Stok: \" + sé.stock + \", Kategori: \" + sé.category + \")\";\n    }\n    \n    funzione inStock() {\n        ritorno sé.stock > 0;\n    }\n    \n    funzione getId() {\n        ritorno sé.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nclasse Order {\n    costruttore(userId, productId, quantity, totalPrice) {\n        sé.id = Math.floor(Math.random() * 10000);\n        sé.userId = userId;\n        sé.productId = productId;\n        sé.quantity = quantity;\n        sé.totalPrice = totalPrice;\n        sé.status = \"pending\";\n        sé.createdAt = \"2024-03-07\";\n    }\n    \n    funzione bilgi() {\n        ritorno \"Sipariş #\" + sé.id + \" - Kullanıcı: \" + sé.userId + \", Ürün: \" + sé.productId + \", Adet: \" + sé.quantity + \", Toplam: \" + sé.totalPrice + \" TL, Durum: \" + sé.status;\n    }\n    \n    funzione confirm() {\n        sé.status = \"confirmed\";\n    }\n    \n    funzione getId() {\n        ritorno sé.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfunzione random_string(length) {\n    ritorno \"random_\" + length;\n}\n\nfunzione sleep(ms) {\n    // Bekleme simülasyonu\n    stampare(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfunzione log(message) {\n    stampare(\"[LOG] \" + message);\n}\n\nfunzione error(message) {\n    stampare(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nclasse Formatting {\n    statico funzione currency(amount, currency) {\n        se (currency == \"TRY\") {\n            ritorno amount + \" ₺\";\n        } altrimenti {\n            se (currency == \"USD\") {\n                ritorno \"$\" + amount;\n            } altrimenti {\n                se (currency == \"EUR\") {\n                    ritorno \"€\" + amount;\n                } altrimenti {\n                    ritorno amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    statico funzione date(date) {\n        ritorno date;\n    }\n    \n    statico funzione phone(phone) {\n        // (555) 123-4567 formatı\n        ritorno \"(\" + phone + \")\";\n    }\n    \n    statico funzione number(num) {\n        // 1,234,567 formatı\n        ritorno num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nclasse Validation {\n    statico funzione email(email) {\n        // Basit email verolama\n        ritorno email.length > 5;\n    }\n    \n    statico funzione password(password) {\n        // Şifre en az 6 karakter olmalı\n        ritorno password.length >= 6;\n    }\n    \n    statico funzione price(price) {\n        ritorno price > 0;\n    }\n    \n    statico funzione phone(phone) {\n        // Telefon numarası verolama\n        ritorno phone.length == 10;\n    }\n    \n    statico funzione required(value) {\n        ritorno value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nvar APP_NAME = \"My Project\";\nvar APP_VERSION = \"1.0.0\";\nvar MAX_UPLOAD_SIZE = 10485760; // 10MB\nvar SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nvar STATUS_PENDING = \"pending\";\nvar STATUS_APPROVED = \"approved\";\nvar STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nvar DB_HOST = \"localhost\";\nvar DB_PORT = 5432;\nvar DB_NAME = \"myproject_db\";\nvar DB_USER = \"admin\";\nvar DB_PASSWORD = \"secure_password\";\n\nfunzione get_connection_string() {\n    ritorno \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nvar API_BASE_URL = \"https://api.example.com\";\nvar API_VERSION = \"v1\";\nvar API_TIMEOUT = 30000;\n\nfunzione get_api_url(endpoint) {\n    ritorno API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "ku": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" bikar_bine;\n\"src/models/product.hudhud\" bikar_bine;\n\"src/models/order.hudhud\" bikar_bine;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" bikar_bine;\n\"src/services/payment.hudhud\" bikar_bine;\n\"src/services/notification.hudhud\" bikar_bine;\n\n// Yardımcı çinları içe aktar\n\"src/utils/validation.hudhud\" bikar_bine;\n\"src/utils/formatting.hudhud\" bikar_bine;\n\nçap_bike(\"============================================================\");\nçap_bike(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nçap_bike(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nguherbar authService = nu AuthService();\nguherbar paymentService = nu PaymentService();\nguherbar notificationService = nu NotificationService();\n\nçap_bike(\"1️⃣  KULLANICI KAYDI\");\nçap_bike(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni bikar_bineıcı oluştur\nguherbar newUser = nu User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nçap_bike(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email rastla\neger (Validation.email(newUser.email)) {\n    çap_bike(\"✓ Email geçerli: \" + newUser.email);\n} weki_din {\n    çap_bike(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nguherbar authResult = authService.register(newUser);\neger (authResult.success) {\n    çap_bike(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nçap_bike(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nçap_bike(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nguherbar product = nu Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nçap_bike(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat rastla\neger (Validation.price(product.price)) {\n    çap_bike(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\neger (product.inStock()) {\n    çap_bike(\"✓ Ürün stokta mevcut\");\n} weki_din {\n    çap_bike(\"✗ Ürün stokta yok\");\n}\n\nçap_bike(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nçap_bike(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nguherbar order = nu Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nçap_bike(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nçap_bike(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nçap_bike(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nguherbar paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\neger (paymentResult.success) {\n    çap_bike(\"✓ \" + paymentResult.message);\n    çap_bike(\"  İşlem No: \" + paymentResult.transactionId);\n    çap_bike(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    çap_bike(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    çap_bike(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} weki_din {\n    çap_bike(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nçap_bike(\"\\n============================================================\");\nçap_bike(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nçap_bike(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nçap_bike(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" bikar_bine;\n\"../src/services/auth.hudhud\" bikar_bine;\n\nçap_bike(\"============================================================\");\nçap_bike(\"Auth Service Tests\");\nçap_bike(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nguherbar authService = nu AuthService();\nçap_bike(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nguherbar user = nu User(\"Test User\", \"test@example.com\", \"test123\");\nguherbar result1 = authService.register(user);\n\neger (result1.success) {\n    çap_bike(\"✓ Test 2 passed: Registration successful\");\n    çap_bike(\"  User ID: \" + result1.userId);\n    çap_bike(\"  Message: \" + result1.message);\n} weki_din {\n    çap_bike(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nguherbar loginResult = authService.login(\"test@example.com\", \"test123\");\n\neger (loginResult.success) {\n    çap_bike(\"✓ Test 3 passed: Login successful\");\n    çap_bike(\"  Token: \" + loginResult.token);\n    çap_bike(\"  Message: \" + loginResult.message);\n} weki_din {\n    çap_bike(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nguherbar verifyResult = authService.verifyToken(loginResult.token);\n\neger (verifyResult.valid) {\n    çap_bike(\"✓ Test 4 passed: Token verification successful\");\n    çap_bike(\"  User ID: \" + verifyResult.userId);\n} weki_din {\n    çap_bike(\"✗ Test 4 failed: Token verification failed\");\n}\n\nçap_bike(\"\\n============================================================\");\nçap_bike(\"All Auth tests completed!\");\nçap_bike(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" bikar_bine;\n\nçap_bike(\"============================================================\");\nçap_bike(\"User Model Tests\");\nçap_bike(\"============================================================\\n\");\n\n// Test 1: User creation\nguherbar user = nu User(\"Test User\", \"test@example.com\", \"test123\");\n\neger (user.name == \"Test User\") {\n    çap_bike(\"✓ Test 1 passed: User creation\");\n} weki_din {\n    çap_bike(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\neger (user.email == \"test@example.com\") {\n    çap_bike(\"✓ Test 2 passed: Email set correctly\");\n} weki_din {\n    çap_bike(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\neger (user.id > 0) {\n    çap_bike(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} weki_din {\n    çap_bike(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nguherbar info = user.bilgi();\neger (info.length > 0) {\n    çap_bike(\"✓ Test 4 passed: bilgi() method works\");\n    çap_bike(\"  Info: \" + info);\n} weki_din {\n    çap_bike(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nçap_bike(\"\\n============================================================\");\nçap_bike(\"All User tests completed!\");\nçap_bike(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nçin NotificationService {\n    fonksiyon send(to, subject, message) {\n        çap_bike(\"   📧 Email gönderildi:\");\n        çap_bike(\"      Kime: \" + to);\n        çap_bike(\"      Konu: \" + subject);\n        çap_bike(\"      Mesaj: \" + message);\n        vegere rast;\n    }\n    \n    fonksiyon sendSms(phone, message) {\n        çap_bike(\"   📱 SMS gönderildi:\");\n        çap_bike(\"      Numara: \" + phone);\n        çap_bike(\"      Mesaj: \" + message);\n        vegere rast;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nçin PaymentService {\n    fonksiyon process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        guherbar success = rast; // Gerçekte API çağrısı yapılır\n        \n        eger (success) {\n            vegere {\n                success: rast,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } weki_din {\n            vegere {\n                success: şaş,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    fonksiyon refund(transactionId) {\n        vegere {\n            success: rast,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nçin AuthService {\n    ava_ker() {\n        xwe.userCount = 0;\n    }\n    \n    fonksiyon register(user) {\n        xwe.userCount = xwe.userCount + 1;\n        vegere {\n            success: rast,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    fonksiyon login(email, password) {\n        // Basitleştirilmiş login\n        vegere {\n            success: rast,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    fonksiyon logout(token) {\n        vegere { success: rast };\n    }\n    \n    fonksiyon verifyToken(token) {\n        vegere { valid: rast, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nçin User {\n    ava_ker(name, email, password) {\n        xwe.id = Math.floor(Math.random() * 10000);\n        xwe.name = name;\n        xwe.email = email;\n        xwe.password = password;\n        xwe.createdAt = \"2024-03-07\";\n    }\n    \n    fonksiyon bilgi() {\n        vegere \"User #\" + xwe.id + \": \" + xwe.name + \" (\" + xwe.email + \")\";\n    }\n    \n    fonksiyon getId() {\n        vegere xwe.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nçin Product {\n    ava_ker(name, price, stock, category) {\n        xwe.id = Math.floor(Math.random() * 10000);\n        xwe.name = name;\n        xwe.price = price;\n        xwe.stock = stock;\n        xwe.category = category;\n    }\n    \n    fonksiyon bilgi() {\n        vegere xwe.name + \" - \" + xwe.price + \" TL (Stok: \" + xwe.stock + \", Kategori: \" + xwe.category + \")\";\n    }\n    \n    fonksiyon inStock() {\n        vegere xwe.stock > 0;\n    }\n    \n    fonksiyon getId() {\n        vegere xwe.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nçin Order {\n    ava_ker(userId, productId, quantity, totalPrice) {\n        xwe.id = Math.floor(Math.random() * 10000);\n        xwe.userId = userId;\n        xwe.productId = productId;\n        xwe.quantity = quantity;\n        xwe.totalPrice = totalPrice;\n        xwe.status = \"pending\";\n        xwe.createdAt = \"2024-03-07\";\n    }\n    \n    fonksiyon bilgi() {\n        vegere \"Sipariş #\" + xwe.id + \" - Kullanıcı: \" + xwe.userId + \", Ürün: \" + xwe.productId + \", Adet: \" + xwe.quantity + \", Toplam: \" + xwe.totalPrice + \" TL, Durum: \" + xwe.status;\n    }\n    \n    fonksiyon confirm() {\n        xwe.status = \"confirmed\";\n    }\n    \n    fonksiyon getId() {\n        vegere xwe.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfonksiyon random_string(length) {\n    vegere \"random_\" + length;\n}\n\nfonksiyon sleep(ms) {\n    // Bekleme simülasyonu\n    çap_bike(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfonksiyon log(message) {\n    çap_bike(\"[LOG] \" + message);\n}\n\nfonksiyon error(message) {\n    çap_bike(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nçin Formatting {\n    statik fonksiyon currency(amount, currency) {\n        eger (currency == \"TRY\") {\n            vegere amount + \" ₺\";\n        } weki_din {\n            eger (currency == \"USD\") {\n                vegere \"$\" + amount;\n            } weki_din {\n                eger (currency == \"EUR\") {\n                    vegere \"€\" + amount;\n                } weki_din {\n                    vegere amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    statik fonksiyon date(date) {\n        vegere date;\n    }\n    \n    statik fonksiyon phone(phone) {\n        // (555) 123-4567 formatı\n        vegere \"(\" + phone + \")\";\n    }\n    \n    statik fonksiyon number(num) {\n        // 1,234,567 formatı\n        vegere num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nçin Validation {\n    statik fonksiyon email(email) {\n        // Basit email rastlama\n        vegere email.length > 5;\n    }\n    \n    statik fonksiyon password(password) {\n        // Şifre en az 6 karakter olmalı\n        vegere password.length >= 6;\n    }\n    \n    statik fonksiyon price(price) {\n        vegere price > 0;\n    }\n    \n    statik fonksiyon phone(phone) {\n        // Telefon numarası rastlama\n        vegere phone.length == 10;\n    }\n    \n    statik fonksiyon required(value) {\n        vegere value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nguherbar APP_NAME = \"My Project\";\nguherbar APP_VERSION = \"1.0.0\";\nguherbar MAX_UPLOAD_SIZE = 10485760; // 10MB\nguherbar SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nguherbar STATUS_PENDING = \"pending\";\nguherbar STATUS_APPROVED = \"approved\";\nguherbar STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nguherbar DB_HOST = \"localhost\";\nguherbar DB_PORT = 5432;\nguherbar DB_NAME = \"myproject_db\";\nguherbar DB_USER = \"admin\";\nguherbar DB_PASSWORD = \"secure_password\";\n\nfonksiyon get_connection_string() {\n    vegere \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nguherbar API_BASE_URL = \"https://api.example.com\";\nguherbar API_VERSION = \"v1\";\nguherbar API_TIMEOUT = 30000;\n\nfonksiyon get_api_url(endpoint) {\n    vegere API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "pl": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" użyj;\n\"src/models/product.hudhud\" użyj;\n\"src/models/order.hudhud\" użyj;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" użyj;\n\"src/services/payment.hudhud\" użyj;\n\"src/services/notification.hudhud\" użyj;\n\n// Yardımcı klasaları içe aktar\n\"src/utils/validation.hudhud\" użyj;\n\"src/utils/formatting.hudhud\" użyj;\n\ndrukuj(\"============================================================\");\ndrukuj(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\ndrukuj(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nzmienna authService = nowy AuthService();\nzmienna paymentService = nowy PaymentService();\nzmienna notificationService = nowy NotificationService();\n\ndrukuj(\"1️⃣  KULLANICI KAYDI\");\ndrukuj(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni użyjıcı oluştur\nzmienna newUser = nowy User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\ndrukuj(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email prawdala\njeśli (Validation.email(newUser.email)) {\n    drukuj(\"✓ Email geçerli: \" + newUser.email);\n} w_przeciwnym_razie {\n    drukuj(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nzmienna authResult = authService.register(newUser);\njeśli (authResult.success) {\n    drukuj(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\ndrukuj(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\ndrukuj(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nzmienna product = nowy Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\ndrukuj(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat prawdala\njeśli (Validation.price(product.price)) {\n    drukuj(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\njeśli (product.inStock()) {\n    drukuj(\"✓ Ürün stokta mevcut\");\n} w_przeciwnym_razie {\n    drukuj(\"✗ Ürün stokta yok\");\n}\n\ndrukuj(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\ndrukuj(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nzmienna order = nowy Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\ndrukuj(\"Sipariş oluşturuldu: \" + order.bilgi());\n\ndrukuj(\"\\n4️⃣  ÖDEME İŞLEMİ\");\ndrukuj(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nzmienna paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\njeśli (paymentResult.success) {\n    drukuj(\"✓ \" + paymentResult.message);\n    drukuj(\"  İşlem No: \" + paymentResult.transactionId);\n    drukuj(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    drukuj(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    drukuj(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} w_przeciwnym_razie {\n    drukuj(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\ndrukuj(\"\\n============================================================\");\ndrukuj(\"✓ E-Ticaret sistemi demo tamamlandı!\");\ndrukuj(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\ndrukuj(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" użyj;\n\"../src/services/auth.hudhud\" użyj;\n\ndrukuj(\"============================================================\");\ndrukuj(\"Auth Service Tests\");\ndrukuj(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nzmienna authService = nowy AuthService();\ndrukuj(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nzmienna user = nowy User(\"Test User\", \"test@example.com\", \"test123\");\nzmienna result1 = authService.register(user);\n\njeśli (result1.success) {\n    drukuj(\"✓ Test 2 passed: Registration successful\");\n    drukuj(\"  User ID: \" + result1.userId);\n    drukuj(\"  Message: \" + result1.message);\n} w_przeciwnym_razie {\n    drukuj(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nzmienna loginResult = authService.login(\"test@example.com\", \"test123\");\n\njeśli (loginResult.success) {\n    drukuj(\"✓ Test 3 passed: Login successful\");\n    drukuj(\"  Token: \" + loginResult.token);\n    drukuj(\"  Message: \" + loginResult.message);\n} w_przeciwnym_razie {\n    drukuj(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nzmienna verifyResult = authService.verifyToken(loginResult.token);\n\njeśli (verifyResult.valid) {\n    drukuj(\"✓ Test 4 passed: Token verification successful\");\n    drukuj(\"  User ID: \" + verifyResult.userId);\n} w_przeciwnym_razie {\n    drukuj(\"✗ Test 4 failed: Token verification failed\");\n}\n\ndrukuj(\"\\n============================================================\");\ndrukuj(\"All Auth tests completed!\");\ndrukuj(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" użyj;\n\ndrukuj(\"============================================================\");\ndrukuj(\"User Model Tests\");\ndrukuj(\"============================================================\\n\");\n\n// Test 1: User creation\nzmienna user = nowy User(\"Test User\", \"test@example.com\", \"test123\");\n\njeśli (user.name == \"Test User\") {\n    drukuj(\"✓ Test 1 passed: User creation\");\n} w_przeciwnym_razie {\n    drukuj(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\njeśli (user.email == \"test@example.com\") {\n    drukuj(\"✓ Test 2 passed: Email set correctly\");\n} w_przeciwnym_razie {\n    drukuj(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\njeśli (user.id > 0) {\n    drukuj(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} w_przeciwnym_razie {\n    drukuj(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nzmienna info = user.bilgi();\njeśli (info.length > 0) {\n    drukuj(\"✓ Test 4 passed: bilgi() method works\");\n    drukuj(\"  Info: \" + info);\n} w_przeciwnym_razie {\n    drukuj(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\ndrukuj(\"\\n============================================================\");\ndrukuj(\"All User tests completed!\");\ndrukuj(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nklasa NotificationService {\n    funkcja send(to, subject, message) {\n        drukuj(\"   📧 Email gönderildi:\");\n        drukuj(\"      Kime: \" + to);\n        drukuj(\"      Konu: \" + subject);\n        drukuj(\"      Mesaj: \" + message);\n        zwróć prawda;\n    }\n    \n    funkcja sendSms(phone, message) {\n        drukuj(\"   📱 SMS gönderildi:\");\n        drukuj(\"      Numara: \" + phone);\n        drukuj(\"      Mesaj: \" + message);\n        zwróć prawda;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nklasa PaymentService {\n    funkcja process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        zmienna success = prawda; // Gerçekte API çağrısı yapılır\n        \n        jeśli (success) {\n            zwróć {\n                success: prawda,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } w_przeciwnym_razie {\n            zwróć {\n                success: fałsz,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    funkcja refund(transactionId) {\n        zwróć {\n            success: prawda,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nklasa AuthService {\n    konstruktor() {\n        własny.userCount = 0;\n    }\n    \n    funkcja register(user) {\n        własny.userCount = własny.userCount + 1;\n        zwróć {\n            success: prawda,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    funkcja login(email, password) {\n        // Basitleştirilmiş login\n        zwróć {\n            success: prawda,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    funkcja logout(token) {\n        zwróć { success: prawda };\n    }\n    \n    funkcja verifyToken(token) {\n        zwróć { valid: prawda, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nklasa User {\n    konstruktor(name, email, password) {\n        własny.id = Math.floor(Math.random() * 10000);\n        własny.name = name;\n        własny.email = email;\n        własny.password = password;\n        własny.createdAt = \"2024-03-07\";\n    }\n    \n    funkcja bilgi() {\n        zwróć \"User #\" + własny.id + \": \" + własny.name + \" (\" + własny.email + \")\";\n    }\n    \n    funkcja getId() {\n        zwróć własny.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nklasa Product {\n    konstruktor(name, price, stock, category) {\n        własny.id = Math.floor(Math.random() * 10000);\n        własny.name = name;\n        własny.price = price;\n        własny.stock = stock;\n        własny.category = category;\n    }\n    \n    funkcja bilgi() {\n        zwróć własny.name + \" - \" + własny.price + \" TL (Stok: \" + własny.stock + \", Kategori: \" + własny.category + \")\";\n    }\n    \n    funkcja inStock() {\n        zwróć własny.stock > 0;\n    }\n    \n    funkcja getId() {\n        zwróć własny.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nklasa Order {\n    konstruktor(userId, productId, quantity, totalPrice) {\n        własny.id = Math.floor(Math.random() * 10000);\n        własny.userId = userId;\n        własny.productId = productId;\n        własny.quantity = quantity;\n        własny.totalPrice = totalPrice;\n        własny.status = \"pending\";\n        własny.createdAt = \"2024-03-07\";\n    }\n    \n    funkcja bilgi() {\n        zwróć \"Sipariş #\" + własny.id + \" - Kullanıcı: \" + własny.userId + \", Ürün: \" + własny.productId + \", Adet: \" + własny.quantity + \", Toplam: \" + własny.totalPrice + \" TL, Durum: \" + własny.status;\n    }\n    \n    funkcja confirm() {\n        własny.status = \"confirmed\";\n    }\n    \n    funkcja getId() {\n        zwróć własny.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfunkcja random_string(length) {\n    zwróć \"random_\" + length;\n}\n\nfunkcja sleep(ms) {\n    // Bekleme simülasyonu\n    drukuj(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfunkcja log(message) {\n    drukuj(\"[LOG] \" + message);\n}\n\nfunkcja error(message) {\n    drukuj(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nklasa Formatting {\n    statyczny funkcja currency(amount, currency) {\n        jeśli (currency == \"TRY\") {\n            zwróć amount + \" ₺\";\n        } w_przeciwnym_razie {\n            jeśli (currency == \"USD\") {\n                zwróć \"$\" + amount;\n            } w_przeciwnym_razie {\n                jeśli (currency == \"EUR\") {\n                    zwróć \"€\" + amount;\n                } w_przeciwnym_razie {\n                    zwróć amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    statyczny funkcja date(date) {\n        zwróć date;\n    }\n    \n    statyczny funkcja phone(phone) {\n        // (555) 123-4567 formatı\n        zwróć \"(\" + phone + \")\";\n    }\n    \n    statyczny funkcja number(num) {\n        // 1,234,567 formatı\n        zwróć num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nklasa Validation {\n    statyczny funkcja email(email) {\n        // Basit email prawdalama\n        zwróć email.length > 5;\n    }\n    \n    statyczny funkcja password(password) {\n        // Şifre en az 6 karakter olmalı\n        zwróć password.length >= 6;\n    }\n    \n    statyczny funkcja price(price) {\n        zwróć price > 0;\n    }\n    \n    statyczny funkcja phone(phone) {\n        // Telefon numarası prawdalama\n        zwróć phone.length == 10;\n    }\n    \n    statyczny funkcja required(value) {\n        zwróć value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nzmienna APP_NAME = \"My Project\";\nzmienna APP_VERSION = \"1.0.0\";\nzmienna MAX_UPLOAD_SIZE = 10485760; // 10MB\nzmienna SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nzmienna STATUS_PENDING = \"pending\";\nzmienna STATUS_APPROVED = \"approved\";\nzmienna STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nzmienna DB_HOST = \"localhost\";\nzmienna DB_PORT = 5432;\nzmienna DB_NAME = \"myproject_db\";\nzmienna DB_USER = \"admin\";\nzmienna DB_PASSWORD = \"secure_password\";\n\nfunkcja get_connection_string() {\n    zwróć \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nzmienna API_BASE_URL = \"https://api.example.com\";\nzmienna API_VERSION = \"v1\";\nzmienna API_TIMEOUT = 30000;\n\nfunkcja get_api_url(endpoint) {\n    zwróć API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "pt": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" usar;\n\"src/models/product.hudhud\" usar;\n\"src/models/order.hudhud\" usar;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" usar;\n\"src/services/payment.hudhud\" usar;\n\"src/services/notification.hudhud\" usar;\n\n// Yardımcı classeları içe aktar\n\"src/utils/validation.hudhud\" usar;\n\"src/utils/formatting.hudhud\" usar;\n\nimprimir(\"============================================================\");\nimprimir(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nimprimir(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nvar authService = novo AuthService();\nvar paymentService = novo PaymentService();\nvar notificationService = novo NotificationService();\n\nimprimir(\"1️⃣  KULLANICI KAYDI\");\nimprimir(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni usarıcı oluştur\nvar newUser = novo User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nimprimir(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email verdadeirola\nse (Validation.email(newUser.email)) {\n    imprimir(\"✓ Email geçerli: \" + newUser.email);\n} senão {\n    imprimir(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nvar authResult = authService.register(newUser);\nse (authResult.success) {\n    imprimir(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nimprimir(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nimprimir(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nvar product = novo Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nimprimir(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat verdadeirola\nse (Validation.price(product.price)) {\n    imprimir(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nse (product.inStock()) {\n    imprimir(\"✓ Ürün stokta mevcut\");\n} senão {\n    imprimir(\"✗ Ürün stokta yok\");\n}\n\nimprimir(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nimprimir(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nvar order = novo Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nimprimir(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nimprimir(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nimprimir(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nvar paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nse (paymentResult.success) {\n    imprimir(\"✓ \" + paymentResult.message);\n    imprimir(\"  İşlem No: \" + paymentResult.transactionId);\n    imprimir(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    imprimir(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    imprimir(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} senão {\n    imprimir(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nimprimir(\"\\n============================================================\");\nimprimir(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nimprimir(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nimprimir(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" usar;\n\"../src/services/auth.hudhud\" usar;\n\nimprimir(\"============================================================\");\nimprimir(\"Auth Service Tests\");\nimprimir(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nvar authService = novo AuthService();\nimprimir(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nvar user = novo User(\"Test User\", \"test@example.com\", \"test123\");\nvar result1 = authService.register(user);\n\nse (result1.success) {\n    imprimir(\"✓ Test 2 passed: Registration successful\");\n    imprimir(\"  User ID: \" + result1.userId);\n    imprimir(\"  Message: \" + result1.message);\n} senão {\n    imprimir(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nvar loginResult = authService.login(\"test@example.com\", \"test123\");\n\nse (loginResult.success) {\n    imprimir(\"✓ Test 3 passed: Login successful\");\n    imprimir(\"  Token: \" + loginResult.token);\n    imprimir(\"  Message: \" + loginResult.message);\n} senão {\n    imprimir(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nvar verifyResult = authService.verifyToken(loginResult.token);\n\nse (verifyResult.valid) {\n    imprimir(\"✓ Test 4 passed: Token verification successful\");\n    imprimir(\"  User ID: \" + verifyResult.userId);\n} senão {\n    imprimir(\"✗ Test 4 failed: Token verification failed\");\n}\n\nimprimir(\"\\n============================================================\");\nimprimir(\"All Auth tests completed!\");\nimprimir(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" usar;\n\nimprimir(\"============================================================\");\nimprimir(\"User Model Tests\");\nimprimir(\"============================================================\\n\");\n\n// Test 1: User creation\nvar user = novo User(\"Test User\", \"test@example.com\", \"test123\");\n\nse (user.name == \"Test User\") {\n    imprimir(\"✓ Test 1 passed: User creation\");\n} senão {\n    imprimir(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nse (user.email == \"test@example.com\") {\n    imprimir(\"✓ Test 2 passed: Email set correctly\");\n} senão {\n    imprimir(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nse (user.id > 0) {\n    imprimir(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} senão {\n    imprimir(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nvar info = user.bilgi();\nse (info.length > 0) {\n    imprimir(\"✓ Test 4 passed: bilgi() method works\");\n    imprimir(\"  Info: \" + info);\n} senão {\n    imprimir(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nimprimir(\"\\n============================================================\");\nimprimir(\"All User tests completed!\");\nimprimir(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nclasse NotificationService {\n    função send(to, subject, message) {\n        imprimir(\"   📧 Email gönderildi:\");\n        imprimir(\"      Kime: \" + to);\n        imprimir(\"      Konu: \" + subject);\n        imprimir(\"      Mesaj: \" + message);\n        retornar verdadeiro;\n    }\n    \n    função sendSms(phone, message) {\n        imprimir(\"   📱 SMS gönderildi:\");\n        imprimir(\"      Numara: \" + phone);\n        imprimir(\"      Mesaj: \" + message);\n        retornar verdadeiro;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nclasse PaymentService {\n    função process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        var success = verdadeiro; // Gerçekte API çağrısı yapılır\n        \n        se (success) {\n            retornar {\n                success: verdadeiro,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } senão {\n            retornar {\n                success: falso,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    função refund(transactionId) {\n        retornar {\n            success: verdadeiro,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nclasse AuthService {\n    construtor() {\n        próprio.userCount = 0;\n    }\n    \n    função register(user) {\n        próprio.userCount = próprio.userCount + 1;\n        retornar {\n            success: verdadeiro,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    função login(email, password) {\n        // Basitleştirilmiş login\n        retornar {\n            success: verdadeiro,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    função logout(token) {\n        retornar { success: verdadeiro };\n    }\n    \n    função verifyToken(token) {\n        retornar { valid: verdadeiro, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nclasse User {\n    construtor(name, email, password) {\n        próprio.id = Math.floor(Math.random() * 10000);\n        próprio.name = name;\n        próprio.email = email;\n        próprio.password = password;\n        próprio.createdAt = \"2024-03-07\";\n    }\n    \n    função bilgi() {\n        retornar \"User #\" + próprio.id + \": \" + próprio.name + \" (\" + próprio.email + \")\";\n    }\n    \n    função getId() {\n        retornar próprio.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nclasse Product {\n    construtor(name, price, stock, category) {\n        próprio.id = Math.floor(Math.random() * 10000);\n        próprio.name = name;\n        próprio.price = price;\n        próprio.stock = stock;\n        próprio.category = category;\n    }\n    \n    função bilgi() {\n        retornar próprio.name + \" - \" + próprio.price + \" TL (Stok: \" + próprio.stock + \", Kategori: \" + próprio.category + \")\";\n    }\n    \n    função inStock() {\n        retornar próprio.stock > 0;\n    }\n    \n    função getId() {\n        retornar próprio.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nclasse Order {\n    construtor(userId, productId, quantity, totalPrice) {\n        próprio.id = Math.floor(Math.random() * 10000);\n        próprio.userId = userId;\n        próprio.productId = productId;\n        próprio.quantity = quantity;\n        próprio.totalPrice = totalPrice;\n        próprio.status = \"pending\";\n        próprio.createdAt = \"2024-03-07\";\n    }\n    \n    função bilgi() {\n        retornar \"Sipariş #\" + próprio.id + \" - Kullanıcı: \" + próprio.userId + \", Ürün: \" + próprio.productId + \", Adet: \" + próprio.quantity + \", Toplam: \" + próprio.totalPrice + \" TL, Durum: \" + próprio.status;\n    }\n    \n    função confirm() {\n        próprio.status = \"confirmed\";\n    }\n    \n    função getId() {\n        retornar próprio.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nfunção random_string(length) {\n    retornar \"random_\" + length;\n}\n\nfunção sleep(ms) {\n    // Bekleme simülasyonu\n    imprimir(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nfunção log(message) {\n    imprimir(\"[LOG] \" + message);\n}\n\nfunção error(message) {\n    imprimir(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nclasse Formatting {\n    estático função currency(amount, currency) {\n        se (currency == \"TRY\") {\n            retornar amount + \" ₺\";\n        } senão {\n            se (currency == \"USD\") {\n                retornar \"$\" + amount;\n            } senão {\n                se (currency == \"EUR\") {\n                    retornar \"€\" + amount;\n                } senão {\n                    retornar amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    estático função date(date) {\n        retornar date;\n    }\n    \n    estático função phone(phone) {\n        // (555) 123-4567 formatı\n        retornar \"(\" + phone + \")\";\n    }\n    \n    estático função number(num) {\n        // 1,234,567 formatı\n        retornar num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nclasse Validation {\n    estático função email(email) {\n        // Basit email verdadeirolama\n        retornar email.length > 5;\n    }\n    \n    estático função password(password) {\n        // Şifre en az 6 karakter olmalı\n        retornar password.length >= 6;\n    }\n    \n    estático função price(price) {\n        retornar price > 0;\n    }\n    \n    estático função phone(phone) {\n        // Telefon numarası verdadeirolama\n        retornar phone.length == 10;\n    }\n    \n    estático função required(value) {\n        retornar value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nvar APP_NAME = \"My Project\";\nvar APP_VERSION = \"1.0.0\";\nvar MAX_UPLOAD_SIZE = 10485760; // 10MB\nvar SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nvar STATUS_PENDING = \"pending\";\nvar STATUS_APPROVED = \"approved\";\nvar STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nvar DB_HOST = \"localhost\";\nvar DB_PORT = 5432;\nvar DB_NAME = \"myproject_db\";\nvar DB_USER = \"admin\";\nvar DB_PASSWORD = \"secure_password\";\n\nfunção get_connection_string() {\n    retornar \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nvar API_BASE_URL = \"https://api.example.com\";\nvar API_VERSION = \"v1\";\nvar API_TIMEOUT = 30000;\n\nfunção get_api_url(endpoint) {\n    retornar API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "ru": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" использовать;\n\"src/models/product.hudhud\" использовать;\n\"src/models/order.hudhud\" использовать;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" использовать;\n\"src/services/payment.hudhud\" использовать;\n\"src/services/notification.hudhud\" использовать;\n\n// Yardımcı классları içe aktar\n\"src/utils/validation.hudhud\" использовать;\n\"src/utils/formatting.hudhud\" использовать;\n\nпечать(\"============================================================\");\nпечать(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nпечать(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nпер authService = новый AuthService();\nпер paymentService = новый PaymentService();\nпер notificationService = новый NotificationService();\n\nпечать(\"1️⃣  KULLANICI KAYDI\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni использоватьıcı oluştur\nпер newUser = новый User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nпечать(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email истинаla\nесли (Validation.email(newUser.email)) {\n    печать(\"✓ Email geçerli: \" + newUser.email);\n} иначе {\n    печать(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nпер authResult = authService.register(newUser);\nесли (authResult.success) {\n    печать(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nпечать(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nпер product = новый Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nпечать(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat истинаla\nесли (Validation.price(product.price)) {\n    печать(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nесли (product.inStock()) {\n    печать(\"✓ Ürün stokta mevcut\");\n} иначе {\n    печать(\"✗ Ürün stokta yok\");\n}\n\nпечать(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nпер order = новый Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nпечать(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nпечать(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nпер paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nесли (paymentResult.success) {\n    печать(\"✓ \" + paymentResult.message);\n    печать(\"  İşlem No: \" + paymentResult.transactionId);\n    печать(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    печать(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    печать(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} иначе {\n    печать(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nпечать(\"\\n============================================================\");\nпечать(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nпечать(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nпечать(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" использовать;\n\"../src/services/auth.hudhud\" использовать;\n\nпечать(\"============================================================\");\nпечать(\"Auth Service Tests\");\nпечать(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nпер authService = новый AuthService();\nпечать(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nпер user = новый User(\"Test User\", \"test@example.com\", \"test123\");\nпер result1 = authService.register(user);\n\nесли (result1.success) {\n    печать(\"✓ Test 2 passed: Registration successful\");\n    печать(\"  User ID: \" + result1.userId);\n    печать(\"  Message: \" + result1.message);\n} иначе {\n    печать(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nпер loginResult = authService.login(\"test@example.com\", \"test123\");\n\nесли (loginResult.success) {\n    печать(\"✓ Test 3 passed: Login successful\");\n    печать(\"  Token: \" + loginResult.token);\n    печать(\"  Message: \" + loginResult.message);\n} иначе {\n    печать(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nпер verifyResult = authService.verifyToken(loginResult.token);\n\nесли (verifyResult.valid) {\n    печать(\"✓ Test 4 passed: Token verification successful\");\n    печать(\"  User ID: \" + verifyResult.userId);\n} иначе {\n    печать(\"✗ Test 4 failed: Token verification failed\");\n}\n\nпечать(\"\\n============================================================\");\nпечать(\"All Auth tests completed!\");\nпечать(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" использовать;\n\nпечать(\"============================================================\");\nпечать(\"User Model Tests\");\nпечать(\"============================================================\\n\");\n\n// Test 1: User creation\nпер user = новый User(\"Test User\", \"test@example.com\", \"test123\");\n\nесли (user.name == \"Test User\") {\n    печать(\"✓ Test 1 passed: User creation\");\n} иначе {\n    печать(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nесли (user.email == \"test@example.com\") {\n    печать(\"✓ Test 2 passed: Email set correctly\");\n} иначе {\n    печать(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nесли (user.id > 0) {\n    печать(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} иначе {\n    печать(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nпер info = user.bilgi();\nесли (info.length > 0) {\n    печать(\"✓ Test 4 passed: bilgi() method works\");\n    печать(\"  Info: \" + info);\n} иначе {\n    печать(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nпечать(\"\\n============================================================\");\nпечать(\"All User tests completed!\");\nпечать(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nкласс NotificationService {\n    функция send(to, subject, message) {\n        печать(\"   📧 Email gönderildi:\");\n        печать(\"      Kime: \" + to);\n        печать(\"      Konu: \" + subject);\n        печать(\"      Mesaj: \" + message);\n        вернуть истина;\n    }\n    \n    функция sendSms(phone, message) {\n        печать(\"   📱 SMS gönderildi:\");\n        печать(\"      Numara: \" + phone);\n        печать(\"      Mesaj: \" + message);\n        вернуть истина;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nкласс PaymentService {\n    функция process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        пер success = истина; // Gerçekte API çağrısı yapılır\n        \n        если (success) {\n            вернуть {\n                success: истина,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } иначе {\n            вернуть {\n                success: ложь,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    функция refund(transactionId) {\n        вернуть {\n            success: истина,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nкласс AuthService {\n    конструктор() {\n        сам.userCount = 0;\n    }\n    \n    функция register(user) {\n        сам.userCount = сам.userCount + 1;\n        вернуть {\n            success: истина,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    функция login(email, password) {\n        // Basitleştirilmiş login\n        вернуть {\n            success: истина,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    функция logout(token) {\n        вернуть { success: истина };\n    }\n    \n    функция verifyToken(token) {\n        вернуть { valid: истина, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nкласс User {\n    конструктор(name, email, password) {\n        сам.id = Math.floor(Math.random() * 10000);\n        сам.name = name;\n        сам.email = email;\n        сам.password = password;\n        сам.createdAt = \"2024-03-07\";\n    }\n    \n    функция bilgi() {\n        вернуть \"User #\" + сам.id + \": \" + сам.name + \" (\" + сам.email + \")\";\n    }\n    \n    функция getId() {\n        вернуть сам.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nкласс Product {\n    конструктор(name, price, stock, category) {\n        сам.id = Math.floor(Math.random() * 10000);\n        сам.name = name;\n        сам.price = price;\n        сам.stock = stock;\n        сам.category = category;\n    }\n    \n    функция bilgi() {\n        вернуть сам.name + \" - \" + сам.price + \" TL (Stok: \" + сам.stock + \", Kategori: \" + сам.category + \")\";\n    }\n    \n    функция inStock() {\n        вернуть сам.stock > 0;\n    }\n    \n    функция getId() {\n        вернуть сам.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nкласс Order {\n    конструктор(userId, productId, quantity, totalPrice) {\n        сам.id = Math.floor(Math.random() * 10000);\n        сам.userId = userId;\n        сам.productId = productId;\n        сам.quantity = quantity;\n        сам.totalPrice = totalPrice;\n        сам.status = \"pending\";\n        сам.createdAt = \"2024-03-07\";\n    }\n    \n    функция bilgi() {\n        вернуть \"Sipariş #\" + сам.id + \" - Kullanıcı: \" + сам.userId + \", Ürün: \" + сам.productId + \", Adet: \" + сам.quantity + \", Toplam: \" + сам.totalPrice + \" TL, Durum: \" + сам.status;\n    }\n    \n    функция confirm() {\n        сам.status = \"confirmed\";\n    }\n    \n    функция getId() {\n        вернуть сам.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nфункция random_string(length) {\n    вернуть \"random_\" + length;\n}\n\nфункция sleep(ms) {\n    // Bekleme simülasyonu\n    печать(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nфункция log(message) {\n    печать(\"[LOG] \" + message);\n}\n\nфункция error(message) {\n    печать(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nкласс Formatting {\n    статический функция currency(amount, currency) {\n        если (currency == \"TRY\") {\n            вернуть amount + \" ₺\";\n        } иначе {\n            если (currency == \"USD\") {\n                вернуть \"$\" + amount;\n            } иначе {\n                если (currency == \"EUR\") {\n                    вернуть \"€\" + amount;\n                } иначе {\n                    вернуть amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    статический функция date(date) {\n        вернуть date;\n    }\n    \n    статический функция phone(phone) {\n        // (555) 123-4567 formatı\n        вернуть \"(\" + phone + \")\";\n    }\n    \n    статический функция number(num) {\n        // 1,234,567 formatı\n        вернуть num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nкласс Validation {\n    статический функция email(email) {\n        // Basit email истинаlama\n        вернуть email.length > 5;\n    }\n    \n    статический функция password(password) {\n        // Şifre en az 6 karakter olmalı\n        вернуть password.length >= 6;\n    }\n    \n    статический функция price(price) {\n        вернуть price > 0;\n    }\n    \n    статический функция phone(phone) {\n        // Telefon numarası истинаlama\n        вернуть phone.length == 10;\n    }\n    \n    статический функция required(value) {\n        вернуть value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nпер APP_NAME = \"My Project\";\nпер APP_VERSION = \"1.0.0\";\nпер MAX_UPLOAD_SIZE = 10485760; // 10MB\nпер SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nпер STATUS_PENDING = \"pending\";\nпер STATUS_APPROVED = \"approved\";\nпер STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nпер DB_HOST = \"localhost\";\nпер DB_PORT = 5432;\nпер DB_NAME = \"myproject_db\";\nпер DB_USER = \"admin\";\nпер DB_PASSWORD = \"secure_password\";\n\nфункция get_connection_string() {\n    вернуть \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nпер API_BASE_URL = \"https://api.example.com\";\nпер API_VERSION = \"v1\";\nпер API_TIMEOUT = 30000;\n\nфункция get_api_url(endpoint) {\n    вернуть API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "sr": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" користи;\n\"src/models/product.hudhud\" користи;\n\"src/models/order.hudhud\" користи;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" користи;\n\"src/services/payment.hudhud\" користи;\n\"src/services/notification.hudhud\" користи;\n\n// Yardımcı класаları içe aktar\n\"src/utils/validation.hudhud\" користи;\n\"src/utils/formatting.hudhud\" користи;\n\nштампај(\"============================================================\");\nштампај(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nштампај(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nваријабла authService = нови AuthService();\nваријабла paymentService = нови PaymentService();\nваријабла notificationService = нови NotificationService();\n\nштампај(\"1️⃣  KULLANICI KAYDI\");\nштампај(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni користиıcı oluştur\nваријабла newUser = нови User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nштампај(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email тачноla\nако (Validation.email(newUser.email)) {\n    штампај(\"✓ Email geçerli: \" + newUser.email);\n} иначе {\n    штампај(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nваријабла authResult = authService.register(newUser);\nако (authResult.success) {\n    штампај(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nштампај(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nштампај(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nваријабла product = нови Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nштампај(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat тачноla\nако (Validation.price(product.price)) {\n    штампај(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nако (product.inStock()) {\n    штампај(\"✓ Ürün stokta mevcut\");\n} иначе {\n    штампај(\"✗ Ürün stokta yok\");\n}\n\nштампај(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nштампај(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nваријабла order = нови Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nштампај(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nштампај(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nштампај(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nваријабла paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nако (paymentResult.success) {\n    штампај(\"✓ \" + paymentResult.message);\n    штампај(\"  İşlem No: \" + paymentResult.transactionId);\n    штампај(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    штампај(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    штампај(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} иначе {\n    штампај(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nштампај(\"\\n============================================================\");\nштампај(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nштампај(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nштампај(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" користи;\n\"../src/services/auth.hudhud\" користи;\n\nштампај(\"============================================================\");\nштампај(\"Auth Service Tests\");\nштампај(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nваријабла authService = нови AuthService();\nштампај(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nваријабла user = нови User(\"Test User\", \"test@example.com\", \"test123\");\nваријабла result1 = authService.register(user);\n\nако (result1.success) {\n    штампај(\"✓ Test 2 passed: Registration successful\");\n    штампај(\"  User ID: \" + result1.userId);\n    штампај(\"  Message: \" + result1.message);\n} иначе {\n    штампај(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nваријабла loginResult = authService.login(\"test@example.com\", \"test123\");\n\nако (loginResult.success) {\n    штампај(\"✓ Test 3 passed: Login successful\");\n    штампај(\"  Token: \" + loginResult.token);\n    штампај(\"  Message: \" + loginResult.message);\n} иначе {\n    штампај(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nваријабла verifyResult = authService.verifyToken(loginResult.token);\n\nако (verifyResult.valid) {\n    штампај(\"✓ Test 4 passed: Token verification successful\");\n    штампај(\"  User ID: \" + verifyResult.userId);\n} иначе {\n    штампај(\"✗ Test 4 failed: Token verification failed\");\n}\n\nштампај(\"\\n============================================================\");\nштампај(\"All Auth tests completed!\");\nштампај(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" користи;\n\nштампај(\"============================================================\");\nштампај(\"User Model Tests\");\nштампај(\"============================================================\\n\");\n\n// Test 1: User creation\nваријабла user = нови User(\"Test User\", \"test@example.com\", \"test123\");\n\nако (user.name == \"Test User\") {\n    штампај(\"✓ Test 1 passed: User creation\");\n} иначе {\n    штампај(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nако (user.email == \"test@example.com\") {\n    штампај(\"✓ Test 2 passed: Email set correctly\");\n} иначе {\n    штампај(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nако (user.id > 0) {\n    штампај(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} иначе {\n    штампај(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nваријабла info = user.bilgi();\nако (info.length > 0) {\n    штампај(\"✓ Test 4 passed: bilgi() method works\");\n    штампај(\"  Info: \" + info);\n} иначе {\n    штампај(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nштампај(\"\\n============================================================\");\nштампај(\"All User tests completed!\");\nштампај(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nкласа NotificationService {\n    функција send(to, subject, message) {\n        штампај(\"   📧 Email gönderildi:\");\n        штампај(\"      Kime: \" + to);\n        штампај(\"      Konu: \" + subject);\n        штампај(\"      Mesaj: \" + message);\n        врати тачно;\n    }\n    \n    функција sendSms(phone, message) {\n        штампај(\"   📱 SMS gönderildi:\");\n        штампај(\"      Numara: \" + phone);\n        штампај(\"      Mesaj: \" + message);\n        врати тачно;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nкласа PaymentService {\n    функција process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        варијабла success = тачно; // Gerçekte API çağrısı yapılır\n        \n        ако (success) {\n            врати {\n                success: тачно,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } иначе {\n            врати {\n                success: нетачно,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    функција refund(transactionId) {\n        врати {\n            success: тачно,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nкласа AuthService {\n    конструктор() {\n        властити.userCount = 0;\n    }\n    \n    функција register(user) {\n        властити.userCount = властити.userCount + 1;\n        врати {\n            success: тачно,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    функција login(email, password) {\n        // Basitleştirilmiş login\n        врати {\n            success: тачно,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    функција logout(token) {\n        врати { success: тачно };\n    }\n    \n    функција verifyToken(token) {\n        врати { valid: тачно, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nкласа User {\n    конструктор(name, email, password) {\n        властити.id = Math.floor(Math.random() * 10000);\n        властити.name = name;\n        властити.email = email;\n        властити.password = password;\n        властити.createdAt = \"2024-03-07\";\n    }\n    \n    функција bilgi() {\n        врати \"User #\" + властити.id + \": \" + властити.name + \" (\" + властити.email + \")\";\n    }\n    \n    функција getId() {\n        врати властити.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nкласа Product {\n    конструктор(name, price, stock, category) {\n        властити.id = Math.floor(Math.random() * 10000);\n        властити.name = name;\n        властити.price = price;\n        властити.stock = stock;\n        властити.category = category;\n    }\n    \n    функција bilgi() {\n        врати властити.name + \" - \" + властити.price + \" TL (Stok: \" + властити.stock + \", Kategori: \" + властити.category + \")\";\n    }\n    \n    функција inStock() {\n        врати властити.stock > 0;\n    }\n    \n    функција getId() {\n        врати властити.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nкласа Order {\n    конструктор(userId, productId, quantity, totalPrice) {\n        властити.id = Math.floor(Math.random() * 10000);\n        властити.userId = userId;\n        властити.productId = productId;\n        властити.quantity = quantity;\n        властити.totalPrice = totalPrice;\n        властити.status = \"pending\";\n        властити.createdAt = \"2024-03-07\";\n    }\n    \n    функција bilgi() {\n        врати \"Sipariş #\" + властити.id + \" - Kullanıcı: \" + властити.userId + \", Ürün: \" + властити.productId + \", Adet: \" + властити.quantity + \", Toplam: \" + властити.totalPrice + \" TL, Durum: \" + властити.status;\n    }\n    \n    функција confirm() {\n        властити.status = \"confirmed\";\n    }\n    \n    функција getId() {\n        врати властити.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nфункција random_string(length) {\n    врати \"random_\" + length;\n}\n\nфункција sleep(ms) {\n    // Bekleme simülasyonu\n    штампај(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nфункција log(message) {\n    штампај(\"[LOG] \" + message);\n}\n\nфункција error(message) {\n    штампај(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nкласа Formatting {\n    статички функција currency(amount, currency) {\n        ако (currency == \"TRY\") {\n            врати amount + \" ₺\";\n        } иначе {\n            ако (currency == \"USD\") {\n                врати \"$\" + amount;\n            } иначе {\n                ако (currency == \"EUR\") {\n                    врати \"€\" + amount;\n                } иначе {\n                    врати amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    статички функција date(date) {\n        врати date;\n    }\n    \n    статички функција phone(phone) {\n        // (555) 123-4567 formatı\n        врати \"(\" + phone + \")\";\n    }\n    \n    статички функција number(num) {\n        // 1,234,567 formatı\n        врати num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nкласа Validation {\n    статички функција email(email) {\n        // Basit email тачноlama\n        врати email.length > 5;\n    }\n    \n    статички функција password(password) {\n        // Şifre en az 6 karakter olmalı\n        врати password.length >= 6;\n    }\n    \n    статички функција price(price) {\n        врати price > 0;\n    }\n    \n    статички функција phone(phone) {\n        // Telefon numarası тачноlama\n        врати phone.length == 10;\n    }\n    \n    статички функција required(value) {\n        врати value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nваријабла APP_NAME = \"My Project\";\nваријабла APP_VERSION = \"1.0.0\";\nваријабла MAX_UPLOAD_SIZE = 10485760; // 10MB\nваријабла SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nваријабла STATUS_PENDING = \"pending\";\nваријабла STATUS_APPROVED = \"approved\";\nваријабла STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nваријабла DB_HOST = \"localhost\";\nваријабла DB_PORT = 5432;\nваријабла DB_NAME = \"myproject_db\";\nваријабла DB_USER = \"admin\";\nваријабла DB_PASSWORD = \"secure_password\";\n\nфункција get_connection_string() {\n    врати \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nваријабла API_BASE_URL = \"https://api.example.com\";\nваријабла API_VERSION = \"v1\";\nваријабла API_TIMEOUT = 30000;\n\nфункција get_api_url(endpoint) {\n    врати API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "th": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" ใช้;\n\"src/models/product.hudhud\" ใช้;\n\"src/models/order.hudhud\" ใช้;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" ใช้;\n\"src/services/payment.hudhud\" ใช้;\n\"src/services/notification.hudhud\" ใช้;\n\n// Yardımcı คลาสları içe aktar\n\"src/utils/validation.hudhud\" ใช้;\n\"src/utils/formatting.hudhud\" ใช้;\n\nพิมพ์(\"============================================================\");\nพิมพ์(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nพิมพ์(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nตัวแปร authService = ใหม่ AuthService();\nตัวแปร paymentService = ใหม่ PaymentService();\nตัวแปร notificationService = ใหม่ NotificationService();\n\nพิมพ์(\"1️⃣  KULLANICI KAYDI\");\nพิมพ์(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni ใช้ıcı oluştur\nตัวแปร newUser = ใหม่ User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nพิมพ์(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email จริงla\nถ้า (Validation.email(newUser.email)) {\n    พิมพ์(\"✓ Email geçerli: \" + newUser.email);\n} มิฉะนั้น {\n    พิมพ์(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nตัวแปร authResult = authService.register(newUser);\nถ้า (authResult.success) {\n    พิมพ์(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nพิมพ์(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nพิมพ์(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nตัวแปร product = ใหม่ Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nพิมพ์(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat จริงla\nถ้า (Validation.price(product.price)) {\n    พิมพ์(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nถ้า (product.inStock()) {\n    พิมพ์(\"✓ Ürün stokta mevcut\");\n} มิฉะนั้น {\n    พิมพ์(\"✗ Ürün stokta yok\");\n}\n\nพิมพ์(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nพิมพ์(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nตัวแปร order = ใหม่ Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nพิมพ์(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nพิมพ์(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nพิมพ์(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nตัวแปร paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nถ้า (paymentResult.success) {\n    พิมพ์(\"✓ \" + paymentResult.message);\n    พิมพ์(\"  İşlem No: \" + paymentResult.transactionId);\n    พิมพ์(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    พิมพ์(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    พิมพ์(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} มิฉะนั้น {\n    พิมพ์(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nพิมพ์(\"\\n============================================================\");\nพิมพ์(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nพิมพ์(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nพิมพ์(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" ใช้;\n\"../src/services/auth.hudhud\" ใช้;\n\nพิมพ์(\"============================================================\");\nพิมพ์(\"Auth Service Tests\");\nพิมพ์(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nตัวแปร authService = ใหม่ AuthService();\nพิมพ์(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nตัวแปร user = ใหม่ User(\"Test User\", \"test@example.com\", \"test123\");\nตัวแปร result1 = authService.register(user);\n\nถ้า (result1.success) {\n    พิมพ์(\"✓ Test 2 passed: Registration successful\");\n    พิมพ์(\"  User ID: \" + result1.userId);\n    พิมพ์(\"  Message: \" + result1.message);\n} มิฉะนั้น {\n    พิมพ์(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nตัวแปร loginResult = authService.login(\"test@example.com\", \"test123\");\n\nถ้า (loginResult.success) {\n    พิมพ์(\"✓ Test 3 passed: Login successful\");\n    พิมพ์(\"  Token: \" + loginResult.token);\n    พิมพ์(\"  Message: \" + loginResult.message);\n} มิฉะนั้น {\n    พิมพ์(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nตัวแปร verifyResult = authService.verifyToken(loginResult.token);\n\nถ้า (verifyResult.valid) {\n    พิมพ์(\"✓ Test 4 passed: Token verification successful\");\n    พิมพ์(\"  User ID: \" + verifyResult.userId);\n} มิฉะนั้น {\n    พิมพ์(\"✗ Test 4 failed: Token verification failed\");\n}\n\nพิมพ์(\"\\n============================================================\");\nพิมพ์(\"All Auth tests completed!\");\nพิมพ์(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" ใช้;\n\nพิมพ์(\"============================================================\");\nพิมพ์(\"User Model Tests\");\nพิมพ์(\"============================================================\\n\");\n\n// Test 1: User creation\nตัวแปร user = ใหม่ User(\"Test User\", \"test@example.com\", \"test123\");\n\nถ้า (user.name == \"Test User\") {\n    พิมพ์(\"✓ Test 1 passed: User creation\");\n} มิฉะนั้น {\n    พิมพ์(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nถ้า (user.email == \"test@example.com\") {\n    พิมพ์(\"✓ Test 2 passed: Email set correctly\");\n} มิฉะนั้น {\n    พิมพ์(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nถ้า (user.id > 0) {\n    พิมพ์(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} มิฉะนั้น {\n    พิมพ์(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nตัวแปร info = user.bilgi();\nถ้า (info.length > 0) {\n    พิมพ์(\"✓ Test 4 passed: bilgi() method works\");\n    พิมพ์(\"  Info: \" + info);\n} มิฉะนั้น {\n    พิมพ์(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nพิมพ์(\"\\n============================================================\");\nพิมพ์(\"All User tests completed!\");\nพิมพ์(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nคลาส NotificationService {\n    ฟังก์ชัน send(to, subject, message) {\n        พิมพ์(\"   📧 Email gönderildi:\");\n        พิมพ์(\"      Kime: \" + to);\n        พิมพ์(\"      Konu: \" + subject);\n        พิมพ์(\"      Mesaj: \" + message);\n        คืนค่า จริง;\n    }\n    \n    ฟังก์ชัน sendSms(phone, message) {\n        พิมพ์(\"   📱 SMS gönderildi:\");\n        พิมพ์(\"      Numara: \" + phone);\n        พิมพ์(\"      Mesaj: \" + message);\n        คืนค่า จริง;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nคลาส PaymentService {\n    ฟังก์ชัน process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        ตัวแปร success = จริง; // Gerçekte API çağrısı yapılır\n        \n        ถ้า (success) {\n            คืนค่า {\n                success: จริง,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } มิฉะนั้น {\n            คืนค่า {\n                success: เท็จ,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    ฟังก์ชัน refund(transactionId) {\n        คืนค่า {\n            success: จริง,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nคลาส AuthService {\n    ตัวสร้าง() {\n        ตัวเอง.userCount = 0;\n    }\n    \n    ฟังก์ชัน register(user) {\n        ตัวเอง.userCount = ตัวเอง.userCount + 1;\n        คืนค่า {\n            success: จริง,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    ฟังก์ชัน login(email, password) {\n        // Basitleştirilmiş login\n        คืนค่า {\n            success: จริง,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    ฟังก์ชัน logout(token) {\n        คืนค่า { success: จริง };\n    }\n    \n    ฟังก์ชัน verifyToken(token) {\n        คืนค่า { valid: จริง, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nคลาส User {\n    ตัวสร้าง(name, email, password) {\n        ตัวเอง.id = Math.floor(Math.random() * 10000);\n        ตัวเอง.name = name;\n        ตัวเอง.email = email;\n        ตัวเอง.password = password;\n        ตัวเอง.createdAt = \"2024-03-07\";\n    }\n    \n    ฟังก์ชัน bilgi() {\n        คืนค่า \"User #\" + ตัวเอง.id + \": \" + ตัวเอง.name + \" (\" + ตัวเอง.email + \")\";\n    }\n    \n    ฟังก์ชัน getId() {\n        คืนค่า ตัวเอง.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nคลาส Product {\n    ตัวสร้าง(name, price, stock, category) {\n        ตัวเอง.id = Math.floor(Math.random() * 10000);\n        ตัวเอง.name = name;\n        ตัวเอง.price = price;\n        ตัวเอง.stock = stock;\n        ตัวเอง.category = category;\n    }\n    \n    ฟังก์ชัน bilgi() {\n        คืนค่า ตัวเอง.name + \" - \" + ตัวเอง.price + \" TL (Stok: \" + ตัวเอง.stock + \", Kategori: \" + ตัวเอง.category + \")\";\n    }\n    \n    ฟังก์ชัน inStock() {\n        คืนค่า ตัวเอง.stock > 0;\n    }\n    \n    ฟังก์ชัน getId() {\n        คืนค่า ตัวเอง.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nคลาส Order {\n    ตัวสร้าง(userId, productId, quantity, totalPrice) {\n        ตัวเอง.id = Math.floor(Math.random() * 10000);\n        ตัวเอง.userId = userId;\n        ตัวเอง.productId = productId;\n        ตัวเอง.quantity = quantity;\n        ตัวเอง.totalPrice = totalPrice;\n        ตัวเอง.status = \"pending\";\n        ตัวเอง.createdAt = \"2024-03-07\";\n    }\n    \n    ฟังก์ชัน bilgi() {\n        คืนค่า \"Sipariş #\" + ตัวเอง.id + \" - Kullanıcı: \" + ตัวเอง.userId + \", Ürün: \" + ตัวเอง.productId + \", Adet: \" + ตัวเอง.quantity + \", Toplam: \" + ตัวเอง.totalPrice + \" TL, Durum: \" + ตัวเอง.status;\n    }\n    \n    ฟังก์ชัน confirm() {\n        ตัวเอง.status = \"confirmed\";\n    }\n    \n    ฟังก์ชัน getId() {\n        คืนค่า ตัวเอง.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nฟังก์ชัน random_string(length) {\n    คืนค่า \"random_\" + length;\n}\n\nฟังก์ชัน sleep(ms) {\n    // Bekleme simülasyonu\n    พิมพ์(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nฟังก์ชัน log(message) {\n    พิมพ์(\"[LOG] \" + message);\n}\n\nฟังก์ชัน error(message) {\n    พิมพ์(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nคลาส Formatting {\n    คงที่ ฟังก์ชัน currency(amount, currency) {\n        ถ้า (currency == \"TRY\") {\n            คืนค่า amount + \" ₺\";\n        } มิฉะนั้น {\n            ถ้า (currency == \"USD\") {\n                คืนค่า \"$\" + amount;\n            } มิฉะนั้น {\n                ถ้า (currency == \"EUR\") {\n                    คืนค่า \"€\" + amount;\n                } มิฉะนั้น {\n                    คืนค่า amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    คงที่ ฟังก์ชัน date(date) {\n        คืนค่า date;\n    }\n    \n    คงที่ ฟังก์ชัน phone(phone) {\n        // (555) 123-4567 formatı\n        คืนค่า \"(\" + phone + \")\";\n    }\n    \n    คงที่ ฟังก์ชัน number(num) {\n        // 1,234,567 formatı\n        คืนค่า num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nคลาส Validation {\n    คงที่ ฟังก์ชัน email(email) {\n        // Basit email จริงlama\n        คืนค่า email.length > 5;\n    }\n    \n    คงที่ ฟังก์ชัน password(password) {\n        // Şifre en az 6 karakter olmalı\n        คืนค่า password.length >= 6;\n    }\n    \n    คงที่ ฟังก์ชัน price(price) {\n        คืนค่า price > 0;\n    }\n    \n    คงที่ ฟังก์ชัน phone(phone) {\n        // Telefon numarası จริงlama\n        คืนค่า phone.length == 10;\n    }\n    \n    คงที่ ฟังก์ชัน required(value) {\n        คืนค่า value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nตัวแปร APP_NAME = \"My Project\";\nตัวแปร APP_VERSION = \"1.0.0\";\nตัวแปร MAX_UPLOAD_SIZE = 10485760; // 10MB\nตัวแปร SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nตัวแปร STATUS_PENDING = \"pending\";\nตัวแปร STATUS_APPROVED = \"approved\";\nตัวแปร STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nตัวแปร DB_HOST = \"localhost\";\nตัวแปร DB_PORT = 5432;\nตัวแปร DB_NAME = \"myproject_db\";\nตัวแปร DB_USER = \"admin\";\nตัวแปร DB_PASSWORD = \"secure_password\";\n\nฟังก์ชัน get_connection_string() {\n    คืนค่า \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nตัวแปร API_BASE_URL = \"https://api.example.com\";\nตัวแปร API_VERSION = \"v1\";\nตัวแปร API_TIMEOUT = 30000;\n\nฟังก์ชัน get_api_url(endpoint) {\n    คืนค่า API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}, "tr": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" kullan;\n\"src/models/product.hudhud\" kullan;\n\"src/models/order.hudhud\" kullan;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" kullan;\n\"src/services/payment.hudhud\" kullan;\n\"src/services/notification.hudhud\" kullan;\n\n// Yardımcı sınıfları içe aktar\n\"src/utils/validation.hudhud\" kullan;\n\"src/utils/formatting.hudhud\" kullan;\n\nyaz(\"============================================================\");\nyaz(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nyaz(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\ndeğişken authService = yeni AuthService();\ndeğişken paymentService = yeni PaymentService();\ndeğişken notificationService = yeni NotificationService();\n\nyaz(\"1️⃣  KULLANICI KAYDI\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni kullanıcı oluştur\ndeğişken newUser = yeni User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nyaz(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email doğrula\neğer (Validation.email(newUser.email)) {\n    yaz(\"✓ Email geçerli: \" + newUser.email);\n} değilse {\n    yaz(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\ndeğişken authResult = authService.register(newUser);\neğer (authResult.success) {\n    yaz(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nyaz(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\ndeğişken product = yeni Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nyaz(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat doğrula\neğer (Validation.price(product.price)) {\n    yaz(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\neğer (product.inStock()) {\n    yaz(\"✓ Ürün stokta mevcut\");\n} değilse {\n    yaz(\"✗ Ürün stokta yok\");\n}\n\nyaz(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\ndeğişken order = yeni Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nyaz(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nyaz(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\ndeğişken paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\neğer (paymentResult.success) {\n    yaz(\"✓ \" + paymentResult.message);\n    yaz(\"  İşlem No: \" + paymentResult.transactionId);\n    yaz(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    yaz(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    yaz(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} değilse {\n    yaz(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nyaz(\"\\n============================================================\");\nyaz(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nyaz(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nyaz(\"============================================================\");\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması - HudHudScript\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"keywords\": [\"ecommerce\", \"hudhudscript\", \"turkish\"],\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\",\n    \"kimya\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhudscript run main.hudhud\",\n    \"dev\": \"hudhudscript run --watch main.hudhud\",\n    \"test\": \"hudhudscript test tests/\",\n    \"build\": \"hudhudscript compile main.hudhud\",\n    \"package\": \"hudhudscript package create\"\n  }\n}\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" kullan;\n\"../src/services/auth.hudhud\" kullan;\n\nyaz(\"============================================================\");\nyaz(\"Auth Service Tests\");\nyaz(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\ndeğişken authService = yeni AuthService();\nyaz(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\ndeğişken user = yeni User(\"Test User\", \"test@example.com\", \"test123\");\ndeğişken result1 = authService.register(user);\n\neğer (result1.success) {\n    yaz(\"✓ Test 2 passed: Registration successful\");\n    yaz(\"  User ID: \" + result1.userId);\n    yaz(\"  Message: \" + result1.message);\n} değilse {\n    yaz(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\ndeğişken loginResult = authService.login(\"test@example.com\", \"test123\");\n\neğer (loginResult.success) {\n    yaz(\"✓ Test 3 passed: Login successful\");\n    yaz(\"  Token: \" + loginResult.token);\n    yaz(\"  Message: \" + loginResult.message);\n} değilse {\n    yaz(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\ndeğişken verifyResult = authService.verifyToken(loginResult.token);\n\neğer (verifyResult.valid) {\n    yaz(\"✓ Test 4 passed: Token verification successful\");\n    yaz(\"  User ID: \" + verifyResult.userId);\n} değilse {\n    yaz(\"✗ Test 4 failed: Token verification failed\");\n}\n\nyaz(\"\\n============================================================\");\nyaz(\"All Auth tests completed!\");\nyaz(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" kullan;\n\nyaz(\"============================================================\");\nyaz(\"User Model Tests\");\nyaz(\"============================================================\\n\");\n\n// Test 1: User creation\ndeğişken user = yeni User(\"Test User\", \"test@example.com\", \"test123\");\n\neğer (user.name == \"Test User\") {\n    yaz(\"✓ Test 1 passed: User creation\");\n} değilse {\n    yaz(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\neğer (user.email == \"test@example.com\") {\n    yaz(\"✓ Test 2 passed: Email set correctly\");\n} değilse {\n    yaz(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\neğer (user.id > 0) {\n    yaz(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} değilse {\n    yaz(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\ndeğişken info = user.bilgi();\neğer (info.length > 0) {\n    yaz(\"✓ Test 4 passed: bilgi() method works\");\n    yaz(\"  Info: \" + info);\n} değilse {\n    yaz(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nyaz(\"\\n============================================================\");\nyaz(\"All User tests completed!\");\nyaz(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nsınıf NotificationService {\n    işlev send(to, subject, message) {\n        yaz(\"   📧 Email gönderildi:\");\n        yaz(\"      Kime: \" + to);\n        yaz(\"      Konu: \" + subject);\n        yaz(\"      Mesaj: \" + message);\n        dön doğru;\n    }\n    \n    işlev sendSms(phone, message) {\n        yaz(\"   📱 SMS gönderildi:\");\n        yaz(\"      Numara: \" + phone);\n        yaz(\"      Mesaj: \" + message);\n        dön doğru;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nsınıf PaymentService {\n    işlev process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        değişken success = doğru; // Gerçekte API çağrısı yapılır\n        \n        eğer (success) {\n            dön {\n                success: doğru,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } değilse {\n            dön {\n                success: yanlış,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    işlev refund(transactionId) {\n        dön {\n            success: doğru,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nsınıf AuthService {\n    kurucu() {\n        kendi.userCount = 0;\n    }\n    \n    işlev register(user) {\n        kendi.userCount = kendi.userCount + 1;\n        dön {\n            success: doğru,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    işlev login(email, password) {\n        // Basitleştirilmiş login\n        dön {\n            success: doğru,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    işlev logout(token) {\n        dön { success: doğru };\n    }\n    \n    işlev verifyToken(token) {\n        dön { valid: doğru, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nsınıf User {\n    kurucu(name, email, password) {\n        kendi.id = Math.floor(Math.random() * 10000);\n        kendi.name = name;\n        kendi.email = email;\n        kendi.password = password;\n        kendi.createdAt = \"2024-03-07\";\n    }\n    \n    işlev bilgi() {\n        dön \"User #\" + kendi.id + \": \" + kendi.name + \" (\" + kendi.email + \")\";\n    }\n    \n    işlev getId() {\n        dön kendi.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nsınıf Product {\n    kurucu(name, price, stock, category) {\n        kendi.id = Math.floor(Math.random() * 10000);\n        kendi.name = name;\n        kendi.price = price;\n        kendi.stock = stock;\n        kendi.category = category;\n    }\n    \n    işlev bilgi() {\n        dön kendi.name + \" - \" + kendi.price + \" TL (Stok: \" + kendi.stock + \", Kategori: \" + kendi.category + \")\";\n    }\n    \n    işlev inStock() {\n        dön kendi.stock > 0;\n    }\n    \n    işlev getId() {\n        dön kendi.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nsınıf Order {\n    kurucu(userId, productId, quantity, totalPrice) {\n        kendi.id = Math.floor(Math.random() * 10000);\n        kendi.userId = userId;\n        kendi.productId = productId;\n        kendi.quantity = quantity;\n        kendi.totalPrice = totalPrice;\n        kendi.status = \"pending\";\n        kendi.createdAt = \"2024-03-07\";\n    }\n    \n    işlev bilgi() {\n        dön \"Sipariş #\" + kendi.id + \" - Kullanıcı: \" + kendi.userId + \", Ürün: \" + kendi.productId + \", Adet: \" + kendi.quantity + \", Toplam: \" + kendi.totalPrice + \" TL, Durum: \" + kendi.status;\n    }\n    \n    işlev confirm() {\n        kendi.status = \"confirmed\";\n    }\n    \n    işlev getId() {\n        dön kendi.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nişlev random_string(length) {\n    dön \"random_\" + length;\n}\n\nişlev sleep(ms) {\n    // Bekleme simülasyonu\n    yaz(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nişlev log(message) {\n    yaz(\"[LOG] \" + message);\n}\n\nişlev error(message) {\n    yaz(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nsınıf Formatting {\n    statik işlev currency(amount, currency) {\n        eğer (currency == \"TRY\") {\n            dön amount + \" ₺\";\n        } değilse {\n            eğer (currency == \"USD\") {\n                dön \"$\" + amount;\n            } değilse {\n                eğer (currency == \"EUR\") {\n                    dön \"€\" + amount;\n                } değilse {\n                    dön amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    statik işlev date(date) {\n        dön date;\n    }\n    \n    statik işlev phone(phone) {\n        // (555) 123-4567 formatı\n        dön \"(\" + phone + \")\";\n    }\n    \n    statik işlev number(num) {\n        // 1,234,567 formatı\n        dön num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nsınıf Validation {\n    statik işlev email(email) {\n        // Basit email doğrulama\n        dön email.length > 5;\n    }\n    \n    statik işlev password(password) {\n        // Şifre en az 6 karakter olmalı\n        dön password.length >= 6;\n    }\n    \n    statik işlev price(price) {\n        dön price > 0;\n    }\n    \n    statik işlev phone(phone) {\n        // Telefon numarası doğrulama\n        dön phone.length == 10;\n    }\n    \n    statik işlev required(value) {\n        dön value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\ndeğişken APP_NAME = \"My Project\";\ndeğişken APP_VERSION = \"1.0.0\";\ndeğişken MAX_UPLOAD_SIZE = 10485760; // 10MB\ndeğişken SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\ndeğişken STATUS_PENDING = \"pending\";\ndeğişken STATUS_APPROVED = \"approved\";\ndeğişken STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\ndeğişken DB_HOST = \"localhost\";\ndeğişken DB_PORT = 5432;\ndeğişken DB_NAME = \"myproject_db\";\ndeğişken DB_USER = \"admin\";\ndeğişken DB_PASSWORD = \"secure_password\";\n\nişlev get_connection_string() {\n    dön \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\ndeğişken API_BASE_URL = \"https://api.example.com\";\ndeğişken API_VERSION = \"v1\";\ndeğişken API_TIMEOUT = 30000;\n\nişlev get_api_url(endpoint) {\n    dön API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n"}, "vi": {"main.hudhud": "// E-Ticaret Sistemi - Ana Giriş Noktası\n// Main Entry Point\n\n// Modelleri içe aktar\n\"src/models/user.hudhud\" sử_dụng;\n\"src/models/product.hudhud\" sử_dụng;\n\"src/models/order.hudhud\" sử_dụng;\n\n// Servisleri içe aktar\n\"src/services/auth.hudhud\" sử_dụng;\n\"src/services/payment.hudhud\" sử_dụng;\n\"src/services/notification.hudhud\" sử_dụng;\n\n// Yardımcı lớpları içe aktar\n\"src/utils/validation.hudhud\" sử_dụng;\n\"src/utils/formatting.hudhud\" sử_dụng;\n\nin(\"============================================================\");\nin(\"E-Ticaret Sistemi - Modüler Mimari Demo\");\nin(\"============================================================\\n\");\n\n// Servis örnekleri oluştur\nbiến authService = mới AuthService();\nbiến paymentService = mới PaymentService();\nbiến notificationService = mới NotificationService();\n\nin(\"1️⃣  KULLANICI KAYDI\");\nin(\"─────────────────────────────────────────────────────────\\n\");\n\n// Yeni sử_dụngıcı oluştur\nbiến newUser = mới User(\"Davut Süleyman\", \"davut@example.com\", \"güvenli123\");\nin(\"Kullanıcı oluşturuldu: \" + newUser.bilgi());\n\n// Email đúngla\nnếu (Validation.email(newUser.email)) {\n    in(\"✓ Email geçerli: \" + newUser.email);\n} nếu_không {\n    in(\"✗ Email geçersiz\");\n}\n\n// Kullanıcıyı kaydet\nbiến authResult = authService.register(newUser);\nnếu (authResult.success) {\n    in(\"✓ \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    \n    // Hoş geldin bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Hoş Geldiniz!\",\n        \"Aramıza hoş geldiniz, \" + newUser.name\n    );\n}\n\nin(\"\\n2️⃣  ÜRÜN OLUŞTURMA\");\nin(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ürün oluştur\nbiến product = mới Product(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nin(\"Ürün oluşturuldu: \" + product.bilgi());\n\n// Fiyat đúngla\nnếu (Validation.price(product.price)) {\n    in(\"✓ Fiyat geçerli: \" + Formatting.currency(product.price, \"TRY\"));\n}\n\n// Stok kontrolü\nnếu (product.inStock()) {\n    in(\"✓ Ürün stokta mevcut\");\n} nếu_không {\n    in(\"✗ Ürün stokta yok\");\n}\n\nin(\"\\n3️⃣  SİPARİŞ OLUŞTURMA\");\nin(\"─────────────────────────────────────────────────────────\\n\");\n\n// Sipariş oluştur\nbiến order = mới Order(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nin(\"Sipariş oluşturuldu: \" + order.bilgi());\n\nin(\"\\n4️⃣  ÖDEME İŞLEMİ\");\nin(\"─────────────────────────────────────────────────────────\\n\");\n\n// Ödeme işle\nbiến paymentResult = paymentService.process(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\nnếu (paymentResult.success) {\n    in(\"✓ \" + paymentResult.message);\n    in(\"  İşlem No: \" + paymentResult.transactionId);\n    in(\"  Tutar: \" + Formatting.currency(paymentResult.amount, \"TRY\"));\n    in(\"  Yöntem: \" + paymentResult.method);\n    \n    // Siparişi onayla\n    order.confirm();\n    in(\"✓ Sipariş onaylandı: \" + order.status);\n    \n    // Sipariş onay bildirimi\n    notificationService.send(\n        newUser.email,\n        \"Siparişiniz Onaylandı\",\n        \"Sipariş numaranız: \" + order.id + \" - Toplam: \" + Formatting.currency(order.totalPrice, \"TRY\")\n    );\n} nếu_không {\n    in(\"✗ Ödeme başarısız: \" + paymentResult.error);\n}\n\nin(\"\\n============================================================\");\nin(\"✓ E-Ticaret sistemi demo tamamlandı!\");\nin(\"✓ Modüler, ölçeklenebilir ve bakımı kolay mimari\");\nin(\"============================================================\");\n", "tests/auth.test.hudhud": "// Auth Service Tests\n\n\"../src/models/user.hudhud\" sử_dụng;\n\"../src/services/auth.hudhud\" sử_dụng;\n\nin(\"============================================================\");\nin(\"Auth Service Tests\");\nin(\"============================================================\\n\");\n\n// Test 1: Create AuthService instance\nbiến authService = mới AuthService();\nin(\"✓ Test 1 passed: AuthService instance created\");\n\n// Test 2: Registration with valid user\nbiến user = mới User(\"Test User\", \"test@example.com\", \"test123\");\nbiến result1 = authService.register(user);\n\nnếu (result1.success) {\n    in(\"✓ Test 2 passed: Registration successful\");\n    in(\"  User ID: \" + result1.userId);\n    in(\"  Message: \" + result1.message);\n} nếu_không {\n    in(\"✗ Test 2 failed: Registration failed\");\n}\n\n// Test 3: Login\nbiến loginResult = authService.login(\"test@example.com\", \"test123\");\n\nnếu (loginResult.success) {\n    in(\"✓ Test 3 passed: Login successful\");\n    in(\"  Token: \" + loginResult.token);\n    in(\"  Message: \" + loginResult.message);\n} nếu_không {\n    in(\"✗ Test 3 failed: Login failed\");\n}\n\n// Test 4: Verify token\nbiến verifyResult = authService.verifyToken(loginResult.token);\n\nnếu (verifyResult.valid) {\n    in(\"✓ Test 4 passed: Token verification successful\");\n    in(\"  User ID: \" + verifyResult.userId);\n} nếu_không {\n    in(\"✗ Test 4 failed: Token verification failed\");\n}\n\nin(\"\\n============================================================\");\nin(\"All Auth tests completed!\");\nin(\"============================================================\");\n", "tests/user.test.hudhud": "// User Model Tests\n\n\"../src/models/user.hudhud\" sử_dụng;\n\nin(\"============================================================\");\nin(\"User Model Tests\");\nin(\"============================================================\\n\");\n\n// Test 1: User creation\nbiến user = mới User(\"Test User\", \"test@example.com\", \"test123\");\n\nnếu (user.name == \"Test User\") {\n    in(\"✓ Test 1 passed: User creation\");\n} nếu_không {\n    in(\"✗ Test 1 failed: Expected 'Test User', got '\" + user.name + \"'\");\n}\n\n// Test 2: Email validation\nnếu (user.email == \"test@example.com\") {\n    in(\"✓ Test 2 passed: Email set correctly\");\n} nếu_không {\n    in(\"✗ Test 2 failed: Expected 'test@example.com', got '\" + user.email + \"'\");\n}\n\n// Test 3: ID generation\nnếu (user.id > 0) {\n    in(\"✓ Test 3 passed: ID generated (ID: \" + user.id + \")\");\n} nếu_không {\n    in(\"✗ Test 3 failed: ID not generated\");\n}\n\n// Test 4: bilgi() method\nbiến info = user.bilgi();\nnếu (info.length > 0) {\n    in(\"✓ Test 4 passed: bilgi() method works\");\n    in(\"  Info: \" + info);\n} nếu_không {\n    in(\"✗ Test 4 failed: bilgi() method returned empty\");\n}\n\nin(\"\\n============================================================\");\nin(\"All User tests completed!\");\nin(\"============================================================\");\n", "src/services/notification.hudhud": "// Notification Service - Bildirim Servisi\n\nlớp NotificationService {\n    hàm send(to, subject, message) {\n        in(\"   📧 Email gönderildi:\");\n        in(\"      Kime: \" + to);\n        in(\"      Konu: \" + subject);\n        in(\"      Mesaj: \" + message);\n        trả_về đúng;\n    }\n    \n    hàm sendSms(phone, message) {\n        in(\"   📱 SMS gönderildi:\");\n        in(\"      Numara: \" + phone);\n        in(\"      Mesaj: \" + message);\n        trả_về đúng;\n    }\n}\n", "src/services/payment.hudhud": "// Payment Service - Ödeme Servisi\n\nlớp PaymentService {\n    hàm process(orderId, amount, method) {\n        // Basitleştirilmiş ödeme işlemi\n        biến success = đúng; // Gerçekte API çağrısı yapılır\n        \n        nếu (success) {\n            trả_về {\n                success: đúng,\n                transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n                amount: amount,\n                method: method,\n                message: \"Ödeme başarılı\"\n            };\n        } nếu_không {\n            trả_về {\n                success: sai,\n                error: \"Ödeme başarısız\"\n            };\n        }\n    }\n    \n    hàm refund(transactionId) {\n        trả_về {\n            success: đúng,\n            refundId: \"REF_\" + Math.floor(Math.random() * 100000)\n        };\n    }\n}\n", "src/services/auth.hudhud": "// Authentication Service - Kimlik Doğrulama Servisi\n\nlớp AuthService {\n    khởi_tạo() {\n        tự.userCount = 0;\n    }\n    \n    hàm register(user) {\n        tự.userCount = tự.userCount + 1;\n        trả_về {\n            success: đúng,\n            userId: user.id,\n            message: \"Kullanıcı başarıyla kaydedildi\"\n        };\n    }\n    \n    hàm login(email, password) {\n        // Basitleştirilmiş login\n        trả_về {\n            success: đúng,\n            token: \"token_\" + Math.floor(Math.random() * 1000),\n            message: \"Giriş başarılı\"\n        };\n    }\n    \n    hàm logout(token) {\n        trả_về { success: đúng };\n    }\n    \n    hàm verifyToken(token) {\n        trả_về { valid: đúng, userId: \"user_123\" };\n    }\n}\n", "src/models/user.hudhud": "// User Model - Kullanıcı Modeli\n\nlớp User {\n    khởi_tạo(name, email, password) {\n        tự.id = Math.floor(Math.random() * 10000);\n        tự.name = name;\n        tự.email = email;\n        tự.password = password;\n        tự.createdAt = \"2024-03-07\";\n    }\n    \n    hàm bilgi() {\n        trả_về \"User #\" + tự.id + \": \" + tự.name + \" (\" + tự.email + \")\";\n    }\n    \n    hàm getId() {\n        trả_về tự.id;\n    }\n}\n", "src/models/product.hudhud": "// Product Model - Ürün Modeli\n\nlớp Product {\n    khởi_tạo(name, price, stock, category) {\n        tự.id = Math.floor(Math.random() * 10000);\n        tự.name = name;\n        tự.price = price;\n        tự.stock = stock;\n        tự.category = category;\n    }\n    \n    hàm bilgi() {\n        trả_về tự.name + \" - \" + tự.price + \" TL (Stok: \" + tự.stock + \", Kategori: \" + tự.category + \")\";\n    }\n    \n    hàm inStock() {\n        trả_về tự.stock > 0;\n    }\n    \n    hàm getId() {\n        trả_về tự.id;\n    }\n}\n", "src/models/order.hudhud": "// Order Model - Sipariş Modeli\n\nlớp Order {\n    khởi_tạo(userId, productId, quantity, totalPrice) {\n        tự.id = Math.floor(Math.random() * 10000);\n        tự.userId = userId;\n        tự.productId = productId;\n        tự.quantity = quantity;\n        tự.totalPrice = totalPrice;\n        tự.status = \"pending\";\n        tự.createdAt = \"2024-03-07\";\n    }\n    \n    hàm bilgi() {\n        trả_về \"Sipariş #\" + tự.id + \" - Kullanıcı: \" + tự.userId + \", Ürün: \" + tự.productId + \", Adet: \" + tự.quantity + \", Toplam: \" + tự.totalPrice + \" TL, Durum: \" + tự.status;\n    }\n    \n    hàm confirm() {\n        tự.status = \"confirmed\";\n    }\n    \n    hàm getId() {\n        trả_về tự.id;\n    }\n}\n", "src/utils/helpers.hudhud": "// Helper Utilities - Yardımcı Fonksiyonlar\n\nhàm random_string(length) {\n    trả_về \"random_\" + length;\n}\n\nhàm sleep(ms) {\n    // Bekleme simülasyonu\n    in(\"Bekleniyor: \" + ms + \"ms\");\n}\n\nhàm log(message) {\n    in(\"[LOG] \" + message);\n}\n\nhàm error(message) {\n    in(\"[ERROR] \" + message);\n}\n", "src/utils/formatting.hudhud": "// Formatting Utilities - Formatlama Fonksiyonları\n\nlớp Formatting {\n    tĩnh hàm currency(amount, currency) {\n        nếu (currency == \"TRY\") {\n            trả_về amount + \" ₺\";\n        } nếu_không {\n            nếu (currency == \"USD\") {\n                trả_về \"$\" + amount;\n            } nếu_không {\n                nếu (currency == \"EUR\") {\n                    trả_về \"€\" + amount;\n                } nếu_không {\n                    trả_về amount + \" \" + currency;\n                }\n            }\n        }\n    }\n    \n    tĩnh hàm date(date) {\n        trả_về date;\n    }\n    \n    tĩnh hàm phone(phone) {\n        // (555) 123-4567 formatı\n        trả_về \"(\" + phone + \")\";\n    }\n    \n    tĩnh hàm number(num) {\n        // 1,234,567 formatı\n        trả_về num;\n    }\n}\n", "src/utils/validation.hudhud": "// Validation Utilities - Doğrulama Fonksiyonları\n\nlớp Validation {\n    tĩnh hàm email(email) {\n        // Basit email đúnglama\n        trả_về email.length > 5;\n    }\n    \n    tĩnh hàm password(password) {\n        // Şifre en az 6 karakter olmalı\n        trả_về password.length >= 6;\n    }\n    \n    tĩnh hàm price(price) {\n        trả_về price > 0;\n    }\n    \n    tĩnh hàm phone(phone) {\n        // Telefon numarası đúnglama\n        trả_về phone.length == 10;\n    }\n    \n    tĩnh hàm required(value) {\n        trả_về value.length > 0;\n    }\n}\n", "src/config/constants.hudhud": "// Constants - Sabitler\n\nbiến APP_NAME = \"My Project\";\nbiến APP_VERSION = \"1.0.0\";\nbiến MAX_UPLOAD_SIZE = 10485760; // 10MB\nbiến SUPPORTED_LANGUAGES = [\"tr\", \"en\", \"de\"];\n\nbiến STATUS_PENDING = \"pending\";\nbiến STATUS_APPROVED = \"approved\";\nbiến STATUS_REJECTED = \"rejected\";\n", "src/config/database.hudhud": "// Database Configuration - Veritabanı Ayarları\n\nbiến DB_HOST = \"localhost\";\nbiến DB_PORT = 5432;\nbiến DB_NAME = \"myproject_db\";\nbiến DB_USER = \"admin\";\nbiến DB_PASSWORD = \"secure_password\";\n\nhàm get_connection_string() {\n    trả_về \"postgresql://\" + DB_USER + \"@\" + DB_HOST + \":\" + DB_PORT + \"/\" + DB_NAME;\n}\n", "src/config/api.hudhud": "// API Configuration - API Ayarları\n\nbiến API_BASE_URL = \"https://api.example.com\";\nbiến API_VERSION = \"v1\";\nbiến API_TIMEOUT = 30000;\n\nhàm get_api_url(endpoint) {\n    trả_về API_BASE_URL + \"/\" + API_VERSION + \"/\" + endpoint;\n}\n", "package.json": "{\n  \"name\": \"my-project\",\n  \"version\": \"1.0.0\",\n  \"description\": \"E-ticaret uygulaması\",\n  \"main\": \"main.hudhud\",\n  \"author\": \"Davut Süleyman\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cebir\": \"^1.0.0\",\n    \"fizik\": \"^1.0.0\"\n  },\n  \"scripts\": {\n    \"start\": \"hudhud run main.hudhud\",\n    \"test\": \"hudhud test tests/\",\n    \"build\": \"hudhud compile main.hudhud\"\n  }\n}"}};
window.STATIC_SAMPLES_CACHE = {"ar": {"objects": "// العربية - الكائنات\n// الكائنات بالكلمات المفتاحية الأصلية\n\n// إنشاء كائن\nمتغير شخص = {\n    الاسم: \"فاطمة\",\n    العمر: 25,\n    المدينة: \"القاهرة\"\n};\n\n// الوصول إلى الخصائص\nمتغير الاسم = شخص.الاسم;\nمتغير العمر = شخص.العمر;\n\n// كائن آخر\nمتغير سيارة = {\n    العلامة: \"تويوتا\",\n    السنة: 2023,\n    اللون: \"أزرق\"\n};\n", "chemistry": "// العربية - وحدة الكيمياء\n\nدالة الكتلة_المولارية(ذرات, الوزن_الذري) {\n    ارجع ذرات * الوزن_الذري;\n}\n\nدالة التركيز(مولات, حجم) {\n    ارجع مولات / حجم;\n}\n\nدالة الأس_الهيدروجيني(تركيز_الهيدروجين) {\n    ارجع 14 - تركيز_الهيدروجين;\n}\n\nدالة الكثافة(كتلة, حجم) {\n    ارجع كتلة / حجم;\n}\n\nدالة التخفيف(ت1, ح1, ح2) {\n    ارجع (ت1 * ح1) / ح2;\n}\n", "loops": "// العربية - الحلقات\n// أمثلة على الحلقات بالكلمات المفتاحية الأصلية\n\n// حلقة بسيطة - مجموع من 1 إلى 5\nمتغير مجموع = 0;\nمتغير عداد = 1;\n\nبينما (عداد <= 5) {\n    مجموع = مجموع + عداد;\n    عداد = عداد + 1;\n}\n\nمجموع;\n", "data_processing": "// العربية - معالجة البيانات\n// معالجة البيانات بالكلمات المفتاحية العربية\n\n// تعريف البيانات\nمتغير قيمة1 = 100;\nمتغير قيمة2 = 200;\nمتغير قيمة3 = 300;\n\n// الحساب\nمتغير المجموع = قيمة1 + قيمة2 + قيمة3;\nمتغير المتوسط = المجموع / 3;\n\n// المعالجة الشرطية\nإذا (المتوسط > 150) {\n    متغير الحالة = \"مرتفع\";\n} وإلا {\n    متغير الحالة = \"منخفض\";\n}\n\nاطبع(\"المجموع: \" + المجموع);\nاطبع(\"المتوسط: \" + المتوسط);\nاطبع(\"الحالة: \" + الحالة);\n", "arrow_functions": "// العربية - دوال السهم\n// صياغة حديثة ومختصرة للدوال\n\n// دالة سهم - صياغة قصيرة\nbila جمع = (أ, ب) => أ + ب;\nbila ضرب = (س, ص) => س * ص;\n\nitbaa(جمع(5, 3));      // 8\nitbaa(ضرب(4, 7)); // 28\n\n// دالة سهم مع كتلة\nbila حساب = (أ, ب) => {\n    bila مجموع = أ + ب;\n    bila حاصل_الضرب = أ * ب;\n    arji مجموع + حاصل_الضرب;\n};\n\nbila نتيجة = حساب(5, 3);\nitbaa(نتيجة);  // 23 (8 + 15)\n\n// معامل واحد (لا حاجة لأقواس)\nbila مربع = س => س * س;\nitbaa(مربع(6));  // 36\n\n// بدون معاملات\nbila تحية = () => \"مرحبا!\";\nitbaa(تحية());  // مرحبا!\n", "modules_import": "// العربية - Modules Import Example\n\n// Import math module (direct access)\nاستخدم \"رياضيات.هدهد\";\n\n// Import physics with alias (access via fizik.functionName)\nاستخدم \"فيزياء.هدهد\" كـ fizik;\n\n// Import chemistry (direct access)\nاستخدم \"كيمياء.هدهد\";\n\n// Using math functions (direct)\nمتغير sum = اجمع(10, 5);\nاطبع(sum);\n\nمتغير product = اضرب(4, 7);\nاطبع(product);\n\n// Using physics functions (via alias: fizik.functionName)\nمتغير f = fizik.قوة(10, 9.8);\nاطبع(f);\n\nمتغير ke = fizik.طاقةحركية(5, 10);\nاطبع(ke);\n\n// Using chemistry functions (direct)\nمتغير d = كثافة(100, 50);\nاطبع(d);\n\nمتغير c = تركيز(2, 5);\nاطبع(c);\n", "return_concept": "// العربية - مفهوم الإرجاع\n// ارجع\n\nدالة مربع(س) {\n    ارجع س * س;\n}\n\nدالة مكعب(س) {\n    ارجع س * س * س;\n}\n\nاطبع(\"=== دوال رياضية ===\");\nاطبع(\"مربع(5): \" + مربع(5));\nاطبع(\"مكعب(3): \" + مكعب(3));\n\nدالة قيمة_مطلقة(س) {\n    إذا (س < 0) {\n        ارجع -س;\n    }\n    ارجع س;\n}\n\nاطبع(\"=== القيمة المطلقة ===\");\nاطبع(\"قيمة_مطلقة(-7): \" + قيمة_مطلقة(-7));\nاطبع(\"قيمة_مطلقة(3): \" + قيمة_مطلقة(3));\n\nدالة أنشئ_نقطة(س, ص) {\n    ارجع { س: س, ص: ص };\n}\n\nمتغير ن = أنشئ_نقطة(10, 20);\nاطبع(\"=== نقطة ===\");\nاطبع(\"نقطة: (\" + ن.س + \", \" + ن.ص + \")\");\n\nدالة عاملي(ع) {\n    إذا (ع <= 1) {\n        ارجع 1;\n    }\n    ارجع ع * عاملي(ع - 1);\n}\n\nاطبع(\"=== العاملي ===\");\nاطبع(\"5! = \" + عاملي(5));\nاطبع(\"10! = \" + عاملي(10));\n", "customer_service": "// العربية - وكيل خدمة العملاء\nاستخدم \"providers.hudhud\";\n\nقانون قانون_الاحترام {\n    وصف: \"يجب أن يكون الوكيل مهذباً ومحترماً\",\n    أولوية: 1\n}\n\nدستور دستور_الخدمة {\n    قوانين: [قانون_الاحترام],\n    وصف: \"إطار خدمة العملاء\"\n}\n\nوكيل وكيل_الخدمة {\n    مزود: OpenAIProvider,\n    model: \"gpt-4\"\n}\n\nدالة رحب(اسم_العميل) {\n    متغير رسالة = \"مرحباً \" + اسم_العميل + \"، كيف يمكنني مساعدتك؟\";\n    اطبع(رسالة);\n    ارجع رسالة;\n}\n\nدالة عالج_طلب(نوع, تفاصيل) {\n    إذا (نوع == \"شكوى\") {\n        اطبع(\"أعتذر عن الإزعاج. سأساعدك في حل المشكلة.\");\n    } وإلا {\n        اطبع(\"شكراً لتواصلك. سأعالج طلبك الآن.\");\n    }\n    ارجع \"تمت معالجة: \" + نوع + \" - \" + تفاصيل;\n}\n\nاطبع(\"=== وكيل خدمة العملاء ===\");\nاطبع(وكيل_الخدمة.model + \" عبر \" + وكيل_الخدمة.مزود.اسم);\nرحب(\"أحمد\");\nمتغير نتيجة = عالج_طلب(\"شكوى\", \"تأخر الشحن\");\nاطبع(نتيجة);\n", "basic_example": "// العربية - مثال أساسي\n// مثال أساسي بالكلمات المفتاحية الأصلية\n\nمتغير س = 10;\nمتغير ص = 20;\nمتغير مجموع = س + ص;\n\nاطبع(مجموع);\n", "physics": "// العربية - وحدة الفيزياء\n\nدالة السرعة(مسافة, زمن) {\n    ارجع مسافة / زمن;\n}\n\nدالة القوة(كتلة, تسارع) {\n    ارجع كتلة * تسارع;\n}\n\nدالة الطاقة_الحركية(كتلة, سرعة) {\n    ارجع 0.5 * كتلة * سرعة * سرعة;\n}\n\nدالة الطاقة_الكامنة(كتلة, جاذبية, ارتفاع) {\n    ارجع كتلة * جاذبية * ارتفاع;\n}\n\nدالة الزخم(كتلة, سرعة) {\n    ارجع كتلة * سرعة;\n}\n", "error_handling": "// Arabic - إدارة الأخطاء\n// التحكم في الأخطاء باستخدام if-else\n\n// دالة للتحقق من الأخطاء\nوظيفة تقسيم(أ، ب) {\n    إذا (ب == 0) {\n        إرجاع { خطأ: صحيح، رسالة: \"خطأ القسمة على صفر\"، قيمة: 0 };\n    }\n    إرجاع { خطأ: خطأ، رسالة: \"\"، قيمة: أ / ب };\n}\n\nاطبع(\"=== عملية القسمة ===\");\n\n// أول عملية قسمة\nاطبع(\"عملية 10 / 2:\");\nمتغير نتيجة1 = تقسيم(10، 2);\nإذا (نتيجة1.خطأ) {\n    اطبع(\"خطأ: \" + نتيجة1.رسالة);\n} وإلا {\n    اطبع(\"10 / 2 = \" + نتيجة1.قيمة);\n}\n\n// القسمة على صفر\nاطبع(\"عملية 10 / 0:\");\nمتغير نتيجة2 = تقسيم(10، 0);\nإذا (نتيجة2.خطأ) {\n    اطبع(\"تم اكتشاف الخطأ: \" + نتيجة2.رسالة);\n} وإلا {\n    اطبع(\"النتيجة: \" + نتيجة2.قيمة);\n}\n\nاطبع(\"تم الانتهاء\");\n", "package_usage": "// استخدام الحزم - نظام حزم هدهد سكريبت\n// نظام إدارة الحزم: إنشاء، تثبيت، نشر واستخدام\n\n// ============================================================\n// 1. استخدام الحزم\n// ============================================================\n\n// استخدام حزمة خارجية\nاستخدم \"جبر\";\nاستخدم \"فيزياء\";\n\n// استيراد وحدات محددة من الحزمة\nاستخدم \"جبر/مصفوفة\";\nاستخدم \"جبر/متجه\";\nاستخدم \"فيزياء/حركة\";\n\nاطبع(\"============================================================\");\nاطبع(\"عرض نظام حزم هدهد سكريبت\");\nاطبع(\"============================================================\\n\");\n\n// ============================================================\n// 2. استخدام دوال الحزم\n// ============================================================\n\nاطبع(\"استخدام حزمة الجبر:\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\n// إنشاء مصفوفة\nمتغير مصفوفة1 = مصفوفة([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nمتغير مصفوفة2 = مصفوفة([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nاطبع(\"المصفوفة 1:\");\nمصفوفة1.اعرض();\n\nاطبع(\"\\nالمصفوفة 2:\");\nمصفوفة2.اعرض();\n\n// جمع المصفوفات\nمتغير المجموع = مصفوفة1.اجمع(مصفوفة2);\nاطبع(\"\\nجمع المصفوفات:\");\nالمجموع.اعرض();\n\n// عمليات المتجهات\nمتغير متجه1 = متجه([1, 2, 3]);\nمتغير متجه2 = متجه([4, 5, 6]);\n\nاطبع(\"\\n\\nعمليات المتجهات:\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\nاطبع(\"المتجه 1: \" + متجه1.نص());\nاطبع(\"المتجه 2: \" + متجه2.نص());\n\nمتغير الجداء_النقطي = متجه1.جداء_نقطي(متجه2);\nاطبع(\"الجداء النقطي: \" + الجداء_النقطي);\n\nمتغير الجداء_التقاطعي = متجه1.جداء_تقاطعي(متجه2);\nاطبع(\"الجداء التقاطعي: \" + الجداء_التقاطعي.نص());\n\n// ============================================================\n// 3. استخدام حزمة الفيزياء\n// ============================================================\n\nاطبع(\"\\n\\nاستخدام حزمة الفيزياء:\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\n// حسابات الحركة\nمتغير السرعة_الابتدائية = 0;      // م/ث\nمتغير التسارع = 9.8;               // م/ث² (الجاذبية)\nمتغير الزمن = 5;                    // ثانية\n\nمتغير السرعة_النهائية = حركة.احسب_السرعة(السرعة_الابتدائية, التسارع, الزمن);\nمتغير المسافة = حركة.احسب_المسافة(السرعة_الابتدائية, التسارع, الزمن);\n\nاطبع(\"السرعة الابتدائية: \" + السرعة_الابتدائية + \" م/ث\");\nاطبع(\"التسارع: \" + التسارع + \" م/ث²\");\nاطبع(\"الزمن: \" + الزمن + \" ث\");\nاطبع(\"─────────────────────────────────────────────────────────\");\nاطبع(\"السرعة النهائية: \" + السرعة_النهائية + \" م/ث\");\nاطبع(\"المسافة المقطوعة: \" + المسافة + \" م\");\n\n// ============================================================\n// 4. إنشاء الحزم\n// ============================================================\n\nاطبع(\"\\n\\nإنشاء الحزم:\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\nاطبع(\"1. أنشئ ملف hudhud.toml:\");\nاطبع(\"   [حزمة]\");\nاطبع(\"   الاسم = 'أدوات-رياضية'\");\nاطبع(\"   الإصدار = '1.0.0'\");\nاطبع(\"   الوصف = 'دوال مساعدة للرياضيات'\");\n\nاطبع(\"\\n2. أضف التبعيات:\");\nاطبع(\"   [تبعيات]\");\nاطبع(\"   جبر = '^2.0.0'\");\nاطبع(\"   فيزياء = '^1.5.0'\");\n\n// ============================================================\n// 5. أوامر إدارة الحزم\n// ============================================================\n\nاطبع(\"\\n\\nأوامر إدارة الحزم:\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\nاطبع(\"تثبيت حزمة:\");\nاطبع(\"  hudhudscript install جبر\");\nاطبع(\"  hudhudscript install فيزياء@1.5.0\");\n\nاطبع(\"\\nتحديث حزمة:\");\nاطبع(\"  hudhudscript update جبر\");\nاطبع(\"  hudhudscript update --all\");\n\nاطبع(\"\\nإزالة حزمة:\");\nاطبع(\"  hudhudscript remove جبر\");\n\nاطبع(\"\\nعرض الحزم المثبتة:\");\nاطبع(\"  hudhudscript list\");\n\nاطبع(\"\\nالبحث عن حزمة:\");\nاطبع(\"  hudhudscript search رياضيات\");\n\nاطبع(\"\\nمعلومات الحزمة:\");\nاطبع(\"  hudhudscript info جبر\");\n\n// ============================================================\n// 6. تبعيات الحزم\n// ============================================================\n\nاطبع(\"\\n\\nتبعيات الحزم:\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\nاطبع(\"تحديد الإصدار:\");\nاطبع(\"  'جبر' = '^2.0.0'    # 2.x.x\");\nاطبع(\"  'فيزياء' = '~1.5.0'    # 1.5.x\");\nاطبع(\"  'كيمياء' = '1.2.3'     # إصدار محدد\");\n\nاطبع(\"\\nمن مستودع جت:\");\nاطبع(\"  'مكتبتي' = { git = 'https://github.com/user/my-lib' }\");\n\nاطبع(\"\\nمن مسار محلي:\");\nاطبع(\"  'مكتبة-محلية' = { path = '../مكتبة-محلية' }\");\n\n// ============================================================\n// 7. أمان الحزم\n// ============================================================\n\nاطبع(\"\\n\\nأمان الحزم:\");\nاطبع(\"─────────────────────────────────────────────────────────\\n\");\n\nاطبع(\"فحص الأمان:\");\nاطبع(\"  hudhudscript audit\");\n\nاطبع(\"\\nالتحقق من المجموع:\");\nاطبع(\"  hudhudscript verify جبر\");\n\nاطبع(\"\\n============================================================\");\nاطبع(\"تم الانتهاء من عرض نظام الحزم!\");\nاطبع(\"اكتب كودًا معياريًا وقابلًا لإعادة الاستخدام مع هدهد سكريبت\");\nاطبع(\"============================================================\");\n", "arrays": "// العربية - المصفوفات\n// المصفوفات بالكلمات المفتاحية الأصلية\n\n// إنشاء المصفوفات\nمتغير أرقام = [1, 2, 3, 4, 5];\nمتغير أسماء = [\"فاطمة\", \"أحمد\", \"مريم\"];\n\n// الوصول إلى العناصر\nمتغير الأول = أرقام[0];\nمتغير الثاني = أرقام[1];\n\n// مصفوفة فارغة\nمتغير قائمة = [];\n", "math": "// العربية - وحدة الرياضيات\n\nدالة اجمع(أ, ب) {\n    ارجع أ + ب;\n}\n\nدالة اطرح(أ, ب) {\n    ارجع أ - ب;\n}\n\nدالة اضرب(أ, ب) {\n    ارجع أ * ب;\n}\n\nدالة اقسم(أ, ب) {\n    إذا (ب == 0) {\n        اطبع(\"خطأ: القسمة على صفر!\");\n        ارجع 0;\n    } وإلا {\n        ارجع أ / ب;\n    }\n}\n\nدالة مربع(س) {\n    ارجع س * س;\n}\n\nدالة مكعب(س) {\n    ارجع س * س * س;\n}\n\nدالة قيمة_مطلقة(س) {\n    إذا (س < 0) {\n        ارجع -س;\n    } وإلا {\n        ارجع س;\n    }\n}\n\nدالة الأكبر(أ, ب) {\n    إذا (أ > ب) {\n        ارجع أ;\n    } وإلا {\n        ارجع ب;\n    }\n}\n\nدالة الأصغر(أ, ب) {\n    إذا (أ < ب) {\n        ارجع أ;\n    } وإلا {\n        ارجع ب;\n    }\n}\n", "control_flow": "// العربية - تدفق التحكم\nمتغير عداد = 0;\nمتغير الحد = 5;\n\n// حلقة\nبينما (عداد < الحد) {\n    عداد = عداد + 1;\n}\n\n// شرط\nمتغير درجة = 85;\n\nإذا (درجة >= 90) {\n    درجة;\n} وإلا {\n    إذا (درجة >= 80) {\n        درجة;\n    } وإلا {\n        درجة;\n    }\n}\n\nعداد;\n", "state_machine": "// State Machine Example\nمتغير state = \"initial\";\n\nإذا (state == \"initial\") {\n    اطبع(\"Starting\");\n    state = \"running\";\n}\n\nاطبع(state);\n", "conditionals": "// العربية - المنطق الشرطي\nمتغير درجة = 85;\n\nإذا (درجة >= 90) {\n    درجة;\n} وإلا {\n    إذا (درجة >= 80) {\n        درجة;\n    } وإلا {\n        درجة;\n    }\n}\n", "code_organization": "// العربية - تنظيم الكود حسب الموضوع\n// تنظيم الكود في مجلدات منطقية\n\n// هيكل المشروع:\n//\n// مشروع/\n//   ├── وكيل/\n//   │   ├── تعريف_الوكيل.hudhud\n//   │   ├── مهام_الوكيل.hudhud\n//   │   ├── أدوات_الوكيل.hudhud\n//   │   └── موفرات_الوكيل.hudhud\n//   │\n//   ├── دستور/\n//   │   ├── الدستور.hudhud\n//   │   ├── القوانين.hudhud\n//   │   ├── القواعد.hudhud\n//   │   ├── مجموعة_القواعد.hudhud\n//   │   └── سلسلة_القواعد.hudhud\n//   │\n//   ├── بيانات/\n//   │   ├── نغمة.hudhud\n//   │   ├── وتر.hudhud\n//   │   ├── لحن.hudhud\n//   │   ├── تناغم.hudhud\n//   │   └── إيقاع.hudhud\n//   │\n//   ├── حوكمة/\n//   │   ├── مجلس.hudhud\n//   │   ├── سرب.hudhud\n//   │   ├── مجتمع.hudhud\n//   │   └── تنفيذ.hudhud\n//   │\n//   ├── تدفق/\n//   │   ├── تدفق_البيانات.hudhud\n//   │   ├── طبقة.hudhud\n//   │   ├── شبكة.hudhud\n//   │   └── تنسيق.hudhud\n//   │\n//   ├── حالة/\n//   │   ├── كيان.hudhud\n//   │   ├── آلة_الحالة.hudhud\n//   │   ├── حدث.hudhud\n//   │   └── نية.hudhud\n//   │\n//   └── أدوات/\n//       ├── رياضيات.hudhud\n//       ├── فيزياء.hudhud\n//       ├── كيمياء.hudhud\n//       └── مساعدات.hudhud\n\n// فوائد هذا التنظيم:\n// 1. فصل واضح للمسؤوليات\n// 2. سهولة العثور على الكود المرتبط\n// 3. قابل للتوسع للمشاريع الكبيرة\n// 4. مناسب لتعاون الفريق\n// 5. وحدات قابلة للصيانة\n\n// أمثلة على الاستيراد:\n// استخدم \"وكيل/تعريف_الوكيل.hudhud\";\n// استخدم \"دستور/القوانين.hudhud\";\n// استخدم \"بيانات/نغمة.hudhud\";\n// استخدم \"أدوات/رياضيات.hudhud\";\n", "module_concepts": "// عربي - Modules & Code Organization\n// Demonstrates module system: use/import like Rust, Java, C++, Python\n\n// Import math module\nuse \"math.hudhud\";\n\n// Example syntax variations:\n// use \"math.hudhud\";\n// use { add, subtract } from \"math.hudhud\";\n// use \"math.hudhud\" as math;\n\n// Using functions from math module\nمتغير sum = add(10, 5);\nاطبع(sum);\n\nمتغير diff = subtract(20, 8);\nاطبع(diff);\n\nمتغير product = multiply(4, 7);\nاطبع(product);\n\nمتغير quotient = divide(15, 3);\nاطبع(quotient);\n\nمتغير squared = square(5);\nاطبع(squared);\n\nمتغير cubed = cube(3);\nاطبع(cubed);\n\nمتغير absolute = abs(-42);\nاطبع(absolute);\n\nمتغير maximum = max(100, 50);\nاطبع(maximum);\n\nمتغير minimum = min(100, 50);\nاطبع(minimum);\n\n// Complex calculation using multiple functions\nمتغير result = add(multiply(5, 3), divide(20, 4));\nاطبع(result);\n", "higher_order_functions": "// العربية - دوال عالية الرتبة\n// دوال تعمل مع دوال اخرى\n\n// دالة تعيد دالة\ndawl مضاعف(عامل) {\n    arji (س) => س * عامل;\n}\n\nbila ضعف = مضاعف(2);\nbila ثلاثة_اضعاف = مضاعف(3);\n\nitbaa(ضعف(5));  // 10\nitbaa(ثلاثة_اضعاف(5));  // 15\n\n// دالة تاخذ دالة\ndawl طبق(دالة, قيمة) {\n    arji دالة(قيمة);\n}\n\nitbaa(طبق(ضعف, 10));  // 20\n\n// مثال على التركيب\ndawl ركب(د1, د2) {\n    arji (س) => د1(د2(س));\n}\n\nbila اضف_واحد = (س) => س + 1;\nbila اضرب_باثنين = (س) => س * 2;\n\nbila اضف_ثم_اضرب = ركب(اضرب_باثنين, اضف_واحد);\nitbaa(اضف_ثم_اضرب(5));  // 12 (5+1=6, 6*2=12)\n", "switch_concepts": "// Arabic - مفاهيم Switch/Case\n// استخدام if-else للشروط المتعددة\n\nوظيفة نوع_اليوم(يوم) {\n    إذا (يوم == \"الإثنين\") { إرجاع \"يوم عمل\"; }\n    إذا (يوم == \"الثلاثاء\") { إرجاع \"يوم عمل\"; }\n    إذا (يوم == \"الأربعاء\") { إرجاع \"يوم عمل\"; }\n    إذا (يوم == \"الخميس\") { إرجاع \"يوم عمل\"; }\n    إذا (يوم == \"الجمعة\") { إرجاع \"يوم عمل\"; }\n    إذا (يوم == \"السبت\") { إرجاع \"عطلة نهاية الأسبوع\"; }\n    إذا (يوم == \"الأحد\") { إرجاع \"عطلة نهاية الأسبوع\"; }\n    إرجاع \"غير معروف\";\n}\n\nاطبع(\"=== أنواع الأيام ===\");\nاطبع(\"الإثنين: \" + نوع_اليوم(\"الإثنين\"));\nاطبع(\"السبت: \" + نوع_اليوم(\"السبت\"));\n\nوظيفة حالة_الشبكة(كود) {\n    إذا (كود == 200) { إرجاع \"OK\"; }\n    إذا (كود == 404) { إرجاع \"غير موجود\"; }\n    إذا (كود == 500) { إرجاع \"خطأ في الخادم\"; }\n    إرجاع \"حالة غير معروفة\";\n}\n\nاطبع(\"=== حالة HTTP ===\");\nاطبع(\"200: \" + حالة_الشبكة(200));\nاطبع(\"404: \" + حالة_الشبكة(404));\n", "event_concepts": "// العربية - مفاهيم الأحداث\n\nحدث تسجيل_دخول {\n    اطبع(\"تم تسجيل الدخول\");\n}\n\nحدث استلام_بيانات {\n    اطبع(\"تم استلام البيانات\");\n}\n\nحدث حدوث_خطأ {\n    اطبع(\"حدث خطأ\");\n}\n\nدالة عند_تسجيل(اسم_مستخدم) {\n    اطبع(\"تسجيل دخول: \" + اسم_مستخدم);\n    ارجع \"مرحباً, \" + اسم_مستخدم;\n}\n\nدالة عند_بيانات(مصدر) {\n    اطبع(\"بيانات من: \" + مصدر);\n    ارجع \"تمت المعالجة: \" + مصدر;\n}\n\nدالة عند_خطأ(رسالة) {\n    اطبع(\"خطأ: \" + رسالة);\n    ارجع \"تمت المعالجة: \" + رسالة;\n}\n\nاطبع(\"=== نظام الأحداث ===\");\nمتغير ن1 = عند_تسجيل(\"المشرف\");\nاطبع(ن1);\nمتغير ن2 = عند_بيانات(\"المستشعر_1\");\nاطبع(ن2);\nمتغير ن3 = عند_خطأ(\"انتهت المهلة\");\nاطبع(ن3);\n", "functions": "// العربية - الدوال\n// أمثلة على تعريف واستخدام الدوال\n\n// دالة بسيطة\nدالة رحب() {\n    اطبع(\"مرحباً بالعالم!\");\n}\n\n// دالة مع معاملات\nدالة اجمع(أ, ب) {\n    ارجع أ + ب;\n}\n\n// دالة متعددة المعاملات\nدالة احسب(رقم١, رقم٢, عملية) {\n    إذا (عملية == \"جمع\") {\n        ارجع رقم١ + رقم٢;\n    } وإلا إذا (عملية == \"طرح\") {\n        ارجع رقم١ - رقم٢;\n    } وإلا إذا (عملية == \"ضرب\") {\n        ارجع رقم١ * رقم٢;\n    } وإلا إذا (عملية == \"قسمة\") {\n        ارجع رقم١ / رقم٢;\n    } وإلا {\n        ارجع 0;\n    }\n}\n\n// دوال رياضية\nدالة مربع(س) {\n    ارجع س * س;\n}\n\nدالة مكعب(س) {\n    ارجع س * س * س;\n}\n\n// استخدام الدوال\nرحب();\n\nمتغير نتيجة١ = اجمع(5, 3);\nاطبع(نتيجة١);\n\nمتغير نتيجة٢ = احسب(10, 5, \"جمع\");\nاطبع(نتيجة٢);\n\nمتغير نتيجة٣ = احسب(10, 5, \"ضرب\");\nاطبع(نتيجة٣);\n\nمتغير نتيجة_مربع = مربع(4);\nاطبع(نتيجة_مربع);\n\nمتغير نتيجة_مكعب = مكعب(3);\nاطبع(نتيجة_مكعب);\n\n// تركيب الدوال\nمتغير المجموع = اجمع(مربع(3), مكعب(2));\nاطبع(المجموع);\n", "entity_concepts": "// العربية - مفاهيم الكيانات\n\nمتغير مستخدم = {\n    معرف: 1,\n    اسم: \"علياء\",\n    بريد: \"aliyaa@example.com\",\n    دور: \"مطورة\"\n};\n\nمتغير منتج = {\n    معرف: 101,\n    اسم: \"محرر هدهد سكريبت\",\n    إصدار: \"2.0\",\n    سعر: 49\n};\n\nمتغير طلب = {\n    معرف: 1001,\n    معرف_مستخدم: 1,\n    معرف_منتج: 101,\n    كمية: 2,\n    حالة: \"مؤكد\"\n};\n\nدالة معلومات_كيان(كيان) {\n    ارجع \"كيان #\" + كيان.معرف + \": \" + كيان.اسم;\n}\n\nدالة احسب_المجموع(طلب, سعر) {\n    ارجع طلب.كمية * سعر;\n}\n\nاطبع(\"=== نظام الكيانات ===\");\nاطبع(معلومات_كيان(مستخدم));\nاطبع(معلومات_كيان(منتج));\nمتغير المجموع = احسب_المجموع(طلب, منتج.سعر);\nاطبع(\"طلب #\" + طلب.معرف + \" المجموع: \" + المجموع);\nاطبع(\"الحالة: \" + طلب.حالة);\n", "error_concepts": "// Arabic - مفاهيم الخطأ\n// دوال التحقق البسيطة\n\nوظيفة التحقق_من_العمر(عمر) {\n    إذا (عمر < 0) {\n        إرجاع { صالح: خطأ، خطأ: \"عمر غير صالح: سالب\" };\n    }\n    إذا (عمر > 150) {\n        إرجاع { صالح: خطأ، خطأ: \"عمر غير صالح: كبير جداً\" };\n    }\n    إرجاع { صالح: صحيح، عمر: عمر };\n}\n\nوظيفة التحقق_من_البريد(بريد) {\n    إذا (بريد == \"\") {\n        إرجاع { صالح: خطأ، خطأ: \"بريد فارغ\" };\n    }\n    إرجاع { صالح: صحيح، بريد: بريد };\n}\n\nاطبع(\"=== التحقق ===\");\n\nمتغير نتيجة_العمر1 = التحقق_من_العمر(25);\nإذا (نتيجة_العمر1.صالح) {\n    اطبع(\"العمر 25 صالح\");\n} وإلا {\n    اطبع(\"خطأ: \" + نتيجة_العمر1.خطأ);\n}\n\nمتغير نتيجة_العمر2 = التحقق_من_العمر(-5);\nإذا (نتيجة_العمر2.صالح) {\n    اطبع(\"العمر صالح\");\n} وإلا {\n    اطبع(\"خطأ: \" + نتيجة_العمر2.خطأ);\n}\n\nاطبع(\"اكتمل التحقق\");\n", "رياضيات": "// العربية - Math Module\n\nدالة اجمع(a, b) {\n    ارجع a + b;\n}\n\nدالة اطرح(a, b) {\n    ارجع a - b;\n}\n\nدالة اضرب(a, b) {\n    ارجع a * b;\n}\n\nدالة اقسم(a, b) {\n    إذا (b == 0) {\n        اطبع(\"Error: Division by zero!\");\n        ارجع 0;\n    } وإلا {\n        ارجع a / b;\n    }\n}\n\nدالة مربع(x) {\n    ارجع x * x;\n}\n\nدالة مكعب(x) {\n    ارجع x * x * x;\n}\n\nدالة مطلق(x) {\n    إذا (x < 0) {\n        ارجع -x;\n    } وإلا {\n        ارجع x;\n    }\n}\n\nدالة اكبر(a, b) {\n    إذا (a > b) {\n        ارجع a;\n    } وإلا {\n        ارجع b;\n    }\n}\n\nدالة اصغر(a, b) {\n    إذا (a < b) {\n        ارجع a;\n    } وإلا {\n        ارجع b;\n    }\n}\n", "كيمياء": "// العربية - Chemistry Module\n\nدالة كتلةمولية(atoms, atomicWeight) {\n    ارجع atoms * atomicWeight;\n}\n\nدالة تركيز(moles, volume) {\n    ارجع moles / volume;\n}\n\nدالة pH(hydrogenConcentration) {\n    ارجع 14 - hydrogenConcentration;\n}\n\nدالة كثافة(mass, volume) {\n    ارجع mass / volume;\n}\n\nدالة تخفيف(c1, v1, v2) {\n    ارجع (c1 * v1) / v2;\n}\n", "فيزياء": "// العربية - Physics Module\n\nدالة سرعة(distance, time) {\n    ارجع distance / time;\n}\n\nدالة قوة(mass, acceleration) {\n    ارجع mass * acceleration;\n}\n\nدالة طاقةحركية(mass, velocity) {\n    ارجع 0.5 * mass * velocity * velocity;\n}\n\nدالة طاقةكامنة(mass, gravity, height) {\n    ارجع mass * gravity * height;\n}\n\nدالة زخم(mass, velocity) {\n    ارجع mass * velocity;\n}\n"}, "ja": {"objects": "// 日本語 - オブジェクト\n// オブジェクトのネイティブキーワード\n\n// オブジェクトを作成\n変数 人 = {\n    名前: \"花子\",\n    年齢: 30,\n    都市: \"東京\"\n};\n\n// プロパティにアクセス\n変数 名前 = 人.名前;\n変数 年齢 = 人.年齢;\n\n// 結果\n名前;\n", "chemistry": "// JA - Chemistry Module\n\n// Molar Mass\n関数 molarMass(atoms, atomicWeight) {\n    戻る atoms * atomicWeight;\n}\n\n// Concentration = Moles / Volume\n関数 concentration(moles, volume) {\n    戻る moles / volume;\n}\n\n// pH calculation\n関数 pH(hydrogenConcentration) {\n    戻る 14 - hydrogenConcentration;\n}\n\n// Density = Mass / Volume\n関数 density(mass, volume) {\n    戻る mass / volume;\n}\n\n// Dilution: C1*V1 = C2*V2\n関数 dilution(c1, v1, v2) {\n    戻る (c1 * v1) / v2;\n}\n", "loops": "// 日本語 - Loop Example\n定義 カウンター = 零;\n定義 最大 = 五;\n\n間 (カウンター < 最大) {\n    カウンター = カウンター + 一;\n}\n\nカウンター;", "data_processing": "// 日本語 - Data Processing\n// Using NATIVE 日本語 keywords\n\n定義 データ一 = 百;\n定義 データ二 = 二百;\n定義 データ三 = 三百;\n\n定義 合計 = データ一 + データ二 + データ三;\n定義 平均 = 合計 / 三;\n\n平均;", "arrow_functions": "// 日本語 - アロー関数\n// 関数の簡潔な構文\n\n// アロー関数 - 短い構文\n変数 足す = (a, b) => a + b;\n変数 掛ける = (x, y) => x * y;\n\n表示(足す(5, 3));      // 8\n表示(掛ける(4, 7)); // 28\n\n// ブロック付きアロー関数\n変数 計算する = (a, b) => {\n    変数 合計 = a + b;\n    変数 積 = a * b;\n    返す 合計 + 積;\n};\n\n変数 結果 = 計算する(5, 3);\n表示(結果);  // 23 (8 + 15)\n\n// 単一パラメータ（括弧不要）\n変数 二乗 = x => x * x;\n表示(二乗(6));  // 36\n\n// パラメータなし\n変数 挨拶 = () => \"こんにちは！\";\n表示(挨拶());  // こんにちは！\n", "modules_import": "// 日本語 - Modules Import Example\n\n// Import math module (direct access)\nuse \"sugaku.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nuse \"butsuri.hudhud\";\n\n// Import chemistry (direct access)\nuse \"kagaku.hudhud\";\n\n// Using math functions (direct)\n変数 sum = tasu(10, 5);\n\n変数 product = kakeru(4, 7);\n\n// Using physics functions (via alias: fizik.functionName)\n変数 f = fizik.chikara(10, 9.8);\n\n変数 ke = fizik.undoEnergi(5, 10);\n\n// Using chemistry functions (direct)\n変数 d = mitsudo(100, 50);\n\n変数 c = nodo(2, 5);\n", "return_concept": "// 日本語 - 戻り値の概念\n// return\n\n関数 square(x) {\n    返す x * x;\n}\n\n関数 cube(x) {\n    返す x * x * x;\n}\n\n表示(\"=== Math Functions ===\");\n表示(\"square(5): \" + square(5));\n表示(\"cube(3): \" + cube(3));\n\n関数 絶対値(x) {\n    もし (x < 0) {\n        返す -x;\n    }\n    返す x;\n}\n\n表示(\"\\n=== Absolute ===\");\n表示(\"絶対値(-7): \" + 絶対値(-7));\n表示(\"絶対値(3): \" + 絶対値(3));\n\n関数 点作成(x, y) {\n    返す { x: x, y: y };\n}\n\n変数 p = 点作成(10, 20);\n表示(\"\\n=== Point ===\");\n表示(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\n関数 階乗(n) {\n    もし (n <= 1) {\n        返す 1;\n    }\n    返す n * 階乗(n - 1);\n}\n\n表示(\"\\n=== Factorial ===\");\n表示(\"5! = \" + 階乗(5));\n表示(\"10! = \" + 階乗(10));\n", "customer_service": "// 日本語 - Customer Service Agent\n// Using NATIVE 日本語 keywords\n\n定義 挨拶 = \"こんにちは、どのようにお手伝いできますか？\";\n定義 応答 = \"ご要望にお応えいたします。\";\n\n挨拶;", "basic_example": "// 日本語 - Basic Example with NATIVE keywords\n変数 エックス = 10;\n変数 ワイ = 210;\n変数 合計 = エックス + ワイ;\n", "physics": "// JA - Physics Module\n\n// Speed = Distance / Time\n関数 speed(distance, time) {\n    戻る distance / time;\n}\n\n// Force = Mass * Acceleration\n関数 force(mass, acceleration) {\n    戻る mass * acceleration;\n}\n\n// Kinetic Energy = 0.5 * Mass * Velocity^2\n関数 kineticEnergy(mass, velocity) {\n    戻る 0.5 * mass * velocity * velocity;\n}\n\n// Potential Energy = Mass * Gravity * Height\n関数 potentialEnergy(mass, gravity, height) {\n    戻る mass * gravity * height;\n}\n\n// Momentum = Mass * Velocity\n関数 momentum(mass, velocity) {\n    戻る mass * velocity;\n}\n", "error_handling": "// Japanese - エラー処理\n// if-elseによるエラー制御\n\n関数 割り算(a, b) {\n    もし (b == 0) {\n        返す { エラー: 真, メッセージ: \"ゼロ除算エラー\", 値: 0 };\n    }\n    返す { エラー: 偽, メッセージ: \"\", 値: a / b };\n}\n\n表示(\"=== 除算処理 ===\");\n\n表示(\"10 / 2 の計算:\");\n変数 結果1 = 割り算(10, 2);\nもし (結果1.エラー) {\n    表示(\"エラー: \" + 結果1.メッセージ);\n} そうでないなら {\n    表示(\"10 / 2 = \" + 結果1.値);\n}\n\n表示(\"10 / 0 の計算:\");\n変数 結果2 = 割り算(10, 0);\nもし (結果2.エラー) {\n    表示(\"エラー検出: \" + 結果2.メッセージ);\n} そうでないなら {\n    表示(\"結果: \" + 結果2.値);\n}\n\n表示(\"完了\");\n", "package_usage": "// パッケージ使用法 - ハドハドスクリプト パッケージシステム\n// パッケージ管理システム: 作成、インストール、公開、使用\n\n// ============================================================\n// 1. パッケージの使用\n// ============================================================\n\n// 外部パッケージの使用\n使う \"代数\";\n使う \"物理\";\n\n// パッケージから特定モジュールをインポート\n使う \"代数/行列\";\n使う \"代数/ベクトル\";\n使う \"物理/運動\";\n\n表示(\"============================================================\");\n表示(\"ハドハドスクリプト パッケージシステムのデモ\");\n表示(\"============================================================\\n\");\n\n// ============================================================\n// 2. パッケージ関数の使用\n// ============================================================\n\n表示(\"代数パッケージの使用:\");\n表示(\"─────────────────────────────────────────────────────────\\n\");\n\n// 行列の作成\n変数 行列1 = 行列([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\n変数 行列2 = 行列([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\n表示(\"行列 1:\");\n行列1.表示する();\n\n表示(\"\\n行列 2:\");\n行列2.表示する();\n\n// 行列の加算\n変数 合計 = 行列1.足す(行列2);\n表示(\"\\n行列の加算:\");\n合計.表示する();\n\n// ベクトル演算\n変数 ベクトル1 = ベクトル([1, 2, 3]);\n変数 ベクトル2 = ベクトル([4, 5, 6]);\n\n表示(\"\\n\\nベクトル演算:\");\n表示(\"─────────────────────────────────────────────────────────\\n\");\n\n表示(\"ベクトル 1: \" + ベクトル1.文字列());\n表示(\"ベクトル 2: \" + ベクトル2.文字列());\n\n変数 内積 = ベクトル1.内積(ベクトル2);\n表示(\"内積: \" + 内積);\n\n変数 外積 = ベクトル1.外積(ベクトル2);\n表示(\"外積: \" + 外積.文字列());\n\n// ============================================================\n// 3. 物理パッケージの使用\n// ============================================================\n\n表示(\"\\n\\n物理パッケージの使用:\");\n表示(\"─────────────────────────────────────────────────────────\\n\");\n\n// 運動計算\n変数 初速度 = 0;        // メートル毎秒\n変数 加速度 = 9.8;      // メートル毎秒二乗 (重力)\n変数 時間 = 5;           // 秒\n\n変数 終速度 = 運動.速度計算(初速度, 加速度, 時間);\n変数 距離 = 運動.距離計算(初速度, 加速度, 時間);\n\n表示(\"初速度: \" + 初速度 + \" メートル毎秒\");\n表示(\"加速度: \" + 加速度 + \" メートル毎秒二乗\");\n表示(\"時間: \" + 時間 + \" 秒\");\n表示(\"─────────────────────────────────────────────────────────\");\n表示(\"終速度: \" + 終速度 + \" メートル毎秒\");\n表示(\"移動距離: \" + 距離 + \" メートル\");\n\n// ============================================================\n// 4. パッケージの作成\n// ============================================================\n\n表示(\"\\n\\nパッケージの作成:\");\n表示(\"─────────────────────────────────────────────────────────\\n\");\n\n表示(\"1. hudhud.toml ファイルを作成:\");\n表示(\"   [パッケージ]\");\n表示(\"   名前 = '数学ユーティリティ'\");\n表示(\"   バージョン = '1.0.0'\");\n表示(\"   説明 = '数学ヘルパー関数'\");\n\n表示(\"\\n2. 依存関係を追加:\");\n表示(\"   [依存関係]\");\n表示(\"   代数 = '^2.0.0'\");\n表示(\"   物理 = '^1.5.0'\");\n\n// ============================================================\n// 5. パッケージ管理コマンド\n// ============================================================\n\n表示(\"\\n\\nパッケージ管理コマンド:\");\n表示(\"─────────────────────────────────────────────────────────\\n\");\n\n表示(\"パッケージのインストール:\");\n表示(\"  hudhudscript install 代数\");\n表示(\"  hudhudscript install 物理@1.5.0\");\n\n表示(\"\\nパッケージの更新:\");\n表示(\"  hudhudscript update 代数\");\n表示(\"  hudhudscript update --all\");\n\n表示(\"\\nパッケージの削除:\");\n表示(\"  hudhudscript remove 代数\");\n\n表示(\"\\nインストール済みパッケージの一覧:\");\n表示(\"  hudhudscript list\");\n\n表示(\"\\nパッケージの検索:\");\n表示(\"  hudhudscript search 数学\");\n\n表示(\"\\nパッケージ情報:\");\n表示(\"  hudhudscript info 代数\");\n\n// ============================================================\n// 6. パッケージの依存関係\n// ============================================================\n\n表示(\"\\n\\nパッケージの依存関係:\");\n表示(\"─────────────────────────────────────────────────────────\\n\");\n\n表示(\"バージョン指定:\");\n表示(\"  '代数' = '^2.0.0'    # 2.x.x\");\n表示(\"  '物理' = '~1.5.0'    # 1.5.x\");\n表示(\"  '化学' = '1.2.3'     # 正確なバージョン\");\n\n表示(\"\\nGitリポジトリから:\");\n表示(\"  'マイライブラリ' = { git = 'https://github.com/user/my-lib' }\");\n\n表示(\"\\nローカルパスから:\");\n表示(\"  'ローカルライブラリ' = { path = '../ローカルライブラリ' }\");\n\n// ============================================================\n// 7. パッケージのセキュリティ\n// ============================================================\n\n表示(\"\\n\\nパッケージのセキュリティ:\");\n表示(\"─────────────────────────────────────────────────────────\\n\");\n\n表示(\"セキュリティ監査:\");\n表示(\"  hudhudscript audit\");\n\n表示(\"\\nチェックサム検証:\");\n表示(\"  hudhudscript verify 代数\");\n\n表示(\"\\n============================================================\");\n表示(\"パッケージシステムのデモが完了しました!\");\n表示(\"ハドハドスクリプトでモジュール化された再利用可能なコードを書きましょう\");\n表示(\"============================================================\");\n", "arrays": "// 日本語 - 配列\n// 配列のネイティブキーワード\n\n// 配列を作成\n変数 数字 = [1, 2, 3, 4, 5];\n変数 名前リスト = [\"花子\", \"太郎\", \"次郎\"];\n\n// 要素にアクセス\n変数 最初 = 数字[0];\n変数 番目 = 数字[1];\n\n// 結果\n最初;\n", "math": "// JA - Math Module\n\n// Addition\n関数 add(a, b) {\n    戻る a + b;\n}\n\n// Subtraction\n関数 subtract(a, b) {\n    戻る a - b;\n}\n\n// Multiplication\n関数 multiply(a, b) {\n    戻る a * b;\n}\n\n// Division\n関数 divide(a, b) {\n    もし (b == 0) {\n        表示(\"Error: Division by zero!\");\n        戻る 0;\n    } それでも {\n        戻る a / b;\n    }\n}\n\n// Square\n関数 square(x) {\n    戻る x * x;\n}\n\n// Cube\n関数 cube(x) {\n    戻る x * x * x;\n}\n\n// Absolute value\n関数 abs(x) {\n    もし (x < 0) {\n        戻る -x;\n    } それでも {\n        戻る x;\n    }\n}\n\n// Maximum\n関数 max(a, b) {\n    もし (a > b) {\n        戻る a;\n    } それでも {\n        戻る b;\n    }\n}\n\n// Minimum\n関数 min(a, b) {\n    もし (a < b) {\n        戻る a;\n    } それでも {\n        戻る b;\n    }\n}\n", "control_flow": "// 日本語 - 制御フロー\n定義 カウンター = 0;\n定義 最大 = 5;\n\n// ループ\n間 (カウンター < 最大) {\n    カウンター = カウンター + 1;\n}\n\n// 条件\n定義 点数 = 85;\n\nもし (点数 >= 90) {\n    点数;\n} それでも {\n    もし (点数 >= 80) {\n        点数;\n    } それでも {\n        点数;\n    }\n}\n\nカウンター;\n", "state_machine": "// State Machine Example\n定義 state = \"initial\";\n\nもし (state == \"initial\") {\n    表示(\"Starting\");\n    state = \"running\";\n}\n\n表示(state);\n", "conditionals": "// 日本語 - Conditional Logic\n定義 点数 = 八十五;\n\nもし (点数 >= 九十) {\n    点数;\n} それでも {\n    もし (点数 >= 八十) {\n        点数;\n    } それでも {\n        点数;\n    }\n}\n", "code_organization": "// 日本語 - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable 各 large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// tsukau \"agent/agent_definition.hudhud\";\n// tsukau \"constitution/laws.hudhud\";\n// tsukau \"data/note.hudhud\";\n// tsukau \"utils/math.hudhud\";\n", "module_concepts": "// 日本語 - Modules & Code Organization\n// Demonstrates module system: tsukau/インポート like Rust, Java, C++, Python\n\n// Import math module\n\"math.hudhud\" kullan;\n\n// Example syntax variations:\n// tsukau \"math.hudhud\";\n// \"math.hudhud\" kara { add, subtract } tsukau;\n// tsukau \"math.hudhud\" toshite math;\n\n// Using functions から math module\n定義 sum = add(10, 5);\ninsatsu(sum);\n\n定義 diff = subtract(20, 8);\ninsatsu(diff);\n\n定義 product = multiply(4, 7);\ninsatsu(product);\n\n定義 quotient = divide(15, 3);\ninsatsu(quotient);\n\n定義 squared = square(5);\ninsatsu(squared);\n\n定義 cubed = cube(3);\ninsatsu(cubed);\n\n定義 absolute = abs(-42);\ninsatsu(absolute);\n\n定義 maximum = max(100, 50);\ninsatsu(maximum);\n\n定義 minimum = min(100, 50);\ninsatsu(minimum);\n\n// Complex calculation using multiple functions\n定義 result = add(multiply(5, 3), divide(20, 4));\ninsatsu(result);\n", "higher_order_functions": "// 日本語 - 高階関数\n// 他の関数と連携する関数\n\n// 関数を返す関数\n関数 乗数器(係数) {\n    返す (x) => x * 係数;\n}\n\n変数 二倍 = 乗数器(2);\n変数 三倍 = 乗数器(3);\n\n表示(二倍(5));  // 10\n表示(三倍(5));  // 15\n\n// 関数を受け取る関数\n関数 適用(関数引数, 値) {\n    返す 関数引数(値);\n}\n\n表示(適用(二倍, 10));  // 20\n\n// 合成の例\n関数 合成(f, g) {\n    返す (x) => f(g(x));\n}\n\n変数 一を足す = (x) => x + 1;\n変数 二を掛ける = (x) => x * 2;\n\n変数 足して掛ける = 合成(二を掛ける, 一を足す);\n表示(足して掛ける(5));  // 12 (5+1=6, 6*2=12)\n", "kagaku": "// 日本語 - Chemistry Module\n\n関数 moruShitsuryou(atoms, atomicWeight) {\n    戻る atoms * atomicWeight;\n}\n\n関数 nodo(moles, volume) {\n    戻る moles / volume;\n}\n\n関数 pH(hydrogenConcentration) {\n    戻る 14 - hydrogenConcentration;\n}\n\n関数 mitsudo(mass, volume) {\n    戻る mass / volume;\n}\n\n関数 kishaku(c1, v1, v2) {\n    戻る (c1 * v1) / v2;\n}\n", "switch_concepts": "// Japanese - Switch/Case概念\n// if-elseによる複数条件分岐\n\n関数 曜日タイプ(曜日) {\n    もし (曜日 == \"月曜日\") { 返す \"平日\"; }\n    もし (曜日 == \"火曜日\") { 返す \"平日\"; }\n    もし (曜日 == \"水曜日\") { 返す \"平日\"; }\n    もし (曜日 == \"木曜日\") { 返す \"平日\"; }\n    もし (曜日 == \"金曜日\") { 返す \"平日\"; }\n    もし (曜日 == \"土曜日\") { 返す \"週末\"; }\n    もし (曜日 == \"日曜日\") { 返す \"週末\"; }\n    返す \"不明\";\n}\n\n表示(\"=== 曜日タイプ ===\");\n表示(\"月曜日: \" + 曜日タイプ(\"月曜日\"));\n表示(\"土曜日: \" + 曜日タイプ(\"土曜日\"));\n\n関数 ステータスメッセージ(コード) {\n    もし (コード == 200) { 返す \"OK\"; }\n    もし (コード == 404) { 返す \"見つかりません\"; }\n    もし (コード == 500) { 返す \"サーバーエラー\"; }\n    返す \"不明なステータス\";\n}\n\n表示(\"=== HTTPステータス ===\");\n表示(\"200: \" + ステータスメッセージ(200));\n表示(\"404: \" + ステータスメッセージ(404));\n", "event_concepts": "// 日本語 - Event Concepts\n\nイベント UserLogin {\n    表示(\"User logged in\");\n}\n\nイベント DataReceived {\n    表示(\"Data received\");\n}\n\nイベント ErrorOccurred {\n    表示(\"Error occurred\");\n}\n\n関数 on_login(username) {\n    表示(\"Login: \" + username);\n    返す \"Welcome, \" + username;\n}\n\n関数 on_data(source) {\n    表示(\"Data from: \" + source);\n    返す \"Processed: \" + source;\n}\n\n関数 on_error(message) {\n    表示(\"Error: \" + message);\n    返す \"Handled: \" + message;\n}\n\n表示(\"=== Event System ===\");\n変数 r1 = on_login(\"admin\");\n表示(r1);\n変数 r2 = on_data(\"sensor_1\");\n表示(r2);\n変数 r3 = on_error(\"timeout\");\n表示(r3);\n", "functions": "// 日本語 - 関数\n// 関数の定義と使用例\n\n// 簡単な関数\n関数 挨拶() {\n    表示(\"こんにちは世界!\");\n}\n\n// 引数付き関数\n関数 足す(甲, 乙) {\n    戻る 甲 + 乙;\n}\n\n// 複数引数の関数\n関数 計算(数１, 数２, 操作) {\n    もし (操作 == \"足す\") {\n        戻る 数１ + 数２;\n    } それでも {\n        戻る 0;\n    }\n}\n\n// 数学関数\n関数 二乗(値) {\n    戻る 値 * 値;\n}\n\n関数 三乗(値) {\n    戻る 値 * 値 * 値;\n}\n\n// 関数の使用\n挨拶();\n\n変数 結果1 = 足す(5, 3);\n表示(結果1);\n\n変数 結果2 = 計算(10, 5, \"足す\");\n表示(結果2);\n\n変数 二乗の結果 = 二乗(4);\n表示(二乗の結果);\n\n変数 三乗の結果 = 三乗(3);\n表示(三乗の結果);\n\n// 関数の合成\n変数 合計 = 足す(二乗(3), 三乗(2));\n表示(合計);\n", "entity_concepts": "// 日本語 - エンティティ概念\n\n変数 利用者 = {\n    識別子: 1,\n    名前: \"花子\",\n    メール: \"hanako@example.com\",\n    役割: \"開発者\"\n};\n\n変数 製品 = {\n    識別子: 101,\n    名前: \"ハドハドスクリプト開発環境\",\n    バージョン: \"2.0\",\n    価格: 49\n};\n\n変数 注文 = {\n    識別子: 1001,\n    利用者識別子: 1,\n    製品識別子: 101,\n    数量: 2,\n    状態: \"確認済み\"\n};\n\n関数 エンティティ情報(エンティティ) {\n    返す \"エンティティ #\" + エンティティ.識別子 + \": \" + エンティティ.名前;\n}\n\n関数 合計計算(注文, 価格) {\n    返す 注文.数量 * 価格;\n}\n\n表示(\"=== エンティティシステム ===\");\n表示(エンティティ情報(利用者));\n表示(エンティティ情報(製品));\n変数 合計 = 合計計算(注文, 製品.価格);\n表示(\"注文 #\" + 注文.識別子 + \" 合計: \" + 合計);\n表示(\"状態: \" + 注文.状態);\n", "butsuri": "// 日本語 - Physics Module\n\n関数 sokudo(distance, time) {\n    戻る distance / time;\n}\n\n関数 chikara(mass, acceleration) {\n    戻る mass * acceleration;\n}\n\n関数 undoEnergi(mass, velocity) {\n    戻る 0.5 * mass * velocity * velocity;\n}\n\n関数 ichiEnergi(mass, gravity, height) {\n    戻る mass * gravity * height;\n}\n\n関数 undo(mass, velocity) {\n    戻る mass * velocity;\n}\n", "sugaku": "// 日本語 - Math Module\n\n関数 tasu(a, b) {\n    戻る a + b;\n}\n\n関数 hiku(a, b) {\n    戻る a - b;\n}\n\n関数 kakeru(a, b) {\n    戻る a * b;\n}\n\n関数 waru(a, b) {\n    もし (b == 0) {\n        insatsu(\"Error: Division by zero!\");\n        戻る 0;\n    } それでも {\n        戻る a / b;\n    }\n}\n\n関数 jijo(x) {\n    戻る x * x;\n}\n\n関数 sanjo(x) {\n    戻る x * x * x;\n}\n\n関数 zettaichi(x) {\n    もし (x < 0) {\n        戻る -x;\n    } それでも {\n        戻る x;\n    }\n}\n\n関数 saidai(a, b) {\n    もし (a > b) {\n        戻る a;\n    } それでも {\n        戻る b;\n    }\n}\n\n関数 saisho(a, b) {\n    もし (a < b) {\n        戻る a;\n    } それでも {\n        戻る b;\n    }\n}\n", "error_concepts": "// Japanese - エラー概念\n// 単純な検証関数\n\n関数 年齢検証(年齢) {\n    もし (年齢 < 0) {\n        返す { 有効: 偽, エラー: \"無効な年齢: 負の値\" };\n    }\n    もし (年齢 > 150) {\n        返す { 有効: 偽, エラー: \"無効な年齢: 大きすぎる\" };\n    }\n    返す { 有効: 真, 年齢: 年齢 };\n}\n\n表示(\"=== 検証 ===\");\n\n変数 年齢結果1 = 年齢検証(25);\nもし (年齢結果1.有効) {\n    表示(\"年齢25は有効です\");\n} そうでないなら {\n    表示(\"エラー: \" + 年齢結果1.エラー);\n}\n\n変数 年齢結果2 = 年齢検証(-5);\nもし (年齢結果2.有効) {\n    表示(\"年齢は有効です\");\n} そうでないなら {\n    表示(\"エラー: \" + 年齢結果2.エラー);\n}\n\n表示(\"検証完了\");\n"}, "zh": {"objects": "// 中文 - 对象\n// 对象与原生关键词\n\n// 创建对象\n变量 人 = {\n    姓名: \"小红\",\n    年龄: 30,\n    城市: \"北京\"\n};\n\n// 访问属性\n变量 姓名 = 人.姓名;\n变量 年龄 = 人.年龄;\n\n// 结果\n姓名;\n", "chemistry": "// ZH - Chemistry Module\n\n// Molar Mass\n函数 molarMass(atoms, atomicWeight) {\n    返回 atoms * atomicWeight;\n}\n\n// Concentration = Moles / Volume\n函数 concentration(moles, volume) {\n    返回 moles / volume;\n}\n\n// pH calculation\n函数 pH(hydrogenConcentration) {\n    返回 14 - hydrogenConcentration;\n}\n\n// Density = Mass / Volume\n函数 density(mass, volume) {\n    返回 mass / volume;\n}\n\n// Dilution: C1*V1 = C2*V2\n函数 dilution(c1, v1, v2) {\n    返回 (c1 * v1) / v2;\n}\n", "loops": "// 中文 - 循环\n变量 计数器 = 0;\n变量 最大值 = 5;\n\n当 (计数器 < 最大值) {\n    打印(计数器);\n    计数器 = 计数器 + 1;\n}\n\n打印(999);\n", "data_processing": "// 中文 - 数据处理\n// 使用中文原生关键字\n\n变量 数据1 = 100;\n变量 数据2 = 200;\n变量 数据3 = 300;\n\n变量 总计 = 数据1 + 数据2 + 数据3;\n变量 平均值 = 总计 / 3;\n\n打印(总计);\n打印(平均值);\n", "arrow_functions": "// 中文 - 箭头函数\n// 函数的简洁语法\n\n// 箭头函数 - 简短语法\n变量 加法 = (a, b) => a + b;\n变量 乘法 = (x, y) => x * y;\n\n打印(加法(5, 3));      // 8\n打印(乘法(4, 7)); // 28\n\n// 带代码块的箭头函数\n变量 计算 = (a, b) => {\n    变量 总和 = a + b;\n    变量 乘积 = a * b;\n    返回 总和 + 乘积;\n};\n\n变量 结果 = 计算(5, 3);\n打印(结果);  // 23 (8 + 15)\n\n// 单参数（不需要括号）\n变量 平方 = x => x * x;\n打印(平方(6));  // 36\n\n// 无参数\n变量 问候 = () => \"你好！\";\n打印(问候());  // 你好！\n", "wuli": "// 中文 - Physics Module\n\n函数 速度(distance, time) {\n    返回 distance / time;\n}\n\n函数 力(mass, acceleration) {\n    返回 mass * acceleration;\n}\n\n函数 动能(mass, velocity) {\n    返回 0.5 * mass * velocity * velocity;\n}\n\n函数 势能(mass, gravity, height) {\n    返回 mass * gravity * height;\n}\n\n函数 动量(mass, velocity) {\n    返回 mass * velocity;\n}\n", "modules_import": "// 中文 - Modules Import Example\n\n// Import math module (direct access)\n使用 \"shuxue.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\n使用 \"wuli.hudhud\" 作为 fizik;\n\n// Import chemistry (direct access)\n使用 \"huaxue.hudhud\";\n\n// Using math functions (direct)\n变量 sum = 加(10, 5);\n打印(sum);\n\n变量 product = 乘(4, 7);\n打印(product);\n\n// Using physics functions (via alias: fizik.functionName)\n变量 f = fizik.力(10, 9.8);\n打印(f);\n\n变量 ke = fizik.动能(5, 10);\n打印(ke);\n\n// Using chemistry functions (direct)\n变量 d = 密度(100, 50);\n打印(d);\n\n变量 c = 浓度(2, 5);\n打印(c);\n", "return_concept": "// 中文 - 返回值概念\n// return\n\n函数 平方(x) {\n    返回 x * x;\n}\n\n函数 立方(x) {\n    返回 x * x * x;\n}\n\n打印(\"=== Math Functions ===\");\n打印(\"平方(5): \" + 平方(5));\n打印(\"立方(3): \" + 立方(3));\n\n函数 绝对值(x) {\n    如果 (x < 0) {\n        返回 -x;\n    }\n    返回 x;\n}\n\n打印(\"\\n=== Absolute ===\");\n打印(\"绝对值(-7): \" + 绝对值(-7));\n打印(\"绝对值(3): \" + 绝对值(3));\n\n函数 创建点(x, y) {\n    返回 { x: x, y: y };\n}\n\n变量 p = 创建点(10, 20);\n打印(\"\\n=== Point ===\");\n打印(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\n函数 阶乘(n) {\n    如果 (n <= 1) {\n        返回 1;\n    }\n    返回 n * 阶乘(n - 1);\n}\n\n打印(\"\\n=== Factorial ===\");\n打印(\"5! = \" + 阶乘(5));\n打印(\"10! = \" + 阶乘(10));\n", "customer_service": "// 中文 - 客户服务代理\n\n法律 尊重法则 {\n    描述: \"代理必须礼貌和尊重客户\",\n    优先级: 1\n}\n\n宪法 服务宪法 {\n    法律列表: [尊重法则],\n    描述: \"客户服务框架\"\n}\n\n代理 服务代理 {\n    模型: \"gpt-4\"\n}\n\n函数 欢迎(客户名) {\n    变量 消息 = \"您好 \" + 客户名 + \"，请问有什么可以帮您？\";\n    打印(消息);\n    返回 消息;\n}\n\n函数 处理请求(类型, 详情) {\n    如果 (类型 == \"投诉\") {\n        打印(\"非常抱歉给您带来不便。我会帮您解决问题。\");\n    } 否则 {\n        打印(\"感谢您的联系。我现在为您处理请求。\");\n    }\n    返回 \"已处理: \" + 类型 + \" - \" + 详情;\n}\n\n打印(\"=== 客户服务代理 ===\");\n欢迎(\"小明\");\n变量 结果 = 处理请求(\"投诉\", \"快递延迟\");\n打印(结果);\n", "basic_example": "// 中文 - Basic Example with NATIVE keywords\n变量 变量1 = 10;\n变量 变量2 = 20;\n变量 总和 = 变量1 + 变量2;\n\n打印(总和);\n", "physics": "// ZH - Physics Module\n\n// Speed = Distance / Time\n函数 speed(distance, time) {\n    返回 distance / time;\n}\n\n// Force = Mass * Acceleration\n函数 force(mass, acceleration) {\n    返回 mass * acceleration;\n}\n\n// Kinetic Energy = 0.5 * Mass * Velocity^2\n函数 kineticEnergy(mass, velocity) {\n    返回 0.5 * mass * velocity * velocity;\n}\n\n// Potential Energy = Mass * Gravity * Height\n函数 potentialEnergy(mass, gravity, height) {\n    返回 mass * gravity * height;\n}\n\n// Momentum = Mass * Velocity\n函数 momentum(mass, velocity) {\n    返回 mass * velocity;\n}\n", "shuxue": "// 中文 - Math Module\n\n函数 加(a, b) {\n    返回 a + b;\n}\n\n函数 减(a, b) {\n    返回 a - b;\n}\n\n函数 乘(a, b) {\n    返回 a * b;\n}\n\n函数 除(a, b) {\n    如果 (b == 0) {\n        打印(\"Error: Division by zero!\");\n        返回 0;\n    } 否则 {\n        返回 a / b;\n    }\n}\n\n函数 平方(x) {\n    返回 x * x;\n}\n\n函数 立方(x) {\n    返回 x * x * x;\n}\n\n函数 绝对值(x) {\n    如果 (x < 0) {\n        返回 -x;\n    } 否则 {\n        返回 x;\n    }\n}\n\n函数 最大(a, b) {\n    如果 (a > b) {\n        返回 a;\n    } 否则 {\n        返回 b;\n    }\n}\n\n函数 最小(a, b) {\n    如果 (a < b) {\n        返回 a;\n    } 否则 {\n        返回 b;\n    }\n}\n", "error_handling": "// zh - Error Handling\n// Simple error control with if-else\n\nfunction divide(a, b) {\n    if (b == 0) {\n        return { error: true, message: \"Division by zero\", value: 0 };\n    }\n    return { error: false, message: \"\", value: a / b };\n}\n\nprint(\"=== Error Handling ===\");\n\nvar result1 = divide(10, 2);\nif (result1.error) {\n    print(\"Error: \" + result1.message);\n} else {\n    print(\"10 / 2 = \" + result1.value);\n}\n\nvar result2 = divide(10, 0);\nif (result2.error) {\n    print(\"Error caught: \" + result2.message);\n} else {\n    print(\"Result: \" + result2.value);\n}\n\nprint(\"Done\");\n", "package_usage": "// 包使用 - 哈德哈德脚本包系统\n// 包管理系统: 创建、安装、发布和使用\n\n// ============================================================\n// 1. 使用包\n// ============================================================\n\n// 使用外部包\n使用 \"代数\";\n使用 \"物理\";\n\n// 从包中导入特定模块\n使用 \"代数/矩阵\";\n使用 \"代数/向量\";\n使用 \"物理/运动\";\n\n打印(\"============================================================\");\n打印(\"哈德哈德脚本包系统演示\");\n打印(\"============================================================\\n\");\n\n// ============================================================\n// 2. 使用包函数\n// ============================================================\n\n打印(\"代数包使用:\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n// 创建矩阵\n变量 矩阵1 = 矩阵([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\n变量 矩阵2 = 矩阵([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\n打印(\"矩阵 1:\");\n矩阵1.显示();\n\n打印(\"\\n矩阵 2:\");\n矩阵2.显示();\n\n// 矩阵加法\n变量 总和 = 矩阵1.加(矩阵2);\n打印(\"\\n矩阵加法:\");\n总和.显示();\n\n// 向量运算\n变量 向量1 = 向量([1, 2, 3]);\n变量 向量2 = 向量([4, 5, 6]);\n\n打印(\"\\n\\n向量运算:\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n打印(\"向量 1: \" + 向量1.转文字());\n打印(\"向量 2: \" + 向量2.转文字());\n\n变量 点积 = 向量1.点积(向量2);\n打印(\"点积: \" + 点积);\n\n变量 叉积 = 向量1.叉积(向量2);\n打印(\"叉积: \" + 叉积.转文字());\n\n// ============================================================\n// 3. 使用物理包\n// ============================================================\n\n打印(\"\\n\\n物理包使用:\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n// 运动计算\n变量 初速度 = 0;        // 米/秒\n变量 加速度 = 9.8;      // 米/秒² (重力)\n变量 时间 = 5;           // 秒\n\n变量 末速度 = 运动.计算速度(初速度, 加速度, 时间);\n变量 距离 = 运动.计算距离(初速度, 加速度, 时间);\n\n打印(\"初速度: \" + 初速度 + \" 米/秒\");\n打印(\"加速度: \" + 加速度 + \" 米/秒²\");\n打印(\"时间: \" + 时间 + \" 秒\");\n打印(\"─────────────────────────────────────────────────────────\");\n打印(\"末速度: \" + 末速度 + \" 米/秒\");\n打印(\"行驶距离: \" + 距离 + \" 米\");\n\n// ============================================================\n// 4. 创建包\n// ============================================================\n\n打印(\"\\n\\n创建包:\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n打印(\"1. 创建 hudhud.toml 文件:\");\n打印(\"   [包]\");\n打印(\"   名称 = '数学工具'\");\n打印(\"   版本 = '1.0.0'\");\n打印(\"   描述 = '数学辅助函数'\");\n\n打印(\"\\n2. 添加依赖:\");\n打印(\"   [依赖]\");\n打印(\"   代数 = '^2.0.0'\");\n打印(\"   物理 = '^1.5.0'\");\n\n// ============================================================\n// 5. 包管理命令\n// ============================================================\n\n打印(\"\\n\\n包管理命令:\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n打印(\"安装包:\");\n打印(\"  hudhudscript install 代数\");\n打印(\"  hudhudscript install 物理@1.5.0\");\n\n打印(\"\\n更新包:\");\n打印(\"  hudhudscript update 代数\");\n打印(\"  hudhudscript update --all\");\n\n打印(\"\\n删除包:\");\n打印(\"  hudhudscript remove 代数\");\n\n打印(\"\\n列出已安装的包:\");\n打印(\"  hudhudscript list\");\n\n打印(\"\\n搜索包:\");\n打印(\"  hudhudscript search 数学\");\n\n打印(\"\\n包信息:\");\n打印(\"  hudhudscript info 代数\");\n\n// ============================================================\n// 6. 包依赖\n// ============================================================\n\n打印(\"\\n\\n包依赖:\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n打印(\"版本指定:\");\n打印(\"  '代数' = '^2.0.0'    # 2.x.x\");\n打印(\"  '物理' = '~1.5.0'    # 1.5.x\");\n打印(\"  '化学' = '1.2.3'     # 精确版本\");\n\n打印(\"\\n从Git仓库:\");\n打印(\"  '我的库' = { git = 'https://github.com/user/my-lib' }\");\n\n打印(\"\\n从本地路径:\");\n打印(\"  '本地库' = { path = '../本地库' }\");\n\n// ============================================================\n// 7. 包安全\n// ============================================================\n\n打印(\"\\n\\n包安全:\");\n打印(\"─────────────────────────────────────────────────────────\\n\");\n\n打印(\"安全审计:\");\n打印(\"  hudhudscript audit\");\n\n打印(\"\\n校验和验证:\");\n打印(\"  hudhudscript verify 代数\");\n\n打印(\"\\n============================================================\");\n打印(\"包系统演示完成!\");\n打印(\"使用哈德哈德脚本编写模块化和可重用的代码\");\n打印(\"============================================================\");\n", "arrays": "// 中文 - 数组\n// 数组与原生关键词\n\n// 创建数组\n变量 数字 = [1, 2, 3, 4, 5];\n变量 名字列表 = [\"小红\", \"小明\", \"小华\"];\n\n// 访问元素\n变量 第一 = 数字[0];\n变量 第二 = 数字[1];\n\n// 结果\n第一;\n", "math": "// ZH - Math Module\n\n// Addition\nfunction add(a, b) {\n    返回 a + b;\n}\n\n// Subtraction\nfunction subtract(a, b) {\n    返回 a - b;\n}\n\n// Multiplication\nfunction multiply(a, b) {\n    返回 a * b;\n}\n\n// Division\nfunction divide(a, b) {\n    如果 (b == 0) {\n        打印(\"Error: Division by zero!\");\n        返回 0;\n    } 否则 {\n        返回 a / b;\n    }\n}\n\n// Square\nfunction square(x) {\n    返回 x * x;\n}\n\n// Cube\nfunction cube(x) {\n    返回 x * x * x;\n}\n\n// Absolute value\nfunction abs(x) {\n    如果 (x < 0) {\n        返回 -x;\n    } 否则 {\n        返回 x;\n    }\n}\n\n// Maximum\nfunction max(a, b) {\n    如果 (a > b) {\n        返回 a;\n    } 否则 {\n        返回 b;\n    }\n}\n\n// Minimum\nfunction min(a, b) {\n    如果 (a < b) {\n        返回 a;\n    } 否则 {\n        返回 b;\n    }\n}\n", "control_flow": "// 中文 - 控制流\n变量 计数器 = 0;\n变量 最大值 = 5;\n\n// Loop\n当 (计数器 < 最大值) {\n    计数器 = 计数器 + 1;\n}\n\n// Conditional\n变量 分数 = 85;\n\n如果 (分数 >= 90) {\n    分数;\n} 否则 {\n    如果 (分数 >= 80) {\n        分数;\n    } 否则 {\n        分数;\n    }\n}\n\n计数器;", "state_machine": "// State Machine Example\n变量 state = \"initial\";\n\n如果 (state == \"initial\") {\n    打印(\"Starting\");\n    state = \"running\";\n}\n\n打印(state);\n", "conditionals": "// 中文 - 条件逻辑\n变量 分数 = 85;\n\n如果 (分数 >= 90) {\n    打印(1000);\n} 否则 {\n    如果 (分数 >= 80) {\n        打印(2000);\n    } 否则 {\n        打印(3000);\n    }\n}\n\n打印(999);\n", "code_organization": "// 中文 - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable 对于 large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// 使用 \"agent/agent_definition.hudhud\";\n// 使用 \"constitution/laws.hudhud\";\n// 使用 \"data/note.hudhud\";\n// 使用 \"utils/math.hudhud\";\n", "module_concepts": "// 中文 - Modules & Code Organization\n// Demonstrates module system: 使用/导入 like Rust, Java, C++, Python\n\n// Import math module\n使用 \"math.hudhud\";\n\n// Example syntax variations:\n// 使用 \"math.hudhud\";\n// 使用 { add, subtract } 从 \"math.hudhud\";\n// 使用 \"math.hudhud\" 作为 math;\n\n// Using functions 从 math module\n变量 sum = add(10, 5);\n打印(sum);\n\n变量 diff = subtract(20, 8);\n打印(diff);\n\n变量 product = multiply(4, 7);\n打印(product);\n\n变量 quotient = divide(15, 3);\n打印(quotient);\n\n变量 squared = square(5);\n打印(squared);\n\n变量 cubed = cube(3);\n打印(cubed);\n\n变量 absolute = abs(-42);\n打印(absolute);\n\n变量 maximum = max(100, 50);\n打印(maximum);\n\n变量 minimum = min(100, 50);\n打印(minimum);\n\n// Complex calculation using multiple functions\n变量 result = add(multiply(5, 3), divide(20, 4));\n打印(result);\n", "huaxue": "// 中文 - Chemistry Module\n\n函数 摩尔质量(atoms, atomicWeight) {\n    返回 atoms * atomicWeight;\n}\n\n函数 浓度(moles, volume) {\n    返回 moles / volume;\n}\n\n函数 pH(hydrogenConcentration) {\n    返回 14 - hydrogenConcentration;\n}\n\n函数 密度(mass, volume) {\n    返回 mass / volume;\n}\n\n函数 稀释(c1, v1, v2) {\n    返回 (c1 * v1) / v2;\n}\n", "higher_order_functions": "// 中文 - 高阶函数\n// 与其他函数协作的函数\n\n// 返回函数的函数\n函数 乘数器(因子) {\n    返回 (x) => x * 因子;\n}\n\n变量 双倍 = 乘数器(2);\n变量 三倍 = 乘数器(3);\n\n打印(双倍(5));  // 10\n打印(三倍(5));  // 15\n\n// 接受函数的函数\n函数 应用(函数参数, 值) {\n    返回 函数参数(值);\n}\n\n打印(应用(双倍, 10));  // 20\n\n// 组合示例\n函数 组合(f, g) {\n    返回 (x) => f(g(x));\n}\n\n变量 加一 = (x) => x + 1;\n变量 乘二 = (x) => x * 2;\n\n变量 先加后乘 = 组合(乘二, 加一);\n打印(先加后乘(5));  // 12 (5+1=6, 6*2=12)\n", "switch_concepts": "// zh - Switch Concepts\n// Using if-else for multiple conditions\n\nfunction dayType(day) {\n    if (day == \"Monday\") { return \"Weekday\"; }\n    if (day == \"Tuesday\") { return \"Weekday\"; }\n    if (day == \"Wednesday\") { return \"Weekday\"; }\n    if (day == \"Thursday\") { return \"Weekday\"; }\n    if (day == \"Friday\") { return \"Weekday\"; }\n    if (day == \"Saturday\") { return \"Weekend\"; }\n    if (day == \"Sunday\") { return \"Weekend\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== Day Types ===\");\nprint(\"Monday: \" + dayType(\"Monday\"));\nprint(\"Saturday: \" + dayType(\"Saturday\"));\nprint(\"Holiday: \" + dayType(\"Holiday\"));\n\nfunction statusMessage(code) {\n    if (code == 200) { return \"OK\"; }\n    if (code == 404) { return \"Not Found\"; }\n    if (code == 500) { return \"Server Error\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== HTTP Status ===\");\nprint(\"200: \" + statusMessage(200));\nprint(\"404: \" + statusMessage(404));\n", "event_concepts": "// 中文 - Event Concepts\n\n事件 UserLogin {\n    打印(\"User logged in\");\n}\n\n事件 DataReceived {\n    打印(\"Data received\");\n}\n\n事件 ErrorOccurred {\n    打印(\"Error occurred\");\n}\n\n函数 on_login(username) {\n    打印(\"Login: \" + username);\n    返回 \"Welcome, \" + username;\n}\n\n函数 on_data(source) {\n    打印(\"Data from: \" + source);\n    返回 \"Processed: \" + source;\n}\n\n函数 on_error(message) {\n    打印(\"Error: \" + message);\n    返回 \"Handled: \" + message;\n}\n\n打印(\"=== Event System ===\");\n变量 r1 = on_login(\"admin\");\n打印(r1);\n变量 r2 = on_data(\"sensor_1\");\n打印(r2);\n变量 r3 = on_error(\"timeout\");\n打印(r3);\n", "functions": "// 中文 - 函数\n// 函数定义和使用示例\n\n// 简单函数\n函数 问候() {\n    打印(\"你好，世界！\");\n}\n\n// 带参数的函数\n函数 加(甲, 乙) {\n    返回 甲 + 乙;\n}\n\n// 多参数函数\n函数 计算(数1, 数2, 操作) {\n    如果 (操作 == \"加\") {\n        返回 数1 + 数2;\n    } 否则 {\n        返回 0;\n    }\n}\n\n// 数学函数\n函数 平方(数) {\n    返回 数 * 数;\n}\n\n函数 立方(数) {\n    返回 数 * 数 * 数;\n}\n\n// 使用函数\n问候();\n\n变量 结果1 = 加(5, 3);\n打印(结果1);\n\n变量 结果2 = 计算(10, 5, \"加\");\n打印(结果2);\n\n变量 平方结果 = 平方(4);\n打印(平方结果);\n\n变量 立方结果 = 立方(3);\n打印(立方结果);\n\n// 函数组合\n变量 总计 = 加(平方(3), 立方(2));\n打印(总计);\n", "entity_concepts": "// 中文 - 实体概念\n\n变量 用户 = {\n    标识: 1,\n    名称: \"小红\",\n    邮箱: \"xiaohong@example.com\",\n    角色: \"开发者\"\n};\n\n变量 产品 = {\n    标识: 101,\n    名称: \"哈德哈德脚本开发环境\",\n    版本: \"2.0\",\n    价格: 49\n};\n\n变量 订单 = {\n    标识: 1001,\n    用户标识: 1,\n    产品标识: 101,\n    数量: 2,\n    状态: \"已确认\"\n};\n\n函数 实体信息(实体) {\n    返回 \"实体 #\" + 实体.标识 + \": \" + 实体.名称;\n}\n\n函数 计算总额(订单, 价格) {\n    返回 订单.数量 * 价格;\n}\n\n打印(\"=== 实体系统 ===\");\n打印(实体信息(用户));\n打印(实体信息(产品));\n变量 总额 = 计算总额(订单, 产品.价格);\n打印(\"订单 #\" + 订单.标识 + \" 总额: \" + 总额);\n打印(\"状态: \" + 订单.状态);\n", "error_concepts": "// zh - Error Concepts\n// Simple validation functions\n\nfunction validateAge(age) {\n    if (age < 0) {\n        return { valid: false, error: \"Invalid age: negative\" };\n    }\n    if (age > 150) {\n        return { valid: false, error: \"Invalid age: too large\" };\n    }\n    return { valid: true, age: age };\n}\n\nfunction validateEmail(email) {\n    if (email == \"\") {\n        return { valid: false, error: \"Empty email\" };\n    }\n    return { valid: true, email: email };\n}\n\nprint(\"=== Validation ===\");\n\nvar ageResult1 = validateAge(25);\nif (ageResult1.valid) {\n    print(\"Age 25 is valid\");\n} else {\n    print(\"Error: \" + ageResult1.error);\n}\n\nvar ageResult2 = validateAge(-5);\nif (ageResult2.valid) {\n    print(\"Age is valid\");\n} else {\n    print(\"Error: \" + ageResult2.error);\n}\n\nvar emailResult = validateEmail(\"user@example.com\");\nif (emailResult.valid) {\n    print(\"Email valid: \" + emailResult.email);\n} else {\n    print(\"Email error: \" + emailResult.error);\n}\n\nprint(\"Validation complete\");\n"}, "hi": {"objects": "// हिन्दी - ऑब्जेक्ट\n// मूल कीवर्ड के साथ ऑब्जेक्ट\n\n// ऑब्जेक्ट बनाएँ\nमान व्यक्ति = {\n    नाम: \"आशा\",\n    उम्र: ३०,\n    शहर: \"मुंबई\"\n};\n\n// गुणों तक पहुँचें\nमान नाम = व्यक्ति.नाम;\nमान उम्र = व्यक्ति.उम्र;\n\n// परिणाम\nनाम;\n", "chemistry": "// HI - Chemistry Module\n\nफ़ंक्शन molarMass(atoms, atomicWeight) {\n    वापस_करो atoms * atomicWeight;\n}\n\nफ़ंक्शन concentration(moles, volume) {\n    वापस_करो moles / volume;\n}\n\nफ़ंक्शन pH(hydrogenConcentration) {\n    वापस_करो 14 - hydrogenConcentration;\n}\n\nफ़ंक्शन density(mass, volume) {\n    वापस_करो mass / volume;\n}\n\nफ़ंक्शन dilution(c1, v1, v2) {\n    वापस_करो (c1 * v1) / v2;\n}\n", "loops": "// हिन्दी - लूप\nमान गिनती = 0;\nमान अधिकतम = 5;\n\nजबतक (गिनती < अधिकतम) {\n    प्रिंट(गिनती);\n    गिनती = गिनती + 1;\n}\n\nप्रिंट(999);\n", "data_processing": "// हिन्दी - Data Processing\n// Using NATIVE हिन्दी keywords\n\nमान_लो data1 = 100;\nमान_लो data2 = 200;\nमान_लो data3 = 300;\n\nमान_लो total = value1+ value2+ value3;\nमान_लो average = total / 3;\n\nप्रिंट(total);\nप्रिंट(average);\n", "modules_import": "// HI - Modules Import Example\n\n// Import math module (direct access)\nउपयोग_करो \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nउपयोग_करो \"physics.hudhud\" के_रूप_में fizik;\n\n// Import chemistry (direct access)\nउपयोग_करो \"chemistry.hudhud\";\n\n// Using math functions (direct)\nमान_लो sum = add(10, 5);\nप्रिंट(sum);\n\nमान_लो product = multiply(4, 7);\nप्रिंट(product);\n\n// Using physics functions (via alias: fizik.functionName)\nमान_लो f = fizik.force(10, 9.8);\nप्रिंट(f);\n\nमान_लो ke = fizik.kineticEnergy(5, 10);\nप्रिंट(ke);\n\n// Using chemistry functions (direct)\nमान_लो d = density(100, 50);\nप्रिंट(d);\n\nमान_लो c = concentration(2, 5);\nप्रिंट(c);\n", "return_concept": "// हिन्दी - रिटर्न अवधारणा\n// return\n\nफ़ंक्शन वर्ग(x) {\n    वापस x * x;\n}\n\nफ़ंक्शन घन(x) {\n    वापस x * x * x;\n}\n\nप्रिंट(\"=== Math Functions ===\");\nप्रिंट(\"वर्ग(5): \" + वर्ग(5));\nप्रिंट(\"घन(3): \" + घन(3));\n\nफ़ंक्शन निरपेक्ष(x) {\n    अगर (x < 0) {\n        वापस -x;\n    }\n    वापस x;\n}\n\nप्रिंट(\"\\n=== Absolute ===\");\nप्रिंट(\"निरपेक्ष(-7): \" + निरपेक्ष(-7));\nप्रिंट(\"निरपेक्ष(3): \" + निरपेक्ष(3));\n\nफ़ंक्शन बिंदु_बनाओ(x, y) {\n    वापस { x: x, y: y };\n}\n\nमान p = बिंदु_बनाओ(10, 20);\nप्रिंट(\"\\n=== Point ===\");\nप्रिंट(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nफ़ंक्शन क्रमगुणित(n) {\n    अगर (n <= 1) {\n        वापस 1;\n    }\n    वापस n * क्रमगुणित(n - 1);\n}\n\nप्रिंट(\"\\n=== Factorial ===\");\nप्रिंट(\"5! = \" + क्रमगुणित(5));\nप्रिंट(\"10! = \" + क्रमगुणित(10));\n", "customer_service": "// हिन्दी - ग्राहक सेवा एजेंट\n// मूल हिन्दी कीवर्ड का उपयोग\n\nमान अभिवादन = \"नमस्ते, मैं आपकी कैसे मदद कर सकता हूँ?\";\nमान उत्तर = \"मैं आपके अनुरोध में सहायता करूँगा।\";\n\nप्रिंट(अभिवादन);\nप्रिंट(उत्तर);\n", "basic_example": "// हिन्दी - Basic Example with NATIVE keywords\nचर एक्स = 10;\nचर वाई = 20;\nचर योग = एक्स + वाई;\n\nप्रिंट(योग);\n", "physics": "// HI - Physics Module\n\nफ़ंक्शन speed(distance, time) {\n    वापस_करो distance / time;\n}\n\nफ़ंक्शन force(mass, acceleration) {\n    वापस_करो mass * acceleration;\n}\n\nफ़ंक्शन kineticEnergy(mass, velocity) {\n    वापस_करो 0.5 * mass * velocity * velocity;\n}\n\nफ़ंक्शन potentialEnergy(mass, gravity, height) {\n    वापस_करो mass * gravity * height;\n}\n\nफ़ंक्शन momentum(mass, velocity) {\n    वापस_करो mass * velocity;\n}\n", "error_handling": "// hi - Error Handling\n// Simple error control with if-else\n\nfunction divide(a, b) {\n    if (b == 0) {\n        return { error: true, message: \"Division by zero\", value: 0 };\n    }\n    return { error: false, message: \"\", value: a / b };\n}\n\nprint(\"=== Error Handling ===\");\n\nvar result1 = divide(10, 2);\nif (result1.error) {\n    print(\"Error: \" + result1.message);\n} else {\n    print(\"10 / 2 = \" + result1.value);\n}\n\nvar result2 = divide(10, 0);\nif (result2.error) {\n    print(\"Error caught: \" + result2.message);\n} else {\n    print(\"Result: \" + result2.value);\n}\n\nprint(\"Done\");\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici पैकेज kullanımı\nउपयोग_करो \"cebir\";\nउपयोग_करो \"fizik\" के_रूप_में पैकेज;\n\n// Paket içinden belirli modülleri içe aktarma\nउपयोग_करो \"cebir/matris\";\nउपयोग_करो \"cebir/vektor\";\nउपयोग_करो \"fizik/hareket\";\n\nलिखो(\"============================================================\");\nलिखो(\"HudHudScript Paket Sistemi Demo\");\nलिखो(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nलिखो(\"📦 Cebir Paketi Kullanımı:\");\nलिखो(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nचर matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nचर matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nलिखो(\"Matris 1:\");\nmatris1.goster();\n\nलिखो(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nचर toplam = matris1.topla(matris2);\nलिखो(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nचर vektor1 = Vektor([1, 2, 3]);\nचर vektor2 = Vektor([4, 5, 6]);\n\nलिखो(\"\\n\\n📐 Vektör İşlemleri:\");\nलिखो(\"─────────────────────────────────────────────────────────\\n\");\n\nलिखो(\"Vektör 1: \" + vektor1.toString());\nलिखो(\"Vektör 2: \" + vektor2.toString());\n\nचर noktaSal = vektor1.noktaSal(vektor2);\nलिखो(\"Nokta Çarpım: \" + noktaSal);\n\nचर caprazCarpim = vektor1.caprazCarpim(vektor2);\nलिखो(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nलिखो(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nलिखो(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nचर baslangicHizi = 0;      // m/s\nचर ivme = 9.8;              // m/s² (yerçekimi)\nचर zaman = 5;               // saniye\n\nचर sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nचर mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nलिखो(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nलिखो(\"İvme: \" + ivme + \" m/s²\");\nलिखो(\"Zaman: \" + zaman + \" s\");\nलिखो(\"─────────────────────────────────────────────────────────\");\nलिखो(\"Son Hız: \" + sonHiz + \" m/s\");\nलिखो(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nलिखो(\"\\n\\n📝 Paket Oluşturma:\");\nलिखो(\"─────────────────────────────────────────────────────────\\n\");\n\nलिखो(\"1. hudhud.toml dosyası oluşturun:\");\nलिखो(\"   [package]\");\nलिखो(\"   name = 'matematik-utils'\");\nलिखो(\"   version = '1.0.0'\");\nलिखो(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nलिखो(\"\\n2. Bağımlılıklar ekleyin:\");\nलिखो(\"   [dependencies]\");\nलिखो(\"   cebir = '^2.0.0'\");\nलिखो(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nलिखो(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nलिखो(\"─────────────────────────────────────────────────────────\\n\");\n\nलिखो(\"Paket kurma:\");\nलिखो(\"  hudhudscript install cebir\");\nलिखो(\"  hudhudscript install fizik@1.5.0\");\n\nलिखो(\"\\nPaket güncelleme:\");\nलिखो(\"  hudhudscript update cebir\");\nलिखो(\"  hudhudscript update --all\");\n\nलिखो(\"\\nPaket kaldırma:\");\nलिखो(\"  hudhudscript remove cebir\");\n\nलिखो(\"\\nKurulu paketleri listeleme:\");\nलिखो(\"  hudhudscript list\");\n\nलिखो(\"\\nPaket arama:\");\nलिखो(\"  hudhudscript search matematik\");\n\nलिखो(\"\\nPaket bilgisi:\");\nलिखो(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nलिखो(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nलिखो(\"─────────────────────────────────────────────────────────\\n\");\n\nलिखो(\"Versiyon belirtme:\");\nलिखो(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nलिखो(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nलिखो(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nलिखो(\"\\nGit deposundan:\");\nलिखो(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nलिखो(\"\\nYerel yoldan:\");\nलिखो(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nलिखो(\"\\n\\n🔒 Paket Güvenliği:\");\nलिखो(\"─────────────────────────────────────────────────────────\\n\");\n\nलिखो(\"Güvenlik kontrolü:\");\nलिखो(\"  hudhudscript audit\");\n\nलिखो(\"\\nChecksum doğrulama:\");\nलिखो(\"  hudhudscript verify cebir\");\n\nलिखो(\"\\n============================================================\");\nलिखो(\"✓ Paket sistemi demo tamamlandı!\");\nलिखो(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nलिखो(\"============================================================\");\n", "arrays": "// हिन्दी - सरणियाँ\n// मूल कीवर्ड के साथ सरणियाँ\n\n// सरणियाँ बनाएँ\nमान संख्याएं = [१, २, ३, ४, ५];\nमान नाम = [\"आशा\", \"राज\", \"प्रिया\"];\n\n// तत्वों तक पहुँचें\nमान पहला = संख्याएं[०];\nमान दूसरा = संख्याएं[१];\n\n// परिणाम\nपहला;\n", "math": "// HI - Math Module\n\nफ़ंक्शन add(a, b) {\n    वापस_करो a + b;\n}\n\nफ़ंक्शन subtract(a, b) {\n    वापस_करो a - b;\n}\n\nफ़ंक्शन multiply(a, b) {\n    वापस_करो a * b;\n}\n\nफ़ंक्शन divide(a, b) {\n    अगर (b == 0) {\n        प्रिंट(\"Error: Division by zero!\");\n        वापस_करो 0;\n    } नहीं_तो {\n        वापस_करो a / b;\n    }\n}\n\nफ़ंक्शन square(x) {\n    वापस_करो x * x;\n}\n\nफ़ंक्शन cube(x) {\n    वापस_करो x * x * x;\n}\n\nफ़ंक्शन abs(x) {\n    अगर (x < 0) {\n        वापस_करो -x;\n    } नहीं_तो {\n        वापस_करो x;\n    }\n}\n\nफ़ंक्शन max(a, b) {\n    अगर (a > b) {\n        वापस_करो a;\n    } नहीं_तो {\n        वापस_करो b;\n    }\n}\n\nफ़ंक्शन min(a, b) {\n    अगर (a < b) {\n        वापस_करो a;\n    } नहीं_तो {\n        वापस_करो b;\n    }\n}\n", "control_flow": "// हिन्दी - नियंत्रण प्रवाह\nचर गणक = 0;\nचर अधिकतम = 5;\n\n// Loop\nजब_तक (गणक < अधिकतम) {\n    गणक = गणक + 1;\n}\n\n// Conditional\nचर स्कोर = 85;\n\nअगर (स्कोर >= 90) {\n    स्कोर;\n} नहीं_तो {\n    अगर (स्कोर >= 80) {\n        स्कोर;\n    } नहीं_तो {\n        स्कोर;\n    }\n}\n\nगणक;\n", "state_machine": "// State Machine Example\nमान_लो state = \"initial\";\n\nअगर (state == \"initial\") {\n    प्रिंट(\"Starting\");\n    state = \"running\";\n}\n\nप्रिंट(state);\n", "conditionals": "// हिन्दी - शर्तीय तर्क\nमान अंक = 85;\n\nअगर (अंक >= 90) {\n    प्रिंट(1000);\n} वरना {\n    अगर (अंक >= 80) {\n        प्रिंट(2000);\n    } वरना {\n        प्रिंट(3000);\n    }\n}\n\nप्रिंट(999);\n", "code_organization": "// हिन्दी - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable प्रत्येक large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// उपयोग_करो \"agent/agent_definition.hudhud\";\n// उपयोग_करो \"constitution/laws.hudhud\";\n// उपयोग_करो \"data/note.hudhud\";\n// उपयोग_करो \"utils/math.hudhud\";\n", "module_concepts": "// हिन्दी - Modules & Code Organization\n// Demonstrates module system: उपयोग_करो/आयात like Rust, Java, C++, Python\n\n// Import math module\n\"math.hudhud\" kullan;\n\n// Example syntax variations:\n// \"math.hudhud\" उपयोग_करो;\n// \"math.hudhud\" से { add, subtract } उपयोग_करो;\n// \"math.hudhud\" math के_रूप_में उपयोग_करो;\n\n// Using functions से math module\nमान_लो sum = add(10, 5);\nछापो(sum);\n\nमान_लो diff = subtract(20, 8);\nछापो(diff);\n\nमान_लो product = multiply(4, 7);\nछापो(product);\n\nमान_लो quotient = divide(15, 3);\nछापो(quotient);\n\nमान_लो squared = square(5);\nछापो(squared);\n\nमान_लो cubed = cube(3);\nछापो(cubed);\n\nमान_लो absolute = abs(-42);\nछापो(absolute);\n\nमान_लो maximum = max(100, 50);\nछापो(maximum);\n\nमान_लो minimum = min(100, 50);\nछापो(minimum);\n\n// Complex calculation using multiple functions\nमान_लो result = add(multiply(5, 3), divide(20, 4));\nछापो(result);\n", "switch_concepts": "// hi - Switch Concepts\n// Using if-else for multiple conditions\n\nfunction dayType(day) {\n    if (day == \"Monday\") { return \"Weekday\"; }\n    if (day == \"Tuesday\") { return \"Weekday\"; }\n    if (day == \"Wednesday\") { return \"Weekday\"; }\n    if (day == \"Thursday\") { return \"Weekday\"; }\n    if (day == \"Friday\") { return \"Weekday\"; }\n    if (day == \"Saturday\") { return \"Weekend\"; }\n    if (day == \"Sunday\") { return \"Weekend\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== Day Types ===\");\nprint(\"Monday: \" + dayType(\"Monday\"));\nprint(\"Saturday: \" + dayType(\"Saturday\"));\nprint(\"Holiday: \" + dayType(\"Holiday\"));\n\nfunction statusMessage(code) {\n    if (code == 200) { return \"OK\"; }\n    if (code == 404) { return \"Not Found\"; }\n    if (code == 500) { return \"Server Error\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== HTTP Status ===\");\nprint(\"200: \" + statusMessage(200));\nprint(\"404: \" + statusMessage(404));\n", "event_concepts": "// हिन्दी - Event Concepts\n\nघटना UserLogin {\n    प्रिंट(\"User logged in\");\n}\n\nघटना DataReceived {\n    प्रिंट(\"Data received\");\n}\n\nघटना ErrorOccurred {\n    प्रिंट(\"Error occurred\");\n}\n\nफ़ंक्शन on_login(username) {\n    प्रिंट(\"Login: \" + username);\n    वापस \"Welcome, \" + username;\n}\n\nफ़ंक्शन on_data(source) {\n    प्रिंट(\"Data from: \" + source);\n    वापस \"Processed: \" + source;\n}\n\nफ़ंक्शन on_error(message) {\n    प्रिंट(\"Error: \" + message);\n    वापस \"Handled: \" + message;\n}\n\nप्रिंट(\"=== Event System ===\");\nमान r1 = on_login(\"admin\");\nप्रिंट(r1);\nमान r2 = on_data(\"sensor_1\");\nप्रिंट(r2);\nमान r3 = on_error(\"timeout\");\nप्रिंट(r3);\n", "functions": "// हिन्दी - फ़ंक्शन\n// फ़ंक्शन परिभाषा और उपयोग के उदाहरण\n\n// सरल फ़ंक्शन\nफ़ंक्शन नमस्कार() {\n    प्रिंट(\"नमस्ते दुनिया!\");\n}\n\n// पैरामीटर वाला फ़ंक्शन\nफ़ंक्शन जोड़(अ, ब) {\n    वापस अ + ब;\n}\n\n// बहु-पैरामीटर फ़ंक्शन\nफ़ंक्शन गणना(संख्या१, संख्या२, क्रिया) {\n    अगर (क्रिया == \"जोड़\") {\n        वापस संख्या१ + संख्या२;\n    } वरना {\n        वापस ०;\n    }\n}\n\n// गणितीय फ़ंक्शन\nफ़ंक्शन वर्ग(ग) {\n    वापस ग * ग;\n}\n\nफ़ंक्शन घन(ग) {\n    वापस ग * ग * ग;\n}\n\n// फ़ंक्शन का उपयोग\nनमस्कार();\n\nमान परिणाम१ = जोड़(५, ३);\nप्रिंट(परिणाम१);\n\nमान परिणाम२ = गणना(१०, ५, \"जोड़\");\nप्रिंट(परिणाम२);\n\nमान वर्ग_परिणाम = वर्ग(४);\nप्रिंट(वर्ग_परिणाम);\n\nमान घन_परिणाम = घन(३);\nप्रिंट(घन_परिणाम);\n\n// फ़ंक्शन संयोजन\nमान योग = जोड़(वर्ग(३), घन(२));\nप्रिंट(योग);\n", "entity_concepts": "// हिन्दी - इकाई अवधारणाएँ\n\nमान उपयोगकर्ता = {\n    आईडी: १,\n    नाम: \"आशा\",\n    ईमेल: \"asha@udaharan.com\",\n    भूमिका: \"डेवलपर\"\n};\n\nमान उत्पाद = {\n    आईडी: १०१,\n    नाम: \"हुदहुदस्क्रिप्ट आईडीई\",\n    संस्करण: \"२.०\",\n    मूल्य: ४९\n};\n\nमान आदेश = {\n    आईडी: १००१,\n    उपयोगकर्ता_आईडी: १,\n    उत्पाद_आईडी: १०१,\n    मात्रा: २,\n    स्थिति: \"पुष्ट\"\n};\n\nफ़ंक्शन इकाई_जानकारी(इकाई) {\n    वापस \"इकाई #\" + इकाई.आईडी + \": \" + इकाई.नाम;\n}\n\nफ़ंक्शन कुल_गणना(आदेश, मूल्य) {\n    वापस आदेश.मात्रा * मूल्य;\n}\n\nप्रिंट(\"=== इकाई प्रणाली ===\");\nप्रिंट(इकाई_जानकारी(उपयोगकर्ता));\nप्रिंट(इकाई_जानकारी(उत्पाद));\nमान कुल = कुल_गणना(आदेश, उत्पाद.मूल्य);\nप्रिंट(\"आदेश #\" + आदेश.आईडी + \" कुल: \" + कुल);\nप्रिंट(\"स्थिति: \" + आदेश.स्थिति);\n", "error_concepts": "// hi - Error Concepts\n// Simple validation functions\n\nfunction validateAge(age) {\n    if (age < 0) {\n        return { valid: false, error: \"Invalid age: negative\" };\n    }\n    if (age > 150) {\n        return { valid: false, error: \"Invalid age: too large\" };\n    }\n    return { valid: true, age: age };\n}\n\nfunction validateEmail(email) {\n    if (email == \"\") {\n        return { valid: false, error: \"Empty email\" };\n    }\n    return { valid: true, email: email };\n}\n\nprint(\"=== Validation ===\");\n\nvar ageResult1 = validateAge(25);\nif (ageResult1.valid) {\n    print(\"Age 25 is valid\");\n} else {\n    print(\"Error: \" + ageResult1.error);\n}\n\nvar ageResult2 = validateAge(-5);\nif (ageResult2.valid) {\n    print(\"Age is valid\");\n} else {\n    print(\"Error: \" + ageResult2.error);\n}\n\nvar emailResult = validateEmail(\"user@example.com\");\nif (emailResult.valid) {\n    print(\"Email valid: \" + emailResult.email);\n} else {\n    print(\"Email error: \" + emailResult.error);\n}\n\nprint(\"Validation complete\");\n"}, "bn": {"objects": "// বাংলা - অবজেক্ট\n// Bengali - Objects with native keywords\n\n// Create object\nধরো ব্যক্তি = {\n    নাম: \"রহিম\",\n    বয়স: 25,\n    শহর: \"ঢাকা\"\n};\n\n// Access properties\nধরো নাম = ব্যক্তি.নাম;\nধরো বয়স = ব্যক্তি.বয়স;\n\n// Another object\nধরো গাড়ি = {\n    ব্র্যান্ড: \"টয়োটা\",\n    বছর: 2023,\n    রঙ: \"নীল\"\n};\n", "chemistry": "// বাংলা - রসায়ন মডিউল\n\nফাংশন মোলার_ভর(পরমাণু, পারমাণবিক_ওজন) {\n    ফেরত পরমাণু * পারমাণবিক_ওজন;\n}\n\nফাংশন ঘনত্ব_মোল(মোল, আয়তন) {\n    ফেরত মোল / আয়তন;\n}\n\nফাংশন পিএইচ(হাইড্রোজেন_ঘনত্ব) {\n    ফেরত ১৪ - হাইড্রোজেন_ঘনত্ব;\n}\n\nফাংশন ঘনত্ব(ভর, আয়তন) {\n    ফেরত ভর / আয়তন;\n}\n\nফাংশন তরলীকরণ(গ১, আ১, আ২) {\n    ফেরত (গ১ * আ১) / আ২;\n}\n", "loops": "// বাংলা - লুপ\n// Bengali - Loops with native keywords\n\nধরো গণনা = ০;\nধরো সর্বোচ্চ = ৫;\n\nযতক্ষণ (গণনা < সর্বোচ্চ) {\n    গণনা = গণনা + ১;\n}\n\nগণনা;", "data_processing": "// বাংলা - ডেটা প্রক্রিয়াকরণ\n// বাংলা - নেটিভ কীওয়ার্ড সহ ডেটা প্রক্রিয়াকরণ\n\n// ডেটা সংজ্ঞায়িত করুন\nধরো ডেটা১ = ১০০;\nধরো ডেটা২ = ২০০;\nধরো ডেটা৩ = ৩০০;\n\n// Calculate\nধরো মোট = ডেটা১ + ডেটা২ + ডেটা৩;\nধরো গড় = মোট / ৩;\n\nগড়;", "modules_import": "// বাংলা - মডিউল ইমপোর্ট উদাহরণ\n\n// গণিত মডিউল ইমপোর্ট (সরাসরি ব্যবহার)\nব্যবহার_করো \"গণিত.hudhud\";\n\n// পদার্থবিদ্যা মডিউল ইমপোর্ট (উপনাম সহ)\nব্যবহার_করো \"পদার্থবিদ্যা.hudhud\" as পদার্থ;\n\n// রসায়ন মডিউল ইমপোর্ট (সরাসরি ব্যবহার)\nব্যবহার_করো \"রসায়ন.hudhud\";\n\n// গণিত ফাংশন ব্যবহার (সরাসরি)\nধরি যোগফল = যোগ(১০, ৫);\nপ্রিন্ট(যোগফল);\n\nধরি গুণফল = গুণ(৪, ৭);\nপ্রিন্ট(গুণফল);\n\n// পদার্থবিদ্যা ফাংশন ব্যবহার (উপনাম সহ)\nধরি ব = পদার্থ.বল(১০, ৯.৮);\nপ্রিন্ট(ব);\n\nধরি গশ = পদার্থ.গতিশক্তি(৫, ১০);\nপ্রিন্ট(গশ);\n\n// রসায়ন ফাংশন ব্যবহার (সরাসরি)\nধরি ঘ = ঘনত্ব(১০০, ৫০);\nপ্রিন্ট(ঘ);\n\nধরি গন = ঘনত্ব_মোল(২, ৫);\nপ্রিন্ট(গন);\n", "return_concept": "// বাংলা - রিটার্ন ধারণা\n// return\n\nফাংশন বর্গ(x) {\n    ফেরত x * x;\n}\n\nফাংশন ঘন(x) {\n    ফেরত x * x * x;\n}\n\nপ্রিন্ট(\"=== Math Functions ===\");\nপ্রিন্ট(\"বর্গ(5): \" + বর্গ(5));\nপ্রিন্ট(\"ঘন(3): \" + ঘন(3));\n\nফাংশন পরম(x) {\n    যদি (x < 0) {\n        ফেরত -x;\n    }\n    ফেরত x;\n}\n\nপ্রিন্ট(\"\\n=== Absolute ===\");\nপ্রিন্ট(\"পরম(-7): \" + পরম(-7));\nপ্রিন্ট(\"পরম(3): \" + পরম(3));\n\nফাংশন বিন্দু_তৈরি(x, y) {\n    ফেরত { x: x, y: y };\n}\n\nধরি p = বিন্দু_তৈরি(10, 20);\nপ্রিন্ট(\"\\n=== Point ===\");\nপ্রিন্ট(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nফাংশন ফ্যাক্টরিয়াল(n) {\n    যদি (n <= 1) {\n        ফেরত 1;\n    }\n    ফেরত n * ফ্যাক্টরিয়াল(n - 1);\n}\n\nপ্রিন্ট(\"\\n=== Factorial ===\");\nপ্রিন্ট(\"5! = \" + ফ্যাক্টরিয়াল(5));\nপ্রিন্ট(\"10! = \" + ফ্যাক্টরিয়াল(10));\n", "customer_service": "// বাংলা - Customer Service Agent\n// Using NATIVE বাংলা keywords\n\nধরো শুভেচ্ছা = \"আপনাকে কিভাবে সাহায্য করতে পারি?\";\nধরো উত্তর = \"আমি আপনার অনুরোধে সহায়তা করব।\";\nধরো অবস্থা = \"সক্রিয়\";\n\nশুভেচ্ছা;", "basic_example": "// বাংলা - মৌলিক উদাহরণ\n// Bengali - Basic Example with native keywords\n\nধরো এক্স = 10;\nধরো ওয়াই = 20;\nধরো যোগফল = এক্স + ওয়াই;\nপ্রিন্ট(যোগফল);\n", "physics": "// বাংলা - পদার্থবিদ্যা মডিউল\n\nফাংশন গতি(দূরত্ব, সময়) {\n    ফেরত দূরত্ব / সময়;\n}\n\nফাংশন বল(ভর, ত্বরণ) {\n    ফেরত ভর * ত্বরণ;\n}\n\nফাংশন গতিশক্তি(ভর, বেগ) {\n    ফেরত ০.৫ * ভর * বেগ * বেগ;\n}\n\nফাংশন বিভবশক্তি(ভর, মাধ্যাকর্ষণ, উচ্চতা) {\n    ফেরত ভর * মাধ্যাকর্ষণ * উচ্চতা;\n}\n\nফাংশন ভরবেগ(ভর, বেগ) {\n    ফেরত ভর * বেগ;\n}\n", "error_handling": "// বাংলা - ত্রুটি পরিচালনা\n// try/catch/finally, throw\n\n// Basic try/catch\nফাংশন ভাগ(a, b) {\n    যদি (b == 0) {\n        ছুঁড়ো \"শূন্য দিয়ে ভাগ ত্রুটি\";\n    }\n    ফেরত a / b;\n}\n\nচেষ্টা {\n    ধরি result = ভাগ(10, 2);\n    প্রিন্ট(\"10 / 2 = \" + result);\n} ধরো (error) {\n    প্রিন্ট(\"ত্রুটি: \" + error);\n}\n\n// Try/catch/finally\nপ্রিন্ট(\"\n=== ফাইল প্রক্রিয়াকরণ ===\");\n\nফাংশন ফাইল_প্রক্রিয়া(filename) {\n    যদি (filename == \"\") {\n        ছুঁড়ো \"খালি ফাইল নাম ত্রুটি\";\n    }\n    প্রিন্ট(\"প্রক্রিয়াকরণ: \" + filename);\n    ফেরত \"ডেটা উৎস \" + filename;\n}\n\nচেষ্টা {\n    ধরি data = ফাইল_প্রক্রিয়া(\"report.txt\");\n    প্রিন্ট(\"ফলাফল: \" + data);\n} ধরো (error) {\n    প্রিন্ট(\"ত্রুটি: \" + error);\n} সবশেষে {\n    প্রিন্ট(\"পরিষ্কার সম্পন্ন\");\n}\n\n// Nested error handling\nপ্রিন্ট(\"\n=== নেস্টেড ত্রুটি পরিচালনা ===\");\n\nচেষ্টা {\n    প্রিন্ট(\"বাইরের চেষ্টা ব্লক\");\n    চেষ্টা {\n        ছুঁড়ো \"ভেতরের ত্রুটি\";\n    } ধরো (inner_err) {\n        প্রিন্ট(\"ভেতরের ধরা হলো: \" + inner_err);\n        ছুঁড়ো \"পুনরায় ছুঁড়ে দেওয়া ত্রুটি\";\n    }\n} ধরো (outer_err) {\n    প্রিন্ট(\"বাইরের ধরা হলো: \" + outer_err);\n} সবশেষে {\n    প্রিন্ট(\"সব সম্পন্ন\");\n}\n", "loops_advanced": "// বাংলা - উন্নত লুপ ধারণা\n// Bengali - Advanced Loop Concepts with native keywords\n\n// যতক্ষণ লুপ\nধরো গণনা = 0;\nযতক্ষণ (গণনা < 5) {\n    গণনা = গণনা + 1;\n}\n\n// জন্য লুপ (যখন দিয়ে)\nধরো i = 0;\nযতক্ষণ (i < 10) {\n    ধরো মান = i * 2;\n    i = i + 1;\n}\n\n// নেস্টেড লুপ\nধরো সারি = 0;\nযতক্ষণ (সারি < 3) {\n    ধরো কলাম = 0;\n    যতক্ষণ (কলাম < 3) {\n        ধরো গুণফল = সারি * কলাম;\n        কলাম = কলাম + 1;\n    }\n    সারি = সারি + 1;\n}\n\n// শর্তসাপেক্ষ লুপ\nধরো j = 0;\nযতক্ষণ (j < 100) {\n    যদি (j == 10) {\n        ধরো থামানো = true;\n    }\n    j = j + 1;\n}\n\n// এড়িয়ে যাওয়া লুপ\nধরো k = 0;\nযতক্ষণ (k < 10) {\n    k = k + 1;\n    যদি (k == 5) {\n        ধরো এড়িয়ে = true;\n    } নাহলে {\n        ধরো প্রক্রিয়া = k;\n    }\n}\n\n// অ্যারে লুপ\nধরো সংখ্যা = [1, 2, 3, 4, 5];\nধরো idx = 0;\nযতক্ষণ (idx < 5) {\n    ধরো মান = সংখ্যা[idx];\n    idx = idx + 1;\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici package kullanımı\nব্যবহার_করো \"cebir\";\nব্যবহার_করো \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nব্যবহার_করো \"cebir/matris\";\nব্যবহার_করো \"cebir/vektor\";\nব্যবহার_করো \"fizik/hareket\";\n\nprint(\"============================================================\");\nprint(\"HudHudScript Paket Sistemi Demo\");\nprint(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nprint(\"📦 Cebir Paketi Kullanımı:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nlet matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nlet matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nprint(\"Matris 1:\");\nmatris1.goster();\n\nprint(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nlet toplam = matris1.topla(matris2);\nprint(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nlet vektor1 = Vektor([1, 2, 3]);\nlet vektor2 = Vektor([4, 5, 6]);\n\nprint(\"\\n\\n📐 Vektör İşlemleri:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"Vektör 1: \" + vektor1.toString());\nprint(\"Vektör 2: \" + vektor2.toString());\n\nlet noktaSal = vektor1.noktaSal(vektor2);\nprint(\"Nokta Çarpım: \" + noktaSal);\n\nlet caprazCarpim = vektor1.caprazCarpim(vektor2);\nprint(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nprint(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nlet baslangicHizi = 0;      // m/s\nlet ivme = 9.8;              // m/s² (yerçekimi)\nlet zaman = 5;               // saniye\n\nlet sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nlet mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nprint(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nprint(\"İvme: \" + ivme + \" m/s²\");\nprint(\"Zaman: \" + zaman + \" s\");\nprint(\"─────────────────────────────────────────────────────────\");\nprint(\"Son Hız: \" + sonHiz + \" m/s\");\nprint(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nprint(\"\\n\\n📝 Paket Oluşturma:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"1. hudhud.toml dosyası oluşturun:\");\nprint(\"   [package]\");\nprint(\"   name = 'matematik-utils'\");\nprint(\"   version = '1.0.0'\");\nprint(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nprint(\"\\n2. Bağımlılıklar ekleyin:\");\nprint(\"   [dependencies]\");\nprint(\"   cebir = '^2.0.0'\");\nprint(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nprint(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"Paket kurma:\");\nprint(\"  hudhudscript install cebir\");\nprint(\"  hudhudscript install fizik@1.5.0\");\n\nprint(\"\\nPaket güncelleme:\");\nprint(\"  hudhudscript update cebir\");\nprint(\"  hudhudscript update --all\");\n\nprint(\"\\nPaket kaldırma:\");\nprint(\"  hudhudscript remove cebir\");\n\nprint(\"\\nKurulu paketleri listeleme:\");\nprint(\"  hudhudscript list\");\n\nprint(\"\\nPaket arama:\");\nprint(\"  hudhudscript search matematik\");\n\nprint(\"\\nPaket bilgisi:\");\nprint(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nprint(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"Versiyon belirtme:\");\nprint(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nprint(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nprint(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nprint(\"\\nGit deposundan:\");\nprint(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nprint(\"\\nYerel yoldan:\");\nprint(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nprint(\"\\n\\n🔒 Paket Güvenliği:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"Güvenlik kontrolü:\");\nprint(\"  hudhudscript audit\");\n\nprint(\"\\nChecksum doğrulama:\");\nprint(\"  hudhudscript verify cebir\");\n\nprint(\"\\n============================================================\");\nprint(\"✓ Paket sistemi demo tamamlandı!\");\nprint(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nprint(\"============================================================\");\n", "arrays": "// বাংলা - অ্যারে\n// Bengali - Arrays with native keywords\n\n// Create arrays\nধরো সংখ্যা = [1, 2, 3, 4, 5];\nধরো নামগুলি = [\"রহিম\", \"করিম\", \"সালমা\"];\n\n// Access elements\nধরো প্রথম = সংখ্যা[0];\nধরো দ্বিতীয় = সংখ্যা[1];\n\n// খালি তালিকা\nধরো খালি = [];\n\nপ্রথম;\n", "math": "// বাংলা - গণিত মডিউল\n\nফাংশন যোগ(ক, খ) {\n    ফেরত ক + খ;\n}\n\nফাংশন বিয়োগ(ক, খ) {\n    ফেরত ক - খ;\n}\n\nফাংশন গুণ(ক, খ) {\n    ফেরত ক * খ;\n}\n\nফাংশন ভাগ(ক, খ) {\n    যদি (খ == 0) {\n        প্রিন্ট(\"ত্রুটি: শূন্য দিয়ে ভাগ!\");\n        ফেরত 0;\n    } নাহলে {\n        ফেরত ক / খ;\n    }\n}\n\nফাংশন বর্গ(স) {\n    ফেরত স * স;\n}\n\nফাংশন ঘন(স) {\n    ফেরত স * স * স;\n}\n\nফাংশন পরম_মান(স) {\n    যদি (স < 0) {\n        ফেরত -স;\n    } নাহলে {\n        ফেরত স;\n    }\n}\n\nফাংশন সর্বোচ্চ(ক, খ) {\n    যদি (ক > খ) {\n        ফেরত ক;\n    } নাহলে {\n        ফেরত খ;\n    }\n}\n\nফাংশন সর্বনিম্ন(ক, খ) {\n    যদি (ক < খ) {\n        ফেরত ক;\n    } নাহলে {\n        ফেরত খ;\n    }\n}\n", "control_flow": "// বাংলা - নিয়ন্ত্রণ প্রবাহ\nধরো গণনা = 0;\nধরো সর্বোচ্চ = 5;\n\n// লুপ\nযতক্ষণ (গণনা < সর্বোচ্চ) {\n    গণনা = গণনা + 1;\n}\n\n// শর্ত\nধরো স্কোর = 85;\n\nযদি (স্কোর >= 90) {\n    স্কোর;\n} নাহলে {\n    যদি (স্কোর >= 80) {\n        স্কোর;\n    } নাহলে {\n        স্কোর;\n    }\n}\n\nগণনা;\n", "state_machine": "// State Machine Example\nধরো state = \"initial\";\n\nযদি (state == \"initial\") {\n    প্রদর্শন(\"Starting\");\n    state = \"running\";\n}\n\nপ্রদর্শন(state);\n", "conditionals": "// বাংলা - শর্তসাপেক্ষ যুক্তি\nধরো স্কোর = ৮৫;\n\nযদি (স্কোর >= ৯০) {\n    স্কোর;\n} নাহলে {\n    যদি (স্কোর >= ৮০) {\n        স্কোর;\n    } নাহলে {\n        স্কোর;\n    }\n}\n", "code_organization": "// বাংলা - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable প্রতিটি large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// ব্যবহার_করো \"agent/agent_definition.hudhud\";\n// ব্যবহার_করো \"constitution/laws.hudhud\";\n// ব্যবহার_করো \"data/note.hudhud\";\n// ব্যবহার_করো \"utils/math.hudhud\";\n", "module_concepts": "// বাংলা - Modules & Code Organization\n// Demonstrates module system: ব্যবহার_করো/আমদানি like Rust, Java, C++, Python\n\n// Import math module\n\"math.hudhud\" kullan;\n\n// Example syntax variations:\n// \"math.hudhud\" ব্যবহার_করো;\n// \"math.hudhud\" থেকে { add, subtract } ব্যবহার_করো;\n// \"math.hudhud\" math হিসেবে ব্যবহার_করো;\n\n// Using functions থেকে math module\nধরো sum = add(10, 5);\nছাপাও(sum);\n\nধরো diff = subtract(20, 8);\nছাপাও(diff);\n\nধরো product = multiply(4, 7);\nছাপাও(product);\n\nধরো quotient = divide(15, 3);\nছাপাও(quotient);\n\nধরো squared = square(5);\nছাপাও(squared);\n\nধরো cubed = cube(3);\nছাপাও(cubed);\n\nধরো absolute = abs(-42);\nছাপাও(absolute);\n\nধরো maximum = max(100, 50);\nছাপাও(maximum);\n\nধরো minimum = min(100, 50);\nছাপাও(minimum);\n\n// Complex calculation using multiple functions\nধরো result = add(multiply(5, 3), divide(20, 4));\nছাপাও(result);\n", "switch_concepts": "// বাংলা - Switch/Case ধারণা\n// switch/case/default\n\nফাংশন দিনের_ধরন(day) {\n    বেছে_নাও (day) {\n        ক্ষেত্রে \"Monday\":\n        ক্ষেত্রে \"Tuesday\":\n        ক্ষেত্রে \"Wednesday\":\n        ক্ষেত্রে \"Thursday\":\n        ক্ষেত্রে \"Friday\":\n            ফেরত \"কর্মদিবস\";\n        ক্ষেত্রে \"Saturday\":\n        ক্ষেত্রে \"Sunday\":\n            ফেরত \"সপ্তাহান্ত\";\n        ডিফল্ট:\n            ফেরত \"অজানা\";\n    }\n}\n\nপ্রিন্ট(\"=== Day Types ===\");\nপ্রিন্ট(\"Monday: \" + দিনের_ধরন(\"Monday\"));\nপ্রিন্ট(\"Saturday: \" + দিনের_ধরন(\"Saturday\"));\nপ্রিন্ট(\"Holiday: \" + দিনের_ধরন(\"Holiday\"));\n\nফাংশন গ্রেড_অক্ষর(score) {\n    বেছে_নাও (score) {\n        ক্ষেত্রে 90:\n            ফেরত \"A\";\n        ক্ষেত্রে 80:\n            ফেরত \"B\";\n        ক্ষেত্রে 70:\n            ফেরত \"C\";\n        ক্ষেত্রে 60:\n            ফেরত \"D\";\n        ডিফল্ট:\n            ফেরত \"F\";\n    }\n}\n\nপ্রিন্ট(\"\\n=== Grades ===\");\nপ্রিন্ট(\"90: \" + গ্রেড_অক্ষর(90));\nপ্রিন্ট(\"70: \" + গ্রেড_অক্ষর(70));\nপ্রিন্ট(\"50: \" + গ্রেড_অক্ষর(50));\n\nফাংশন অবস্থা_বার্তা(code) {\n    বেছে_নাও (code) {\n        ক্ষেত্রে 200:\n            ফেরত \"OK\";\n        ক্ষেত্রে 404:\n            ফেরত \"Not Found\";\n        ক্ষেত্রে 500:\n            ফেরত \"Server Error\";\n        ডিফল্ট:\n            ফেরত \"অজানা Status\";\n    }\n}\n\nপ্রিন্ট(\"\\n=== HTTP Status ===\");\nপ্রিন্ট(\"200: \" + অবস্থা_বার্তা(200));\nপ্রিন্ট(\"404: \" + অবস্থা_বার্তা(404));\n", "event_concepts": "// বাংলা - Event Concepts\n\nইভেন্ট UserLogin {\n    প্রিন্ট(\"User logged in\");\n}\n\nইভেন্ট DataReceived {\n    প্রিন্ট(\"Data received\");\n}\n\nইভেন্ট ErrorOccurred {\n    প্রিন্ট(\"Error occurred\");\n}\n\nফাংশন on_login(username) {\n    প্রিন্ট(\"Login: \" + username);\n    ফেরত \"Welcome, \" + username;\n}\n\nফাংশন on_data(source) {\n    প্রিন্ট(\"Data from: \" + source);\n    ফেরত \"Processed: \" + source;\n}\n\nফাংশন on_error(message) {\n    প্রিন্ট(\"Error: \" + message);\n    ফেরত \"Handled: \" + message;\n}\n\nপ্রিন্ট(\"=== Event System ===\");\nধরি r1 = on_login(\"admin\");\nপ্রিন্ট(r1);\nধরি r2 = on_data(\"sensor_1\");\nপ্রিন্ট(r2);\nধরি r3 = on_error(\"timeout\");\nপ্রিন্ট(r3);\n", "functions": "// বাংলা - ফাংশন\n// ফাংশন সংজ্ঞা এবং ব্যবহারের উদাহরণ\n\n// সাধারণ ফাংশন\nফাংশন অভিবাদন() {\n    প্রিন্ট(\"হ্যালো বিশ্ব!\");\n}\n\n// প্যারামিটার সহ ফাংশন\nফাংশন যোগ(ক, খ) {\n    ফেরত ক + খ;\n}\n\n// বহু-প্যারামিটার ফাংশন\nফাংশন হিসাব(সংখ্যা১, সংখ্যা২, অপারেশন) {\n    যদি (অপারেশন == \"যোগ\") {\n        ফেরত সংখ্যা১ + সংখ্যা২;\n    } নাহলে {\n        যদি (অপারেশন == \"বিয়োগ\") {\n            ফেরত সংখ্যা১ - সংখ্যা২;\n        } নাহলে {\n            যদি (অপারেশন == \"গুণ\") {\n                ফেরত সংখ্যা১ * সংখ্যা২;\n            } নাহলে {\n                যদি (অপারেশন == \"ভাগ\") {\n                    ফেরত সংখ্যা১ / সংখ্যা২;\n                } নাহলে {\n                    ফেরত 0;\n                }\n            }\n        }\n    }\n}\n\n// গণিত ফাংশন\nফাংশন বর্গ(স) {\n    ফেরত স * স;\n}\n\nফাংশন ঘন(স) {\n    ফেরত স * স * স;\n}\n\n// ফাংশন ব্যবহার\nঅভিবাদন();\n\nধরি ফলাফল১ = যোগ(5, 3);\nপ্রিন্ট(ফলাফল১);\n\nধরি ফলাফল২ = হিসাব(10, 5, \"যোগ\");\nপ্রিন্ট(ফলাফল২);\n\nধরি ফলাফল৩ = হিসাব(10, 5, \"গুণ\");\nপ্রিন্ট(ফলাফল৩);\n\nধরি বর্গ_ফলাফল = বর্গ(4);\nপ্রিন্ট(বর্গ_ফলাফল);\n\nধরি ঘন_ফলাফল = ঘন(3);\nপ্রিন্ট(ঘন_ফলাফল);\n\n// ফাংশন সংমিশ্রণ\nধরি মোট = যোগ(বর্গ(3), ঘন(2));\nপ্রিন্ট(মোট);\n", "entity_concepts": "// বাংলা - সত্তা ধারণা\n\nধরি ব্যবহারকারী = {\n    আইডি: ১,\n    নাম: \"আয়েশা\",\n    ইমেইল: \"ayesha@example.com\",\n    ভূমিকা: \"ডেভেলপার\"\n};\n\nধরি পণ্য = {\n    আইডি: ১০১,\n    নাম: \"হুদহুদস্ক্রিপ্ট আইডিই\",\n    সংস্করণ: \"২.০\",\n    মূল্য: ৪৯\n};\n\nধরি অর্ডার = {\n    আইডি: ১০০১,\n    ব্যবহারকারী_আইডি: ১,\n    পণ্য_আইডি: ১০১,\n    পরিমাণ: ২,\n    অবস্থা: \"নিশ্চিত\"\n};\n\nফাংশন সত্তা_তথ্য(সত্তা) {\n    ফেরত \"সত্তা #\" + সত্তা.আইডি + \": \" + সত্তা.নাম;\n}\n\nফাংশন মোট_হিসাব(অর্ডার, মূল্য) {\n    ফেরত অর্ডার.পরিমাণ * মূল্য;\n}\n\nপ্রিন্ট(\"=== সত্তা সিস্টেম ===\");\nপ্রিন্ট(সত্তা_তথ্য(ব্যবহারকারী));\nপ্রিন্ট(সত্তা_তথ্য(পণ্য));\nধরি মোট = মোট_হিসাব(অর্ডার, পণ্য.মূল্য);\nপ্রিন্ট(\"অর্ডার #\" + অর্ডার.আইডি + \" মোট: \" + মোট);\nপ্রিন্ট(\"অবস্থা: \" + অর্ডার.অবস্থা);\n", "error_concepts": "// বাংলা - Error Concepts\n\nফাংশন validate_age(age) {\n    যদি (age < 0) {\n        ছুঁড়ো \"Invalid age: negative\";\n    }\n    যদি (age > 150) {\n        ছুঁড়ো \"Invalid age: too large\";\n    }\n    ফেরত age;\n}\n\nফাংশন validate_email(email) {\n    যদি (email == \"\") {\n        ছুঁড়ো \"Empty email\";\n    }\n    প্রিন্ট(\"Email valid: \" + email);\n    ফেরত email;\n}\n\nপ্রিন্ট(\"=== Validation ===\");\n\nচেষ্টা {\n    validate_age(25);\n    প্রিন্ট(\"Age 25: valid\");\n} ধরো (error) {\n    প্রিন্ট(\"Error: \" + error);\n}\n\nচেষ্টা {\n    validate_age(-5);\n} ধরো (error) {\n    প্রিন্ট(\"Error: \" + error);\n}\n\nচেষ্টা {\n    validate_email(\"user@example.com\");\n    validate_email(\"\");\n} ধরো (error) {\n    প্রিন্ট(\"Email error: \" + error);\n} সবশেষে {\n    প্রিন্ট(\"Validation complete\");\n}\n"}, "bs": {"objects": "// Bosanski - Objekti\n// Objekti sa domaćim ključnim riječima\n\n// Kreiraj objekat\nneka osoba = {\n    ime: \"Amina\",\n    godine: 30,\n    grad: \"Sarajevo\"\n};\n\n// Pristupi svojstvima\nneka ime = osoba.ime;\nneka godine = osoba.godine;\n\n// Rezultat\nime;\n", "chemistry": "// BS - Chemistry Module\n\nfunkcija molarMass(atoms, atomicWeight) {\n    vrati atoms * atomicWeight;\n}\n\nfunkcija concentration(moles, volume) {\n    vrati moles / volume;\n}\n\nfunkcija pH(hydrogenConcentration) {\n    vrati 14 - hydrogenConcentration;\n}\n\nfunkcija density(mass, volume) {\n    vrati mass / volume;\n}\n\nfunkcija dilution(c1, v1, v2) {\n    vrati (c1 * v1) / v2;\n}\n", "loops": "// Bosanski - Petlje\nneka brojač = 0;\nneka maksimum = 5;\n\ndok (brojač < maksimum) {\n    ispiši(brojač);\n    brojač = brojač + 1;\n}\n\nispiši(999);\n", "data_processing": "// Bosanski - Data Processing\n// Using NATIVE Bosanski keywords\n\nneka value1 = 100;\nneka value2 = 200;\nneka value3 = 300;\n\nneka total = value1+ value2+ value3;\nneka average = total / 3;\n\nštampaj(total);\nštampaj(average);\n", "modules_import": "// BS - Modules Import Example\n\n// Import math module (direct access)\nkoristi \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nkoristi \"physics.hudhud\" kao fizik;\n\n// Import chemistry (direct access)\nkoristi \"chemistry.hudhud\";\n\n// Using math functions (direct)\nneka sum = add(10, 5);\nštampaj(sum);\n\nneka product = multiply(4, 7);\nštampaj(product);\n\n// Using physics functions (via alias: fizik.functionName)\nneka f = fizik.force(10, 9.8);\nštampaj(f);\n\nneka ke = fizik.kineticEnergy(5, 10);\nštampaj(ke);\n\n// Using chemistry functions (direct)\nneka d = density(100, 50);\nštampaj(d);\n\nneka c = concentration(2, 5);\nštampaj(c);\n", "return_concept": "// Bosanski - Koncept povratka\n// return\n\nfunkcija kvadrat(x) {\n    vrati x * x;\n}\n\nfunkcija kub(x) {\n    vrati x * x * x;\n}\n\nispiši(\"=== Math Functions ===\");\nispiši(\"kvadrat(5): \" + kvadrat(5));\nispiši(\"kub(3): \" + kub(3));\n\nfunkcija apsolutna(x) {\n    ako (x < 0) {\n        vrati -x;\n    }\n    vrati x;\n}\n\nispiši(\"\\n=== Absolute ===\");\nispiši(\"apsolutna(-7): \" + apsolutna(-7));\nispiši(\"apsolutna(3): \" + apsolutna(3));\n\nfunkcija kreiraj_tačku(x, y) {\n    vrati { x: x, y: y };\n}\n\nneka p = kreiraj_tačku(10, 20);\nispiši(\"\\n=== Point ===\");\nispiši(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfunkcija faktorijel(n) {\n    ako (n <= 1) {\n        vrati 1;\n    }\n    vrati n * faktorijel(n - 1);\n}\n\nispiši(\"\\n=== Factorial ===\");\nispiši(\"5! = \" + faktorijel(5));\nispiši(\"10! = \" + faktorijel(10));\n", "customer_service": "// Bosanski - Agent za korisničku podršku\n// Koristi DOMAĆE bosanske ključne riječi\n\nneka pozdrav = \"Zdravo, kako vam mogu pomoći?\";\nneka odgovor = \"Pomoći ću vam s vašim zahtjevom.\";\n\nispiši(pozdrav);\nispiši(odgovor);\n", "basic_example": "// Bosanski - Basic Example with NATIVE keywords\nvarijabla a = 10;\nvarijabla b = 20;\nvarijabla suma = a + b;\n\nštampaj(suma);\n", "physics": "// BS - Physics Module\n\nfunkcija speed(distance, time) {\n    vrati distance / time;\n}\n\nfunkcija force(mass, acceleration) {\n    vrati mass * acceleration;\n}\n\nfunkcija kineticEnergy(mass, velocity) {\n    vrati 0.5 * mass * velocity * velocity;\n}\n\nfunkcija potentialEnergy(mass, gravity, height) {\n    vrati mass * gravity * height;\n}\n\nfunkcija momentum(mass, velocity) {\n    vrati mass * velocity;\n}\n", "error_handling": "// Bosanski - Upravljanje greškama\n// try/catch/finally, throw\n\n// Basic try/catch\nfunkcija podijeli(a, b) {\n    ako (b == 0) {\n        baci \"Greška dijeljenja nulom\";\n    }\n    vrati a / b;\n}\n\npokušaj {\n    neka result = podijeli(10, 2);\n    ispiši(\"10 / 2 = \" + result);\n} uhvati (error) {\n    ispiši(\"Greška: \" + error);\n}\n\n// Try/catch/finally\nispiši(\"\n=== Obrada datoteke ===\");\n\nfunkcija obradi_datoteku(filename) {\n    ako (filename == \"\") {\n        baci \"Greška praznog naziva datoteke\";\n    }\n    ispiši(\"Obrada: \" + filename);\n    vrati \"Podaci iz \" + filename;\n}\n\npokušaj {\n    neka data = obradi_datoteku(\"report.txt\");\n    ispiši(\"Rezultat: \" + data);\n} uhvati (error) {\n    ispiši(\"Greška: \" + error);\n} konačno {\n    ispiši(\"Čišćenje završeno\");\n}\n\n// Nested error handling\nispiši(\"\n=== Ugniježđeno upravljanje greškama ===\");\n\npokušaj {\n    ispiši(\"Vanjski pokušaj blok\");\n    pokušaj {\n        baci \"Unutrašnja greška\";\n    } uhvati (inner_err) {\n        ispiši(\"Uhvaćena unutrašnja: \" + inner_err);\n        baci \"Ponovo bačena greška\";\n    }\n} uhvati (outer_err) {\n    ispiši(\"Uhvaćena vanjska: \" + outer_err);\n} konačno {\n    ispiši(\"Sve gotovo\");\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici paket kullanımı\nkoristi \"cebir\";\nkoristi \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nkoristi \"cebir/matris\";\nkoristi \"cebir/vektor\";\nkoristi \"fizik/hareket\";\n\npiši(\"============================================================\");\npiši(\"HudHudScript Paket Sistemi Demo\");\npiši(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\npiši(\"📦 Cebir Paketi Kullanımı:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nvarijabla matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nvarijabla matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\npiši(\"Matris 1:\");\nmatris1.goster();\n\npiši(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nvarijabla toplam = matris1.topla(matris2);\npiši(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nvarijabla vektor1 = Vektor([1, 2, 3]);\nvarijabla vektor2 = Vektor([4, 5, 6]);\n\npiši(\"\\n\\n📐 Vektör İşlemleri:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"Vektör 1: \" + vektor1.toString());\npiši(\"Vektör 2: \" + vektor2.toString());\n\nvarijabla noktaSal = vektor1.noktaSal(vektor2);\npiši(\"Nokta Çarpım: \" + noktaSal);\n\nvarijabla caprazCarpim = vektor1.caprazCarpim(vektor2);\npiši(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\npiši(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nvarijabla baslangicHizi = 0;      // m/s\nvarijabla ivme = 9.8;              // m/s² (yerçekimi)\nvarijabla zaman = 5;               // saniye\n\nvarijabla sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nvarijabla mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\npiši(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\npiši(\"İvme: \" + ivme + \" m/s²\");\npiši(\"Zaman: \" + zaman + \" s\");\npiši(\"─────────────────────────────────────────────────────────\");\npiši(\"Son Hız: \" + sonHiz + \" m/s\");\npiši(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\npiši(\"\\n\\n📝 Paket Oluşturma:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"1. hudhud.toml dosyası oluşturun:\");\npiši(\"   [package]\");\npiši(\"   name = 'matematik-utils'\");\npiši(\"   version = '1.0.0'\");\npiši(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\npiši(\"\\n2. Bağımlılıklar ekleyin:\");\npiši(\"   [dependencies]\");\npiši(\"   cebir = '^2.0.0'\");\npiši(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\npiši(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"Paket kurma:\");\npiši(\"  hudhudscript install cebir\");\npiši(\"  hudhudscript install fizik@1.5.0\");\n\npiši(\"\\nPaket güncelleme:\");\npiši(\"  hudhudscript update cebir\");\npiši(\"  hudhudscript update --all\");\n\npiši(\"\\nPaket kaldırma:\");\npiši(\"  hudhudscript remove cebir\");\n\npiši(\"\\nKurulu paketleri listeleme:\");\npiši(\"  hudhudscript list\");\n\npiši(\"\\nPaket arama:\");\npiši(\"  hudhudscript search matematik\");\n\npiši(\"\\nPaket bilgisi:\");\npiši(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\npiši(\"\\n\\n🔗 Paket Bağımlılıkları:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"Versiyon belirtme:\");\npiši(\"  'cebir' = '^2.0.0'    # 2.x.x\");\npiši(\"  'fizik' = '~1.5.0'    # 1.5.x\");\npiši(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\npiši(\"\\nGit deposundan:\");\npiši(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\npiši(\"\\nYerel yoldan:\");\npiši(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\npiši(\"\\n\\n🔒 Paket Güvenliği:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"Güvenlik kontrolü:\");\npiši(\"  hudhudscript audit\");\n\npiši(\"\\nChecksum doğrulama:\");\npiši(\"  hudhudscript verify cebir\");\n\npiši(\"\\n============================================================\");\npiši(\"✓ Paket sistemi demo tamamlandı!\");\npiši(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\npiši(\"============================================================\");\n", "arrays": "// Bosanski - Nizovi\n// Nizovi sa domaćim ključnim riječima\n\n// Kreiraj nizove\nneka brojevi = [1, 2, 3, 4, 5];\nneka imena = [\"Amina\", \"Emir\", \"Hana\"];\n\n// Pristupi elementima\nneka prvi = brojevi[0];\nneka drugi = brojevi[1];\n\n// Rezultat\nprvi;\n", "math": "// BS - Math Module\n\nfunction add(a, b) {\n    vrati a + b;\n}\n\nfunction subtract(a, b) {\n    vrati a - b;\n}\n\nfunction multiply(a, b) {\n    vrati a * b;\n}\n\nfunction divide(a, b) {\n    ako (b == 0) {\n        štampaj(\"Error: Division by zero!\");\n        vrati 0;\n    } inače {\n        vrati a / b;\n    }\n}\n\nfunction square(x) {\n    vrati x * x;\n}\n\nfunction cube(x) {\n    vrati x * x * x;\n}\n\nfunction abs(x) {\n    ako (x < 0) {\n        vrati -x;\n    } inače {\n        vrati x;\n    }\n}\n\nfunction max(a, b) {\n    ako (a > b) {\n        vrati a;\n    } inače {\n        vrati b;\n    }\n}\n\nfunction min(a, b) {\n    ako (a < b) {\n        vrati a;\n    } inače {\n        vrati b;\n    }\n}\n", "control_flow": "// Bosanski - Kontrola Toka\nvarijabla brojač = 0;\nvarijabla maksimum = 5;\n\n// Loop\ndok (brojač < maksimum) {\n    brojač = brojač + 1;\n}\n\n// Conditional\nvarijabla rezultat = 85;\n\nako (rezultat >= 90) {\n    rezultat;\n} inače {\n    ako (rezultat >= 80) {\n        rezultat;\n    } inače {\n        rezultat;\n    }\n}\n\nbrojač;", "state_machine": "// State Machine Example\nneka state = \"initial\";\n\nako (state == \"initial\") {\n    štampaj(\"Starting\");\n    state = \"running\";\n}\n\nštampaj(state);\n", "conditionals": "// Bosanski - Uslovna logika\nneka bodovi = 85;\n\nako (bodovi >= 90) {\n    ispiši(1000);\n} inače {\n    ako (bodovi >= 80) {\n        ispiši(2000);\n    } inače {\n        ispiši(3000);\n    }\n}\n\nispiši(999);\n", "code_organization": "// Bosanski - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable za large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// koristi \"agent/agent_definition.hudhud\";\n// koristi \"constitution/laws.hudhud\";\n// koristi \"data/note.hudhud\";\n// koristi \"utils/math.hudhud\";\n", "module_concepts": "// Bosanski - Modules & Code Organization\n// Demonstrates module system: koristi/uvezi like Rust, Java, C++, Python\n\n// Import math module\nkoristi \"math.hudhud\";\n\n// Example syntax variations:\n// koristi \"math.hudhud\";\n// koristi { add, subtract } od \"math.hudhud\";\n// koristi \"math.hudhud\" kao math;\n\n// Using functions iz math module\nneka sum = add(10, 5);\nštampaj(sum);\n\nneka diff = subtract(20, 8);\nštampaj(diff);\n\nneka product = multiply(4, 7);\nštampaj(product);\n\nneka quotient = divide(15, 3);\nštampaj(quotient);\n\nneka squared = square(5);\nštampaj(squared);\n\nneka cubed = cube(3);\nštampaj(cubed);\n\nneka absolute = abs(-42);\nštampaj(absolute);\n\nneka maximum = max(100, 50);\nštampaj(maximum);\n\nneka minimum = min(100, 50);\nštampaj(minimum);\n\n// Complex calculation using multiple functions\nneka result = add(multiply(5, 3), divide(20, 4));\nštampaj(result);\n", "switch_concepts": "// Bosanski - Switch/Case koncepti\n// switch/case/default\n\nfunkcija tip_dana(day) {\n    odaberi (day) {\n        slučaj \"Monday\":\n        slučaj \"Tuesday\":\n        slučaj \"Wednesday\":\n        slučaj \"Thursday\":\n        slučaj \"Friday\":\n            vrati \"Radni dan\";\n        slučaj \"Saturday\":\n        slučaj \"Sunday\":\n            vrati \"Vikend\";\n        podrazumijevano:\n            vrati \"Nepoznato\";\n    }\n}\n\nispiši(\"=== Day Types ===\");\nispiši(\"Monday: \" + tip_dana(\"Monday\"));\nispiši(\"Saturday: \" + tip_dana(\"Saturday\"));\nispiši(\"Holiday: \" + tip_dana(\"Holiday\"));\n\nfunkcija ocjena_slovo(score) {\n    odaberi (score) {\n        slučaj 90:\n            vrati \"A\";\n        slučaj 80:\n            vrati \"B\";\n        slučaj 70:\n            vrati \"C\";\n        slučaj 60:\n            vrati \"D\";\n        podrazumijevano:\n            vrati \"F\";\n    }\n}\n\nispiši(\"\\n=== Grades ===\");\nispiši(\"90: \" + ocjena_slovo(90));\nispiši(\"70: \" + ocjena_slovo(70));\nispiši(\"50: \" + ocjena_slovo(50));\n\nfunkcija poruka_statusa(code) {\n    odaberi (code) {\n        slučaj 200:\n            vrati \"OK\";\n        slučaj 404:\n            vrati \"Not Found\";\n        slučaj 500:\n            vrati \"Server Error\";\n        podrazumijevano:\n            vrati \"Nepoznato Status\";\n    }\n}\n\nispiši(\"\\n=== HTTP Status ===\");\nispiši(\"200: \" + poruka_statusa(200));\nispiši(\"404: \" + poruka_statusa(404));\n", "event_concepts": "// Bosanski - Event Concepts\n\ndogađaj UserLogin {\n    ispiši(\"User logged in\");\n}\n\ndogađaj DataReceived {\n    ispiši(\"Data received\");\n}\n\ndogađaj ErrorOccurred {\n    ispiši(\"Error occurred\");\n}\n\nfunkcija on_login(username) {\n    ispiši(\"Login: \" + username);\n    vrati \"Welcome, \" + username;\n}\n\nfunkcija on_data(source) {\n    ispiši(\"Data from: \" + source);\n    vrati \"Processed: \" + source;\n}\n\nfunkcija on_error(message) {\n    ispiši(\"Error: \" + message);\n    vrati \"Handled: \" + message;\n}\n\nispiši(\"=== Event System ===\");\nneka r1 = on_login(\"admin\");\nispiši(r1);\nneka r2 = on_data(\"sensor_1\");\nispiši(r2);\nneka r3 = on_error(\"timeout\");\nispiši(r3);\n", "functions": "// Bosanski - Funkcije\n// Primjeri definisanja i korištenja funkcija\n\n// Jednostavna funkcija\nfunkcija pozdravi() {\n    ispiši(\"Zdravo Svijete!\");\n}\n\n// Funkcija sa parametrima\nfunkcija saberi(a, b) {\n    vrati a + b;\n}\n\n// Višeparametarska funkcija\nfunkcija izračunaj(broj1, broj2, operacija) {\n    ako (operacija == \"saberi\") {\n        vrati broj1 + broj2;\n    } inače {\n        vrati 0;\n    }\n}\n\n// Matematičke funkcije\nfunkcija kvadrat(x) {\n    vrati x * x;\n}\n\nfunkcija kub(x) {\n    vrati x * x * x;\n}\n\n// Korištenje funkcija\npozdravi();\n\nneka rezultat1 = saberi(5, 3);\nispiši(rezultat1);\n\nneka rezultat2 = izračunaj(10, 5, \"saberi\");\nispiši(rezultat2);\n\nneka rezultat_kvadrat = kvadrat(4);\nispiši(rezultat_kvadrat);\n\nneka rezultat_kub = kub(3);\nispiši(rezultat_kub);\n\n// Kompozicija funkcija\nneka ukupno = saberi(kvadrat(3), kub(2));\nispiši(ukupno);\n", "entity_concepts": "// Bosanski - Koncepti entiteta\n\nneka korisnik = {\n    id: 1,\n    ime: \"Amina\",\n    email: \"amina@primjer.com\",\n    uloga: \"programer\"\n};\n\nneka proizvod = {\n    id: 101,\n    ime: \"HudHudScript IDE\",\n    verzija: \"2.0\",\n    cijena: 49\n};\n\nneka narudžba = {\n    id: 1001,\n    korisnik_id: 1,\n    proizvod_id: 101,\n    količina: 2,\n    status: \"potvrđeno\"\n};\n\nfunkcija info_entiteta(entitet) {\n    vrati \"Entitet #\" + entitet.id + \": \" + entitet.ime;\n}\n\nfunkcija izračunaj_ukupno(narudžba, cijena) {\n    vrati narudžba.količina * cijena;\n}\n\nispiši(\"=== Sistem entiteta ===\");\nispiši(info_entiteta(korisnik));\nispiši(info_entiteta(proizvod));\nneka ukupno = izračunaj_ukupno(narudžba, proizvod.cijena);\nispiši(\"Narudžba #\" + narudžba.id + \" ukupno: \" + ukupno);\nispiši(\"Status: \" + narudžba.status);\n", "error_concepts": "// Bosanski - Error Concepts\n\nfunkcija validate_age(age) {\n    ako (age < 0) {\n        baci \"Invalid age: negative\";\n    }\n    ako (age > 150) {\n        baci \"Invalid age: too large\";\n    }\n    vrati age;\n}\n\nfunkcija validate_email(email) {\n    ako (email == \"\") {\n        baci \"Empty email\";\n    }\n    ispiši(\"Email valid: \" + email);\n    vrati email;\n}\n\nispiši(\"=== Validation ===\");\n\npokušaj {\n    validate_age(25);\n    ispiši(\"Age 25: valid\");\n} uhvati (error) {\n    ispiši(\"Error: \" + error);\n}\n\npokušaj {\n    validate_age(-5);\n} uhvati (error) {\n    ispiši(\"Error: \" + error);\n}\n\npokušaj {\n    validate_email(\"user@example.com\");\n    validate_email(\"\");\n} uhvati (error) {\n    ispiši(\"Email error: \" + error);\n} konačno {\n    ispiši(\"Validation complete\");\n}\n"}, "de": {"objects": "// Deutsch - Objekte\n// Objekte mit nativen Schlüsselwörtern\n\n// Objekt erstellen\nsei person = {\n    name: \"Anna\",\n    alter: 30,\n    stadt: \"Berlin\"\n};\n\n// Auf Eigenschaften zugreifen\nsei name = person.name;\nsei alter = person.alter;\n\n// Ergebnis\nname;\n", "chemistry": "// DE - Chemistry Module\n\n// Molar Mass\nfunktion molarMass(atoms, atomicWeight) {\n    zurück atoms * atomicWeight;\n}\n\n// Concentration = Moles / Volume\nfunktion concentration(moles, volume) {\n    zurück moles / volume;\n}\n\n// pH calculation\nfunktion pH(hydrogenConcentration) {\n    zurück 14 - hydrogenConcentration;\n}\n\n// Density = Mass / Volume\nfunktion density(mass, volume) {\n    zurück mass / volume;\n}\n\n// Dilution: C1*V1 = C2*V2\nfunktion dilution(c1, v1, v2) {\n    zurück (c1 * v1) / v2;\n}\n", "loops": "// Deutsch - Schleifen\nlasse zähler = 0;\nlasse maximum = 5;\n\nwährend (zähler < maximum) {\n    drucke(zähler);\n    zähler = zähler + 1;\n}\n\ndrucke(999);\n", "physik": "// Deutsch - Physics Module\n\nfunction geschwindigkeit(distance, time) {\n    zurück distance / time;\n}\n\nfunction kraft(mass, acceleration) {\n    zurück mass * acceleration;\n}\n\nfunction kinetischeEnergie(mass, velocity) {\n    zurück 0.5 * mass * velocity * velocity;\n}\n\nfunction potentielleEnergie(mass, gravity, height) {\n    zurück mass * gravity * height;\n}\n\nfunction impuls(mass, velocity) {\n    zurück mass * velocity;\n}\n", "data_processing": "// Deutsch - Data Processing\n// Using NATIVE Deutsch keywords\n\nvariable value1 = 100;\nvariable value2 = 200;\nvariable value3 = 300;\n\nvariable total = value1+ value2+ value3;\nvariable average = total / 3;\n\ndrucken(total);\ndrucken(average);\n", "modules_import": "// Deutsch - Modules Import Example\n\n// Import math module (direct access)\nverwenden \"mathematik.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nverwenden \"physik.hudhud\" als fizik;\n\n// Import chemistry (direct access)\nverwenden \"chemie.hudhud\";\n\n// Using math functions (direct)\nvariable sum = addieren(10, 5);\ndrucken(sum);\n\nvariable product = multiplizieren(4, 7);\ndrucken(product);\n\n// Using physics functions (via alias: fizik.functionName)\nvariable f = fizik.kraft(10, 9.8);\ndrucken(f);\n\nvariable ke = fizik.kinetischeEnergie(5, 10);\ndrucken(ke);\n\n// Using chemistry functions (direct)\nvariable d = dichte(100, 50);\ndrucken(d);\n\nvariable c = konzentration(2, 5);\ndrucken(c);\n", "return_concept": "// Deutsch - Rückgabe-Konzept\n// return\n\nfunktion quadrat(x) {\n    zurück x * x;\n}\n\nfunktion würfel(x) {\n    zurück x * x * x;\n}\n\ndrucke(\"=== Math Functions ===\");\ndrucke(\"quadrat(5): \" + quadrat(5));\ndrucke(\"würfel(3): \" + würfel(3));\n\nfunktion absolut(x) {\n    wenn (x < 0) {\n        zurück -x;\n    }\n    zurück x;\n}\n\ndrucke(\"\\n=== Absolute ===\");\ndrucke(\"absolut(-7): \" + absolut(-7));\ndrucke(\"absolut(3): \" + absolut(3));\n\nfunktion punkt_erstellen(x, y) {\n    zurück { x: x, y: y };\n}\n\nsei p = punkt_erstellen(10, 20);\ndrucke(\"\\n=== Point ===\");\ndrucke(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfunktion fakultät(n) {\n    wenn (n <= 1) {\n        zurück 1;\n    }\n    zurück n * fakultät(n - 1);\n}\n\ndrucke(\"\\n=== Factorial ===\");\ndrucke(\"5! = \" + fakultät(5));\ndrucke(\"10! = \" + fakultät(10));\n", "customer_service": "// Deutsch - Kundenservice-Agent\n\ngesetz Respekt_Gesetz {\n    beschreibung: \"Der Agent muss hoeflich und respektvoll sein\",\n    prioritaet: 1\n}\n\nverfassung Service_Verfassung {\n    gesetze: [Respekt_Gesetz],\n    beschreibung: \"Kundenservice-Rahmenwerk\"\n}\n\nagent Service_Agent {\n    modell: \"gpt-4\"\n}\n\nfunktion begrüße(kundenname) {\n    sei nachricht = \"Hallo \" + kundenname + \", wie kann ich Ihnen helfen?\";\n    drucke(nachricht);\n    zurück nachricht;\n}\n\nfunktion bearbeite_anfrage(typ, details) {\n    wenn (typ == \"Beschwerde\") {\n        drucke(\"Ich entschuldige mich fuer die Unannehmlichkeiten. Ich werde Ihnen helfen.\");\n    } sonst {\n        drucke(\"Vielen Dank fuer Ihre Anfrage. Ich bearbeite sie jetzt.\");\n    }\n    zurück \"Bearbeitet: \" + typ + \" - \" + details;\n}\n\ndrucke(\"=== Kundenservice-Agent ===\");\nbegrüße(\"Hans\");\nsei ergebnis = bearbeite_anfrage(\"Beschwerde\", \"Lieferverzoegerung\");\ndrucke(ergebnis);\n", "basic_example": "// Deutsch - Basic Example with NATIVE keywords\nvariable a = 10;\nvariable b = 20;\nvariable summe = a + b;\n\ndrucken(summe);\n", "physics": "// DE - Physics Module\n\n// Speed = Distance / Time\nfunktion speed(distance, time) {\n    zurück distance / time;\n}\n\n// Force = Mass * Acceleration\nfunktion force(mass, acceleration) {\n    zurück mass * acceleration;\n}\n\n// Kinetic Energy = 0.5 * Mass * Velocity^2\nfunktion kineticEnergy(mass, velocity) {\n    zurück 0.5 * mass * velocity * velocity;\n}\n\n// Potential Energy = Mass * Gravity * Height\nfunktion potentialEnergy(mass, gravity, height) {\n    zurück mass * gravity * height;\n}\n\n// Momentum = Mass * Velocity\nfunktion momentum(mass, velocity) {\n    zurück mass * velocity;\n}\n", "error_handling": "// Deutsch - Fehlerbehandlung\n// Einfache Fehlerkontrolle mit if-else\n\n// Funktion zur Fehlerprüfung\nfunktion teile(a, b) {\n    wenn (b == 0) {\n        zurück { fehler: wahr, nachricht: \"Division durch Null Fehler\", wert: 0 };\n    }\n    zurück { fehler: falsch, nachricht: \"\", wert: a / b };\n}\n\ndrucke(\"=== Divisionsoperation ===\");\n\n// Erste Division\ndrucke(\"10 / 2 Operation:\");\nlasse ergebnis1 = teile(10, 2);\nwenn (ergebnis1.fehler) {\n    drucke(\"Fehler: \" + ergebnis1.nachricht);\n} sonst {\n    drucke(\"10 / 2 = \" + ergebnis1.wert);\n}\n\n// Division durch Null\ndrucke(\"10 / 0 Operation:\");\nlasse ergebnis2 = teile(10, 0);\nwenn (ergebnis2.fehler) {\n    drucke(\"Fehler erkannt: \" + ergebnis2.nachricht);\n} sonst {\n    drucke(\"Ergebnis: \" + ergebnis2.wert);\n}\n\n// Beispiel für Dateiverarbeitung\ndrucke(\"=== Dateiverarbeitung ===\");\n\nfunktion datei_verarbeiten(dateiname) {\n    wenn (dateiname == \"\") {\n        zurück { erfolgreich: falsch, nachricht: \"Leerer Dateiname Fehler\" };\n    }\n    drucke(\"Verarbeite: \" + dateiname);\n    zurück { erfolgreich: wahr, daten: \"Daten von \" + dateiname };\n}\n\nlasse datei_ergebnis = datei_verarbeiten(\"bericht.txt\");\nwenn (datei_ergebnis.erfolgreich) {\n    drucke(\"Ergebnis: \" + datei_ergebnis.daten);\n} sonst {\n    drucke(\"Fehler: \" + datei_ergebnis.nachricht);\n}\n\ndrucke(\"Alles erledigt\");\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici paket kullanımı\nverwenden \"cebir\";\nverwenden \"fizik\" als paket;\n\n// Paket içinden belirli modülleri içe aktarma\nverwenden \"cebir/matris\";\nverwenden \"cebir/vektor\";\nverwenden \"fizik/hareket\";\n\nschreibe(\"============================================================\");\nschreibe(\"HudHudScript Paket Sistemi Demo\");\nschreibe(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nschreibe(\"📦 Cebir Paketi Kullanımı:\");\nschreibe(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nvariable matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nvariable matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nschreibe(\"Matris 1:\");\nmatris1.goster();\n\nschreibe(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nvariable toplam = matris1.topla(matris2);\nschreibe(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nvariable vektor1 = Vektor([1, 2, 3]);\nvariable vektor2 = Vektor([4, 5, 6]);\n\nschreibe(\"\\n\\n📐 Vektör İşlemleri:\");\nschreibe(\"─────────────────────────────────────────────────────────\\n\");\n\nschreibe(\"Vektör 1: \" + vektor1.toString());\nschreibe(\"Vektör 2: \" + vektor2.toString());\n\nvariable noktaSal = vektor1.noktaSal(vektor2);\nschreibe(\"Nokta Çarpım: \" + noktaSal);\n\nvariable caprazCarpim = vektor1.caprazCarpim(vektor2);\nschreibe(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nschreibe(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nschreibe(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nvariable baslangicHizi = 0;      // m/s\nvariable ivme = 9.8;              // m/s² (yerçekimi)\nvariable zaman = 5;               // saniye\n\nvariable sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nvariable mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nschreibe(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nschreibe(\"İvme: \" + ivme + \" m/s²\");\nschreibe(\"Zaman: \" + zaman + \" s\");\nschreibe(\"─────────────────────────────────────────────────────────\");\nschreibe(\"Son Hız: \" + sonHiz + \" m/s\");\nschreibe(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nschreibe(\"\\n\\n📝 Paket Oluşturma:\");\nschreibe(\"─────────────────────────────────────────────────────────\\n\");\n\nschreibe(\"1. hudhud.toml dosyası oluşturun:\");\nschreibe(\"   [package]\");\nschreibe(\"   name = 'matematik-utils'\");\nschreibe(\"   version = '1.0.0'\");\nschreibe(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nschreibe(\"\\n2. Bağımlılıklar ekleyin:\");\nschreibe(\"   [dependencies]\");\nschreibe(\"   cebir = '^2.0.0'\");\nschreibe(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nschreibe(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nschreibe(\"─────────────────────────────────────────────────────────\\n\");\n\nschreibe(\"Paket kurma:\");\nschreibe(\"  hudhudscript install cebir\");\nschreibe(\"  hudhudscript install fizik@1.5.0\");\n\nschreibe(\"\\nPaket güncelleme:\");\nschreibe(\"  hudhudscript update cebir\");\nschreibe(\"  hudhudscript update --all\");\n\nschreibe(\"\\nPaket kaldırma:\");\nschreibe(\"  hudhudscript remove cebir\");\n\nschreibe(\"\\nKurulu paketleri listeleme:\");\nschreibe(\"  hudhudscript list\");\n\nschreibe(\"\\nPaket arama:\");\nschreibe(\"  hudhudscript search matematik\");\n\nschreibe(\"\\nPaket bilgisi:\");\nschreibe(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nschreibe(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nschreibe(\"─────────────────────────────────────────────────────────\\n\");\n\nschreibe(\"Versiyon belirtme:\");\nschreibe(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nschreibe(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nschreibe(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nschreibe(\"\\nGit deposundan:\");\nschreibe(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nschreibe(\"\\nYerel yoldan:\");\nschreibe(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nschreibe(\"\\n\\n🔒 Paket Güvenliği:\");\nschreibe(\"─────────────────────────────────────────────────────────\\n\");\n\nschreibe(\"Güvenlik kontrolü:\");\nschreibe(\"  hudhudscript audit\");\n\nschreibe(\"\\nChecksum doğrulama:\");\nschreibe(\"  hudhudscript verify cebir\");\n\nschreibe(\"\\n============================================================\");\nschreibe(\"✓ Paket sistemi demo tamamlandı!\");\nschreibe(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nschreibe(\"============================================================\");\n", "arrays": "// Deutsch - Arrays\n// Arrays mit nativen Schlüsselwörtern\n\n// Arrays erstellen\nlasse zahlen = [1, 2, 3, 4, 5];\nlasse namen = [\"Anna\", \"Bernd\", \"Christian\"];\n\n// Auf Elemente zugreifen\nlasse erstes = zahlen[0];\nlasse zweites = zahlen[1];\n\n// Ergebnis\nerstes;\n", "math": "// DE - Math Module\n\n// Addition\nfunction add(a, b) {\n    zurück a + b;\n}\n\n// Subtraction\nfunction subtract(a, b) {\n    zurück a - b;\n}\n\n// Multiplication\nfunction multiply(a, b) {\n    zurück a * b;\n}\n\n// Division\nfunction divide(a, b) {\n    wenn (b == 0) {\n        drucken(\"Error: Division by zero!\");\n        zurück 0;\n    } sonst {\n        zurück a / b;\n    }\n}\n\n// Square\nfunction square(x) {\n    zurück x * x;\n}\n\n// Cube\nfunction cube(x) {\n    zurück x * x * x;\n}\n\n// Absolute value\nfunction abs(x) {\n    wenn (x < 0) {\n        zurück -x;\n    } sonst {\n        zurück x;\n    }\n}\n\n// Maximum\nfunction max(a, b) {\n    wenn (a > b) {\n        zurück a;\n    } sonst {\n        zurück b;\n    }\n}\n\n// Minimum\nfunction min(a, b) {\n    wenn (a < b) {\n        zurück a;\n    } sonst {\n        zurück b;\n    }\n}\n", "control_flow": "// Deutsch - Kontrollfluss\nvariable zähler = 0;\nvariable maximum = 5;\n\n// Loop\nwährend (zähler < maximum) {\n    zähler = zähler + 1;\n}\n\n// Conditional\nvariable punktzahl = 85;\n\nwenn (punktzahl >= 90) {\n    punktzahl;\n} sonst {\n    wenn (punktzahl >= 80) {\n        punktzahl;\n    } sonst {\n        punktzahl;\n    }\n}\n\nzähler;\n", "state_machine": "// State Machine Example\nvariable state = \"initial\";\n\nwenn (state == \"initial\") {\n    drucken(\"Starting\");\n    state = \"running\";\n}\n\ndrucken(state);\n", "conditionals": "// Deutsch - Bedingte Logik\nsei punktzahl = 85;\n\nwenn (punktzahl >= 90) {\n    drucke(1000);\n} sonst {\n    wenn (punktzahl >= 80) {\n        drucke(2000);\n    } sonst {\n        drucke(3000);\n    }\n}\n\ndrucke(999);\n", "code_organization": "// Deutsch - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable für large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// verwenden \"agent/agent_definition.hudhud\";\n// verwenden \"constitution/laws.hudhud\";\n// verwenden \"data/note.hudhud\";\n// verwenden \"utils/math.hudhud\";\n", "module_concepts": "// Deutsch - Modules & Code Organization\n// Demonstrates module system: verwenden/importieren like Rust, Java, C++, Python\n\n// Import math module\nverwenden \"math.hudhud\";\n\n// Example syntax variations:\n// verwenden \"math.hudhud\";\n// verwenden { add, subtract } von \"math.hudhud\";\n// verwenden \"math.hudhud\" als math;\n\n// Using functions von math module\nvariable sum = add(10, 5);\ndrucken(sum);\n\nvariable diff = subtract(20, 8);\ndrucken(diff);\n\nvariable product = multiply(4, 7);\ndrucken(product);\n\nvariable quotient = divide(15, 3);\ndrucken(quotient);\n\nvariable squared = square(5);\ndrucken(squared);\n\nvariable cubed = cube(3);\ndrucken(cubed);\n\nvariable absolute = abs(-42);\ndrucken(absolute);\n\nvariable maximum = max(100, 50);\ndrucken(maximum);\n\nvariable minimum = min(100, 50);\ndrucken(minimum);\n\n// Complex calculation using multiple functions\nvariable result = add(multiply(5, 3), divide(20, 4));\ndrucken(result);\n", "mathematik": "// Deutsch - Math Module\n\nfunction addieren(a, b) {\n    zurück a + b;\n}\n\nfunction subtrahieren(a, b) {\n    zurück a - b;\n}\n\nfunction multiplizieren(a, b) {\n    zurück a * b;\n}\n\nfunction dividieren(a, b) {\n    wenn (b == 0) {\n        drucken(\"Error: Division by zero!\");\n        zurück 0;\n    } sonst {\n        zurück a / b;\n    }\n}\n\nfunction quadrat(x) {\n    zurück x * x;\n}\n\nfunction kubik(x) {\n    zurück x * x * x;\n}\n\nfunction absolut(x) {\n    wenn (x < 0) {\n        zurück -x;\n    } sonst {\n        zurück x;\n    }\n}\n\nfunction maximum(a, b) {\n    wenn (a > b) {\n        zurück a;\n    } sonst {\n        zurück b;\n    }\n}\n\nfunction minimum(a, b) {\n    wenn (a < b) {\n        zurück a;\n    } sonst {\n        zurück b;\n    }\n}\n", "switch_concepts": "// Deutsch - Switch/Case Konzepte\n// Mit if-else für mehrere Bedingungen\n\nfunktion tag_typ(tag) {\n    wenn (tag == \"Montag\") { zurück \"Wochentag\"; }\n    wenn (tag == \"Dienstag\") { zurück \"Wochentag\"; }\n    wenn (tag == \"Mittwoch\") { zurück \"Wochentag\"; }\n    wenn (tag == \"Donnerstag\") { zurück \"Wochentag\"; }\n    wenn (tag == \"Freitag\") { zurück \"Wochentag\"; }\n    wenn (tag == \"Samstag\") { zurück \"Wochenende\"; }\n    wenn (tag == \"Sonntag\") { zurück \"Wochenende\"; }\n    zurück \"Unbekannt\";\n}\n\ndrucke(\"=== Tag Typen ===\");\ndrucke(\"Montag: \" + tag_typ(\"Montag\"));\ndrucke(\"Samstag: \" + tag_typ(\"Samstag\"));\ndrucke(\"Feiertag: \" + tag_typ(\"Feiertag\"));\n\nfunktion noten_buchstabe(punkte) {\n    wenn (punkte == 90) { zurück \"A\"; }\n    wenn (punkte == 80) { zurück \"B\"; }\n    wenn (punkte == 70) { zurück \"C\"; }\n    wenn (punkte == 60) { zurück \"D\"; }\n    zurück \"F\";\n}\n\ndrucke(\"=== Noten ===\");\ndrucke(\"90: \" + noten_buchstabe(90));\ndrucke(\"70: \" + noten_buchstabe(70));\ndrucke(\"50: \" + noten_buchstabe(50));\n\nfunktion status_nachricht(code) {\n    wenn (code == 200) { zurück \"OK\"; }\n    wenn (code == 404) { zurück \"Nicht gefunden\"; }\n    wenn (code == 500) { zurück \"Server Fehler\"; }\n    zurück \"Unbekannter Status\";\n}\n\ndrucke(\"=== HTTP Status ===\");\ndrucke(\"200: \" + status_nachricht(200));\ndrucke(\"404: \" + status_nachricht(404));\n", "event_concepts": "// Deutsch - Event Concepts\n\nereignis UserLogin {\n    drucke(\"User logged in\");\n}\n\nereignis DataReceived {\n    drucke(\"Data received\");\n}\n\nereignis ErrorOccurred {\n    drucke(\"Error occurred\");\n}\n\nfunktion on_login(username) {\n    drucke(\"Login: \" + username);\n    zurück \"Welcome, \" + username;\n}\n\nfunktion on_data(source) {\n    drucke(\"Data from: \" + source);\n    zurück \"Processed: \" + source;\n}\n\nfunktion on_error(message) {\n    drucke(\"Error: \" + message);\n    zurück \"Handled: \" + message;\n}\n\ndrucke(\"=== Event System ===\");\nsei r1 = on_login(\"admin\");\ndrucke(r1);\nsei r2 = on_data(\"sensor_1\");\ndrucke(r2);\nsei r3 = on_error(\"timeout\");\ndrucke(r3);\n", "functions": "// Deutsch - Funktionen\n\nfunktion grüßen() {\n    drucke(\"Hallo Welt!\");\n}\n\nfunktion addieren(a, b) {\n    zurück a + b;\n}\n\nfunktion berechnen(zahl1, zahl2, operation) {\n    wenn (operation == \"addieren\") {\n        zurück zahl1 + zahl2;\n    } sonst {\n        zurück 0;\n    }\n}\n\nfunktion quadrat(x) {\n    zurück x * x;\n}\n\nfunktion würfel(x) {\n    zurück x * x * x;\n}\n\ngrüßen();\n\nlasse ergebnis1 = addieren(5, 3);\ndrucke(ergebnis1);\n\nlasse ergebnis2 = berechnen(10, 5, \"addieren\");\ndrucke(ergebnis2);\n\nlasse quadrat_ergebnis = quadrat(4);\ndrucke(quadrat_ergebnis);\n\nlasse würfel_ergebnis = würfel(3);\ndrucke(würfel_ergebnis);\n\nlasse gesamt = addieren(quadrat(3), würfel(2));\ndrucke(gesamt);\n", "chemie": "// Deutsch - Chemistry Module\n\nfunktion molareMasse(atoms, atomicWeight) {\n    zurück atoms * atomicWeight;\n}\n\nfunktion konzentration(moles, volume) {\n    zurück moles / volume;\n}\n\nfunktion pH(hydrogenConcentration) {\n    zurück 14 - hydrogenConcentration;\n}\n\nfunktion dichte(mass, volume) {\n    zurück mass / volume;\n}\n\nfunktion verdünnung(c1, v1, v2) {\n    zurück (c1 * v1) / v2;\n}\n", "entity_concepts": "// Deutsch - Entitätskonzepte\n\nsei benutzer = {\n    id: 1,\n    name: \"Anna\",\n    email: \"anna@beispiel.de\",\n    rolle: \"Entwicklerin\"\n};\n\nsei produkt = {\n    id: 101,\n    name: \"HudHudScript IDE\",\n    version: \"2.0\",\n    preis: 49\n};\n\nsei bestellung = {\n    id: 1001,\n    benutzer_id: 1,\n    produkt_id: 101,\n    menge: 2,\n    status: \"bestätigt\"\n};\n\nfunktion entität_info(entität) {\n    zurück \"Entität #\" + entität.id + \": \" + entität.name;\n}\n\nfunktion berechne_gesamt(bestellung, preis) {\n    zurück bestellung.menge * preis;\n}\n\ndrucke(\"=== Entitätssystem ===\");\ndrucke(entität_info(benutzer));\ndrucke(entität_info(produkt));\nsei gesamt = berechne_gesamt(bestellung, produkt.preis);\ndrucke(\"Bestellung #\" + bestellung.id + \" Gesamt: \" + gesamt);\ndrucke(\"Status: \" + bestellung.status);\n", "error_concepts": "// Deutsch - Fehlerkonzepte\n// Einfache Validierungsfunktionen\n\nfunktion alter_validieren(alter) {\n    wenn (alter < 0) {\n        zurück { gültig: falsch, fehler: \"Ungültiges Alter: negativ\" };\n    }\n    wenn (alter > 150) {\n        zurück { gültig: falsch, fehler: \"Ungültiges Alter: zu groß\" };\n    }\n    zurück { gültig: wahr, alter: alter };\n}\n\nfunktion email_validieren(email) {\n    wenn (email == \"\") {\n        zurück { gültig: falsch, fehler: \"Leere E-Mail\" };\n    }\n    zurück { gültig: wahr, email: email };\n}\n\ndrucke(\"=== Validierung ===\");\n\n// Altersvalidierung\nlasse alter_ergebnis1 = alter_validieren(25);\nwenn (alter_ergebnis1.gültig) {\n    drucke(\"Alter 25 ist gültig\");\n} sonst {\n    drucke(\"Fehler: \" + alter_ergebnis1.fehler);\n}\n\nlasse alter_ergebnis2 = alter_validieren(-5);\nwenn (alter_ergebnis2.gültig) {\n    drucke(\"Alter ist gültig\");\n} sonst {\n    drucke(\"Fehler: \" + alter_ergebnis2.fehler);\n}\n\n// E-Mail-Validierung\nlasse email_ergebnis1 = email_validieren(\"user@example.com\");\nwenn (email_ergebnis1.gültig) {\n    drucke(\"E-Mail gültig: \" + email_ergebnis1.email);\n} sonst {\n    drucke(\"E-Mail Fehler: \" + email_ergebnis1.fehler);\n}\n\nlasse email_ergebnis2 = email_validieren(\"\");\nwenn (email_ergebnis2.gültig) {\n    drucke(\"E-Mail gültig\");\n} sonst {\n    drucke(\"E-Mail Fehler: \" + email_ergebnis2.fehler);\n}\n\ndrucke(\"Validierung abgeschlossen\");\n"}, "el": {"objects": "// Ελληνικά - Αντικείμενα\n// Αντικείμενα με εγγενείς λέξεις-κλειδιά\n\n// Δημιουργία αντικειμένου\nέστω άτομο = {\n    όνομα: \"Αλίκη\",\n    ηλικία: 30,\n    πόλη: \"Αθήνα\"\n};\n\n// Πρόσβαση σε ιδιότητες\nέστω όνομα = άτομο.όνομα;\nέστω ηλικία = άτομο.ηλικία;\n\n// Αποτέλεσμα\nόνομα;\n", "chemistry": "// EL - Chemistry Module\n\nσυνάρτηση molarMass(atoms, atomicWeight) {\n    επιστροφή atoms * atomicWeight;\n}\n\nσυνάρτηση concentration(moles, volume) {\n    επιστροφή moles / volume;\n}\n\nσυνάρτηση pH(hydrogenConcentration) {\n    επιστροφή 14 - hydrogenConcentration;\n}\n\nσυνάρτηση density(mass, volume) {\n    επιστροφή mass / volume;\n}\n\nσυνάρτηση dilution(c1, v1, v2) {\n    επιστροφή (c1 * v1) / v2;\n}\n", "loops": "// Ελληνικά - Βρόχοι\nέστω μετρητής = 0;\nέστω μέγιστο = 5;\n\nενώ (μετρητής < μέγιστο) {\n    εκτύπωσε(μετρητής);\n    μετρητής = μετρητής + 1;\n}\n\nεκτύπωσε(999);\n", "data_processing": "// Ελληνικά - Data Processing\n// Using NATIVE Ελληνικά keywords\n\nας data1 = 100;\nας data2 = 200;\nας data3 = 300;\n\nας total = value1+ value2+ value3;\nας average = total / 3;\n\nektyposi(total);\nektyposi(average);\n", "modules_import": "// EL - Modules Import Example\n\n// Import math module (direct access)\nχρήση \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nχρήση \"physics.hudhud\" ως fizik;\n\n// Import chemistry (direct access)\nχρήση \"chemistry.hudhud\";\n\n// Using math functions (direct)\nας sum = add(10, 5);\nεκτύπωση(sum);\n\nας product = multiply(4, 7);\nεκτύπωση(product);\n\n// Using physics functions (via alias: fizik.functionName)\nας f = fizik.force(10, 9.8);\nεκτύπωση(f);\n\nας ke = fizik.kineticEnergy(5, 10);\nεκτύπωση(ke);\n\n// Using chemistry functions (direct)\nας d = density(100, 50);\nεκτύπωση(d);\n\nας c = concentration(2, 5);\nεκτύπωση(c);\n", "return_concept": "// Ελληνικά - Έννοια Επιστροφής\n// return\n\nσυνάρτηση τετράγωνο(x) {\n    επέστρεψε x * x;\n}\n\nσυνάρτηση κύβος(x) {\n    επέστρεψε x * x * x;\n}\n\nεκτύπωσε(\"=== Math Functions ===\");\nεκτύπωσε(\"τετράγωνο(5): \" + τετράγωνο(5));\nεκτύπωσε(\"κύβος(3): \" + κύβος(3));\n\nσυνάρτηση απόλυτο(x) {\n    αν (x < 0) {\n        επέστρεψε -x;\n    }\n    επέστρεψε x;\n}\n\nεκτύπωσε(\"\\n=== Absolute ===\");\nεκτύπωσε(\"απόλυτο(-7): \" + απόλυτο(-7));\nεκτύπωσε(\"απόλυτο(3): \" + απόλυτο(3));\n\nσυνάρτηση δημιούργησε_σημείο(x, y) {\n    επέστρεψε { x: x, y: y };\n}\n\nέστω p = δημιούργησε_σημείο(10, 20);\nεκτύπωσε(\"\\n=== Point ===\");\nεκτύπωσε(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nσυνάρτηση παραγοντικό(n) {\n    αν (n <= 1) {\n        επέστρεψε 1;\n    }\n    επέστρεψε n * παραγοντικό(n - 1);\n}\n\nεκτύπωσε(\"\\n=== Factorial ===\");\nεκτύπωσε(\"5! = \" + παραγοντικό(5));\nεκτύπωσε(\"10! = \" + παραγοντικό(10));\n", "customer_service": "// Ελληνικά - Πράκτορας Εξυπηρέτησης Πελατών\n// Χρήση ΕΓΓΕΝΩΝ λέξεων-κλειδιών Ελληνικών\n\nέστω χαιρετισμός = \"Γεια σας, πώς μπορώ να σας βοηθήσω;\";\nέστω απάντηση = \"Θα σας βοηθήσω με το αίτημά σας.\";\n\nεκτύπωσε(χαιρετισμός);\nεκτύπωσε(απάντηση);\n", "basic_example": "// Ελληνικά - Basic Example with NATIVE keywords\nμεταβλητή χ = 10;\nμεταβλητή ψ = 20;\nμεταβλητή άθροισμα = χ + ψ;\n\nεκτύπωση(άθροισμα);\n", "physics": "// EL - Physics Module\n\nσυνάρτηση speed(distance, time) {\n    επιστροφή distance / time;\n}\n\nσυνάρτηση force(mass, acceleration) {\n    επιστροφή mass * acceleration;\n}\n\nσυνάρτηση kineticEnergy(mass, velocity) {\n    επιστροφή 0.5 * mass * velocity * velocity;\n}\n\nσυνάρτηση potentialEnergy(mass, gravity, height) {\n    επιστροφή mass * gravity * height;\n}\n\nσυνάρτηση momentum(mass, velocity) {\n    επιστροφή mass * velocity;\n}\n", "error_handling": "// Ελληνικά - Διαχείριση σφαλμάτων\n// try/catch/finally, throw\n\n// Basic try/catch\nσυνάρτηση διαίρεσε(a, b) {\n    αν (b == 0) {\n        ρίξε \"Σφάλμα διαίρεσης με μηδέν\";\n    }\n    επέστρεψε a / b;\n}\n\nδοκίμασε {\n    έστω result = διαίρεσε(10, 2);\n    εκτύπωσε(\"10 / 2 = \" + result);\n} πιάσε (error) {\n    εκτύπωσε(\"Σφάλμα: \" + error);\n}\n\n// Try/catch/finally\nεκτύπωσε(\"\n=== Επεξεργασία αρχείου ===\");\n\nσυνάρτηση επεξεργασία_αρχείου(filename) {\n    αν (filename == \"\") {\n        ρίξε \"Σφάλμα κενού ονόματος αρχείου\";\n    }\n    εκτύπωσε(\"Επεξεργασία: \" + filename);\n    επέστρεψε \"Δεδομένα από \" + filename;\n}\n\nδοκίμασε {\n    έστω data = επεξεργασία_αρχείου(\"report.txt\");\n    εκτύπωσε(\"Αποτέλεσμα: \" + data);\n} πιάσε (error) {\n    εκτύπωσε(\"Σφάλμα: \" + error);\n} τελικά {\n    εκτύπωσε(\"Καθαρισμός ολοκληρώθηκε\");\n}\n\n// Nested error handling\nεκτύπωσε(\"\n=== Ένθετη διαχείριση σφαλμάτων ===\");\n\nδοκίμασε {\n    εκτύπωσε(\"Εξωτερικό μπλοκ δοκίμασε\");\n    δοκίμασε {\n        ρίξε \"Εσωτερικό σφάλμα\";\n    } πιάσε (inner_err) {\n        εκτύπωσε(\"Πιάστηκε εσωτερικό: \" + inner_err);\n        ρίξε \"Επαναριπτόμενο σφάλμα\";\n    }\n} πιάσε (outer_err) {\n    εκτύπωσε(\"Πιάστηκε εξωτερικό: \" + outer_err);\n} τελικά {\n    εκτύπωσε(\"Όλα ολοκληρώθηκαν\");\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici πακέτο kullanımı\nχρήση \"cebir\";\nχρήση \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nχρήση \"cebir/matris\";\nχρήση \"cebir/vektor\";\nχρήση \"fizik/hareket\";\n\nγράψε(\"============================================================\");\nγράψε(\"HudHudScript Paket Sistemi Demo\");\nγράψε(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nγράψε(\"📦 Cebir Paketi Kullanımı:\");\nγράψε(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nμεταβλητή matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nμεταβλητή matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nγράψε(\"Matris 1:\");\nmatris1.goster();\n\nγράψε(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nμεταβλητή toplam = matris1.topla(matris2);\nγράψε(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nμεταβλητή vektor1 = Vektor([1, 2, 3]);\nμεταβλητή vektor2 = Vektor([4, 5, 6]);\n\nγράψε(\"\\n\\n📐 Vektör İşlemleri:\");\nγράψε(\"─────────────────────────────────────────────────────────\\n\");\n\nγράψε(\"Vektör 1: \" + vektor1.toString());\nγράψε(\"Vektör 2: \" + vektor2.toString());\n\nμεταβλητή noktaSal = vektor1.noktaSal(vektor2);\nγράψε(\"Nokta Çarpım: \" + noktaSal);\n\nμεταβλητή caprazCarpim = vektor1.caprazCarpim(vektor2);\nγράψε(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nγράψε(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nγράψε(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nμεταβλητή baslangicHizi = 0;      // m/s\nμεταβλητή ivme = 9.8;              // m/s² (yerçekimi)\nμεταβλητή zaman = 5;               // saniye\n\nμεταβλητή sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nμεταβλητή mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nγράψε(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nγράψε(\"İvme: \" + ivme + \" m/s²\");\nγράψε(\"Zaman: \" + zaman + \" s\");\nγράψε(\"─────────────────────────────────────────────────────────\");\nγράψε(\"Son Hız: \" + sonHiz + \" m/s\");\nγράψε(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nγράψε(\"\\n\\n📝 Paket Oluşturma:\");\nγράψε(\"─────────────────────────────────────────────────────────\\n\");\n\nγράψε(\"1. hudhud.toml dosyası oluşturun:\");\nγράψε(\"   [package]\");\nγράψε(\"   name = 'matematik-utils'\");\nγράψε(\"   version = '1.0.0'\");\nγράψε(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nγράψε(\"\\n2. Bağımlılıklar ekleyin:\");\nγράψε(\"   [dependencies]\");\nγράψε(\"   cebir = '^2.0.0'\");\nγράψε(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nγράψε(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nγράψε(\"─────────────────────────────────────────────────────────\\n\");\n\nγράψε(\"Paket kurma:\");\nγράψε(\"  hudhudscript install cebir\");\nγράψε(\"  hudhudscript install fizik@1.5.0\");\n\nγράψε(\"\\nPaket güncelleme:\");\nγράψε(\"  hudhudscript update cebir\");\nγράψε(\"  hudhudscript update --all\");\n\nγράψε(\"\\nPaket kaldırma:\");\nγράψε(\"  hudhudscript remove cebir\");\n\nγράψε(\"\\nKurulu paketleri listeleme:\");\nγράψε(\"  hudhudscript list\");\n\nγράψε(\"\\nPaket arama:\");\nγράψε(\"  hudhudscript search matematik\");\n\nγράψε(\"\\nPaket bilgisi:\");\nγράψε(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nγράψε(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nγράψε(\"─────────────────────────────────────────────────────────\\n\");\n\nγράψε(\"Versiyon belirtme:\");\nγράψε(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nγράψε(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nγράψε(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nγράψε(\"\\nGit deposundan:\");\nγράψε(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nγράψε(\"\\nYerel yoldan:\");\nγράψε(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nγράψε(\"\\n\\n🔒 Paket Güvenliği:\");\nγράψε(\"─────────────────────────────────────────────────────────\\n\");\n\nγράψε(\"Güvenlik kontrolü:\");\nγράψε(\"  hudhudscript audit\");\n\nγράψε(\"\\nChecksum doğrulama:\");\nγράψε(\"  hudhudscript verify cebir\");\n\nγράψε(\"\\n============================================================\");\nγράψε(\"✓ Paket sistemi demo tamamlandı!\");\nγράψε(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nγράψε(\"============================================================\");\n", "arrays": "// Ελληνικά - Πίνακες\n// Πίνακες με εγγενείς λέξεις-κλειδιά\n\n// Δημιουργία πινάκων\nέστω αριθμοί = [1, 2, 3, 4, 5];\nέστω ονόματα = [\"Αλίκη\", \"Βασίλης\", \"Γιώργος\"];\n\n// Πρόσβαση σε στοιχεία\nέστω πρώτος = αριθμοί[0];\nέστω δεύτερος = αριθμοί[1];\n\n// Αποτέλεσμα\nπρώτος;\n", "math": "// EL - Math Module\n\nfunction add(a, b) {\n    επιστροφή a + b;\n}\n\nfunction subtract(a, b) {\n    επιστροφή a - b;\n}\n\nfunction multiply(a, b) {\n    επιστροφή a * b;\n}\n\nfunction divide(a, b) {\n    αν (b == 0) {\n        εκτύπωση(\"Error: Division by zero!\");\n        επιστροφή 0;\n    } αλλιώς {\n        επιστροφή a / b;\n    }\n}\n\nfunction square(x) {\n    επιστροφή x * x;\n}\n\nfunction cube(x) {\n    επιστροφή x * x * x;\n}\n\nfunction abs(x) {\n    αν (x < 0) {\n        επιστροφή -x;\n    } αλλιώς {\n        επιστροφή x;\n    }\n}\n\nfunction max(a, b) {\n    αν (a > b) {\n        επιστροφή a;\n    } αλλιώς {\n        επιστροφή b;\n    }\n}\n\nfunction min(a, b) {\n    αν (a < b) {\n        επιστροφή a;\n    } αλλιώς {\n        επιστροφή b;\n    }\n}\n", "control_flow": "// Ελληνικά - Έλεγχος Ροής\nμεταβλητή μετρητής = 0;\nμεταβλητή μέγιστο = 5;\n\n// Loop\nενώ (μετρητής < μέγιστο) {\n    μετρητής = μετρητής + 1;\n}\n\n// Conditional\nμεταβλητή βαθμολογία = 85;\n\nαν (βαθμολογία >= 90) {\n    βαθμολογία;\n} αλλιώς {\n    αν (βαθμολογία >= 80) {\n        βαθμολογία;\n    } αλλιώς {\n        βαθμολογία;\n    }\n}\n\nμετρητής;", "state_machine": "// State Machine Example\nας state = \"initial\";\n\nαν (state == \"initial\") {\n    εκτύπωση(\"Starting\");\n    state = \"running\";\n}\n\nεκτύπωση(state);\n", "conditionals": "// Ελληνικά - Λογική συνθηκών\nέστω βαθμός = 85;\n\nαν (βαθμός >= 90) {\n    εκτύπωσε(1000);\n} αλλιώς {\n    αν (βαθμός >= 80) {\n        εκτύπωσε(2000);\n    } αλλιώς {\n        εκτύπωσε(3000);\n    }\n}\n\nεκτύπωσε(999);\n", "code_organization": "// Ελληνικά - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable για large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// χρήση \"agent/agent_definition.hudhud\";\n// χρήση \"constitution/laws.hudhud\";\n// χρήση \"data/note.hudhud\";\n// χρήση \"utils/math.hudhud\";\n", "module_concepts": "// Ελληνικά - Modules & Code Organization\n// Demonstrates module system: χρήση/εισαγωγή like Rust, Java, C++, Python\n\n// Import math module\nχρήση \"math.hudhud\";\n\n// Example syntax variations:\n// χρήση \"math.hudhud\";\n// χρήση { add, subtract } από \"math.hudhud\";\n// χρήση \"math.hudhud\" ως math;\n\n// Using functions από math module\nας sum = add(10, 5);\nεκτύπωση(sum);\n\nας diff = subtract(20, 8);\nεκτύπωση(diff);\n\nας product = multiply(4, 7);\nεκτύπωση(product);\n\nας quotient = divide(15, 3);\nεκτύπωση(quotient);\n\nας squared = square(5);\nεκτύπωση(squared);\n\nας cubed = cube(3);\nεκτύπωση(cubed);\n\nας absolute = abs(-42);\nεκτύπωση(absolute);\n\nας maximum = max(100, 50);\nεκτύπωση(maximum);\n\nας minimum = min(100, 50);\nεκτύπωση(minimum);\n\n// Complex calculation using multiple functions\nας result = add(multiply(5, 3), divide(20, 4));\nεκτύπωση(result);\n", "switch_concepts": "// Ελληνικά - Έννοιες Switch/Case\n// switch/case/default\n\nσυνάρτηση τύπος_ημέρας(day) {\n    επίλεξε (day) {\n        περίπτωση \"Monday\":\n        περίπτωση \"Tuesday\":\n        περίπτωση \"Wednesday\":\n        περίπτωση \"Thursday\":\n        περίπτωση \"Friday\":\n            επέστρεψε \"Εργάσιμη\";\n        περίπτωση \"Saturday\":\n        περίπτωση \"Sunday\":\n            επέστρεψε \"Σαββατοκύριακο\";\n        προεπιλογή:\n            επέστρεψε \"Άγνωστο\";\n    }\n}\n\nεκτύπωσε(\"=== Day Types ===\");\nεκτύπωσε(\"Monday: \" + τύπος_ημέρας(\"Monday\"));\nεκτύπωσε(\"Saturday: \" + τύπος_ημέρας(\"Saturday\"));\nεκτύπωσε(\"Holiday: \" + τύπος_ημέρας(\"Holiday\"));\n\nσυνάρτηση βαθμός_γράμμα(score) {\n    επίλεξε (score) {\n        περίπτωση 90:\n            επέστρεψε \"A\";\n        περίπτωση 80:\n            επέστρεψε \"B\";\n        περίπτωση 70:\n            επέστρεψε \"C\";\n        περίπτωση 60:\n            επέστρεψε \"D\";\n        προεπιλογή:\n            επέστρεψε \"F\";\n    }\n}\n\nεκτύπωσε(\"\\n=== Grades ===\");\nεκτύπωσε(\"90: \" + βαθμός_γράμμα(90));\nεκτύπωσε(\"70: \" + βαθμός_γράμμα(70));\nεκτύπωσε(\"50: \" + βαθμός_γράμμα(50));\n\nσυνάρτηση μήνυμα_κατάστασης(code) {\n    επίλεξε (code) {\n        περίπτωση 200:\n            επέστρεψε \"OK\";\n        περίπτωση 404:\n            επέστρεψε \"Not Found\";\n        περίπτωση 500:\n            επέστρεψε \"Server Error\";\n        προεπιλογή:\n            επέστρεψε \"Άγνωστο Status\";\n    }\n}\n\nεκτύπωσε(\"\\n=== HTTP Status ===\");\nεκτύπωσε(\"200: \" + μήνυμα_κατάστασης(200));\nεκτύπωσε(\"404: \" + μήνυμα_κατάστασης(404));\n", "event_concepts": "// Ελληνικά - Event Concepts\n\nγεγονός UserLogin {\n    εκτύπωσε(\"User logged in\");\n}\n\nγεγονός DataReceived {\n    εκτύπωσε(\"Data received\");\n}\n\nγεγονός ErrorOccurred {\n    εκτύπωσε(\"Error occurred\");\n}\n\nσυνάρτηση on_login(username) {\n    εκτύπωσε(\"Login: \" + username);\n    επέστρεψε \"Welcome, \" + username;\n}\n\nσυνάρτηση on_data(source) {\n    εκτύπωσε(\"Data from: \" + source);\n    επέστρεψε \"Processed: \" + source;\n}\n\nσυνάρτηση on_error(message) {\n    εκτύπωσε(\"Error: \" + message);\n    επέστρεψε \"Handled: \" + message;\n}\n\nεκτύπωσε(\"=== Event System ===\");\nέστω r1 = on_login(\"admin\");\nεκτύπωσε(r1);\nέστω r2 = on_data(\"sensor_1\");\nεκτύπωσε(r2);\nέστω r3 = on_error(\"timeout\");\nεκτύπωσε(r3);\n", "functions": "// Ελληνικά - Συναρτήσεις\n// Παραδείγματα ορισμού και χρήσης συναρτήσεων\n\n// Απλή συνάρτηση\nσυνάρτηση χαιρέτισε() {\n    εκτύπωσε(\"Γεια σου Κόσμε!\");\n}\n\n// Συνάρτηση με παραμέτρους\nσυνάρτηση πρόσθεσε(α, β) {\n    επέστρεψε α + β;\n}\n\n// Συνάρτηση με πολλές παραμέτρους\nσυνάρτηση υπολόγισε(αρ1, αρ2, πράξη) {\n    αν (πράξη == \"πρόσθεσε\") {\n        επέστρεψε αρ1 + αρ2;\n    } αλλιώς {\n        επέστρεψε 0;\n    }\n}\n\n// Μαθηματικές συναρτήσεις\nσυνάρτηση τετράγωνο(χ) {\n    επέστρεψε χ * χ;\n}\n\nσυνάρτηση κύβος(χ) {\n    επέστρεψε χ * χ * χ;\n}\n\n// Χρήση συναρτήσεων\nχαιρέτισε();\n\nέστω αποτέλεσμα1 = πρόσθεσε(5, 3);\nεκτύπωσε(αποτέλεσμα1);\n\nέστω αποτέλεσμα2 = υπολόγισε(10, 5, \"πρόσθεσε\");\nεκτύπωσε(αποτέλεσμα2);\n\nέστω αποτέλεσμα_τετράγωνο = τετράγωνο(4);\nεκτύπωσε(αποτέλεσμα_τετράγωνο);\n\nέστω αποτέλεσμα_κύβος = κύβος(3);\nεκτύπωσε(αποτέλεσμα_κύβος);\n\n// Σύνθεση συναρτήσεων\nέστω σύνολο = πρόσθεσε(τετράγωνο(3), κύβος(2));\nεκτύπωσε(σύνολο);\n", "entity_concepts": "// Ελληνικά - Έννοιες Οντοτήτων\n\nέστω χρήστης = {\n    id: 1,\n    όνομα: \"Αλίκη\",\n    email: \"aliki@παράδειγμα.gr\",\n    ρόλος: \"προγραμματίστρια\"\n};\n\nέστω προϊόν = {\n    id: 101,\n    όνομα: \"HudHudScript IDE\",\n    έκδοση: \"2.0\",\n    τιμή: 49\n};\n\nέστω παραγγελία = {\n    id: 1001,\n    id_χρήστη: 1,\n    id_προϊόντος: 101,\n    ποσότητα: 2,\n    κατάσταση: \"επιβεβαιωμένη\"\n};\n\nσυνάρτηση πληροφορίες_οντότητας(οντότητα) {\n    επέστρεψε \"Οντότητα #\" + οντότητα.id + \": \" + οντότητα.όνομα;\n}\n\nσυνάρτηση υπολόγισε_σύνολο(παραγγελία, τιμή) {\n    επέστρεψε παραγγελία.ποσότητα * τιμή;\n}\n\nεκτύπωσε(\"=== Σύστημα Οντοτήτων ===\");\nεκτύπωσε(πληροφορίες_οντότητας(χρήστης));\nεκτύπωσε(πληροφορίες_οντότητας(προϊόν));\nέστω σύνολο = υπολόγισε_σύνολο(παραγγελία, προϊόν.τιμή);\nεκτύπωσε(\"Παραγγελία #\" + παραγγελία.id + \" σύνολο: \" + σύνολο);\nεκτύπωσε(\"Κατάσταση: \" + παραγγελία.κατάσταση);\n", "error_concepts": "// Ελληνικά - Error Concepts\n\nσυνάρτηση validate_age(age) {\n    αν (age < 0) {\n        ρίξε \"Invalid age: negative\";\n    }\n    αν (age > 150) {\n        ρίξε \"Invalid age: too large\";\n    }\n    επέστρεψε age;\n}\n\nσυνάρτηση validate_email(email) {\n    αν (email == \"\") {\n        ρίξε \"Empty email\";\n    }\n    εκτύπωσε(\"Email valid: \" + email);\n    επέστρεψε email;\n}\n\nεκτύπωσε(\"=== Validation ===\");\n\nδοκίμασε {\n    validate_age(25);\n    εκτύπωσε(\"Age 25: valid\");\n} πιάσε (error) {\n    εκτύπωσε(\"Error: \" + error);\n}\n\nδοκίμασε {\n    validate_age(-5);\n} πιάσε (error) {\n    εκτύπωσε(\"Error: \" + error);\n}\n\nδοκίμασε {\n    validate_email(\"user@example.com\");\n    validate_email(\"\");\n} πιάσε (error) {\n    εκτύπωσε(\"Email error: \" + error);\n} τελικά {\n    εκτύπωσε(\"Validation complete\");\n}\n"}, "en": {"objects": "// English - Object-Oriented Programming (OOP)\n// Object-based programming patterns in HudHudScript\n\n// ============================================\n// 1. Basic Object Definition\n// ============================================\n\nobject Animal {\n    name: \"Unknown\",\n    species: \"Unknown\",\n    age: 0,\n    alive: true\n}\n\nobject Cat {\n    name: \"Whiskers\",\n    species: \"Cat\",\n    age: 3,\n    alive: true,\n    color: \"orange\",\n    indoor: true\n}\n\nprint(\"=== Basic Objects ===\");\nprint(Animal.name);\nprint(Cat.name + \" (\" + Cat.species + \") - \" + Cat.age + \" years old\");\n\n// ============================================\n// 2. Factory Functions (Constructor Pattern)\n// ============================================\n\nfunction CreateCar(brand, model, year, color) {\n    return {\n        brand: brand,\n        model: model,\n        year: year,\n        color: color,\n        mileage: 0,\n        running: true\n    };\n}\n\nlet car1 = CreateCar(\"Toyota\", \"Corolla\", 2024, \"white\");\nlet car2 = CreateCar(\"Honda\", \"Civic\", 2023, \"black\");\n\nprint(\"\\n=== Factory Functions ===\");\nprint(car1.brand + \" \" + car1.model + \" - \" + car1.color);\nprint(car2.brand + \" \" + car2.model + \" - \" + car2.color);\n\n// ============================================\n// 3. Behavior Functions (Method Pattern)\n// ============================================\n\nfunction car_info(car) {\n    return car.brand + \" \" + car.model + \" (\" + car.year + \") \" + car.color;\n}\n\nfunction drive(car, distance) {\n    let new_km = car.mileage + distance;\n    print(car.brand + \" drove \" + distance + \" km. Total: \" + new_km + \" km\");\n    return new_km;\n}\n\nfunction car_age(car) {\n    return 2024 - car.year;\n}\n\nprint(\"\\n=== Behavior Functions ===\");\nprint(car_info(car1));\ndrive(car1, 150);\ndrive(car1, 230);\nprint(\"Car age: \" + car_age(car1) + \" years\");\n\n// ============================================\n// 4. Object Composition\n// ============================================\n\nfunction CreateAddress(city, district, neighborhood) {\n    return {\n        city: city,\n        district: district,\n        neighborhood: neighborhood\n    };\n}\n\nfunction CreatePerson(name, age, address) {\n    return {\n        name: name,\n        age: age,\n        address: address,\n        occupation: \"Not specified\"\n    };\n}\n\nlet home_addr = CreateAddress(\"London\", \"Camden\", \"Primrose Hill\");\nlet person = CreatePerson(\"Alice\", 28, home_addr);\n\nprint(\"\\n=== Object Composition ===\");\nprint(person.name + \" - \" + person.age + \" years old\");\nprint(\"Address: \" + person.address.neighborhood + \", \" + person.address.district + \"/\" + person.address.city);\n\n// ============================================\n// 5. Collections and Object Arrays\n// ============================================\n\nlet students = [\n    CreatePerson(\"Bob\", 20, CreateAddress(\"New York\", \"Manhattan\", \"SoHo\")),\n    CreatePerson(\"Charlie\", 22, CreateAddress(\"San Francisco\", \"Mission\", \"Valencia\")),\n    CreatePerson(\"Diana\", 21, CreateAddress(\"Chicago\", \"Lincoln Park\", \"DePaul\"))\n];\n\nprint(\"\\n=== Object Collections ===\");\nlet idx = 0;\nwhile (idx < 3) {\n    let student = students[idx];\n    print(student.name + \" - \" + student.address.city);\n    idx = idx + 1;\n}\n\n// ============================================\n// 6. Business Logic Object (Shopping Cart)\n// ============================================\n\nfunction CreateCartItem(product, price, quantity) {\n    return {\n        product: product,\n        price: price,\n        quantity: quantity\n    };\n}\n\nfunction item_total(item) {\n    return item.price * item.quantity;\n}\n\nlet cart = [\n    CreateCartItem(\"Laptop\", 1200, 1),\n    CreateCartItem(\"Mouse\", 25, 2),\n    CreateCartItem(\"Keyboard\", 75, 1)\n];\n\nprint(\"\\n=== Shopping Cart ===\");\nlet grand_total = 0;\nlet s = 0;\nwhile (s < 3) {\n    let item = cart[s];\n    let total = item_total(item);\n    print(item.product + \" x\" + item.quantity + \" = $\" + total);\n    grand_total = grand_total + total;\n    s = s + 1;\n}\nprint(\"Grand Total: $\" + grand_total);\n", "chemistry": "// English - Chemistry Module\n\nfunction molarMass(atoms, atomicWeight) {\n    return atoms * atomicWeight;\n}\n\nfunction concentration(moles, volume) {\n    return moles / volume;\n}\n\nfunction pH(hydrogenConcentration) {\n    return 14 - hydrogenConcentration;\n}\n\nfunction density(mass, volume) {\n    return mass / volume;\n}\n\nfunction dilution(c1, v1, v2) {\n    return (c1 * v1) / v2;\n}\n", "loops": "// English - Loops\n// Loop examples with native keywords\n\n// Simple loop - sum from 1 to 5\nlet sum = 0;\nlet counter = 1;\n\nwhile (counter <= 5) {\n    sum = sum + counter;\n    counter = counter + 1;\n}\n\nsum;\n", "data_processing": "// English - Data Processing\n// Data processing with native keywords\n\n// Define data\nlet value1 = 100;\nlet value2 = 200;\nlet value3 = 300;\n\n// Calculate\nlet total = value1+ value2+ value3;\nlet average = total / 3;\n\n// Conditional processing\nif (average > 150) {\n    let status = \"high\";\n} else {\n    let status = \"low\";\n}\n", "arrow_functions": "// English - Arrow Functions\n// Modern, concise syntax for functions\n\n// Arrow function - short syntax\nlet add = (a, b) => a + b;\nlet multiply = (x, y) => x * y;\n\nprint(add(5, 3));      // 8\nprint(multiply(4, 7)); // 28\n\n// Arrow function with block\nlet calculate = (a, b) => {\n    let sum = a + b;\n    let product = a * b;\n    return sum + product;\n};\n\nlet result = calculate(5, 3);\nprint(result);  // 23 (8 + 15)\n\n// Single parameter (no parentheses needed)\nlet square = x => x * x;\nprint(square(6));  // 36\n\n// No parameters\nlet greet = () => \"Hello!\";\nprint(greet());  // Hello!\n", "modules_import": "// English - Modules Import Example\n\n// Import math module (direct access)\nuse \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nuse \"physics.hudhud\" as fizik;\n\n// Import chemistry (direct access)\nuse \"chemistry.hudhud\";\n\n// Using math functions (direct)\nlet sum = add(10, 5);\nprint(sum);\n\nlet product = multiply(4, 7);\nprint(product);\n\n// Using physics functions (via alias: fizik.functionName)\nlet f = fizik.force(10, 9.8);\nprint(f);\n\nlet ke = fizik.kineticEnergy(5, 10);\nprint(ke);\n\n// Using chemistry functions (direct)\nlet d = density(100, 50);\nprint(d);\n\nlet c = concentration(2, 5);\nprint(c);\n", "return_concept": "// English - Return Concept\n// return\n\nfunction square(x) {\n    return x * x;\n}\n\nfunction cube(x) {\n    return x * x * x;\n}\n\nprint(\"=== Math Functions ===\");\nprint(\"square(5): \" + square(5));\nprint(\"cube(3): \" + cube(3));\n\nfunction absolute(x) {\n    if (x < 0) {\n        return -x;\n    }\n    return x;\n}\n\nprint(\"\\n=== Absolute ===\");\nprint(\"absolute(-7): \" + absolute(-7));\nprint(\"absolute(3): \" + absolute(3));\n\nfunction create_point(x, y) {\n    return { x: x, y: y };\n}\n\nlet p = create_point(10, 20);\nprint(\"\\n=== Point ===\");\nprint(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfunction factorial(n) {\n    if (n <= 1) {\n        return 1;\n    }\n    return n * factorial(n - 1);\n}\n\nprint(\"\\n=== Factorial ===\");\nprint(\"5! = \" + factorial(5));\nprint(\"10! = \" + factorial(10));\n", "customer_service": "// English - Customer Service Agent\n\nlaw respect_law {\n    description: \"The agent must be polite and respectful\",\n    priority: 1\n}\n\nconstitution service_constitution {\n    laws: [respect_law],\n    description: \"Customer service framework\"\n}\n\nagent service_agent {\n    model: \"gpt-4\"\n}\n\nfunction greet(customer_name) {\n    let message = \"Hello \" + customer_name + \", how can I help you?\";\n    print(message);\n    return message;\n}\n\nfunction handle_request(type, details) {\n    if (type == \"complaint\") {\n        print(\"I apologize for the inconvenience. I will help resolve your issue.\");\n    } else {\n        print(\"Thank you for reaching out. I will process your request now.\");\n    }\n    return \"Processed: \" + type + \" - \" + details;\n}\n\nprint(\"=== Customer Service Agent ===\");\ngreet(\"Alice\");\nlet result = handle_request(\"complaint\", \"shipping delay\");\nprint(result);\n", "basic_example": "// English - Basic Example\n// Basic example with native keywords\n\nlet x = 10;\nlet y = 20;\nlet sum = x + y;\n\nprint(sum);\n", "physics": "// English - Physics Module\n\nfunction speed(distance, time) {\n    return distance / time;\n}\n\nfunction force(mass, acceleration) {\n    return mass * acceleration;\n}\n\nfunction kineticEnergy(mass, velocity) {\n    return 0.5 * mass * velocity * velocity;\n}\n\nfunction potentialEnergy(mass, gravity, height) {\n    return mass * gravity * height;\n}\n\nfunction momentum(mass, velocity) {\n    return mass * velocity;\n}\n", "error_handling": "// English - Error Handling\n// Simple error control with if-else\n\n// Function that checks for errors\nfunction divide(a, b) {\n    if (b == 0) {\n        return { error: true, message: \"Division by zero error\", value: 0 };\n    }\n    return { error: false, message: \"\", value: a / b };\n}\n\nprint(\"=== Division Operation ===\");\n\n// First division\nprint(\"10 / 2 operation:\");\nlet result1 = divide(10, 2);\nif (result1.error) {\n    print(\"Error: \" + result1.message);\n} else {\n    print(\"10 / 2 = \" + result1.value);\n}\n\n// Division by zero\nprint(\"10 / 0 operation:\");\nlet result2 = divide(10, 0);\nif (result2.error) {\n    print(\"Error caught: \" + result2.message);\n} else {\n    print(\"Result: \" + result2.value);\n}\n\n// File processing example\nprint(\"=== File Processing ===\");\n\nfunction process_file(filename) {\n    if (filename == \"\") {\n        return { success: false, message: \"Empty filename error\" };\n    }\n    print(\"Processing: \" + filename);\n    return { success: true, data: \"Data from \" + filename };\n}\n\nlet file_result = process_file(\"report.txt\");\nif (file_result.success) {\n    print(\"Result: \" + file_result.data);\n} else {\n    print(\"Error: \" + file_result.message);\n}\n\nprint(\"All done\");\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici package kullanımı\nuse \"cebir\";\nuse \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nuse \"cebir/matris\";\nuse \"cebir/vektor\";\nuse \"fizik/hareket\";\n\nprint(\"============================================================\");\nprint(\"HudHudScript Paket Sistemi Demo\");\nprint(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nprint(\"📦 Cebir Paketi Kullanımı:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nlet matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nlet matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nprint(\"Matris 1:\");\nmatris1.goster();\n\nprint(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nlet toplam = matris1.topla(matris2);\nprint(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nlet vektor1 = Vektor([1, 2, 3]);\nlet vektor2 = Vektor([4, 5, 6]);\n\nprint(\"\\n\\n📐 Vektör İşlemleri:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"Vektör 1: \" + vektor1.toString());\nprint(\"Vektör 2: \" + vektor2.toString());\n\nlet noktaSal = vektor1.noktaSal(vektor2);\nprint(\"Nokta Çarpım: \" + noktaSal);\n\nlet caprazCarpim = vektor1.caprazCarpim(vektor2);\nprint(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nprint(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nlet baslangicHizi = 0;      // m/s\nlet ivme = 9.8;              // m/s² (yerçekimi)\nlet zaman = 5;               // saniye\n\nlet sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nlet mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nprint(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nprint(\"İvme: \" + ivme + \" m/s²\");\nprint(\"Zaman: \" + zaman + \" s\");\nprint(\"─────────────────────────────────────────────────────────\");\nprint(\"Son Hız: \" + sonHiz + \" m/s\");\nprint(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nprint(\"\\n\\n📝 Paket Oluşturma:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"1. hudhud.toml dosyası oluşturun:\");\nprint(\"   [package]\");\nprint(\"   name = 'matematik-utils'\");\nprint(\"   version = '1.0.0'\");\nprint(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nprint(\"\\n2. Bağımlılıklar ekleyin:\");\nprint(\"   [dependencies]\");\nprint(\"   cebir = '^2.0.0'\");\nprint(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nprint(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"Paket kurma:\");\nprint(\"  hudhudscript install cebir\");\nprint(\"  hudhudscript install fizik@1.5.0\");\n\nprint(\"\\nPaket güncelleme:\");\nprint(\"  hudhudscript update cebir\");\nprint(\"  hudhudscript update --all\");\n\nprint(\"\\nPaket kaldırma:\");\nprint(\"  hudhudscript remove cebir\");\n\nprint(\"\\nKurulu paketleri listeleme:\");\nprint(\"  hudhudscript list\");\n\nprint(\"\\nPaket arama:\");\nprint(\"  hudhudscript search matematik\");\n\nprint(\"\\nPaket bilgisi:\");\nprint(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nprint(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"Versiyon belirtme:\");\nprint(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nprint(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nprint(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nprint(\"\\nGit deposundan:\");\nprint(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nprint(\"\\nYerel yoldan:\");\nprint(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nprint(\"\\n\\n🔒 Paket Güvenliği:\");\nprint(\"─────────────────────────────────────────────────────────\\n\");\n\nprint(\"Güvenlik kontrolü:\");\nprint(\"  hudhudscript audit\");\n\nprint(\"\\nChecksum doğrulama:\");\nprint(\"  hudhudscript verify cebir\");\n\nprint(\"\\n============================================================\");\nprint(\"✓ Paket sistemi demo tamamlandı!\");\nprint(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nprint(\"============================================================\");\n", "arrays": "// English - Arrays\n// Arrays with native keywords\n\n// Create arrays\nlet numbers = [1, 2, 3, 4, 5];\nlet names = [\"Alice\", \"Bob\", \"Charlie\"];\n\n// Access elements\nlet first = numbers[0];\nlet second = numbers[1];\n\n// Empty array\nlet list = [];\n", "math": "// English - Math Module\n\nfunction add(a, b) {\n    return a + b;\n}\n\nfunction subtract(a, b) {\n    return a - b;\n}\n\nfunction multiply(a, b) {\n    return a * b;\n}\n\nfunction divide(a, b) {\n    if (b == 0) {\n        print(\"Error: Division by zero!\");\n        return 0;\n    } else {\n        return a / b;\n    }\n}\n\nfunction square(x) {\n    return x * x;\n}\n\nfunction cube(x) {\n    return x * x * x;\n}\n\nfunction abs(x) {\n    if (x < 0) {\n        return -x;\n    } else {\n        return x;\n    }\n}\n\nfunction max(a, b) {\n    if (a > b) {\n        return a;\n    } else {\n        return b;\n    }\n}\n\nfunction min(a, b) {\n    if (a < b) {\n        return a;\n    } else {\n        return b;\n    }\n}\n", "control_flow": "// English - Control Flow\nlet counter = 0;\nlet max = 5;\n\n// Loop\nwhile (counter < max) {\n    counter = counter + 1;\n}\n\n// Conditional\nlet score = 85;\n\nif (score >= 90) {\n    score;\n} else {\n    if (score >= 80) {\n        score;\n    } else {\n        score;\n    }\n}\n\ncounter;\n", "state_machine": "// State Machine Example\nlet state = \"initial\";\n\nif (state == \"initial\") {\n    print(\"Starting\");\n    state = \"running\";\n}\n\nprint(state);\n", "conditionals": "// English - Conditional Logic\nlet score = 85;\n\nif (score >= 90) {\n    score;\n} else {\n    if (score >= 80) {\n        score;\n    } else {\n        score;\n    }\n}\n", "code_organization": "// English - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable for large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// use \"agent/agent_definition.hudhud\";\n// use \"constitution/laws.hudhud\";\n// use \"data/note.hudhud\";\n// use \"utils/math.hudhud\";\n", "module_concepts": "// English - Modules & Code Organization\n// Demonstrates module system: use/import like Rust, Java, C++, Python\n\n// Import math module\nuse \"math.hudhud\";\n\n// Example syntax variations:\n// use \"math.hudhud\";\n// use { add, subtract } from \"math.hudhud\";\n// use \"math.hudhud\" as math;\n\n// Using functions from math module\nlet sum = add(10, 5);\nprint(sum);\n\nlet diff = subtract(20, 8);\nprint(diff);\n\nlet product = multiply(4, 7);\nprint(product);\n\nlet quotient = divide(15, 3);\nprint(quotient);\n\nlet squared = square(5);\nprint(squared);\n\nlet cubed = cube(3);\nprint(cubed);\n\nlet absolute = abs(-42);\nprint(absolute);\n\nlet maximum = max(100, 50);\nprint(maximum);\n\nlet minimum = min(100, 50);\nprint(minimum);\n\n// Complex calculation using multiple functions\nlet result = add(multiply(5, 3), divide(20, 4));\nprint(result);\n", "higher_order_functions": "// English - Higher-Order Functions\n// Functions that work with other functions\n\n// Function that returns a function\nfunction multiplier(factor) {\n    return (x) => x * factor;\n}\n\nlet double = multiplier(2);\nlet triple = multiplier(3);\n\nprint(double(5));  // 10\nprint(triple(5));  // 15\n\n// Function that takes a function\nfunction apply(fn, value) {\n    return fn(value);\n}\n\nprint(apply(double, 10));  // 20\n\n// Composition example\nfunction compose(f, g) {\n    return (x) => f(g(x));\n}\n\nlet addOne = (x) => x + 1;\nlet timesTwo = (x) => x * 2;\n\nlet addThenDouble = compose(timesTwo, addOne);\nprint(addThenDouble(5));  // 12 (5+1=6, 6*2=12)\n\n", "classes_oop": "// English - Classes and Object-Oriented Programming (OOP)\n// Class-based programming in HudHudScript\n\n// ============================================\n// 1. Basic Class Definition\n// ============================================\n\n// Access modifiers: public, private, protected\nclass Animal {\n    public var name = \"Unknown\";\n    public var species = \"Unknown\";\n    public var age = 0;\n    public var alive = true;\n    private var id = \"A-001\";\n}\n\nprint(\"=== Basic Class ===\");\nprint(\"Class defined: Animal\");\n\n// ============================================\n// 2. Inheritance — <- operator\n// ============================================\n\n// Base Vehicle class\nclass Vehicle {\n    public var brand = \"Unknown\";\n    public var model = \"Unknown\";\n    public var year = 2024;\n    private var engine_no = \"ENG-0000\";\n    protected var production_cost = 50000;\n}\n\n// Car <- Vehicle (Car inherits from Vehicle)\nclass Car <- Vehicle {\n    public var color = \"white\";\n    public var door_count = 4;\n    private var mileage = 0;\n}\n\n// Sedan <- Car <- Vehicle (multi-level inheritance)\nclass Sedan <- Car {\n    public var trunk_volume = 500;\n    public var type = \"sedan\";\n}\n\n// SUV <- Car <- Vehicle\nclass SUV <- Car {\n    public var four_wheel_drive = true;\n    public var height = 180;\n    public var off_road_mode = \"off\";\n}\n\nprint(\"\\n=== Inheritance Hierarchy ===\");\nprint(\"Vehicle -> Car -> Sedan\");\nprint(\"Vehicle -> Car -> SUV\");\n\n// ============================================\n// 3. Static Fields\n// ============================================\n\nclass CarFactory {\n    static public var total_production = 0;\n    static private var factory_code = \"FAC-2024\";\n    static public var founded = 2020;\n    static public var location = \"Istanbul\";\n}\n\nprint(\"\\n=== Static Fields ===\");\nprint(\"Factory: \" + CarFactory.location);\nprint(\"Founded: \" + CarFactory.founded);\n\n// ============================================\n// 4. Access Modifiers\n// ============================================\n\nclass BankAccount {\n    public var holder = \"Alice Johnson\";\n    public var account_type = \"Checking\";\n    protected var balance = 10000;\n    private var password = \"secret123\";\n    private var security_code = \"XYZ\";\n    public var currency = \"USD\";\n}\n\nprint(\"\\n=== Access Modifiers ===\");\nprint(\"public    -> Everyone: holder, account_type\");\nprint(\"protected -> Class and subclasses: balance\");\nprint(\"private   -> Class only: password, security_code\");\n\n// ============================================\n// 5. Class Hierarchy — Living Entities\n// ============================================\n\nclass LivingEntity {\n    public var name = \"Unknown\";\n    public var age = 0;\n    protected var energy = 100;\n    private var dna = \"ACGT\";\n}\n\nclass Mammal <- LivingEntity {\n    public var blood_temp = \"warm\";\n    public var has_fur = true;\n}\n\nclass Bird <- LivingEntity {\n    public var wingspan = 0;\n    public var can_fly = true;\n}\n\nclass Cat <- Mammal {\n    public var breed = \"Tabby\";\n    public var indoor = true;\n    public var color = \"orange\";\n}\n\nclass Dog <- Mammal {\n    public var breed = \"Golden\";\n    public var trained = false;\n    public var size = \"large\";\n}\n\nclass Parrot <- Bird {\n    public var can_talk = true;\n    public var color = \"green\";\n    public var vocabulary = 50;\n}\n\nprint(\"\\n=== Living Entity Hierarchy ===\");\nprint(\"LivingEntity\");\nprint(\"  +-- Mammal\");\nprint(\"  |   +-- Cat (breed: \" + Cat.breed + \", color: \" + Cat.color + \")\");\nprint(\"  |   +-- Dog (breed: \" + Dog.breed + \", size: \" + Dog.size + \")\");\nprint(\"  +-- Bird\");\nprint(\"      +-- Parrot (can_talk: \" + Parrot.can_talk + \", vocab: \" + Parrot.vocabulary + \")\");\n\n// ============================================\n// 6. Business Domain Classes\n// ============================================\n\nclass Company {\n    public var name = \"HudHud Technology\";\n    public var sector = \"Software\";\n    public var founded = 2023;\n    public var employees = 45;\n    private var tax_id = \"US-12345678\";\n}\n\nclass Department {\n    public var name = \"Engineering\";\n    public var manager = \"Bob Smith\";\n    public var headcount = 12;\n    public var budget = 500000;\n}\n\nclass Employee {\n    public var name = \"Alice Chen\";\n    public var title = \"Senior Developer\";\n    public var department = \"Engineering\";\n    protected var salary = 95000;\n    private var ssn = \"123-45-6789\";\n}\n\nprint(\"\\n=== Business Domain ===\");\nprint(Company.name + \" - \" + Company.sector);\nprint(\"Department: \" + Department.name + \" (\" + Department.headcount + \" people)\");\nprint(\"Employee: \" + Employee.name + \" - \" + Employee.title);\n", "switch_concepts": "// English - Switch/Case Concepts\n// Using if-else for multiple conditions\n\nfunction day_type(day) {\n    if (day == \"Monday\") {\n        return \"Weekday\";\n    }\n    if (day == \"Tuesday\") {\n        return \"Weekday\";\n    }\n    if (day == \"Wednesday\") {\n        return \"Weekday\";\n    }\n    if (day == \"Thursday\") {\n        return \"Weekday\";\n    }\n    if (day == \"Friday\") {\n        return \"Weekday\";\n    }\n    if (day == \"Saturday\") {\n        return \"Weekend\";\n    }\n    if (day == \"Sunday\") {\n        return \"Weekend\";\n    }\n    return \"Unknown\";\n}\n\nprint(\"=== Day Types ===\");\nprint(\"Monday: \" + day_type(\"Monday\"));\nprint(\"Saturday: \" + day_type(\"Saturday\"));\nprint(\"Holiday: \" + day_type(\"Holiday\"));\n\nfunction grade_letter(score) {\n    if (score == 90) {\n        return \"A\";\n    }\n    if (score == 80) {\n        return \"B\";\n    }\n    if (score == 70) {\n        return \"C\";\n    }\n    if (score == 60) {\n        return \"D\";\n    }\n    return \"F\";\n}\n\nprint(\"=== Grades ===\");\nprint(\"90: \" + grade_letter(90));\nprint(\"70: \" + grade_letter(70));\nprint(\"50: \" + grade_letter(50));\n\nfunction status_message(code) {\n    if (code == 200) {\n        return \"OK\";\n    }\n    if (code == 404) {\n        return \"Not Found\";\n    }\n    if (code == 500) {\n        return \"Server Error\";\n    }\n    return \"Unknown Status\";\n}\n\nprint(\"=== HTTP Status ===\");\nprint(\"200: \" + status_message(200));\nprint(\"404: \" + status_message(404));\n", "event_concepts": "// English - Event Concepts\n\nevent UserLogin {\n    print(\"User logged in\");\n}\n\nevent DataReceived {\n    print(\"Data received\");\n}\n\nevent ErrorOccurred {\n    print(\"Error occurred\");\n}\n\nfunction on_login(username) {\n    print(\"Login: \" + username);\n    return \"Welcome, \" + username;\n}\n\nfunction on_data(source) {\n    print(\"Data from: \" + source);\n    return \"Processed: \" + source;\n}\n\nfunction on_error(message) {\n    print(\"Error: \" + message);\n    return \"Handled: \" + message;\n}\n\nprint(\"=== Event System ===\");\nlet r1 = on_login(\"admin\");\nprint(r1);\nlet r2 = on_data(\"sensor_1\");\nprint(r2);\nlet r3 = on_error(\"timeout\");\nprint(r3);\n", "functions": "// English - Functions\n// Function definition and usage examples\n\n// Simple function\nfunction greet() {\n    print(\"Hello World!\");\n}\n\n// Function with parameters\nfunction add(a, b) {\n    return a + b;\n}\n\n// Multi-parameter function\nfunction calculate(num1, num2, operation) {\n    if (operation == \"add\") {\n        return num1 + num2;\n    } else if (operation == \"subtract\") {\n        return num1 - num2;\n    } else if (operation == \"multiply\") {\n        return num1 * num2;\n    } else if (operation == \"divide\") {\n        return num1 / num2;\n    } else {\n        return 0;\n    }\n}\n\n// Mathematical functions\nfunction square(x) {\n    return x * x;\n}\n\nfunction cube(x) {\n    return x * x * x;\n}\n\n// Using functions\ngreet();\n\nlet result1 = add(5, 3);\nprint(result1);\n\nlet result2 = calculate(10, 5, \"add\");\nprint(result2);\n\nlet result3 = calculate(10, 5, \"multiply\");\nprint(result3);\n\nlet square_result = square(4);\nprint(square_result);\n\nlet cube_result = cube(3);\nprint(cube_result);\n\n// Function composition\nlet total = add(square(3), cube(2));\nprint(total);\n", "entity_concepts": "// English - Entity Concepts\n\nlet user = {\n    id: 1,\n    name: \"Alice\",\n    email: \"alice@example.com\",\n    role: \"developer\"\n};\n\nlet product = {\n    id: 101,\n    name: \"HudHudScript IDE\",\n    version: \"2.0\",\n    price: 49\n};\n\nlet order = {\n    id: 1001,\n    user_id: 1,\n    product_id: 101,\n    quantity: 2,\n    status: \"confirmed\"\n};\n\nfunction entity_info(entity) {\n    return \"Entity #\" + entity.id + \": \" + entity.name;\n}\n\nfunction calculate_total(order, price) {\n    return order.quantity * price;\n}\n\nprint(\"=== Entity System ===\");\nprint(entity_info(user));\nprint(entity_info(product));\nlet total = calculate_total(order, product.price);\nprint(\"Order #\" + order.id + \" total: \" + total);\nprint(\"Status: \" + order.status);\n", "error_concepts": "// English - Error Concepts\n// Simple validation functions\n\nfunction validate_age(age) {\n    if (age < 0) {\n        return { valid: false, error: \"Invalid age: negative\" };\n    }\n    if (age > 150) {\n        return { valid: false, error: \"Invalid age: too large\" };\n    }\n    return { valid: true, age: age };\n}\n\nfunction validate_email(email) {\n    if (email == \"\") {\n        return { valid: false, error: \"Empty email\" };\n    }\n    return { valid: true, email: email };\n}\n\nprint(\"=== Validation ===\");\n\n// Age validation\nlet age_result1 = validate_age(25);\nif (age_result1.valid) {\n    print(\"Age 25 is valid\");\n} else {\n    print(\"Error: \" + age_result1.error);\n}\n\nlet age_result2 = validate_age(-5);\nif (age_result2.valid) {\n    print(\"Age is valid\");\n} else {\n    print(\"Error: \" + age_result2.error);\n}\n\n// Email validation\nlet email_result1 = validate_email(\"user@example.com\");\nif (email_result1.valid) {\n    print(\"Email valid: \" + email_result1.email);\n} else {\n    print(\"Email error: \" + email_result1.error);\n}\n\nlet email_result2 = validate_email(\"\");\nif (email_result2.valid) {\n    print(\"Email valid\");\n} else {\n    print(\"Email error: \" + email_result2.error);\n}\n\nprint(\"Validation complete\");\n", "subject_oriented": "// English - Subject-Oriented Programming\n// A paradigm unique to HudHudScript: modeling entities as subjects\n\n// ============================================\n// 1. Basic Subject Definition\n// ============================================\n\nsubject User {\n    name: \"Alice Johnson\",\n    email: \"alice@example.com\",\n    role: \"developer\",\n    active: true,\n    registered: \"2024-01-15\"\n}\n\nsubject Manager {\n    name: \"Bob Smith\",\n    email: \"bob@example.com\",\n    role: \"manager\",\n    active: true,\n    department: \"engineering\",\n    team_size: 8\n}\n\nprint(\"=== Basic Subjects ===\");\nprint(User.name + \" (\" + User.role + \")\");\nprint(Manager.name + \" - \" + Manager.department + \" department\");\n\n// ============================================\n// 2. Domain Modeling\n// ============================================\n\nsubject Product {\n    id: 1001,\n    name: \"HudHudScript IDE Pro\",\n    version: \"3.0\",\n    price: 299,\n    category: \"software\",\n    stock: 500,\n    active: true\n}\n\nsubject Order {\n    id: 5001,\n    customer: \"Alice Johnson\",\n    product_name: \"HudHudScript IDE Pro\",\n    quantity: 2,\n    unit_price: 299,\n    status: \"confirmed\",\n    date: \"2024-03-20\"\n}\n\nfunction order_total(order) {\n    return order.quantity * order.unit_price;\n}\n\nprint(\"\\n=== Domain Modeling ===\");\nprint(\"Product: \" + Product.name + \" v\" + Product.version + \" - $\" + Product.price);\nprint(\"Stock: \" + Product.stock + \" units\");\nlet total = order_total(Order);\nprint(\"Order #\" + Order.id + \": \" + Order.quantity + \" units = $\" + total);\nprint(\"Status: \" + Order.status);\n\n// ============================================\n// 3. Subject Interactions\n// ============================================\n\nsubject Student {\n    name: \"Diana Chen\",\n    id: 2024001,\n    major: \"Computer Science\",\n    year: 3,\n    gpa: 3.45\n}\n\nsubject Professor {\n    name: \"Prof. James Wilson\",\n    title: \"Professor\",\n    department: \"Computer Science\",\n    courses: 4\n}\n\nsubject Course {\n    code: \"CS301\",\n    name: \"Data Structures\",\n    credits: 4,\n    capacity: 60,\n    enrolled: 45,\n    instructor: \"Prof. James Wilson\"\n}\n\nfunction occupancy_rate(course) {\n    return (course.enrolled * 100) / course.capacity;\n}\n\nfunction is_honors(student) {\n    if (student.gpa >= 3.5) {\n        return \"Yes - Honors Student\";\n    } else {\n        return \"No\";\n    }\n}\n\nprint(\"\\n=== Subject Interactions ===\");\nprint(Student.name + \" - \" + Student.major);\nprint(\"GPA: \" + Student.gpa + \" - Honors: \" + is_honors(Student));\nprint(Course.code + \" \" + Course.name + \" (\" + Course.credits + \" credits)\");\nprint(\"Occupancy: \" + occupancy_rate(Course) + \"%\");\nprint(\"Instructor: \" + Course.instructor);\n\n// ============================================\n// 4. State Machine Pattern\n// ============================================\n\nsubject Task {\n    title: \"API Development\",\n    description: \"REST API endpoint design\",\n    assignee: \"Alice Johnson\",\n    priority: \"high\",\n    status: \"in_progress\",\n    estimated_days: 5,\n    elapsed_days: 3\n}\n\nfunction task_report(task) {\n    let remaining = task.estimated_days - task.elapsed_days;\n    let percent = (task.elapsed_days * 100) / task.estimated_days;\n\n    print(\"Task: \" + task.title);\n    print(\"Assignee: \" + task.assignee);\n    print(\"Status: \" + task.status + \" (\" + percent + \"% complete)\");\n    print(\"Remaining: \" + remaining + \" days\");\n    return percent;\n}\n\nfunction advance_task(task) {\n    if (task.status == \"pending\") {\n        return \"in_progress\";\n    } else if (task.status == \"in_progress\") {\n        return \"review\";\n    } else if (task.status == \"review\") {\n        return \"completed\";\n    } else {\n        return task.status;\n    }\n}\n\nprint(\"\\n=== State Machine ===\");\ntask_report(Task);\nlet next_status = advance_task(Task);\nprint(\"Next status: \" + next_status);\n\n// ============================================\n// 5. Factory with Subject Arrays\n// ============================================\n\nfunction CreateEmployee(name, department, salary) {\n    return {\n        name: name,\n        department: department,\n        salary: salary,\n        active: true\n    };\n}\n\nlet team = [\n    CreateEmployee(\"Elif Arslan\", \"Backend\", 95000),\n    CreateEmployee(\"Can Ozkan\", \"Frontend\", 88000),\n    CreateEmployee(\"Seda Yildiz\", \"DevOps\", 102000),\n    CreateEmployee(\"Burak Sahin\", \"Mobile\", 91000)\n];\n\nfunction team_report(team) {\n    print(\"Team Report:\");\n    print(\"─────────────────────────────\");\n    let total_salary = 0;\n    let idx = 0;\n    while (idx < 4) {\n        let emp = team[idx];\n        print(emp.name + \" | \" + emp.department + \" | $\" + emp.salary);\n        total_salary = total_salary + emp.salary;\n        idx = idx + 1;\n    }\n    print(\"─────────────────────────────\");\n    print(\"Total payroll: $\" + total_salary);\n    print(\"Average salary: $\" + (total_salary / 4));\n}\n\nprint(\"\\n=== Team Management ===\");\nteam_report(team);\n"}, "es": {"objects": "// Español - Objetos\n// Objetos con palabras clave nativas\n\n// Crear objeto\nsea persona = {\n    nombre: \"Alicia\",\n    edad: 30,\n    ciudad: \"Madrid\"\n};\n\n// Acceder a propiedades\nsea nombre = persona.nombre;\nsea edad = persona.edad;\n\n// Resultado\nnombre;\n", "chemistry": "// ES - Chemistry Module\n\n// Molar Mass\nfunción molarMass(atoms, atomicWeight) {\n    retornar atoms * atomicWeight;\n}\n\n// Concentration = Moles / Volume\nfunción concentration(moles, volume) {\n    retornar moles / volume;\n}\n\n// pH calculation\nfunción pH(hydrogenConcentration) {\n    retornar 14 - hydrogenConcentration;\n}\n\n// Density = Mass / Volume\nfunción density(mass, volume) {\n    retornar mass / volume;\n}\n\n// Dilution: C1*V1 = C2*V2\nfunción dilution(c1, v1, v2) {\n    retornar (c1 * v1) / v2;\n}\n", "loops": "// Español - Loop Example\nsea contador = 0;\nsea máximo = 5;\n\nmientras (contador < máximo) {\n    contador = contador + 1;\n}\n\ncontador;", "data_processing": "// Español - Data Processing\n// Using NATIVE Español keywords\n\nsea datos1 = 100;\nsea datos2 = 200;\nsea datos3 = 300;\n\nsea total = datos1 + datos2 + datos3;\nsea promedio = total / 3;\n\npromedio;", "arrow_functions": "// Espanol - Funciones Flecha\n// Sintaxis moderna y concisa para funciones\n\n// Funcion flecha - sintaxis corta\nsea sumar = (a, b) => a + b;\nsea multiplicar = (x, y) => x * y;\n\nimprime(sumar(5, 3));      // 8\nimprime(multiplicar(4, 7)); // 28\n\n// Funcion flecha con bloque\nsea calcular = (a, b) => {\n    sea suma = a + b;\n    sea producto = a * b;\n    retorna suma + producto;\n};\n\nsea resultado = calcular(5, 3);\nimprime(resultado);  // 23 (8 + 15)\n\n// Un solo parametro (no se necesitan parentesis)\nsea cuadrado = x => x * x;\nimprime(cuadrado(6));  // 36\n\n// Sin parametros\nsea saludar = () => \"Hola!\";\nimprime(saludar());  // Hola!\n", "modules_import": "// Español - Modules Import Example\n\n// Import math module (direct access)\nusar \"matematicas.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nusar \"fisica.hudhud\" como fizik;\n\n// Import chemistry (direct access)\nusar \"quimica.hudhud\";\n\n// Using math functions (direct)\nsea sum = sumar(10, 5);\nimprimir(sum);\n\nsea product = multiplicar(4, 7);\nimprimir(product);\n\n// Using physics functions (via alias: fizik.functionName)\nsea f = fizik.fuerza(10, 9.8);\nimprimir(f);\n\nsea ke = fizik.energiaCinetica(5, 10);\nimprimir(ke);\n\n// Using chemistry functions (direct)\nsea d = densidad(100, 50);\nimprimir(d);\n\nsea c = concentracion(2, 5);\nimprimir(c);\n", "return_concept": "// Español - Concepto de Retorno\n// return\n\nfunción cuadrado(x) {\n    retorna x * x;\n}\n\nfunción cubo(x) {\n    retorna x * x * x;\n}\n\nimprime(\"=== Math Functions ===\");\nimprime(\"cuadrado(5): \" + cuadrado(5));\nimprime(\"cubo(3): \" + cubo(3));\n\nfunción absoluto(x) {\n    si (x < 0) {\n        retorna -x;\n    }\n    retorna x;\n}\n\nimprime(\"\\n=== Absolute ===\");\nimprime(\"absoluto(-7): \" + absoluto(-7));\nimprime(\"absoluto(3): \" + absoluto(3));\n\nfunción crear_punto(x, y) {\n    retorna { x: x, y: y };\n}\n\nsea p = crear_punto(10, 20);\nimprime(\"\\n=== Point ===\");\nimprime(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfunción factorial(n) {\n    si (n <= 1) {\n        retorna 1;\n    }\n    retorna n * factorial(n - 1);\n}\n\nimprime(\"\\n=== Factorial ===\");\nimprime(\"5! = \" + factorial(5));\nimprime(\"10! = \" + factorial(10));\n", "customer_service": "// Español - Customer Service Agent\n// Using NATIVE Español keywords\n\nsea saludo = \"Hola, ¿cómo puedo ayudarte?\";\nsea respuesta = \"Te ayudaré con tu solicitud.\";\n\nsaludo;", "basic_example": "// Español - Basic Example with NATIVE keywords\nsea equis = 10;\nsea ye = 20;\nsea suma = equis + ye;\nimprimir(suma);\n", "physics": "// ES - Physics Module\n\n// Speed = Distance / Time\nfunción speed(distance, time) {\n    retornar distance / time;\n}\n\n// Force = Mass * Acceleration\nfunción force(mass, acceleration) {\n    retornar mass * acceleration;\n}\n\n// Kinetic Energy = 0.5 * Mass * Velocity^2\nfunción kineticEnergy(mass, velocity) {\n    retornar 0.5 * mass * velocity * velocity;\n}\n\n// Potential Energy = Mass * Gravity * Height\nfunción potentialEnergy(mass, gravity, height) {\n    retornar mass * gravity * height;\n}\n\n// Momentum = Mass * Velocity\nfunción momentum(mass, velocity) {\n    retornar mass * velocity;\n}\n", "error_handling": "// Español - Manejo de errores\n// Control de errores simple con if-else\n\n// Función que verifica errores\nfunción dividir(a, b) {\n    si (b == 0) {\n        devolver { error: verdadero, mensaje: \"Error de división por cero\", valor: 0 };\n    }\n    devolver { error: falso, mensaje: \"\", valor: a / b };\n}\n\nimprimir(\"=== Operación de División ===\");\n\n// Primera división\nimprimir(\"Operación 10 / 2:\");\ndefinir resultado1 = dividir(10, 2);\nsi (resultado1.error) {\n    imprimir(\"Error: \" + resultado1.mensaje);\n} sino {\n    imprimir(\"10 / 2 = \" + resultado1.valor);\n}\n\n// División por cero\nimprimir(\"Operación 10 / 0:\");\ndefinir resultado2 = dividir(10, 0);\nsi (resultado2.error) {\n    imprimir(\"Error capturado: \" + resultado2.mensaje);\n} sino {\n    imprimir(\"Resultado: \" + resultado2.valor);\n}\n\n// Ejemplo de procesamiento de archivos\nimprimir(\"=== Procesamiento de Archivos ===\");\n\nfunción procesar_archivo(nombre) {\n    si (nombre == \"\") {\n        devolver { exitoso: falso, mensaje: \"Error: nombre de archivo vacío\" };\n    }\n    imprimir(\"Procesando: \" + nombre);\n    devolver { exitoso: verdadero, datos: \"Datos de \" + nombre };\n}\n\ndefinir resultado_archivo = procesar_archivo(\"reporte.txt\");\nsi (resultado_archivo.exitoso) {\n    imprimir(\"Resultado: \" + resultado_archivo.datos);\n} sino {\n    imprimir(\"Error: \" + resultado_archivo.mensaje);\n}\n\nimprimir(\"Todo completado\");\n", "matematicas": "// Español - Math Module\n\nfunción sumar(a, b) {\n    retornar a + b;\n}\n\nfunción restar(a, b) {\n    retornar a - b;\n}\n\nfunción multiplicar(a, b) {\n    retornar a * b;\n}\n\nfunción dividir(a, b) {\n    si (b == 0) {\n        imprimir(\"Error: Division by zero!\");\n        retornar 0;\n    } sino {\n        retornar a / b;\n    }\n}\n\nfunción cuadrado(x) {\n    retornar x * x;\n}\n\nfunción cubo(x) {\n    retornar x * x * x;\n}\n\nfunción absoluto(x) {\n    si (x < 0) {\n        retornar -x;\n    } sino {\n        retornar x;\n    }\n}\n\nfunción maximo(a, b) {\n    si (a > b) {\n        retornar a;\n    } sino {\n        retornar b;\n    }\n}\n\nfunción minimo(a, b) {\n    si (a < b) {\n        retornar a;\n    } sino {\n        retornar b;\n    }\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici paquete kullanımı\nusar \"cebir\";\nusar \"fizik\" como paquete;\n\n// Paket içinden belirli modülleri içe aktarma\nusar \"cebir/matris\";\nusar \"cebir/vektor\";\nusar \"fizik/hareket\";\n\nescribe(\"============================================================\");\nescribe(\"HudHudScript Paket Sistemi Demo\");\nescribe(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nescribe(\"📦 Cebir Paketi Kullanımı:\");\nescribe(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nvariable matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nvariable matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nescribe(\"Matris 1:\");\nmatris1.goster();\n\nescribe(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nvariable toplam = matris1.topla(matris2);\nescribe(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nvariable vektor1 = Vektor([1, 2, 3]);\nvariable vektor2 = Vektor([4, 5, 6]);\n\nescribe(\"\\n\\n📐 Vektör İşlemleri:\");\nescribe(\"─────────────────────────────────────────────────────────\\n\");\n\nescribe(\"Vektör 1: \" + vektor1.toString());\nescribe(\"Vektör 2: \" + vektor2.toString());\n\nvariable noktaSal = vektor1.noktaSal(vektor2);\nescribe(\"Nokta Çarpım: \" + noktaSal);\n\nvariable caprazCarpim = vektor1.caprazCarpim(vektor2);\nescribe(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nescribe(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nescribe(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nvariable baslangicHizi = 0;      // m/s\nvariable ivme = 9.8;              // m/s² (yerçekimi)\nvariable zaman = 5;               // saniye\n\nvariable sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nvariable mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nescribe(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nescribe(\"İvme: \" + ivme + \" m/s²\");\nescribe(\"Zaman: \" + zaman + \" s\");\nescribe(\"─────────────────────────────────────────────────────────\");\nescribe(\"Son Hız: \" + sonHiz + \" m/s\");\nescribe(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nescribe(\"\\n\\n📝 Paket Oluşturma:\");\nescribe(\"─────────────────────────────────────────────────────────\\n\");\n\nescribe(\"1. hudhud.toml dosyası oluşturun:\");\nescribe(\"   [package]\");\nescribe(\"   name = 'matematik-utils'\");\nescribe(\"   version = '1.0.0'\");\nescribe(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nescribe(\"\\n2. Bağımlılıklar ekleyin:\");\nescribe(\"   [dependencies]\");\nescribe(\"   cebir = '^2.0.0'\");\nescribe(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nescribe(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nescribe(\"─────────────────────────────────────────────────────────\\n\");\n\nescribe(\"Paket kurma:\");\nescribe(\"  hudhudscript install cebir\");\nescribe(\"  hudhudscript install fizik@1.5.0\");\n\nescribe(\"\\nPaket güncelleme:\");\nescribe(\"  hudhudscript update cebir\");\nescribe(\"  hudhudscript update --all\");\n\nescribe(\"\\nPaket kaldırma:\");\nescribe(\"  hudhudscript remove cebir\");\n\nescribe(\"\\nKurulu paketleri listeleme:\");\nescribe(\"  hudhudscript list\");\n\nescribe(\"\\nPaket arama:\");\nescribe(\"  hudhudscript search matematik\");\n\nescribe(\"\\nPaket bilgisi:\");\nescribe(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nescribe(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nescribe(\"─────────────────────────────────────────────────────────\\n\");\n\nescribe(\"Versiyon belirtme:\");\nescribe(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nescribe(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nescribe(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nescribe(\"\\nGit deposundan:\");\nescribe(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nescribe(\"\\nYerel yoldan:\");\nescribe(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nescribe(\"\\n\\n🔒 Paket Güvenliği:\");\nescribe(\"─────────────────────────────────────────────────────────\\n\");\n\nescribe(\"Güvenlik kontrolü:\");\nescribe(\"  hudhudscript audit\");\n\nescribe(\"\\nChecksum doğrulama:\");\nescribe(\"  hudhudscript verify cebir\");\n\nescribe(\"\\n============================================================\");\nescribe(\"✓ Paket sistemi demo tamamlandı!\");\nescribe(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nescribe(\"============================================================\");\n", "arrays": "// Español - Arreglos\n// Arreglos con palabras clave nativas\n\n// Crear arreglos\nsea números = [1, 2, 3, 4, 5];\nsea nombres = [\"Alicia\", \"Roberto\", \"Carlos\"];\n\n// Acceder a elementos\nsea primero = números[0];\nsea segundo = números[1];\n\n// Resultado\nprimero;\n", "math": "// ES - Math Module\n\n// Addition\nfunción add(a, b) {\n    retornar a + b;\n}\n\n// Subtraction\nfunción subtract(a, b) {\n    retornar a - b;\n}\n\n// Multiplication\nfunción multiply(a, b) {\n    retornar a * b;\n}\n\n// Division\nfunción divide(a, b) {\n    si (b == 0) {\n        imprimir(\"Error: Division by zero!\");\n        retornar 0;\n    } sino {\n        retornar a / b;\n    }\n}\n\n// Square\nfunción square(x) {\n    retornar x * x;\n}\n\n// Cube\nfunción cube(x) {\n    retornar x * x * x;\n}\n\n// Absolute value\nfunción abs(x) {\n    si (x < 0) {\n        retornar -x;\n    } sino {\n        retornar x;\n    }\n}\n\n// Maximum\nfunción max(a, b) {\n    si (a > b) {\n        retornar a;\n    } sino {\n        retornar b;\n    }\n}\n\n// Minimum\nfunción min(a, b) {\n    si (a < b) {\n        retornar a;\n    } sino {\n        retornar b;\n    }\n}\n", "control_flow": "// Español - Control Flow\nsea contador = 0;\nsea máximo = 5;\n\n// Loop\nmientras (contador < máximo) {\n    contador = contador + 1;\n}\n\n// Conditional\nsea puntuación = 85;\n\nsi (puntuación >= 90) {\n    puntuación;\n} sino {\n    si (puntuación >= 80) {\n        puntuación;\n    } sino {\n        puntuación;\n    }\n}\n\ncontador;\n", "state_machine": "// State Machine Example\nsea state = \"initial\";\n\nsi (state == \"initial\") {\n    imprimir(\"Starting\");\n    state = \"running\";\n}\n\nimprimir(state);\n", "conditionals": "// Español - Conditional Logic\nsea puntuación = 85;\n\nsi (puntuación >= 90) {\n    puntuación;\n} sino {\n    si (puntuación >= 80) {\n        puntuación;\n    } sino {\n        puntuación;\n    }\n}", "code_organization": "// Español - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable para large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// usar \"agent/agent_definition.hudhud\";\n// usar \"constitution/laws.hudhud\";\n// usar \"data/note.hudhud\";\n// usar \"utils/math.hudhud\";\n", "module_concepts": "// Español - Modules & Code Organization\n// Demonstrates module system: usar/importar like Rust, Java, C++, Python\n\n// Import math module\nusar \"math.hudhud\";\n\n// Example syntax variations:\n// usar \"math.hudhud\";\n// usar { add, subtract } desde \"math.hudhud\";\n// usar \"math.hudhud\" como math;\n\n// Using functions desde math module\nsea sum = add(10, 5);\nimprimir(sum);\n\nsea diff = subtract(20, 8);\nimprimir(diff);\n\nsea product = multiply(4, 7);\nimprimir(product);\n\nsea quotient = divide(15, 3);\nimprimir(quotient);\n\nsea squared = square(5);\nimprimir(squared);\n\nsea cubed = cube(3);\nimprimir(cubed);\n\nsea absolute = abs(-42);\nimprimir(absolute);\n\nsea maximum = max(100, 50);\nimprimir(maximum);\n\nsea minimum = min(100, 50);\nimprimir(minimum);\n\n// Complex calculation using multiple functions\nsea result = add(multiply(5, 3), divide(20, 4));\nimprimir(result);\n", "higher_order_functions": "// Espanol - Funciones de Orden Superior\n// Funciones que trabajan con otras funciones\n\n// Funcion que devuelve una funcion\nfuncion multiplicador(factor) {\n    retorna (x) => x * factor;\n}\n\nsea doble = multiplicador(2);\nsea triple = multiplicador(3);\n\nimprime(doble(5));  // 10\nimprime(triple(5));  // 15\n\n// Funcion que recibe una funcion\nfuncion aplicar(fn, valor) {\n    retorna fn(valor);\n}\n\nimprime(aplicar(doble, 10));  // 20\n\n// Ejemplo de composicion\nfuncion componer(f, g) {\n    retorna (x) => f(g(x));\n}\n\nsea sumarUno = (x) => x + 1;\nsea porDos = (x) => x * 2;\n\nsea sumarLuegoDoble = componer(porDos, sumarUno);\nimprime(sumarLuegoDoble(5));  // 12 (5+1=6, 6*2=12)\n", "fisica": "// Español - Physics Module\n\nfunción velocidad(distance, time) {\n    retornar distance / time;\n}\n\nfunción fuerza(mass, acceleration) {\n    retornar mass * acceleration;\n}\n\nfunción energiaCinetica(mass, velocity) {\n    retornar 0.5 * mass * velocity * velocity;\n}\n\nfunción energiaPotencial(mass, gravity, height) {\n    retornar mass * gravity * height;\n}\n\nfunción momento(mass, velocity) {\n    retornar mass * velocity;\n}\n", "quimica": "// Español - Chemistry Module\n\nfunción masaMolar(atoms, atomicWeight) {\n    retornar atoms * atomicWeight;\n}\n\nfunción concentracion(moles, volume) {\n    retornar moles / volume;\n}\n\nfunción pH(hydrogenConcentration) {\n    retornar 14 - hydrogenConcentration;\n}\n\nfunción densidad(mass, volume) {\n    retornar mass / volume;\n}\n\nfunción dilucion(c1, v1, v2) {\n    retornar (c1 * v1) / v2;\n}\n", "switch_concepts": "// Español - Conceptos Switch/Case\n// Usando if-else para condiciones múltiples\n\nfunción tipo_dia(dia) {\n    si (dia == \"Lunes\") { devolver \"Día laborable\"; }\n    si (dia == \"Martes\") { devolver \"Día laborable\"; }\n    si (dia == \"Miércoles\") { devolver \"Día laborable\"; }\n    si (dia == \"Jueves\") { devolver \"Día laborable\"; }\n    si (dia == \"Viernes\") { devolver \"Día laborable\"; }\n    si (dia == \"Sábado\") { devolver \"Fin de semana\"; }\n    si (dia == \"Domingo\") { devolver \"Fin de semana\"; }\n    devolver \"Desconocido\";\n}\n\nimprimir(\"=== Tipos de Día ===\");\nimprimir(\"Lunes: \" + tipo_dia(\"Lunes\"));\nimprimir(\"Sábado: \" + tipo_dia(\"Sábado\"));\nimprimir(\"Feriado: \" + tipo_dia(\"Feriado\"));\n\nfunción letra_grado(puntaje) {\n    si (puntaje == 90) { devolver \"A\"; }\n    si (puntaje == 80) { devolver \"B\"; }\n    si (puntaje == 70) { devolver \"C\"; }\n    si (puntaje == 60) { devolver \"D\"; }\n    devolver \"F\";\n}\n\nimprimir(\"=== Calificaciones ===\");\nimprimir(\"90: \" + letra_grado(90));\nimprimir(\"70: \" + letra_grado(70));\nimprimir(\"50: \" + letra_grado(50));\n\nfunción mensaje_estado(código) {\n    si (código == 200) { devolver \"OK\"; }\n    si (código == 404) { devolver \"No encontrado\"; }\n    si (código == 500) { devolver \"Error del servidor\"; }\n    devolver \"Estado desconocido\";\n}\n\nimprimir(\"=== Estado HTTP ===\");\nimprimir(\"200: \" + mensaje_estado(200));\nimprimir(\"404: \" + mensaje_estado(404));\n", "event_concepts": "// Español - Event Concepts\n\nevento UserLogin {\n    imprime(\"User logged in\");\n}\n\nevento DataReceived {\n    imprime(\"Data received\");\n}\n\nevento ErrorOccurred {\n    imprime(\"Error occurred\");\n}\n\nfunción on_login(username) {\n    imprime(\"Login: \" + username);\n    retorna \"Welcome, \" + username;\n}\n\nfunción on_data(source) {\n    imprime(\"Data from: \" + source);\n    retorna \"Processed: \" + source;\n}\n\nfunción on_error(message) {\n    imprime(\"Error: \" + message);\n    retorna \"Handled: \" + message;\n}\n\nimprime(\"=== Event System ===\");\nsea r1 = on_login(\"admin\");\nimprime(r1);\nsea r2 = on_data(\"sensor_1\");\nimprime(r2);\nsea r3 = on_error(\"timeout\");\nimprime(r3);\n", "functions": "// Español - Funciones\n// Ejemplos de definición y uso de funciones\n\n// Función simple\nfunción saludar() {\n    imprime(\"Hola Mundo!\");\n}\n\n// Función con parámetros\nfunción sumar(a, b) {\n    retorna a + b;\n}\n\n// Función con múltiples parámetros\nfunción calcular(num1, num2, operación) {\n    si (operación == \"sumar\") {\n        retorna num1 + num2;\n    } sino {\n        retorna 0;\n    }\n}\n\n// Funciones matemáticas\nfunción cuadrado(x) {\n    retorna x * x;\n}\n\nfunción cubo(x) {\n    retorna x * x * x;\n}\n\n// Uso de funciones\nsaludar();\n\nsea resultado1 = sumar(5, 3);\nimprime(resultado1);\n\nsea resultado2 = calcular(10, 5, \"sumar\");\nimprime(resultado2);\n\nsea resultado_cuadrado = cuadrado(4);\nimprime(resultado_cuadrado);\n\nsea resultado_cubo = cubo(3);\nimprime(resultado_cubo);\n\n// Composición de funciones\nsea total = sumar(cuadrado(3), cubo(2));\nimprime(total);\n", "entity_concepts": "// Español - Conceptos de Entidad\n\nsea usuario = {\n    id: 1,\n    nombre: \"Alicia\",\n    correo: \"alicia@ejemplo.com\",\n    rol: \"desarrolladora\"\n};\n\nsea producto = {\n    id: 101,\n    nombre: \"HudHudScript IDE\",\n    versión: \"2.0\",\n    precio: 49\n};\n\nsea pedido = {\n    id: 1001,\n    id_usuario: 1,\n    id_producto: 101,\n    cantidad: 2,\n    estado: \"confirmado\"\n};\n\nfunción info_entidad(entidad) {\n    retorna \"Entidad #\" + entidad.id + \": \" + entidad.nombre;\n}\n\nfunción calcular_total(pedido, precio) {\n    retorna pedido.cantidad * precio;\n}\n\nimprime(\"=== Sistema de Entidades ===\");\nimprime(info_entidad(usuario));\nimprime(info_entidad(producto));\nsea total = calcular_total(pedido, producto.precio);\nimprime(\"Pedido #\" + pedido.id + \" total: \" + total);\nimprime(\"Estado: \" + pedido.estado);\n", "error_concepts": "// Español - Conceptos de Error\n// Funciones simples de validación\n\nfunción validar_edad(edad) {\n    si (edad < 0) {\n        devolver { válido: falso, error: \"Edad inválida: negativa\" };\n    }\n    si (edad > 150) {\n        devolver { válido: falso, error: \"Edad inválida: demasiado grande\" };\n    }\n    devolver { válido: verdadero, edad: edad };\n}\n\nfunción validar_email(email) {\n    si (email == \"\") {\n        devolver { válido: falso, error: \"Email vacío\" };\n    }\n    devolver { válido: verdadero, email: email };\n}\n\nimprimir(\"=== Validación ===\");\n\ndefinir resultado_edad1 = validar_edad(25);\nsi (resultado_edad1.válido) {\n    imprimir(\"Edad 25 es válida\");\n} sino {\n    imprimir(\"Error: \" + resultado_edad1.error);\n}\n\ndefinir resultado_edad2 = validar_edad(-5);\nsi (resultado_edad2.válido) {\n    imprimir(\"Edad es válida\");\n} sino {\n    imprimir(\"Error: \" + resultado_edad2.error);\n}\n\ndefinir resultado_email1 = validar_email(\"user@example.com\");\nsi (resultado_email1.válido) {\n    imprimir(\"Email válido: \" + resultado_email1.email);\n} sino {\n    imprimir(\"Error de email: \" + resultado_email1.error);\n}\n\ndefinir resultado_email2 = validar_email(\"\");\nsi (resultado_email2.válido) {\n    imprimir(\"Email válido\");\n} sino {\n    imprimir(\"Error de email: \" + resultado_email2.error);\n}\n\nimprimir(\"Validación completada\");\n"}, "fa": {"objects": "// فارسی - اشیا\n// اشیا با کلمات کلیدی فارسی\n\n// ساخت شیء\nبگذار شخص = {\n    نام: \"فاطمه\",\n    سن: ۳۰,\n    شهر: \"تهران\"\n};\n\n// دسترسی به ویژگی‌ها\nبگذار نام = شخص.نام;\nبگذار سن = شخص.سن;\n\n// نتیجه\nنام;\n", "chemistry": "// FA - Chemistry Module\n\nتابع molarMass(atoms, atomicWeight) {\n    برگردان atoms * atomicWeight;\n}\n\nتابع concentration(moles, volume) {\n    برگردان moles / volume;\n}\n\nتابع pH(hydrogenConcentration) {\n    برگردان 14 - hydrogenConcentration;\n}\n\nتابع density(mass, volume) {\n    برگردان mass / volume;\n}\n\nتابع dilution(c1, v1, v2) {\n    برگردان (c1 * v1) / v2;\n}\n", "loops": "// فارسی - حلقه‌ها\nبگذار شمارنده = 0;\nبگذار حداکثر = 5;\n\nتا_وقتی (شمارنده < حداکثر) {\n    چاپ(شمارنده);\n    شمارنده = شمارنده + 1;\n}\n\nچاپ(999);\n", "data_processing": "// فارسی - Data Processing\n// Using NATIVE فارسی keywords\n\nبگذار value1 = 100;\nبگذار value2 = 200;\nبگذار value3 = 300;\n\nبگذار total = value1+ value2+ value3;\nبگذار average = total / 3;\n\nچاپ(total);\nچاپ(average);\n", "modules_import": "// FA - Modules Import Example\n\n// Import math module (direct access)\nاستفاده \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nاستفاده \"physics.hudhud\" به_عنوان fizik;\n\n// Import chemistry (direct access)\nاستفاده \"chemistry.hudhud\";\n\n// Using math functions (direct)\nبگذار sum = add(10, 5);\nچاپ(sum);\n\nبگذار product = multiply(4, 7);\nچاپ(product);\n\n// Using physics functions (via alias: fizik.functionName)\nبگذار f = fizik.force(10, 9.8);\nچاپ(f);\n\nبگذار ke = fizik.kineticEnergy(5, 10);\nچاپ(ke);\n\n// Using chemistry functions (direct)\nبگذار d = density(100, 50);\nچاپ(d);\n\nبگذار c = concentration(2, 5);\nچاپ(c);\n", "return_concept": "// فارسی - مفهوم بازگشت\n// return\n\nتابع مربع(x) {\n    برگردان x * x;\n}\n\nتابع مکعب(x) {\n    برگردان x * x * x;\n}\n\nچاپ(\"=== Math Functions ===\");\nچاپ(\"مربع(5): \" + مربع(5));\nچاپ(\"مکعب(3): \" + مکعب(3));\n\nتابع قدرمطلق(x) {\n    اگر (x < 0) {\n        برگردان -x;\n    }\n    برگردان x;\n}\n\nچاپ(\"\\n=== Absolute ===\");\nچاپ(\"قدرمطلق(-7): \" + قدرمطلق(-7));\nچاپ(\"قدرمطلق(3): \" + قدرمطلق(3));\n\nتابع ایجاد_نقطه(x, y) {\n    برگردان { x: x, y: y };\n}\n\nبگذار p = ایجاد_نقطه(10, 20);\nچاپ(\"\\n=== Point ===\");\nچاپ(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nتابع فاکتوریل(n) {\n    اگر (n <= 1) {\n        برگردان 1;\n    }\n    برگردان n * فاکتوریل(n - 1);\n}\n\nچاپ(\"\\n=== Factorial ===\");\nچاپ(\"5! = \" + فاکتوریل(5));\nچاپ(\"10! = \" + فاکتوریل(10));\n", "customer_service": "// فارسی - عامل خدمات مشتری\n// با کلمات کلیدی فارسی\n\nبگذار خوشامد = \"سلام، چگونه می‌توانم کمکتان کنم؟\";\nبگذار پاسخ = \"به درخواست شما رسیدگی خواهم کرد.\";\n\nچاپ(خوشامد);\nچاپ(پاسخ);\n", "basic_example": "// فارسی - Basic Example with NATIVE keywords\nمتغیر ایکس = 10;\nمتغیر وای = 20;\nمتغیر مجموع = ایکس + وای;\n\nچاپ(مجموع);\n", "physics": "// FA - Physics Module\n\nتابع speed(distance, time) {\n    برگردان distance / time;\n}\n\nتابع force(mass, acceleration) {\n    برگردان mass * acceleration;\n}\n\nتابع kineticEnergy(mass, velocity) {\n    برگردان 0.5 * mass * velocity * velocity;\n}\n\nتابع potentialEnergy(mass, gravity, height) {\n    برگردان mass * gravity * height;\n}\n\nتابع momentum(mass, velocity) {\n    برگردان mass * velocity;\n}\n", "error_handling": "// فارسی - مدیریت خطا\n// try/catch/finally, throw\n\n// Basic try/catch\nتابع تقسیم(a, b) {\n    اگر (b == 0) {\n        پرتاب \"خطای تقسیم بر صفر\";\n    }\n    برگردان a / b;\n}\n\nامتحان {\n    بگذار result = تقسیم(10, 2);\n    چاپ(\"10 / 2 = \" + result);\n} بگیر (error) {\n    چاپ(\"خطا: \" + error);\n}\n\n// Try/catch/finally\nچاپ(\"\n=== پردازش فایل ===\");\n\nتابع پردازش_فایل(filename) {\n    اگر (filename == \"\") {\n        پرتاب \"خطای نام فایل خالی\";\n    }\n    چاپ(\"در حال پردازش: \" + filename);\n    برگردان \"داده از \" + filename;\n}\n\nامتحان {\n    بگذار data = پردازش_فایل(\"report.txt\");\n    چاپ(\"نتیجه: \" + data);\n} بگیر (error) {\n    چاپ(\"خطا: \" + error);\n} در_نهایت {\n    چاپ(\"پاکسازی کامل شد\");\n}\n\n// Nested error handling\nچاپ(\"\n=== مدیریت خطای تودرتو ===\");\n\nامتحان {\n    چاپ(\"بلوک تلاش خارجی\");\n    امتحان {\n        پرتاب \"خطای داخلی\";\n    } بگیر (inner_err) {\n        چاپ(\"خطای داخلی گرفته شد: \" + inner_err);\n        پرتاب \"خطای پرتاب مجدد\";\n    }\n} بگیر (outer_err) {\n    چاپ(\"خطای خارجی گرفته شد: \" + outer_err);\n} در_نهایت {\n    چاپ(\"همه انجام شد\");\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici بسته kullanımı\nاستفاده \"cebir\";\nاستفاده \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nاستفاده \"cebir/matris\";\nاستفاده \"cebir/vektor\";\nاستفاده \"fizik/hareket\";\n\nچاپ(\"============================================================\");\nچاپ(\"HudHudScript Paket Sistemi Demo\");\nچاپ(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nچاپ(\"📦 Cebir Paketi Kullanımı:\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nمتغیر matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nمتغیر matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nچاپ(\"Matris 1:\");\nmatris1.goster();\n\nچاپ(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nمتغیر toplam = matris1.topla(matris2);\nچاپ(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nمتغیر vektor1 = Vektor([1, 2, 3]);\nمتغیر vektor2 = Vektor([4, 5, 6]);\n\nچاپ(\"\\n\\n📐 Vektör İşlemleri:\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\nچاپ(\"Vektör 1: \" + vektor1.toString());\nچاپ(\"Vektör 2: \" + vektor2.toString());\n\nمتغیر noktaSal = vektor1.noktaSal(vektor2);\nچاپ(\"Nokta Çarpım: \" + noktaSal);\n\nمتغیر caprazCarpim = vektor1.caprazCarpim(vektor2);\nچاپ(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nچاپ(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nمتغیر baslangicHizi = 0;      // m/s\nمتغیر ivme = 9.8;              // m/s² (yerçekimi)\nمتغیر zaman = 5;               // saniye\n\nمتغیر sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nمتغیر mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nچاپ(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nچاپ(\"İvme: \" + ivme + \" m/s²\");\nچاپ(\"Zaman: \" + zaman + \" s\");\nچاپ(\"─────────────────────────────────────────────────────────\");\nچاپ(\"Son Hız: \" + sonHiz + \" m/s\");\nچاپ(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nچاپ(\"\\n\\n📝 Paket Oluşturma:\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\nچاپ(\"1. hudhud.toml dosyası oluşturun:\");\nچاپ(\"   [package]\");\nچاپ(\"   name = 'matematik-utils'\");\nچاپ(\"   version = '1.0.0'\");\nچاپ(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nچاپ(\"\\n2. Bağımlılıklar ekleyin:\");\nچاپ(\"   [dependencies]\");\nچاپ(\"   cebir = '^2.0.0'\");\nچاپ(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nچاپ(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\nچاپ(\"Paket kurma:\");\nچاپ(\"  hudhudscript install cebir\");\nچاپ(\"  hudhudscript install fizik@1.5.0\");\n\nچاپ(\"\\nPaket güncelleme:\");\nچاپ(\"  hudhudscript update cebir\");\nچاپ(\"  hudhudscript update --all\");\n\nچاپ(\"\\nPaket kaldırma:\");\nچاپ(\"  hudhudscript remove cebir\");\n\nچاپ(\"\\nKurulu paketleri listeleme:\");\nچاپ(\"  hudhudscript list\");\n\nچاپ(\"\\nPaket arama:\");\nچاپ(\"  hudhudscript search matematik\");\n\nچاپ(\"\\nPaket bilgisi:\");\nچاپ(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nچاپ(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\nچاپ(\"Versiyon belirtme:\");\nچاپ(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nچاپ(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nچاپ(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nچاپ(\"\\nGit deposundan:\");\nچاپ(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nچاپ(\"\\nYerel yoldan:\");\nچاپ(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nچاپ(\"\\n\\n🔒 Paket Güvenliği:\");\nچاپ(\"─────────────────────────────────────────────────────────\\n\");\n\nچاپ(\"Güvenlik kontrolü:\");\nچاپ(\"  hudhudscript audit\");\n\nچاپ(\"\\nChecksum doğrulama:\");\nچاپ(\"  hudhudscript verify cebir\");\n\nچاپ(\"\\n============================================================\");\nچاپ(\"✓ Paket sistemi demo tamamlandı!\");\nچاپ(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nچاپ(\"============================================================\");\n", "arrays": "// فارسی - آرایه‌ها\n// آرایه‌ها با کلمات کلیدی فارسی\n\n// ساخت آرایه‌ها\nبگذار اعداد = [۱, ۲, ۳, ۴, ۵];\nبگذار نام‌ها = [\"فاطمه\", \"علی\", \"مریم\"];\n\n// دسترسی به عناصر\nبگذار اول = اعداد[۰];\nبگذار دوم = اعداد[۱];\n\n// نتیجه\nاول;\n", "math": "// FA - Math Module\n\nfunction add(a, b) {\n    برگردان a + b;\n}\n\nfunction subtract(a, b) {\n    برگردان a - b;\n}\n\nfunction multiply(a, b) {\n    برگردان a * b;\n}\n\nfunction divide(a, b) {\n    اگر (b == 0) {\n        چاپ(\"Error: Division by zero!\");\n        برگردان 0;\n    } وگرنه {\n        برگردان a / b;\n    }\n}\n\nfunction square(x) {\n    برگردان x * x;\n}\n\nfunction cube(x) {\n    برگردان x * x * x;\n}\n\nfunction abs(x) {\n    اگر (x < 0) {\n        برگردان -x;\n    } وگرنه {\n        برگردان x;\n    }\n}\n\nfunction max(a, b) {\n    اگر (a > b) {\n        برگردان a;\n    } وگرنه {\n        برگردان b;\n    }\n}\n\nfunction min(a, b) {\n    اگر (a < b) {\n        برگردان a;\n    } وگرنه {\n        برگردان b;\n    }\n}\n", "control_flow": "// فارسی - جریان کنترل\nمتغیر شمارنده = 0;\nمتغیر حداکثر = 5;\n\n// Loop\nتا_وقتی (شمارنده < حداکثر) {\n    شمارنده = شمارنده + 1;\n}\n\n// Conditional\nمتغیر امتیاز = 85;\n\nاگر (امتیاز >= 90) {\n    امتیاز;\n} وگرنه {\n    اگر (امتیاز >= 80) {\n        امتیاز;\n    } وگرنه {\n        امتیاز;\n    }\n}\n\nشمارنده;\n", "state_machine": "// State Machine Example\nبگذار state = \"initial\";\n\nاگر (state == \"initial\") {\n    چاپ(\"Starting\");\n    state = \"running\";\n}\n\nچاپ(state);\n", "conditionals": "// فارسی - منطق شرطی\nبگذار نمره = 85;\n\nاگر (نمره >= 90) {\n    چاپ(1000);\n} وگرنه {\n    اگر (نمره >= 80) {\n        چاپ(2000);\n    } وگرنه {\n        چاپ(3000);\n    }\n}\n\nچاپ(999);\n", "code_organization": "// فارسی - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable برای large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// استفاده \"agent/agent_definition.hudhud\";\n// استفاده \"constitution/laws.hudhud\";\n// استفاده \"data/note.hudhud\";\n// استفاده \"utils/math.hudhud\";\n", "module_concepts": "// فارسی - Modules & Code Organization\n// Demonstrates module system: استفاده/وارد_کن like Rust, Java, C++, Python\n\n// Import math module\n\"math.hudhud\" kullan;\n\n// Example syntax variations:\n// \"math.hudhud\" استفاده;\n// \"math.hudhud\" از { add, subtract } استفاده;\n// \"math.hudhud\" math به_عنوان استفاده;\n\n// Using functions از math module\nبگذار sum = add(10, 5);\nچاپ(sum);\n\nبگذار diff = subtract(20, 8);\nچاپ(diff);\n\nبگذار product = multiply(4, 7);\nچاپ(product);\n\nبگذار quotient = divide(15, 3);\nچاپ(quotient);\n\nبگذار squared = square(5);\nچاپ(squared);\n\nبگذار cubed = cube(3);\nچاپ(cubed);\n\nبگذار absolute = abs(-42);\nچاپ(absolute);\n\nبگذار maximum = max(100, 50);\nچاپ(maximum);\n\nبگذار minimum = min(100, 50);\nچاپ(minimum);\n\n// Complex calculation using multiple functions\nبگذار result = add(multiply(5, 3), divide(20, 4));\nچاپ(result);\n", "switch_concepts": "// فارسی - مفاهیم انتخاب\n// switch/case/default\n\nتابع نوع_روز(day) {\n    انتخاب (day) {\n        حالت \"Monday\":\n        حالت \"Tuesday\":\n        حالت \"Wednesday\":\n        حالت \"Thursday\":\n        حالت \"Friday\":\n            برگردان \"روز کاری\";\n        حالت \"Saturday\":\n        حالت \"Sunday\":\n            برگردان \"آخر هفته\";\n        پیش_فرض:\n            برگردان \"ناشناخته\";\n    }\n}\n\nچاپ(\"=== Day Types ===\");\nچاپ(\"Monday: \" + نوع_روز(\"Monday\"));\nچاپ(\"Saturday: \" + نوع_روز(\"Saturday\"));\nچاپ(\"Holiday: \" + نوع_روز(\"Holiday\"));\n\nتابع حرف_نمره(score) {\n    انتخاب (score) {\n        حالت 90:\n            برگردان \"A\";\n        حالت 80:\n            برگردان \"B\";\n        حالت 70:\n            برگردان \"C\";\n        حالت 60:\n            برگردان \"D\";\n        پیش_فرض:\n            برگردان \"F\";\n    }\n}\n\nچاپ(\"\\n=== Grades ===\");\nچاپ(\"90: \" + حرف_نمره(90));\nچاپ(\"70: \" + حرف_نمره(70));\nچاپ(\"50: \" + حرف_نمره(50));\n\nتابع پیام_وضعیت(code) {\n    انتخاب (code) {\n        حالت 200:\n            برگردان \"OK\";\n        حالت 404:\n            برگردان \"Not Found\";\n        حالت 500:\n            برگردان \"Server Error\";\n        پیش_فرض:\n            برگردان \"ناشناخته Status\";\n    }\n}\n\nچاپ(\"\\n=== HTTP Status ===\");\nچاپ(\"200: \" + پیام_وضعیت(200));\nچاپ(\"404: \" + پیام_وضعیت(404));\n", "event_concepts": "// فارسی - Event Concepts\n\nرویداد UserLogin {\n    چاپ(\"User logged in\");\n}\n\nرویداد DataReceived {\n    چاپ(\"Data received\");\n}\n\nرویداد ErrorOccurred {\n    چاپ(\"Error occurred\");\n}\n\nتابع on_login(username) {\n    چاپ(\"Login: \" + username);\n    برگردان \"Welcome, \" + username;\n}\n\nتابع on_data(source) {\n    چاپ(\"Data from: \" + source);\n    برگردان \"Processed: \" + source;\n}\n\nتابع on_error(message) {\n    چاپ(\"Error: \" + message);\n    برگردان \"Handled: \" + message;\n}\n\nچاپ(\"=== Event System ===\");\nبگذار r1 = on_login(\"admin\");\nچاپ(r1);\nبگذار r2 = on_data(\"sensor_1\");\nچاپ(r2);\nبگذار r3 = on_error(\"timeout\");\nچاپ(r3);\n", "functions": "// فارسی - توابع\n// نمونه‌های تعریف و استفاده از توابع\n\n// تابع ساده\nتابع سلام_بگو() {\n    چاپ(\"سلام دنیا!\");\n}\n\n// تابع با پارامترها\nتابع جمع(الف, ب) {\n    برگردان الف + ب;\n}\n\n// تابع با تفریق\nتابع تفریق(الف, ب) {\n    برگردان الف - ب;\n}\n\n// توابع ریاضی\nتابع مربع(ع) {\n    برگردان ع * ع;\n}\n\nتابع مکعب(ع) {\n    برگردان ع * ع * ع;\n}\n\n// استفاده از توابع\nسلام_بگو();\n\nبگذار نتیجه۱ = جمع(۵, ۳);\nچاپ(نتیجه۱);\n\nبگذار نتیجه۲ = تفریق(۱۰, ۵);\nچاپ(نتیجه۲);\n\nبگذار نتیجه_مربع = مربع(۴);\nچاپ(نتیجه_مربع);\n\nبگذار نتیجه_مکعب = مکعب(۳);\nچاپ(نتیجه_مکعب);\n\n// ترکیب توابع\nبگذار مجموع = جمع(مربع(۳), مکعب(۲));\nچاپ(مجموع);\n", "entity_concepts": "// فارسی - مفاهیم موجودیت\n\nبگذار کاربر = {\n    شناسه: ۱,\n    نام: \"فاطمه\",\n    ایمیل: \"fatemeh@namune.com\",\n    نقش: \"برنامه‌نویس\"\n};\n\nبگذار محصول = {\n    شناسه: ۱۰۱,\n    نام: \"هدهد اسکریپت آی‌دی‌ای\",\n    نسخه: \"۲.۰\",\n    قیمت: ۴۹\n};\n\nبگذار سفارش = {\n    شناسه: ۱۰۰۱,\n    شناسه_کاربر: ۱,\n    شناسه_محصول: ۱۰۱,\n    تعداد: ۲,\n    وضعیت: \"تایید شده\"\n};\n\nتابع اطلاعات_موجودیت(موجودیت) {\n    برگردان \"موجودیت #\" + موجودیت.شناسه + \": \" + موجودیت.نام;\n}\n\nتابع محاسبه_کل(سفارش, قیمت) {\n    برگردان سفارش.تعداد * قیمت;\n}\n\nچاپ(\"=== سیستم موجودیت ===\");\nچاپ(اطلاعات_موجودیت(کاربر));\nچاپ(اطلاعات_موجودیت(محصول));\nبگذار کل = محاسبه_کل(سفارش, محصول.قیمت);\nچاپ(\"سفارش #\" + سفارش.شناسه + \" کل: \" + کل);\nچاپ(\"وضعیت: \" + سفارش.وضعیت);\n", "error_concepts": "// فارسی - Error Concepts\n\nتابع validate_age(age) {\n    اگر (age < 0) {\n        پرتاب \"Invalid age: negative\";\n    }\n    اگر (age > 150) {\n        پرتاب \"Invalid age: too large\";\n    }\n    برگردان age;\n}\n\nتابع validate_email(email) {\n    اگر (email == \"\") {\n        پرتاب \"Empty email\";\n    }\n    چاپ(\"Email valid: \" + email);\n    برگردان email;\n}\n\nچاپ(\"=== Validation ===\");\n\nامتحان {\n    validate_age(25);\n    چاپ(\"Age 25: valid\");\n} بگیر (error) {\n    چاپ(\"Error: \" + error);\n}\n\nامتحان {\n    validate_age(-5);\n} بگیر (error) {\n    چاپ(\"Error: \" + error);\n}\n\nامتحان {\n    validate_email(\"user@example.com\");\n    validate_email(\"\");\n} بگیر (error) {\n    چاپ(\"Email error: \" + error);\n} در_نهایت {\n    چاپ(\"Validation complete\");\n}\n"}, "fr": {"objects": "// Français - Objets\n// Objets avec mots-clés natifs\n\n// Créer un objet\nsoit personne = {\n    nom: \"Alice\",\n    âge: 30,\n    ville: \"Paris\"\n};\n\n// Accéder aux propriétés\nsoit nom = personne.nom;\nsoit âge = personne.âge;\n\n// Résultat\nnom;\n", "chemistry": "// FR - Chemistry Module\n\n// Molar Mass\nfonction molarMass(atoms, atomicWeight) {\n    retourner atoms * atomicWeight;\n}\n\n// Concentration = Moles / Volume\nfonction concentration(moles, volume) {\n    retourner moles / volume;\n}\n\n// pH calculation\nfonction pH(hydrogenConcentration) {\n    retourner 14 - hydrogenConcentration;\n}\n\n// Density = Mass / Volume\nfonction density(mass, volume) {\n    retourner mass / volume;\n}\n\n// Dilution: C1*V1 = C2*V2\nfonction dilution(c1, v1, v2) {\n    retourner (c1 * v1) / v2;\n}\n", "loops": "// Français - Boucles\nsoit compteur = 0;\nsoit maximum = 5;\n\npendant (compteur < maximum) {\n    affiche(compteur);\n    compteur = compteur + 1;\n}\n\naffiche(999);\n", "data_processing": "// Français - Data Processing\n// Using NATIVE Français keywords\n\nvariable value1 = 100;\nvariable value2 = 200;\nvariable value3 = 300;\n\nvariable total = value1+ value2+ value3;\nvariable average = total / 3;\n\nafficher(total);\nafficher(average);\n", "modules_import": "// Français - Modules Import Example\n\n// Import math module (direct access)\nutiliser \"mathematiques.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nutiliser \"physique.hudhud\" comme fizik;\n\n// Import chemistry (direct access)\nutiliser \"chimie.hudhud\";\n\n// Using math functions (direct)\nvariable sum = ajouter(10, 5);\nimprimer(sum);\n\nvariable product = multiplier(4, 7);\nimprimer(product);\n\n// Using physics functions (via alias: fizik.functionName)\nvariable f = fizik.force(10, 9.8);\nimprimer(f);\n\nvariable ke = fizik.energieCinetique(5, 10);\nimprimer(ke);\n\n// Using chemistry functions (direct)\nvariable d = densite(100, 50);\nimprimer(d);\n\nvariable c = concentration(2, 5);\nimprimer(c);\n", "return_concept": "// Français - Concept de Retour\n// return\n\nfonction carré(x) {\n    retour x * x;\n}\n\nfonction cube(x) {\n    retour x * x * x;\n}\n\naffiche(\"=== Math Functions ===\");\naffiche(\"carré(5): \" + carré(5));\naffiche(\"cube(3): \" + cube(3));\n\nfonction absolu(x) {\n    si (x < 0) {\n        retour -x;\n    }\n    retour x;\n}\n\naffiche(\"\\n=== Absolute ===\");\naffiche(\"absolu(-7): \" + absolu(-7));\naffiche(\"absolu(3): \" + absolu(3));\n\nfonction créer_point(x, y) {\n    retour { x: x, y: y };\n}\n\nsoit p = créer_point(10, 20);\naffiche(\"\\n=== Point ===\");\naffiche(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfonction factorielle(n) {\n    si (n <= 1) {\n        retour 1;\n    }\n    retour n * factorielle(n - 1);\n}\n\naffiche(\"\\n=== Factorial ===\");\naffiche(\"5! = \" + factorielle(5));\naffiche(\"10! = \" + factorielle(10));\n", "customer_service": "// Français - Agent de Service Client\n// Utilisant les mots-clés NATIFS du Français\n\nsoit salutation = \"Bonjour, comment puis-je vous aider?\";\nsoit réponse = \"Je vais vous aider avec votre demande.\";\n\naffiche(salutation);\naffiche(réponse);\n", "basic_example": "// Français - Basic Example with NATIVE keywords\nvariable a = 10;\nvariable b = 20;\nvariable somme = a + b;\n\nimprimer(somme);\n", "physics": "// FR - Physics Module\n\n// Speed = Distance / Time\nfonction speed(distance, time) {\n    retourner distance / time;\n}\n\n// Force = Mass * Acceleration\nfonction force(mass, acceleration) {\n    retourner mass * acceleration;\n}\n\n// Kinetic Energy = 0.5 * Mass * Velocity^2\nfonction kineticEnergy(mass, velocity) {\n    retourner 0.5 * mass * velocity * velocity;\n}\n\n// Potential Energy = Mass * Gravity * Height\nfonction potentialEnergy(mass, gravity, height) {\n    retourner mass * gravity * height;\n}\n\n// Momentum = Mass * Velocity\nfonction momentum(mass, velocity) {\n    retourner mass * velocity;\n}\n", "error_handling": "// fr - Error Handling\n// Simple error control with if-else\n\nfunction divide(a, b) {\n    if (b == 0) {\n        return { error: true, message: \"Division by zero\", value: 0 };\n    }\n    return { error: false, message: \"\", value: a / b };\n}\n\nprint(\"=== Error Handling ===\");\n\nvar result1 = divide(10, 2);\nif (result1.error) {\n    print(\"Error: \" + result1.message);\n} else {\n    print(\"10 / 2 = \" + result1.value);\n}\n\nvar result2 = divide(10, 0);\nif (result2.error) {\n    print(\"Error caught: \" + result2.message);\n} else {\n    print(\"Result: \" + result2.value);\n}\n\nprint(\"Done\");\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici paquet kullanımı\nutiliser \"cebir\";\nutiliser \"fizik\" comme paquet;\n\n// Paket içinden belirli modülleri içe aktarma\nutiliser \"cebir/matris\";\nutiliser \"cebir/vektor\";\nutiliser \"fizik/hareket\";\n\nécris(\"============================================================\");\nécris(\"HudHudScript Paket Sistemi Demo\");\nécris(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nécris(\"📦 Cebir Paketi Kullanımı:\");\nécris(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nvariable matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nvariable matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nécris(\"Matris 1:\");\nmatris1.goster();\n\nécris(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nvariable toplam = matris1.topla(matris2);\nécris(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nvariable vektor1 = Vektor([1, 2, 3]);\nvariable vektor2 = Vektor([4, 5, 6]);\n\nécris(\"\\n\\n📐 Vektör İşlemleri:\");\nécris(\"─────────────────────────────────────────────────────────\\n\");\n\nécris(\"Vektör 1: \" + vektor1.toString());\nécris(\"Vektör 2: \" + vektor2.toString());\n\nvariable noktaSal = vektor1.noktaSal(vektor2);\nécris(\"Nokta Çarpım: \" + noktaSal);\n\nvariable caprazCarpim = vektor1.caprazCarpim(vektor2);\nécris(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nécris(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nécris(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nvariable baslangicHizi = 0;      // m/s\nvariable ivme = 9.8;              // m/s² (yerçekimi)\nvariable zaman = 5;               // saniye\n\nvariable sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nvariable mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nécris(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nécris(\"İvme: \" + ivme + \" m/s²\");\nécris(\"Zaman: \" + zaman + \" s\");\nécris(\"─────────────────────────────────────────────────────────\");\nécris(\"Son Hız: \" + sonHiz + \" m/s\");\nécris(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nécris(\"\\n\\n📝 Paket Oluşturma:\");\nécris(\"─────────────────────────────────────────────────────────\\n\");\n\nécris(\"1. hudhud.toml dosyası oluşturun:\");\nécris(\"   [package]\");\nécris(\"   name = 'matematik-utils'\");\nécris(\"   version = '1.0.0'\");\nécris(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nécris(\"\\n2. Bağımlılıklar ekleyin:\");\nécris(\"   [dependencies]\");\nécris(\"   cebir = '^2.0.0'\");\nécris(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nécris(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nécris(\"─────────────────────────────────────────────────────────\\n\");\n\nécris(\"Paket kurma:\");\nécris(\"  hudhudscript install cebir\");\nécris(\"  hudhudscript install fizik@1.5.0\");\n\nécris(\"\\nPaket güncelleme:\");\nécris(\"  hudhudscript update cebir\");\nécris(\"  hudhudscript update --all\");\n\nécris(\"\\nPaket kaldırma:\");\nécris(\"  hudhudscript remove cebir\");\n\nécris(\"\\nKurulu paketleri listeleme:\");\nécris(\"  hudhudscript list\");\n\nécris(\"\\nPaket arama:\");\nécris(\"  hudhudscript search matematik\");\n\nécris(\"\\nPaket bilgisi:\");\nécris(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nécris(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nécris(\"─────────────────────────────────────────────────────────\\n\");\n\nécris(\"Versiyon belirtme:\");\nécris(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nécris(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nécris(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nécris(\"\\nGit deposundan:\");\nécris(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nécris(\"\\nYerel yoldan:\");\nécris(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nécris(\"\\n\\n🔒 Paket Güvenliği:\");\nécris(\"─────────────────────────────────────────────────────────\\n\");\n\nécris(\"Güvenlik kontrolü:\");\nécris(\"  hudhudscript audit\");\n\nécris(\"\\nChecksum doğrulama:\");\nécris(\"  hudhudscript verify cebir\");\n\nécris(\"\\n============================================================\");\nécris(\"✓ Paket sistemi demo tamamlandı!\");\nécris(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nécris(\"============================================================\");\n", "arrays": "// Français - Tableaux\n// Tableaux avec mots-clés natifs\n\n// Créer des tableaux\nsoit nombres = [1, 2, 3, 4, 5];\nsoit prénoms = [\"Alice\", \"Bernard\", \"Charles\"];\n\n// Accéder aux éléments\nsoit premier = nombres[0];\nsoit deuxième = nombres[1];\n\n// Résultat\npremier;\n", "math": "// Français - Module mathématique\n\nfonction additionner(a, b) {\n    retour a + b;\n}\n\nfonction soustraire(a, b) {\n    retour a - b;\n}\n\nfonction multiplier(a, b) {\n    retour a * b;\n}\n\nfonction diviser(a, b) {\n    si (b == 0) {\n        affiche(\"Erreur: Division par zéro!\");\n        retour 0;\n    } sinon {\n        retour a / b;\n    }\n}\n\nfonction carré(x) {\n    retour x * x;\n}\n\nfonction cube(x) {\n    retour x * x * x;\n}\n\nfonction absolue(x) {\n    si (x < 0) {\n        retour -x;\n    } sinon {\n        retour x;\n    }\n}\n\nfonction maximum(a, b) {\n    si (a > b) {\n        retour a;\n    } sinon {\n        retour b;\n    }\n}\n\nfonction minimum(a, b) {\n    si (a < b) {\n        retour a;\n    } sinon {\n        retour b;\n    }\n}\n", "control_flow": "// Français - Flux de contrôle\nsoit compteur = 0;\nsoit maximum = 5;\n\n// Boucle\ntantque (compteur < maximum) {\n    compteur = compteur + 1;\n}\n\n// Condition\nsoit note = 85;\n\nsi (note >= 90) {\n    note;\n} sinon {\n    si (note >= 80) {\n        note;\n    } sinon {\n        note;\n    }\n}\n\ncompteur;\n", "state_machine": "// State Machine Example\nvariable state = \"initial\";\n\nsi (state == \"initial\") {\n    afficher(\"Starting\");\n    state = \"running\";\n}\n\nafficher(state);\n", "conditionals": "// Français - Logique conditionnelle\nsoit note = 85;\n\nsi (note >= 90) {\n    note;\n} sinon {\n    si (note >= 80) {\n        note;\n    } sinon {\n        note;\n    }\n}\n", "code_organization": "// Français - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable pour large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// utiliser \"agent/agent_definition.hudhud\";\n// utiliser \"constitution/laws.hudhud\";\n// utiliser \"data/note.hudhud\";\n// utiliser \"utils/math.hudhud\";\n", "module_concepts": "// Français - Modules & Code Organization\n// Demonstrates module system: utiliser/importer like Rust, Java, C++, Python\n\n// Import math module\nutiliser \"math.hudhud\";\n\n// Example syntax variations:\n// utiliser \"math.hudhud\";\n// utiliser { add, subtract } de \"math.hudhud\";\n// utiliser \"math.hudhud\" comme math;\n\n// Using functions depuis math module\nvariable sum = add(10, 5);\nimprimer(sum);\n\nvariable diff = subtract(20, 8);\nimprimer(diff);\n\nvariable product = multiply(4, 7);\nimprimer(product);\n\nvariable quotient = divide(15, 3);\nimprimer(quotient);\n\nvariable squared = square(5);\nimprimer(squared);\n\nvariable cubed = cube(3);\nimprimer(cubed);\n\nvariable absolute = abs(-42);\nimprimer(absolute);\n\nvariable maximum = max(100, 50);\nimprimer(maximum);\n\nvariable minimum = min(100, 50);\nimprimer(minimum);\n\n// Complex calculation using multiple functions\nvariable result = add(multiply(5, 3), divide(20, 4));\nimprimer(result);\n", "chimie": "// Français - Chemistry Module\n\nfonction masseMolaire(atoms, atomicWeight) {\n    retourner atoms * atomicWeight;\n}\n\nfonction concentration(moles, volume) {\n    retourner moles / volume;\n}\n\nfonction pH(hydrogenConcentration) {\n    retourner 14 - hydrogenConcentration;\n}\n\nfonction densite(mass, volume) {\n    retourner mass / volume;\n}\n\nfonction dilution(c1, v1, v2) {\n    retourner (c1 * v1) / v2;\n}\n", "mathematiques": "// Français - Math Module\n\nfonction ajouter(a, b) {\n    retourner a + b;\n}\n\nfonction soustraire(a, b) {\n    retourner a - b;\n}\n\nfonction multiplier(a, b) {\n    retourner a * b;\n}\n\nfonction diviser(a, b) {\n    si (b == 0) {\n        imprimer(\"Error: Division by zero!\");\n        retourner 0;\n    } autrement {\n        retourner a / b;\n    }\n}\n\nfonction carre(x) {\n    retourner x * x;\n}\n\nfonction cube(x) {\n    retourner x * x * x;\n}\n\nfonction absolu(x) {\n    si (x < 0) {\n        retourner -x;\n    } autrement {\n        retourner x;\n    }\n}\n\nfonction maximum(a, b) {\n    si (a > b) {\n        retourner a;\n    } autrement {\n        retourner b;\n    }\n}\n\nfonction minimum(a, b) {\n    si (a < b) {\n        retourner a;\n    } autrement {\n        retourner b;\n    }\n}\n", "physique": "// Français - Physics Module\n\nfonction vitesse(distance, time) {\n    retourner distance / time;\n}\n\nfonction force(mass, acceleration) {\n    retourner mass * acceleration;\n}\n\nfonction energieCinetique(mass, velocity) {\n    retourner 0.5 * mass * velocity * velocity;\n}\n\nfonction energiePotentielle(mass, gravity, height) {\n    retourner mass * gravity * height;\n}\n\nfonction quantite(mass, velocity) {\n    retourner mass * velocity;\n}\n", "switch_concepts": "// fr - Switch Concepts\n// Using if-else for multiple conditions\n\nfunction dayType(day) {\n    if (day == \"Monday\") { return \"Weekday\"; }\n    if (day == \"Tuesday\") { return \"Weekday\"; }\n    if (day == \"Wednesday\") { return \"Weekday\"; }\n    if (day == \"Thursday\") { return \"Weekday\"; }\n    if (day == \"Friday\") { return \"Weekday\"; }\n    if (day == \"Saturday\") { return \"Weekend\"; }\n    if (day == \"Sunday\") { return \"Weekend\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== Day Types ===\");\nprint(\"Monday: \" + dayType(\"Monday\"));\nprint(\"Saturday: \" + dayType(\"Saturday\"));\nprint(\"Holiday: \" + dayType(\"Holiday\"));\n\nfunction statusMessage(code) {\n    if (code == 200) { return \"OK\"; }\n    if (code == 404) { return \"Not Found\"; }\n    if (code == 500) { return \"Server Error\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== HTTP Status ===\");\nprint(\"200: \" + statusMessage(200));\nprint(\"404: \" + statusMessage(404));\n", "event_concepts": "// Français - Event Concepts\n\névénement UserLogin {\n    affiche(\"User logged in\");\n}\n\névénement DataReceived {\n    affiche(\"Data received\");\n}\n\névénement ErrorOccurred {\n    affiche(\"Error occurred\");\n}\n\nfonction on_login(username) {\n    affiche(\"Login: \" + username);\n    retour \"Welcome, \" + username;\n}\n\nfonction on_data(source) {\n    affiche(\"Data from: \" + source);\n    retour \"Processed: \" + source;\n}\n\nfonction on_error(message) {\n    affiche(\"Error: \" + message);\n    retour \"Handled: \" + message;\n}\n\naffiche(\"=== Event System ===\");\nsoit r1 = on_login(\"admin\");\naffiche(r1);\nsoit r2 = on_data(\"sensor_1\");\naffiche(r2);\nsoit r3 = on_error(\"timeout\");\naffiche(r3);\n", "functions": "// Français - Fonctions\n// Exemples de définition et d'utilisation de fonctions\n\n// Fonction simple\nfonction saluer() {\n    affiche(\"Bonjour le monde!\");\n}\n\n// Fonction avec paramètres\nfonction ajouter(a, b) {\n    retourner a + b;\n}\n\n// Fonctions mathématiques\nfonction carré(x) {\n    retourner x * x;\n}\n\nfonction cube(x) {\n    retourner x * x * x;\n}\n\n// Utilisation des fonctions\nsaluer();\n\nsoit résultat1 = ajouter(5, 3);\naffiche(résultat1);\n\nsoit résultat_carré = carré(4);\naffiche(résultat_carré);\n\nsoit résultat_cube = cube(3);\naffiche(résultat_cube);\n\n// Composition de fonctions\nsoit total = ajouter(carré(3), cube(2));\naffiche(total);\n", "entity_concepts": "// Français - Concepts d'Entité\n\nsoit utilisateur = {\n    id: 1,\n    nom: \"Alice\",\n    courriel: \"alice@exemple.com\",\n    rôle: \"développeur\"\n};\n\nsoit produit = {\n    id: 101,\n    nom: \"HudHudScript IDE\",\n    version: \"2.0\",\n    prix: 49\n};\n\nsoit commande = {\n    id: 1001,\n    id_utilisateur: 1,\n    id_produit: 101,\n    quantité: 2,\n    statut: \"confirmé\"\n};\n\nfonction info_entité(entité) {\n    retour \"Entité #\" + entité.id + \": \" + entité.nom;\n}\n\nfonction calculer_total(commande, prix) {\n    retour commande.quantité * prix;\n}\n\naffiche(\"=== Système d'Entités ===\");\naffiche(info_entité(utilisateur));\naffiche(info_entité(produit));\nsoit total = calculer_total(commande, produit.prix);\naffiche(\"Commande #\" + commande.id + \" total: \" + total);\naffiche(\"Statut: \" + commande.statut);\n", "error_concepts": "// fr - Error Concepts\n// Simple validation functions\n\nfunction validateAge(age) {\n    if (age < 0) {\n        return { valid: false, error: \"Invalid age: negative\" };\n    }\n    if (age > 150) {\n        return { valid: false, error: \"Invalid age: too large\" };\n    }\n    return { valid: true, age: age };\n}\n\nfunction validateEmail(email) {\n    if (email == \"\") {\n        return { valid: false, error: \"Empty email\" };\n    }\n    return { valid: true, email: email };\n}\n\nprint(\"=== Validation ===\");\n\nvar ageResult1 = validateAge(25);\nif (ageResult1.valid) {\n    print(\"Age 25 is valid\");\n} else {\n    print(\"Error: \" + ageResult1.error);\n}\n\nvar ageResult2 = validateAge(-5);\nif (ageResult2.valid) {\n    print(\"Age is valid\");\n} else {\n    print(\"Error: \" + ageResult2.error);\n}\n\nvar emailResult = validateEmail(\"user@example.com\");\nif (emailResult.valid) {\n    print(\"Email valid: \" + emailResult.email);\n} else {\n    print(\"Email error: \" + emailResult.error);\n}\n\nprint(\"Validation complete\");\n"}, "hr": {"objects": "// Hrvatski - Objekti\n// Objekti s domaćim ključnim riječima\n\n// Kreiraj objekt\nneka osoba = {\n    ime: \"Ana\",\n    godine: 30,\n    grad: \"Zagreb\"\n};\n\n// Pristupi svojstvima\nneka ime = osoba.ime;\nneka godine = osoba.godine;\n\n// Rezultat\nime;\n", "chemistry": "// HR - Chemistry Module\n\nfunkcija molarMass(atoms, atomicWeight) {\n    vrati atoms * atomicWeight;\n}\n\nfunkcija concentration(moles, volume) {\n    vrati moles / volume;\n}\n\nfunkcija pH(hydrogenConcentration) {\n    vrati 14 - hydrogenConcentration;\n}\n\nfunkcija density(mass, volume) {\n    vrati mass / volume;\n}\n\nfunkcija dilution(c1, v1, v2) {\n    vrati (c1 * v1) / v2;\n}\n", "loops": "// Hrvatski - Primjer petlje\nneka brojač = 0;\nneka maksimum = 5;\n\ndok (brojač < maksimum) {\n    ispiši(brojač);\n    brojač = brojač + 1;\n}\n\nispiši(999);\n", "data_processing": "// Hrvatski - Data Processing\n// Using NATIVE Hrvatski keywords\n\nneka value1 = 100;\nneka value2 = 200;\nneka value3 = 300;\n\nneka total = value1+ value2+ value3;\nneka average = total / 3;\n\nispiši(total);\nispiši(average);\n", "modules_import": "// HR - Modules Import Example\n\n// Import math module (direct access)\nkoristi \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nkoristi \"physics.hudhud\" kao fizik;\n\n// Import chemistry (direct access)\nkoristi \"chemistry.hudhud\";\n\n// Using math functions (direct)\nneka sum = add(10, 5);\nispiši(sum);\n\nneka product = multiply(4, 7);\nispiši(product);\n\n// Using physics functions (via alias: fizik.functionName)\nneka f = fizik.force(10, 9.8);\nispiši(f);\n\nneka ke = fizik.kineticEnergy(5, 10);\nispiši(ke);\n\n// Using chemistry functions (direct)\nneka d = density(100, 50);\nispiši(d);\n\nneka c = concentration(2, 5);\nispiši(c);\n", "return_concept": "// Hrvatski - Koncept povratka\n// return\n\nfunkcija kvadrat(x) {\n    vrati x * x;\n}\n\nfunkcija kub(x) {\n    vrati x * x * x;\n}\n\nispiši(\"=== Math Functions ===\");\nispiši(\"kvadrat(5): \" + kvadrat(5));\nispiši(\"kub(3): \" + kub(3));\n\nfunkcija apsolutna(x) {\n    ako (x < 0) {\n        vrati -x;\n    }\n    vrati x;\n}\n\nispiši(\"\\n=== Absolute ===\");\nispiši(\"apsolutna(-7): \" + apsolutna(-7));\nispiši(\"apsolutna(3): \" + apsolutna(3));\n\nfunkcija kreiraj_točku(x, y) {\n    vrati { x: x, y: y };\n}\n\nneka p = kreiraj_točku(10, 20);\nispiši(\"\\n=== Point ===\");\nispiši(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfunkcija faktorijel(n) {\n    ako (n <= 1) {\n        vrati 1;\n    }\n    vrati n * faktorijel(n - 1);\n}\n\nispiši(\"\\n=== Factorial ===\");\nispiši(\"5! = \" + faktorijel(5));\nispiši(\"10! = \" + faktorijel(10));\n", "customer_service": "// Hrvatski - Agent za korisničku podršku\n// Koristi DOMAĆE hrvatske ključne riječi\n\nneka pozdrav = \"Zdravo, kako vam mogu pomoći?\";\nneka odgovor = \"Pomoći ću vam s vašim zahtjevom.\";\n\nispiši(pozdrav);\nispiši(odgovor);\n", "basic_example": "// Hrvatski - Basic Example with NATIVE keywords\nvarijabla a = 10;\nvarijabla b = 20;\nvarijabla suma = a + b;\n\nispiši(suma);\n", "physics": "// HR - Physics Module\n\nfunkcija speed(distance, time) {\n    vrati distance / time;\n}\n\nfunkcija force(mass, acceleration) {\n    vrati mass * acceleration;\n}\n\nfunkcija kineticEnergy(mass, velocity) {\n    vrati 0.5 * mass * velocity * velocity;\n}\n\nfunkcija potentialEnergy(mass, gravity, height) {\n    vrati mass * gravity * height;\n}\n\nfunkcija momentum(mass, velocity) {\n    vrati mass * velocity;\n}\n", "error_handling": "// Hrvatski - Upravljanje greškama\n// try/catch/finally, throw\n\n// Basic try/catch\nfunkcija podijeli(a, b) {\n    ako (b == 0) {\n        baci \"Greška dijeljenja nulom\";\n    }\n    vrati a / b;\n}\n\npokušaj {\n    neka result = podijeli(10, 2);\n    ispiši(\"10 / 2 = \" + result);\n} uhvati (error) {\n    ispiši(\"Greška: \" + error);\n}\n\n// Try/catch/finally\nispiši(\"\n=== Obrada datoteke ===\");\n\nfunkcija obradi_datoteku(filename) {\n    ako (filename == \"\") {\n        baci \"Greška praznog naziva datoteke\";\n    }\n    ispiši(\"Obrada: \" + filename);\n    vrati \"Podaci iz \" + filename;\n}\n\npokušaj {\n    neka data = obradi_datoteku(\"report.txt\");\n    ispiši(\"Rezultat: \" + data);\n} uhvati (error) {\n    ispiši(\"Greška: \" + error);\n} konačno {\n    ispiši(\"Čišćenje završeno\");\n}\n\n// Nested error handling\nispiši(\"\n=== Ugniježđeno upravljanje greškama ===\");\n\npokušaj {\n    ispiši(\"Vanjski pokušaj blok\");\n    pokušaj {\n        baci \"Unutrašnja greška\";\n    } uhvati (inner_err) {\n        ispiši(\"Uhvaćena unutrašnja: \" + inner_err);\n        baci \"Ponovo bačena greška\";\n    }\n} uhvati (outer_err) {\n    ispiši(\"Uhvaćena vanjska: \" + outer_err);\n} konačno {\n    ispiši(\"Sve gotovo\");\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici paket kullanımı\nkoristi \"cebir\";\nkoristi \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nkoristi \"cebir/matris\";\nkoristi \"cebir/vektor\";\nkoristi \"fizik/hareket\";\n\npiši(\"============================================================\");\npiši(\"HudHudScript Paket Sistemi Demo\");\npiši(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\npiši(\"📦 Cebir Paketi Kullanımı:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nvarijabla matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nvarijabla matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\npiši(\"Matris 1:\");\nmatris1.goster();\n\npiši(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nvarijabla toplam = matris1.topla(matris2);\npiši(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nvarijabla vektor1 = Vektor([1, 2, 3]);\nvarijabla vektor2 = Vektor([4, 5, 6]);\n\npiši(\"\\n\\n📐 Vektör İşlemleri:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"Vektör 1: \" + vektor1.toString());\npiši(\"Vektör 2: \" + vektor2.toString());\n\nvarijabla noktaSal = vektor1.noktaSal(vektor2);\npiši(\"Nokta Çarpım: \" + noktaSal);\n\nvarijabla caprazCarpim = vektor1.caprazCarpim(vektor2);\npiši(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\npiši(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nvarijabla baslangicHizi = 0;      // m/s\nvarijabla ivme = 9.8;              // m/s² (yerçekimi)\nvarijabla zaman = 5;               // saniye\n\nvarijabla sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nvarijabla mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\npiši(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\npiši(\"İvme: \" + ivme + \" m/s²\");\npiši(\"Zaman: \" + zaman + \" s\");\npiši(\"─────────────────────────────────────────────────────────\");\npiši(\"Son Hız: \" + sonHiz + \" m/s\");\npiši(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\npiši(\"\\n\\n📝 Paket Oluşturma:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"1. hudhud.toml dosyası oluşturun:\");\npiši(\"   [package]\");\npiši(\"   name = 'matematik-utils'\");\npiši(\"   version = '1.0.0'\");\npiši(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\npiši(\"\\n2. Bağımlılıklar ekleyin:\");\npiši(\"   [dependencies]\");\npiši(\"   cebir = '^2.0.0'\");\npiši(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\npiši(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"Paket kurma:\");\npiši(\"  hudhudscript install cebir\");\npiši(\"  hudhudscript install fizik@1.5.0\");\n\npiši(\"\\nPaket güncelleme:\");\npiši(\"  hudhudscript update cebir\");\npiši(\"  hudhudscript update --all\");\n\npiši(\"\\nPaket kaldırma:\");\npiši(\"  hudhudscript remove cebir\");\n\npiši(\"\\nKurulu paketleri listeleme:\");\npiši(\"  hudhudscript list\");\n\npiši(\"\\nPaket arama:\");\npiši(\"  hudhudscript search matematik\");\n\npiši(\"\\nPaket bilgisi:\");\npiši(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\npiši(\"\\n\\n🔗 Paket Bağımlılıkları:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"Versiyon belirtme:\");\npiši(\"  'cebir' = '^2.0.0'    # 2.x.x\");\npiši(\"  'fizik' = '~1.5.0'    # 1.5.x\");\npiši(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\npiši(\"\\nGit deposundan:\");\npiši(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\npiši(\"\\nYerel yoldan:\");\npiši(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\npiši(\"\\n\\n🔒 Paket Güvenliği:\");\npiši(\"─────────────────────────────────────────────────────────\\n\");\n\npiši(\"Güvenlik kontrolü:\");\npiši(\"  hudhudscript audit\");\n\npiši(\"\\nChecksum doğrulama:\");\npiši(\"  hudhudscript verify cebir\");\n\npiši(\"\\n============================================================\");\npiši(\"✓ Paket sistemi demo tamamlandı!\");\npiši(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\npiši(\"============================================================\");\n", "arrays": "// Hrvatski - Nizovi\n// Nizovi s domaćim ključnim riječima\n\n// Kreiraj nizove\nneka brojevi = [1, 2, 3, 4, 5];\nneka imena = [\"Ana\", \"Ivan\", \"Maja\"];\n\n// Pristupi elementima\nneka prvi = brojevi[0];\nneka drugi = brojevi[1];\n\n// Rezultat\nprvi;\n", "math": "// HR - Math Module\n\nfunction add(a, b) {\n    vrati a + b;\n}\n\nfunction subtract(a, b) {\n    vrati a - b;\n}\n\nfunction multiply(a, b) {\n    vrati a * b;\n}\n\nfunction divide(a, b) {\n    ako (b == 0) {\n        ispiši(\"Error: Division by zero!\");\n        vrati 0;\n    } inače {\n        vrati a / b;\n    }\n}\n\nfunction square(x) {\n    vrati x * x;\n}\n\nfunction cube(x) {\n    vrati x * x * x;\n}\n\nfunction abs(x) {\n    ako (x < 0) {\n        vrati -x;\n    } inače {\n        vrati x;\n    }\n}\n\nfunction max(a, b) {\n    ako (a > b) {\n        vrati a;\n    } inače {\n        vrati b;\n    }\n}\n\nfunction min(a, b) {\n    ako (a < b) {\n        vrati a;\n    } inače {\n        vrati b;\n    }\n}\n", "control_flow": "// Hrvatski - Kontrola Toka\nvarijabla brojač = 0;\nvarijabla maksimum = 5;\n\n// Loop\ndok (brojač < maksimum) {\n    brojač = brojač + 1;\n}\n\n// Conditional\nvarijabla rezultat = 85;\n\nako (rezultat >= 90) {\n    rezultat;\n} inače {\n    ako (rezultat >= 80) {\n        rezultat;\n    } inače {\n        rezultat;\n    }\n}\n\nbrojač;", "state_machine": "// State Machine Example\nneka state = \"initial\";\n\nako (state == \"initial\") {\n    ispiši(\"Starting\");\n    state = \"running\";\n}\n\nispiši(state);\n", "conditionals": "// Hrvatski - Uvjetna logika\nneka bodovi = 85;\n\nako (bodovi >= 90) {\n    ispiši(1000);\n} inače {\n    ako (bodovi >= 80) {\n        ispiši(2000);\n    } inače {\n        ispiši(3000);\n    }\n}\n\nispiši(999);\n", "code_organization": "// Hrvatski - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable za large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// koristi \"agent/agent_definition.hudhud\";\n// koristi \"constitution/laws.hudhud\";\n// koristi \"data/note.hudhud\";\n// koristi \"utils/math.hudhud\";\n", "module_concepts": "// Hrvatski - Modules & Code Organization\n// Demonstrates module system: koristi/uvezi like Rust, Java, C++, Python\n\n// Import math module\nkoristi \"math.hudhud\";\n\n// Example syntax variations:\n// koristi \"math.hudhud\";\n// koristi { add, subtract } od \"math.hudhud\";\n// koristi \"math.hudhud\" kao math;\n\n// Using functions iz math module\nneka sum = add(10, 5);\nispiši(sum);\n\nneka diff = subtract(20, 8);\nispiši(diff);\n\nneka product = multiply(4, 7);\nispiši(product);\n\nneka quotient = divide(15, 3);\nispiši(quotient);\n\nneka squared = square(5);\nispiši(squared);\n\nneka cubed = cube(3);\nispiši(cubed);\n\nneka absolute = abs(-42);\nispiši(absolute);\n\nneka maximum = max(100, 50);\nispiši(maximum);\n\nneka minimum = min(100, 50);\nispiši(minimum);\n\n// Complex calculation using multiple functions\nneka result = add(multiply(5, 3), divide(20, 4));\nispiši(result);\n", "switch_concepts": "// Hrvatski - Switch/Case koncepti\n// switch/case/default\n\nfunkcija tip_dana(day) {\n    odaberi (day) {\n        slučaj \"Monday\":\n        slučaj \"Tuesday\":\n        slučaj \"Wednesday\":\n        slučaj \"Thursday\":\n        slučaj \"Friday\":\n            vrati \"Radni dan\";\n        slučaj \"Saturday\":\n        slučaj \"Sunday\":\n            vrati \"Vikend\";\n        podrazumijevano:\n            vrati \"Nepoznato\";\n    }\n}\n\nispiši(\"=== Day Types ===\");\nispiši(\"Monday: \" + tip_dana(\"Monday\"));\nispiši(\"Saturday: \" + tip_dana(\"Saturday\"));\nispiši(\"Holiday: \" + tip_dana(\"Holiday\"));\n\nfunkcija ocjena_slovo(score) {\n    odaberi (score) {\n        slučaj 90:\n            vrati \"A\";\n        slučaj 80:\n            vrati \"B\";\n        slučaj 70:\n            vrati \"C\";\n        slučaj 60:\n            vrati \"D\";\n        podrazumijevano:\n            vrati \"F\";\n    }\n}\n\nispiši(\"\\n=== Grades ===\");\nispiši(\"90: \" + ocjena_slovo(90));\nispiši(\"70: \" + ocjena_slovo(70));\nispiši(\"50: \" + ocjena_slovo(50));\n\nfunkcija poruka_statusa(code) {\n    odaberi (code) {\n        slučaj 200:\n            vrati \"OK\";\n        slučaj 404:\n            vrati \"Not Found\";\n        slučaj 500:\n            vrati \"Server Error\";\n        podrazumijevano:\n            vrati \"Nepoznato Status\";\n    }\n}\n\nispiši(\"\\n=== HTTP Status ===\");\nispiši(\"200: \" + poruka_statusa(200));\nispiši(\"404: \" + poruka_statusa(404));\n", "event_concepts": "// Hrvatski - Event Concepts\n\ndogađaj UserLogin {\n    ispiši(\"User logged in\");\n}\n\ndogađaj DataReceived {\n    ispiši(\"Data received\");\n}\n\ndogađaj ErrorOccurred {\n    ispiši(\"Error occurred\");\n}\n\nfunkcija on_login(username) {\n    ispiši(\"Login: \" + username);\n    vrati \"Welcome, \" + username;\n}\n\nfunkcija on_data(source) {\n    ispiši(\"Data from: \" + source);\n    vrati \"Processed: \" + source;\n}\n\nfunkcija on_error(message) {\n    ispiši(\"Error: \" + message);\n    vrati \"Handled: \" + message;\n}\n\nispiši(\"=== Event System ===\");\nneka r1 = on_login(\"admin\");\nispiši(r1);\nneka r2 = on_data(\"sensor_1\");\nispiši(r2);\nneka r3 = on_error(\"timeout\");\nispiši(r3);\n", "functions": "// Hrvatski - Funkcije\n// Primjeri definiranja i korištenja funkcija\n\n// Jednostavna funkcija\nfunkcija pozdravi() {\n    ispiši(\"Zdravo Svijete!\");\n}\n\n// Funkcija s parametrima\nfunkcija zbroji(a, b) {\n    vrati a + b;\n}\n\n// Višeparametarska funkcija\nfunkcija izračunaj(broj1, broj2, operacija) {\n    ako (operacija == \"zbroji\") {\n        vrati broj1 + broj2;\n    } inače {\n        vrati 0;\n    }\n}\n\n// Matematičke funkcije\nfunkcija kvadrat(x) {\n    vrati x * x;\n}\n\nfunkcija kub(x) {\n    vrati x * x * x;\n}\n\n// Korištenje funkcija\npozdravi();\n\nneka rezultat1 = zbroji(5, 3);\nispiši(rezultat1);\n\nneka rezultat2 = izračunaj(10, 5, \"zbroji\");\nispiši(rezultat2);\n\nneka rezultat_kvadrat = kvadrat(4);\nispiši(rezultat_kvadrat);\n\nneka rezultat_kub = kub(3);\nispiši(rezultat_kub);\n\n// Kompozicija funkcija\nneka ukupno = zbroji(kvadrat(3), kub(2));\nispiši(ukupno);\n", "entity_concepts": "// Hrvatski - Koncepti entiteta\n\nneka korisnik = {\n    id: 1,\n    ime: \"Ana\",\n    email: \"ana@primjer.com\",\n    uloga: \"programer\"\n};\n\nneka proizvod = {\n    id: 101,\n    ime: \"HudHudScript IDE\",\n    verzija: \"2.0\",\n    cijena: 49\n};\n\nneka narudžba = {\n    id: 1001,\n    korisnik_id: 1,\n    proizvod_id: 101,\n    količina: 2,\n    status: \"potvrđeno\"\n};\n\nfunkcija info_entiteta(entitet) {\n    vrati \"Entitet #\" + entitet.id + \": \" + entitet.ime;\n}\n\nfunkcija izračunaj_ukupno(narudžba, cijena) {\n    vrati narudžba.količina * cijena;\n}\n\nispiši(\"=== Sustav entiteta ===\");\nispiši(info_entiteta(korisnik));\nispiši(info_entiteta(proizvod));\nneka ukupno = izračunaj_ukupno(narudžba, proizvod.cijena);\nispiši(\"Narudžba #\" + narudžba.id + \" ukupno: \" + ukupno);\nispiši(\"Status: \" + narudžba.status);\n", "error_concepts": "// Hrvatski - Error Concepts\n\nfunkcija validate_age(age) {\n    ako (age < 0) {\n        baci \"Invalid age: negative\";\n    }\n    ako (age > 150) {\n        baci \"Invalid age: too large\";\n    }\n    vrati age;\n}\n\nfunkcija validate_email(email) {\n    ako (email == \"\") {\n        baci \"Empty email\";\n    }\n    ispiši(\"Email valid: \" + email);\n    vrati email;\n}\n\nispiši(\"=== Validation ===\");\n\npokušaj {\n    validate_age(25);\n    ispiši(\"Age 25: valid\");\n} uhvati (error) {\n    ispiši(\"Error: \" + error);\n}\n\npokušaj {\n    validate_age(-5);\n} uhvati (error) {\n    ispiši(\"Error: \" + error);\n}\n\npokušaj {\n    validate_email(\"user@example.com\");\n    validate_email(\"\");\n} uhvati (error) {\n    ispiši(\"Email error: \" + error);\n} konačno {\n    ispiši(\"Validation complete\");\n}\n"}, "id": {"objects": "// Indonesia - Objek\n// Objek dengan kata kunci asli\n\n// Buat objek\nbiar orang = {\n    nama: \"Ani\",\n    umur: 30,\n    kota: \"Jakarta\"\n};\n\n// Akses properti\nbiar nama = orang.nama;\nbiar umur = orang.umur;\n\n// Hasil\nnama;\n", "chemistry": "// ID - Chemistry Module\n\nfungsi molarMass(atoms, atomicWeight) {\n    kembali atoms * atomicWeight;\n}\n\nfungsi concentration(moles, volume) {\n    kembali moles / volume;\n}\n\nfungsi pH(hydrogenConcentration) {\n    kembali 14 - hydrogenConcentration;\n}\n\nfungsi density(mass, volume) {\n    kembali mass / volume;\n}\n\nfungsi dilution(c1, v1, v2) {\n    kembali (c1 * v1) / v2;\n}\n", "loops": "// Indonesia - Perulangan\n// Contoh perulangan dengan kata kunci asli\n\n// Perulangan sederhana - jumlah dari 1 sampai 5\nbiar jumlah = 0;\nbiar penghitung = 1;\n\nselama (penghitung <= 5) {\n    jumlah = jumlah + penghitung;\n    penghitung = penghitung + 1;\n}\n\njumlah;\n", "data_processing": "// Bahasa Indonesia - Data Processing\n// Using NATIVE Bahasa Indonesia keywords\n\nbiarkan value1 = 100;\nbiarkan value2 = 200;\nbiarkan value3 = 300;\n\nbiarkan total = value1+ value2+ value3;\nbiarkan average = total / 3;\n\ncetak(total);\ncetak(average);\n", "modules_import": "// ID - Modules Import Example\n\n// Import math module (direct access)\ngunakan \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\ngunakan \"physics.hudhud\" sebagai fizik;\n\n// Import chemistry (direct access)\ngunakan \"chemistry.hudhud\";\n\n// Using math functions (direct)\nbiarkan sum = add(10, 5);\ncetak(sum);\n\nbiarkan product = multiply(4, 7);\ncetak(product);\n\n// Using physics functions (via alias: fizik.functionName)\nbiarkan f = fizik.force(10, 9.8);\ncetak(f);\n\nbiarkan ke = fizik.kineticEnergy(5, 10);\ncetak(ke);\n\n// Using chemistry functions (direct)\nbiarkan d = density(100, 50);\ncetak(d);\n\nbiarkan c = concentration(2, 5);\ncetak(c);\n", "return_concept": "// Bahasa Indonesia - Konsep Return\n// return\n\nfungsi kuadrat(x) {\n    kembalikan x * x;\n}\n\nfungsi kubik(x) {\n    kembalikan x * x * x;\n}\n\ncetak(\"=== Math Functions ===\");\ncetak(\"kuadrat(5): \" + kuadrat(5));\ncetak(\"kubik(3): \" + kubik(3));\n\nfungsi absolut(x) {\n    jika (x < 0) {\n        kembalikan -x;\n    }\n    kembalikan x;\n}\n\ncetak(\"\\n=== Absolute ===\");\ncetak(\"absolut(-7): \" + absolut(-7));\ncetak(\"absolut(3): \" + absolut(3));\n\nfungsi buat_titik(x, y) {\n    kembalikan { x: x, y: y };\n}\n\nbiar p = buat_titik(10, 20);\ncetak(\"\\n=== Point ===\");\ncetak(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfungsi faktorial(n) {\n    jika (n <= 1) {\n        kembalikan 1;\n    }\n    kembalikan n * faktorial(n - 1);\n}\n\ncetak(\"\\n=== Factorial ===\");\ncetak(\"5! = \" + faktorial(5));\ncetak(\"10! = \" + faktorial(10));\n", "customer_service": "// Bahasa Indonesia - Agen Layanan Pelanggan\n// Menggunakan kata kunci ASLI Bahasa Indonesia\n\nbiar salam = \"Halo, bagaimana saya bisa membantu Anda?\";\nbiar tanggapan = \"Saya akan membantu permintaan Anda.\";\n\ncetak(salam);\ncetak(tanggapan);\n", "basic_example": "// Indonesia - Basic Example with NATIVE keywords\nvariabel a = 10;\nvariabel b = 20;\nvariabel jumlah = a + b;\n\ncetak(jumlah);\n", "physics": "// ID - Physics Module\n\nfungsi speed(distance, time) {\n    kembali distance / time;\n}\n\nfungsi force(mass, acceleration) {\n    kembali mass * acceleration;\n}\n\nfungsi kineticEnergy(mass, velocity) {\n    kembali 0.5 * mass * velocity * velocity;\n}\n\nfungsi potentialEnergy(mass, gravity, height) {\n    kembali mass * gravity * height;\n}\n\nfungsi momentum(mass, velocity) {\n    kembali mass * velocity;\n}\n", "error_handling": "// id - Error Handling\n// Simple error control with if-else\n\nfunction divide(a, b) {\n    if (b == 0) {\n        return { error: true, message: \"Division by zero\", value: 0 };\n    }\n    return { error: false, message: \"\", value: a / b };\n}\n\nprint(\"=== Error Handling ===\");\n\nvar result1 = divide(10, 2);\nif (result1.error) {\n    print(\"Error: \" + result1.message);\n} else {\n    print(\"10 / 2 = \" + result1.value);\n}\n\nvar result2 = divide(10, 0);\nif (result2.error) {\n    print(\"Error caught: \" + result2.message);\n} else {\n    print(\"Result: \" + result2.value);\n}\n\nprint(\"Done\");\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici paket kullanımı\ngunakan \"cebir\";\ngunakan \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\ngunakan \"cebir/matris\";\ngunakan \"cebir/vektor\";\ngunakan \"fizik/hareket\";\n\ntulis(\"============================================================\");\ntulis(\"HudHudScript Paket Sistemi Demo\");\ntulis(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\ntulis(\"📦 Cebir Paketi Kullanımı:\");\ntulis(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nvariabel matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nvariabel matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\ntulis(\"Matris 1:\");\nmatris1.goster();\n\ntulis(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nvariabel toplam = matris1.topla(matris2);\ntulis(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nvariabel vektor1 = Vektor([1, 2, 3]);\nvariabel vektor2 = Vektor([4, 5, 6]);\n\ntulis(\"\\n\\n📐 Vektör İşlemleri:\");\ntulis(\"─────────────────────────────────────────────────────────\\n\");\n\ntulis(\"Vektör 1: \" + vektor1.toString());\ntulis(\"Vektör 2: \" + vektor2.toString());\n\nvariabel noktaSal = vektor1.noktaSal(vektor2);\ntulis(\"Nokta Çarpım: \" + noktaSal);\n\nvariabel caprazCarpim = vektor1.caprazCarpim(vektor2);\ntulis(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\ntulis(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\ntulis(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nvariabel baslangicHizi = 0;      // m/s\nvariabel ivme = 9.8;              // m/s² (yerçekimi)\nvariabel zaman = 5;               // saniye\n\nvariabel sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nvariabel mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\ntulis(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\ntulis(\"İvme: \" + ivme + \" m/s²\");\ntulis(\"Zaman: \" + zaman + \" s\");\ntulis(\"─────────────────────────────────────────────────────────\");\ntulis(\"Son Hız: \" + sonHiz + \" m/s\");\ntulis(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\ntulis(\"\\n\\n📝 Paket Oluşturma:\");\ntulis(\"─────────────────────────────────────────────────────────\\n\");\n\ntulis(\"1. hudhud.toml dosyası oluşturun:\");\ntulis(\"   [package]\");\ntulis(\"   name = 'matematik-utils'\");\ntulis(\"   version = '1.0.0'\");\ntulis(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\ntulis(\"\\n2. Bağımlılıklar ekleyin:\");\ntulis(\"   [dependencies]\");\ntulis(\"   cebir = '^2.0.0'\");\ntulis(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\ntulis(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\ntulis(\"─────────────────────────────────────────────────────────\\n\");\n\ntulis(\"Paket kurma:\");\ntulis(\"  hudhudscript install cebir\");\ntulis(\"  hudhudscript install fizik@1.5.0\");\n\ntulis(\"\\nPaket güncelleme:\");\ntulis(\"  hudhudscript update cebir\");\ntulis(\"  hudhudscript update --all\");\n\ntulis(\"\\nPaket kaldırma:\");\ntulis(\"  hudhudscript remove cebir\");\n\ntulis(\"\\nKurulu paketleri listeleme:\");\ntulis(\"  hudhudscript list\");\n\ntulis(\"\\nPaket arama:\");\ntulis(\"  hudhudscript search matematik\");\n\ntulis(\"\\nPaket bilgisi:\");\ntulis(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\ntulis(\"\\n\\n🔗 Paket Bağımlılıkları:\");\ntulis(\"─────────────────────────────────────────────────────────\\n\");\n\ntulis(\"Versiyon belirtme:\");\ntulis(\"  'cebir' = '^2.0.0'    # 2.x.x\");\ntulis(\"  'fizik' = '~1.5.0'    # 1.5.x\");\ntulis(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\ntulis(\"\\nGit deposundan:\");\ntulis(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\ntulis(\"\\nYerel yoldan:\");\ntulis(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\ntulis(\"\\n\\n🔒 Paket Güvenliği:\");\ntulis(\"─────────────────────────────────────────────────────────\\n\");\n\ntulis(\"Güvenlik kontrolü:\");\ntulis(\"  hudhudscript audit\");\n\ntulis(\"\\nChecksum doğrulama:\");\ntulis(\"  hudhudscript verify cebir\");\n\ntulis(\"\\n============================================================\");\ntulis(\"✓ Paket sistemi demo tamamlandı!\");\ntulis(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\ntulis(\"============================================================\");\n", "arrays": "// Indonesia - Larik\n// Larik dengan kata kunci asli\n\n// Buat larik\nbiar angka = [1, 2, 3, 4, 5];\nbiar nama = [\"Ani\", \"Budi\", \"Citra\"];\n\n// Akses elemen\nbiar pertama = angka[0];\nbiar kedua = angka[1];\n\n// Hasil\npertama;\n", "math": "// Indonesia - Modul Matematika\n\nfungsi tambah(a, b) {\n    kembalikan a + b;\n}\n\nfungsi kurang(a, b) {\n    kembalikan a - b;\n}\n\nfungsi kali(a, b) {\n    kembalikan a * b;\n}\n\nfungsi bagi(a, b) {\n    jika (b == 0) {\n        cetak(\"Kesalahan: Pembagian dengan nol!\");\n        kembalikan 0;\n    } kalau {\n        kembalikan a / b;\n    }\n}\n\nfungsi kuadrat(x) {\n    kembalikan x * x;\n}\n\nfungsi pangkat_tiga(x) {\n    kembalikan x * x * x;\n}\n\nfungsi nilai_mutlak(x) {\n    jika (x < 0) {\n        kembalikan -x;\n    } kalau {\n        kembalikan x;\n    }\n}\n\nfungsi terbesar(a, b) {\n    jika (a > b) {\n        kembalikan a;\n    } kalau {\n        kembalikan b;\n    }\n}\n\nfungsi terkecil(a, b) {\n    jika (a < b) {\n        kembalikan a;\n    } kalau {\n        kembalikan b;\n    }\n}\n", "control_flow": "// Indonesia - Alur Kontrol\nvariabel penghitung = 0;\nvariabel maksimum = 5;\n\n// Loop\nselama (penghitung < maksimum) {\n    penghitung = penghitung + 1;\n}\n\n// Conditional\nvariabel skor = 85;\n\njika (skor >= 90) {\n    skor;\n} jika_tidak {\n    jika (skor >= 80) {\n        skor;\n    } jika_tidak {\n        skor;\n    }\n}\n\npenghitung;\n", "state_machine": "// State Machine Example\nbiarkan state = \"initial\";\n\njika (state == \"initial\") {\n    cetak(\"Starting\");\n    state = \"running\";\n}\n\ncetak(state);\n", "conditionals": "// Indonesia - Logika kondisional\nbiar nilai = 85;\n\njika (nilai >= 90) {\n    nilai;\n} kalau {\n    jika (nilai >= 80) {\n        nilai;\n    } kalau {\n        nilai;\n    }\n}\n", "code_organization": "// Bahasa Indonesia - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable untuk large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// gunakan \"agent/agent_definition.hudhud\";\n// gunakan \"constitution/laws.hudhud\";\n// gunakan \"data/note.hudhud\";\n// gunakan \"utils/math.hudhud\";\n", "module_concepts": "// Bahasa Indonesia - Modules & Code Organization\n// Demonstrates module system: gunakan/impor like Rust, Java, C++, Python\n\n// Import math module\ngunakan \"math.hudhud\";\n\n// Example syntax variations:\n// gunakan \"math.hudhud\";\n// gunakan { add, subtract } dari \"math.hudhud\";\n// gunakan \"math.hudhud\" sebagai math;\n\n// Using functions dari math module\nbiarkan sum = add(10, 5);\ncetak(sum);\n\nbiarkan diff = subtract(20, 8);\ncetak(diff);\n\nbiarkan product = multiply(4, 7);\ncetak(product);\n\nbiarkan quotient = divide(15, 3);\ncetak(quotient);\n\nbiarkan squared = square(5);\ncetak(squared);\n\nbiarkan cubed = cube(3);\ncetak(cubed);\n\nbiarkan absolute = abs(-42);\ncetak(absolute);\n\nbiarkan maximum = max(100, 50);\ncetak(maximum);\n\nbiarkan minimum = min(100, 50);\ncetak(minimum);\n\n// Complex calculation using multiple functions\nbiarkan result = add(multiply(5, 3), divide(20, 4));\ncetak(result);\n", "switch_concepts": "// id - Switch Concepts\n// Using if-else for multiple conditions\n\nfunction dayType(day) {\n    if (day == \"Monday\") { return \"Weekday\"; }\n    if (day == \"Tuesday\") { return \"Weekday\"; }\n    if (day == \"Wednesday\") { return \"Weekday\"; }\n    if (day == \"Thursday\") { return \"Weekday\"; }\n    if (day == \"Friday\") { return \"Weekday\"; }\n    if (day == \"Saturday\") { return \"Weekend\"; }\n    if (day == \"Sunday\") { return \"Weekend\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== Day Types ===\");\nprint(\"Monday: \" + dayType(\"Monday\"));\nprint(\"Saturday: \" + dayType(\"Saturday\"));\nprint(\"Holiday: \" + dayType(\"Holiday\"));\n\nfunction statusMessage(code) {\n    if (code == 200) { return \"OK\"; }\n    if (code == 404) { return \"Not Found\"; }\n    if (code == 500) { return \"Server Error\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== HTTP Status ===\");\nprint(\"200: \" + statusMessage(200));\nprint(\"404: \" + statusMessage(404));\n", "event_concepts": "// Bahasa Indonesia - Event Concepts\n\nacara UserLogin {\n    cetak(\"User logged in\");\n}\n\nacara DataReceived {\n    cetak(\"Data received\");\n}\n\nacara ErrorOccurred {\n    cetak(\"Error occurred\");\n}\n\nfungsi on_login(username) {\n    cetak(\"Login: \" + username);\n    kembalikan \"Welcome, \" + username;\n}\n\nfungsi on_data(source) {\n    cetak(\"Data from: \" + source);\n    kembalikan \"Processed: \" + source;\n}\n\nfungsi on_error(message) {\n    cetak(\"Error: \" + message);\n    kembalikan \"Handled: \" + message;\n}\n\ncetak(\"=== Event System ===\");\nbiar r1 = on_login(\"admin\");\ncetak(r1);\nbiar r2 = on_data(\"sensor_1\");\ncetak(r2);\nbiar r3 = on_error(\"timeout\");\ncetak(r3);\n", "functions": "// Indonesia - Fungsi\n// Contoh definisi dan penggunaan fungsi\n\n// Fungsi sederhana\nfungsi sambut() {\n    cetak(\"Halo Dunia!\");\n}\n\n// Fungsi dengan parameter\nfungsi tambah(a, b) {\n    kembalikan a + b;\n}\n\n// Fungsi multi-parameter\nfungsi hitung(angka1, angka2, operasi) {\n    jika (operasi == \"tambah\") {\n        kembalikan angka1 + angka2;\n    } kalau (operasi == \"kurang\") {\n        kembalikan angka1 - angka2;\n    } kalau (operasi == \"kali\") {\n        kembalikan angka1 * angka2;\n    } kalau (operasi == \"bagi\") {\n        kembalikan angka1 / angka2;\n    }\n}\n\n// Fungsi matematika\nfungsi kuadrat(x) {\n    kembalikan x * x;\n}\n\nfungsi pangkat_tiga(x) {\n    kembalikan x * x * x;\n}\n\n// Menggunakan fungsi\nsambut();\n\nbiar hasil1 = tambah(5, 3);\ncetak(hasil1);\n\nbiar hasil2 = hitung(10, 5, \"tambah\");\ncetak(hasil2);\n\nbiar hasil3 = hitung(10, 5, \"kali\");\ncetak(hasil3);\n\nbiar hasil_kuadrat = kuadrat(4);\ncetak(hasil_kuadrat);\n\nbiar hasil_pangkat = pangkat_tiga(3);\ncetak(hasil_pangkat);\n\n// Komposisi fungsi\nbiar total = tambah(kuadrat(3), pangkat_tiga(2));\ncetak(total);\n", "entity_concepts": "// Bahasa Indonesia - Konsep Entitas\n\nbiar pengguna = {\n    id: 1,\n    nama: \"Ani\",\n    email: \"ani@contoh.com\",\n    peran: \"pengembang\"\n};\n\nbiar produk = {\n    id: 101,\n    nama: \"HudHudScript IDE\",\n    versi: \"2.0\",\n    harga: 49\n};\n\nbiar pesanan = {\n    id: 1001,\n    id_pengguna: 1,\n    id_produk: 101,\n    jumlah: 2,\n    status: \"dikonfirmasi\"\n};\n\nfungsi info_entitas(entitas) {\n    kembalikan \"Entitas #\" + entitas.id + \": \" + entitas.nama;\n}\n\nfungsi hitung_total(pesanan, harga) {\n    kembalikan pesanan.jumlah * harga;\n}\n\ncetak(\"=== Sistem Entitas ===\");\ncetak(info_entitas(pengguna));\ncetak(info_entitas(produk));\nbiar total = hitung_total(pesanan, produk.harga);\ncetak(\"Pesanan #\" + pesanan.id + \" total: \" + total);\ncetak(\"Status: \" + pesanan.status);\n", "error_concepts": "// id - Error Concepts\n// Simple validation functions\n\nfunction validateAge(age) {\n    if (age < 0) {\n        return { valid: false, error: \"Invalid age: negative\" };\n    }\n    if (age > 150) {\n        return { valid: false, error: \"Invalid age: too large\" };\n    }\n    return { valid: true, age: age };\n}\n\nfunction validateEmail(email) {\n    if (email == \"\") {\n        return { valid: false, error: \"Empty email\" };\n    }\n    return { valid: true, email: email };\n}\n\nprint(\"=== Validation ===\");\n\nvar ageResult1 = validateAge(25);\nif (ageResult1.valid) {\n    print(\"Age 25 is valid\");\n} else {\n    print(\"Error: \" + ageResult1.error);\n}\n\nvar ageResult2 = validateAge(-5);\nif (ageResult2.valid) {\n    print(\"Age is valid\");\n} else {\n    print(\"Error: \" + ageResult2.error);\n}\n\nvar emailResult = validateEmail(\"user@example.com\");\nif (emailResult.valid) {\n    print(\"Email valid: \" + emailResult.email);\n} else {\n    print(\"Email error: \" + emailResult.error);\n}\n\nprint(\"Validation complete\");\n"}, "it": {"objects": "// Italiano - Oggetti\n// Oggetti con parole chiave native\n\n// Creare oggetto\nsia persona = {\n    nome: \"Alice\",\n    età: 30,\n    città: \"Roma\"\n};\n\n// Accedere alle proprietà\nsia nome = persona.nome;\nsia età = persona.età;\n\n// Risultato\nnome;\n", "chemistry": "// Italiano - Modulo di chimica\n\nfunzione massa_molare(atomi, peso_atomico) {\n    ritorna atomi * peso_atomico;\n}\n\nfunzione concentrazione(moli, volume) {\n    ritorna moli / volume;\n}\n\nfunzione pH(concentrazione_idrogeno) {\n    ritorna 14 - concentrazione_idrogeno;\n}\n\nfunzione densità(massa, volume) {\n    ritorna massa / volume;\n}\n\nfunzione diluizione(c1, v1, v2) {\n    ritorna (c1 * v1) / v2;\n}\n", "loops": "// Italiano - Esempio di ciclo\nsia contatore = 0;\nsia massimo = 5;\n\nmentre (contatore < massimo) {\n    stampa(contatore);\n    contatore = contatore + 1;\n}\n\nstampa(999);\n", "data_processing": "// Italiano - Data Processing\n// Using NATIVE Italiano keywords\n\nvariabile value1 = 100;\nvariabile value2 = 200;\nvariabile value3 = 300;\n\nvariabile total = value1+ value2+ value3;\nvariabile average = total / 3;\n\nstampare(total);\nstampare(average);\n", "modules_import": "// IT - Modules Import Example\n\n// Import math module (direct access)\nuse \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nuse \"physics.hudhud\" as fizik;\n\n// Import chemistry (direct access)\nuse \"chemistry.hudhud\";\n\n// Using math functions (direct)\nvariabile sum = add(10, 5);\nstampa(sum);\n\nvariabile product = multiply(4, 7);\nstampa(product);\n\n// Using physics functions (via alias: fizik.functionName)\nvariabile f = fizik.force(10, 9.8);\nstampa(f);\n\nvariabile ke = fizik.kineticEnergy(5, 10);\nstampa(ke);\n\n// Using chemistry functions (direct)\nvariabile d = density(100, 50);\nstampa(d);\n\nvariabile c = concentration(2, 5);\nstampa(c);\n", "return_concept": "// Italiano - Concetto di Ritorno\n// return\n\nfunzione quadrato(x) {\n    ritorna x * x;\n}\n\nfunzione cubo(x) {\n    ritorna x * x * x;\n}\n\nstampa(\"=== Math Functions ===\");\nstampa(\"quadrato(5): \" + quadrato(5));\nstampa(\"cubo(3): \" + cubo(3));\n\nfunzione assoluto(x) {\n    se (x < 0) {\n        ritorna -x;\n    }\n    ritorna x;\n}\n\nstampa(\"\\n=== Absolute ===\");\nstampa(\"assoluto(-7): \" + assoluto(-7));\nstampa(\"assoluto(3): \" + assoluto(3));\n\nfunzione crea_punto(x, y) {\n    ritorna { x: x, y: y };\n}\n\nsia p = crea_punto(10, 20);\nstampa(\"\\n=== Point ===\");\nstampa(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfunzione fattoriale(n) {\n    se (n <= 1) {\n        ritorna 1;\n    }\n    ritorna n * fattoriale(n - 1);\n}\n\nstampa(\"\\n=== Factorial ===\");\nstampa(\"5! = \" + fattoriale(5));\nstampa(\"10! = \" + fattoriale(10));\n", "customer_service": "// Italiano - Agente di Servizio Clienti\n// Usando parole chiave NATIVE dell'Italiano\n\nsia saluto = \"Ciao, come posso aiutarti?\";\nsia risposta = \"Ti aiuterò con la tua richiesta.\";\n\nstampa(saluto);\nstampa(risposta);\n", "basic_example": "// Italiano - Basic Example with NATIVE keywords\nvariabile a = 10;\nvariabile b = 20;\nvariabile somma = a + b;\n\nstampare(somma);\n", "physics": "// Italiano - Modulo di fisica\n\nfunzione velocità(distanza, tempo) {\n    ritorna distanza / tempo;\n}\n\nfunzione forza(massa, accelerazione) {\n    ritorna massa * accelerazione;\n}\n\nfunzione energia_cinetica(massa, velocità) {\n    ritorna 0.5 * massa * velocità * velocità;\n}\n\nfunzione energia_potenziale(massa, gravità, altezza) {\n    ritorna massa * gravità * altezza;\n}\n\nfunzione quantità_moto(massa, velocità) {\n    ritorna massa * velocità;\n}\n", "error_handling": "// it - Error Handling\n// Simple error control with if-else\n\nfunction divide(a, b) {\n    if (b == 0) {\n        return { error: true, message: \"Division by zero\", value: 0 };\n    }\n    return { error: false, message: \"\", value: a / b };\n}\n\nprint(\"=== Error Handling ===\");\n\nvar result1 = divide(10, 2);\nif (result1.error) {\n    print(\"Error: \" + result1.message);\n} else {\n    print(\"10 / 2 = \" + result1.value);\n}\n\nvar result2 = divide(10, 0);\nif (result2.error) {\n    print(\"Error caught: \" + result2.message);\n} else {\n    print(\"Result: \" + result2.value);\n}\n\nprint(\"Done\");\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici pacchetto kullanımı\nuse \"cebir\";\nuse \"fizik\" as pacchetto;\n\n// Paket içinden belirli modülleri içe aktarma\nuse \"cebir/matris\";\nuse \"cebir/vektor\";\nuse \"fizik/hareket\";\n\nscrivi(\"============================================================\");\nscrivi(\"HudHudScript Paket Sistemi Demo\");\nscrivi(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nscrivi(\"📦 Cebir Paketi Kullanımı:\");\nscrivi(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nvariabile matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nvariabile matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nscrivi(\"Matris 1:\");\nmatris1.goster();\n\nscrivi(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nvariabile toplam = matris1.topla(matris2);\nscrivi(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nvariabile vektor1 = Vektor([1, 2, 3]);\nvariabile vektor2 = Vektor([4, 5, 6]);\n\nscrivi(\"\\n\\n📐 Vektör İşlemleri:\");\nscrivi(\"─────────────────────────────────────────────────────────\\n\");\n\nscrivi(\"Vektör 1: \" + vektor1.toString());\nscrivi(\"Vektör 2: \" + vektor2.toString());\n\nvariabile noktaSal = vektor1.noktaSal(vektor2);\nscrivi(\"Nokta Çarpım: \" + noktaSal);\n\nvariabile caprazCarpim = vektor1.caprazCarpim(vektor2);\nscrivi(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nscrivi(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nscrivi(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nvariabile baslangicHizi = 0;      // m/s\nvariabile ivme = 9.8;              // m/s² (yerçekimi)\nvariabile zaman = 5;               // saniye\n\nvariabile sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nvariabile mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nscrivi(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nscrivi(\"İvme: \" + ivme + \" m/s²\");\nscrivi(\"Zaman: \" + zaman + \" s\");\nscrivi(\"─────────────────────────────────────────────────────────\");\nscrivi(\"Son Hız: \" + sonHiz + \" m/s\");\nscrivi(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nscrivi(\"\\n\\n📝 Paket Oluşturma:\");\nscrivi(\"─────────────────────────────────────────────────────────\\n\");\n\nscrivi(\"1. hudhud.toml dosyası oluşturun:\");\nscrivi(\"   [package]\");\nscrivi(\"   name = 'matematik-utils'\");\nscrivi(\"   version = '1.0.0'\");\nscrivi(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nscrivi(\"\\n2. Bağımlılıklar ekleyin:\");\nscrivi(\"   [dependencies]\");\nscrivi(\"   cebir = '^2.0.0'\");\nscrivi(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nscrivi(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nscrivi(\"─────────────────────────────────────────────────────────\\n\");\n\nscrivi(\"Paket kurma:\");\nscrivi(\"  hudhudscript install cebir\");\nscrivi(\"  hudhudscript install fizik@1.5.0\");\n\nscrivi(\"\\nPaket güncelleme:\");\nscrivi(\"  hudhudscript update cebir\");\nscrivi(\"  hudhudscript update --all\");\n\nscrivi(\"\\nPaket kaldırma:\");\nscrivi(\"  hudhudscript remove cebir\");\n\nscrivi(\"\\nKurulu paketleri listeleme:\");\nscrivi(\"  hudhudscript list\");\n\nscrivi(\"\\nPaket arama:\");\nscrivi(\"  hudhudscript search matematik\");\n\nscrivi(\"\\nPaket bilgisi:\");\nscrivi(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nscrivi(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nscrivi(\"─────────────────────────────────────────────────────────\\n\");\n\nscrivi(\"Versiyon belirtme:\");\nscrivi(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nscrivi(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nscrivi(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nscrivi(\"\\nGit deposundan:\");\nscrivi(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nscrivi(\"\\nYerel yoldan:\");\nscrivi(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nscrivi(\"\\n\\n🔒 Paket Güvenliği:\");\nscrivi(\"─────────────────────────────────────────────────────────\\n\");\n\nscrivi(\"Güvenlik kontrolü:\");\nscrivi(\"  hudhudscript audit\");\n\nscrivi(\"\\nChecksum doğrulama:\");\nscrivi(\"  hudhudscript verify cebir\");\n\nscrivi(\"\\n============================================================\");\nscrivi(\"✓ Paket sistemi demo tamamlandı!\");\nscrivi(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nscrivi(\"============================================================\");\n", "arrays": "// Italiano - Array\n// Array con parole chiave native\n\n// Creare array\nsia numeri = [1, 2, 3, 4, 5];\nsia nomi = [\"Alice\", \"Bruno\", \"Carlo\"];\n\n// Accedere agli elementi\nsia primo = numeri[0];\nsia secondo = numeri[1];\n\n// Risultato\nprimo;\n", "math": "// Italiano - Modulo di matematica\n\nfunzione somma(a, b) {\n    ritorna a + b;\n}\n\nfunzione sottrai(a, b) {\n    ritorna a - b;\n}\n\nfunzione moltiplica(a, b) {\n    ritorna a * b;\n}\n\nfunzione dividi(a, b) {\n    se (b == 0) {\n        stampa(\"Errore: Divisione per zero!\");\n        ritorna 0;\n    } altrimenti {\n        ritorna a / b;\n    }\n}\n\nfunzione quadrato(x) {\n    ritorna x * x;\n}\n\nfunzione cubo(x) {\n    ritorna x * x * x;\n}\n\nfunzione valore_assoluto(x) {\n    se (x < 0) {\n        ritorna -x;\n    } altrimenti {\n        ritorna x;\n    }\n}\n\nfunzione massimo(a, b) {\n    se (a > b) {\n        ritorna a;\n    } altrimenti {\n        ritorna b;\n    }\n}\n\nfunzione minimo(a, b) {\n    se (a < b) {\n        ritorna a;\n    } altrimenti {\n        ritorna b;\n    }\n}\n", "control_flow": "// Italiano - Flusso di Controllo\nvariabile contatore = 0;\nvariabile massimo = 5;\n\n// Loop\nmentre (contatore < massimo) {\n    contatore = contatore + 1;\n}\n\n// Conditional\nvariabile punteggio = 85;\n\nse (punteggio >= 90) {\n    punteggio;\n} altrimenti {\n    se (punteggio >= 80) {\n        punteggio;\n    } altrimenti {\n        punteggio;\n    }\n}\n\ncontatore;\n", "state_machine": "// State Machine Example\nvariabile state = \"initial\";\n\nse (state == \"initial\") {\n    stampa(\"Starting\");\n    state = \"running\";\n}\n\nstampa(state);\n", "conditionals": "// Italiano - Logica condizionale\nsia punteggio = 85;\n\nse (punteggio >= 90) {\n    stampa(1000);\n} altrimenti {\n    se (punteggio >= 80) {\n        stampa(2000);\n    } altrimenti {\n        stampa(3000);\n    }\n}\n\nstampa(999);\n", "code_organization": "// Italiano - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable per large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// usare \"agent/agent_definition.hudhud\";\n// usare \"constitution/laws.hudhud\";\n// usare \"data/note.hudhud\";\n// usare \"utils/math.hudhud\";\n", "module_concepts": "// Italiano - Modules & Code Organization\n// Demonstrates module system: use/import like Rust, Java, C++, Python\n\n// Import math module\nuse \"math.hudhud\";\n\n// Example syntax variations:\n// use \"math.hudhud\";\n// use { add, subtract } from \"math.hudhud\";\n// use \"math.hudhud\" as math;\n\n// Using functions from math module\nvariabile sum = add(10, 5);\nstampa(sum);\n\nvariabile diff = subtract(20, 8);\nstampa(diff);\n\nvariabile product = multiply(4, 7);\nstampa(product);\n\nvariabile quotient = divide(15, 3);\nstampa(quotient);\n\nvariabile squared = square(5);\nstampa(squared);\n\nvariabile cubed = cube(3);\nstampa(cubed);\n\nvariabile absolute = abs(-42);\nstampa(absolute);\n\nvariabile maximum = max(100, 50);\nstampa(maximum);\n\nvariabile minimum = min(100, 50);\nstampa(minimum);\n\n// Complex calculation using multiple functions\nvariabile result = add(multiply(5, 3), divide(20, 4));\nstampa(result);\n", "switch_concepts": "// it - Switch Concepts\n// Using if-else for multiple conditions\n\nfunction dayType(day) {\n    if (day == \"Monday\") { return \"Weekday\"; }\n    if (day == \"Tuesday\") { return \"Weekday\"; }\n    if (day == \"Wednesday\") { return \"Weekday\"; }\n    if (day == \"Thursday\") { return \"Weekday\"; }\n    if (day == \"Friday\") { return \"Weekday\"; }\n    if (day == \"Saturday\") { return \"Weekend\"; }\n    if (day == \"Sunday\") { return \"Weekend\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== Day Types ===\");\nprint(\"Monday: \" + dayType(\"Monday\"));\nprint(\"Saturday: \" + dayType(\"Saturday\"));\nprint(\"Holiday: \" + dayType(\"Holiday\"));\n\nfunction statusMessage(code) {\n    if (code == 200) { return \"OK\"; }\n    if (code == 404) { return \"Not Found\"; }\n    if (code == 500) { return \"Server Error\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== HTTP Status ===\");\nprint(\"200: \" + statusMessage(200));\nprint(\"404: \" + statusMessage(404));\n", "event_concepts": "// Italiano - Event Concepts\n\nevento UserLogin {\n    stampa(\"User logged in\");\n}\n\nevento DataReceived {\n    stampa(\"Data received\");\n}\n\nevento ErrorOccurred {\n    stampa(\"Error occurred\");\n}\n\nfunzione on_login(username) {\n    stampa(\"Login: \" + username);\n    ritorna \"Welcome, \" + username;\n}\n\nfunzione on_data(source) {\n    stampa(\"Data from: \" + source);\n    ritorna \"Processed: \" + source;\n}\n\nfunzione on_error(message) {\n    stampa(\"Error: \" + message);\n    ritorna \"Handled: \" + message;\n}\n\nstampa(\"=== Event System ===\");\nsia r1 = on_login(\"admin\");\nstampa(r1);\nsia r2 = on_data(\"sensor_1\");\nstampa(r2);\nsia r3 = on_error(\"timeout\");\nstampa(r3);\n", "functions": "// Italiano - Funzioni\n// Esempi di definizione e uso di funzioni\n\n// Funzione semplice\nfunzione saluta() {\n    stampa(\"Ciao Mondo!\");\n}\n\n// Funzione con parametri\nfunzione somma(a, b) {\n    ritorna a + b;\n}\n\n// Funzione con più parametri\nfunzione calcola(num1, num2, operazione) {\n    se (operazione == \"somma\") {\n        ritorna num1 + num2;\n    } altrimenti {\n        se (operazione == \"sottrai\") {\n            ritorna num1 - num2;\n        } altrimenti {\n            se (operazione == \"moltiplica\") {\n                ritorna num1 * num2;\n            } altrimenti {\n                se (operazione == \"dividi\") {\n                    ritorna num1 / num2;\n                } altrimenti {\n                    ritorna 0;\n                }\n            }\n        }\n    }\n}\n\n// Funzioni matematiche\nfunzione quadrato(x) {\n    ritorna x * x;\n}\n\nfunzione cubo(x) {\n    ritorna x * x * x;\n}\n\n// Uso delle funzioni\nsaluta();\n\nsia risultato1 = somma(5, 3);\nstampa(risultato1);\n\nsia risultato2 = calcola(10, 5, \"somma\");\nstampa(risultato2);\n\nsia risultato3 = calcola(10, 5, \"moltiplica\");\nstampa(risultato3);\n\nsia risultato_quadrato = quadrato(4);\nstampa(risultato_quadrato);\n\nsia risultato_cubo = cubo(3);\nstampa(risultato_cubo);\n\n// Composizione di funzioni\nsia totale = somma(quadrato(3), cubo(2));\nstampa(totale);\n", "entity_concepts": "// Italiano - Concetti di Entità\n\nsia utente = {\n    id: 1,\n    nome: \"Alice\",\n    email: \"alice@esempio.com\",\n    ruolo: \"sviluppatore\"\n};\n\nsia prodotto = {\n    id: 101,\n    nome: \"HudHudScript IDE\",\n    versione: \"2.0\",\n    prezzo: 49\n};\n\nsia ordine = {\n    id: 1001,\n    id_utente: 1,\n    id_prodotto: 101,\n    quantità: 2,\n    stato: \"confermato\"\n};\n\nfunzione info_entità(entità) {\n    ritorna \"Entità #\" + entità.id + \": \" + entità.nome;\n}\n\nfunzione calcola_totale(ordine, prezzo) {\n    ritorna ordine.quantità * prezzo;\n}\n\nstampa(\"=== Sistema di Entità ===\");\nstampa(info_entità(utente));\nstampa(info_entità(prodotto));\nsia totale = calcola_totale(ordine, prodotto.prezzo);\nstampa(\"Ordine #\" + ordine.id + \" totale: \" + totale);\nstampa(\"Stato: \" + ordine.stato);\n", "error_concepts": "// it - Error Concepts\n// Simple validation functions\n\nfunction validateAge(age) {\n    if (age < 0) {\n        return { valid: false, error: \"Invalid age: negative\" };\n    }\n    if (age > 150) {\n        return { valid: false, error: \"Invalid age: too large\" };\n    }\n    return { valid: true, age: age };\n}\n\nfunction validateEmail(email) {\n    if (email == \"\") {\n        return { valid: false, error: \"Empty email\" };\n    }\n    return { valid: true, email: email };\n}\n\nprint(\"=== Validation ===\");\n\nvar ageResult1 = validateAge(25);\nif (ageResult1.valid) {\n    print(\"Age 25 is valid\");\n} else {\n    print(\"Error: \" + ageResult1.error);\n}\n\nvar ageResult2 = validateAge(-5);\nif (ageResult2.valid) {\n    print(\"Age is valid\");\n} else {\n    print(\"Error: \" + ageResult2.error);\n}\n\nvar emailResult = validateEmail(\"user@example.com\");\nif (emailResult.valid) {\n    print(\"Email valid: \" + emailResult.email);\n} else {\n    print(\"Email error: \" + emailResult.error);\n}\n\nprint(\"Validation complete\");\n"}, "ku": {"objects": "// Kurdi - Objects\n// Objects with native keywords\n\n// Create object\nguherbar mirov = {\n    nave: \"Ehmed\",\n    temen: 30,\n    bajar: \"Hewler\"\n};\n\n// Access properties\nguherbar nave = mirov.nave;\nguherbar temen = mirov.temen;\n\n// Result\nnave;\n", "chemistry": "// Kurdi - Modula Kimyaye\n\nfonksiyon giraniya_molar(atom, giraniya_atomi) {\n    vegerine atom * giraniya_atomi;\n}\n\nfonksiyon derbazin(mol, hecm) {\n    vegerine mol / hecm;\n}\n\nfonksiyon asidi(derbazina_hidrojen) {\n    vegerine 14 - derbazina_hidrojen;\n}\n\nfonksiyon girani(giran, hecm) {\n    vegerine giran / hecm;\n}\n\nfonksiyon zelalkirin(d1, h1, h2) {\n    vegerine (d1 * h1) / h2;\n}\n", "loops": "// Kurdi - Lup\n// Minaken lupe bi peyven esli\n\n// Lupa sade - berhevok ji 1 heta 5\nbila berhevok = 0;\nbila jimarvan = 1;\n\ndema (jimarvan <= 5) {\n    berhevok = berhevok + jimarvan;\n    jimarvan = jimarvan + 1;\n}\n\nberhevok;\n", "data_processing": "// Kurdi - Data Processing\n// Using NATIVE Kurdi keywords\n\nbila value1 = 100;\nbila value2 = 200;\nbila value3 = 300;\n\nbila total = value1+ value2+ value3;\nbila average = total / 3;\n\nçap_bike(total);\nçap_bike(average);\n", "modules_import": "// KU - Modules Import Example\n\n// Import math module (direct access)\nbikar_bine \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nbikar_bine \"physics.hudhud\" wek fizik;\n\n// Import chemistry (direct access)\nbikar_bine \"chemistry.hudhud\";\n\n// Using math functions (direct)\nbila sum = add(10, 5);\nçap_bike(sum);\n\nbila product = multiply(4, 7);\nçap_bike(product);\n\n// Using physics functions (via alias: fizik.functionName)\nbila f = fizik.force(10, 9.8);\nçap_bike(f);\n\nbila ke = fizik.kineticEnergy(5, 10);\nçap_bike(ke);\n\n// Using chemistry functions (direct)\nbila d = density(100, 50);\nçap_bike(d);\n\nbila c = concentration(2, 5);\nçap_bike(c);\n", "return_concept": "// Kurdi - Tegeha Vegerine\n// return\n\nfonksiyon çargoşe(x) {\n    vegerine x * x;\n}\n\nfonksiyon kub(x) {\n    vegerine x * x * x;\n}\n\nçap_bike(\"=== Math Functions ===\");\nçap_bike(\"çargoşe(5): \" + çargoşe(5));\nçap_bike(\"kub(3): \" + kub(3));\n\nfonksiyon mutleq(x) {\n    eger (x < 0) {\n        vegerine -x;\n    }\n    vegerine x;\n}\n\nçap_bike(\"\\n=== Absolute ===\");\nçap_bike(\"mutleq(-7): \" + mutleq(-7));\nçap_bike(\"mutleq(3): \" + mutleq(3));\n\nfonksiyon xal_biafirine(x, y) {\n    vegerine { x: x, y: y };\n}\n\nbila p = xal_biafirine(10, 20);\nçap_bike(\"\\n=== Point ===\");\nçap_bike(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfonksiyon faktoriyel(n) {\n    eger (n <= 1) {\n        vegerine 1;\n    }\n    vegerine n * faktoriyel(n - 1);\n}\n\nçap_bike(\"\\n=== Factorial ===\");\nçap_bike(\"5! = \" + faktoriyel(5));\nçap_bike(\"10! = \" + faktoriyel(10));\n", "customer_service": "// Kurdi - Ajansa Xizmeta Xeridar\n// Bi karanina peyv bejeyen XWECIHI yen Kurdi\n\nbila silav = \"Silav, ez çawa dikarim alikariya we bikim?\";\nbila bersiv = \"Ez e daxwaza we bi cih binim.\";\n\nçap_bike(silav);\nçap_bike(bersiv);\n", "basic_example": "// Kurdi - Basic Example with NATIVE keywords\nguherbar yek = 10;\nguherbar du = 20;\nguherbar kom = yek + du;\n\nçap_bike(kom);\n", "physics": "// Kurdi - Modula Fizike\n\nfonksiyon lez(mesafe, dem) {\n    vegerine mesafe / dem;\n}\n\nfonksiyon hez(giran, bilezi) {\n    vegerine giran * bilezi;\n}\n\nfonksiyon enerjiya_kinetik(giran, lez) {\n    vegerine 0.5 * giran * lez * lez;\n}\n\nfonksiyon enerjiya_potansiyel(giran, gravite, bilindahi) {\n    vegerine giran * gravite * bilindahi;\n}\n\nfonksiyon moment(giran, lez) {\n    vegerine giran * lez;\n}\n", "error_handling": "// Kurdi - Reveberiya xeletiyan\n// try/catch/finally, throw\n\n// Basic try/catch\nfonksiyon parve(a, b) {\n    eger (b == 0) {\n        baveje \"Xeletiya dabeşkirina bi sifire\";\n    }\n    vegerine a / b;\n}\n\nbiceribine {\n    bila result = parve(10, 2);\n    çap_bike(\"10 / 2 = \" + result);\n} bigire (error) {\n    çap_bike(\"Xeleti: \" + error);\n}\n\n// Try/catch/finally\nçap_bike(\"\n=== Pevajokirina pele ===\");\n\nfonksiyon pele_bişopine(filename) {\n    eger (filename == \"\") {\n        baveje \"Xeletiya nave pele vala\";\n    }\n    çap_bike(\"Pevajokirin: \" + filename);\n    vegerine \"Dane ji \" + filename;\n}\n\nbiceribine {\n    bila data = pele_bişopine(\"report.txt\");\n    çap_bike(\"Encam: \" + data);\n} bigire (error) {\n    çap_bike(\"Xeleti: \" + error);\n} di_dawiye {\n    çap_bike(\"Paqijkirin temam\");\n}\n\n// Nested error handling\nçap_bike(\"\n=== Reveberiya xeletiyan a hundurin ===\");\n\nbiceribine {\n    çap_bike(\"Bloka biceribine ya derve\");\n    biceribine {\n        baveje \"Xeletiya hundurin\";\n    } bigire (inner_err) {\n        çap_bike(\"Hundurin hat girtin: \" + inner_err);\n        baveje \"Xeletiya ji nu ve aveti\";\n    }\n} bigire (outer_err) {\n    çap_bike(\"Derve hat girtin: \" + outer_err);\n} di_dawiye {\n    çap_bike(\"Hemu qediya\");\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici پاکێج kullanımı\nbikar_bine \"cebir\";\nbikar_bine \"fizik\" wek پاکێج;\n\n// Paket içinden belirli modülleri içe aktarma\nbikar_bine \"cebir/matris\";\nbikar_bine \"cebir/vektor\";\nbikar_bine \"fizik/hareket\";\n\nبنووسە(\"============================================================\");\nبنووسە(\"HudHudScript Paket Sistemi Demo\");\nبنووسە(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nبنووسە(\"📦 Cebir Paketi Kullanımı:\");\nبنووسە(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nbila matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nbila matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nبنووسە(\"Matris 1:\");\nmatris1.goster();\n\nبنووسە(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nbila toplam = matris1.topla(matris2);\nبنووسە(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nbila vektor1 = Vektor([1, 2, 3]);\nbila vektor2 = Vektor([4, 5, 6]);\n\nبنووسە(\"\\n\\n📐 Vektör İşlemleri:\");\nبنووسە(\"─────────────────────────────────────────────────────────\\n\");\n\nبنووسە(\"Vektör 1: \" + vektor1.toString());\nبنووسە(\"Vektör 2: \" + vektor2.toString());\n\nbila noktaSal = vektor1.noktaSal(vektor2);\nبنووسە(\"Nokta Çarpım: \" + noktaSal);\n\nbila caprazCarpim = vektor1.caprazCarpim(vektor2);\nبنووسە(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nبنووسە(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nبنووسە(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nbila baslangicHizi = 0;      // m/s\nbila ivme = 9.8;              // m/s² (yerçekimi)\nbila zaman = 5;               // saniye\n\nbila sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nbila mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nبنووسە(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nبنووسە(\"İvme: \" + ivme + \" m/s²\");\nبنووسە(\"Zaman: \" + zaman + \" s\");\nبنووسە(\"─────────────────────────────────────────────────────────\");\nبنووسە(\"Son Hız: \" + sonHiz + \" m/s\");\nبنووسە(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nبنووسە(\"\\n\\n📝 Paket Oluşturma:\");\nبنووسە(\"─────────────────────────────────────────────────────────\\n\");\n\nبنووسە(\"1. hudhud.toml dosyası oluşturun:\");\nبنووسە(\"   [package]\");\nبنووسە(\"   name = 'matematik-utils'\");\nبنووسە(\"   version = '1.0.0'\");\nبنووسە(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nبنووسە(\"\\n2. Bağımlılıklar ekleyin:\");\nبنووسە(\"   [dependencies]\");\nبنووسە(\"   cebir = '^2.0.0'\");\nبنووسە(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nبنووسە(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nبنووسە(\"─────────────────────────────────────────────────────────\\n\");\n\nبنووسە(\"Paket kurma:\");\nبنووسە(\"  hudhudscript install cebir\");\nبنووسە(\"  hudhudscript install fizik@1.5.0\");\n\nبنووسە(\"\\nPaket güncelleme:\");\nبنووسە(\"  hudhudscript update cebir\");\nبنووسە(\"  hudhudscript update --all\");\n\nبنووسە(\"\\nPaket kaldırma:\");\nبنووسە(\"  hudhudscript remove cebir\");\n\nبنووسە(\"\\nKurulu paketleri listeleme:\");\nبنووسە(\"  hudhudscript list\");\n\nبنووسە(\"\\nPaket arama:\");\nبنووسە(\"  hudhudscript search matematik\");\n\nبنووسە(\"\\nPaket bilgisi:\");\nبنووسە(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nبنووسە(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nبنووسە(\"─────────────────────────────────────────────────────────\\n\");\n\nبنووسە(\"Versiyon belirtme:\");\nبنووسە(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nبنووسە(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nبنووسە(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nبنووسە(\"\\nGit deposundan:\");\nبنووسە(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nبنووسە(\"\\nYerel yoldan:\");\nبنووسە(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nبنووسە(\"\\n\\n🔒 Paket Güvenliği:\");\nبنووسە(\"─────────────────────────────────────────────────────────\\n\");\n\nبنووسە(\"Güvenlik kontrolü:\");\nبنووسە(\"  hudhudscript audit\");\n\nبنووسە(\"\\nChecksum doğrulama:\");\nبنووسە(\"  hudhudscript verify cebir\");\n\nبنووسە(\"\\n============================================================\");\nبنووسە(\"✓ Paket sistemi demo tamamlandı!\");\nبنووسە(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nبنووسە(\"============================================================\");\n", "arrays": "// Kurdi - Arrays\n// Arrays with native keywords\n\n// Create arrays\nguherbar jimarekan = [1, 2, 3, 4, 5];\nguherbar navan = [\"Ehmed\", \"Fatma\", \"Hesen\"];\n\n// Access elements\nguherbar yekem = jimarekan[0];\nguherbar duyem = jimarekan[1];\n\n// Result\nyekem;\n", "math": "// Kurdi - Modula Matematike\n\nfonksiyon zede_bike(a, b) {\n    vegerine a + b;\n}\n\nfonksiyon je_bike(a, b) {\n    vegerine a - b;\n}\n\nfonksiyon zede_bike_car(a, b) {\n    vegerine a * b;\n}\n\nfonksiyon dabeş_bike(a, b) {\n    eger (b == 0) {\n        çap_bike(\"Çewti: Dabeşkirina bi sifire!\");\n        vegerine 0;\n    } wella {\n        vegerine a / b;\n    }\n}\n\nfonksiyon çargoşe(x) {\n    vegerine x * x;\n}\n\nfonksiyon kup(x) {\n    vegerine x * x * x;\n}\n\nfonksiyon nirxa_mutleq(x) {\n    eger (x < 0) {\n        vegerine -x;\n    } wella {\n        vegerine x;\n    }\n}\n\nfonksiyon heri_mezin(a, b) {\n    eger (a > b) {\n        vegerine a;\n    } wella {\n        vegerine b;\n    }\n}\n\nfonksiyon heri_piçuk(a, b) {\n    eger (a < b) {\n        vegerine a;\n    } wella {\n        vegerine b;\n    }\n}\n", "control_flow": "// Kurdi - Kontrola Herikine\nguherbar jimarker = 0;\nguherbar heri_zede = 5;\n\n// Loop\ndema_ku (jimarker < heri_zede) {\n    jimarker = jimarker + 1;\n}\n\n// Conditional\nguherbar xal = 85;\n\neger (xal >= 90) {\n    xal;\n} weki_din {\n    eger (xal >= 80) {\n        xal;\n    } weki_din {\n        xal;\n    }\n}\n\njimarker;\n", "state_machine": "// State Machine Example\nbila state = \"initial\";\n\neger (state == \"initial\") {\n    çap_bike(\"Starting\");\n    state = \"running\";\n}\n\nçap_bike(state);\n", "conditionals": "// Kurdi - Mantiqe merci\nbila puan = 85;\n\neger (puan >= 90) {\n    çap_bike(1000);\n} wella {\n    eger (puan >= 80) {\n        çap_bike(2000);\n    } wella {\n        çap_bike(3000);\n    }\n}\n\nçap_bike(999);\n", "code_organization": "// Kurdi - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable ji_bo large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// bikar_bine \"agent/agent_definition.hudhud\";\n// bikar_bine \"constitution/laws.hudhud\";\n// bikar_bine \"data/note.hudhud\";\n// bikar_bine \"utils/math.hudhud\";\n", "module_concepts": "// Kurdi - Modules & Code Organization\n// Demonstrates module system: bikar_bine/anin like Rust, Java, C++, Python\n\n// Import math module\n\"math.hudhud\" kullan;\n\n// Example syntax variations:\n// \"math.hudhud\" bikar_bine;\n// \"math.hudhud\" ji { add, subtract } bikar_bine;\n// \"math.hudhud\" math wek bikar_bine;\n\n// Using functions ji math module\nbila sum = add(10, 5);\nçap_bike(sum);\n\nbila diff = subtract(20, 8);\nçap_bike(diff);\n\nbila product = multiply(4, 7);\nçap_bike(product);\n\nbila quotient = divide(15, 3);\nçap_bike(quotient);\n\nbila squared = square(5);\nçap_bike(squared);\n\nbila cubed = cube(3);\nçap_bike(cubed);\n\nbila absolute = abs(-42);\nçap_bike(absolute);\n\nbila maximum = max(100, 50);\nçap_bike(maximum);\n\nbila minimum = min(100, 50);\nçap_bike(minimum);\n\n// Complex calculation using multiple functions\nbila result = add(multiply(5, 3), divide(20, 4));\nçap_bike(result);\n", "switch_concepts": "// Kurdi - Tegehen Switch/Case\n// switch/case/default\n\nfonksiyon tipa_roje(day) {\n    hilbijere (day) {\n        rewş \"Monday\":\n        rewş \"Tuesday\":\n        rewş \"Wednesday\":\n        rewş \"Thursday\":\n        rewş \"Friday\":\n            vegerine \"Roja kar\";\n        rewş \"Saturday\":\n        rewş \"Sunday\":\n            vegerine \"Dawiya hefte\";\n        standard:\n            vegerine \"Nenas\";\n    }\n}\n\nçap_bike(\"=== Day Types ===\");\nçap_bike(\"Monday: \" + tipa_roje(\"Monday\"));\nçap_bike(\"Saturday: \" + tipa_roje(\"Saturday\"));\nçap_bike(\"Holiday: \" + tipa_roje(\"Holiday\"));\n\nfonksiyon tipa_note(score) {\n    hilbijere (score) {\n        rewş 90:\n            vegerine \"A\";\n        rewş 80:\n            vegerine \"B\";\n        rewş 70:\n            vegerine \"C\";\n        rewş 60:\n            vegerine \"D\";\n        standard:\n            vegerine \"F\";\n    }\n}\n\nçap_bike(\"\\n=== Grades ===\");\nçap_bike(\"90: \" + tipa_note(90));\nçap_bike(\"70: \" + tipa_note(70));\nçap_bike(\"50: \" + tipa_note(50));\n\nfonksiyon peyama_rewşe(code) {\n    hilbijere (code) {\n        rewş 200:\n            vegerine \"OK\";\n        rewş 404:\n            vegerine \"Not Found\";\n        rewş 500:\n            vegerine \"Server Error\";\n        standard:\n            vegerine \"Nenas Status\";\n    }\n}\n\nçap_bike(\"\\n=== HTTP Status ===\");\nçap_bike(\"200: \" + peyama_rewşe(200));\nçap_bike(\"404: \" + peyama_rewşe(404));\n", "event_concepts": "// Kurdi - Event Concepts\n\nbuyer UserLogin {\n    çap_bike(\"User logged in\");\n}\n\nbuyer DataReceived {\n    çap_bike(\"Data received\");\n}\n\nbuyer ErrorOccurred {\n    çap_bike(\"Error occurred\");\n}\n\nfonksiyon on_login(username) {\n    çap_bike(\"Login: \" + username);\n    vegerine \"Welcome, \" + username;\n}\n\nfonksiyon on_data(source) {\n    çap_bike(\"Data from: \" + source);\n    vegerine \"Processed: \" + source;\n}\n\nfonksiyon on_error(message) {\n    çap_bike(\"Error: \" + message);\n    vegerine \"Handled: \" + message;\n}\n\nçap_bike(\"=== Event System ===\");\nbila r1 = on_login(\"admin\");\nçap_bike(r1);\nbila r2 = on_data(\"sensor_1\");\nçap_bike(r2);\nbila r3 = on_error(\"timeout\");\nçap_bike(r3);\n", "functions": "// Kurdi - Fonksiyonan\n// Minaken penasekirina u bikaranina fonksiyonan\n\n// Fonksiyona hesan\nfonksiyon silav_bide() {\n    çap_bike(\"Silav Cihan!\");\n}\n\n// Fonksiyon bi parametreyan\nfonksiyon le_zede_bike(a, b) {\n    vegerine a + b;\n}\n\n// Fonksiyon bi jekirine\nfonksiyon je_bike(a, b) {\n    vegerine a - b;\n}\n\n// Fonksiyonen matematiki\nfonksiyon çargoşe(x) {\n    vegerine x * x;\n}\n\nfonksiyon kup(x) {\n    vegerine x * x * x;\n}\n\n// Bikaranina fonksiyonan\nsilav_bide();\n\nbila encam1 = le_zede_bike(5, 3);\nçap_bike(encam1);\n\nbila encam2 = je_bike(10, 5);\nçap_bike(encam2);\n\nbila encam_çargoşe = çargoşe(4);\nçap_bike(encam_çargoşe);\n\nbila encam_kup = kup(3);\nçap_bike(encam_kup);\n\n// Hevgirtina fonksiyonan\nbila tevahi = le_zede_bike(çargoşe(3), kup(2));\nçap_bike(tevahi);\n", "entity_concepts": "// Kurdi - Tegehen Heyine\n\nbila bikarhener = {\n    nas: 1,\n    nav: \"Leyla\",\n    epeyam: \"leyla@nimune.com\",\n    rol: \"bernameçeker\"\n};\n\nbila hilber = {\n    nas: 101,\n    nav: \"HudHudScript IDE\",\n    guherto: \"2.0\",\n    biha: 49\n};\n\nbila ferman = {\n    nas: 1001,\n    nas_bikarhener: 1,\n    nas_hilber: 101,\n    hejmar: 2,\n    rewş: \"pejirandi\"\n};\n\nfonksiyon agahi_heyine(heyin) {\n    vegerine \"Heyin #\" + heyin.nas + \": \" + heyin.nav;\n}\n\nfonksiyon tevahi_bihesibine(ferman, biha) {\n    vegerine ferman.hejmar * biha;\n}\n\nçap_bike(\"=== Sistema Heyine ===\");\nçap_bike(agahi_heyine(bikarhener));\nçap_bike(agahi_heyine(hilber));\nbila tevahi = tevahi_bihesibine(ferman, hilber.biha);\nçap_bike(\"Ferman #\" + ferman.nas + \" tevahi: \" + tevahi);\nçap_bike(\"Rewş: \" + ferman.rewş);\n", "error_concepts": "// Kurdi - Error Concepts\n\nfonksiyon validate_age(age) {\n    eger (age < 0) {\n        baveje \"Invalid age: negative\";\n    }\n    eger (age > 150) {\n        baveje \"Invalid age: too large\";\n    }\n    vegerine age;\n}\n\nfonksiyon validate_email(email) {\n    eger (email == \"\") {\n        baveje \"Empty email\";\n    }\n    çap_bike(\"Email valid: \" + email);\n    vegerine email;\n}\n\nçap_bike(\"=== Validation ===\");\n\nbiceribine {\n    validate_age(25);\n    çap_bike(\"Age 25: valid\");\n} bigire (error) {\n    çap_bike(\"Error: \" + error);\n}\n\nbiceribine {\n    validate_age(-5);\n} bigire (error) {\n    çap_bike(\"Error: \" + error);\n}\n\nbiceribine {\n    validate_email(\"user@example.com\");\n    validate_email(\"\");\n} bigire (error) {\n    çap_bike(\"Email error: \" + error);\n} di_dawiye {\n    çap_bike(\"Validation complete\");\n}\n"}, "pl": {"objects": "// Polski - Obiekty\n// Obiekty z natywnymi słowami kluczowymi\n\n// Tworzenie obiektu\nniech osoba = {\n    imię: \"Alicja\",\n    wiek: 30,\n    miasto: \"Warszawa\"\n};\n\n// Dostęp do właściwości\nniech imię = osoba.imię;\nniech wiek = osoba.wiek;\n\n// Wynik\nimię;\n", "chemistry": "// PL - Chemistry Module\n\nfunkcja molarMass(atoms, atomicWeight) {\n    zwróć atoms * atomicWeight;\n}\n\nfunkcja concentration(moles, volume) {\n    zwróć moles / volume;\n}\n\nfunkcja pH(hydrogenConcentration) {\n    zwróć 14 - hydrogenConcentration;\n}\n\nfunkcja density(mass, volume) {\n    zwróć mass / volume;\n}\n\nfunkcja dilution(c1, v1, v2) {\n    zwróć (c1 * v1) / v2;\n}\n", "loops": "// Polski - Pętle\nniech licznik = 0;\nniech maksimum = 5;\n\ndopóki (licznik < maksimum) {\n    drukuj(licznik);\n    licznik = licznik + 1;\n}\n\ndrukuj(999);\n", "data_processing": "// Polski - Data Processing\n// Using NATIVE Polski keywords\n\nniech value1 = 100;\nniech value2 = 200;\nniech value3 = 300;\n\nniech total = value1+ value2+ value3;\nniech average = total / 3;\n\ndrukuj(total);\ndrukuj(average);\n", "modules_import": "// PL - Modules Import Example\n\n// Import math module (direct access)\nużyj \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nużyj \"physics.hudhud\" jako fizik;\n\n// Import chemistry (direct access)\nużyj \"chemistry.hudhud\";\n\n// Using math functions (direct)\nniech sum = add(10, 5);\ndrukuj(sum);\n\nniech product = multiply(4, 7);\ndrukuj(product);\n\n// Using physics functions (via alias: fizik.functionName)\nniech f = fizik.force(10, 9.8);\ndrukuj(f);\n\nniech ke = fizik.kineticEnergy(5, 10);\ndrukuj(ke);\n\n// Using chemistry functions (direct)\nniech d = density(100, 50);\ndrukuj(d);\n\nniech c = concentration(2, 5);\ndrukuj(c);\n", "return_concept": "// Polski - Koncepcja Zwracania\n// return\n\nfunkcja kwadrat(x) {\n    zwróć x * x;\n}\n\nfunkcja sześcian(x) {\n    zwróć x * x * x;\n}\n\ndrukuj(\"=== Math Functions ===\");\ndrukuj(\"kwadrat(5): \" + kwadrat(5));\ndrukuj(\"sześcian(3): \" + sześcian(3));\n\nfunkcja bezwzględna(x) {\n    jeśli (x < 0) {\n        zwróć -x;\n    }\n    zwróć x;\n}\n\ndrukuj(\"\\n=== Absolute ===\");\ndrukuj(\"bezwzględna(-7): \" + bezwzględna(-7));\ndrukuj(\"bezwzględna(3): \" + bezwzględna(3));\n\nfunkcja utwórz_punkt(x, y) {\n    zwróć { x: x, y: y };\n}\n\nniech p = utwórz_punkt(10, 20);\ndrukuj(\"\\n=== Point ===\");\ndrukuj(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfunkcja silnia(n) {\n    jeśli (n <= 1) {\n        zwróć 1;\n    }\n    zwróć n * silnia(n - 1);\n}\n\ndrukuj(\"\\n=== Factorial ===\");\ndrukuj(\"5! = \" + silnia(5));\ndrukuj(\"10! = \" + silnia(10));\n", "customer_service": "// Polski - Agent Obsługi Klienta\n// Używając NATYWNYCH słów kluczowych Polskiego\n\nniech powitanie = \"Dzień dobry, jak mogę pomóc?\";\nniech odpowiedź = \"Pomogę z Państwa zgłoszeniem.\";\n\ndrukuj(powitanie);\ndrukuj(odpowiedź);\n", "basic_example": "// Polski - Basic Example with NATIVE keywords\nzmienna a = 10;\nzmienna b = 20;\nzmienna suma = a + b;\n\ndrukuj(suma);\n", "physics": "// PL - Physics Module\n\nfunkcja speed(distance, time) {\n    zwróć distance / time;\n}\n\nfunkcja force(mass, acceleration) {\n    zwróć mass * acceleration;\n}\n\nfunkcja kineticEnergy(mass, velocity) {\n    zwróć 0.5 * mass * velocity * velocity;\n}\n\nfunkcja potentialEnergy(mass, gravity, height) {\n    zwróć mass * gravity * height;\n}\n\nfunkcja momentum(mass, velocity) {\n    zwróć mass * velocity;\n}\n", "error_handling": "// Polski - Obsługa błędów\n// try/catch/finally, throw\n\n// Basic try/catch\nfunkcja podziel(a, b) {\n    jeśli (b == 0) {\n        rzuć \"Błąd dzielenia przez zero\";\n    }\n    zwróć a / b;\n}\n\nspróbuj {\n    niech result = podziel(10, 2);\n    drukuj(\"10 / 2 = \" + result);\n} złap (error) {\n    drukuj(\"Błąd: \" + error);\n}\n\n// Try/catch/finally\ndrukuj(\"\n=== Przetwarzanie pliku ===\");\n\nfunkcja przetwórz_plik(filename) {\n    jeśli (filename == \"\") {\n        rzuć \"Błąd pustej nazwy pliku\";\n    }\n    drukuj(\"Przetwarzanie: \" + filename);\n    zwróć \"Dane z \" + filename;\n}\n\nspróbuj {\n    niech data = przetwórz_plik(\"report.txt\");\n    drukuj(\"Wynik: \" + data);\n} złap (error) {\n    drukuj(\"Błąd: \" + error);\n} na_końcu {\n    drukuj(\"Czyszczenie zakończone\");\n}\n\n// Nested error handling\ndrukuj(\"\n=== Zagnieżdżona obsługa błędów ===\");\n\nspróbuj {\n    drukuj(\"Zewnętrzny blok spróbuj\");\n    spróbuj {\n        rzuć \"Błąd wewnętrzny\";\n    } złap (inner_err) {\n        drukuj(\"Złapano wewnętrzny: \" + inner_err);\n        rzuć \"Ponownie rzucony błąd\";\n    }\n} złap (outer_err) {\n    drukuj(\"Złapano zewnętrzny: \" + outer_err);\n} na_końcu {\n    drukuj(\"Wszystko gotowe\");\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici pakiet kullanımı\nużyj \"cebir\";\nużyj \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nużyj \"cebir/matris\";\nużyj \"cebir/vektor\";\nużyj \"fizik/hareket\";\n\npisz(\"============================================================\");\npisz(\"HudHudScript Paket Sistemi Demo\");\npisz(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\npisz(\"📦 Cebir Paketi Kullanımı:\");\npisz(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nzmienna matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nzmienna matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\npisz(\"Matris 1:\");\nmatris1.goster();\n\npisz(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nzmienna toplam = matris1.topla(matris2);\npisz(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nzmienna vektor1 = Vektor([1, 2, 3]);\nzmienna vektor2 = Vektor([4, 5, 6]);\n\npisz(\"\\n\\n📐 Vektör İşlemleri:\");\npisz(\"─────────────────────────────────────────────────────────\\n\");\n\npisz(\"Vektör 1: \" + vektor1.toString());\npisz(\"Vektör 2: \" + vektor2.toString());\n\nzmienna noktaSal = vektor1.noktaSal(vektor2);\npisz(\"Nokta Çarpım: \" + noktaSal);\n\nzmienna caprazCarpim = vektor1.caprazCarpim(vektor2);\npisz(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\npisz(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\npisz(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nzmienna baslangicHizi = 0;      // m/s\nzmienna ivme = 9.8;              // m/s² (yerçekimi)\nzmienna zaman = 5;               // saniye\n\nzmienna sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nzmienna mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\npisz(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\npisz(\"İvme: \" + ivme + \" m/s²\");\npisz(\"Zaman: \" + zaman + \" s\");\npisz(\"─────────────────────────────────────────────────────────\");\npisz(\"Son Hız: \" + sonHiz + \" m/s\");\npisz(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\npisz(\"\\n\\n📝 Paket Oluşturma:\");\npisz(\"─────────────────────────────────────────────────────────\\n\");\n\npisz(\"1. hudhud.toml dosyası oluşturun:\");\npisz(\"   [package]\");\npisz(\"   name = 'matematik-utils'\");\npisz(\"   version = '1.0.0'\");\npisz(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\npisz(\"\\n2. Bağımlılıklar ekleyin:\");\npisz(\"   [dependencies]\");\npisz(\"   cebir = '^2.0.0'\");\npisz(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\npisz(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\npisz(\"─────────────────────────────────────────────────────────\\n\");\n\npisz(\"Paket kurma:\");\npisz(\"  hudhudscript install cebir\");\npisz(\"  hudhudscript install fizik@1.5.0\");\n\npisz(\"\\nPaket güncelleme:\");\npisz(\"  hudhudscript update cebir\");\npisz(\"  hudhudscript update --all\");\n\npisz(\"\\nPaket kaldırma:\");\npisz(\"  hudhudscript remove cebir\");\n\npisz(\"\\nKurulu paketleri listeleme:\");\npisz(\"  hudhudscript list\");\n\npisz(\"\\nPaket arama:\");\npisz(\"  hudhudscript search matematik\");\n\npisz(\"\\nPaket bilgisi:\");\npisz(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\npisz(\"\\n\\n🔗 Paket Bağımlılıkları:\");\npisz(\"─────────────────────────────────────────────────────────\\n\");\n\npisz(\"Versiyon belirtme:\");\npisz(\"  'cebir' = '^2.0.0'    # 2.x.x\");\npisz(\"  'fizik' = '~1.5.0'    # 1.5.x\");\npisz(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\npisz(\"\\nGit deposundan:\");\npisz(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\npisz(\"\\nYerel yoldan:\");\npisz(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\npisz(\"\\n\\n🔒 Paket Güvenliği:\");\npisz(\"─────────────────────────────────────────────────────────\\n\");\n\npisz(\"Güvenlik kontrolü:\");\npisz(\"  hudhudscript audit\");\n\npisz(\"\\nChecksum doğrulama:\");\npisz(\"  hudhudscript verify cebir\");\n\npisz(\"\\n============================================================\");\npisz(\"✓ Paket sistemi demo tamamlandı!\");\npisz(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\npisz(\"============================================================\");\n", "arrays": "// Polski - Tablice\n// Tablice z natywnymi słowami kluczowymi\n\n// Tworzenie tablic\nniech liczby = [1, 2, 3, 4, 5];\nniech imiona = [\"Alicja\", \"Bartek\", \"Czarek\"];\n\n// Dostęp do elementów\nniech pierwszy = liczby[0];\nniech drugi = liczby[1];\n\n// Wynik\npierwszy;\n", "math": "// PL - Math Module\n\nfunction add(a, b) {\n    zwróć a + b;\n}\n\nfunction subtract(a, b) {\n    zwróć a - b;\n}\n\nfunction multiply(a, b) {\n    zwróć a * b;\n}\n\nfunction divide(a, b) {\n    jeśli (b == 0) {\n        drukuj(\"Error: Division by zero!\");\n        zwróć 0;\n    } w_przeciwnym_razie {\n        zwróć a / b;\n    }\n}\n\nfunction square(x) {\n    zwróć x * x;\n}\n\nfunction cube(x) {\n    zwróć x * x * x;\n}\n\nfunction abs(x) {\n    jeśli (x < 0) {\n        zwróć -x;\n    } w_przeciwnym_razie {\n        zwróć x;\n    }\n}\n\nfunction max(a, b) {\n    jeśli (a > b) {\n        zwróć a;\n    } w_przeciwnym_razie {\n        zwróć b;\n    }\n}\n\nfunction min(a, b) {\n    jeśli (a < b) {\n        zwróć a;\n    } w_przeciwnym_razie {\n        zwróć b;\n    }\n}\n", "control_flow": "// Polski - Przepływ Sterowania\nzmienna licznik = 0;\nzmienna maksimum = 5;\n\n// Loop\npodczas (licznik < maksimum) {\n    licznik = licznik + 1;\n}\n\n// Conditional\nzmienna wynik = 85;\n\njeśli (wynik >= 90) {\n    wynik;\n} inaczej {\n    jeśli (wynik >= 80) {\n        wynik;\n    } inaczej {\n        wynik;\n    }\n}\n\nlicznik;", "state_machine": "// State Machine Example\nniech state = \"initial\";\n\njeśli (state == \"initial\") {\n    drukuj(\"Starting\");\n    state = \"running\";\n}\n\ndrukuj(state);\n", "conditionals": "// Polski - Logika warunkowa\nniech wynik = 85;\n\njeśli (wynik >= 90) {\n    drukuj(1000);\n} inaczej {\n    jeśli (wynik >= 80) {\n        drukuj(2000);\n    } inaczej {\n        drukuj(3000);\n    }\n}\n\ndrukuj(999);\n", "code_organization": "// Polski - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable dla large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// użyj \"agent/agent_definition.hudhud\";\n// użyj \"constitution/laws.hudhud\";\n// użyj \"data/note.hudhud\";\n// użyj \"utils/math.hudhud\";\n", "module_concepts": "// Polski - Modules & Code Organization\n// Demonstrates module system: użyj/importuj like Rust, Java, C++, Python\n\n// Import math module\nużyj \"math.hudhud\";\n\n// Example syntax variations:\n// użyj \"math.hudhud\";\n// użyj { add, subtract } z \"math.hudhud\";\n// użyj \"math.hudhud\" jako math;\n\n// Using functions z math module\nniech sum = add(10, 5);\ndrukuj(sum);\n\nniech diff = subtract(20, 8);\ndrukuj(diff);\n\nniech product = multiply(4, 7);\ndrukuj(product);\n\nniech quotient = divide(15, 3);\ndrukuj(quotient);\n\nniech squared = square(5);\ndrukuj(squared);\n\nniech cubed = cube(3);\ndrukuj(cubed);\n\nniech absolute = abs(-42);\ndrukuj(absolute);\n\nniech maximum = max(100, 50);\ndrukuj(maximum);\n\nniech minimum = min(100, 50);\ndrukuj(minimum);\n\n// Complex calculation using multiple functions\nniech result = add(multiply(5, 3), divide(20, 4));\ndrukuj(result);\n", "switch_concepts": "// Polski - Koncepcje Switch/Case\n// switch/case/default\n\nfunkcja typ_dnia(day) {\n    wybierz (day) {\n        przypadek \"Monday\":\n        przypadek \"Tuesday\":\n        przypadek \"Wednesday\":\n        przypadek \"Thursday\":\n        przypadek \"Friday\":\n            zwróć \"Dzień roboczy\";\n        przypadek \"Saturday\":\n        przypadek \"Sunday\":\n            zwróć \"Weekend\";\n        domyślnie:\n            zwróć \"Nieznany\";\n    }\n}\n\ndrukuj(\"=== Day Types ===\");\ndrukuj(\"Monday: \" + typ_dnia(\"Monday\"));\ndrukuj(\"Saturday: \" + typ_dnia(\"Saturday\"));\ndrukuj(\"Holiday: \" + typ_dnia(\"Holiday\"));\n\nfunkcja litera_oceny(score) {\n    wybierz (score) {\n        przypadek 90:\n            zwróć \"A\";\n        przypadek 80:\n            zwróć \"B\";\n        przypadek 70:\n            zwróć \"C\";\n        przypadek 60:\n            zwróć \"D\";\n        domyślnie:\n            zwróć \"F\";\n    }\n}\n\ndrukuj(\"\\n=== Grades ===\");\ndrukuj(\"90: \" + litera_oceny(90));\ndrukuj(\"70: \" + litera_oceny(70));\ndrukuj(\"50: \" + litera_oceny(50));\n\nfunkcja komunikat_statusu(code) {\n    wybierz (code) {\n        przypadek 200:\n            zwróć \"OK\";\n        przypadek 404:\n            zwróć \"Not Found\";\n        przypadek 500:\n            zwróć \"Server Error\";\n        domyślnie:\n            zwróć \"Nieznany Status\";\n    }\n}\n\ndrukuj(\"\\n=== HTTP Status ===\");\ndrukuj(\"200: \" + komunikat_statusu(200));\ndrukuj(\"404: \" + komunikat_statusu(404));\n", "event_concepts": "// Polski - Event Concepts\n\nzdarzenie UserLogin {\n    drukuj(\"User logged in\");\n}\n\nzdarzenie DataReceived {\n    drukuj(\"Data received\");\n}\n\nzdarzenie ErrorOccurred {\n    drukuj(\"Error occurred\");\n}\n\nfunkcja on_login(username) {\n    drukuj(\"Login: \" + username);\n    zwróć \"Welcome, \" + username;\n}\n\nfunkcja on_data(source) {\n    drukuj(\"Data from: \" + source);\n    zwróć \"Processed: \" + source;\n}\n\nfunkcja on_error(message) {\n    drukuj(\"Error: \" + message);\n    zwróć \"Handled: \" + message;\n}\n\ndrukuj(\"=== Event System ===\");\nniech r1 = on_login(\"admin\");\ndrukuj(r1);\nniech r2 = on_data(\"sensor_1\");\ndrukuj(r2);\nniech r3 = on_error(\"timeout\");\ndrukuj(r3);\n", "functions": "// Polski - Funkcje\n// Przykłady definiowania i używania funkcji\n\n// Prosta funkcja\nfunkcja przywitaj() {\n    drukuj(\"Witaj Świecie!\");\n}\n\n// Funkcja z parametrami\nfunkcja dodaj(a, b) {\n    zwróć a + b;\n}\n\n// Funkcja z wieloma parametrami\nfunkcja oblicz(num1, num2, operacja) {\n    jeśli (operacja == \"dodaj\") {\n        zwróć num1 + num2;\n    } inaczej {\n        zwróć 0;\n    }\n}\n\n// Funkcje matematyczne\nfunkcja kwadrat(x) {\n    zwróć x * x;\n}\n\nfunkcja sześcian(x) {\n    zwróć x * x * x;\n}\n\n// Użycie funkcji\nprzywitaj();\n\nniech wynik1 = dodaj(5, 3);\ndrukuj(wynik1);\n\nniech wynik2 = oblicz(10, 5, \"dodaj\");\ndrukuj(wynik2);\n\nniech wynik_kwadrat = kwadrat(4);\ndrukuj(wynik_kwadrat);\n\nniech wynik_sześcian = sześcian(3);\ndrukuj(wynik_sześcian);\n\n// Kompozycja funkcji\nniech suma = dodaj(kwadrat(3), sześcian(2));\ndrukuj(suma);\n", "entity_concepts": "// Polski - Koncepcje Encji\n\nniech użytkownik = {\n    id: 1,\n    nazwa: \"Alicja\",\n    email: \"alicja@przykład.pl\",\n    rola: \"programistka\"\n};\n\nniech produkt = {\n    id: 101,\n    nazwa: \"HudHudScript IDE\",\n    wersja: \"2.0\",\n    cena: 49\n};\n\nniech zamówienie = {\n    id: 1001,\n    id_użytkownika: 1,\n    id_produktu: 101,\n    ilość: 2,\n    stan: \"potwierdzony\"\n};\n\nfunkcja info_encji(encja) {\n    zwróć \"Encja #\" + encja.id + \": \" + encja.nazwa;\n}\n\nfunkcja oblicz_sumę(zamówienie, cena) {\n    zwróć zamówienie.ilość * cena;\n}\n\ndrukuj(\"=== System Encji ===\");\ndrukuj(info_encji(użytkownik));\ndrukuj(info_encji(produkt));\nniech suma = oblicz_sumę(zamówienie, produkt.cena);\ndrukuj(\"Zamówienie #\" + zamówienie.id + \" suma: \" + suma);\ndrukuj(\"Stan: \" + zamówienie.stan);\n", "error_concepts": "// Polski - Error Concepts\n\nfunkcja validate_age(age) {\n    jeśli (age < 0) {\n        rzuć \"Invalid age: negative\";\n    }\n    jeśli (age > 150) {\n        rzuć \"Invalid age: too large\";\n    }\n    zwróć age;\n}\n\nfunkcja validate_email(email) {\n    jeśli (email == \"\") {\n        rzuć \"Empty email\";\n    }\n    drukuj(\"Email valid: \" + email);\n    zwróć email;\n}\n\ndrukuj(\"=== Validation ===\");\n\nspróbuj {\n    validate_age(25);\n    drukuj(\"Age 25: valid\");\n} złap (error) {\n    drukuj(\"Error: \" + error);\n}\n\nspróbuj {\n    validate_age(-5);\n} złap (error) {\n    drukuj(\"Error: \" + error);\n}\n\nspróbuj {\n    validate_email(\"user@example.com\");\n    validate_email(\"\");\n} złap (error) {\n    drukuj(\"Email error: \" + error);\n} na_końcu {\n    drukuj(\"Validation complete\");\n}\n"}, "pt": {"objects": "// Português - Objetos\n// Objetos com palavras-chave nativas\n\n// Criar objeto\nseja pessoa = {\n    nome: \"Alice\",\n    idade: 30,\n    cidade: \"Lisboa\"\n};\n\n// Acessar propriedades\nseja nome = pessoa.nome;\nseja idade = pessoa.idade;\n\n// Resultado\nnome;\n", "chemistry": "// PT - Chemistry Module\n\nfunção molarMass(atoms, atomicWeight) {\n    retornar atoms * atomicWeight;\n}\n\nfunção concentration(moles, volume) {\n    retornar moles / volume;\n}\n\nfunção pH(hydrogenConcentration) {\n    retornar 14 - hydrogenConcentration;\n}\n\nfunção density(mass, volume) {\n    retornar mass / volume;\n}\n\nfunção dilution(c1, v1, v2) {\n    retornar (c1 * v1) / v2;\n}\n", "loops": "// Português - Laços\nseja contador = 0;\nseja máximo = 5;\n\nenquanto (contador < máximo) {\n    imprima(contador);\n    contador = contador + 1;\n}\n\nimprima(999);\n", "data_processing": "// Português - Data Processing\n// Using NATIVE Português keywords\n\nvariável value1 = 100;\nvariável value2 = 200;\nvariável value3 = 300;\n\nvariável total = value1+ value2+ value3;\nvariável average = total / 3;\n\nimprimir(total);\nimprimir(average);\n", "arrow_functions": "// Portugues - Funcoes Seta\n// Sintaxe moderna e concisa para funcoes\n\n// Funcao seta - sintaxe curta\nseja somar = (a, b) => a + b;\nseja multiplicar = (x, y) => x * y;\n\nimprima(somar(5, 3));      // 8\nimprima(multiplicar(4, 7)); // 28\n\n// Funcao seta com bloco\nseja calcular = (a, b) => {\n    seja soma = a + b;\n    seja produto = a * b;\n    retorna soma + produto;\n};\n\nseja resultado = calcular(5, 3);\nimprima(resultado);  // 23 (8 + 15)\n\n// Parametro unico (sem necessidade de parenteses)\nseja quadrado = x => x * x;\nimprima(quadrado(6));  // 36\n\n// Sem parametros\nseja saudar = () => \"Ola!\";\nimprima(saudar());  // Ola!\n", "modules_import": "// PT - Modules Import Example\n\n// Import math module (direct access)\nusar \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nusar \"physics.hudhud\" como fizik;\n\n// Import chemistry (direct access)\nusar \"chemistry.hudhud\";\n\n// Using math functions (direct)\nvariável sum = add(10, 5);\nimprimir(sum);\n\nvariável product = multiply(4, 7);\nimprimir(product);\n\n// Using physics functions (via alias: fizik.functionName)\nvariável f = fizik.force(10, 9.8);\nimprimir(f);\n\nvariável ke = fizik.kineticEnergy(5, 10);\nimprimir(ke);\n\n// Using chemistry functions (direct)\nvariável d = density(100, 50);\nimprimir(d);\n\nvariável c = concentration(2, 5);\nimprimir(c);\n", "return_concept": "// Português - Conceito de Retorno\n// return\n\nfunção quadrado(x) {\n    retorna x * x;\n}\n\nfunção cubo(x) {\n    retorna x * x * x;\n}\n\nimprima(\"=== Math Functions ===\");\nimprima(\"quadrado(5): \" + quadrado(5));\nimprima(\"cubo(3): \" + cubo(3));\n\nfunção absoluto(x) {\n    se (x < 0) {\n        retorna -x;\n    }\n    retorna x;\n}\n\nimprima(\"\\n=== Absolute ===\");\nimprima(\"absoluto(-7): \" + absoluto(-7));\nimprima(\"absoluto(3): \" + absoluto(3));\n\nfunção criar_ponto(x, y) {\n    retorna { x: x, y: y };\n}\n\nseja p = criar_ponto(10, 20);\nimprima(\"\\n=== Point ===\");\nimprima(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfunção fatorial(n) {\n    se (n <= 1) {\n        retorna 1;\n    }\n    retorna n * fatorial(n - 1);\n}\n\nimprima(\"\\n=== Factorial ===\");\nimprima(\"5! = \" + fatorial(5));\nimprima(\"10! = \" + fatorial(10));\n", "customer_service": "// Português - Agente de Atendimento ao Cliente\n// Usando palavras-chave NATIVAS do Português\n\nseja saudação = \"Olá, como posso ajudá-lo?\";\nseja resposta = \"Vou ajudá-lo com o seu pedido.\";\n\nimprima(saudação);\nimprima(resposta);\n", "basic_example": "// Português - Basic Example with NATIVE keywords\nvariável a = 10;\nvariável b = 20;\nvariável soma = a + b;\n\nimprimir(soma);\n", "physics": "// PT - Physics Module\n\nfunção speed(distance, time) {\n    retornar distance / time;\n}\n\nfunção force(mass, acceleration) {\n    retornar mass * acceleration;\n}\n\nfunção kineticEnergy(mass, velocity) {\n    retornar 0.5 * mass * velocity * velocity;\n}\n\nfunção potentialEnergy(mass, gravity, height) {\n    retornar mass * gravity * height;\n}\n\nfunção momentum(mass, velocity) {\n    retornar mass * velocity;\n}\n", "error_handling": "// pt - Error Handling\n// Simple error control with if-else\n\nfunction divide(a, b) {\n    if (b == 0) {\n        return { error: true, message: \"Division by zero\", value: 0 };\n    }\n    return { error: false, message: \"\", value: a / b };\n}\n\nprint(\"=== Error Handling ===\");\n\nvar result1 = divide(10, 2);\nif (result1.error) {\n    print(\"Error: \" + result1.message);\n} else {\n    print(\"10 / 2 = \" + result1.value);\n}\n\nvar result2 = divide(10, 0);\nif (result2.error) {\n    print(\"Error caught: \" + result2.message);\n} else {\n    print(\"Result: \" + result2.value);\n}\n\nprint(\"Done\");\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici pacote kullanımı\nusar \"cebir\";\nusar \"fizik\" como pacote;\n\n// Paket içinden belirli modülleri içe aktarma\nusar \"cebir/matris\";\nusar \"cebir/vektor\";\nusar \"fizik/hareket\";\n\nescreve(\"============================================================\");\nescreve(\"HudHudScript Paket Sistemi Demo\");\nescreve(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nescreve(\"📦 Cebir Paketi Kullanımı:\");\nescreve(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nvariável matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nvariável matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nescreve(\"Matris 1:\");\nmatris1.goster();\n\nescreve(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nvariável toplam = matris1.topla(matris2);\nescreve(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nvariável vektor1 = Vektor([1, 2, 3]);\nvariável vektor2 = Vektor([4, 5, 6]);\n\nescreve(\"\\n\\n📐 Vektör İşlemleri:\");\nescreve(\"─────────────────────────────────────────────────────────\\n\");\n\nescreve(\"Vektör 1: \" + vektor1.toString());\nescreve(\"Vektör 2: \" + vektor2.toString());\n\nvariável noktaSal = vektor1.noktaSal(vektor2);\nescreve(\"Nokta Çarpım: \" + noktaSal);\n\nvariável caprazCarpim = vektor1.caprazCarpim(vektor2);\nescreve(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nescreve(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nescreve(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nvariável baslangicHizi = 0;      // m/s\nvariável ivme = 9.8;              // m/s² (yerçekimi)\nvariável zaman = 5;               // saniye\n\nvariável sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nvariável mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nescreve(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nescreve(\"İvme: \" + ivme + \" m/s²\");\nescreve(\"Zaman: \" + zaman + \" s\");\nescreve(\"─────────────────────────────────────────────────────────\");\nescreve(\"Son Hız: \" + sonHiz + \" m/s\");\nescreve(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nescreve(\"\\n\\n📝 Paket Oluşturma:\");\nescreve(\"─────────────────────────────────────────────────────────\\n\");\n\nescreve(\"1. hudhud.toml dosyası oluşturun:\");\nescreve(\"   [package]\");\nescreve(\"   name = 'matematik-utils'\");\nescreve(\"   version = '1.0.0'\");\nescreve(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nescreve(\"\\n2. Bağımlılıklar ekleyin:\");\nescreve(\"   [dependencies]\");\nescreve(\"   cebir = '^2.0.0'\");\nescreve(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nescreve(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nescreve(\"─────────────────────────────────────────────────────────\\n\");\n\nescreve(\"Paket kurma:\");\nescreve(\"  hudhudscript install cebir\");\nescreve(\"  hudhudscript install fizik@1.5.0\");\n\nescreve(\"\\nPaket güncelleme:\");\nescreve(\"  hudhudscript update cebir\");\nescreve(\"  hudhudscript update --all\");\n\nescreve(\"\\nPaket kaldırma:\");\nescreve(\"  hudhudscript remove cebir\");\n\nescreve(\"\\nKurulu paketleri listeleme:\");\nescreve(\"  hudhudscript list\");\n\nescreve(\"\\nPaket arama:\");\nescreve(\"  hudhudscript search matematik\");\n\nescreve(\"\\nPaket bilgisi:\");\nescreve(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nescreve(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nescreve(\"─────────────────────────────────────────────────────────\\n\");\n\nescreve(\"Versiyon belirtme:\");\nescreve(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nescreve(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nescreve(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nescreve(\"\\nGit deposundan:\");\nescreve(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nescreve(\"\\nYerel yoldan:\");\nescreve(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nescreve(\"\\n\\n🔒 Paket Güvenliği:\");\nescreve(\"─────────────────────────────────────────────────────────\\n\");\n\nescreve(\"Güvenlik kontrolü:\");\nescreve(\"  hudhudscript audit\");\n\nescreve(\"\\nChecksum doğrulama:\");\nescreve(\"  hudhudscript verify cebir\");\n\nescreve(\"\\n============================================================\");\nescreve(\"✓ Paket sistemi demo tamamlandı!\");\nescreve(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nescreve(\"============================================================\");\n", "arrays": "// Português - Arrays\n// Arrays com palavras-chave nativas\n\n// Criar arrays\nseja números = [1, 2, 3, 4, 5];\nseja nomes = [\"Alice\", \"Bruno\", \"Carlos\"];\n\n// Acessar elementos\nseja primeiro = números[0];\nseja segundo = números[1];\n\n// Resultado\nprimeiro;\n", "math": "// PT - Math Module\n\nfunction add(a, b) {\n    retornar a + b;\n}\n\nfunction subtract(a, b) {\n    retornar a - b;\n}\n\nfunction multiply(a, b) {\n    retornar a * b;\n}\n\nfunction divide(a, b) {\n    se (b == 0) {\n        imprimir(\"Error: Division by zero!\");\n        retornar 0;\n    } senão {\n        retornar a / b;\n    }\n}\n\nfunction square(x) {\n    retornar x * x;\n}\n\nfunction cube(x) {\n    retornar x * x * x;\n}\n\nfunction abs(x) {\n    se (x < 0) {\n        retornar -x;\n    } senão {\n        retornar x;\n    }\n}\n\nfunction max(a, b) {\n    se (a > b) {\n        retornar a;\n    } senão {\n        retornar b;\n    }\n}\n\nfunction min(a, b) {\n    se (a < b) {\n        retornar a;\n    } senão {\n        retornar b;\n    }\n}\n", "control_flow": "// Português - Fluxo de Controle\nvariável contador = 0;\nvariável máximo = 5;\n\n// Loop\nenquanto (contador < máximo) {\n    contador = contador + 1;\n}\n\n// Conditional\nvariável pontuação = 85;\n\nse (pontuação >= 90) {\n    pontuação;\n} senão {\n    se (pontuação >= 80) {\n        pontuação;\n    } senão {\n        pontuação;\n    }\n}\n\ncontador;\n", "state_machine": "// State Machine Example\nvariável state = \"initial\";\n\nse (state == \"initial\") {\n    imprimir(\"Starting\");\n    state = \"running\";\n}\n\nimprimir(state);\n", "conditionals": "// Português - Lógica condicional\nseja pontuação = 85;\n\nse (pontuação >= 90) {\n    imprima(1000);\n} senão {\n    se (pontuação >= 80) {\n        imprima(2000);\n    } senão {\n        imprima(3000);\n    }\n}\n\nimprima(999);\n", "code_organization": "// Português - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable para large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// usar \"agent/agent_definition.hudhud\";\n// usar \"constitution/laws.hudhud\";\n// usar \"data/note.hudhud\";\n// usar \"utils/math.hudhud\";\n", "module_concepts": "// Português - Modules & Code Organization\n// Demonstrates module system: usar/importar like Rust, Java, C++, Python\n\n// Import math module\nusar \"math.hudhud\";\n\n// Example syntax variations:\n// usar \"math.hudhud\";\n// usar { add, subtract } de \"math.hudhud\";\n// usar \"math.hudhud\" como math;\n\n// Using functions de math module\nvariável sum = add(10, 5);\nimprimir(sum);\n\nvariável diff = subtract(20, 8);\nimprimir(diff);\n\nvariável product = multiply(4, 7);\nimprimir(product);\n\nvariável quotient = divide(15, 3);\nimprimir(quotient);\n\nvariável squared = square(5);\nimprimir(squared);\n\nvariável cubed = cube(3);\nimprimir(cubed);\n\nvariável absolute = abs(-42);\nimprimir(absolute);\n\nvariável maximum = max(100, 50);\nimprimir(maximum);\n\nvariável minimum = min(100, 50);\nimprimir(minimum);\n\n// Complex calculation using multiple functions\nvariável result = add(multiply(5, 3), divide(20, 4));\nimprimir(result);\n", "higher_order_functions": "// Portugues - Funcoes de Ordem Superior\n// Funcoes que trabalham com outras funcoes\n\n// Funcao que retorna uma funcao\nfuncao multiplicador(fator) {\n    retorna (x) => x * fator;\n}\n\nseja dobro = multiplicador(2);\nseja triplo = multiplicador(3);\n\nimprima(dobro(5));  // 10\nimprima(triplo(5));  // 15\n\n// Funcao que recebe uma funcao\nfuncao aplicar(fn, valor) {\n    retorna fn(valor);\n}\n\nimprima(aplicar(dobro, 10));  // 20\n\n// Exemplo de composicao\nfuncao compor(f, g) {\n    retorna (x) => f(g(x));\n}\n\nseja somarUm = (x) => x + 1;\nseja vezesDois = (x) => x * 2;\n\nseja somarDepoisDobrar = compor(vezesDois, somarUm);\nimprima(somarDepoisDobrar(5));  // 12 (5+1=6, 6*2=12)\n", "switch_concepts": "// pt - Switch Concepts\n// Using if-else for multiple conditions\n\nfunction dayType(day) {\n    if (day == \"Monday\") { return \"Weekday\"; }\n    if (day == \"Tuesday\") { return \"Weekday\"; }\n    if (day == \"Wednesday\") { return \"Weekday\"; }\n    if (day == \"Thursday\") { return \"Weekday\"; }\n    if (day == \"Friday\") { return \"Weekday\"; }\n    if (day == \"Saturday\") { return \"Weekend\"; }\n    if (day == \"Sunday\") { return \"Weekend\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== Day Types ===\");\nprint(\"Monday: \" + dayType(\"Monday\"));\nprint(\"Saturday: \" + dayType(\"Saturday\"));\nprint(\"Holiday: \" + dayType(\"Holiday\"));\n\nfunction statusMessage(code) {\n    if (code == 200) { return \"OK\"; }\n    if (code == 404) { return \"Not Found\"; }\n    if (code == 500) { return \"Server Error\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== HTTP Status ===\");\nprint(\"200: \" + statusMessage(200));\nprint(\"404: \" + statusMessage(404));\n", "event_concepts": "// Português - Event Concepts\n\nevento UserLogin {\n    imprima(\"User logged in\");\n}\n\nevento DataReceived {\n    imprima(\"Data received\");\n}\n\nevento ErrorOccurred {\n    imprima(\"Error occurred\");\n}\n\nfunção on_login(username) {\n    imprima(\"Login: \" + username);\n    retorna \"Welcome, \" + username;\n}\n\nfunção on_data(source) {\n    imprima(\"Data from: \" + source);\n    retorna \"Processed: \" + source;\n}\n\nfunção on_error(message) {\n    imprima(\"Error: \" + message);\n    retorna \"Handled: \" + message;\n}\n\nimprima(\"=== Event System ===\");\nseja r1 = on_login(\"admin\");\nimprima(r1);\nseja r2 = on_data(\"sensor_1\");\nimprima(r2);\nseja r3 = on_error(\"timeout\");\nimprima(r3);\n", "functions": "// Português - Funções\n// Exemplos de definição e uso de funções\n\n// Função simples\nfunção saudar() {\n    imprima(\"Olá Mundo!\");\n}\n\n// Função com parâmetros\nfunção somar(a, b) {\n    retorna a + b;\n}\n\n// Função com vários parâmetros\nfunção calcular(num1, num2, operação) {\n    se (operação == \"somar\") {\n        retorna num1 + num2;\n    } senão {\n        retorna 0;\n    }\n}\n\n// Funções matemáticas\nfunção quadrado(x) {\n    retorna x * x;\n}\n\nfunção cubo(x) {\n    retorna x * x * x;\n}\n\n// Uso de funções\nsaudar();\n\nseja resultado1 = somar(5, 3);\nimprima(resultado1);\n\nseja resultado2 = calcular(10, 5, \"somar\");\nimprima(resultado2);\n\nseja resultado_quadrado = quadrado(4);\nimprima(resultado_quadrado);\n\nseja resultado_cubo = cubo(3);\nimprima(resultado_cubo);\n\n// Composição de funções\nseja total = somar(quadrado(3), cubo(2));\nimprima(total);\n", "entity_concepts": "// Português - Conceitos de Entidade\n\nseja utilizador = {\n    id: 1,\n    nome: \"Alice\",\n    email: \"alice@exemplo.com\",\n    papel: \"desenvolvedor\"\n};\n\nseja produto = {\n    id: 101,\n    nome: \"HudHudScript IDE\",\n    versão: \"2.0\",\n    preço: 49\n};\n\nseja encomenda = {\n    id: 1001,\n    id_utilizador: 1,\n    id_produto: 101,\n    quantidade: 2,\n    estado: \"confirmado\"\n};\n\nfunção info_entidade(entidade) {\n    retorna \"Entidade #\" + entidade.id + \": \" + entidade.nome;\n}\n\nfunção calcular_total(encomenda, preço) {\n    retorna encomenda.quantidade * preço;\n}\n\nimprima(\"=== Sistema de Entidades ===\");\nimprima(info_entidade(utilizador));\nimprima(info_entidade(produto));\nseja total = calcular_total(encomenda, produto.preço);\nimprima(\"Encomenda #\" + encomenda.id + \" total: \" + total);\nimprima(\"Estado: \" + encomenda.estado);\n", "error_concepts": "// pt - Error Concepts\n// Simple validation functions\n\nfunction validateAge(age) {\n    if (age < 0) {\n        return { valid: false, error: \"Invalid age: negative\" };\n    }\n    if (age > 150) {\n        return { valid: false, error: \"Invalid age: too large\" };\n    }\n    return { valid: true, age: age };\n}\n\nfunction validateEmail(email) {\n    if (email == \"\") {\n        return { valid: false, error: \"Empty email\" };\n    }\n    return { valid: true, email: email };\n}\n\nprint(\"=== Validation ===\");\n\nvar ageResult1 = validateAge(25);\nif (ageResult1.valid) {\n    print(\"Age 25 is valid\");\n} else {\n    print(\"Error: \" + ageResult1.error);\n}\n\nvar ageResult2 = validateAge(-5);\nif (ageResult2.valid) {\n    print(\"Age is valid\");\n} else {\n    print(\"Error: \" + ageResult2.error);\n}\n\nvar emailResult = validateEmail(\"user@example.com\");\nif (emailResult.valid) {\n    print(\"Email valid: \" + emailResult.email);\n} else {\n    print(\"Email error: \" + emailResult.error);\n}\n\nprint(\"Validation complete\");\n"}, "ru": {"objects": "// Русский - Объекты\n// Объекты с родными ключевыми словами\n\n// Создание объекта\nпусть человек = {\n    имя: \"Алиса\",\n    возраст: 30,\n    город: \"Москва\"\n};\n\n// Доступ к свойствам\nпусть имя = человек.имя;\nпусть возраст = человек.возраст;\n\n// Результат\nимя;\n", "chemistry": "// RU - Chemistry Module\n\n// Molar Mass\nфункция molarMass(atoms, atomicWeight) {\n    вернуть atoms * atomicWeight;\n}\n\n// Concentration = Moles / Volume\nфункция concentration(moles, volume) {\n    вернуть moles / volume;\n}\n\n// pH calculation\nфункция pH(hydrogenConcentration) {\n    вернуть 14 - hydrogenConcentration;\n}\n\n// Density = Mass / Volume\nфункция density(mass, volume) {\n    вернуть mass / volume;\n}\n\n// Dilution: C1*V1 = C2*V2\nфункция dilution(c1, v1, v2) {\n    вернуть (c1 * v1) / v2;\n}\n", "loops": "// Русский - Loop Example\nпусть счётчик = 0;\nпусть максимум = 5;\n\nпока (счётчик < максимум) {\n    счётчик = счётчик + 1;\n}\n\nсчётчик;", "data_processing": "// Русский - Data Processing\n// Using NATIVE Русский keywords\n\nпусть данные1 = 100;\nпусть данные2 = 200;\nпусть данные3 = 300;\n\nпусть итого = данные1 + данные2 + данные3;\nпусть среднее = итого / 3;\n\nсреднее;", "arrow_functions": "// Русский - Стрелочные функции\n// Современный, краткий синтаксис для функций\n\n// Стрелочная функция - короткий синтаксис\nпусть сложить = (а, б) => а + б;\nпусть умножить = (х, у) => х * у;\n\nпечать(сложить(5, 3));      // 8\nпечать(умножить(4, 7)); // 28\n\n// Стрелочная функция с блоком\nпусть вычислить = (а, б) => {\n    пусть сумма = а + б;\n    пусть произведение = а * б;\n    вернуть сумма + произведение;\n};\n\nпусть результат = вычислить(5, 3);\nпечать(результат);  // 23 (8 + 15)\n\n// Один параметр (скобки не нужны)\nпусть квадрат = х => х * х;\nпечать(квадрат(6));  // 36\n\n// Без параметров\nпусть приветствие = () => \"Привет!\";\nпечать(приветствие());  // Привет!\n", "modules_import": "// Русский - Modules Import Example\n\n// Import math module (direct access)\nиспользовать \"matematika.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nиспользовать \"fizika.hudhud\" как fizik;\n\n// Import chemistry (direct access)\nиспользовать \"himiya.hudhud\";\n\n// Using math functions (direct)\nпусть sum = сложить(10, 5);\nпечать(sum);\n\nпусть product = умножить(4, 7);\nпечать(product);\n\n// Using physics functions (via alias: fizik.functionName)\nпусть f = fizik.сила(10, 9.8);\nпечать(f);\n\nпусть ke = fizik.кинетическаяЭнергия(5, 10);\nпечать(ke);\n\n// Using chemistry functions (direct)\nпусть d = плотность(100, 50);\nпечать(d);\n\nпусть c = концентрация(2, 5);\nпечать(c);\n", "return_concept": "// Русский - Концепция Возврата\n// return\n\nфункция квадрат(x) {\n    вернуть x * x;\n}\n\nфункция куб(x) {\n    вернуть x * x * x;\n}\n\nпечать(\"=== Math Functions ===\");\nпечать(\"квадрат(5): \" + квадрат(5));\nпечать(\"куб(3): \" + куб(3));\n\nфункция абсолютное(x) {\n    если (x < 0) {\n        вернуть -x;\n    }\n    вернуть x;\n}\n\nпечать(\"\\n=== Absolute ===\");\nпечать(\"абсолютное(-7): \" + абсолютное(-7));\nпечать(\"абсолютное(3): \" + абсолютное(3));\n\nфункция создай_точку(x, y) {\n    вернуть { x: x, y: y };\n}\n\nпусть p = создай_точку(10, 20);\nпечать(\"\\n=== Point ===\");\nпечать(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nфункция факториал(n) {\n    если (n <= 1) {\n        вернуть 1;\n    }\n    вернуть n * факториал(n - 1);\n}\n\nпечать(\"\\n=== Factorial ===\");\nпечать(\"5! = \" + факториал(5));\nпечать(\"10! = \" + факториал(10));\n", "customer_service": "// Русский - Customer Service Agent\n// Using NATIVE Русский keywords\n\nпусть приветствие = \"Здравствуйте, чем могу помочь?\";\nпусть ответ = \"Я помогу вам с вашим запросом.\";\n\nприветствие;", "basic_example": "// Русский - Basic Example with NATIVE keywords\nпусть икс = 10;\nпусть игрек = 20;\nпусть сумма = икс + игрек;\nпечать(сумма);\n", "physics": "// RU - Physics Module\n\n// Speed = Distance / Time\nфункция speed(distance, time) {\n    вернуть distance / time;\n}\n\n// Force = Mass * Acceleration\nфункция force(mass, acceleration) {\n    вернуть mass * acceleration;\n}\n\n// Kinetic Energy = 0.5 * Mass * Velocity^2\nфункция kineticEnergy(mass, velocity) {\n    вернуть 0.5 * mass * velocity * velocity;\n}\n\n// Potential Energy = Mass * Gravity * Height\nфункция potentialEnergy(mass, gravity, height) {\n    вернуть mass * gravity * height;\n}\n\n// Momentum = Mass * Velocity\nфункция momentum(mass, velocity) {\n    вернуть mass * velocity;\n}\n", "error_handling": "// ru - Error Handling\n// Simple error control with if-else\n\nfunction divide(a, b) {\n    if (b == 0) {\n        return { error: true, message: \"Division by zero\", value: 0 };\n    }\n    return { error: false, message: \"\", value: a / b };\n}\n\nprint(\"=== Error Handling ===\");\n\nvar result1 = divide(10, 2);\nif (result1.error) {\n    print(\"Error: \" + result1.message);\n} else {\n    print(\"10 / 2 = \" + result1.value);\n}\n\nvar result2 = divide(10, 0);\nif (result2.error) {\n    print(\"Error caught: \" + result2.message);\n} else {\n    print(\"Result: \" + result2.value);\n}\n\nprint(\"Done\");\n", "package_usage": "// Использование пакетов - Система пакетов ХудХудСкрипт\n// Система управления пакетами: создание, установка, публикация и использование\n\n// ============================================================\n// 1. ИСПОЛЬЗОВАНИЕ ПАКЕТОВ\n// ============================================================\n\n// Использование внешнего пакета\nиспользовать \"алгебра\";\nиспользовать \"физика\";\n\n// Импорт конкретных модулей из пакета\nиспользовать \"алгебра/матрица\";\nиспользовать \"алгебра/вектор\";\nиспользовать \"физика/движение\";\n\nпечать(\"============================================================\");\nпечать(\"Демо системы пакетов ХудХудСкрипт\");\nпечать(\"============================================================\\n\");\n\n// ============================================================\n// 2. ИСПОЛЬЗОВАНИЕ ФУНКЦИЙ ПАКЕТА\n// ============================================================\n\nпечать(\"Использование пакета алгебры:\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\n// Создание матрицы\nпусть матрица1 = Матрица([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nпусть матрица2 = Матрица([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nпечать(\"Матрица 1:\");\nматрица1.показать();\n\nпечать(\"\\nМатрица 2:\");\nматрица2.показать();\n\n// Сложение матриц\nпусть сумма = матрица1.сложить(матрица2);\nпечать(\"\\nСложение матриц:\");\nсумма.показать();\n\n// Операции с векторами\nпусть вектор1 = Вектор([1, 2, 3]);\nпусть вектор2 = Вектор([4, 5, 6]);\n\nпечать(\"\\n\\nОперации с векторами:\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\nпечать(\"Вектор 1: \" + вектор1.строка());\nпечать(\"Вектор 2: \" + вектор2.строка());\n\nпусть скалярное = вектор1.скалярное(вектор2);\nпечать(\"Скалярное произведение: \" + скалярное);\n\nпусть векторное = вектор1.векторное(вектор2);\nпечать(\"Векторное произведение: \" + векторное.строка());\n\n// ============================================================\n// 3. ИСПОЛЬЗОВАНИЕ ПАКЕТА ФИЗИКИ\n// ============================================================\n\nпечать(\"\\n\\nИспользование пакета физики:\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\n// Расчёты движения\nпусть начальная_скорость = 0;     // м/с\nпусть ускорение = 9.8;            // м/с² (гравитация)\nпусть время = 5;                   // секунд\n\nпусть конечная_скорость = Движение.рассчитать_скорость(начальная_скорость, ускорение, время);\nпусть расстояние = Движение.рассчитать_расстояние(начальная_скорость, ускорение, время);\n\nпечать(\"Начальная скорость: \" + начальная_скорость + \" м/с\");\nпечать(\"Ускорение: \" + ускорение + \" м/с²\");\nпечать(\"Время: \" + время + \" с\");\nпечать(\"─────────────────────────────────────────────────────────\");\nпечать(\"Конечная скорость: \" + конечная_скорость + \" м/с\");\nпечать(\"Пройденное расстояние: \" + расстояние + \" м\");\n\n// ============================================================\n// 4. СОЗДАНИЕ ПАКЕТОВ\n// ============================================================\n\nпечать(\"\\n\\nСоздание пакетов:\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\nпечать(\"1. Создайте файл hudhud.toml:\");\nпечать(\"   [пакет]\");\nпечать(\"   имя = 'математические-утилиты'\");\nпечать(\"   версия = '1.0.0'\");\nпечать(\"   описание = 'Вспомогательные математические функции'\");\n\nпечать(\"\\n2. Добавьте зависимости:\");\nпечать(\"   [зависимости]\");\nпечать(\"   алгебра = '^2.0.0'\");\nпечать(\"   физика = '^1.5.0'\");\n\n// ============================================================\n// 5. КОМАНДЫ УПРАВЛЕНИЯ ПАКЕТАМИ\n// ============================================================\n\nпечать(\"\\n\\nКоманды управления пакетами:\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\nпечать(\"Установка пакета:\");\nпечать(\"  hudhudscript install алгебра\");\nпечать(\"  hudhudscript install физика@1.5.0\");\n\nпечать(\"\\nОбновление пакета:\");\nпечать(\"  hudhudscript update алгебра\");\nпечать(\"  hudhudscript update --all\");\n\nпечать(\"\\nУдаление пакета:\");\nпечать(\"  hudhudscript remove алгебра\");\n\nпечать(\"\\nСписок установленных пакетов:\");\nпечать(\"  hudhudscript list\");\n\nпечать(\"\\nПоиск пакета:\");\nпечать(\"  hudhudscript search математика\");\n\nпечать(\"\\nИнформация о пакете:\");\nпечать(\"  hudhudscript info алгебра\");\n\n// ============================================================\n// 6. ЗАВИСИМОСТИ ПАКЕТОВ\n// ============================================================\n\nпечать(\"\\n\\nЗависимости пакетов:\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\nпечать(\"Указание версии:\");\nпечать(\"  'алгебра' = '^2.0.0'    # 2.x.x\");\nпечать(\"  'физика' = '~1.5.0'    # 1.5.x\");\nпечать(\"  'химия' = '1.2.3'     # Точная версия\");\n\nпечать(\"\\nИз репозитория Гит:\");\nпечать(\"  'моя-библиотека' = { git = 'https://github.com/user/my-lib' }\");\n\nпечать(\"\\nИз локального пути:\");\nпечать(\"  'локальная-библиотека' = { path = '../локальная-библиотека' }\");\n\n// ============================================================\n// 7. БЕЗОПАСНОСТЬ ПАКЕТОВ\n// ============================================================\n\nпечать(\"\\n\\nБезопасность пакетов:\");\nпечать(\"─────────────────────────────────────────────────────────\\n\");\n\nпечать(\"Проверка безопасности:\");\nпечать(\"  hudhudscript audit\");\n\nпечать(\"\\nПроверка контрольной суммы:\");\nпечать(\"  hudhudscript verify алгебра\");\n\nпечать(\"\\n============================================================\");\nпечать(\"Демо системы пакетов завершено!\");\nпечать(\"Пишите модульный и переиспользуемый код с ХудХудСкрипт\");\nпечать(\"============================================================\");\n", "arrays": "// Русский - Массивы\n// Массивы с родными ключевыми словами\n\n// Создание массивов\nпусть числа = [1, 2, 3, 4, 5];\nпусть имена = [\"Алиса\", \"Борис\", \"Виктор\"];\n\n// Доступ к элементам\nпусть первый = числа[0];\nпусть второй = числа[1];\n\n// Результат\nпервый;\n", "math": "// RU - Math Module\n\n// Addition\nфункция add(a, b) {\n    вернуть a + b;\n}\n\n// Subtraction\nфункция subtract(a, b) {\n    вернуть a - b;\n}\n\n// Multiplication\nфункция multiply(a, b) {\n    вернуть a * b;\n}\n\n// Division\nфункция divide(a, b) {\n    если (b == 0) {\n        печать(\"Error: Division by zero!\");\n        вернуть 0;\n    } иначе {\n        вернуть a / b;\n    }\n}\n\n// Square\nфункция square(x) {\n    вернуть x * x;\n}\n\n// Cube\nфункция cube(x) {\n    вернуть x * x * x;\n}\n\n// Absolute value\nфункция abs(x) {\n    если (x < 0) {\n        вернуть -x;\n    } иначе {\n        вернуть x;\n    }\n}\n\n// Maximum\nфункция max(a, b) {\n    если (a > b) {\n        вернуть a;\n    } иначе {\n        вернуть b;\n    }\n}\n\n// Minimum\nфункция min(a, b) {\n    если (a < b) {\n        вернуть a;\n    } иначе {\n        вернуть b;\n    }\n}\n", "control_flow": "// Русский - Control Flow\nпусть счётчик = 0;\nпусть максимум = 5;\n\n// Loop\nпока (счётчик < максимум) {\n    счётчик = счётчик + 1;\n}\n\n// Conditional\nпусть оценка = 85;\n\nесли (оценка >= 90) {\n    оценка;\n} иначе {\n    если (оценка >= 80) {\n        оценка;\n    } иначе {\n        оценка;\n    }\n}\n\nсчётчик;\n", "himiya": "// Русский - Chemistry Module\n\nфункция молярнаяМасса(atoms, atomicWeight) {\n    вернуть atoms * atomicWeight;\n}\n\nфункция концентрация(moles, volume) {\n    вернуть moles / volume;\n}\n\nфункция pH(hydrogenConcentration) {\n    вернуть 14 - hydrogenConcentration;\n}\n\nфункция плотность(mass, volume) {\n    вернуть mass / volume;\n}\n\nфункция разбавление(c1, v1, v2) {\n    вернуть (c1 * v1) / v2;\n}\n", "state_machine": "// State Machine Example\nпусть state = \"initial\";\n\nесли (state == \"initial\") {\n    печать(\"Starting\");\n    state = \"running\";\n}\n\nпечать(state);\n", "conditionals": "// Русский - Conditional Logic\nпусть оценка = 85;\n\nесли (оценка >= 90) {\n    оценка;\n} иначе {\n    если (оценка >= 80) {\n        оценка;\n    } иначе {\n        оценка;\n    }\n}", "code_organization": "// Русский - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable для large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// использовать \"agent/agent_definition.hudhud\";\n// использовать \"constitution/laws.hudhud\";\n// использовать \"data/note.hudhud\";\n// использовать \"utils/math.hudhud\";\n", "module_concepts": "// Русский - Modules & Code Organization\n// Demonstrates module system: использовать/импорт like Rust, Java, C++, Python\n\n// Import math module\nиспользовать \"math.hudhud\";\n\n// Example syntax variations:\n// использовать \"math.hudhud\";\n// использовать { add, subtract } из \"math.hudhud\";\n// использовать \"math.hudhud\" как math;\n\n// Using functions из math module\nпусть sum = add(10, 5);\nпечать(sum);\n\nпусть diff = subtract(20, 8);\nпечать(diff);\n\nпусть product = multiply(4, 7);\nпечать(product);\n\nпусть quotient = divide(15, 3);\nпечать(quotient);\n\nпусть squared = square(5);\nпечать(squared);\n\nпусть cubed = cube(3);\nпечать(cubed);\n\nпусть absolute = abs(-42);\nпечать(absolute);\n\nпусть maximum = max(100, 50);\nпечать(maximum);\n\nпусть minimum = min(100, 50);\nпечать(minimum);\n\n// Complex calculation using multiple functions\nпусть result = add(multiply(5, 3), divide(20, 4));\nпечать(result);\n", "higher_order_functions": "// Русский - Функции высшего порядка\n// Функции, работающие с другими функциями\n\n// Функция, возвращающая функцию\nфункция множитель(коэффициент) {\n    вернуть (х) => х * коэффициент;\n}\n\nпусть удвоить = множитель(2);\nпусть утроить = множитель(3);\n\nпечать(удвоить(5));  // 10\nпечать(утроить(5));  // 15\n\n// Функция, принимающая функцию\nфункция применить(функ, значение) {\n    вернуть функ(значение);\n}\n\nпечать(применить(удвоить, 10));  // 20\n\n// Пример композиции\nфункция составить(ф, г) {\n    вернуть (х) => ф(г(х));\n}\n\nпусть добавитьОдин = (х) => х + 1;\nпусть умножитьНаДва = (х) => х * 2;\n\nпусть сложитьЗатемУдвоить = составить(умножитьНаДва, добавитьОдин);\nпечать(сложитьЗатемУдвоить(5));  // 12 (5+1=6, 6*2=12)\n", "switch_concepts": "// ru - Switch Concepts\n// Using if-else for multiple conditions\n\nfunction dayType(day) {\n    if (day == \"Monday\") { return \"Weekday\"; }\n    if (day == \"Tuesday\") { return \"Weekday\"; }\n    if (day == \"Wednesday\") { return \"Weekday\"; }\n    if (day == \"Thursday\") { return \"Weekday\"; }\n    if (day == \"Friday\") { return \"Weekday\"; }\n    if (day == \"Saturday\") { return \"Weekend\"; }\n    if (day == \"Sunday\") { return \"Weekend\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== Day Types ===\");\nprint(\"Monday: \" + dayType(\"Monday\"));\nprint(\"Saturday: \" + dayType(\"Saturday\"));\nprint(\"Holiday: \" + dayType(\"Holiday\"));\n\nfunction statusMessage(code) {\n    if (code == 200) { return \"OK\"; }\n    if (code == 404) { return \"Not Found\"; }\n    if (code == 500) { return \"Server Error\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== HTTP Status ===\");\nprint(\"200: \" + statusMessage(200));\nprint(\"404: \" + statusMessage(404));\n", "event_concepts": "// Русский - Event Concepts\n\nсобытие UserLogin {\n    печать(\"User logged in\");\n}\n\nсобытие DataReceived {\n    печать(\"Data received\");\n}\n\nсобытие ErrorOccurred {\n    печать(\"Error occurred\");\n}\n\nфункция on_login(username) {\n    печать(\"Login: \" + username);\n    вернуть \"Welcome, \" + username;\n}\n\nфункция on_data(source) {\n    печать(\"Data from: \" + source);\n    вернуть \"Processed: \" + source;\n}\n\nфункция on_error(message) {\n    печать(\"Error: \" + message);\n    вернуть \"Handled: \" + message;\n}\n\nпечать(\"=== Event System ===\");\nпусть r1 = on_login(\"admin\");\nпечать(r1);\nпусть r2 = on_data(\"sensor_1\");\nпечать(r2);\nпусть r3 = on_error(\"timeout\");\nпечать(r3);\n", "functions": "// Русский - Функции\n// Примеры определения и использования функций\n\n// Простая функция\nфункция приветствовать() {\n    печать(\"Привет мир!\");\n}\n\n// Функция с параметрами\nфункция сложить(а, б) {\n    вернуть а + б;\n}\n\n// Функция с несколькими параметрами\nфункция вычислить(число1, число2, операция) {\n    если (операция == \"сложить\") {\n        вернуть число1 + число2;\n    } иначе {\n        вернуть 0;\n    }\n}\n\n// Математические функции\nфункция квадрат(х) {\n    вернуть х * х;\n}\n\nфункция куб(х) {\n    вернуть х * х * х;\n}\n\n// Использование функций\nприветствовать();\n\nпусть результат1 = сложить(5, 3);\nпечать(результат1);\n\nпусть результат2 = вычислить(10, 5, \"сложить\");\nпечать(результат2);\n\nпусть результат_квадрат = квадрат(4);\nпечать(результат_квадрат);\n\nпусть результат_куб = куб(3);\nпечать(результат_куб);\n\n// Композиция функций\nпусть итого = сложить(квадрат(3), куб(2));\nпечать(итого);\n", "entity_concepts": "// Русский - Концепции сущностей\n\nпусть пользователь = {\n    ид: 1,\n    имя: \"Алиса\",\n    почта: \"alisa@example.com\",\n    роль: \"разработчик\"\n};\n\nпусть продукт = {\n    ид: 101,\n    имя: \"Среда разработки ХудХудСкрипт\",\n    версия: \"2.0\",\n    цена: 49\n};\n\nпусть заказ = {\n    ид: 1001,\n    ид_пользователя: 1,\n    ид_продукта: 101,\n    количество: 2,\n    статус: \"подтверждён\"\n};\n\nфункция информация_сущности(сущность) {\n    вернуть \"Сущность #\" + сущность.ид + \": \" + сущность.имя;\n}\n\nфункция рассчитать_итого(заказ, цена) {\n    вернуть заказ.количество * цена;\n}\n\nпечать(\"=== Система сущностей ===\");\nпечать(информация_сущности(пользователь));\nпечать(информация_сущности(продукт));\nпусть итого = рассчитать_итого(заказ, продукт.цена);\nпечать(\"Заказ #\" + заказ.ид + \" итого: \" + итого);\nпечать(\"Статус: \" + заказ.статус);\n", "fizika": "// Русский - Physics Module\n\nфункция скорость(distance, time) {\n    вернуть distance / time;\n}\n\nфункция сила(mass, acceleration) {\n    вернуть mass * acceleration;\n}\n\nфункция кинетическаяЭнергия(mass, velocity) {\n    вернуть 0.5 * mass * velocity * velocity;\n}\n\nфункция потенциальнаяЭнергия(mass, gravity, height) {\n    вернуть mass * gravity * height;\n}\n\nфункция импульс(mass, velocity) {\n    вернуть mass * velocity;\n}\n", "error_concepts": "// ru - Error Concepts\n// Simple validation functions\n\nfunction validateAge(age) {\n    if (age < 0) {\n        return { valid: false, error: \"Invalid age: negative\" };\n    }\n    if (age > 150) {\n        return { valid: false, error: \"Invalid age: too large\" };\n    }\n    return { valid: true, age: age };\n}\n\nfunction validateEmail(email) {\n    if (email == \"\") {\n        return { valid: false, error: \"Empty email\" };\n    }\n    return { valid: true, email: email };\n}\n\nprint(\"=== Validation ===\");\n\nvar ageResult1 = validateAge(25);\nif (ageResult1.valid) {\n    print(\"Age 25 is valid\");\n} else {\n    print(\"Error: \" + ageResult1.error);\n}\n\nvar ageResult2 = validateAge(-5);\nif (ageResult2.valid) {\n    print(\"Age is valid\");\n} else {\n    print(\"Error: \" + ageResult2.error);\n}\n\nvar emailResult = validateEmail(\"user@example.com\");\nif (emailResult.valid) {\n    print(\"Email valid: \" + emailResult.email);\n} else {\n    print(\"Email error: \" + emailResult.error);\n}\n\nprint(\"Validation complete\");\n", "matematika": "// Русский - Math Module\n\nфункция сложить(a, b) {\n    вернуть a + b;\n}\n\nфункция вычесть(a, b) {\n    вернуть a - b;\n}\n\nфункция умножить(a, b) {\n    вернуть a * b;\n}\n\nфункция разделить(a, b) {\n    если (b == 0) {\n        печать(\"Error: Division by zero!\");\n        вернуть 0;\n    } иначе {\n        вернуть a / b;\n    }\n}\n\nфункция квадрат(x) {\n    вернуть x * x;\n}\n\nфункция куб(x) {\n    вернуть x * x * x;\n}\n\nфункция модуль(x) {\n    если (x < 0) {\n        вернуть -x;\n    } иначе {\n        вернуть x;\n    }\n}\n\nфункция максимум(a, b) {\n    если (a > b) {\n        вернуть a;\n    } иначе {\n        вернуть b;\n    }\n}\n\nфункция минимум(a, b) {\n    если (a < b) {\n        вернуть a;\n    } иначе {\n        вернуть b;\n    }\n}\n"}, "sr": {"objects": "// Српски - Објекти\n// Објекти са домаћим кључним речима\n\n// Креирај објекат\nнека особа = {\n    име: \"Ана\",\n    године: 30,\n    град: \"Београд\"\n};\n\n// Приступи својствима\nнека име = особа.име;\nнека године = особа.године;\n\n// Резултат\nиме;\n", "chemistry": "// SR - Chemistry Module\n\nна molarMass(atoms, atomicWeight) {\n    врати atoms * atomicWeight;\n}\n\nна concentration(moles, volume) {\n    врати moles / volume;\n}\n\nна pH(hydrogenConcentration) {\n    врати 14 - hydrogenConcentration;\n}\n\nна density(mass, volume) {\n    врати mass / volume;\n}\n\nна dilution(c1, v1, v2) {\n    врати (c1 * v1) / v2;\n}\n", "loops": "// Српски - Пример петље\nнека бројач = 0;\nнека максимум = 5;\n\nдок (бројач < максимум) {\n    ispiši(бројач);\n    бројач = бројач + 1;\n}\n\nispiši(999);\n", "data_processing": "// Српски - Data Processing\n// Using NATIVE Српски keywords\n\nнека value1 = 100;\nнека value2 = 200;\nнека value3 = 300;\n\nнека total = value1+ value2+ value3;\nнека average = total / 3;\n\nštampaj(total);\nštampaj(average);\n", "modules_import": "// SR - Modules Import Example\n\n// Import math module (direct access)\nкористи \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nкористи \"physics.hudhud\" као fizik;\n\n// Import chemistry (direct access)\nкористи \"chemistry.hudhud\";\n\n// Using math functions (direct)\nнека sum = add(10, 5);\nштампај(sum);\n\nнека product = multiply(4, 7);\nштампај(product);\n\n// Using physics functions (via alias: fizik.functionName)\nнека f = fizik.force(10, 9.8);\nштампај(f);\n\nнека ke = fizik.kineticEnergy(5, 10);\nштампај(ke);\n\n// Using chemistry functions (direct)\nнека d = density(100, 50);\nштампај(d);\n\nнека c = concentration(2, 5);\nштампај(c);\n", "return_concept": "// Српски - Концепт повратка\n// return\n\nfunkcija квадрат(x) {\n    vrati x * x;\n}\n\nfunkcija куб(x) {\n    vrati x * x * x;\n}\n\nispiši(\"=== Math Functions ===\");\nispiši(\"квадрат(5): \" + квадрат(5));\nispiši(\"куб(3): \" + куб(3));\n\nfunkcija апсолутна(x) {\n    ako (x < 0) {\n        vrati -x;\n    }\n    vrati x;\n}\n\nispiši(\"\\n=== Absolute ===\");\nispiši(\"апсолутна(-7): \" + апсолутна(-7));\nispiši(\"апсолутна(3): \" + апсолутна(3));\n\nfunkcija креирај_тачку(x, y) {\n    vrati { x: x, y: y };\n}\n\nneka p = креирај_тачку(10, 20);\nispiši(\"\\n=== Point ===\");\nispiši(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nfunkcija факторијел(n) {\n    ako (n <= 1) {\n        vrati 1;\n    }\n    vrati n * факторијел(n - 1);\n}\n\nispiši(\"\\n=== Factorial ===\");\nispiši(\"5! = \" + факторијел(5));\nispiši(\"10! = \" + факторијел(10));\n", "customer_service": "// Српски - Агент за корисничку подршку\n// Користи ДОМАЋЕ српске кључне речи\n\nнека поздрав = \"Здраво, како вам могу помоћи?\";\nнека одговор = \"Помоћи ћу вам са вашим захтевом.\";\n\nispiši(поздрав);\nispiši(одговор);\n", "basic_example": "// Српски - Basic Example with NATIVE keywords\nпроменљива икс = 10;\nпроменљива ипсилон = 20;\nпроменљива сума = икс + ипсилон;\n\nштампај(сума);\n", "physics": "// SR - Physics Module\n\nна speed(distance, time) {\n    врати distance / time;\n}\n\nна force(mass, acceleration) {\n    врати mass * acceleration;\n}\n\nна kineticEnergy(mass, velocity) {\n    врати 0.5 * mass * velocity * velocity;\n}\n\nна potentialEnergy(mass, gravity, height) {\n    врати mass * gravity * height;\n}\n\nна momentum(mass, velocity) {\n    врати mass * velocity;\n}\n", "error_handling": "// Српски - Управљање грешкама\n// try/catch/finally, throw\n\n// Basic try/catch\nfunkcija подели(a, b) {\n    ako (b == 0) {\n        baci \"Грешка дељења нулом\";\n    }\n    vrati a / b;\n}\n\npokušaj {\n    neka result = подели(10, 2);\n    ispiši(\"10 / 2 = \" + result);\n} uhvati (error) {\n    ispiši(\"Грешка: \" + error);\n}\n\n// Try/catch/finally\nispiši(\"\n=== Обрада датотеке ===\");\n\nfunkcija обради_датотеку(filename) {\n    ako (filename == \"\") {\n        baci \"Грешка празног назива датотеке\";\n    }\n    ispiši(\"Обрада: \" + filename);\n    vrati \"Подаци из \" + filename;\n}\n\npokušaj {\n    neka data = обради_датотеку(\"report.txt\");\n    ispiši(\"Резултат: \" + data);\n} uhvati (error) {\n    ispiši(\"Грешка: \" + error);\n} konačno {\n    ispiši(\"Чишћење завршено\");\n}\n\n// Nested error handling\nispiši(\"\n=== Угнежђено управљање грешкама ===\");\n\npokušaj {\n    ispiši(\"Спољни покушај блок\");\n    pokušaj {\n        baci \"Унутрашња грешка\";\n    } uhvati (inner_err) {\n        ispiši(\"Ухваћена унутрашња: \" + inner_err);\n        baci \"Поново бачена грешка\";\n    }\n} uhvati (outer_err) {\n    ispiši(\"Ухваћена спољашња: \" + outer_err);\n} konačno {\n    ispiši(\"Све готово\");\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici пакет kullanımı\nкористи \"cebir\";\nкористи \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nкористи \"cebir/matris\";\nкористи \"cebir/vektor\";\nкористи \"fizik/hareket\";\n\nпиши(\"============================================================\");\nпиши(\"HudHudScript Paket Sistemi Demo\");\nпиши(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nпиши(\"📦 Cebir Paketi Kullanımı:\");\nпиши(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nпроменљива matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nпроменљива matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nпиши(\"Matris 1:\");\nmatris1.goster();\n\nпиши(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nпроменљива toplam = matris1.topla(matris2);\nпиши(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nпроменљива vektor1 = Vektor([1, 2, 3]);\nпроменљива vektor2 = Vektor([4, 5, 6]);\n\nпиши(\"\\n\\n📐 Vektör İşlemleri:\");\nпиши(\"─────────────────────────────────────────────────────────\\n\");\n\nпиши(\"Vektör 1: \" + vektor1.toString());\nпиши(\"Vektör 2: \" + vektor2.toString());\n\nпроменљива noktaSal = vektor1.noktaSal(vektor2);\nпиши(\"Nokta Çarpım: \" + noktaSal);\n\nпроменљива caprazCarpim = vektor1.caprazCarpim(vektor2);\nпиши(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nпиши(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nпиши(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nпроменљива baslangicHizi = 0;      // m/s\nпроменљива ivme = 9.8;              // m/s² (yerçekimi)\nпроменљива zaman = 5;               // saniye\n\nпроменљива sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nпроменљива mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nпиши(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nпиши(\"İvme: \" + ivme + \" m/s²\");\nпиши(\"Zaman: \" + zaman + \" s\");\nпиши(\"─────────────────────────────────────────────────────────\");\nпиши(\"Son Hız: \" + sonHiz + \" m/s\");\nпиши(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nпиши(\"\\n\\n📝 Paket Oluşturma:\");\nпиши(\"─────────────────────────────────────────────────────────\\n\");\n\nпиши(\"1. hudhud.toml dosyası oluşturun:\");\nпиши(\"   [package]\");\nпиши(\"   name = 'matematik-utils'\");\nпиши(\"   version = '1.0.0'\");\nпиши(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nпиши(\"\\n2. Bağımlılıklar ekleyin:\");\nпиши(\"   [dependencies]\");\nпиши(\"   cebir = '^2.0.0'\");\nпиши(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nпиши(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nпиши(\"─────────────────────────────────────────────────────────\\n\");\n\nпиши(\"Paket kurma:\");\nпиши(\"  hudhudscript install cebir\");\nпиши(\"  hudhudscript install fizik@1.5.0\");\n\nпиши(\"\\nPaket güncelleme:\");\nпиши(\"  hudhudscript update cebir\");\nпиши(\"  hudhudscript update --all\");\n\nпиши(\"\\nPaket kaldırma:\");\nпиши(\"  hudhudscript remove cebir\");\n\nпиши(\"\\nKurulu paketleri listeleme:\");\nпиши(\"  hudhudscript list\");\n\nпиши(\"\\nPaket arama:\");\nпиши(\"  hudhudscript search matematik\");\n\nпиши(\"\\nPaket bilgisi:\");\nпиши(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nпиши(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nпиши(\"─────────────────────────────────────────────────────────\\n\");\n\nпиши(\"Versiyon belirtme:\");\nпиши(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nпиши(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nпиши(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nпиши(\"\\nGit deposundan:\");\nпиши(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nпиши(\"\\nYerel yoldan:\");\nпиши(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nпиши(\"\\n\\n🔒 Paket Güvenliği:\");\nпиши(\"─────────────────────────────────────────────────────────\\n\");\n\nпиши(\"Güvenlik kontrolü:\");\nпиши(\"  hudhudscript audit\");\n\nпиши(\"\\nChecksum doğrulama:\");\nпиши(\"  hudhudscript verify cebir\");\n\nпиши(\"\\n============================================================\");\nпиши(\"✓ Paket sistemi demo tamamlandı!\");\nпиши(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nпиши(\"============================================================\");\n", "arrays": "// Српски - Низови\n// Низови са домаћим кључним речима\n\n// Креирај низове\nнека бројеви = [1, 2, 3, 4, 5];\nнека имена = [\"Ана\", \"Иван\", \"Маја\"];\n\n// Приступи елементима\nнека први = бројеви[0];\nнека други = бројеви[1];\n\n// Резултат\nпрви;\n", "math": "// SR - Math Module\n\nна add(a, b) {\n    врати a + b;\n}\n\nна subtract(a, b) {\n    врати a - b;\n}\n\nна multiply(a, b) {\n    врати a * b;\n}\n\nна divide(a, b) {\n    ако (b == 0) {\n        штампај(\"Error: Division by zero!\");\n        врати 0;\n    } иначе {\n        врати a / b;\n    }\n}\n\nна square(x) {\n    врати x * x;\n}\n\nна cube(x) {\n    врати x * x * x;\n}\n\nна abs(x) {\n    ако (x < 0) {\n        врати -x;\n    } иначе {\n        врати x;\n    }\n}\n\nна max(a, b) {\n    ако (a > b) {\n        врати a;\n    } иначе {\n        врати b;\n    }\n}\n\nна min(a, b) {\n    ако (a < b) {\n        врати a;\n    } иначе {\n        врати b;\n    }\n}\n", "control_flow": "// Српски - Контрола Тока\nпроменљива бројач = 0;\nпроменљива максимум = 5;\n\n// Loop\nдок (бројач < максимум) {\n    бројач = бројач + 1;\n}\n\n// Conditional\nпроменљива резултат = 85;\n\nако (резултат >= 90) {\n    резултат;\n} иначе {\n    ако (резултат >= 80) {\n        резултат;\n    } иначе {\n        резултат;\n    }\n}\n\nбројач;", "state_machine": "// State Machine Example\nнека state = \"initial\";\n\nако (state == \"initial\") {\n    штампај(\"Starting\");\n    state = \"running\";\n}\n\nштампај(state);\n", "conditionals": "// Српски - Условна логика\nнека резултат = 85;\n\nако (резултат >= 90) {\n    ispiši(1000);\n} иначе {\n    ако (резултат >= 80) {\n        ispiši(2000);\n    } иначе {\n        ispiši(3000);\n    }\n}\n\nispiši(999);\n", "code_organization": "// Српски - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable за large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// користи \"agent/agent_definition.hudhud\";\n// користи \"constitution/laws.hudhud\";\n// користи \"data/note.hudhud\";\n// користи \"utils/math.hudhud\";\n", "module_concepts": "// Српски - Modules & Code Organization\n// Demonstrates module system: користи/увези like Rust, Java, C++, Python\n\n// Import math module\nкористи \"math.hudhud\";\n\n// Example syntax variations:\n// користи \"math.hudhud\";\n// користи { add, subtract } од \"math.hudhud\";\n// користи \"math.hudhud\" као math;\n\n// Using functions из math module\nнека sum = add(10, 5);\nштампај(sum);\n\nнека diff = subtract(20, 8);\nштампај(diff);\n\nнека product = multiply(4, 7);\nштампај(product);\n\nнека quotient = divide(15, 3);\nштампај(quotient);\n\nнека squared = square(5);\nштампај(squared);\n\nнека cubed = cube(3);\nштампај(cubed);\n\nнека absolute = abs(-42);\nштампај(absolute);\n\nнека maximum = max(100, 50);\nштампај(maximum);\n\nнека minimum = min(100, 50);\nштампај(minimum);\n\n// Complex calculation using multiple functions\nнека result = add(multiply(5, 3), divide(20, 4));\nштампај(result);\n", "switch_concepts": "// Српски - Switch/Case концепти\n// switch/case/default\n\nfunkcija тип_дана(day) {\n    odaberi (day) {\n        slučaj \"Monday\":\n        slučaj \"Tuesday\":\n        slučaj \"Wednesday\":\n        slučaj \"Thursday\":\n        slučaj \"Friday\":\n            vrati \"Радни дан\";\n        slučaj \"Saturday\":\n        slučaj \"Sunday\":\n            vrati \"Викенд\";\n        podrazumevano:\n            vrati \"Непознато\";\n    }\n}\n\nispiši(\"=== Day Types ===\");\nispiši(\"Monday: \" + тип_дана(\"Monday\"));\nispiši(\"Saturday: \" + тип_дана(\"Saturday\"));\nispiši(\"Holiday: \" + тип_дана(\"Holiday\"));\n\nfunkcija оцена_слово(score) {\n    odaberi (score) {\n        slučaj 90:\n            vrati \"A\";\n        slučaj 80:\n            vrati \"B\";\n        slučaj 70:\n            vrati \"C\";\n        slučaj 60:\n            vrati \"D\";\n        podrazumevano:\n            vrati \"F\";\n    }\n}\n\nispiši(\"\\n=== Grades ===\");\nispiši(\"90: \" + оцена_слово(90));\nispiši(\"70: \" + оцена_слово(70));\nispiši(\"50: \" + оцена_слово(50));\n\nfunkcija порука_статуса(code) {\n    odaberi (code) {\n        slučaj 200:\n            vrati \"OK\";\n        slučaj 404:\n            vrati \"Not Found\";\n        slučaj 500:\n            vrati \"Server Error\";\n        podrazumevano:\n            vrati \"Непознато Status\";\n    }\n}\n\nispiši(\"\\n=== HTTP Status ===\");\nispiši(\"200: \" + порука_статуса(200));\nispiši(\"404: \" + порука_статуса(404));\n", "event_concepts": "// Српски - Event Concepts\n\ndogađaj UserLogin {\n    ispiši(\"User logged in\");\n}\n\ndogađaj DataReceived {\n    ispiši(\"Data received\");\n}\n\ndogađaj ErrorOccurred {\n    ispiši(\"Error occurred\");\n}\n\nfunkcija on_login(username) {\n    ispiši(\"Login: \" + username);\n    vrati \"Welcome, \" + username;\n}\n\nfunkcija on_data(source) {\n    ispiši(\"Data from: \" + source);\n    vrati \"Processed: \" + source;\n}\n\nfunkcija on_error(message) {\n    ispiši(\"Error: \" + message);\n    vrati \"Handled: \" + message;\n}\n\nispiši(\"=== Event System ===\");\nneka r1 = on_login(\"admin\");\nispiši(r1);\nneka r2 = on_data(\"sensor_1\");\nispiši(r2);\nneka r3 = on_error(\"timeout\");\nispiši(r3);\n", "functions": "// Српски - Функције\n// Примери дефинисања и коришћења функција\n\n// Једноставна функција\nфункција поздрави() {\n    ispiši(\"Здраво Свете!\");\n}\n\n// Функција са параметрима\nфункција сабери(а, б) {\n    vrati а + б;\n}\n\n// Вишепараметарска функција\nфункција израчунај(број1, број2, операција) {\n    ako (операција == \"сабери\") {\n        vrati број1 + број2;\n    } inače {\n        vrati 0;\n    }\n}\n\n// Математичке функције\nфункција квадрат(x) {\n    vrati x * x;\n}\n\nфункција куб(x) {\n    vrati x * x * x;\n}\n\n// Коришћење функција\nпоздрави();\n\nнека резултат1 = сабери(5, 3);\nispiši(резултат1);\n\nнека резултат2 = израчунај(10, 5, \"сабери\");\nispiši(резултат2);\n\nнека резултат_квадрат = квадрат(4);\nispiši(резултат_квадрат);\n\nнека резултат_куб = куб(3);\nispiši(резултат_куб);\n\n// Композиција функција\nнека укупно = сабери(квадрат(3), куб(2));\nispiši(укупно);\n", "entity_concepts": "// Српски - Концепти ентитета\n\nнека корисник = {\n    ид: 1,\n    име: \"Ана\",\n    имејл: \"ana@primer.com\",\n    улога: \"програмер\"\n};\n\nнека производ = {\n    ид: 101,\n    име: \"ХудХудСкрипт ИДЕ\",\n    верзија: \"2.0\",\n    цена: 49\n};\n\nнека наруџбина = {\n    ид: 1001,\n    ид_корисника: 1,\n    ид_производа: 101,\n    количина: 2,\n    статус: \"потврђено\"\n};\n\nфункција инфо_ентитета(ентитет) {\n    vrati \"Ентитет #\" + ентитет.ид + \": \" + ентитет.име;\n}\n\nфункција израчунај_укупно(наруџбина, цена) {\n    vrati наруџбина.количина * цена;\n}\n\nispiši(\"=== Систем ентитета ===\");\nispiši(инфо_ентитета(корисник));\nispiši(инфо_ентитета(производ));\nнека укупно = израчунај_укупно(наруџбина, производ.цена);\nispiši(\"Наруџбина #\" + наруџбина.ид + \" укупно: \" + укупно);\nispiši(\"Статус: \" + наруџбина.статус);\n", "error_concepts": "// Српски - Error Concepts\n\nfunkcija validate_age(age) {\n    ako (age < 0) {\n        baci \"Invalid age: negative\";\n    }\n    ako (age > 150) {\n        baci \"Invalid age: too large\";\n    }\n    vrati age;\n}\n\nfunkcija validate_email(email) {\n    ako (email == \"\") {\n        baci \"Empty email\";\n    }\n    ispiši(\"Email valid: \" + email);\n    vrati email;\n}\n\nispiši(\"=== Validation ===\");\n\npokušaj {\n    validate_age(25);\n    ispiši(\"Age 25: valid\");\n} uhvati (error) {\n    ispiši(\"Error: \" + error);\n}\n\npokušaj {\n    validate_age(-5);\n} uhvati (error) {\n    ispiši(\"Error: \" + error);\n}\n\npokušaj {\n    validate_email(\"user@example.com\");\n    validate_email(\"\");\n} uhvati (error) {\n    ispiši(\"Email error: \" + error);\n} konačno {\n    ispiši(\"Validation complete\");\n}\n"}, "th": {"objects": "// ไทย - อ็อบเจกต์\n// อ็อบเจกต์ด้วยคำหลักภาษาไทย\n\n// สร้างอ็อบเจกต์\nให้ บุคคล = {\n    ชื่อ: \"อรุณ\",\n    อายุ: ๓๐,\n    เมือง: \"กรุงเทพ\"\n};\n\n// เข้าถึงคุณสมบัติ\nให้ ชื่อ = บุคคล.ชื่อ;\nให้ อายุ = บุคคล.อายุ;\n\n// ผลลัพธ์\nชื่อ;\n", "chemistry": "// TH - Chemistry Module\n\nฟังก์ชัน molarMass(atoms, atomicWeight) {\n    คืนค่า atoms * atomicWeight;\n}\n\nฟังก์ชัน concentration(moles, volume) {\n    คืนค่า moles / volume;\n}\n\nฟังก์ชัน pH(hydrogenConcentration) {\n    คืนค่า 14 - hydrogenConcentration;\n}\n\nฟังก์ชัน density(mass, volume) {\n    คืนค่า mass / volume;\n}\n\nฟังก์ชัน dilution(c1, v1, v2) {\n    คืนค่า (c1 * v1) / v2;\n}\n", "loops": "// ภาษาไทย - ลูป\nให้ ตัวนับ = 0;\nให้ สูงสุด = 5;\n\nขณะที่ (ตัวนับ < สูงสุด) {\n    พิมพ์(ตัวนับ);\n    ตัวนับ = ตัวนับ + 1;\n}\n\nพิมพ์(999);\n", "data_processing": "// ภาษาไทย - Data Processing\n// Using NATIVE ภาษาไทย keywords\n\nให้ value1 = 100;\nให้ value2 = 200;\nให้ value3 = 300;\n\nให้ total = value1+ value2+ value3;\nให้ average = total / 3;\n\nพิมพ์(total);\nพิมพ์(average);\n", "modules_import": "// TH - Modules Import Example\n\n// Import math module (direct access)\nใช้ \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nใช้ \"physics.hudhud\" เป็น fizik;\n\n// Import chemistry (direct access)\nใช้ \"chemistry.hudhud\";\n\n// Using math functions (direct)\nให้ sum = add(10, 5);\nพิมพ์(sum);\n\nให้ product = multiply(4, 7);\nพิมพ์(product);\n\n// Using physics functions (via alias: fizik.functionName)\nให้ f = fizik.force(10, 9.8);\nพิมพ์(f);\n\nให้ ke = fizik.kineticEnergy(5, 10);\nพิมพ์(ke);\n\n// Using chemistry functions (direct)\nให้ d = density(100, 50);\nพิมพ์(d);\n\nให้ c = concentration(2, 5);\nพิมพ์(c);\n", "return_concept": "// ภาษาไทย - แนวคิดการคืนค่า\n// return\n\nฟังก์ชัน กำลังสอง(x) {\n    คืน x * x;\n}\n\nฟังก์ชัน กำลังสาม(x) {\n    คืน x * x * x;\n}\n\nพิมพ์(\"=== Math Functions ===\");\nพิมพ์(\"กำลังสอง(5): \" + กำลังสอง(5));\nพิมพ์(\"กำลังสาม(3): \" + กำลังสาม(3));\n\nฟังก์ชัน ค่าสัมบูรณ์(x) {\n    ถ้า (x < 0) {\n        คืน -x;\n    }\n    คืน x;\n}\n\nพิมพ์(\"\\n=== Absolute ===\");\nพิมพ์(\"ค่าสัมบูรณ์(-7): \" + ค่าสัมบูรณ์(-7));\nพิมพ์(\"ค่าสัมบูรณ์(3): \" + ค่าสัมบูรณ์(3));\n\nฟังก์ชัน สร้าง_จุด(x, y) {\n    คืน { x: x, y: y };\n}\n\nให้ p = สร้าง_จุด(10, 20);\nพิมพ์(\"\\n=== Point ===\");\nพิมพ์(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nฟังก์ชัน แฟกทอเรียล(n) {\n    ถ้า (n <= 1) {\n        คืน 1;\n    }\n    คืน n * แฟกทอเรียล(n - 1);\n}\n\nพิมพ์(\"\\n=== Factorial ===\");\nพิมพ์(\"5! = \" + แฟกทอเรียล(5));\nพิมพ์(\"10! = \" + แฟกทอเรียล(10));\n", "customer_service": "// ภาษาไทย - ตัวแทนบริการลูกค้า\n// ใช้คำหลักภาษาไทย\n\nให้ คำทักทาย = \"สวัสดี ฉันช่วยอะไรคุณได้บ้าง?\";\nให้ คำตอบ = \"ฉันจะช่วยเหลือคำขอของคุณ\";\n\nพิมพ์(คำทักทาย);\nพิมพ์(คำตอบ);\n", "basic_example": "// ไทย - Basic Example with NATIVE keywords\nตัวแปร เอ็กซ์ = 10;\nตัวแปร วาย = 20;\nตัวแปร ผลรวม = เอ็กซ์ + วาย;\n\nพิมพ์(ผลรวม);\n", "physics": "// TH - Physics Module\n\nฟังก์ชัน speed(distance, time) {\n    คืนค่า distance / time;\n}\n\nฟังก์ชัน force(mass, acceleration) {\n    คืนค่า mass * acceleration;\n}\n\nฟังก์ชัน kineticEnergy(mass, velocity) {\n    คืนค่า 0.5 * mass * velocity * velocity;\n}\n\nฟังก์ชัน potentialEnergy(mass, gravity, height) {\n    คืนค่า mass * gravity * height;\n}\n\nฟังก์ชัน momentum(mass, velocity) {\n    คืนค่า mass * velocity;\n}\n", "error_handling": "// ภาษาไทย - การจัดการข้อผิดพลาด\n// try/catch/finally, throw\n\n// Basic try/catch\nฟังก์ชัน หาร(a, b) {\n    ถ้า (b == 0) {\n        โยน \"ข้อผิดพลาดหารด้วยศูนย์\";\n    }\n    คืน a / b;\n}\n\nลอง {\n    ให้ result = หาร(10, 2);\n    พิมพ์(\"10 / 2 = \" + result);\n} จับ (error) {\n    พิมพ์(\"ข้อผิดพลาด: \" + error);\n}\n\n// Try/catch/finally\nพิมพ์(\"\n=== การประมวลผลไฟล์ ===\");\n\nฟังก์ชัน ประมวลผล_ไฟล์(filename) {\n    ถ้า (filename == \"\") {\n        โยน \"ข้อผิดพลาดชื่อไฟล์ว่าง\";\n    }\n    พิมพ์(\"กำลังประมวลผล: \" + filename);\n    คืน \"ข้อมูลจาก \" + filename;\n}\n\nลอง {\n    ให้ data = ประมวลผล_ไฟล์(\"report.txt\");\n    พิมพ์(\"ผลลัพธ์: \" + data);\n} จับ (error) {\n    พิมพ์(\"ข้อผิดพลาด: \" + error);\n} ในที่สุด {\n    พิมพ์(\"เสร็จสิ้นการล้าง\");\n}\n\n// Nested error handling\nพิมพ์(\"\n=== การจัดการข้อผิดพลาดซ้อน ===\");\n\nลอง {\n    พิมพ์(\"บล็อกลองภายนอก\");\n    ลอง {\n        โยน \"ข้อผิดพลาดภายใน\";\n    } จับ (inner_err) {\n        พิมพ์(\"จับภายใน: \" + inner_err);\n        โยน \"ข้อผิดพลาดโยนซ้ำ\";\n    }\n} จับ (outer_err) {\n    พิมพ์(\"จับภายนอก: \" + outer_err);\n} ในที่สุด {\n    พิมพ์(\"เสร็จทั้งหมด\");\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici แพ็คเกจ kullanımı\nใช้ \"cebir\";\nใช้ \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nใช้ \"cebir/matris\";\nใช้ \"cebir/vektor\";\nใช้ \"fizik/hareket\";\n\nเขียน(\"============================================================\");\nเขียน(\"HudHudScript Paket Sistemi Demo\");\nเขียน(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nเขียน(\"📦 Cebir Paketi Kullanımı:\");\nเขียน(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nตัวแปร matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nตัวแปร matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nเขียน(\"Matris 1:\");\nmatris1.goster();\n\nเขียน(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nตัวแปร toplam = matris1.topla(matris2);\nเขียน(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nตัวแปร vektor1 = Vektor([1, 2, 3]);\nตัวแปร vektor2 = Vektor([4, 5, 6]);\n\nเขียน(\"\\n\\n📐 Vektör İşlemleri:\");\nเขียน(\"─────────────────────────────────────────────────────────\\n\");\n\nเขียน(\"Vektör 1: \" + vektor1.toString());\nเขียน(\"Vektör 2: \" + vektor2.toString());\n\nตัวแปร noktaSal = vektor1.noktaSal(vektor2);\nเขียน(\"Nokta Çarpım: \" + noktaSal);\n\nตัวแปร caprazCarpim = vektor1.caprazCarpim(vektor2);\nเขียน(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nเขียน(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nเขียน(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nตัวแปร baslangicHizi = 0;      // m/s\nตัวแปร ivme = 9.8;              // m/s² (yerçekimi)\nตัวแปร zaman = 5;               // saniye\n\nตัวแปร sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nตัวแปร mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nเขียน(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nเขียน(\"İvme: \" + ivme + \" m/s²\");\nเขียน(\"Zaman: \" + zaman + \" s\");\nเขียน(\"─────────────────────────────────────────────────────────\");\nเขียน(\"Son Hız: \" + sonHiz + \" m/s\");\nเขียน(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nเขียน(\"\\n\\n📝 Paket Oluşturma:\");\nเขียน(\"─────────────────────────────────────────────────────────\\n\");\n\nเขียน(\"1. hudhud.toml dosyası oluşturun:\");\nเขียน(\"   [package]\");\nเขียน(\"   name = 'matematik-utils'\");\nเขียน(\"   version = '1.0.0'\");\nเขียน(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nเขียน(\"\\n2. Bağımlılıklar ekleyin:\");\nเขียน(\"   [dependencies]\");\nเขียน(\"   cebir = '^2.0.0'\");\nเขียน(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nเขียน(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nเขียน(\"─────────────────────────────────────────────────────────\\n\");\n\nเขียน(\"Paket kurma:\");\nเขียน(\"  hudhudscript install cebir\");\nเขียน(\"  hudhudscript install fizik@1.5.0\");\n\nเขียน(\"\\nPaket güncelleme:\");\nเขียน(\"  hudhudscript update cebir\");\nเขียน(\"  hudhudscript update --all\");\n\nเขียน(\"\\nPaket kaldırma:\");\nเขียน(\"  hudhudscript remove cebir\");\n\nเขียน(\"\\nKurulu paketleri listeleme:\");\nเขียน(\"  hudhudscript list\");\n\nเขียน(\"\\nPaket arama:\");\nเขียน(\"  hudhudscript search matematik\");\n\nเขียน(\"\\nPaket bilgisi:\");\nเขียน(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nเขียน(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nเขียน(\"─────────────────────────────────────────────────────────\\n\");\n\nเขียน(\"Versiyon belirtme:\");\nเขียน(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nเขียน(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nเขียน(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nเขียน(\"\\nGit deposundan:\");\nเขียน(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nเขียน(\"\\nYerel yoldan:\");\nเขียน(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nเขียน(\"\\n\\n🔒 Paket Güvenliği:\");\nเขียน(\"─────────────────────────────────────────────────────────\\n\");\n\nเขียน(\"Güvenlik kontrolü:\");\nเขียน(\"  hudhudscript audit\");\n\nเขียน(\"\\nChecksum doğrulama:\");\nเขียน(\"  hudhudscript verify cebir\");\n\nเขียน(\"\\n============================================================\");\nเขียน(\"✓ Paket sistemi demo tamamlandı!\");\nเขียน(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nเขียน(\"============================================================\");\n", "arrays": "// ไทย - อาร์เรย์\n// อาร์เรย์ด้วยคำหลักภาษาไทย\n\n// สร้างอาร์เรย์\nให้ ตัวเลข = [๑, ๒, ๓, ๔, ๕];\nให้ ชื่อ = [\"อรุณ\", \"สมชาย\", \"มาลี\"];\n\n// เข้าถึงสมาชิก\nให้ แรก = ตัวเลข[๐];\nให้ ที่สอง = ตัวเลข[๑];\n\n// ผลลัพธ์\nแรก;\n", "math": "// TH - Math Module\n\nfunction add(a, b) {\n    คืนค่า a + b;\n}\n\nfunction subtract(a, b) {\n    คืนค่า a - b;\n}\n\nfunction multiply(a, b) {\n    คืนค่า a * b;\n}\n\nfunction divide(a, b) {\n    ถ้า (b == 0) {\n        พิมพ์(\"Error: Division by zero!\");\n        คืนค่า 0;\n    } มิฉะนั้น {\n        คืนค่า a / b;\n    }\n}\n\nfunction square(x) {\n    คืนค่า x * x;\n}\n\nfunction cube(x) {\n    คืนค่า x * x * x;\n}\n\nfunction abs(x) {\n    ถ้า (x < 0) {\n        คืนค่า -x;\n    } มิฉะนั้น {\n        คืนค่า x;\n    }\n}\n\nfunction max(a, b) {\n    ถ้า (a > b) {\n        คืนค่า a;\n    } มิฉะนั้น {\n        คืนค่า b;\n    }\n}\n\nfunction min(a, b) {\n    ถ้า (a < b) {\n        คืนค่า a;\n    } มิฉะนั้น {\n        คืนค่า b;\n    }\n}\n", "control_flow": "// ไทย - การควบคุมการไหล\nตัวแปร ตัวนับ = 0;\nตัวแปร สูงสุด = 5;\n\n// Loop\nขณะที่ (ตัวนับ < สูงสุด) {\n    ตัวนับ = ตัวนับ + 1;\n}\n\n// Conditional\nตัวแปร คะแนน = 85;\n\nถ้า (คะแนน >= 90) {\n    คะแนน;\n} มิฉะนั้น {\n    ถ้า (คะแนน >= 80) {\n        คะแนน;\n    } มิฉะนั้น {\n        คะแนน;\n    }\n}\n\nตัวนับ;\n", "state_machine": "// State Machine Example\nให้ state = \"initial\";\n\nถ้า (state == \"initial\") {\n    พิมพ์(\"Starting\");\n    state = \"running\";\n}\n\nพิมพ์(state);\n", "conditionals": "// ภาษาไทย - ตรรกะเงื่อนไข\nให้ คะแนน = 85;\n\nถ้า (คะแนน >= 90) {\n    พิมพ์(1000);\n} ไม่งั้น {\n    ถ้า (คะแนน >= 80) {\n        พิมพ์(2000);\n    } ไม่งั้น {\n        พิมพ์(3000);\n    }\n}\n\nพิมพ์(999);\n", "code_organization": "// ไทย - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable สำหรับ large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// ใช้ \"agent/agent_definition.hudhud\";\n// ใช้ \"constitution/laws.hudhud\";\n// ใช้ \"data/note.hudhud\";\n// ใช้ \"utils/math.hudhud\";\n", "module_concepts": "// ไทย - Modules & Code Organization\n// Demonstrates module system: ใช้/นำเข้า like Rust, Java, C++, Python\n\n// Import math module\nใช้ \"math.hudhud\";\n\n// Example syntax variations:\n// ใช้ \"math.hudhud\";\n// ใช้ { add, subtract } จาก \"math.hudhud\";\n// ใช้ \"math.hudhud\" เป็น math;\n\n// Using functions จาก math module\nให้ sum = add(10, 5);\nพิมพ์(sum);\n\nให้ diff = subtract(20, 8);\nพิมพ์(diff);\n\nให้ product = multiply(4, 7);\nพิมพ์(product);\n\nให้ quotient = divide(15, 3);\nพิมพ์(quotient);\n\nให้ squared = square(5);\nพิมพ์(squared);\n\nให้ cubed = cube(3);\nพิมพ์(cubed);\n\nให้ absolute = abs(-42);\nพิมพ์(absolute);\n\nให้ maximum = max(100, 50);\nพิมพ์(maximum);\n\nให้ minimum = min(100, 50);\nพิมพ์(minimum);\n\n// Complex calculation using multiple functions\nให้ result = add(multiply(5, 3), divide(20, 4));\nพิมพ์(result);\n", "switch_concepts": "// ภาษาไทย - แนวคิด Switch/Case\n// switch/case/default\n\nฟังก์ชัน ประเภท_วัน(day) {\n    เลือก (day) {\n        กรณี \"Monday\":\n        กรณี \"Tuesday\":\n        กรณี \"Wednesday\":\n        กรณี \"Thursday\":\n        กรณี \"Friday\":\n            คืน \"วันธรรมดา\";\n        กรณี \"Saturday\":\n        กรณี \"Sunday\":\n            คืน \"สุดสัปดาห์\";\n        ค่าเริ่มต้น:\n            คืน \"ไม่ทราบ\";\n    }\n}\n\nพิมพ์(\"=== Day Types ===\");\nพิมพ์(\"Monday: \" + ประเภท_วัน(\"Monday\"));\nพิมพ์(\"Saturday: \" + ประเภท_วัน(\"Saturday\"));\nพิมพ์(\"Holiday: \" + ประเภท_วัน(\"Holiday\"));\n\nฟังก์ชัน เกรด_ตัวอักษร(score) {\n    เลือก (score) {\n        กรณี 90:\n            คืน \"A\";\n        กรณี 80:\n            คืน \"B\";\n        กรณี 70:\n            คืน \"C\";\n        กรณี 60:\n            คืน \"D\";\n        ค่าเริ่มต้น:\n            คืน \"F\";\n    }\n}\n\nพิมพ์(\"\\n=== Grades ===\");\nพิมพ์(\"90: \" + เกรด_ตัวอักษร(90));\nพิมพ์(\"70: \" + เกรด_ตัวอักษร(70));\nพิมพ์(\"50: \" + เกรด_ตัวอักษร(50));\n\nฟังก์ชัน ข้อความ_สถานะ(code) {\n    เลือก (code) {\n        กรณี 200:\n            คืน \"OK\";\n        กรณี 404:\n            คืน \"Not Found\";\n        กรณี 500:\n            คืน \"Server Error\";\n        ค่าเริ่มต้น:\n            คืน \"ไม่ทราบ Status\";\n    }\n}\n\nพิมพ์(\"\\n=== HTTP Status ===\");\nพิมพ์(\"200: \" + ข้อความ_สถานะ(200));\nพิมพ์(\"404: \" + ข้อความ_สถานะ(404));\n", "event_concepts": "// ภาษาไทย - Event Concepts\n\nเหตุการณ์ UserLogin {\n    พิมพ์(\"User logged in\");\n}\n\nเหตุการณ์ DataReceived {\n    พิมพ์(\"Data received\");\n}\n\nเหตุการณ์ ErrorOccurred {\n    พิมพ์(\"Error occurred\");\n}\n\nฟังก์ชัน on_login(username) {\n    พิมพ์(\"Login: \" + username);\n    คืน \"Welcome, \" + username;\n}\n\nฟังก์ชัน on_data(source) {\n    พิมพ์(\"Data from: \" + source);\n    คืน \"Processed: \" + source;\n}\n\nฟังก์ชัน on_error(message) {\n    พิมพ์(\"Error: \" + message);\n    คืน \"Handled: \" + message;\n}\n\nพิมพ์(\"=== Event System ===\");\nให้ r1 = on_login(\"admin\");\nพิมพ์(r1);\nให้ r2 = on_data(\"sensor_1\");\nพิมพ์(r2);\nให้ r3 = on_error(\"timeout\");\nพิมพ์(r3);\n", "functions": "// ภาษาไทย - ฟังก์ชัน\n// ตัวอย่างการกำหนดและใช้งานฟังก์ชัน\n\n// ฟังก์ชันง่ายๆ\nฟังก์ชัน ทักทาย() {\n    พิมพ์(\"สวัสดีชาวโลก!\");\n}\n\n// ฟังก์ชันที่มีพารามิเตอร์\nฟังก์ชัน บวก(ก, ข) {\n    คืน ก + ข;\n}\n\n// ฟังก์ชันหลายพารามิเตอร์\nฟังก์ชัน คำนวณ(จำนวน๑, จำนวน๒, การดำเนินการ) {\n    ถ้า (การดำเนินการ == \"บวก\") {\n        คืน จำนวน๑ + จำนวน๒;\n    } ไม่งั้น {\n        คืน ๐;\n    }\n}\n\n// ฟังก์ชันคณิตศาสตร์\nฟังก์ชัน ยกกำลังสอง(ค) {\n    คืน ค * ค;\n}\n\nฟังก์ชัน ยกกำลังสาม(ค) {\n    คืน ค * ค * ค;\n}\n\n// ใช้งานฟังก์ชัน\nทักทาย();\n\nให้ ผลลัพธ์๑ = บวก(๕, ๓);\nพิมพ์(ผลลัพธ์๑);\n\nให้ ผลลัพธ์๒ = คำนวณ(๑๐, ๕, \"บวก\");\nพิมพ์(ผลลัพธ์๒);\n\nให้ ผลลัพธ์_ยกกำลังสอง = ยกกำลังสอง(๔);\nพิมพ์(ผลลัพธ์_ยกกำลังสอง);\n\nให้ ผลลัพธ์_ยกกำลังสาม = ยกกำลังสาม(๓);\nพิมพ์(ผลลัพธ์_ยกกำลังสาม);\n\n// การประกอบฟังก์ชัน\nให้ รวม = บวก(ยกกำลังสอง(๓), ยกกำลังสาม(๒));\nพิมพ์(รวม);\n", "entity_concepts": "// ภาษาไทย - แนวคิดเอนทิตี\n\nให้ ผู้ใช้ = {\n    รหัส: ๑,\n    ชื่อ: \"อรุณ\",\n    อีเมล: \"arun@tuayang.com\",\n    บทบาท: \"นักพัฒนา\"\n};\n\nให้ ผลิตภัณฑ์ = {\n    รหัส: ๑๐๑,\n    ชื่อ: \"ฮุดฮุดสคริปต์ ไอดีอี\",\n    เวอร์ชัน: \"๒.๐\",\n    ราคา: ๔๙\n};\n\nให้ คำสั่งซื้อ = {\n    รหัส: ๑๐๐๑,\n    รหัส_ผู้ใช้: ๑,\n    รหัส_ผลิตภัณฑ์: ๑๐๑,\n    จำนวน: ๒,\n    สถานะ: \"ยืนยันแล้ว\"\n};\n\nฟังก์ชัน ข้อมูล_เอนทิตี(เอนทิตี) {\n    คืน \"เอนทิตี #\" + เอนทิตี.รหัส + \": \" + เอนทิตี.ชื่อ;\n}\n\nฟังก์ชัน คำนวณ_รวม(คำสั่งซื้อ, ราคา) {\n    คืน คำสั่งซื้อ.จำนวน * ราคา;\n}\n\nพิมพ์(\"=== ระบบเอนทิตี ===\");\nพิมพ์(ข้อมูล_เอนทิตี(ผู้ใช้));\nพิมพ์(ข้อมูล_เอนทิตี(ผลิตภัณฑ์));\nให้ รวม = คำนวณ_รวม(คำสั่งซื้อ, ผลิตภัณฑ์.ราคา);\nพิมพ์(\"คำสั่งซื้อ #\" + คำสั่งซื้อ.รหัส + \" รวม: \" + รวม);\nพิมพ์(\"สถานะ: \" + คำสั่งซื้อ.สถานะ);\n", "error_concepts": "// ภาษาไทย - Error Concepts\n\nฟังก์ชัน validate_age(age) {\n    ถ้า (age < 0) {\n        โยน \"Invalid age: negative\";\n    }\n    ถ้า (age > 150) {\n        โยน \"Invalid age: too large\";\n    }\n    คืน age;\n}\n\nฟังก์ชัน validate_email(email) {\n    ถ้า (email == \"\") {\n        โยน \"Empty email\";\n    }\n    พิมพ์(\"Email valid: \" + email);\n    คืน email;\n}\n\nพิมพ์(\"=== Validation ===\");\n\nลอง {\n    validate_age(25);\n    พิมพ์(\"Age 25: valid\");\n} จับ (error) {\n    พิมพ์(\"Error: \" + error);\n}\n\nลอง {\n    validate_age(-5);\n} จับ (error) {\n    พิมพ์(\"Error: \" + error);\n}\n\nลอง {\n    validate_email(\"user@example.com\");\n    validate_email(\"\");\n} จับ (error) {\n    พิมพ์(\"Email error: \" + error);\n} ในที่สุด {\n    พิมพ์(\"Validation complete\");\n}\n"}, "tr": {"objects": "// Türkçe - Nesne Yönelimli Programlama (OOP)\n// HudHudScript'te nesne tabanlı programlama kalıpları\n\n// ============================================\n// 1. Temel Nesne Tanımlama\n// ============================================\n\nnesne Hayvan {\n    isim: \"Bilinmiyor\",\n    tür: \"Bilinmiyor\",\n    yaş: 0,\n    canlı: doğru\n}\n\nnesne Kedi {\n    isim: \"Tekir\",\n    tür: \"Kedi\",\n    yaş: 3,\n    canlı: doğru,\n    renk: \"turuncu\",\n    iç_mekan: doğru\n}\n\nyaz(\"=== Temel Nesneler ===\");\nyaz(Hayvan.isim);\nyaz(Kedi.isim + \" (\" + Kedi.tür + \") - \" + Kedi.yaş + \" yaşında\");\n\n// ============================================\n// 2. Fabrika Fonksiyonları (Constructor Pattern)\n// ============================================\n\nişlev ArabaOluştur(marka, model, yıl, renk) {\n    dön {\n        marka: marka,\n        model: model,\n        yıl: yıl,\n        renk: renk,\n        kilometre: 0,\n        çalışıyor: doğru\n    };\n}\n\ndeğişken araba1 = ArabaOluştur(\"Toyota\", \"Corolla\", 2024, \"beyaz\");\ndeğişken araba2 = ArabaOluştur(\"Honda\", \"Civic\", 2023, \"siyah\");\n\nyaz(\"\\n=== Fabrika Fonksiyonu ===\");\nyaz(araba1.marka + \" \" + araba1.model + \" - \" + araba1.renk);\nyaz(araba2.marka + \" \" + araba2.model + \" - \" + araba2.renk);\n\n// ============================================\n// 3. Davranış Fonksiyonları (Method Pattern)\n// ============================================\n\nişlev araba_bilgisi(araba) {\n    dön araba.marka + \" \" + araba.model + \" (\" + araba.yıl + \") \" + araba.renk;\n}\n\nişlev araba_sür(araba, mesafe) {\n    değişken yeni_km = araba.kilometre + mesafe;\n    yaz(araba.marka + \" \" + mesafe + \" km yol aldı. Toplam: \" + yeni_km + \" km\");\n    dön yeni_km;\n}\n\nişlev araba_yaşı(araba) {\n    dön 2024 - araba.yıl;\n}\n\nyaz(\"\\n=== Davranış Fonksiyonları ===\");\nyaz(araba_bilgisi(araba1));\naraba_sür(araba1, 150);\naraba_sür(araba1, 230);\nyaz(\"Araç yaşı: \" + araba_yaşı(araba1) + \" yıl\");\n\n// ============================================\n// 4. Nesne Kompozisyonu\n// ============================================\n\nişlev AdresOluştur(şehir, ilçe, mahalle) {\n    dön {\n        şehir: şehir,\n        ilçe: ilçe,\n        mahalle: mahalle\n    };\n}\n\nişlev KişiOluştur(isim, yaş, adres) {\n    dön {\n        isim: isim,\n        yaş: yaş,\n        adres: adres,\n        meslek: \"Belirtilmemiş\"\n    };\n}\n\ndeğişken ev_adresi = AdresOluştur(\"İstanbul\", \"Kadıköy\", \"Moda\");\ndeğişken kişi = KişiOluştur(\"Davut\", 28, ev_adresi);\n\nyaz(\"\\n=== Nesne Kompozisyonu ===\");\nyaz(kişi.isim + \" - \" + kişi.yaş + \" yaşında\");\nyaz(\"Adres: \" + kişi.adres.mahalle + \", \" + kişi.adres.ilçe + \"/\" + kişi.adres.şehir);\n\n// ============================================\n// 5. Koleksiyon ve Nesne Dizileri\n// ============================================\n\ndeğişken öğrenciler = [\n    KişiOluştur(\"Elif\", 20, AdresOluştur(\"Ankara\", \"Çankaya\", \"Kızılay\")),\n    KişiOluştur(\"Mehmet\", 22, AdresOluştur(\"İzmir\", \"Konak\", \"Alsancak\")),\n    KişiOluştur(\"Zeynep\", 21, AdresOluştur(\"Bursa\", \"Nilüfer\", \"Özlüce\"))\n];\n\nyaz(\"\\n=== Nesne Koleksiyonları ===\");\ndeğişken idx = 0;\niken (idx < 3) {\n    değişken öğrenci = öğrenciler[idx];\n    yaz(öğrenci.isim + \" - \" + öğrenci.adres.şehir);\n    idx = idx + 1;\n}\n\n// ============================================\n// 6. Hesaplama Nesnesi (Alışveriş Sepeti)\n// ============================================\n\nişlev SepetÖğesiOluştur(ürün, fiyat, adet) {\n    dön {\n        ürün: ürün,\n        fiyat: fiyat,\n        adet: adet\n    };\n}\n\nişlev toplam_fiyat(öğe) {\n    dön öğe.fiyat * öğe.adet;\n}\n\ndeğişken sepet = [\n    SepetÖğesiOluştur(\"Laptop\", 25000, 1),\n    SepetÖğesiOluştur(\"Mouse\", 500, 2),\n    SepetÖğesiOluştur(\"Klavye\", 1200, 1)\n];\n\nyaz(\"\\n=== Alışveriş Sepeti ===\");\ndeğişken genel_toplam = 0;\ndeğişken s = 0;\niken (s < 3) {\n    değişken öğe = sepet[s];\n    değişken tutar = toplam_fiyat(öğe);\n    yaz(öğe.ürün + \" x\" + öğe.adet + \" = \" + tutar + \" TL\");\n    genel_toplam = genel_toplam + tutar;\n    s = s + 1;\n}\nyaz(\"Genel Toplam: \" + genel_toplam + \" TL\");\n", "chemistry": "// Türkçe - Chemistry Module\n// Basic chemistry calculations\n\n// Molar Mass calculation (simplified)\nişlev molarMass(atoms, atomicWeight) {\n    dön atoms * atomicWeight;\n}\n\n// Concentration = Moles / Volume\nişlev concentration(moles, volume) {\n    dön moles / volume;\n}\n\n// pH calculation (simplified: -log[H+])\nişlev pH(hydrogenConcentration) {\n    dön 14 - hydrogenConcentration;\n}\n\n// Density = Mass / Volume\nişlev density(mass, volume) {\n    dön mass / volume;\n}\n\n// Dilution: C1*V1 = C2*V2\nişlev dilution(c1, v1, v2) {\n    dön (c1 * v1) / v2;\n}\n", "loops": "// Türkçe - Döngüler\n// Türkçe - Yerel anahtar kelimelerle döngüler\n\n// Basit döngü - 1'den 5'e kadar topla\ndeğişken toplam = 0;\ndeğişken sayaç = 1;\n\niken (sayaç <= 5) {\n    toplam = toplam + sayaç;\n    sayaç = sayaç + 1;\n}\n\ntoplam;\n", "data_processing": "// Türkçe - Veri İşleme\n// Türkçe - Yerel anahtar kelimelerle veri işleme\n\n// Veri tanımla\ndeğişken değer1 = 100;\ndeğişken değer2 = 200;\ndeğişken değer3 = 300;\n\n// Hesapla\ndeğişken toplam = değer1+ değer2+ değer3;\ndeğişken ortalama = toplam / 3;\n\n// Koşullu işleme\neğer (ortalama > 150) {\n    değişken durum_bilgisi = \"yüksek\";\n} değilse {\n    değişken durum_bilgisi = \"düşük\";\n}\n", "arrow_functions": "// Türkçe - Ok Fonksiyonları\n// Fonksiyonlar için modern, kısa sözdizimi\n\n// Ok fonksiyonu - kısa sözdizimi\ndeğişken topla = (a, b) => a + b;\ndeğişken çarp = (x, y) => x * y;\n\nyazdır(topla(5, 3));      // 8\nyazdır(çarp(4, 7)); // 28\n\n// Bloklu ok fonksiyonu\ndeğişken hesapla = (a, b) => {\n    değişken toplam = a + b;\n    değişken çarpım = a * b;\n    dön toplam + çarpım;\n};\n\ndeğişken sonuç = hesapla(5, 3);\nyazdır(sonuç);  // 23 (8 + 15)\n\n// Tek parametre (parantez gerekmez)\ndeğişken kare = x => x * x;\nyazdır(kare(6));  // 36\n\n// Parametresiz\ndeğişken selamla = () => \"Merhaba!\";\nyazdır(selamla());  // Merhaba!\n", "modules_import": "// Türkçe - Modül İçe Aktarma Örneği\n\n// Matematik modülünü içe aktar (cebir.topla() şeklinde erişilir)\n\"cebir.hudhud\" kullan\n\n// Fizik modülünü takma adla içe aktar (fizik.kuvvet() şeklinde)\n\"fizik.hudhud\" fizik olarak kullan\n\n// Kimya modülünü içe aktar (kimya.yogunluk() şeklinde erişilir)\n\"kimya.hudhud\" kullan\n\n// Matematik fonksiyonları (modül adı üzerinden)\ndeğişken toplam = cebir.topla(10, 5)\nyaz(toplam)\n\ndeğişken hesap = cebir.carp(4, 7)\nyaz(hesap)\n\n// Fizik fonksiyonları (takma ad: fizik)\ndeğişken f = fizik.kuvvet(10, 9.8)\nyaz(f)\n\ndeğişken ke = fizik.kinetikEnerji(5, 10)\nyaz(ke)\n\n// Kimya fonksiyonları (modül adı üzerinden)\ndeğişken d = kimya.yogunluk(100, 50)\nyaz(d)\n\ndeğişken c = kimya.konsantrasyon(2, 5)\nyaz(c)\n", "return_concept": "// Türkçe - Dönüş Kavramı\n// return\n\nişlev kare(x) {\n    dön x * x;\n}\n\nişlev küp(x) {\n    dön x * x * x;\n}\n\nyazdır(\"=== Math Functions ===\");\nyazdır(\"kare(5): \" + kare(5));\nyazdır(\"küp(3): \" + küp(3));\n\nişlev mutlak(x) {\n    eğer (x < 0) {\n        dön -x;\n    }\n    dön x;\n}\n\nyazdır(\"\\n=== Absolute ===\");\nyazdır(\"mutlak(-7): \" + mutlak(-7));\nyazdır(\"mutlak(3): \" + mutlak(3));\n\nişlev nokta_oluştur(x, y) {\n    dön { x: x, y: y };\n}\n\ndeğişken p = nokta_oluştur(10, 20);\nyazdır(\"\\n=== Point ===\");\nyazdır(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nişlev faktöriyel(n) {\n    eğer (n <= 1) {\n        dön 1;\n    }\n    dön n * faktöriyel(n - 1);\n}\n\nyazdır(\"\\n=== Factorial ===\");\nyazdır(\"5! = \" + faktöriyel(5));\nyazdır(\"10! = \" + faktöriyel(10));\n", "customer_service": "// Türkçe - Müşteri Hizmetleri Ajanı\n\nyasa saygi_yasasi {\n    açıklama: \"Ajan nazik ve saygılı olmalıdır\",\n    öncelik: 1\n}\n\nanayasa hizmet_anayasasi {\n    yasalar: [saygi_yasasi],\n    açıklama: \"Müşteri hizmetleri çerçevesi\"\n}\n\najan hizmet_ajanı {\n    model: \"gpt-4\"\n}\n\nişlev karşıla(müşteri_adı) {\n    değişken mesaj = \"Merhaba \" + müşteri_adı + \", size nasıl yardımcı olabilirim?\";\n    yazdır(mesaj);\n    dön mesaj;\n}\n\nişlev talep_işle(tür, detay) {\n    eğer (tür == \"şikayet\") {\n        yazdır(\"Rahatsızlık için özür dilerim. Sorununuzu çözmek için buradayım.\");\n    } değilse {\n        yazdır(\"İletişime geçtiğiniz için teşekkürler. Talebinizi şimdi işliyorum.\");\n    }\n    dön \"İşlendi: \" + tür + \" - \" + detay;\n}\n\nyazdır(\"=== Müşteri Hizmetleri Ajanı ===\");\nkarşıla(\"Ahmet\");\ndeğişken sonuç = talep_işle(\"şikayet\", \"kargo gecikmesi\");\nyazdır(sonuç);\n", "ide": "// HudHud IDE Modülü - Dosya ve Proje Yönetimi\n\n// Dosya işlemleri\nişlev dosya_oku(yol) {\n    yaz(\"Dosya okunuyor: \" + yol);\n    dön {\n        yol: yol,\n        içerik: \"// Dosya içeriği buraya gelecek\",\n        satırlar: 42,\n        boyut: \"1.2 KB\"\n    };\n}\n\nişlev dosya_yaz(yol, içerik) {\n    yaz(\"Dosya kaydediliyor: \" + yol);\n    dön {\n        başarılı: doğru,\n        mesaj: \"Dosya başarıyla kaydedildi\"\n    };\n}\n\nişlev dosya_sil(yol) {\n    yaz(\"Dosya siliniyor: \" + yol);\n    dön {\n        başarılı: doğru,\n        mesaj: \"Dosya silindi\"\n    };\n}\n\n// Klasör işlemleri\nişlev klasör_oluştur(yol) {\n    yaz(\"Klasör oluşturuluyor: \" + yol);\n    dön {\n        başarılı: doğru,\n        yol: yol\n    };\n}\n\nişlev klasör_listele(yol) {\n    yaz(\"Klasör listeleniyor: \" + yol);\n    dön [\n        { isim: \"main.hudhud\", tür: \"dosya\", boyut: \"1.2 KB\" },\n        { isim: \"src\", tür: \"klasör\", boyut: \"-\" },\n        { isim: \"tests\", tür: \"klasör\", boyut: \"-\" }\n    ];\n}\n\n// Kod çalıştırma\nişlev kod_kontrol(kod) {\n    yaz(\"Syntax kontrolü yapılıyor...\");\n    dön {\n        başarılı: doğru,\n        hatalar: [],\n        uyarılar: []\n    };\n}\n\nişlev kod_derle(kod) {\n    yaz(\"Kod derleniyor...\");\n    dön {\n        başarılı: doğru,\n        bytecode: \"0x4844534352495054\",\n        boyut: \"2.5 KB\"\n    };\n}\n\nişlev kod_çalıştır(kod) {\n    yaz(\"Kod çalıştırılıyor...\");\n    dön {\n        başarılı: doğru,\n        çıktı: \"Program başarıyla çalıştı!\",\n        süre: \"0.15s\"\n    };\n}\n\n// Proje yönetimi\nişlev proje_oluştur(isim, açıklama) {\n    yaz(\"Yeni proje oluşturuluyor: \" + isim);\n    \n    değişken proje = {\n        isim: isim,\n        açıklama: açıklama,\n        versiyon: \"1.0.0\",\n        yazar: \"HudHud Developer\",\n        oluşturma_tarihi: \"2024-03-07\",\n        dosyalar: [],\n        bağımlılıklar: {}\n    };\n    \n    // Ana dosyayı oluştur\n    dosya_yaz(isim + \"/main.hudhud\", \"// Ana dosya\");\n    \n    // package.json oluştur\n    dosya_yaz(isim + \"/package.json\", \"package config\");\n    \n    dön proje;\n}\n\nişlev paket_oluştur(proje_yolu) {\n    yaz(\"Paket oluşturuluyor...\");\n    \n    değişken dosyalar = klasör_listele(proje_yolu);\n    değişken paket_ismi = proje_yolu + \"-1.0.0.hudhudpkg\";\n    \n    yaz(\"Paket oluşturuldu: \" + paket_ismi);\n    \n    dön {\n        başarılı: doğru,\n        paket: paket_ismi,\n        boyut: \"15.3 KB\",\n        dosya_sayısı: dosyalar.length\n    };\n}\n\n// Git işlemleri\nişlev kaydet_degisiklik(mesaj) {\n    yaz(\"Commit yapılıyor: \" + mesaj);\n    dön {\n        başarılı: doğru,\n        kod: \"a1b2c3d\",\n        mesaj: mesaj\n    };\n}\n\nişlev yukle_degisiklik(branch) {\n    yaz(\"Push yapılıyor: \" + branch);\n    dön {\n        başarılı: doğru,\n        branch: branch,\n        commits: 1\n    };\n}\n\n// Terminal işlemleri\nişlev terminal_komut_çalıştır(komut) {\n    yaz(\"$ \" + komut);\n    \n    eğer (komut == \"ls\") {\n        dön \"main.hudhud package.json src tests\";\n    } değilse ama (komut == \"pwd\") {\n        dön \"/home/user/my-project\";\n    } değilse {\n        dön \"Komut çalıştırıldı: \" + komut;\n    }\n}\n\n// Arama ve değiştirme\nişlev dosyalarda_ara(arama_metni, klasör) {\n    yaz(\"Aranıyor: \" + arama_metni);\n    \n    dön [\n        { dosya: \"main.hudhud\", satır: 5, içerik: \"yaz kodu\" },\n        { dosya: \"src/utils.hudhud\", satır: 12, içerik: \"yaz kodu\" }\n    ];\n}\n\nişlev dosyalarda_değiştir(eski, yeni, klasör) {\n    yaz(\"Değiştiriliyor: \" + eski + \" -> \" + yeni);\n    \n    dön {\n        başarılı: doğru,\n        değişen_dosya: 3,\n        toplam_değişiklik: 7\n    };\n}\n\n// Örnek kullanım\nyaz(\"=== HudHud IDE Modülü ===\\n\");\n\n// Yeni proje oluştur\ndeğişken proje = proje_oluştur(\"my-app\", \"Harika bir uygulama\");\nyaz(\"Proje oluşturuldu: \" + proje.isim);\n\n// Dosya oku\ndeğişken dosya = dosya_oku(\"my-app/main.hudhud\");\nyaz(\"Dosya okundu: \" + dosya.satırlar + \" satır\");\n\n// Kod kontrol et\ndeğişken kontrol = kod_kontrol(\"yaz('test');\");\neğer (kontrol.başarılı) {\n    yaz(\"Syntax kontrolü başarılı\");\n}\n\n// Kod derle\ndeğişken derleme = kod_derle(\"yaz('test');\");\neğer (derleme.başarılı) {\n    yaz(\"Derleme başarılı: \" + derleme.boyut);\n}\n\n// Kod çalıştır\ndeğişken çalıştırma = kod_çalıştır(\"yaz('Merhaba Dünya!');\");\neğer (çalıştırma.başarılı) {\n    yaz(\"Çalıştırma başarılı: \" + çalıştırma.süre);\n}\n\n// Paket oluştur\ndeğişken paket = paket_oluştur(\"my-app\");\nyaz(\"Paket: \" + paket.paket + \" (\" + paket.boyut + \")\");\n\n// Git commit\ndeğişken kayit_sonuc = kaydet_degisiklik(\"feat: ilk commit\");\nyaz(\"Kayit: \" + kayit_sonuc.kod);\n\n// Dosyalarda ara\ndeğişken sonuçlar = dosyalarda_ara(\"yaz\", \"my-app\");\nyaz(\"Arama sonuçları: \" + sonuçlar.length + \" eşleşme\");\n\nyaz(\"IDE modülü hazır!\");\n", "basic_example": "// Türkçe - Temel Örnek\n// Türkçe - Yerel anahtar kelimelerle temel örnek\n\ndeğişken a = 10;\ndeğişken b = 20;\ndeğişken toplam = a + b;\n\nyaz(\"Birinci Toplam : \" + toplam);\n\ndeğişken d1 = 79;\ndeğişken d2 = 21;\ndeğişken toplam = d1 + d2;\n\nyaz(\"İkinci Toplam : \" + toplam);\n\ndeğişken test1 = 770;\ndeğişken test2 = 230;\ntoplam = test1 + test2;\n\nyaz(\"Üçüncü Toplam : \" + toplam);\n\n\n\n\n", "physics": "// Türkçe - Physics Module\n// Basic physics calculations\n\n// Speed = Distance / Time\nişlev speed(distance, time) {\n    dön distance / time;\n}\n\n// Force = Mass * Acceleration\nişlev force(mass, acceleration) {\n    dön mass * acceleration;\n}\n\n// Kinetic Energy = 0.5 * Mass * Velocity^2\nişlev kineticEnergy(mass, velocity) {\n    dön 0.5 * mass * velocity * velocity;\n}\n\n// Potential Energy = Mass * Gravity * Height\nişlev potentialEnergy(mass, gravity, height) {\n    dön mass * gravity * height;\n}\n\n// Momentum = Mass * Velocity\nişlev momentum(mass, velocity) {\n    dön mass * velocity;\n}\n", "fizik": "// Türkçe - Physics Module\n\nişlev hiz(uzaklık, zaman) {\n    dön uzaklık / zaman;\n}\n\nişlev kuvvet(kütle, ivme) {\n    dön kütle * ivme;\n}\n\nişlev kinetikEnerji(kütle, hız) {\n    dön 0.5 * kütle * hız * hız;\n}\n\nişlev potansiyelEnerji(kütle, yerçekimi, yükseklik) {\n    dön kütle * yerçekimi * yükseklik;\n}\n\nişlev momentum(kütle, hız) {\n    dön kütle * hız;\n}\n", "constants": "// Türkçe - Sabitler (Constants)\n\n// Sabit tanımlama - değiştirilemez\nsabit PI = 3.14159;\nsabit MAKSIMUM_DENEME = 3;\nsabit UYGULAMA_ADI = \"HudHudScript\";\n\nyaz(PI);\nyaz(MAKSIMUM_DENEME);\nyaz(UYGULAMA_ADI);\n\n// Sabit ile hesaplama\nsabit YARICAP = 5;\ndeğişken alan = PI * YARICAP * YARICAP;\nyaz(alan);\n\n// Sabit dizi\nsabit RENKLER = [\"kırmızı\", \"yeşil\", \"mavi\"];\nyaz(RENKLER);\n\n// Sabit nesne\nsabit AYARLAR = {\n    dil: \"tr\",\n    tema: \"koyu\",\n    bildirimler: doğru\n};\nyaz(AYARLAR);\n\n// HATA: Sabit değiştirilemez\n// PI = 3.14;  // Bu hata verir!\n", "error_handling": "// Türkçe - Hata Yönetimi\n// Basit hata kontrolü ile hata yönetimi\n\n// Hata durumunu kontrol eden işlev\nişlev böl(a, b) {\n    eğer (b == 0) {\n        dön { hata: doğru, mesaj: \"Sıfıra bölme hatası\", değer: 0 };\n    }\n    dön { hata: yanlış, mesaj: \"\", değer: a / b };\n}\n\nyazdır(\"=== Bölme İşlemi ===\");\n\n// İlk bölme\nyazdır(\"10 / 2 işlemi:\");\ndeğişken sonuç1 = böl(10, 2);\neğer (sonuç1.hata) {\n    yazdır(\"Hata: \" + sonuç1.mesaj);\n} değilse {\n    yazdır(\"10 / 2 = \" + sonuç1.değer);\n}\n\n// Sıfıra bölme\nyazdır(\"10 / 0 işlemi:\");\ndeğişken sonuç2 = böl(10, 0);\neğer (sonuç2.hata) {\n    yazdır(\"Hata yakalandı: \" + sonuç2.mesaj);\n} değilse {\n    yazdır(\"Sonuç: \" + sonuç2.değer);\n}\n\n// Dosya işleme benzeri örnek\nyazdır(\"=== Dosya İşleme ===\");\n\nişlev dosya_isle(filename) {\n    eğer (filename == \"\") {\n        dön { başarılı: yanlış, mesaj: \"Boş dosya adı hatası\" };\n    }\n    yazdır(\"İşleniyor: \" + filename);\n    dön { başarılı: doğru, veri: \"Veri kaynağı \" + filename };\n}\n\ndeğişken dosya_sonuç = dosya_isle(\"report.txt\");\neğer (dosya_sonuç.başarılı) {\n    yazdır(\"Sonuç: \" + dosya_sonuç.veri);\n} değilse {\n    yazdır(\"Hata: \" + dosya_sonuç.mesaj);\n}\n\nyazdır(\"Hepsi tamam\");\n", "math_functions": "// Türkçe - Matematik Fonksiyonları\n\n// Temel matematik sabitleri\nyaz(Matematik.PI);\nyaz(Matematik.E);\n\n// Mutlak değer\nyaz(Matematik.mutlak(-42));  // 42\n\n// Karekök\nyaz(Matematik.karekök(16));  // 4\nyaz(Matematik.karekök(2));   // 1.414...\n\n// Küpkök\nyaz(Matematik.küpkök(27));   // 3\nyaz(Matematik.küpkök(8));    // 2\n\n// Üs alma (power)\nyaz(Matematik.üs(2, 3));     // 8 (2^3)\nyaz(Matematik.üs(3, 2));     // 9 (3^2)\nyaz(Matematik.üs(10, 3));    // 1000\n\n// Faktöriyel\nyaz(Matematik.faktöriyel(5));  // 120\nyaz(Matematik.faktöriyel(3));  // 6\nyaz(Matematik.faktöriyel(10)); // 3628800\n\n// Yuvarlama\nyaz(Matematik.yuvarla(3.7)); // 4\nyaz(Matematik.yukarı(3.2));  // 4\nyaz(Matematik.aşağı(3.9));   // 3\n\n// Min ve Max\nyaz(Matematik.min(5, 10));   // 5\nyaz(Matematik.maks(5, 10));  // 10\n\n// Trigonometri\nyaz(Matematik.sin(Matematik.PI / 2));  // 1\nyaz(Matematik.cos(0));                  // 1\nyaz(Matematik.tan(Matematik.PI / 4));  // 1\n\n// Logaritma\nyaz(Matematik.log(10));      // 2.302...\nyaz(Matematik.log10(100));   // 2\n\n// Rastgele sayı\nyaz(Matematik.rastgele());   // 0 ile 1 arası\n\n// Kısaltma: Mat.\nyaz(Mat.karekök(25));        // 5\nyaz(Mat.üs(2, 10));          // 1024\nyaz(Mat.faktöriyel(7));      // 5040\n", "loops_advanced": "// Türkçe - Gelişmiş Döngüler (Advanced Loops)\n\n// While döngüsü\ndeğişken sayaç = 0;\niken (sayaç < 5) {\n    yaz(sayaç);\n    sayaç = sayaç + 1;\n}\n\n// Koşullu döngü\ndeğişken toplam = 0;\ndeğişken i = 1;\niken (i <= 10) {\n    toplam = toplam + i;\n    i = i + 1;\n}\nyaz(toplam);\n\n// İç içe döngüler\ndeğişken x = 1;\niken (x <= 3) {\n    değişken y = 1;\n    iken (y <= 3) {\n        yaz(x * y);\n        y = y + 1;\n    }\n    x = x + 1;\n}\n\n// Break ve devam\ndeğişken sayı = 1;\niken (sayı <= 10) {\n    eğer (sayı == 5) {\n        sayı = sayı + 1;\n        devam;\n    }\n    eğer (sayı == 8) {\n        kır;\n    }\n    yaz(sayı);\n    sayı = sayı + 1;\n}\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici paket kullanımı\nkullan \"cebir\";\nkullan \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nkullan \"cebir/matris\";\nkullan \"cebir/vektor\";\nkullan \"fizik/hareket\";\n\nyaz(\"============================================================\");\nyaz(\"HudHudScript Paket Sistemi Demo\");\nyaz(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nyaz(\"📦 Cebir Paketi Kullanımı:\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\ndeğişken matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\ndeğişken matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nyaz(\"Matris 1:\");\nmatris1.goster();\n\nyaz(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\ndeğişken toplam = matris1.topla(matris2);\nyaz(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\ndeğişken vektor1 = Vektor([1, 2, 3]);\ndeğişken vektor2 = Vektor([4, 5, 6]);\n\nyaz(\"\\n\\n📐 Vektör İşlemleri:\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\nyaz(\"Vektör 1: \" + vektor1.toString());\nyaz(\"Vektör 2: \" + vektor2.toString());\n\ndeğişken noktaSal = vektor1.noktaSal(vektor2);\nyaz(\"Nokta Çarpım: \" + noktaSal);\n\ndeğişken caprazCarpim = vektor1.caprazCarpim(vektor2);\nyaz(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nyaz(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\ndeğişken baslangicHizi = 0;      // m/s\ndeğişken ivme = 9.8;              // m/s² (yerçekimi)\ndeğişken zaman = 5;               // saniye\n\ndeğişken sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\ndeğişken mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nyaz(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nyaz(\"İvme: \" + ivme + \" m/s²\");\nyaz(\"Zaman: \" + zaman + \" s\");\nyaz(\"─────────────────────────────────────────────────────────\");\nyaz(\"Son Hız: \" + sonHiz + \" m/s\");\nyaz(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nyaz(\"\\n\\n📝 Paket Oluşturma:\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\nyaz(\"1. hudhud.toml dosyası oluşturun:\");\nyaz(\"   [package]\");\nyaz(\"   name = 'matematik-utils'\");\nyaz(\"   version = '1.0.0'\");\nyaz(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nyaz(\"\\n2. Bağımlılıklar ekleyin:\");\nyaz(\"   [dependencies]\");\nyaz(\"   cebir = '^2.0.0'\");\nyaz(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nyaz(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\nyaz(\"Paket kurma:\");\nyaz(\"  hudhudscript install cebir\");\nyaz(\"  hudhudscript install fizik@1.5.0\");\n\nyaz(\"\\nPaket güncelleme:\");\nyaz(\"  hudhudscript update cebir\");\nyaz(\"  hudhudscript update --all\");\n\nyaz(\"\\nPaket kaldırma:\");\nyaz(\"  hudhudscript remove cebir\");\n\nyaz(\"\\nKurulu paketleri listeleme:\");\nyaz(\"  hudhudscript list\");\n\nyaz(\"\\nPaket arama:\");\nyaz(\"  hudhudscript search matematik\");\n\nyaz(\"\\nPaket bilgisi:\");\nyaz(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nyaz(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\nyaz(\"Versiyon belirtme:\");\nyaz(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nyaz(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nyaz(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nyaz(\"\\nGit deposundan:\");\nyaz(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nyaz(\"\\nYerel yoldan:\");\nyaz(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nyaz(\"\\n\\n🔒 Paket Güvenliği:\");\nyaz(\"─────────────────────────────────────────────────────────\\n\");\n\nyaz(\"Güvenlik kontrolü:\");\nyaz(\"  hudhudscript audit\");\n\nyaz(\"\\nChecksum doğrulama:\");\nyaz(\"  hudhudscript verify cebir\");\n\nyaz(\"\\n============================================================\");\nyaz(\"✓ Paket sistemi demo tamamlandı!\");\nyaz(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nyaz(\"============================================================\");\n", "arrays": "// Türkçe - Diziler\n// Türkçe - Yerel anahtar kelimelerle diziler\n\n// Dizi oluştur\ndeğişken sayılar = [1, 2, 3, 4, 5];\ndeğişken isimler = [\"Davut\", \"Ayşe\", \"Mehmet\"];\n\n// Elemanlara eriş\ndeğişken ilk = sayılar[0];\ndeğişken ikinci = sayılar[1];\n\n// Boş dizi\ndeğişken liste = [];\n", "math": "// Türkçe - Math Module\n// Basic mathematical operations\n\n// Addition\nişlev add(a, b) {\n    dön a + b;\n}\n\n// Subtraction\nişlev subtract(a, b) {\n    dön a - b;\n}\n\n// Multiplication\nişlev multiply(a, b) {\n    dön a * b;\n}\n\n// Division\nişlev divide(a, b) {\n    eğer (b == 0) {\n        yaz(\"Error: Division by zero!\");\n        dön 0;\n    } değilse {\n        dön a / b;\n    }\n}\n\n// Square\nişlev square(x) {\n    dön x * x;\n}\n\n// Cube\nişlev cube(x) {\n    dön x * x * x;\n}\n\n// Absolute value\nişlev abs(x) {\n    eğer (x < 0) {\n        dön -x;\n    } değilse {\n        dön x;\n    }\n}\n\n// Maximum of two numbers\nişlev max(a, b) {\n    eğer (a > b) {\n        dön a;\n    } değilse {\n        dön b;\n    }\n}\n\n// Minimum of two numbers\nişlev min(a, b) {\n    eğer (a < b) {\n        dön a;\n    } değilse {\n        dön b;\n    }\n}\n", "control_flow": "// Türkçe - Kontrol Akışı\ndeğişken sayaç = 0;\ndeğişken maksimum = 5;\n\n// Döngü (iken) - Türkçe doğal sözdizimi\niken (sayaç < maksimum) {\n    sayaç = sayaç + 1;\n}\n\n// Koşul - Türkçe doğal sözdizimi: eğer ... ise\ndeğişken puan = 85;\ndeğişken sonuç = \"\";\n\neğer (puan >= 90) {\n    sonuç = \"Mükemmel\";\n} değilse {\n    eğer (puan >= 80) {\n        sonuç = \"İyi\";\n    } değilse {\n        sonuç = \"Geçer\";\n    }\n}\n\nyaz(sonuç);\n\ndeğişken farklıBirSonuç = \"\";\n\neğer (puan == 100) {\n    farklıBirSonuç = \"Süper!\";\n} değilse ama (puan >= 90 && puan < 100) {\n    farklıBirSonuç = \"Çok iyi\";\n} değilse ama (puan >= 80 && puan < 90) {\n    farklıBirSonuç = \"iyi\";\n} değilse ama (puan >= 70 && puan < 80) {\n    farklıBirSonuç = \"İyi olabilir\";\n} değilse ama (puan >= 40 && puan < 70) {\n    farklıBirSonuç = \"Ortalama\";\n}değilse ama (puan >= 10 && puan < 40) {\n    farklıBirSonuç = \"Daha çok çalışmalısın\";\n}hiçbiri değilse {\n    farklıBirSonuç = \"Ya çalışmadın ya da öğretmenin öğretememiş.\";\n}\n\nyaz(farklıBirSonuç);\n\n", "test_module_import": "// Test module içe_aktar\n\"cebir.hudhud\" kullan;\n\ndeğişken sonuc = topla(10, 5);\nyaz(sonuc);\n", "state_machine": "// State Machine Example\ndeğişken state = \"initial\";\n\neğer (state == \"initial\") {\n    yaz(\"Starting\");\n    state = \"running\";\n}\n\nyaz(state);\n", "kimya": "// Türkçe - Chemistry Module\n\nişlev molarKutle(atomlar, atomAğırlığı) {\n    dön atomlar * atomAğırlığı;\n}\n\nişlev konsantrasyon(mol, hacim) {\n    dön mol / hacim;\n}\n\nişlev pH(hydrogenConcentration) {\n    dön 14 - hydrogenConcentration;\n}\n\nişlev yogunluk(kütle, hacim) {\n    dön kütle / hacim;\n}\n\nişlev seyreltme(c1, v1, v2) {\n    dön (c1 * v1) / v2;\n}\n", "conditionals": "// Türkçe - Koşullu Mantık\ndeğişken puan = 85;\n\neğer (puan >= 90) {\n    puan;\n} değilse {\n    eğer (puan >= 80) {\n        puan;\n    } değilse {\n        puan;\n    }\n}\n", "code_organization": "// E-Ticaret Sistemi - Modüler Kod Organizasyonu\n// Function-based modüler mimari\n\nyaz(\"============================================================\");\nyaz(\"E-Ticaret Sistemi - Modüler Kod Organizasyonu\");\nyaz(\"============================================================\\n\");\n\n//\n// MODELS - Veri Modelleri\n//\n\n// src/models/user.hudhud\nişlev userOlustur(name, email, password) {\n    dön {\n        id: Math.floor(Math.random() * 10000),\n        name: name,\n        email: email,\n        password: password,\n        createdAt: \"2024-03-07\"\n    };\n}\n\nişlev userBilgi(user) {\n    dön \"User #\" + user.id + \": \" + user.name + \" (\" + user.email + \")\";\n}\n\n// src/models/product.hudhud\nişlev productOlustur(name, price, stock, category) {\n    dön {\n        id: Math.floor(Math.random() * 10000),\n        name: name,\n        price: price,\n        stock: stock,\n        category: category\n    };\n}\n\nişlev productBilgi(product) {\n    dön product.name + \" - \" + product.price + \" TL (Stok: \" + product.stock + \", Kategori: \" + product.category + \")\";\n}\n\nişlev productStokta(product) {\n    dön product.stock > 0;\n}\n\n// src/models/order.hudhud\nişlev orderOlustur(userId, productId, quantity, totalPrice) {\n    dön {\n        id: Math.floor(Math.random() * 10000),\n        userId: userId,\n        productId: productId,\n        quantity: quantity,\n        totalPrice: totalPrice,\n        status: \"pending\",\n        createdAt: \"2024-03-07\"\n    };\n}\n\nişlev orderBilgi(order) {\n    dön \"Siparis #\" + order.id + \" - Kullanici: \" + order.userId + \", Urun: \" + order.productId + \", Adet: \" + order.quantity + \", Toplam: \" + order.totalPrice + \" TL, Durum: \" + order.status;\n}\n\n//\n// SERVICES - Is Mantigi Servisleri\n//\n\n// src/services/auth.hudhud\nişlev authKaydet(user) {\n    dön {\n        success: doğru,\n        userId: user.id,\n        message: \"Kullanici basariyla kaydedildi\"\n    };\n}\n\nişlev authGiris(email, password) {\n    dön {\n        success: doğru,\n        token: \"token_\" + Math.floor(Math.random() * 1000),\n        message: \"Giris basarili\"\n    };\n}\n\n// src/services/payment.hudhud\nişlev odemeIsle(orderId, amount, method) {\n    değişken success = doğru;\n    eğer (success) {\n        dön {\n            success: doğru,\n            transactionId: \"TXN_\" + Math.floor(Math.random() * 100000),\n            amount: amount,\n            method: method,\n            message: \"Odeme basarili\"\n        };\n    } değilse {\n        dön {\n            success: yanlış,\n            error: \"Odeme basarisiz\"\n        };\n    }\n}\n\n// src/services/notification.hudhud\nişlev bildirimGonder(to, subject, message) {\n    yaz(\"   Email gonderildi:\");\n    yaz(\"      Kime: \" + to);\n    yaz(\"      Konu: \" + subject);\n    yaz(\"      Mesaj: \" + message);\n    dön doğru;\n}\n\n//\n// UTILS - Yardimci Fonksiyonlar\n//\n\n// src/utils/validation.hudhud\nişlev emailGecerli(email) {\n    dön email.length > 5;\n}\n\nişlev sifreGecerli(password) {\n    dön password.length >= 6;\n}\n\nişlev fiyatGecerli(price) {\n    dön price > 0;\n}\n\n// src/utils/formatting.hudhud\nişlev paraBirimi(amount, currency) {\n    eğer (currency == \"TRY\") {\n        dön amount + \" TL\";\n    } değilse {\n        eğer (currency == \"USD\") {\n            dön \"$\" + amount;\n        } değilse {\n            dön amount + \" \" + currency;\n        }\n    }\n}\n\n//\n// MAIN - Uygulama Akisi\n//\n\nyaz(\"1. KULLANICI KAYDI\");\nyaz(\"-----------------------------------------------------------\\n\");\n\n// Yeni kullanici olustur\ndeğişken newUser = userOlustur(\"Davut Suleyman\", \"davut@example.com\", \"guvenli123\");\nyaz(\"Kullanici olusturuldu: \" + userBilgi(newUser));\n\n// Email dogrula\neğer (emailGecerli(newUser.email)) {\n    yaz(\"OK Email gecerli: \" + newUser.email);\n} değilse {\n    yaz(\"HATA Email gecersiz\");\n}\n\n// Kullaniciyi kaydet\ndeğişken authResult = authKaydet(newUser);\neğer (authResult.success) {\n    yaz(\"OK \" + authResult.message + \" (ID: \" + authResult.userId + \")\");\n    bildirimGonder(\n        newUser.email,\n        \"Hos Geldiniz!\",\n        \"Aramiza hos geldiniz, \" + newUser.name\n    );\n}\n\nyaz(\"\\n2. URUN OLUSTURMA\");\nyaz(\"-----------------------------------------------------------\\n\");\n\n// Urun olustur\ndeğişken product = productOlustur(\"MacBook Pro M3\", 45000, 10, \"Elektronik\");\nyaz(\"Urun olusturuldu: \" + productBilgi(product));\n\n// Fiyat dogrula\neğer (fiyatGecerli(product.price)) {\n    yaz(\"OK Fiyat gecerli: \" + paraBirimi(product.price, \"TRY\"));\n}\n\n// Stok kontrolu\neğer (productStokta(product)) {\n    yaz(\"OK Urun stokta mevcut\");\n} değilse {\n    yaz(\"HATA Urun stokta yok\");\n}\n\nyaz(\"\\n3. SIPARIS OLUSTURMA\");\nyaz(\"-----------------------------------------------------------\\n\");\n\n// Siparis olustur\ndeğişken order = orderOlustur(\n    newUser.id,\n    product.id,\n    1,\n    product.price\n);\nyaz(\"Siparis olusturuldu: \" + orderBilgi(order));\n\nyaz(\"\\n4. ODEME ISLEMI\");\nyaz(\"-----------------------------------------------------------\\n\");\n\n// Odeme isle\ndeğişken paymentResult = odemeIsle(\n    order.id,\n    order.totalPrice,\n    \"credit_card\"\n);\n\neğer (paymentResult.success) {\n    yaz(\"OK \" + paymentResult.message);\n    yaz(\"  Islem No: \" + paymentResult.transactionId);\n    yaz(\"  Tutar: \" + paraBirimi(paymentResult.amount, \"TRY\"));\n    yaz(\"  Yontem: \" + paymentResult.method);\n\n    bildirimGonder(\n        newUser.email,\n        \"Siparisıniz Onaylandi\",\n        \"Siparis numaraniz: \" + order.id + \" - Toplam: \" + paraBirimi(order.totalPrice, \"TRY\")\n    );\n} değilse {\n    yaz(\"HATA Odeme basarisiz: \" + paymentResult.error);\n}\n\nyaz(\"\\n============================================================\");\nyaz(\"OK E-Ticaret sistemi demo tamamlandi!\");\nyaz(\"OK Moduler, olceklenebilir ve bakimi kolay mimari\");\nyaz(\"============================================================\");\n", "module_concepts": "// Türkçe - Modules & Code Organization\n// Demonstrates module system: kullan/içe_aktar like Rust, Java, C++, Python\n\n// Import math module\n\"math.hudhud\" kullan;\n\n// Example syntax variations:\n// \"math.hudhud\" kullan;\n// \"math.hudhud\" den { add, subtract } kullan;\n// \"math.hudhud\" math olarak kullan;\n\n// Using functions şuradan math module\ndeğişken sum = add(10, 5);\nyaz(sum);\n\ndeğişken diff = subtract(20, 8);\nyaz(diff);\n\ndeğişken product = multiply(4, 7);\nyaz(product);\n\ndeğişken quotient = divide(15, 3);\nyaz(quotient);\n\ndeğişken squared = square(5);\nyaz(squared);\n\ndeğişken cubed = cube(3);\nyaz(cubed);\n\ndeğişken absolute = abs(-42);\nyaz(absolute);\n\ndeğişken maximum = max(100, 50);\nyaz(maximum);\n\ndeğişken minimum = min(100, 50);\nyaz(minimum);\n\n// Complex calculation using multiple functions\ndeğişken result = add(multiply(5, 3), divide(20, 4));\nyaz(result);\n", "higher_order_functions": "// Turkce - Yuksek Dereceli Fonksiyonlar\n// Diger fonksiyonlarla calisan fonksiyonlar\n\n// Fonksiyon donduren fonksiyon\nislev carpan(faktör) {\n    dön (x) => x * faktör;\n}\n\ntanim ikiye = carpan(2);\ntanim üçe = carpan(3);\n\nyazdir(ikiye(5));  // 10\nyazdir(üçe(5));  // 15\n\n// Fonksiyon alan fonksiyon\nislev uygula(fn, değer) {\n    dön fn(değer);\n}\n\nyazdir(uygula(ikiye, 10));  // 20\n\n// Bilesim ornegi\nislev birleştir(f, g) {\n    dön (x) => f(g(x));\n}\n\ntanim birEkle = (x) => x + 1;\ntanim ikiyleÇarp = (x) => x * 2;\n\ntanim ekleSonraÇarp = birleştir(ikiyleÇarp, birEkle);\nyazdir(ekleSonraÇarp(5));  // 12 (5+1=6, 6*2=12)\n", "cebir": "// Türkçe - Math Module\n\nişlev topla(a, b) {\n    dön a + b;\n}\n\nişlev cikar(a, b) {\n    dön a - b;\n}\n\nişlev carp(a, b) {\n    dön a * b;\n}\n\nişlev bol(a, b) {\n    eğer (b == 0) {\n        yaz(\"Error: Division by zero!\");\n        dön 0;\n    } değilse {\n        dön a / b;\n    }\n}\n\nişlev kare(x) {\n    dön x * x;\n}\n\nişlev kup(x) {\n    dön x * x * x;\n}\n\nişlev mutlak(x) {\n    eğer (x < 0) {\n        dön -x;\n    } değilse {\n        dön x;\n    }\n}\n\nişlev maksimum(a, b) {\n    eğer (a > b) {\n        dön a;\n    } değilse {\n        dön b;\n    }\n}\n\nişlev minimum(a, b) {\n    eğer (a < b) {\n        dön a;\n    } değilse {\n        dön b;\n    }\n}\n", "classes_oop": "// Türkçe - Sınıflar ve Nesne Yönelimli Programlama (OOP)\n// HudHudScript'te sınıf tabanlı programlama\n\n// ============================================\n// 1. Temel Sınıf Tanımlama\n// ============================================\n\n// Erişim belirleyicileri: açık (public), gizli (private), saklı (protected)\nsınıf Hayvan {\n    açık değişken isim = \"Bilinmiyor\";\n    açık değişken tür = \"Bilinmiyor\";\n    açık değişken yaş = 0;\n    açık değişken canlı = doğru;\n    gizli değişken kimlik = \"H-001\";\n}\n\nyaz(\"=== Temel Sınıf ===\");\nyaz(\"Sınıf tanımlandı: Hayvan\");\n\n// ============================================\n// 2. Kalıtım (Inheritance) — <- operatörü\n// ============================================\n\n// Araç temel sınıfı\nsınıf Araç {\n    açık değişken marka = \"Bilinmiyor\";\n    açık değişken model = \"Bilinmiyor\";\n    açık değişken yıl = 2024;\n    gizli değişken motor_no = \"MOTOR-0000\";\n    saklı değişken üretim_maliyeti = 50000;\n}\n\n// Araba <- Araç (Araba, Araç'tan türetilmiş)\nsınıf Araba <- Araç {\n    açık değişken renk = \"beyaz\";\n    açık değişken kapı_sayısı = 4;\n    gizli değişken kilometre = 0;\n}\n\n// Sedan <- Araba <- Araç (çok seviyeli kalıtım)\nsınıf Sedan <- Araba {\n    açık değişken bagaj_hacmi = 500;\n    açık değişken tip = \"sedan\";\n}\n\n// SUV <- Araba <- Araç\nsınıf SUV <- Araba {\n    açık değişken dört_çeker = doğru;\n    açık değişken yükseklik = 180;\n    açık değişken arazi_modu = \"kapalı\";\n}\n\nyaz(\"\\n=== Kalıtım Hiyerarşisi ===\");\nyaz(\"Araç → Araba → Sedan\");\nyaz(\"Araç → Araba → SUV\");\n\n// ============================================\n// 3. Statik Alanlar (Static Fields)\n// ============================================\n\nsınıf ArabaFabrikası {\n    statik açık değişken toplam_üretim = 0;\n    statik gizli değişken fabrika_kodu = \"FAB-2024\";\n    statik açık değişken kuruluş_yılı = 2020;\n    statik açık değişken konum = \"İstanbul\";\n}\n\nyaz(\"\\n=== Statik Alanlar ===\");\nyaz(\"Fabrika: \" + ArabaFabrikası.konum);\nyaz(\"Kuruluş: \" + ArabaFabrikası.kuruluş_yılı);\n\n// ============================================\n// 4. Erişim Belirleyicileri (Access Modifiers)\n// ============================================\n\nsınıf BankaHesabı {\n    açık değişken hesap_sahibi = \"Ayşe Yılmaz\";\n    açık değişken hesap_türü = \"Vadesiz\";\n    saklı değişken bakiye = 10000;\n    gizli değişken şifre = \"gizli123\";\n    gizli değişken güvenlik_kodu = \"XYZ\";\n    açık değişken para_birimi = \"TL\";\n}\n\nyaz(\"\\n=== Erişim Belirleyicileri ===\");\nyaz(\"açık (public)  → Herkese açık: hesap_sahibi, hesap_türü\");\nyaz(\"saklı (protected) → Sadece sınıf ve alt sınıflar: bakiye\");\nyaz(\"gizli (private)  → Sadece sınıf içi: şifre, güvenlik_kodu\");\n\n// ============================================\n// 5. Sınıf Hiyerarşisi — Canlı Varlıklar\n// ============================================\n\nsınıf CanlıVarlık {\n    açık değişken isim = \"Bilinmiyor\";\n    açık değişken yaş = 0;\n    saklı değişken enerji = 100;\n    gizli değişken dna = \"ACGT\";\n}\n\nsınıf Memeli <- CanlıVarlık {\n    açık değişken kan_sıcaklığı = \"sıcak\";\n    açık değişken tüy = doğru;\n}\n\nsınıf Kuş <- CanlıVarlık {\n    açık değişken kanat_açıklığı = 0;\n    açık değişken uçabilir = doğru;\n}\n\nsınıf Kedi <- Memeli {\n    açık değişken cins = \"Tekir\";\n    açık değişken iç_mekan = doğru;\n    açık değişken renk = \"turuncu\";\n}\n\nsınıf Köpek <- Memeli {\n    açık değişken cins = \"Golden\";\n    açık değişken eğitimli = yanlış;\n    açık değişken boyut = \"büyük\";\n}\n\nsınıf Papağan <- Kuş {\n    açık değişken konuşabilir = doğru;\n    açık değişken renk = \"yeşil\";\n    açık değişken kelime_sayısı = 50;\n}\n\nyaz(\"\\n=== Canlı Varlık Hiyerarşisi ===\");\nyaz(\"CanlıVarlık\");\nyaz(\"  ├── Memeli\");\nyaz(\"  │   ├── Kedi (cins: \" + Kedi.cins + \", renk: \" + Kedi.renk + \")\");\nyaz(\"  │   └── Köpek (cins: \" + Köpek.cins + \", boyut: \" + Köpek.boyut + \")\");\nyaz(\"  └── Kuş\");\nyaz(\"      └── Papağan (konuşabilir: \" + Papağan.konuşabilir + \", kelime: \" + Papağan.kelime_sayısı + \")\");\n\n// ============================================\n// 6. İş Dünyası Sınıfları\n// ============================================\n\nsınıf Şirket {\n    açık değişken isim = \"HudHud Teknoloji\";\n    açık değişken sektör = \"Yazılım\";\n    açık değişken kuruluş = 2023;\n    açık değişken çalışan_sayısı = 45;\n    gizli değişken vergi_no = \"TR-12345678\";\n}\n\nsınıf Departman {\n    açık değişken isim = \"Mühendislik\";\n    açık değişken yönetici = \"Mehmet Kaya\";\n    açık değişken kişi_sayısı = 12;\n    açık değişken bütçe = 500000;\n}\n\nsınıf Çalışan {\n    açık değişken isim = \"Elif Demir\";\n    açık değişken unvan = \"Kıdemli Geliştirici\";\n    açık değişken departman = \"Mühendislik\";\n    saklı değişken maaş = 35000;\n    gizli değişken tc_no = \"12345678901\";\n}\n\nyaz(\"\\n=== İş Dünyası ===\");\nyaz(Şirket.isim + \" - \" + Şirket.sektör);\nyaz(\"Departman: \" + Departman.isim + \" (\" + Departman.kişi_sayısı + \" kişi)\");\nyaz(\"Çalışan: \" + Çalışan.isim + \" - \" + Çalışan.unvan);\n", "switch_concepts": "// Türkçe - Seç/Durum Kavramları\n// if-else ile çoklu durum kontrolü\n\nişlev gün_tipi(day) {\n    eğer (day == \"Monday\") {\n        dön \"Hafta içi\";\n    } değilse {\n        eğer (day == \"Tuesday\") {\n            dön \"Hafta içi\";\n        } değilse {\n            eğer (day == \"Wednesday\") {\n                dön \"Hafta içi\";\n            } değilse {\n                eğer (day == \"Thursday\") {\n                    dön \"Hafta içi\";\n                } değilse {\n                    eğer (day == \"Friday\") {\n                        dön \"Hafta içi\";\n                    } değilse {\n                        eğer (day == \"Saturday\") {\n                            dön \"Hafta sonu\";\n                        } değilse {\n                            eğer (day == \"Sunday\") {\n                                dön \"Hafta sonu\";\n                            } değilse {\n                                dön \"Bilinmeyen\";\n                            }\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n\nyazdır(\"=== Gün Tipleri ===\");\nyazdır(\"Monday: \" + gün_tipi(\"Monday\"));\nyazdır(\"Saturday: \" + gün_tipi(\"Saturday\"));\nyazdır(\"Holiday: \" + gün_tipi(\"Holiday\"));\n\nişlev not_harfi(score) {\n    eğer (score == 90) {\n        dön \"A\";\n    } değilse {\n        eğer (score == 80) {\n            dön \"B\";\n        } değilse {\n            eğer (score == 70) {\n                dön \"C\";\n            } değilse {\n                eğer (score == 60) {\n                    dön \"D\";\n                } değilse {\n                    dön \"F\";\n                }\n            }\n        }\n    }\n}\n\nyazdır(\"=== Not Harfleri ===\");\nyazdır(\"90: \" + not_harfi(90));\nyazdır(\"70: \" + not_harfi(70));\nyazdır(\"50: \" + not_harfi(50));\n\nişlev durum_mesajı(code) {\n    eğer (code == 200) {\n        dön \"OK\";\n    } değilse {\n        eğer (code == 404) {\n            dön \"Not Found\";\n        } değilse {\n            eğer (code == 500) {\n                dön \"Server Error\";\n            } değilse {\n                dön \"Bilinmeyen Status\";\n            }\n        }\n    }\n}\n\nyazdır(\"=== HTTP Durum Kodları ===\");\nyazdır(\"200: \" + durum_mesajı(200));\nyazdır(\"404: \" + durum_mesajı(404));\n", "event_concepts": "// Türkçe - Event Concepts\n\nolay UserLogin {\n    yazdır(\"User logged in\");\n}\n\nolay DataReceived {\n    yazdır(\"Data received\");\n}\n\nolay ErrorOccurred {\n    yazdır(\"Error occurred\");\n}\n\nişlev on_login(username) {\n    yazdır(\"Login: \" + username);\n    dön \"Welcome, \" + username;\n}\n\nişlev on_data(source) {\n    yazdır(\"Data from: \" + source);\n    dön \"Processed: \" + source;\n}\n\nişlev on_error(message) {\n    yazdır(\"Error: \" + message);\n    dön \"Handled: \" + message;\n}\n\nyazdır(\"=== Event System ===\");\ndeğişken r1 = on_login(\"admin\");\nyazdır(r1);\ndeğişken r2 = on_data(\"sensor_1\");\nyazdır(r2);\ndeğişken r3 = on_error(\"timeout\");\nyazdır(r3);\n", "functions": "// Türkçe - Fonksiyonlar\n// Fonksiyon tanımlama ve kullanma örnekleri\n\n// Basit fonksiyon\nişlev selamla() {\n    yaz(\"Merhaba Dünya!\");\n}\n\n// Parametreli fonksiyon\nişlev topla(a, b) {\n    dön a + b;\n}\n\n// Çoklu parametreli fonksiyon\nişlev hesapla(sayı1, sayı2, işlem) {\n    eğer (işlem == \"topla\") {\n        dön sayı1 + sayı2;\n    } değilse ama (işlem == \"çıkar\") {\n        dön sayı1 - sayı2;\n    } değilse ama (işlem == \"çarp\") {\n        dön sayı1 * sayı2;\n    } değilse ama (işlem == \"böl\") {\n        dön sayı1 / sayı2;\n    } hiçbiri değilse {\n        dön 0;\n    }\n}\n\n// Matematiksel fonksiyonlar\nişlev kare(x) {\n    dön x * x;\n}\n\nişlev küp(x) {\n    dön x * x * x;\n}\n\n// Fonksiyonları kullanma\nselamla();\n\ndeğişken sonuç1 = topla(5, 3);\nyaz(sonuç1);\n\ndeğişken sonuç2 = hesapla(10, 5, \"topla\");\nyaz(sonuç2);\n\ndeğişken sonuç3 = hesapla(10, 5, \"çarp\");\nyaz(sonuç3);\n\ndeğişken kare_sonuç = kare(4);\nyaz(kare_sonuç);\n\ndeğişken küp_sonuç = küp(3);\nyaz(küp_sonuç);\n\n// Fonksiyon ile hesaplama\ndeğişken toplam = topla(kare(3), küp(2));\nyaz(toplam);\n", "entity_concepts": "// Türkçe - Varlık Kavramları\n\ndeğişken kullanıcı = {\n    kimlik: 1,\n    isim: \"Ayşe\",\n    eposta: \"ayse@ornek.com\",\n    rol: \"geliştirici\"\n};\n\ndeğişken ürün = {\n    kimlik: 101,\n    isim: \"HudHudScript IDE\",\n    sürüm: \"2.0\",\n    fiyat: 49\n};\n\ndeğişken sipariş = {\n    kimlik: 1001,\n    kullanıcı_kimlik: 1,\n    ürün_kimlik: 101,\n    miktar: 2,\n    durum: \"onaylandı\"\n};\n\nişlev varlık_bilgisi(varlık) {\n    dön \"Varlık #\" + varlık.kimlik + \": \" + varlık.isim;\n}\n\nişlev toplam_hesapla(sipariş, fiyat) {\n    dön sipariş.miktar * fiyat;\n}\n\nyazdır(\"=== Varlık Sistemi ===\");\nyazdır(varlık_bilgisi(kullanıcı));\nyazdır(varlık_bilgisi(ürün));\ndeğişken toplam = toplam_hesapla(sipariş, ürün.fiyat);\nyazdır(\"Sipariş #\" + sipariş.kimlik + \" toplam: \" + toplam);\nyazdır(\"Durum: \" + sipariş.durum);\n", "error_concepts": "// Türkçe - Error Concepts\n// Basit doğrulama işlevleri\n\nişlev validate_age(age) {\n    eğer (age < 0) {\n        dön { geçerli: yanlış, hata: \"Geçersiz yaş: negatif\" };\n    }\n    eğer (age > 150) {\n        dön { geçerli: yanlış, hata: \"Geçersiz yaş: çok büyük\" };\n    }\n    dön { geçerli: doğru, yaş: age };\n}\n\nişlev validate_email(email) {\n    eğer (email == \"\") {\n        dön { geçerli: yanlış, hata: \"Boş email\" };\n    }\n    dön { geçerli: doğru, email: email };\n}\n\nyazdır(\"=== Doğrulama ===\");\n\n// Yaş doğrulama\ndeğişken yaş_sonuç1 = validate_age(25);\neğer (yaş_sonuç1.geçerli) {\n    yazdır(\"Yaş 25 geçerli\");\n} değilse {\n    yazdır(\"Hata: \" + yaş_sonuç1.hata);\n}\n\ndeğişken yaş_sonuç2 = validate_age(-5);\neğer (yaş_sonuç2.geçerli) {\n    yazdır(\"Yaş geçerli\");\n} değilse {\n    yazdır(\"Hata: \" + yaş_sonuç2.hata);\n}\n\n// Email doğrulama\ndeğişken email_sonuç1 = validate_email(\"user@example.com\");\neğer (email_sonuç1.geçerli) {\n    yazdır(\"Email geçerli: \" + email_sonuç1.email);\n} değilse {\n    yazdır(\"Email hatası: \" + email_sonuç1.hata);\n}\n\ndeğişken email_sonuç2 = validate_email(\"\");\neğer (email_sonuç2.geçerli) {\n    yazdır(\"Email geçerli\");\n} değilse {\n    yazdır(\"Email hatası: \" + email_sonuç2.hata);\n}\n\nyazdır(\"Doğrulama tamamlandı\");\n", "subject_oriented": "// Türkçe - Özne Yönelimli Programlama\n// HudHudScript'e özgü paradigma: varlıkları özne olarak modelleme\n\n// ============================================\n// 1. Temel Özne Tanımlama\n// ============================================\n\nözne Kullanıcı {\n    isim: \"Ayşe Yılmaz\",\n    eposta: \"ayse@ornek.com\",\n    rol: \"geliştirici\",\n    aktif: doğru,\n    kayıt_tarihi: \"2024-01-15\"\n}\n\nözne Yönetici {\n    isim: \"Mehmet Kaya\",\n    eposta: \"mehmet@ornek.com\",\n    rol: \"yönetici\",\n    aktif: doğru,\n    departman: \"mühendislik\",\n    takım_büyüklüğü: 8\n}\n\nyaz(\"=== Temel Özneler ===\");\nyaz(Kullanıcı.isim + \" (\" + Kullanıcı.rol + \")\");\nyaz(Yönetici.isim + \" - \" + Yönetici.departman + \" departmanı\");\n\n// ============================================\n// 2. İş Alanı Modelleme\n// ============================================\n\nözne Ürün {\n    kimlik: 1001,\n    isim: \"HudHudScript IDE Pro\",\n    sürüm: \"3.0\",\n    fiyat: 299,\n    kategori: \"yazılım\",\n    stok: 500,\n    aktif: doğru\n}\n\nözne Sipariş {\n    kimlik: 5001,\n    müşteri: \"Ayşe Yılmaz\",\n    ürün_adı: \"HudHudScript IDE Pro\",\n    adet: 2,\n    birim_fiyat: 299,\n    durum: \"onaylandı\",\n    tarih: \"2024-03-20\"\n}\n\nişlev sipariş_tutarı(sipariş) {\n    dön sipariş.adet * sipariş.birim_fiyat;\n}\n\nyaz(\"\\n=== İş Alanı Modelleme ===\");\nyaz(\"Ürün: \" + Ürün.isim + \" v\" + Ürün.sürüm + \" - \" + Ürün.fiyat + \" TL\");\nyaz(\"Stok: \" + Ürün.stok + \" adet\");\ndeğişken tutar = sipariş_tutarı(Sipariş);\nyaz(\"Sipariş #\" + Sipariş.kimlik + \": \" + Sipariş.adet + \" adet = \" + tutar + \" TL\");\nyaz(\"Durum: \" + Sipariş.durum);\n\n// ============================================\n// 3. Özne Etkileşimleri\n// ============================================\n\nözne Öğrenci {\n    isim: \"Elif Demir\",\n    numara: 2024001,\n    bölüm: \"Bilgisayar Mühendisliği\",\n    sınıf: 3,\n    not_ortalaması: 3.45\n}\n\nözne Öğretim_Üyesi {\n    isim: \"Prof. Dr. Ali Vural\",\n    unvan: \"Profesör\",\n    bölüm: \"Bilgisayar Mühendisliği\",\n    ders_sayısı: 4\n}\n\nözne Ders {\n    kod: \"BM301\",\n    isim: \"Veri Yapıları\",\n    kredi: 4,\n    kontenjan: 60,\n    kayıtlı: 45,\n    öğretim_üyesi: \"Prof. Dr. Ali Vural\"\n}\n\nişlev doluluk_oranı(ders) {\n    dön (ders.kayıtlı * 100) / ders.kontenjan;\n}\n\nişlev onur_öğrencisi_mi(öğrenci) {\n    eğer (öğrenci.not_ortalaması >= 3.5) {\n        dön \"Evet - Onur Öğrencisi\";\n    } hiçbiri değilse {\n        dön \"Hayır\";\n    }\n}\n\nyaz(\"\\n=== Özne Etkileşimleri ===\");\nyaz(Öğrenci.isim + \" - \" + Öğrenci.bölüm);\nyaz(\"Not Ortalaması: \" + Öğrenci.not_ortalaması + \" - Onur: \" + onur_öğrencisi_mi(Öğrenci));\nyaz(Ders.kod + \" \" + Ders.isim + \" (\" + Ders.kredi + \" kredi)\");\nyaz(\"Doluluk: \" + doluluk_oranı(Ders) + \"%\");\nyaz(\"Veren: \" + Ders.öğretim_üyesi);\n\n// ============================================\n// 4. Durum Makinesi (State Pattern)\n// ============================================\n\nözne Görev {\n    başlık: \"API Geliştirme\",\n    açıklama: \"REST API endpoint tasarımı\",\n    sorumlu: \"Ayşe Yılmaz\",\n    öncelik: \"yüksek\",\n    durum: \"devam_ediyor\",\n    tahmini_süre: 5,\n    geçen_süre: 3\n}\n\nişlev görev_durumu(görev) {\n    değişken kalan = görev.tahmini_süre - görev.geçen_süre;\n    değişken yüzde = (görev.geçen_süre * 100) / görev.tahmini_süre;\n\n    yaz(\"Görev: \" + görev.başlık);\n    yaz(\"Sorumlu: \" + görev.sorumlu);\n    yaz(\"Durum: \" + görev.durum + \" (\" + yüzde + \"% tamamlandı)\");\n    yaz(\"Kalan süre: \" + kalan + \" gün\");\n    dön yüzde;\n}\n\nişlev görev_ilerlet(görev) {\n    eğer (görev.durum == \"bekliyor\") {\n        dön \"devam_ediyor\";\n    } değilse ama (görev.durum == \"devam_ediyor\") {\n        dön \"inceleme\";\n    } değilse ama (görev.durum == \"inceleme\") {\n        dön \"tamamlandı\";\n    } hiçbiri değilse {\n        dön görev.durum;\n    }\n}\n\nyaz(\"\\n=== Durum Makinesi ===\");\ngörev_durumu(Görev);\ndeğişken sonraki = görev_ilerlet(Görev);\nyaz(\"Sonraki durum: \" + sonraki);\n\n// ============================================\n// 5. Fabrika ile Özne Dizileri\n// ============================================\n\nişlev ÇalışanOluştur(isim, departman, maaş) {\n    dön {\n        isim: isim,\n        departman: departman,\n        maaş: maaş,\n        aktif: doğru\n    };\n}\n\ndeğişken takım = [\n    ÇalışanOluştur(\"Elif Arslan\", \"Backend\", 35000),\n    ÇalışanOluştur(\"Can Özkan\", \"Frontend\", 32000),\n    ÇalışanOluştur(\"Seda Yıldız\", \"DevOps\", 38000),\n    ÇalışanOluştur(\"Burak Şahin\", \"Mobil\", 34000)\n];\n\nişlev departman_raporu(takım) {\n    yaz(\"Takım Raporu:\");\n    yaz(\"─────────────────────────\");\n    değişken toplam_maaş = 0;\n    değişken idx = 0;\n    iken (idx < 4) {\n        değişken çalışan = takım[idx];\n        yaz(çalışan.isim + \" | \" + çalışan.departman + \" | \" + çalışan.maaş + \" TL\");\n        toplam_maaş = toplam_maaş + çalışan.maaş;\n        idx = idx + 1;\n    }\n    yaz(\"─────────────────────────\");\n    yaz(\"Toplam maaş gideri: \" + toplam_maaş + \" TL\");\n    yaz(\"Ortalama maaş: \" + (toplam_maaş / 4) + \" TL\");\n}\n\nyaz(\"\\n=== Takım Yönetimi ===\");\ndepartman_raporu(takım);\n", "conditionals_advanced": "// Türkçe - Gelişmiş Koşullar (Advanced Conditionals)\n\n// Basit koşul\ndeğişken sayı = -5;\n\neğer (sayı < 0) {\n    yaz(\"Sayı negatif\");\n}\n\n// Eğer-değilse\ndeğişken yaş = 18;\n\neğer (yaş >= 18) {\n    yaz(\"Yetişkin\");\n} değilse {\n    yaz(\"Çocuk\");\n}\n\n// Çoklu koşullar (değilse eğer)\ndeğişken puan = 75;\n\neğer (puan >= 90) {\n    yaz(\"Mükemmel\");\n} değilse ama (puan >= 70) {\n    yaz(\"İyi\");\n} değilse ama (puan >= 50) {\n    yaz(\"Orta\");\n} değilse {\n    yaz(\"Yetersiz\");\n}\n\n// İç içe koşullar\ndeğişken sıcaklık = 25;\ndeğişken yağmurlu = yanlış;\n\neğer (sıcaklık > 20) {\n    eğer (yağmurlu) {\n        yaz(\"Sıcak ama yağmurlu\");\n    } değilse {\n        yaz(\"Güzel hava\");\n    }\n} değilse {\n    yaz(\"Soğuk hava\");\n}\n"}, "vi": {"objects": "// Tiếng Việt - Đối tượng\n// Đối tượng với từ khóa tiếng Việt\n\n// Tạo đối tượng\nđặt người = {\n    tên: \"An\",\n    tuổi: 30,\n    thành_phố: \"Hà Nội\"\n};\n\n// Truy cập thuộc tính\nđặt tên = người.tên;\nđặt tuổi = người.tuổi;\n\n// Kết quả\ntên;\n", "chemistry": "// VI - Chemistry Module\n\nhàm molarMass(atoms, atomicWeight) {\n    trả_về atoms * atomicWeight;\n}\n\nhàm concentration(moles, volume) {\n    trả_về moles / volume;\n}\n\nhàm pH(hydrogenConcentration) {\n    trả_về 14 - hydrogenConcentration;\n}\n\nhàm density(mass, volume) {\n    trả_về mass / volume;\n}\n\nhàm dilution(c1, v1, v2) {\n    trả_về (c1 * v1) / v2;\n}\n", "loops": "// Tiếng Việt - Ví dụ vòng lặp\nđặt bộ_đếm = 0;\nđặt tối_đa = 5;\n\ntrong khi (bộ_đếm < tối_đa) {\n    in_ra(bộ_đếm);\n    bộ_đếm = bộ_đếm + 1;\n}\n\nin_ra(999);\n", "data_processing": "// Tiếng Việt - Data Processing\n// Using NATIVE Tiếng Việt keywords\n\ncho data1 = 100;\ncho data2 = 200;\ncho data3 = 300;\n\ncho total = value1+ value2+ value3;\ncho average = total / 3;\n\nin_ra(total);\nin_ra(average);\n", "modules_import": "// VI - Modules Import Example\n\n// Import math module (direct access)\nsử_dụng \"math.hudhud\";\n\n// Import physics with alias (access via fizik.functionName)\nsử_dụng \"physics.hudhud\" như fizik;\n\n// Import chemistry (direct access)\nsử_dụng \"chemistry.hudhud\";\n\n// Using math functions (direct)\ncho sum = add(10, 5);\nin_ra(sum);\n\ncho product = multiply(4, 7);\nin_ra(product);\n\n// Using physics functions (via alias: fizik.functionName)\ncho f = fizik.force(10, 9.8);\nin_ra(f);\n\ncho ke = fizik.kineticEnergy(5, 10);\nin_ra(ke);\n\n// Using chemistry functions (direct)\ncho d = density(100, 50);\nin_ra(d);\n\ncho c = concentration(2, 5);\nin_ra(c);\n", "return_concept": "// Tiếng Việt - Khái niệm Trả về\n// return\n\nhàm bình_phương(x) {\n    trả về x * x;\n}\n\nhàm lập_phương(x) {\n    trả về x * x * x;\n}\n\nprint(\"=== Math Functions ===\");\nprint(\"bình_phương(5): \" + bình_phương(5));\nprint(\"lập_phương(3): \" + lập_phương(3));\n\nhàm tuyệt_đối(x) {\n    nếu (x < 0) {\n        trả về -x;\n    }\n    trả về x;\n}\n\nprint(\"\\n=== Absolute ===\");\nprint(\"tuyệt_đối(-7): \" + tuyệt_đối(-7));\nprint(\"tuyệt_đối(3): \" + tuyệt_đối(3));\n\nhàm tạo_điểm(x, y) {\n    trả về { x: x, y: y };\n}\n\nđặt p = tạo_điểm(10, 20);\nprint(\"\\n=== Point ===\");\nprint(\"Point: (\" + p.x + \", \" + p.y + \")\");\n\nhàm factorial(n) {\n    nếu (n <= 1) {\n        trả về 1;\n    }\n    trả về n * factorial(n - 1);\n}\n\nprint(\"\\n=== Factorial ===\");\nprint(\"5! = \" + factorial(5));\nprint(\"10! = \" + factorial(10));\n", "customer_service": "// Tiếng Việt - Nhân viên dịch vụ khách hàng\n// Sử dụng từ khóa tiếng Việt\n\nđặt lời_chào = \"Xin chào, tôi có thể giúp gì cho bạn?\";\nđặt phản_hồi = \"Tôi sẽ hỗ trợ yêu cầu của bạn.\";\n\nin_ra(lời_chào);\nin_ra(phản_hồi);\n", "basic_example": "// Tiếng Việt - Basic Example with NATIVE keywords\nbiến a = 10;\nbiến b = 20;\nbiến tổng = a + b;\n\nin_ra(tổng);\n", "physics": "// VI - Physics Module\n\nhàm speed(distance, time) {\n    trả_về distance / time;\n}\n\nhàm force(mass, acceleration) {\n    trả_về mass * acceleration;\n}\n\nhàm kineticEnergy(mass, velocity) {\n    trả_về 0.5 * mass * velocity * velocity;\n}\n\nhàm potentialEnergy(mass, gravity, height) {\n    trả_về mass * gravity * height;\n}\n\nhàm momentum(mass, velocity) {\n    trả_về mass * velocity;\n}\n", "error_handling": "// vi - Error Handling\n// Simple error control with if-else\n\nfunction divide(a, b) {\n    if (b == 0) {\n        return { error: true, message: \"Division by zero\", value: 0 };\n    }\n    return { error: false, message: \"\", value: a / b };\n}\n\nprint(\"=== Error Handling ===\");\n\nvar result1 = divide(10, 2);\nif (result1.error) {\n    print(\"Error: \" + result1.message);\n} else {\n    print(\"10 / 2 = \" + result1.value);\n}\n\nvar result2 = divide(10, 0);\nif (result2.error) {\n    print(\"Error caught: \" + result2.message);\n} else {\n    print(\"Result: \" + result2.value);\n}\n\nprint(\"Done\");\n", "package_usage": "// Package Kullanımı - HudHudScript Paket Sistemi\n// Paket yönetim sistemi: oluşturma, kurma, yayınlama ve kullanma\n\n// ============================================================\n// 1. PAKET KULLANIMI (Using Packages)\n// ============================================================\n\n// Harici gói kullanımı\nsử_dụng \"cebir\";\nsử_dụng \"fizik\";\n\n// Paket içinden belirli modülleri içe aktarma\nsử_dụng \"cebir/matris\";\nsử_dụng \"cebir/vektor\";\nsử_dụng \"fizik/hareket\";\n\nviết(\"============================================================\");\nviết(\"HudHudScript Paket Sistemi Demo\");\nviết(\"============================================================\\n\");\n\n// ============================================================\n// 2. PAKET FONKSİYONLARINI KULLANMA\n// ============================================================\n\nviết(\"📦 Cebir Paketi Kullanımı:\");\nviết(\"─────────────────────────────────────────────────────────\\n\");\n\n// Matris oluşturma\nbiến matris1 = Matris([\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]);\n\nbiến matris2 = Matris([\n    [9, 8, 7],\n    [6, 5, 4],\n    [3, 2, 1]\n]);\n\nviết(\"Matris 1:\");\nmatris1.goster();\n\nviết(\"\\nMatris 2:\");\nmatris2.goster();\n\n// Matris toplama\nbiến toplam = matris1.topla(matris2);\nviết(\"\\nMatris Toplama:\");\ntoplam.goster();\n\n// Vektör işlemleri\nbiến vektor1 = Vektor([1, 2, 3]);\nbiến vektor2 = Vektor([4, 5, 6]);\n\nviết(\"\\n\\n📐 Vektör İşlemleri:\");\nviết(\"─────────────────────────────────────────────────────────\\n\");\n\nviết(\"Vektör 1: \" + vektor1.toString());\nviết(\"Vektör 2: \" + vektor2.toString());\n\nbiến noktaSal = vektor1.noktaSal(vektor2);\nviết(\"Nokta Çarpım: \" + noktaSal);\n\nbiến caprazCarpim = vektor1.caprazCarpim(vektor2);\nviết(\"Çapraz Çarpım: \" + caprazCarpim.toString());\n\n// ============================================================\n// 3. FİZİK PAKETİ KULLANIMI\n// ============================================================\n\nviết(\"\\n\\n⚡ Fizik Paketi Kullanımı:\");\nviết(\"─────────────────────────────────────────────────────────\\n\");\n\n// Hareket hesaplamaları\nbiến baslangicHizi = 0;      // m/s\nbiến ivme = 9.8;              // m/s² (yerçekimi)\nbiến zaman = 5;               // saniye\n\nbiến sonHiz = Hareket.hizHesapla(baslangicHizi, ivme, zaman);\nbiến mesafe = Hareket.mesafeHesapla(baslangicHizi, ivme, zaman);\n\nviết(\"Başlangıç Hızı: \" + baslangicHizi + \" m/s\");\nviết(\"İvme: \" + ivme + \" m/s²\");\nviết(\"Zaman: \" + zaman + \" s\");\nviết(\"─────────────────────────────────────────────────────────\");\nviết(\"Son Hız: \" + sonHiz + \" m/s\");\nviết(\"Alınan Mesafe: \" + mesafe + \" m\");\n\n// ============================================================\n// 4. PAKET OLUŞTURMA (Package Creation)\n// ============================================================\n\nviết(\"\\n\\n📝 Paket Oluşturma:\");\nviết(\"─────────────────────────────────────────────────────────\\n\");\n\nviết(\"1. hudhud.toml dosyası oluşturun:\");\nviết(\"   [package]\");\nviết(\"   name = 'matematik-utils'\");\nviết(\"   version = '1.0.0'\");\nviết(\"   description = 'Matematik yardımcı fonksiyonları'\");\n\nviết(\"\\n2. Bağımlılıklar ekleyin:\");\nviết(\"   [dependencies]\");\nviết(\"   cebir = '^2.0.0'\");\nviết(\"   fizik = '^1.5.0'\");\n\n// ============================================================\n// 5. PAKET YÖNETİMİ KOMUTLARI\n// ============================================================\n\nviết(\"\\n\\n🔧 Paket Yönetimi Komutları:\");\nviết(\"─────────────────────────────────────────────────────────\\n\");\n\nviết(\"Paket kurma:\");\nviết(\"  hudhudscript install cebir\");\nviết(\"  hudhudscript install fizik@1.5.0\");\n\nviết(\"\\nPaket güncelleme:\");\nviết(\"  hudhudscript update cebir\");\nviết(\"  hudhudscript update --all\");\n\nviết(\"\\nPaket kaldırma:\");\nviết(\"  hudhudscript remove cebir\");\n\nviết(\"\\nKurulu paketleri listeleme:\");\nviết(\"  hudhudscript list\");\n\nviết(\"\\nPaket arama:\");\nviết(\"  hudhudscript search matematik\");\n\nviết(\"\\nPaket bilgisi:\");\nviết(\"  hudhudscript info cebir\");\n\n// ============================================================\n// 6. PAKET BAĞIMLILIKLARI\n// ============================================================\n\nviết(\"\\n\\n🔗 Paket Bağımlılıkları:\");\nviết(\"─────────────────────────────────────────────────────────\\n\");\n\nviết(\"Versiyon belirtme:\");\nviết(\"  'cebir' = '^2.0.0'    # 2.x.x\");\nviết(\"  'fizik' = '~1.5.0'    # 1.5.x\");\nviết(\"  'kimya' = '1.2.3'     # Tam versiyon\");\n\nviết(\"\\nGit deposundan:\");\nviết(\"  'my-lib' = { git = 'https://github.com/user/my-lib' }\");\n\nviết(\"\\nYerel yoldan:\");\nviết(\"  'local-lib' = { path = '../local-lib' }\");\n\n// ============================================================\n// 7. PAKET GÜVENLİĞİ\n// ============================================================\n\nviết(\"\\n\\n🔒 Paket Güvenliği:\");\nviết(\"─────────────────────────────────────────────────────────\\n\");\n\nviết(\"Güvenlik kontrolü:\");\nviết(\"  hudhudscript audit\");\n\nviết(\"\\nChecksum doğrulama:\");\nviết(\"  hudhudscript verify cebir\");\n\nviết(\"\\n============================================================\");\nviết(\"✓ Paket sistemi demo tamamlandı!\");\nviết(\"✓ HudHudScript ile modüler ve yeniden kullanılabilir kod yazın\");\nviết(\"============================================================\");\n", "arrays": "// Tiếng Việt - Mảng\n// Mảng với từ khóa tiếng Việt\n\n// Tạo mảng\nđặt số = [1, 2, 3, 4, 5];\nđặt tên = [\"An\", \"Bình\", \"Chi\"];\n\n// Truy cập phần tử\nđặt đầu_tiên = số[0];\nđặt thứ_hai = số[1];\n\n// Kết quả\nđầu_tiên;\n", "math": "// VI - Math Module\n\nfunction add(a, b) {\n    trả_về a + b;\n}\n\nfunction subtract(a, b) {\n    trả_về a - b;\n}\n\nfunction multiply(a, b) {\n    trả_về a * b;\n}\n\nfunction divide(a, b) {\n    nếu (b == 0) {\n        in_ra(\"Error: Division by zero!\");\n        trả_về 0;\n    } nếu_không {\n        trả_về a / b;\n    }\n}\n\nfunction square(x) {\n    trả_về x * x;\n}\n\nfunction cube(x) {\n    trả_về x * x * x;\n}\n\nfunction abs(x) {\n    nếu (x < 0) {\n        trả_về -x;\n    } nếu_không {\n        trả_về x;\n    }\n}\n\nfunction max(a, b) {\n    nếu (a > b) {\n        trả_về a;\n    } nếu_không {\n        trả_về b;\n    }\n}\n\nfunction min(a, b) {\n    nếu (a < b) {\n        trả_về a;\n    } nếu_không {\n        trả_về b;\n    }\n}\n", "control_flow": "// Tiếng Việt - Luồng Điều Khiển\nbiến bộ_đếm = 0;\nbiến tối_đa = 5;\n\n// Loop\ntrong_khi (bộ_đếm < tối_đa) {\n    bộ_đếm = bộ_đếm + 1;\n}\n\n// Conditional\nbiến điểm = 85;\n\nnếu (điểm >= 90) {\n    điểm;\n} nếu_không {\n    nếu (điểm >= 80) {\n        điểm;\n    } nếu_không {\n        điểm;\n    }\n}\n\nbộ_đếm;", "state_machine": "// State Machine Example\ncho state = \"initial\";\n\nnếu (state == \"initial\") {\n    in_ra(\"Starting\");\n    state = \"running\";\n}\n\nin_ra(state);\n", "conditionals": "// Tiếng Việt - Logic điều kiện\nđặt điểm = 85;\n\nnếu (điểm >= 90) {\n    in_ra(1000);\n} không thì {\n    nếu (điểm >= 80) {\n        in_ra(2000);\n    } không thì {\n        in_ra(3000);\n    }\n}\n\nin_ra(999);\n", "code_organization": "// Tiếng Việt - Code Organization by Topic\n// Organizing code into logical folders\n\n// Project Structure:\n// \n// project/\n//   ├── agent/\n//   │   ├── agent_definition.hudhud\n//   │   ├── agent_tasks.hudhud\n//   │   ├── agent_tools.hudhud\n//   │   └── agent_providers.hudhud\n//   │\n//   ├── constitution/\n//   │   ├── constitution.hudhud\n//   │   ├── laws.hudhud\n//   │   ├── rules.hudhud\n//   │   ├── ruleset.hudhud\n//   │   └── rulechain.hudhud\n//   │\n//   ├── data/\n//   │   ├── note.hudhud\n//   │   ├── chord.hudhud\n//   │   ├── melody.hudhud\n//   │   ├── harmony.hudhud\n//   │   └── rhythm.hudhud\n//   │\n//   ├── governance/\n//   │   ├── council.hudhud\n//   │   ├── swarm.hudhud\n//   │   ├── community.hudhud\n//   │   └── enforcement.hudhud\n//   │\n//   ├── flow/\n//   │   ├── dataflow.hudhud\n//   │   ├── layer.hudhud\n//   │   ├── network.hudhud\n//   │   └── orchestration.hudhud\n//   │\n//   ├── state/\n//   │   ├── entity.hudhud\n//   │   ├── state_machine.hudhud\n//   │   ├── event.hudhud\n//   │   └── intent.hudhud\n//   │\n//   └── utils/\n//       ├── math.hudhud\n//       ├── physics.hudhud\n//       ├── chemistry.hudhud\n//       └── helpers.hudhud\n\n// Benefits of this organization:\n// 1. Clear separation of concerns\n// 2. Easy to find related code\n// 3. Scalable cho_mỗi large projects\n// 4. Team collaboration friendly\n// 5. Modular and maintainable\n\n// Example imports:\n// sử_dụng \"agent/agent_definition.hudhud\";\n// sử_dụng \"constitution/laws.hudhud\";\n// sử_dụng \"data/note.hudhud\";\n// sử_dụng \"utils/math.hudhud\";\n", "module_concepts": "// Tiếng Việt - Modules & Code Organization\n// Demonstrates module system: sử_dụng/nhập like Rust, Java, C++, Python\n\n// Import math module\nsử_dụng \"math.hudhud\";\n\n// Example syntax variations:\n// sử_dụng \"math.hudhud\";\n// sử_dụng { add, subtract } từ \"math.hudhud\";\n// sử_dụng \"math.hudhud\" như math;\n\n// Using functions từ math module\ncho sum = add(10, 5);\nin_ra(sum);\n\ncho diff = subtract(20, 8);\nin_ra(diff);\n\ncho product = multiply(4, 7);\nin_ra(product);\n\ncho quotient = divide(15, 3);\nin_ra(quotient);\n\ncho squared = square(5);\nin_ra(squared);\n\ncho cubed = cube(3);\nin_ra(cubed);\n\ncho absolute = abs(-42);\nin_ra(absolute);\n\ncho maximum = max(100, 50);\nin_ra(maximum);\n\ncho minimum = min(100, 50);\nin_ra(minimum);\n\n// Complex calculation using multiple functions\ncho result = add(multiply(5, 3), divide(20, 4));\nin_ra(result);\n", "switch_concepts": "// vi - Switch Concepts\n// Using if-else for multiple conditions\n\nfunction dayType(day) {\n    if (day == \"Monday\") { return \"Weekday\"; }\n    if (day == \"Tuesday\") { return \"Weekday\"; }\n    if (day == \"Wednesday\") { return \"Weekday\"; }\n    if (day == \"Thursday\") { return \"Weekday\"; }\n    if (day == \"Friday\") { return \"Weekday\"; }\n    if (day == \"Saturday\") { return \"Weekend\"; }\n    if (day == \"Sunday\") { return \"Weekend\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== Day Types ===\");\nprint(\"Monday: \" + dayType(\"Monday\"));\nprint(\"Saturday: \" + dayType(\"Saturday\"));\nprint(\"Holiday: \" + dayType(\"Holiday\"));\n\nfunction statusMessage(code) {\n    if (code == 200) { return \"OK\"; }\n    if (code == 404) { return \"Not Found\"; }\n    if (code == 500) { return \"Server Error\"; }\n    return \"Unknown\";\n}\n\nprint(\"=== HTTP Status ===\");\nprint(\"200: \" + statusMessage(200));\nprint(\"404: \" + statusMessage(404));\n", "event_concepts": "// Tiếng Việt - Event Concepts\n\nsự kiện UserLogin {\n    in_ra(\"User logged in\");\n}\n\nsự kiện DataReceived {\n    in_ra(\"Data received\");\n}\n\nsự kiện ErrorOccurred {\n    in_ra(\"Error occurred\");\n}\n\nhàm on_login(username) {\n    in_ra(\"Login: \" + username);\n    trả về \"Welcome, \" + username;\n}\n\nhàm on_data(source) {\n    in_ra(\"Data from: \" + source);\n    trả về \"Processed: \" + source;\n}\n\nhàm on_error(message) {\n    in_ra(\"Error: \" + message);\n    trả về \"Handled: \" + message;\n}\n\nin_ra(\"=== Event System ===\");\nđặt r1 = on_login(\"admin\");\nin_ra(r1);\nđặt r2 = on_data(\"sensor_1\");\nin_ra(r2);\nđặt r3 = on_error(\"timeout\");\nin_ra(r3);\n", "functions": "// Tiếng Việt - Hàm\n// Ví dụ định nghĩa và sử dụng hàm\n\n// Hàm đơn giản\nhàm chào_hỏi() {\n    in_ra(\"Xin chào Thế giới!\");\n}\n\n// Hàm có tham số\nhàm cộng(a, b) {\n    trả về a + b;\n}\n\n// Hàm nhiều tham số\nhàm tính(số1, số2, phép_tính) {\n    nếu (phép_tính == \"cộng\") {\n        trả về số1 + số2;\n    } không thì {\n        trả về 0;\n    }\n}\n\n// Hàm toán học\nhàm bình_phương(x) {\n    trả về x * x;\n}\n\nhàm lập_phương(x) {\n    trả về x * x * x;\n}\n\n// Sử dụng hàm\nchào_hỏi();\n\nđặt kết_quả1 = cộng(5, 3);\nin_ra(kết_quả1);\n\nđặt kết_quả2 = tính(10, 5, \"cộng\");\nin_ra(kết_quả2);\n\nđặt kết_quả_bình_phương = bình_phương(4);\nin_ra(kết_quả_bình_phương);\n\nđặt kết_quả_lập_phương = lập_phương(3);\nin_ra(kết_quả_lập_phương);\n\n// Kết hợp hàm\nđặt tổng = cộng(bình_phương(3), lập_phương(2));\nin_ra(tổng);\n", "entity_concepts": "// Tiếng Việt - Khái niệm thực thể\n\nđặt người_dùng = {\n    mã: 1,\n    tên: \"An\",\n    email: \"an@vidu.com\",\n    vai_trò: \"lập trình viên\"\n};\n\nđặt sản_phẩm = {\n    mã: 101,\n    tên: \"HudHudScript IDE\",\n    phiên_bản: \"2.0\",\n    giá: 49\n};\n\nđặt đơn_hàng = {\n    mã: 1001,\n    mã_người_dùng: 1,\n    mã_sản_phẩm: 101,\n    số_lượng: 2,\n    trạng_thái: \"đã xác nhận\"\n};\n\nhàm thông_tin_thực_thể(thực_thể) {\n    trả về \"Thực thể #\" + thực_thể.mã + \": \" + thực_thể.tên;\n}\n\nhàm tính_tổng(đơn_hàng, giá) {\n    trả về đơn_hàng.số_lượng * giá;\n}\n\nin_ra(\"=== Hệ thống thực thể ===\");\nin_ra(thông_tin_thực_thể(người_dùng));\nin_ra(thông_tin_thực_thể(sản_phẩm));\nđặt tổng = tính_tổng(đơn_hàng, sản_phẩm.giá);\nin_ra(\"Đơn hàng #\" + đơn_hàng.mã + \" tổng: \" + tổng);\nin_ra(\"Trạng thái: \" + đơn_hàng.trạng_thái);\n", "error_concepts": "// vi - Error Concepts\n// Simple validation functions\n\nfunction validateAge(age) {\n    if (age < 0) {\n        return { valid: false, error: \"Invalid age: negative\" };\n    }\n    if (age > 150) {\n        return { valid: false, error: \"Invalid age: too large\" };\n    }\n    return { valid: true, age: age };\n}\n\nfunction validateEmail(email) {\n    if (email == \"\") {\n        return { valid: false, error: \"Empty email\" };\n    }\n    return { valid: true, email: email };\n}\n\nprint(\"=== Validation ===\");\n\nvar ageResult1 = validateAge(25);\nif (ageResult1.valid) {\n    print(\"Age 25 is valid\");\n} else {\n    print(\"Error: \" + ageResult1.error);\n}\n\nvar ageResult2 = validateAge(-5);\nif (ageResult2.valid) {\n    print(\"Age is valid\");\n} else {\n    print(\"Error: \" + ageResult2.error);\n}\n\nvar emailResult = validateEmail(\"user@example.com\");\nif (emailResult.valid) {\n    print(\"Email valid: \" + emailResult.email);\n} else {\n    print(\"Email error: \" + emailResult.error);\n}\n\nprint(\"Validation complete\");\n"}};
